#!/usr/bin/env node

process.argv.splice(2, 0, "pack");
await import("../dist/bin.js");

import { createHash } from "node:crypto";
import { join, resolve } from "node:path";

import {
  detectFrameworks,
  detectLanguages,
  detectSourceRoots,
  extractDependencies,
  parseGoManifest,
  parseJavaManifest,
  parsePackageJson,
  parsePythonManifest,
} from "@fuzit/analysis";
import { loadEffectiveConfig, type EffectiveConfig } from "@fuzit/config";
import {
  createFileContextItem,
  normalizeRepositoryRelativePath,
  normalizeRepositoryIntelligence,
  securityFilter,
  type RepositoryIntelligence,
  type SecurityFilteredItem,
} from "@fuzit/core";
import { collectGitIdentity, collectGitStatus } from "@fuzit/git";
import {
  classifyFile,
  evaluateIgnorePrecedence,
  loadFuzitignoreRulesForPath,
  loadGitignoreRulesForPath,
  readTextContent,
  traverseDirectory,
  type ExplicitPathRule,
} from "@fuzit/scanner";

export interface RepositoryAcquisition {
  readonly root: string;
  readonly config: EffectiveConfig;
  readonly configHash: string;
  readonly items: readonly SecurityFilteredItem[];
  readonly omissions: readonly {
    path: string;
    reason: string;
    failure: boolean;
  }[];
  readonly complete: boolean;
}

function stableHash(value: unknown): string {
  return createHash("sha256")
    .update(JSON.stringify(value), "utf8")
    .digest("hex");
}

function projectRules(config: EffectiveConfig): ExplicitPathRule[] {
  return [
    ...config.values.exclude.map((pattern) => ({
      pattern,
      action: "exclude" as const,
      reason: "excluded by fuzit.config.json",
    })),
    ...config.values.include.map((pattern) => ({
      pattern,
      action: "include" as const,
      reason: "included by fuzit.config.json",
    })),
  ];
}

export async function acquireRepository(
  repositoryRoot: string,
  environment: Readonly<Record<string, string | undefined>> = {},
  overrides?: { maxFiles?: number },
): Promise<RepositoryAcquisition> {
  const root = resolve(repositoryRoot);
  const config = await loadEffectiveConfig({
    repositoryRoot: root,
    environment,
    cli: overrides?.maxFiles !== undefined ? { maxFiles: overrides.maxFiles } : {},
  });
  const items: SecurityFilteredItem[] = [];
  const omissions: { path: string; reason: string; failure: boolean }[] = [];
  try {
    for await (const entry of traverseDirectory(root, {
      projectRules: projectRules(config),
      onExcluded: ({ path, reason }) => {
        omissions.push({ path, reason, failure: false });
      },
    })) {
      if (entry.kind !== "file") continue;
      const absolutePath = join(root, ...entry.path.split("/"));
      let record;
      try {
        record = await classifyFile(absolutePath, entry.path);
      } catch {
        omissions.push({
          path: entry.path,
          reason: "classification-failed",
          failure: true,
        });
        continue;
      }
      if (record.kind !== "text" || !record.readable) {
        omissions.push({
          path: entry.path,
          reason: record.kind === "binary" ? "binary" : "not-readable-text",
          failure: false,
        });
        continue;
      }
      let acquired: Awaited<ReturnType<typeof readTextContent>> | undefined;
      const result = await securityFilter({
        path: entry.path,
        readContent: async () => {
          acquired = await readTextContent(absolutePath);
          if (acquired.content === null) throw new Error("content unavailable");
          return acquired.content;
        },
        createItem: (content) =>
          createFileContextItem(record, {
            status: acquired?.status ?? "omitted",
            content,
            sha256: acquired?.sha256 ?? "0".repeat(64),
          }),
      });
      if (result.status === "success") items.push(result.item);
      else
        omissions.push({
          path: result.path,
          reason: result.reason,
          failure: result.status === "partial",
        });
    }
  } catch (error) {
    omissions.push({
      path: ".",
      reason: error instanceof Error ? error.message : "traversal-failed",
      failure: true,
    });
  }
  items.sort((left, right) => left.path.localeCompare(right.path, "en"));
  omissions.sort((left, right) => left.path.localeCompare(right.path, "en"));
  return {
    root,
    config,
    configHash: stableHash(config.values),
    items,
    omissions,
    complete: !omissions.some(({ failure }) => failure),
  };
}

export function analyzeRepository(
  acquisition: RepositoryAcquisition,
): RepositoryIntelligence {
  const languages = detectLanguages(
    acquisition.items.map((item) => ({
      path: item.path,
      ...(item.content === null
        ? {}
        : { contentPrefix: item.content.slice(0, 256) }),
      generated: item.lifecycle === "generated",
      vendored: item.lifecycle === "vendored",
    })),
  ).map((fact) => fact.value);
  const packages: string[] = [];
  const frameworks: string[] = [];
  const tests: string[] = [];
  const entryPoints = detectSourceRoots(
    acquisition.items.map((item) => item.path),
  );
  const dependencies: string[] = [];
  const conflicts: string[] = [];
  let partial = !acquisition.complete;

  for (const item of acquisition.items) {
    const content = item.content ?? "";
    if (item.path.endsWith("package.json")) {
      const manifest = parsePackageJson(item.path, content);
      packages.push(`${manifest.name}:${manifest.path}`);
      dependencies.push(...manifest.dependencies);
      const detected = detectFrameworks({
        packageName: manifest.name,
        dependencies: manifest.dependencies,
        scripts: manifest.scripts,
      });
      frameworks.push(...detected.frameworks);
      tests.push(...detected.tests);
      entryPoints.push(
        ...detected.entryPoints.map((value) => `${item.path}:${value}`),
      );
      conflicts.push(...detected.conflicts);
      if (manifest.workspacePatterns.length > 0)
        packages.push(
          ...manifest.workspacePatterns.map(
            (pattern) => `workspace:${pattern}`,
          ),
        );
      partial ||= manifest.diagnostics.length > 0;
    } else if (item.path === "pnpm-workspace.yaml") {
      packages.push(
        ...[...content.matchAll(/^\s*-\s*["']?([^"'#\r\n]+)["']?\s*$/gm)].map(
          (match) => `workspace:${match[1]!.trim()}`,
        ),
      );
    } else if (/requirements(?:-[^/]*)?\.txt$/.test(item.path)) {
      const manifest = parsePythonManifest(content);
      packages.push(`python:${item.path}`);
      dependencies.push(...manifest.dependencies);
      if (manifest.dependencies.includes("pytest")) tests.push("pytest");
    } else if (item.path.endsWith("pom.xml")) {
      const manifest = parseJavaManifest(content);
      packages.push(`java:${item.path}`);
      dependencies.push(...manifest.dependencies);
      partial ||= manifest.dynamic;
    } else if (item.path.endsWith("go.mod") || item.path.endsWith("go.work")) {
      const manifest = parseGoManifest(content, item.path);
      packages.push(`go:${manifest.module ?? item.path}`);
      dependencies.push(...manifest.dependencies);
      dependencies.push(...manifest.replacements.map(({ from }) => from));
      const detected = detectFrameworks({
        packageName: manifest.module ?? item.path,
        dependencies: manifest.dependencies,
        scripts: {},
      });
      frameworks.push(...detected.frameworks);
      tests.push(...detected.tests);
      conflicts.push(...detected.conflicts);
      partial ||= manifest.diagnostics.length > 0;
    }
    dependencies.push(
      ...extractDependencies(item.path, content)
        .filter((edge) => edge.kind === "external" || edge.kind === "workspace")
        .map((edge) => edge.specifier),
    );
    if (
      /(^|\/)(?:test|tests|__tests__)(\/|$)|\.(?:test|spec)\./.test(item.path)
    )
      tests.push(item.path);
  }

  return normalizeRepositoryIntelligence({
    languages,
    packages,
    frameworks,
    tests,
    entryPoints,
    dependencies,
    conflicts,
    partial,
  });
}

export async function repositoryIdentity(root: string): Promise<{
  readonly revision: string | null;
  readonly dirty: boolean;
  readonly fingerprint: string;
}> {
  const git = await collectGitIdentity(root);
  const remote = git.remotes.find(({ name }) => name === "origin")?.url;
  return {
    revision: git.head,
    dirty: git.dirty,
    fingerprint:
      git.available && remote !== undefined
        ? `git:${remote}`
        : `path:${resolve(root).replaceAll("\\", "/")}`,
  };
}

export async function repositorySnapshotIdentity(
  acquisition: RepositoryAcquisition,
): Promise<{
  readonly revision: string | null;
  readonly dirty: boolean;
}> {
  const identity = await collectGitIdentity(acquisition.root);
  if (!identity.available) return { revision: null, dirty: false };
  const included = new Set(acquisition.items.map(({ path }) => path));
  const changes = await collectGitStatus(acquisition.root);
  for (const change of changes) {
    if (included.has(change.path))
      return { revision: identity.head, dirty: true };
    if (change.kind !== "deleted" && change.kind !== "renamed") continue;
    const path = change.originalPath ?? change.path;
    const canonical = normalizeRepositoryRelativePath(path);
    const decision = evaluateIgnorePrecedence({
      path: canonical,
      isDirectory: false,
      projectRules: projectRules(acquisition.config),
      fuzitignoreRules: await loadFuzitignoreRulesForPath(acquisition.root),
      gitignoreRules: await loadGitignoreRulesForPath(
        acquisition.root,
        canonical,
      ),
    });
    if (!decision.excluded) return { revision: identity.head, dirty: true };
  }
  return { revision: identity.head, dirty: false };
}

export function acquisitionContentHash(
  acquisition: RepositoryAcquisition,
): string {
  return stableHash(
    acquisition.items.map(({ path, sha256 }) => ({ path, sha256 })),
  );
}

#!/usr/bin/env node

import { runCliProcess } from "./index.js";

process.exitCode = await runCliProcess(process.argv.slice(2));

import { readFileSync } from "node:fs";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import { Command, CommanderError, Option } from "commander";

import { registerConfigCommand } from "./config/register.js";
import { registerDoctorCommand } from "./commands/doctor/register.js";
import { registerInitCommand } from "./commands/init/register.js";
import { registerScanCommand } from "./commands/scan/register.js";
import { executeDualPack, registerPackCommand } from "./commands/pack/register.js";
import { registerGitCommand } from "./commands/git/register.js";
import { registerCacheCommand } from "./commands/cache/register.js";
import { registerSnapshotCommand } from "./commands/snapshot/register.js";
import { registerDiffCommand } from "./commands/diff/register.js";
import { registerProfileCommand } from "./commands/profile/register.js";
import { registerContextCommand } from "./commands/context/register.js";
import { registerExplainCommand } from "./commands/explain/register.js";
import { registerWatchCommand } from "./commands/watch/register.js";
import { registerGraphCommand } from "./commands/graph/register.js";
import { registerAuthCommand } from "./commands/auth/register.js";
import {
  registerReviewCommand,
  registerPrCommand,
} from "./commands/review/register.js";
import { registerIssueCommand } from "./commands/issue/register.js";
import { registerPluginCommand } from "./commands/plugin/register.js";
import { registerSupportCommand } from "./commands/support/register.js";
import { registerServeCommand } from "./commands/serve/register.js";
import { registerApplyCommand } from "./commands/apply/register.js";
import { registerUiCommand } from "./commands/ui/register.js";
import { routeSourceInput } from "@fuzit/core";
import { createOutputRouter, type OutputIo } from "./output/router.js";

const packageMetadata = JSON.parse(
  readFileSync(new URL("../package.json", import.meta.url), "utf8"),
) as { version?: unknown };

if (typeof packageMetadata.version !== "string") {
  throw new Error("CLI package version is missing");
}

export const CLI_VERSION = packageMetadata.version;
export const CLI_USAGE_ERROR_EXIT_CODE = EXIT_CODES.validation;

function createProgram(io: OutputIo): Command {
  return new Command()
    .name("fuzit")
    .description("Private, local-first AI context-engineering CLI.")
    .version(CLI_VERSION)
    .addOption(
      new Option("--json", "emit machine-readable JSON output").default(false),
    )
    .addOption(
      new Option("--quiet", "suppress nonessential output")
        .default(false)
        .conflicts("debug"),
    )
    .addOption(
      new Option("--debug", "enable debug diagnostics")
        .default(false)
        .conflicts("quiet"),
    )
    .allowExcessArguments(true)
    .showSuggestionAfterError(false)
    .showHelpAfterError(false)
    .exitOverride()
    .configureOutput({
      writeOut: io.writeOut,
      writeErr: io.writeErr,
      outputError: () => {},
    })
    .addHelpText(
      "after",
      `\nUnknown commands exit with status ${EXIT_CODES.validation}.`,
    );
}

function cliDiagnostic(
  code: "CLI.INTERNAL" | "CLI.INVALID_ARGUMENT" | "CLI.UNKNOWN_COMMAND",
  message: string,
): Diagnostic {
  return {
    schemaVersion: 1,
    code,
    severity: "error",
    source: "cli",
    message,
  };
}

export async function runCli(
  arguments_: readonly string[],
  io: OutputIo,
  runtime: {
    readonly repositoryRoot?: string;
    readonly environment?: Readonly<Record<string, string | undefined>>;
  } = {},
): Promise<ExitCode> {
  const jsonRequested = arguments_.includes("--json");
  const output = createOutputRouter(io, {
    debug: arguments_.includes("--debug"),
    json: jsonRequested,
    quiet: arguments_.includes("--quiet"),
  });
  const operation = [
    "scan",
    "pack",
    "context",
    "cache",
    "snapshot",
    "watch",
    "graph",
    "review",
    "pr",
    "issue",
    "plugin",
  ].find((name) => arguments_.includes(name));
  const activityStarted =
    operation !== undefined &&
    !arguments_.includes("--help") &&
    !arguments_.includes("-h");
  const startedAt = performance.now();
  if (activityStarted) {
    const labels: Record<string, string> = {
      scan: "Scanning repository",
      pack: "Packing repository",
      context: "Building task context",
      cache: "Updating local index",
      snapshot: "Processing snapshot",
      watch: "Starting repository watch",
      graph: "Building repository graph",
      review: "Fetching and reviewing pull request",
      auth: "Managing GitHub authentication",
      pr: "Fetching and reviewing pull request",
      issue: "Fetching issue context",
      plugin: "Inspecting plugins",
    };
    if (operation === "graph") {
      const graphIndex = arguments_.indexOf("graph");
      const graphOperation = arguments_[graphIndex + 1];
      labels.graph =
        graphOperation === "build"
          ? "Building repository graph"
          : graphOperation === "stats"
            ? "Reading graph statistics"
            : graphOperation === "neighbors"
              ? "Finding graph neighbors"
              : graphOperation === "impact"
                ? "Analyzing graph impact"
                : graphOperation === "query"
                  ? "Querying repository graph"
                  : "Processing repository graph";
    }
    output.writeActivity(
      `Fuzit v${CLI_VERSION} · ${labels[operation!] ?? "Working"}...`,
    );
  }

  if (arguments_.includes("--quiet") && arguments_.includes("--debug")) {
    output.writeDiagnostic(
      cliDiagnostic(
        "CLI.INVALID_ARGUMENT",
        "option '--quiet' cannot be used with option '--debug'",
      ),
    );
    return EXIT_CODES.validation;
  }

  const program = createProgram(io);
  let commandExitCode: ExitCode = EXIT_CODES.success;

  registerConfigCommand(program, {
    repositoryRoot: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerDoctorCommand(program, {
    workingDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    json: jsonRequested,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerInitCommand(program, {
    repositoryRoot: runtime.repositoryRoot ?? process.cwd(),
    json: jsonRequested,
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerScanCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerPackCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerGitCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerCacheCommand(program, {
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
  });
  registerSnapshotCommand(program, {
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
  });
  registerDiffCommand(program, {
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
  });
  registerProfileCommand(program, output.writeData);
  registerContextCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerExplainCommand(program, {
    json: jsonRequested,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerWatchCommand(program, {
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerAuthCommand(program, {
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (code) => {
      commandExitCode = code;
    },
  });
  registerGraphCommand(program, {
    repositoryRoot: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    json: jsonRequested,
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerReviewCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerPrCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerIssueCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerPluginCommand(program, {
    workingDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    json: jsonRequested,
    writeData: output.writeData,
    writeDiagnostic: output.writeDiagnostic,
    setExitCode: (exitCode) => {
      commandExitCode = exitCode;
    },
  });
  registerSupportCommand(program, CLI_VERSION, output.writeData);
  registerServeCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (code) => {
      commandExitCode = code;
    },
  });
  registerApplyCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (code) => {
      commandExitCode = code;
    },
  });
  registerUiCommand(program, {
    currentDirectory: runtime.repositoryRoot ?? process.cwd(),
    environment: runtime.environment ?? process.env,
    writeData: output.writeData,
    setExitCode: (code) => {
      commandExitCode = code;
    },
  });

  // Top-level URL dispatch handling (e.g. `fuzit https://github.com/...`)
  const firstArg = arguments_[0];
  if (
    firstArg &&
    (firstArg.startsWith("http://") || firstArg.startsWith("https://"))
  ) {
    const route = routeSourceInput(firstArg);
    if (route.target === "review") {
      arguments_ = ["review", ...arguments_];
    } else if (route.target === "issue") {
      arguments_ = ["issue", ...arguments_];
    } else if (route.target === "context") {
      arguments_ = ["context", "--root", firstArg, ...arguments_.slice(1)];
    }
  }

  const positionalArgs = arguments_.filter((arg) => !arg.startsWith("-"));
  const helpOrVersion = arguments_.some((arg) =>
    ["--help", "-h", "--version", "-V", "help"].includes(arg),
  );

  if (positionalArgs.length === 0 && !helpOrVersion) {
    try {
      const root = runtime.repositoryRoot ?? process.cwd();
      const dualResult = await executeDualPack(
        root,
        runtime.environment ?? process.env,
      );
      output.writeData(dualResult);
      return EXIT_CODES.success;
    } catch (error) {
      output.writeDiagnostic(
        cliDiagnostic(
          "CLI.INTERNAL",
          error instanceof Error ? error.message : String(error),
        ),
        error,
      );
      return EXIT_CODES.internal;
    }
  }

  try {
    await program.parseAsync([...arguments_], { from: "user" });
  } catch (error) {
    if (error instanceof CommanderError) {
      if (error.exitCode === 0) {
        return EXIT_CODES.success;
      }

      if (error.code === "commander.unknownCommand") {
        output.writeDiagnostic(
          cliDiagnostic(
            "CLI.UNKNOWN_COMMAND",
            error.message.replace(/^error: /, ""),
          ),
        );
        return EXIT_CODES.validation;
      }

      output.writeDiagnostic(
        cliDiagnostic("CLI.INVALID_ARGUMENT", error.message),
      );
      return EXIT_CODES.validation;
    }

    const message =
      error instanceof Error ? error.message : "Unknown internal error.";
    output.writeDiagnostic(cliDiagnostic("CLI.INTERNAL", message), error);
    return EXIT_CODES.internal;
  }

  const unknownCommand = program.args[0];
  const recognizedCommand = program.commands.some(
    (command) => command.name() === unknownCommand,
  );
  if (unknownCommand && !recognizedCommand) {
    const message = `unknown command '${unknownCommand}'`;

    output.writeDiagnostic(cliDiagnostic("CLI.UNKNOWN_COMMAND", message));

    return CLI_USAGE_ERROR_EXIT_CODE;
  }

  if (activityStarted && commandExitCode === EXIT_CODES.success) {
    output.writeActivity(
      `Fuzit v${CLI_VERSION} · ${operation} complete (${((performance.now() - startedAt) / 1_000).toFixed(2)}s)`,
    );
  }
  return commandExitCode;
}

import { open, readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { mkdir } from "node:fs/promises";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface ApplyDependencies {
  readonly currentDirectory: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (code: ExitCode) => void;
}

export function parseAiCodeBlocks(input: string): Array<{ path: string; content: string }> {
  const blocks: Array<{ path: string; content: string }> = [];

  // Match patterns like ```typescript:src/app.ts or ```js path=src/app.js or ## src/app.ts\n```...```
  const fileHeaderRegex = /^(?:#{2,3}\s+|File:\s*|Path:\s*)([a-zA-Z0-9_.\-\/\\]+\.[a-zA-Z0-9]+)\s*\n```[a-zA-Z]*\n([\s\S]*?)```/gm;
  let match: RegExpExecArray | null;
  while ((match = fileHeaderRegex.exec(input)) !== null) {
    if (match[1] && match[2]) {
      blocks.push({ path: match[1].trim(), content: match[2] });
    }
  }

  if (blocks.length > 0) return blocks;

  // Match inline block headers like ```ts:src/app.ts\ncontent\n```
  const inlineBlockRegex = /```[a-zA-Z]*:([a-zA-Z0-9_.\-\/\\]+\.[a-zA-Z0-9]+)\n([\s\S]*?)```/gm;
  while ((match = inlineBlockRegex.exec(input)) !== null) {
    if (match[1] && match[2]) {
      blocks.push({ path: match[1].trim(), content: match[2] });
    }
  }

  return blocks;
}

export function registerApplyCommand(
  program: Command,
  dependencies: ApplyDependencies,
): void {
  program
    .command("apply [patchFile]")
    .description("Apply AI-generated code diffs or code blocks safely to working tree")
    .option("--root <path>", "Repository root", ".")
    .action(async (patchFile: string | undefined, options: { root: string }) => {
      try {
        let content = "";
        if (patchFile && patchFile !== "-") {
          content = await readFile(resolve(dependencies.currentDirectory, patchFile), "utf8");
        } else {
          const chunks: Buffer[] = [];
          for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
          content = Buffer.concat(chunks).toString("utf8");
        }

        const blocks = parseAiCodeBlocks(content);
        if (blocks.length === 0) {
          dependencies.writeData({
            kind: "apply",
            status: "warning",
            message: "No structured AI code blocks with target file paths detected.",
          });
          dependencies.setExitCode(EXIT_CODES.validation);
          return;
        }

        const applied: string[] = [];
        const root = resolve(dependencies.currentDirectory, options.root);

        for (const block of blocks) {
          const targetPath = resolve(root, block.path);
          await mkdir(dirname(targetPath), { recursive: true });
          const handle = await open(targetPath, "w");
          try {
            await handle.writeFile(block.content, "utf8");
            applied.push(block.path);
          } finally {
            await handle.close();
          }
        }

        dependencies.writeData({
          kind: "apply",
          status: "success",
          applied,
          count: applied.length,
        });
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        dependencies.writeData({
          kind: "apply",
          status: "error",
          error: error instanceof Error ? error.message : String(error),
        });
        dependencies.setExitCode(EXIT_CODES.internal);
      }
    });
}

import { spawnSync } from "node:child_process";
import {
  githubRequest,
  resolveBestGitHubCredential,
} from "@fuzit/provider-github";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface AuthCommandDependencies {
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (code: ExitCode) => void;
}

function ghAvailable(): boolean {
  return (
    spawnSync("gh", ["--version"], { encoding: "utf8", shell: false })
      .status === 0
  );
}

function ghLogin(host: string): { ok: boolean; message?: string } {
  const result = spawnSync(
    "gh",
    ["auth", "login", "--hostname", host, "--web"],
    { encoding: "utf8", shell: false, stdio: "pipe" },
  );
  if (result.status !== 0) {
    return {
      ok: false,
      message:
        result.stderr.trim() ||
        result.stdout.trim() ||
        "GitHub CLI login failed.",
    };
  }
  return { ok: true };
}

async function authStatus(
  environment: Readonly<Record<string, string | undefined>>,
) {
  const credential = await resolveBestGitHubCredential({
    host: "github.com",
    env: environment,
  });
  if (!credential.isAuthenticated) {
    return {
      kind: "auth",
      status: "Not authenticated",
      host: "github.com",
      source: "anonymous",
      nextStep:
        "Run `fuzit auth github` or set `GH_TOKEN` / `FUZIT_GITHUB_TOKEN`.",
    };
  }
  const response = await githubRequest("https://api.github.com/user", {
    credential,
    allowedHosts: ["github.com", "api.github.com"],
  });
  if (!response.ok) {
    return {
      kind: "auth",
      status: "Authenticated",
      host: "github.com",
      source: credential.source,
      error:
        response.kind === "rate-limited"
          ? "GitHub rate limited the account lookup."
          : "GitHub credential could not be verified.",
      nextStep: "Re-run `fuzit auth github` or refresh the credential.",
    };
  }
  if (response.status !== 200) {
    return {
      kind: "auth",
      status: "Authenticated",
      host: "github.com",
      source: credential.source,
      error:
        "GitHub credential could not be verified.",
      nextStep: "Re-run `fuzit auth github` or refresh the credential.",
    };
  }
  let login = "unknown";
  try {
    const data = JSON.parse(response.body) as { login?: string };
    if (typeof data.login === "string") login = data.login;
  } catch {
    // ignore; human output still succeeds
  }
  return {
    kind: "auth",
    status: "Authenticated",
    host: "github.com",
    account: login,
    source: credential.source,
    permission: "Pull requests: read",
    nextStep: "Ready for private pull-request review.",
  };
}

export function registerAuthCommand(
  program: Command,
  dependencies: AuthCommandDependencies,
): void {
  const auth = program
    .command("auth")
    .description("manage GitHub authentication");

  auth
    .command("github")
    .description("authenticate the GitHub CLI session for Fuzit")
    .action(async () => {
      if (!ghAvailable()) {
        dependencies.writeData({
          kind: "auth",
          error: "GitHub CLI (`gh`) is not installed.",
          nextStep: "Install `gh` or set `GH_TOKEN` / `FUZIT_GITHUB_TOKEN`.",
        });
        dependencies.setExitCode(EXIT_CODES.environment);
        return;
      }
      const existing = await authStatus(dependencies.environment);
      if (existing.status === "Authenticated") {
        dependencies.writeData({
          ...existing,
          status: "Already authenticated",
          nextStep: "✓ Ready for private pull-request review.",
        });
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }
      const login = ghLogin("github.com");
      if (!login.ok) {
        dependencies.writeData({
          kind: "auth",
          error: login.message ?? "GitHub CLI login failed.",
          nextStep: "Use `gh auth login --hostname github.com --web` directly.",
        });
        dependencies.setExitCode(EXIT_CODES.environment);
        return;
      }
      dependencies.writeData(await authStatus(dependencies.environment));
      dependencies.setExitCode(EXIT_CODES.success);
    });

  auth
    .command("status")
    .description("show GitHub authentication status")
    .action(async () => {
      dependencies.writeData(await authStatus(dependencies.environment));
      dependencies.setExitCode(EXIT_CODES.success);
    });
}

import { rm } from "node:fs/promises";
import { resolve } from "node:path";

import {
  createIndexIdentitySet,
  createRepositoryId,
  evaluateInvalidation,
  getLocalIndexPath,
  getLocalIndexStatus,
  inspectLocalIndex,
  openLocalIndex,
  readLocalIndexSemanticState,
  verifyLocalIndex,
  writeLocalIndexSemanticState,
  type LocalIndexSemanticState,
} from "@fuzit/index";
import { LOCAL_INDEX_SCHEMA_VERSION } from "@fuzit/schemas";
import { Command } from "commander";

import {
  acquireRepository,
  acquisitionContentHash,
  repositoryIdentity,
} from "../../application/repository.js";

const versions = {
  scannerVersion: "1",
  parserVersion: "1",
  securityPolicyVersion: "1",
  schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
} as const;

const componentIdentities = {
  parser: { name: "fuzit-built-in-parsers", version: versions.parserVersion },
  analysis: { name: "fuzit-analysis", version: "1" },
  graph: { name: "fuzit-context-graph", schemaVersion: 1 },
  schema: { name: "fuzit-incremental-index", schemaVersion: 1 },
  securityPolicy: {
    name: "fuzit-security-policy",
    version: versions.securityPolicyVersion,
  },
} as const;

export function registerCacheCommand(
  program: Command,
  runtime: {
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
  },
): void {
  const cache = program.command("cache").description("Manage the local index.");
  const location = async (root: string) => {
    const repositoryRoot = resolve(root);
    const cacheHome = resolve(
      runtime.environment.FUZIT_CACHE_HOME ??
        runtime.environment.LOCALAPPDATA ??
        ".cache",
    );
    const identity = await repositoryIdentity(repositoryRoot);
    return {
      path: getLocalIndexPath({
        cacheHome,
        repositoryFingerprint: identity.fingerprint,
      }),
      repositoryId: createRepositoryId(identity.fingerprint),
      fingerprint: identity.fingerprint,
      cacheHome,
      repositoryRoot,
    };
  };
  const currentState = async (
    root: string,
  ): Promise<LocalIndexSemanticState> => {
    const acquisition = await acquireRepository(root, runtime.environment);
    return {
      ...versions,
      contentHash: acquisitionContentHash(acquisition),
      configHash: acquisition.configHash,
      identities: createIndexIdentitySet({
        effectiveConfiguration: acquisition.configHash,
        ignorePolicy: {
          configuration: acquisition.configHash,
          precedence: "hard-cli-project-fuzitignore-gitignore-defaults",
        },
        ...componentIdentities,
      }),
    };
  };

  cache
    .command("init")
    .requiredOption("--root <path>", "repository root")
    .action(async ({ root }: { root: string }) => {
      const value = await location(root);
      const store = await openLocalIndex(value.path, value.repositoryId);
      await writeLocalIndexSemanticState(
        value.path,
        await currentState(value.repositoryRoot),
      );
      runtime.writeData({
        path: store.directory,
        repositoryId: value.repositoryId,
        schemaVersion: store.metadata.schemaVersion,
        state: "ready",
      });
    });

  cache
    .command("status")
    .requiredOption("--root <path>")
    .option("--json")
    .action(async ({ root }: { root: string }) => {
      const value = await location(root);
      const observed = await inspectLocalIndex(value.path, value.repositoryId);
      const stored = await readLocalIndexSemanticState(value.path);
      runtime.writeData({
        ...getLocalIndexStatus(
          {
            cacheHome: value.cacheHome,
            repositoryFingerprint: value.fingerprint,
          },
          observed,
        ),
        identities: stored?.identities ?? null,
      });
    });

  cache
    .command("rebuild")
    .requiredOption("--root <path>")
    .option("--dry-run")
    .action(async ({ root, dryRun }: { root: string; dryRun?: boolean }) => {
      const value = await location(root);
      const current = await currentState(value.repositoryRoot);
      const stored = await readLocalIndexSemanticState(value.path);
      const decision =
        stored === undefined
          ? {
              valid: false,
              reasons: ["index semantic state absent"],
              action: "rebuild" as const,
              affectedRecordTypes: ["file", "analysis", "graph"] as const,
            }
          : evaluateInvalidation(stored, current);
      if (!dryRun && decision.action === "rebuild") {
        await openLocalIndex(value.path, value.repositoryId);
        await writeLocalIndexSemanticState(value.path, current);
      }
      runtime.writeData({
        path: value.path,
        dryRun: dryRun === true,
        decision,
      });
    });

  cache
    .command("verify")
    .requiredOption("--root <path>")
    .action(async ({ root }: { root: string }) => {
      const value = await location(root);
      const current = await currentState(value.repositoryRoot);
      const result = await verifyLocalIndex({
        indexPath: value.path,
        expectedRepositoryId: value.repositoryId,
        currentSemanticState: current,
      });
      runtime.writeData({
        schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
        repositoryId: value.repositoryId,
        path: value.path,
        state: result.status,
        valid: result.valid,
        rebuildRequired: result.rebuildRequired,
        reasons: result.reasons,
        details: result.details,
      });
    });

  cache
    .command("purge")
    .requiredOption("--root <path>")
    .option("--dry-run")
    .action(async ({ root, dryRun }: { root: string; dryRun?: boolean }) => {
      const value = await location(root);
      if (!dryRun) await rm(value.path, { recursive: true, force: true });
      runtime.writeData({
        path: value.path,
        dryRun: dryRun === true,
        action: dryRun
          ? "would purge exact Fuzit-owned index directory"
          : "purged exact Fuzit-owned index directory",
      });
    });
}

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { createTaskContext, renderTaskContext } from "@fuzit/core";
import {
  createRepositoryId,
  getLocalIndexPath,
  inspectLocalIndex,
} from "@fuzit/index";
import { getProfile } from "@fuzit/profiles";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

import {
  acquireRepository,
  repositoryIdentity,
} from "../../application/repository.js";

export function registerContextCommand(
  program: Command,
  dependencies: {
    readonly currentDirectory: string;
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
    readonly setExitCode: (code: ExitCode) => void;
  },
): void {
  program
    .command("context")
    .description("build task-aware local context")
    .requiredOption("--task <task>")
    .requiredOption("--profile <profile>")
    .requiredOption("--budget-tokens <tokens>")
    .requiredOption("--format <format>")
    .requiredOption("--output <path>")
    .option("--root <path>")
    .option("--no-index")
    .option("--explain", "emit aligned selection evidence")
    .action(
      async (options: {
        task: string;
        profile: string;
        budgetTokens: string;
        format: string;
        output: string;
        root?: string;
        index: boolean;
        explain?: boolean;
      }) => {
        try {
          const profile = getProfile(options.profile);
          if (!["markdown", "json", "text", "xml"].includes(options.format))
            throw new Error("unsupported format");
          const root = resolve(
            dependencies.currentDirectory,
            options.root ?? ".",
          );
          const acquisition = await acquireRepository(
            root,
            dependencies.environment,
          );
          let index: "used" | "bypassed" | "unavailable" = options.index
            ? "unavailable"
            : "bypassed";
          if (options.index) {
            const identity = await repositoryIdentity(root);
            const cacheHome =
              dependencies.environment.FUZIT_CACHE_HOME ??
              resolve(dependencies.environment.LOCALAPPDATA ?? ".cache");
            const indexPath = getLocalIndexPath({
              cacheHome,
              repositoryFingerprint: identity.fingerprint,
            });
            const status = await inspectLocalIndex(
              indexPath,
              createRepositoryId(identity.fingerprint),
            );
            if (status.kind === "ready") {
              index = "used";
            } else {
              index = "unavailable";
            }
          }
          const result = await createTaskContext({
            items: acquisition.items,
            task: options.task,
            profile,
            budgetTokens: Number.parseInt(options.budgetTokens, 10),
            ...(options.explain === undefined
              ? {}
              : { explain: options.explain }),
            index,
            omissions: options.explain
              ? acquisition.omissions.map(({ path, reason }) => ({
                  path,
                  reason,
                }))
              : [],
          });
          const rendered = renderTaskContext(
            result,
            options.format as "markdown" | "json" | "text" | "xml",
          );
          if (options.output === "-") dependencies.writeData(rendered);
          else {
            const output = resolve(
              dependencies.currentDirectory,
              options.output,
            );
            await mkdir(dirname(output), { recursive: true });
            await writeFile(output, rendered, { encoding: "utf8", flag: "wx" });
            dependencies.writeData({
              output,
              selected: result.selected.map(({ path }) => path),
              report: result,
            });
          }
        } catch (error) {
          dependencies.writeData({
            error: error instanceof Error ? error.message : String(error),
          });
          dependencies.setExitCode(EXIT_CODES.validation);
        }
      },
    );
}

import { resolve } from "node:path";

import { computeSnapshotDelta, readSnapshot } from "@fuzit/snapshots";
import type { Command } from "commander";

export function registerDiffCommand(
  program: Command,
  runtime: {
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
  },
): void {
  program
    .command("diff")
    .argument("<snapshot-a>")
    .argument("<snapshot-b>")
    .option("--json")
    .description("Compare immutable snapshots.")
    .action(async (snapshotA: string, snapshotB: string) => {
      const directory = resolve(
        runtime.environment.FUZIT_CACHE_HOME ?? ".cache",
        "snapshots",
      );
      runtime.writeData(
        computeSnapshotDelta(
          await readSnapshot(directory, snapshotA),
          await readSnapshot(directory, snapshotB),
        ),
      );
    });
}

import { loadEffectiveConfig } from "@fuzit/config";
import { runDoctor, type DoctorReport } from "@fuzit/core";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface DoctorCommandDependencies {
  readonly workingDirectory: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly json: boolean;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

export function formatDoctorReport(report: DoctorReport): string {
  const lines = report.checks.map((check) => {
    const label =
      check.status === "pass"
        ? "PASS"
        : check.status === "warning"
          ? "WARN"
          : "FAIL";
    return `${label} ${check.id}: ${check.message}`;
  });

  return ["Fuzit doctor", ...lines].join("\n");
}

export function registerDoctorCommand(
  program: Command,
  dependencies: DoctorCommandDependencies,
): void {
  program
    .command("doctor")
    .description("report local environment readiness")
    .action(async () => {
      const report = await runDoctor(dependencies.workingDirectory, {
        ...(dependencies.environment.npm_config_user_agent === undefined
          ? {}
          : {
              pnpmUserAgent: dependencies.environment.npm_config_user_agent,
            }),
        checkConfiguration: async () => {
          await loadEffectiveConfig({
            repositoryRoot: dependencies.workingDirectory,
            environment: dependencies.environment,
          });
        },
      });

      dependencies.writeData(report);
      dependencies.setExitCode(
        report.status === "ready" ? EXIT_CODES.success : EXIT_CODES.environment,
      );
    });
}

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import {
  explainPath,
  formatSelectionExplanation,
  renderSelectionFailure,
  type SelectionReport,
} from "@fuzit/selection";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

async function loadReport(path: string): Promise<SelectionReport> {
  const value: unknown = JSON.parse(await readFile(resolve(path), "utf8"));
  if (
    typeof value !== "object" ||
    value === null ||
    !("schemaVersion" in value) ||
    !("entries" in value) ||
    value.schemaVersion !== 1 ||
    !Array.isArray(value.entries)
  ) {
    throw new Error("Selection report schema is invalid.");
  }
  return value as SelectionReport;
}

export function registerExplainCommand(
  program: Command,
  dependencies: {
    readonly json: boolean;
    readonly writeData: (value: unknown) => void;
    readonly setExitCode: (code: ExitCode) => void;
  },
): void {
  const explain = program
    .command("explain")
    .description("explain selection evidence");
  explain
    .command("selection <report>")
    .description("explain every selection decision")
    .action(async (reportPath: string) => {
      try {
        const report = await loadReport(reportPath);
        dependencies.writeData(
          dependencies.json
            ? report
            : report.entries.map(formatSelectionExplanation).join("\n\n"),
        );
      } catch (error) {
        dependencies.writeData(
          renderSelectionFailure(error, dependencies.json ? "json" : "text"),
        );
        dependencies.setExitCode(EXIT_CODES.validation);
      }
    });
  explain
    .command("path <path> <report>")
    .description("explain one path")
    .action(async (path: string, reportPath: string) => {
      try {
        const evidence = explainPath(await loadReport(reportPath), path);
        dependencies.writeData(
          dependencies.json ? evidence : formatSelectionExplanation(evidence),
        );
      } catch (error) {
        dependencies.writeData(
          renderSelectionFailure(error, dependencies.json ? "json" : "text"),
        );
        dependencies.setExitCode(EXIT_CODES.validation);
      }
    });
}

import {
  collectGitDiff,
  collectGitHistory,
  collectGitStatus,
  collectBlame,
  collectFileHistory,
} from "@fuzit/git";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface GitCommandDependencies {
  readonly currentDirectory: string;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

export function registerGitCommand(
  program: Command,
  dependencies: GitCommandDependencies,
): void {
  const git = program.command("git").description("inspect local Git context");
  git
    .command("status")
    .description("show normalized working changes")
    .action(async () => {
      dependencies.writeData({
        schemaVersion: 1,
        changes: await collectGitStatus(dependencies.currentDirectory),
      });
      dependencies.setExitCode(EXIT_CODES.success);
    });
  git
    .command("log")
    .description("show bounded local commit history")
    .option("--limit <count>", "maximum commits", "20")
    .action(async (options: { limit: string }) => {
      const limit = Number.parseInt(options.limit, 10);
      dependencies.writeData({
        schemaVersion: 1,
        entries: await collectGitHistory(dependencies.currentDirectory, {
          limit: Number.isFinite(limit) ? limit : 20,
        }),
      });
      dependencies.setExitCode(EXIT_CODES.success);
    });
  git
    .command("diff")
    .description("show bounded redacted local diff")
    .option("--base <revision>", "explicit base revision")
    .action(async (options: { base?: string }) => {
      dependencies.writeData({
        schemaVersion: 1,
        ...(await collectGitDiff(dependencies.currentDirectory, options)),
      });
      dependencies.setExitCode(EXIT_CODES.success);
    });
  git
    .command("file-history")
    .argument("<path>")
    .option("--limit <count>", "maximum commits", "20")
    .action(async (path: string, options: { limit: string }) => {
      dependencies.writeData({
        schemaVersion: 1,
        entries: await collectFileHistory(
          dependencies.currentDirectory,
          path,
          Number.parseInt(options.limit, 10),
        ),
      });
      dependencies.setExitCode(EXIT_CODES.success);
    });
  git
    .command("blame")
    .argument("<path>")
    .requiredOption("--lines <range>", "inclusive start:end")
    .action(async (path: string, options: { lines: string }) => {
      dependencies.writeData({
        schemaVersion: 1,
        lines: await collectBlame(
          dependencies.currentDirectory,
          path,
          options.lines,
        ),
      });
      dependencies.setExitCode(EXIT_CODES.success);
    });
}

import { readFile, writeFile, mkdir, realpath, stat } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { createHash } from "node:crypto";
import { toRepositoryRelativePath } from "@fuzit/core";
import {
  buildFilePackageGraph,
  graphImpact,
  graphNeighbors,
  graphQuery,
  graphStats,
  type GraphSnapshot,
} from "@fuzit/graph";
import {
  EXIT_CODES,
  parseGraphEdge,
  parseGraphNode,
  type Diagnostic,
  type ExitCode,
  type GraphNodeKind,
} from "@fuzit/schemas";
import type { Command } from "commander";
import {
  acquireRepository,
  repositoryIdentity,
} from "../../application/repository.js";

interface GraphCommandDependencies {
  readonly repositoryRoot: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly json: boolean;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (value: Diagnostic) => void;
  readonly setExitCode: (code: ExitCode) => void;
}
const diagnostic = (
  severity: "warning" | "error",
  message: string,
): Diagnostic => ({
  schemaVersion: 1,
  code: severity === "error" ? "CLI.INVALID_ARGUMENT" : "GRAPH.PARTIAL",
  severity,
  source: "graph",
  message,
});
async function loadGraph(root: string, input: string): Promise<GraphSnapshot> {
  const path = resolve(root, input);
  const [canonicalRoot, canonicalPath] = await Promise.all([
    realpath(root),
    realpath(path),
  ]);
  if (!isGraphPathInsideRepository(canonicalRoot, canonicalPath))
    throw new Error("Graph input must remain inside the repository root");
  const value: unknown = JSON.parse(
    (await readFile(canonicalPath, "utf8")).replace(/^\uFEFF/, ""),
  );
  if (
    !value ||
    typeof value !== "object" ||
    !("repositoryId" in value) ||
    !("nodes" in value) ||
    !("edges" in value) ||
    !Array.isArray(value.nodes) ||
    !Array.isArray(value.edges)
  )
    throw new Error("Graph input schema is invalid");
  return {
    schemaVersion: 1,
    repositoryId: String(value.repositoryId),
    nodes: value.nodes.map(parseGraphNode),
    edges: value.edges.map(parseGraphEdge),
    diagnostics:
      "diagnostics" in value && Array.isArray(value.diagnostics)
        ? value.diagnostics.map(String).slice(0, 128)
        : [],
    completeness:
      "completeness" in value && value.completeness === "partial"
        ? "partial"
        : "complete",
  };
}

export function isGraphPathInsideRepository(
  repositoryRoot: string,
  graphPath: string,
): boolean {
  try {
    toRepositoryRelativePath(repositoryRoot, graphPath);
    return true;
  } catch {
    return false;
  }
}

async function hasGitMetadata(directory: string): Promise<boolean> {
  try {
    await stat(join(directory, ".git"));
    return true;
  } catch {
    return false;
  }
}

async function findContainingGitRepository(
  startDirectory: string,
): Promise<string | null> {
  let directory = await realpath(startDirectory);
  while (true) {
    if (await hasGitMetadata(directory)) return directory;
    const parent = dirname(directory);
    if (parent === directory) return null;
    directory = parent;
  }
}

async function resolveGraphInput(
  defaultRoot: string,
  input: string,
  explicitRoot?: string,
): Promise<{ readonly root: string; readonly input: string }> {
  const requestedRoot = explicitRoot
    ? resolve(defaultRoot, explicitRoot)
    : defaultRoot;
  const inputPath = isAbsolute(input)
    ? resolve(input)
    : resolve(requestedRoot, input);

  if (explicitRoot) return { root: requestedRoot, input: inputPath };

  const containingRoot = await findContainingGitRepository(dirname(inputPath));
  if (containingRoot && isGraphPathInsideRepository(containingRoot, inputPath))
    return { root: containingRoot, input: inputPath };

  const canonicalDefaultRoot = await realpath(defaultRoot);
  if (isGraphPathInsideRepository(canonicalDefaultRoot, inputPath))
    return { root: canonicalDefaultRoot, input: inputPath };

  throw new Error(
    "Graph input is outside the current repository root. Pass --root <repository> for an artifact inside another repository.",
  );
}
async function buildRepositoryGraph(
  root: string,
  environment: Readonly<Record<string, string | undefined>>,
): Promise<GraphSnapshot> {
  const acquisition = await acquireRepository(root, environment);
  const identity = await repositoryIdentity(root);
  const hash = (value: string) =>
    createHash("sha256").update(value).digest("hex");
  const repositoryId = `sha256:${hash(identity.fingerprint)}` as const;
  return buildFilePackageGraph({
    analysis: {
      schemaVersion: 1,
      repositoryId,
      analysisIdentity: `analysis:repository:${hash(identity.fingerprint)}`,
      files: acquisition.items.map((item) => ({
        id: `analysis:file:${hash(item.path)}`,
        repositoryId,
        kind: "file" as const,
        path: item.path,
        language: "text",
        contentHash: `sha256:${item.sha256}`,
      })),
      modules: [],
      symbols: [],
      relationships: [],
      completeness: acquisition.complete ? "complete" : "partial",
      diagnostics: acquisition.omissions
        .filter(({ failure }) => failure)
        .map(({ path, reason }) => `${path}: ${reason}`)
        .slice(0, 128),
    },
    revision: identity.revision ?? `working-tree:${identity.fingerprint}`,
    packages: [],
  });
}
export function registerGraphCommand(
  program: Command,
  dependencies: GraphCommandDependencies,
): void {
  const graph = program
    .command("graph")
    .description("query a bounded local context graph");
  const input = (command: Command) =>
    command
      .option(
        "--input <path>",
        "graph JSON path; its containing Git repository is used when --root is omitted",
      )
      .option(
        "--root <path>",
        "repository root that must contain --input; defaults to the input artifact's Git repository",
      );
  const run = async (
    options: {
      input?: string;
      root?: string;
      node?: string;
      depth?: string;
      limit?: string;
      kind?: string;
    },
    operation: "stats" | "neighbors" | "impact" | "query",
  ) => {
    try {
      const root = resolve(dependencies.repositoryRoot, options.root ?? ".");
      const snapshot = options.input
        ? await resolveGraphInput(
            dependencies.repositoryRoot,
            options.input,
            options.root,
          ).then((resolved) => loadGraph(resolved.root, resolved.input))
        : await buildRepositoryGraph(root, dependencies.environment);
      const limits = {
        depth: Number(options.depth ?? 1),
        maxItems: Number(options.limit ?? 100),
      };
      const result =
        operation === "stats"
          ? graphStats(snapshot)
          : operation === "query"
            ? graphQuery(snapshot, {
                repositoryId: snapshot.repositoryId,
                limits,
                ...(options.kind
                  ? { nodeKinds: [options.kind as GraphNodeKind] }
                  : {}),
              })
            : (operation === "impact" ? graphImpact : graphNeighbors)(
                snapshot,
                options.node!,
                { repositoryId: snapshot.repositoryId, limits },
              );
      if (dependencies.json) {
        dependencies.writeData(result);
      } else {
        dependencies.writeData(
          operation === "stats"
            ? {
                kind: "graph-stats",
                ...result,
              }
            : {
                kind: "graph-query",
                output: options.input ?? "",
                results: (result as ReturnType<typeof graphQuery>).nodes,
                diagnostics: (result as ReturnType<typeof graphQuery>).diagnostics,
                truncated: (result as ReturnType<typeof graphQuery>).truncated,
              },
        );
      }
      if (snapshot.completeness === "partial")
        for (const message of snapshot.diagnostics)
          dependencies.writeDiagnostic(diagnostic("warning", message));
    } catch (error) {
      dependencies.writeDiagnostic(
        diagnostic(
          "error",
          error instanceof Error ? error.message : String(error),
        ),
      );
      dependencies.setExitCode(EXIT_CODES.validation);
    }
  };
  graph
    .command("build")
    .description("build a repository graph snapshot")
    .option("--root <path>", "repository root", ".")
    .option("--output <path>", "output graph JSON", ".fuzit/graph.json")
    .action(async (options: { root: string; output: string }) => {
      try {
        const root = resolve(dependencies.repositoryRoot, options.root);
        const snapshot = await buildRepositoryGraph(
          root,
          dependencies.environment,
        );
        const output = resolve(root, options.output);
        const rel = relative(root, output);
        if (rel.startsWith("..") || isAbsolute(rel))
          throw new Error(
            "Graph output must remain inside the repository root",
          );
        await mkdir(resolve(output, ".."), { recursive: true });
        await writeFile(output, `${JSON.stringify(snapshot, null, 2)}\n`, {
          encoding: "utf8",
          flag: "wx",
        });
        const buildResult = {
          output,
          nodes: snapshot.nodes.length,
          edges: snapshot.edges.length,
          completeness: snapshot.completeness,
        };
        dependencies.writeData(
          dependencies.json ? buildResult : { kind: "graph-build", ...buildResult },
        );
      } catch (error) {
        dependencies.writeDiagnostic(
          diagnostic(
            "error",
            error instanceof Error ? error.message : String(error),
          ),
        );
        dependencies.setExitCode(EXIT_CODES.validation);
      }
    });
  input(
    graph.command("stats").description("show deterministic graph statistics"),
  ).action((options) => run(options, "stats"));
  input(
    graph
      .command("neighbors <node>")
      .description("show bounded graph neighbors")
      .option("--depth <n>", "maximum traversal depth", "1")
      .option("--limit <n>", "maximum returned items", "100"),
  ).action((node, options) => run({ ...options, node }, "neighbors"));
  input(
    graph
      .command("impact <node>")
      .description("show bounded impact neighbors")
      .option("--depth <n>", "maximum traversal depth", "2")
      .option("--limit <n>", "maximum returned items", "100"),
  ).action((node, options) => run({ ...options, node }, "impact"));
  input(
    graph
      .command("query")
      .description("filter bounded graph nodes")
      .option("--kind <kind>", "graph node kind")
      .option("--limit <n>", "maximum returned items", "100"),
  ).action((options) => run(options, "query"));
}

import {
  InitConflictError,
  applyInitialization,
  planInitialization,
  type InitPlan,
} from "@fuzit/config";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface InitCommandDependencies {
  readonly repositoryRoot: string;
  readonly json: boolean;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

function formatInitPlan(plan: InitPlan, dryRun: boolean): string {
  if (plan.changes.length === 0) {
    return "Fuzit init\nNo changes.";
  }

  const lines = [dryRun ? "Fuzit init dry run" : "Fuzit init applied"];
  for (const change of plan.changes) {
    lines.push(`${change.action.toUpperCase()} ${change.path}`);
    if (change.content !== undefined) {
      lines.push(
        ...change.content
          .trimEnd()
          .split("\n")
          .map((line) => `  ${line}`),
      );
    }
    if (change.lines !== undefined) {
      lines.push(...change.lines.map((line) => `  ${line}`));
    }
  }
  return lines.join("\n");
}

export function registerInitCommand(
  program: Command,
  dependencies: InitCommandDependencies,
): void {
  program
    .command("init")
    .description("initialize approved local Fuzit files")
    .option("--dry-run", "show exact changes without writing files", false)
    .option("--force", "replace an incompatible existing configuration", false)
    .option("--mcp", "initialize Model Context Protocol server config and Agent Skills", false)
    .action(async (options: { dryRun: boolean; force: boolean; mcp?: boolean }) => {
      try {
        const input = {
          repositoryRoot: dependencies.repositoryRoot,
          force: options.force,
        };
        let plan = await planInitialization(input);

        if (options.mcp) {
          const mcpConfigContent = JSON.stringify(
            {
              mcpServers: {
                fuzit: {
                  command: "fuzit",
                  args: ["plugin", "mcp"],
                  env: { FUZIT_CACHE_HOME: ".cache" },
                },
              },
            },
            null,
            2,
          );
          const skillContent = `---
name: fuzit-pack
description: Build task-aware security-filtered context bundle for AI coding workflows.
---
# Fuzit Context Pack Skill

Use \`fuzit pack --root .\` to bundle repository context with automatic security redaction and intelligence graph ranking.
`;
          const mcpPlan = {
            ...plan,
            changes: [
              ...plan.changes,
              { action: "CREATE", path: ".vscode/mcp.json", content: mcpConfigContent },
              { action: "CREATE", path: ".agents/skills/fuzit-pack/SKILL.md", content: skillContent },
            ],
          };

          dependencies.writeData(
            dependencies.json
              ? { ...mcpPlan, dryRun: options.dryRun, applied: !options.dryRun }
              : formatInitPlan(mcpPlan as any, options.dryRun),
          );
          dependencies.setExitCode(EXIT_CODES.success);
          return;
        }

        if (!options.dryRun) {
          await applyInitialization(input, plan);
        }

        dependencies.writeData(
          dependencies.json
            ? {
                ...plan,
                dryRun: options.dryRun,
                applied: !options.dryRun && plan.changes.length > 0,
              }
            : formatInitPlan(plan, options.dryRun),
        );
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        if (error instanceof InitConflictError) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: error.code,
            severity: "error",
            source: "init",
            message: error.message,
          });
          dependencies.setExitCode(EXIT_CODES.validation);
          return;
        }
        throw error;
      }
    });
}

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { runIssueContext } from "@fuzit/core";
import {
  parseGitHubUrl,
  parseOwnerRepoHash,
  parseNumericWithRepo,
} from "@fuzit/provider-github";
import { inferRemoteFromGitConfig, runGit } from "@fuzit/git";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import { getProfile } from "@fuzit/profiles";
import type { Command } from "commander";

export function registerIssueCommand(
  program: Command,
  dependencies: {
    readonly currentDirectory: string;
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
    readonly setExitCode: (code: ExitCode) => void;
  },
): void {
  program
    .command("issue")
    .description("get context from a GitHub issue")
    .argument("<source>", "Issue URL, OWNER/REPO#NUMBER, or ISSUE-NUMBER")
    .option("--repo <repo>", "target repository in OWNER/REPO format")
    .option("--profile <profile>", "profile", "bug-fix")
    .option("--format <format>", "output format", "markdown")
    .option("--output <path>", "output path or '-' for stdout", "-")
    .action(
      async (
        sourceArg: string,
        options: {
          repo?: string;
          profile: string;
          format: string;
          output: string;
        },
      ) => {
        try {
          getProfile(options.profile);
          let issueRef;
          if (
            sourceArg.startsWith("http://") ||
            sourceArg.startsWith("https://")
          ) {
            const parsed = parseGitHubUrl(sourceArg);
            if (!parsed.ok || parsed.ref.kind !== "github-issue") {
              throw new Error(`invalid issue URL '${sourceArg}'`);
            }
            issueRef = parsed.ref;
          } else if (sourceArg.includes("#")) {
            const parsed = parseOwnerRepoHash(sourceArg, "issue");
            if (!parsed.ok) throw new Error(parsed.reason);
            issueRef = parsed.ref;
          } else if (/^\d+$/.test(sourceArg)) {
            if (options.repo) {
              const parsed = parseNumericWithRepo(
                sourceArg,
                options.repo,
                "issue",
              );
              if (!parsed.ok) throw new Error(parsed.reason);
              issueRef = parsed.ref;
            } else {
              const remote = await runGit(["remote", "get-url", "origin"], {
                cwd: dependencies.currentDirectory,
              });
              const inferred = remote.ok
                ? inferRemoteFromGitConfig([
                    { name: "origin", url: remote.stdout.trim() },
                  ])
                : null;
              if (!inferred)
                throw new Error(
                  "Could not infer repository from local clone; pass --repo OWNER/REPO",
                );
              const parsed = parseNumericWithRepo(
                sourceArg,
                `${inferred.owner}/${inferred.repo}`,
                "issue",
              );
              if (!parsed.ok) throw new Error(parsed.reason);
              issueRef = parsed.ref;
            }
          } else {
            throw new Error(`invalid issue argument '${sourceArg}'`);
          }

          const result = await runIssueContext({
            issueRef,
            profileName: options.profile,
            environment: dependencies.environment,
          });
          if (!["markdown", "json", "text"].includes(options.format))
            throw new Error(`unsupported issue format '${options.format}'`);
          const rendered =
            options.format === "json"
              ? `${JSON.stringify(result, null, 2)}\n`
              : `${result.summary}\n`;

          if (options.output === "-") {
            dependencies.writeData(
              options.format === "json" ? result : rendered,
            );
          } else {
            const outputPath = resolve(
              dependencies.currentDirectory,
              options.output,
            );
            await mkdir(dirname(outputPath), { recursive: true });
            await writeFile(outputPath, rendered, {
              encoding: "utf8",
              flag: "wx",
            });
            dependencies.writeData({ output: outputPath, result });
          }
        } catch (error) {
          dependencies.writeData({
            error: error instanceof Error ? error.message : String(error),
          });
          dependencies.setExitCode(EXIT_CODES.validation);
        }
      },
    );
}

import { open, readFile } from "node:fs/promises";
import { extname, resolve } from "node:path";

import { estimateBudget } from "@fuzit/budgeting";
import {
  createContextBundle,
  createFileContextItem,
  registerSecurityFilteredItem,
  selectDeltaScope,
  transformCodeContent,
  parseByteSize,
  splitPackedOutput,
  type SecurityFilteredItem,
} from "@fuzit/core";
import { markdownRenderer } from "@fuzit/renderer-markdown";
import { RendererRegistry } from "@fuzit/renderer-core";
import { jsonRenderer } from "@fuzit/renderer-json";
import { renderXml, xmlRenderer } from "@fuzit/renderer-xml";
import { textRenderer } from "@fuzit/renderer-text";
import {
  collectGitDiff,
  collectGitHistory,
  collectGitIdentity,
  collectGitStatus,
} from "@fuzit/git";
import {
  computeSnapshotDelta,
  createSnapshot,
  readSnapshot,
} from "@fuzit/snapshots";
import { parseGitHubUrl, parseOwnerRepoHash } from "@fuzit/provider-github";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

import {
  acquireRepository,
  analyzeRepository,
} from "../../application/repository.js";
import { copyToClipboard } from "../../output/clipboard.js";

interface PackDependencies {
  readonly currentDirectory: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

function collect(value: string, previous: string[]): string[] {
  return [...previous, value];
}

async function readStdinText(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(Buffer.from(chunk));
  }
  return Buffer.concat(chunks).toString("utf8");
}

function matchesPattern(path: string, pattern: string): boolean {
  const normalizedPath = path.toLowerCase();
  const normalizedPattern = pattern.toLowerCase().replace(/^\.\//, "");
  if (normalizedPattern.includes("*")) {
    const regex = new RegExp("^" + normalizedPattern.replace(/\*/g, ".*") + "$");
    return regex.test(normalizedPath);
  }
  return normalizedPath.includes(normalizedPattern);
}

export function resolvePackRenderer(
  renderers: RendererRegistry,
  format: string,
  output: string,
) {
  if (format === "auto") {
    if (output === "-") throw new Error("PACK.AUTO_REQUIRES_EXTENSION");
    const extension = extname(output).toLowerCase();
    const metadata = renderers
      .list()
      .find((candidate) => candidate.extension === extension);
    if (metadata === undefined) throw new Error("PACK.EXTENSION_UNKNOWN");
    return renderers.get(metadata.format);
  }
  const renderer = renderers.get(format);
  if (
    output !== "-" &&
    extname(output).toLowerCase() !== renderer.metadata.extension
  )
    throw new Error("PACK.EXTENSION_MISMATCH");
  if (output === "-" && renderer.metadata.capabilities.binary)
    throw new Error("PACK.BINARY_STDOUT_UNSUPPORTED");
  return renderer;
}

export function registerPackCommand(
  program: Command,
  dependencies: PackDependencies,
): void {
  const renderers = new RendererRegistry([
    jsonRenderer,
    markdownRenderer,
    textRenderer,
    xmlRenderer,
  ]);
  program
    .command("pack [source]")
    .description("create a local security-filtered context bundle")
    .option("--format <format>", "markdown, json, xml, text, or auto", "auto")
    .option("--output <path>", "output path or - for stdout", "fuzit-pack.md")
    .option("--root <path>", "repository root")
    .option("--remote <source>", "remote GitHub repository URL or OWNER/REPO")
    .option("--include <pattern>", "include path pattern", collect, [])
    .option("--ignore <pattern>", "ignore path pattern", collect, [])
    .option("--compress", "compress code to structural skeletons", false)
    .option("--remove-comments", "remove comments from source code", false)
    .option("--remove-empty-lines", "remove consecutive blank lines", false)
    .option("--line-numbers", "add line numbers to file contents", false)
    .option("--split-size <size>", "split output into chunks (e.g. 500kb, 1mb)")
    .option("--copy", "copy packed output to system clipboard", false)
    .option("--dry-run", "report selection without writing output")
    .option("--instruction <text>", "prepend system prompt or instructions to context bundle")
    .option("--config <path>", "custom configuration file path")
    .option("--max-files <count>", "override maximum file count limit", (val) => Number(val))
    .option("--git <mode>", "include current, history, or diff Git context")
    .option("--since <snapshot>", "include changes since an immutable snapshot")
    .option("-F, --full", "force full unlimited dump of all repository files", false)
    .option("--target <model>", "target AI model context window optimization (e.g. gpt-terra, gpt-sol, gemini-3.6, claude-fable, deepseek-r1)")
    .option("--task <intent>", "intent-based context retrieval for specific natural language tasks")
    .option("--diff", "pack only files changed in git diff", false)
    .option("--staged", "pack only staged git files", false)
    .option("--profile <profile>", "apply preset workflow profile (e.g. bug-fix, security-audit, code-review)")
    .option("--zip", "output compressed .zip context archive", false)
    .action(
      async (
        sourceArg: string | undefined,
        options: {
          format: string;
          output: string;
          root?: string;
          remote?: string;
          include: string[];
          ignore: string[];
          compress?: boolean;
          removeComments?: boolean;
          removeEmptyLines?: boolean;
          lineNumbers?: boolean;
          splitSize?: string;
          copy?: boolean;
          dryRun?: boolean;
          instruction?: string;
          config?: string;
          maxFiles?: number;
          git?: string;
          since?: string;
          full?: boolean;
          target?: string;
          task?: string;
          diff?: boolean;
          staged?: boolean;
          profile?: string;
          zip?: boolean;
        },
      ) => {
        let renderer;
        try {
          renderer = resolvePackRenderer(
            renderers,
            options.format,
            options.output,
          );
        } catch {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: "PACK.FORMAT_UNSUPPORTED",
            severity: "error",
            source: "pack",
            message: `Invalid format/output combination: ${options.format} (${renderers
              .list()
              .map(({ format }) => format)
              .join(", ")}).`,
          });
          dependencies.setExitCode(EXIT_CODES.validation);
          return;
        }

        const isStdin = options.root === "-" || sourceArg === "-";
        const remoteSource = options.remote ?? (sourceArg && (sourceArg.startsWith("http://") || sourceArg.startsWith("https://") || sourceArg.includes("/")) ? sourceArg : undefined);

        const root = resolve(
          dependencies.currentDirectory,
          options.root ?? dependencies.currentDirectory,
        );

        let items: SecurityFilteredItem[] = [];
        let failedSources: string[] = [];
        const effectiveMaxFiles = options.full ? 999999 : options.maxFiles;
        const acquisition = await acquireRepository(
          root,
          dependencies.environment,
          { ...(effectiveMaxFiles !== undefined ? { maxFiles: effectiveMaxFiles } : {}) },
        );

        if (isStdin) {
          const stdinText = await readStdinText();
          const item = createFileContextItem(
            {
              schemaVersion: 1,
              path: "stdin.txt",
              kind: "text",
              extension: "txt",
              language: { name: "text", confidence: 1.0 },
              vendored: false,
              generated: false,
              symlink: false,
              readable: true,
              sizeBytes: Buffer.byteLength(stdinText, "utf8"),
            },
            {
              status: "complete",
              content: stdinText,
              sha256: "sha256:stdin",
            },
          );
          items = [registerSecurityFilteredItem({ ...item, findings: [] } as unknown as SecurityFilteredItem)];
        } else {
          items = [...acquisition.items];
          failedSources = acquisition.omissions
            .filter(({ failure }) => failure)
            .map(({ path, reason }) => `${path}: ${reason}`);
        }

        // Apply --diff or --staged filter
        if (options.diff || options.staged) {
          const status = await collectGitStatus(root);
          const changedPaths = new Set(status.map((s) => s.path));
          if (changedPaths.size > 0) {
            items = items.filter((item) => changedPaths.has(item.path));
          }
        }

        // Apply --task filter
        if (options.task) {
          const words = options.task.toLowerCase().split(/\s+/).filter(Boolean);
          items = items.filter((item) =>
            words.some(
              (w) =>
                item.path.toLowerCase().includes(w) ||
                (item.content && item.content.toLowerCase().includes(w)),
            ),
          );
        }

        // Apply --include and --ignore pattern filters
        if (options.include.length > 0) {
          items = items.filter((item) =>
            options.include.some((pattern) => matchesPattern(item.path, pattern)),
          );
        }
        if (options.ignore.length > 0) {
          items = items.filter(
            (item) =>
              !options.ignore.some((pattern) => matchesPattern(item.path, pattern)),
          );
        }

        // Apply transformations (compress, comments, empty lines, line numbers)
        const transformOptions = {
          ...(options.compress ? { compress: true } : {}),
          ...(options.removeComments ? { removeComments: true } : {}),
          ...(options.removeEmptyLines ? { removeEmptyLines: true } : {}),
          ...(options.lineNumbers ? { lineNumbers: true } : {}),
        };

        if (
          transformOptions.compress ||
          transformOptions.removeComments ||
          transformOptions.removeEmptyLines ||
          transformOptions.lineNumbers
        ) {
          items = items.map((item) => {
            if (!item.content) return item;
            const transformed = transformCodeContent(
              item.content,
              item.path,
              transformOptions,
            );
            return registerSecurityFilteredItem({
              ...item,
              content: transformed,
            });
          });
        }

        const intelligence = analyzeRepository(acquisition);

        const gitIdentity = await collectGitIdentity(root);
        let deltaScope:
          ReturnType<typeof selectDeltaScope<SecurityFilteredItem>> | undefined;
        if (options.since !== undefined) {
          const snapshotDirectory = resolve(
            dependencies.environment.FUZIT_CACHE_HOME ?? ".cache",
            "snapshots",
          );
          const baseline = await readSnapshot(snapshotDirectory, options.since);
          const current = createSnapshot({
            repositoryRevision: gitIdentity.head,
            dirty: gitIdentity.dirty,
            configHash: baseline.configHash,
            fileFingerprints: items.map((item) => ({
              path: item.path,
              sha256: item.sha256,
            })),
            bundleIdentityInputs: baseline.bundleIdentityInputs,
            complete: failedSources.length === 0,
            diagnostics: failedSources,
          });
          deltaScope = selectDeltaScope(
            items,
            computeSnapshotDelta(baseline, current),
          );
          items = [...deltaScope.included];
        }

        const estimate = estimateBudget(
          items.map((item) => item.content ?? "").join("\n"),
        );
        const gitContext =
          options.git === undefined
            ? undefined
            : {
                identity: gitIdentity,
                changes: await collectGitStatus(root),
                history:
                  options.git === "history"
                    ? await collectGitHistory(root)
                    : [],
                diff:
                  options.git === "diff" ? await collectGitDiff(root) : null,
              };

        const bundle = createContextBundle({
          schemaVersion: 1,
          source: { kind: "repository", root: "." },
          revision: gitIdentity.head,
          items: items.map((item) => ({
            id: item.id,
            path: item.path,
            sha256: item.sha256,
            contentStatus: item.contentStatus,
            redacted: item.findings.length > 0,
          })),
          redactionSummary: {
            findings: items.reduce(
              (sum, item) => sum + item.findings.length,
              0,
            ),
            redactedItems: items.filter((item) => item.findings.length > 0)
              .length,
            omittedItems: items.filter(
              (item) => item.contentStatus === "omitted",
            ).length,
          },
          warnings:
            failedSources.length > 0
              ? ["Pack completed partially."]
              : options.since === undefined
                ? []
                : [
                    `Baseline: ${options.since}`,
                    ...(deltaScope?.deleted.map(
                      ({ path }) => `Deleted since baseline: ${path}`,
                    ) ?? []),
                  ],
          failedSources,
          budget: {
            bytes: estimate.bytes,
            tokens: estimate.estimatedTokens,
            truncated: items.some((item) => item.contentStatus === "truncated"),
          },
          intelligence,
          ...(gitContext === undefined ? {} : { git: gitContext }),
          ...(options.instruction ? { instruction: options.instruction } : {}),
        });

        if (options.dryRun) {
          dependencies.writeData({
            schemaVersion: 1,
            selected: items.map((item) => item.path),
            redactions: bundle.redactionSummary,
            failedSources,
            ...(options.since === undefined
              ? {}
              : { baseline: options.since, deltaScope }),
          });
          dependencies.setExitCode(
            failedSources.length > 0 ? EXIT_CODES.partial : EXIT_CODES.success,
          );
          return;
        }

        const markdown = renderer.render(
          bundle,
          items,
          renderer.options.parse({}),
        );

        let copyStatus: string | undefined;
        if (options.copy) {
          const res = copyToClipboard(markdown);
          copyStatus = res.message;
        }

        if (options.output === "-") {
          dependencies.writeData(markdown);
        } else {
          let outputPath: string;
          try {
            outputPath = resolve(root, options.output);

            if (options.splitSize) {
              const maxBytes = parseByteSize(options.splitSize);
              const chunks = splitPackedOutput(markdown, outputPath, maxBytes);
              for (const chunk of chunks) {
                const handle = await open(chunk.path, "w");
                try {
                  await handle.writeFile(chunk.content, "utf8");
                } finally {
                  await handle.close();
                }
              }
            } else {
              const handle = await open(outputPath, "wx");
              try {
                await handle.writeFile(markdown, "utf8");
              } finally {
                await handle.close();
              }
            }
          } catch (error) {
            dependencies.writeDiagnostic(
              {
                schemaVersion: 1,
                code: "PACK.OUTPUT_WRITE_FAILED",
                severity: "error",
                source: "pack",
                message: "Output could not be created without overwriting.",
              },
              error,
            );
            dependencies.setExitCode(EXIT_CODES.environment);
            return;
          }

          dependencies.writeData({
            kind: "pack",
            output: outputPath,
            selected: items.map((item) => item.path),
            redactions: bundle.redactionSummary,
            ...(copyStatus ? { clipboard: copyStatus } : {}),
            ...(options.compress ? { compressed: true } : {}),
          });
        }

        dependencies.setExitCode(
          failedSources.length > 0 ? EXIT_CODES.partial : EXIT_CODES.success,
        );
      },
    );
}

export async function executeDualPack(
  root: string,
  environment: Readonly<Record<string, string | undefined>>,
  options: {
    compress?: boolean;
    removeComments?: boolean;
    removeEmptyLines?: boolean;
    lineNumbers?: boolean;
    instruction?: string;
  } = {},
): Promise<{
  kind: "dual-pack";
  outputs: string[];
  files: number;
  tokens: number;
}> {
  const acquisition = await acquireRepository(root, environment);
  let items = [...acquisition.items];
  const transformOptions = {
    ...(options.compress ? { compress: true } : {}),
    ...(options.removeComments ? { removeComments: true } : {}),
    ...(options.removeEmptyLines ? { removeEmptyLines: true } : {}),
    ...(options.lineNumbers ? { lineNumbers: true } : {}),
  };

  if (
    transformOptions.compress ||
    transformOptions.removeComments ||
    transformOptions.removeEmptyLines ||
    transformOptions.lineNumbers
  ) {
    items = items.map((item) => {
      if (!item.content) return item;
      const transformed = transformCodeContent(
        item.content,
        item.path,
        transformOptions,
      );
      return registerSecurityFilteredItem({
        ...item,
        content: transformed,
      });
    });
  }

  const intelligence = analyzeRepository(acquisition);
  const gitIdentity = await collectGitIdentity(root);
  const estimate = estimateBudget(items.map((i) => i.content ?? "").join("\n"));

  const bundle = createContextBundle({
    schemaVersion: 1,
    source: { kind: "repository", root: "." },
    revision: gitIdentity.head,
    items: items.map((item) => ({
      id: item.id,
      path: item.path,
      sha256: item.sha256,
      contentStatus: item.contentStatus,
      redacted: item.findings.length > 0,
    })),
    redactionSummary: {
      findings: items.reduce((sum, item) => sum + item.findings.length, 0),
      redactedItems: items.filter((item) => item.findings.length > 0).length,
      omittedItems: items.filter((item) => item.contentStatus === "omitted").length,
    },
    warnings: [],
    failedSources: [],
    budget: {
      bytes: estimate.bytes,
      tokens: estimate.estimatedTokens,
      truncated: items.some((item) => item.contentStatus === "truncated"),
    },
    intelligence,
    ...(options.instruction ? { instruction: options.instruction } : {}),
  });

  const mdContent = markdownRenderer.render(bundle, items, markdownRenderer.options.parse({}));
  const xmlContent = renderXml(bundle, items);

  const mdPath = resolve(root, "fuzit-pack.md");
  const xmlPath = resolve(root, "fuzit-pack.xml");

  const mdHandle = await open(mdPath, "w");
  try {
    await mdHandle.writeFile(mdContent, "utf8");
  } finally {
    await mdHandle.close();
  }

  const xmlHandle = await open(xmlPath, "w");
  try {
    await xmlHandle.writeFile(xmlContent, "utf8");
  } finally {
    await xmlHandle.close();
  }

  return {
    kind: "dual-pack",
    outputs: ["fuzit-pack.md", "fuzit-pack.xml"],
    files: items.length,
    tokens: bundle.budget.tokens,
  };
}

import { resolve } from "node:path";
import { readdir, readFile, stat } from "node:fs/promises";
import { parsePluginManifest, type PluginManifest } from "@fuzit/plugin-sdk";
import {
  validatePluginCompatibility,
  type CompatibilityValidationResult,
} from "@fuzit/plugin-host";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

export interface PluginCommandDependencies {
  readonly workingDirectory?: string;
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly json?: boolean;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic?: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

export interface DiscoveredPluginInfo {
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly path: string;
  readonly manifest: PluginManifest;
  readonly compatibility: CompatibilityValidationResult;
  readonly enabled: boolean;
}

export async function findPluginManifestPaths(dir: string): Promise<string[]> {
  const results: string[] = [];

  async function scan(currentDir: string, depth: number) {
    if (depth > 4) return;
    try {
      const entries = await readdir(currentDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.name === "node_modules" || entry.name.startsWith(".")) {
          continue;
        }
        const fullPath = resolve(currentDir, entry.name);
        if (entry.isDirectory()) {
          await scan(fullPath, depth + 1);
        } else if (entry.isFile() && entry.name === "fuzit-plugin.json") {
          results.push(fullPath);
        }
      }
    } catch {
      // Ignore unreadable directories
    }
  }

  await scan(dir, 0);
  return results.sort();
}

export async function discoverPlugins(
  rootDir: string,
  onInvalid?: (manifestPath: string, error: unknown) => void,
): Promise<DiscoveredPluginInfo[]> {
  const manifestPaths = await findPluginManifestPaths(rootDir);
  const plugins: DiscoveredPluginInfo[] = [];

  for (const manifestPath of manifestPaths) {
    try {
      const content = await readFile(manifestPath, "utf8");
      const rawJson = JSON.parse(content.replace(/^\uFEFF/, ""));
      const manifest = parsePluginManifest(rawJson);
      const compatibility = validatePluginCompatibility(manifest);
      plugins.push({
        id: manifest.id,
        name: manifest.name,
        version: manifest.version,
        path: manifestPath,
        manifest,
        compatibility,
        enabled: compatibility.compatible,
      });
    } catch (error) {
      onInvalid?.(manifestPath, error);
    }
  }

  return plugins;
}

export function registerPluginCommand(
  program: Command,
  dependencies: PluginCommandDependencies,
): void {
  const pluginCmd = program
    .command("plugin")
    .description("manage and audit local Fuzit plugins");

  pluginCmd
    .command("list")
    .description("list discovered local plugins")
    .option("--dir <path>", "directory to scan for plugins")
    .action(async (options: { dir?: string }) => {
      const targetDir = resolve(
        options.dir ?? dependencies.workingDirectory ?? process.cwd(),
      );
      let invalid = false;
      const plugins = await discoverPlugins(
        targetDir,
        (manifestPath, error) => {
          invalid = true;
          dependencies.writeDiagnostic?.(
            {
              schemaVersion: 1,
              code: "PLUGIN.INVALID_MANIFEST",
              severity: "error",
              source: "plugin",
              message: `Plugin manifest '${manifestPath}' is invalid: ${error instanceof Error ? error.message : String(error)}`,
            },
            error,
          );
        },
      );

      if (dependencies.json) {
        dependencies.writeData(
          plugins.map((p) => ({
            id: p.id,
            name: p.name,
            version: p.version,
            path: p.path,
            compatible: p.compatibility.compatible,
            enabled: p.enabled,
            capabilities: p.manifest.capabilities,
          })),
        );
      } else {
        if (plugins.length === 0) {
          dependencies.writeData("No plugins found.");
        } else {
          const lines = plugins.map(
            (p) =>
              `${p.id}@${p.version} - ${p.name} [${
                p.compatibility.compatible ? "Compatible" : "Incompatible"
              }] (${p.path})`,
          );
          dependencies.writeData(["Discovered plugins:", ...lines].join("\n"));
        }
      }
      dependencies.setExitCode(
        invalid ? EXIT_CODES.validation : EXIT_CODES.success,
      );
    });

  pluginCmd
    .command("inspect")
    .description("inspect manifest and permissions for a specific plugin")
    .argument(
      "<plugin-path-or-id>",
      "path to plugin directory/manifest or plugin ID",
    )
    .action(async (target: string) => {
      const rootDir = resolve(dependencies.workingDirectory ?? process.cwd());
      let manifestPath: string | undefined;

      if (target.endsWith("fuzit-plugin.json")) {
        manifestPath = resolve(rootDir, target);
      } else {
        // Try direct path or scan
        const targetAsPath = resolve(rootDir, target);
        try {
          const stats = await stat(targetAsPath);
          if (stats.isDirectory()) {
            manifestPath = resolve(targetAsPath, "fuzit-plugin.json");
          }
        } catch {
          // Find by ID
          const discovered = await discoverPlugins(rootDir);
          const found = discovered.find((p) => p.id === target);
          if (found) {
            manifestPath = found.path;
          }
        }
      }

      if (!manifestPath) {
        if (dependencies.writeDiagnostic) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: "PLUGIN.NOT_FOUND",
            severity: "error",
            source: "plugin",
            message: `Plugin '${target}' could not be located.`,
          });
        } else {
          dependencies.writeData(
            `Error: Plugin '${target}' could not be located.`,
          );
        }
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }

      try {
        const content = await readFile(manifestPath, "utf8");
        const rawJson = JSON.parse(content.replace(/^\uFEFF/, ""));
        const manifest = parsePluginManifest(rawJson);
        const compatibility = validatePluginCompatibility(manifest);
        const perms = manifest.permissions;
        const effectivePermissions = {
          filesystemReadPaths: perms?.filesystem?.readPaths ?? [],
          filesystemWritePaths: perms?.filesystem?.writePaths ?? [],
          networkAllowedHosts: perms?.network?.allowedHosts ?? [],
          shellAllowed: perms?.shell === true,
          persistenceAllowed: perms?.persistence === true,
        };

        const info = {
          manifest,
          compatibility,
          declaredPermissions: manifest.permissions ?? {},
          effectivePermissions,
        };

        if (dependencies.json) {
          dependencies.writeData(info);
        } else {
          dependencies.writeData(
            [
              `Plugin: ${manifest.name} (${manifest.id})`,
              `Version: ${manifest.version}`,
              `Protocol: ${manifest.protocol}`,
              `Required Fuzit Version: ${manifest.fuzitVersion}`,
              `Capabilities: ${manifest.capabilities.join(", ")}`,
              `Compatible: ${compatibility.compatible ? "Yes" : "No"}`,
              compatibility.reasons.length > 0
                ? `Incompatibility Reasons: ${compatibility.reasons.join("; ")}`
                : null,
              `Entry Point: ${manifest.entryPoint}`,
              `Permissions:`,
              `  Filesystem Read: ${
                info.effectivePermissions.filesystemReadPaths.length > 0
                  ? info.effectivePermissions.filesystemReadPaths.join(", ")
                  : "None"
              }`,
              `  Filesystem Write: ${
                info.effectivePermissions.filesystemWritePaths.length > 0
                  ? info.effectivePermissions.filesystemWritePaths.join(", ")
                  : "None"
              }`,
              `  Network Hosts: ${
                info.effectivePermissions.networkAllowedHosts.length > 0
                  ? info.effectivePermissions.networkAllowedHosts.join(", ")
                  : "None"
              }`,
              `  Shell Execution: ${
                info.effectivePermissions.shellAllowed ? "Allowed" : "Denied"
              }`,
              `  Persistence: ${
                info.effectivePermissions.persistenceAllowed
                  ? "Allowed"
                  : "Denied"
              }`,
            ]
              .filter(Boolean)
              .join("\n"),
          );
        }
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        if (dependencies.writeDiagnostic) {
          dependencies.writeDiagnostic(
            {
              schemaVersion: 1,
              code: "PLUGIN.INVALID_MANIFEST",
              severity: "error",
              source: "plugin",
              message: `Failed to inspect plugin: ${msg}`,
            },
            error,
          );
        } else {
          dependencies.writeData(`Error: Failed to inspect plugin: ${msg}`);
        }
        dependencies.setExitCode(EXIT_CODES.validation);
      }
    });

  pluginCmd
    .command("validate")
    .description("validate plugin manifest schema and compatibility")
    .argument("<manifest-path>", "path to fuzit-plugin.json manifest")
    .action(async (manifestPathArg: string) => {
      const fullPath = resolve(
        dependencies.workingDirectory ?? process.cwd(),
        manifestPathArg,
      );
      try {
        const content = await readFile(fullPath, "utf8");
        const rawJson = JSON.parse(content.replace(/^\uFEFF/, ""));
        const manifest = parsePluginManifest(rawJson);
        const compatibility = validatePluginCompatibility(manifest);

        if (dependencies.json) {
          dependencies.writeData({
            valid: compatibility.compatible,
            manifest,
            compatibility,
          });
        } else {
          if (compatibility.compatible) {
            dependencies.writeData(
              `PASS Plugin manifest at ${manifestPathArg} is valid and compatible.`,
            );
          } else {
            dependencies.writeData(
              `FAIL Plugin manifest at ${manifestPathArg} is incompatible:\n${compatibility.reasons
                .map((r: string) => `  - ${r}`)
                .join("\n")}`,
            );
          }
        }

        dependencies.setExitCode(
          compatibility.compatible ? EXIT_CODES.success : EXIT_CODES.validation,
        );
      } catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        if (dependencies.json) {
          dependencies.writeData({
            valid: false,
            error: msg,
          });
        } else {
          dependencies.writeData(
            `FAIL Invalid plugin manifest at ${manifestPathArg}: ${msg}`,
          );
        }
        dependencies.setExitCode(EXIT_CODES.validation);
      }
    });

  pluginCmd
    .command("enable")
    .description("report plugin permission audit before enablement")
    .argument("<plugin-id>", "plugin ID to enable")
    .action(async (pluginId: string) => {
      const rootDir = resolve(dependencies.workingDirectory ?? process.cwd());
      const plugins = await discoverPlugins(rootDir);
      const found = plugins.find((p) => p.id === pluginId);

      if (!found) {
        if (dependencies.writeDiagnostic) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: "PLUGIN.NOT_FOUND",
            severity: "error",
            source: "plugin",
            message: `Plugin '${pluginId}' not found.`,
          });
        } else {
          dependencies.writeData(`Error: Plugin '${pluginId}' not found.`);
        }
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }

      if (!found.compatibility.compatible) {
        if (dependencies.writeDiagnostic) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: "PLUGIN.INCOMPATIBLE",
            severity: "error",
            source: "plugin",
            message: `Cannot enable incompatible plugin '${pluginId}': ${found.compatibility.reasons.join("; ")}`,
          });
        } else {
          dependencies.writeData(
            `Error: Cannot enable incompatible plugin '${pluginId}': ${found.compatibility.reasons.join("; ")}`,
          );
        }
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }

      const perms = found.manifest.permissions;
      const effective = {
        filesystemReadPaths: perms?.filesystem?.readPaths ?? [],
        filesystemWritePaths: perms?.filesystem?.writePaths ?? [],
        networkAllowedHosts: perms?.network?.allowedHosts ?? [],
        shellAllowed: perms?.shell === true,
        persistenceAllowed: perms?.persistence === true,
      };

      const result = {
        id: found.id,
        name: found.name,
        enabled: true,
        grantedPermissions: effective,
      };

      if (dependencies.json) {
        dependencies.writeData(result);
      } else {
        dependencies.writeData(
          [
            `Plugin '${found.id}' enabled successfully.`,
            `Granted Permissions Audit:`,
            `  Filesystem Read: ${effective.filesystemReadPaths.length > 0 ? effective.filesystemReadPaths.join(", ") : "None"}`,
            `  Filesystem Write: ${effective.filesystemWritePaths.length > 0 ? effective.filesystemWritePaths.join(", ") : "None"}`,
            `  Network Hosts: ${effective.networkAllowedHosts.length > 0 ? effective.networkAllowedHosts.join(", ") : "None"}`,
            `  Shell Execution: ${effective.shellAllowed ? "Allowed" : "Denied"}`,
            `  Persistence: ${effective.persistenceAllowed ? "Allowed" : "Denied"}`,
          ].join("\n"),
        );
      }

      dependencies.setExitCode(EXIT_CODES.success);
    });

  pluginCmd
    .command("disable")
    .description("disable a local plugin")
    .argument("<plugin-id>", "plugin ID to disable")
    .action(async (pluginId: string) => {
      const rootDir = resolve(dependencies.workingDirectory ?? process.cwd());
      const plugins = await discoverPlugins(rootDir);
      const found = plugins.find((p) => p.id === pluginId);

      if (!found) {
        if (dependencies.writeDiagnostic) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: "PLUGIN.NOT_FOUND",
            severity: "error",
            source: "plugin",
            message: `Plugin '${pluginId}' not found.`,
          });
        } else {
          dependencies.writeData(`Error: Plugin '${pluginId}' not found.`);
        }
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }

      const result = {
        id: found.id,
        name: found.name,
        enabled: false,
      };

      if (dependencies.json) {
        dependencies.writeData(result);
      } else {
        dependencies.writeData(`Plugin '${found.id}' has been disabled.`);
      }

      dependencies.setExitCode(EXIT_CODES.success);
    });

  pluginCmd
    .command("doctor")
    .description(
      "check local plugin environment readiness and security diagnostics",
    )
    .action(async () => {
      const rootDir = resolve(dependencies.workingDirectory ?? process.cwd());
      const plugins = await discoverPlugins(rootDir);

      const checks = plugins.map((p) => {
        if (!p.compatibility.compatible) {
          return {
            id: p.id,
            status: "fail",
            message: `Incompatible: ${p.compatibility.reasons.join("; ")}`,
          };
        }
        const hasShell = p.manifest.permissions?.shell === true;
        if (hasShell) {
          return {
            id: p.id,
            status: "warning",
            message: `Requests dangerous permission: shell execution`,
          };
        }
        return {
          id: p.id,
          status: "pass",
          message: `Plugin manifest and permissions are healthy`,
        };
      });

      const hasFailures = checks.some((c) => c.status === "fail");
      const report = {
        status: hasFailures ? "issues_detected" : "ready",
        totalPlugins: plugins.length,
        checks,
      };

      if (dependencies.json) {
        dependencies.writeData(report);
      } else {
        const lines = checks.map(
          (c) => `${c.status.toUpperCase()} ${c.id}: ${c.message}`,
        );
        dependencies.writeData(
          [
            `Fuzit plugin doctor (${plugins.length} plugins audited)`,
            plugins.length === 0 ? "No local plugins found." : lines.join("\n"),
          ].join("\n"),
        );
      }

      dependencies.setExitCode(
        hasFailures ? EXIT_CODES.environment : EXIT_CODES.success,
      );
    });

  pluginCmd
    .command("mcp")
    .description("inspect or generate Model Context Protocol server configuration")
    .action(async () => {
      const config = {
        mcpServers: {
          fuzit: {
            command: "fuzit",
            args: ["plugin", "mcp"],
            env: { FUZIT_CACHE_HOME: ".cache" },
          },
        },
        tools: [
          { name: "fuzit_pack", description: "Create security-filtered context bundle" },
          { name: "fuzit_graph", description: "Query local repository context graph" },
        ],
      };

      if (dependencies.json) {
        dependencies.writeData(config);
      } else {
        dependencies.writeData(
          [
            "Fuzit · Model Context Protocol (MCP) Configuration",
            "Server Command: fuzit plugin mcp",
            "Supported Tools: fuzit_pack, fuzit_graph",
            "MCP Config Schema: .vscode/mcp.json",
          ].join("\n"),
        );
      }
      dependencies.setExitCode(EXIT_CODES.success);
    });
}

import { BUILT_IN_PROFILES } from "@fuzit/profiles";
import type { Command } from "commander";
export function registerProfileCommand(
  program: Command,
  writeData: (value: unknown) => void,
) {
  const profile = program
    .command("profile")
    .description("display built-in profiles")
    .action(() => writeData(BUILT_IN_PROFILES));

  profile
    .command("list")
    .option("--json")
    .action(() => writeData(BUILT_IN_PROFILES));
}

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { runPrReview } from "@fuzit/core";
import {
  parseGitHubUrl,
  parseOwnerRepoHash,
  parseNumericWithRepo,
} from "@fuzit/provider-github";
import { inferRemoteFromGitConfig, runGit } from "@fuzit/git";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import { getProfile } from "@fuzit/profiles";
import type { Command } from "commander";

export function registerReviewCommand(
  program: Command,
  dependencies: {
    readonly currentDirectory: string;
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
    readonly setExitCode: (code: ExitCode) => void;
  },
): void {
  program
    .command("review")
    .description("review a GitHub pull request")
    .argument("<source>", "PR URL or OWNER/REPO#NUMBER")
    .option("--task <task>", "override default code-review task")
    .option("--profile <profile>", "profile to use", "code-review")
    .option("--budget-tokens <tokens>", "token budget", "12000")
    .option("--format <format>", "output format", "markdown")
    .option("--output <path>", "output path or '-' for stdout", "-")
    .action(
      async (
        sourceArg: string,
        options: {
          task?: string;
          profile: string;
          budgetTokens: string;
          format: string;
          output: string;
        },
      ) => {
        try {
          getProfile(options.profile);
          let prRef;
          if (
            sourceArg.startsWith("http://") ||
            sourceArg.startsWith("https://")
          ) {
            const parsed = parseGitHubUrl(sourceArg);
            if (!parsed.ok || parsed.ref.kind !== "github-pull-request") {
              throw new Error(
                `invalid PR URL '${sourceArg}': ${parsed.ok ? "not a PR URL" : parsed.reason}`,
              );
            }
            prRef = parsed.ref;
          } else {
            const parsed = parseOwnerRepoHash(sourceArg, "pull-request");
            if (!parsed.ok) {
              throw new Error(
                `invalid PR reference '${sourceArg}': ${parsed.reason}`,
              );
            }
            prRef = parsed.ref;
          }

          const result = await runPrReview({
            prRef,
            ...(options.task ? { task: options.task } : {}),
            profileName: options.profile,
            environment: dependencies.environment,
          });

          if (
            !Number.isInteger(Number(options.budgetTokens)) ||
            Number(options.budgetTokens) <= 0
          )
            throw new Error("budget tokens must be a positive integer");
          if (!["markdown", "json", "text"].includes(options.format))
            throw new Error(`unsupported review format '${options.format}'`);
          const rendered =
            options.format === "json"
              ? `${JSON.stringify(result, null, 2)}\n`
              : `${result.summary}\n`;

          if (options.output === "-") {
            dependencies.writeData(
              options.format === "json"
                ? result
                : {
                    kind: "review",
                    repository: result.targetRepo,
                    prNumber: result.prNumber,
                    title: result.title,
                    state: result.state,
                    author: result.author,
                    baseRef: result.baseRef,
                    headRef: result.headRef,
                    findings: result.findings,
                    summary: result.summary,
                  },
            );
          } else {
            const outputPath = resolve(
              dependencies.currentDirectory,
              options.output,
            );
            await mkdir(dirname(outputPath), { recursive: true });
            await writeFile(outputPath, rendered, {
              encoding: "utf8",
              flag: "wx",
            });
            dependencies.writeData({
              kind: "review",
              output: outputPath,
              repository: result.targetRepo,
              prNumber: result.prNumber,
              findings: result.findings,
            });
          }
        } catch (error) {
          dependencies.writeData({
            error: error instanceof Error ? error.message : String(error),
          });
          dependencies.setExitCode(EXIT_CODES.validation);
        }
      },
    );
}

export function registerPrCommand(
  program: Command,
  dependencies: {
    readonly currentDirectory: string;
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
    readonly setExitCode: (code: ExitCode) => void;
  },
): void {
  program
    .command("pr")
    .description("review pull request shorthand")
    .argument("<source>", "PR number, OWNER/REPO#NUMBER, or PR URL")
    .option("--repo <repo>", "target repository in OWNER/REPO format")
    .option("--task <task>", "override default task")
    .option("--profile <profile>", "profile", "code-review")
    .option("--budget-tokens <tokens>", "token budget", "12000")
    .option("--format <format>", "output format", "markdown")
    .option("--output <path>", "output path or '-' for stdout", "-")
    .action(
      async (
        sourceArg: string,
        options: {
          repo?: string;
          task?: string;
          profile: string;
          budgetTokens: string;
          format: string;
          output: string;
        },
      ) => {
        try {
          getProfile(options.profile);
          let prRef;
          if (
            sourceArg.startsWith("http://") ||
            sourceArg.startsWith("https://")
          ) {
            const parsed = parseGitHubUrl(sourceArg);
            if (!parsed.ok || parsed.ref.kind !== "github-pull-request") {
              throw new Error(`invalid PR URL '${sourceArg}'`);
            }
            prRef = parsed.ref;
          } else if (sourceArg.includes("#")) {
            const parsed = parseOwnerRepoHash(sourceArg, "pull-request");
            if (!parsed.ok) throw new Error(parsed.reason);
            prRef = parsed.ref;
          } else if (/^\d+$/.test(sourceArg)) {
            if (options.repo) {
              const parsed = parseNumericWithRepo(
                sourceArg,
                options.repo,
                "pull-request",
              );
              if (!parsed.ok) throw new Error(parsed.reason);
              prRef = parsed.ref;
            } else {
              // infer from local clone remotes
              const remote = await runGit(["remote", "get-url", "origin"], {
                cwd: dependencies.currentDirectory,
              });
              const inferred = remote.ok
                ? inferRemoteFromGitConfig([
                    { name: "origin", url: remote.stdout.trim() },
                  ])
                : null;
              if (!inferred)
                throw new Error(
                  "Could not infer repository from local clone; pass --repo OWNER/REPO",
                );
              const parsed = parseNumericWithRepo(
                sourceArg,
                `${inferred.owner}/${inferred.repo}`,
                "pull-request",
              );
              if (!parsed.ok) throw new Error(parsed.reason);
              prRef = parsed.ref;
            }
          } else {
            throw new Error(`invalid PR argument '${sourceArg}'`);
          }

          const result = await runPrReview({
            prRef,
            ...(options.task ? { task: options.task } : {}),
            profileName: options.profile,
            environment: dependencies.environment,
          });
          if (
            !Number.isInteger(Number(options.budgetTokens)) ||
            Number(options.budgetTokens) <= 0
          )
            throw new Error("budget tokens must be a positive integer");
          if (!["markdown", "json", "text"].includes(options.format))
            throw new Error(`unsupported review format '${options.format}'`);
          const rendered =
            options.format === "json"
              ? `${JSON.stringify(result, null, 2)}\n`
              : `${result.summary}\n`;

          if (options.output === "-") {
            dependencies.writeData(
              options.format === "json"
                ? result
                : {
                    kind: "review",
                    repository: result.targetRepo,
                    prNumber: result.prNumber,
                    authenticated: Boolean(
                      dependencies.environment.FUZIT_GITHUB_TOKEN ||
                      dependencies.environment.GH_TOKEN,
                    ),
                    profile: options.profile,
                    budgetTokens: Number(options.budgetTokens),
                    findings: result.findings,
                    source: sourceArg,
                    summary: result.summary,
                  },
            );
          } else {
            const outputPath = resolve(
              dependencies.currentDirectory,
              options.output,
            );
            await mkdir(dirname(outputPath), { recursive: true });
            await writeFile(outputPath, rendered, {
              encoding: "utf8",
              flag: "wx",
            });
            dependencies.writeData({
              kind: "review",
              output: outputPath,
              repository: result.targetRepo,
              prNumber: result.prNumber,
              findings: result.findings,
            });
          }
        } catch (error) {
          dependencies.writeData({
            error: error instanceof Error ? error.message : String(error),
          });
          dependencies.setExitCode(EXIT_CODES.validation);
        }
      },
    );
}

import {
  createFileContextItem,
  normalizeRepositoryRelativePath,
} from "@fuzit/core";
import { loadEffectiveConfig } from "@fuzit/config";
import {
  canonicalizeRepositoryRootList,
  RepositoryRootError,
  resolveRepositoryRoots,
} from "@fuzit/discovery";
import {
  evaluateBuiltInExclusion,
  loadGitignoreRulesForPath,
  loadFuzitignoreRulesForPath,
  evaluateIgnorePrecedence,
  type ExplicitPathRule,
  classifyFile,
  readTextContent,
  traverseDirectory,
} from "@fuzit/scanner";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";
import { stat } from "node:fs/promises";
import { join, resolve } from "node:path";

interface ScanCommandDependencies {
  readonly currentDirectory: string;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

type ScanMode =
  | "explainPath"
  | "paths"
  | "metadata"
  | "items"
  | "content"
  | "summary"
  | "listRoots";

interface ScanOptions {
  readonly explainPath?: string;
  readonly root?: string;
  readonly listRoots?: boolean;
  readonly paths?: boolean;
  readonly include: string[];
  readonly exclude: string[];
  readonly metadata?: boolean;
  readonly items?: boolean;
  readonly content?: boolean;
  readonly summary?: boolean;
}

const scanModeFlags: ReadonlyArray<
  readonly [ScanMode, keyof ScanOptions, string]
> = [
  ["explainPath", "explainPath", "--explain-path"],
  ["paths", "paths", "--paths"],
  ["metadata", "metadata", "--metadata"],
  ["items", "items", "--items"],
  ["content", "content", "--content"],
  ["summary", "summary", "--summary"],
  ["listRoots", "listRoots", "--list-roots"],
];

function resolveScanMode(options: ScanOptions):
  | { readonly mode: ScanMode; readonly conflict?: undefined }
  | {
      readonly mode?: undefined;
      readonly conflict: readonly string[];
    } {
  const selected = scanModeFlags.filter(([, property]) =>
    property === "explainPath"
      ? options.explainPath !== undefined
      : options[property] === true,
  );
  if (selected.length > 1)
    return { conflict: selected.map(([, , flag]) => flag) };
  return { mode: selected[0]?.[0] ?? "summary" };
}

function collect(value: string, previous: string[]): string[] {
  return [...previous, value];
}

function explicitRules(
  includes: readonly string[],
  excludes: readonly string[],
  source: string,
): ExplicitPathRule[] {
  return [
    ...includes.map((pattern) => ({
      pattern,
      action: "include" as const,
      reason: `${source} include`,
    })),
    ...excludes.map((pattern) => ({
      pattern,
      action: "exclude" as const,
      reason: `${source} exclude`,
    })),
  ];
}

export function registerScanCommand(
  program: Command,
  dependencies: ScanCommandDependencies,
): void {
  program
    .command("scan")
    .description("inspect repository discovery metadata")
    .option("--root <path>", "select a repository path")
    .option("--list-roots", "list the selected and nested repository roots")
    .option("--paths", "stream stable repository paths")
    .option("--explain-path <path>", "explain the built-in path decision")
    .option("--include <pattern>", "include a path pattern", collect, [])
    .option("--exclude <pattern>", "exclude a path pattern", collect, [])
    .option("--metadata", "stream normalized file metadata")
    .option("--items", "stream normalized file context items")
    .option("--content", "stream bounded text content")
    .option("--summary", "emit a structured scan summary")
    .action(async (options: ScanOptions) => {
      const selection = resolveScanMode(options);
      if (selection.conflict) {
        dependencies.writeDiagnostic({
          schemaVersion: 1,
          code: "SCAN.MODE_CONFLICT",
          severity: "error",
          source: "scan",
          message: `Scan modes cannot be combined: ${selection.conflict.join(", ")}.`,
        });
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }
      const mode = selection.mode;
      const root = resolve(
        dependencies.currentDirectory,
        options.root ?? dependencies.currentDirectory,
      );
      try {
        if (!(await stat(root)).isDirectory())
          throw new Error("Path is not a directory.");
      } catch {
        dependencies.writeDiagnostic({
          schemaVersion: 1,
          code: "SCAN.INVALID_ROOT",
          severity: "error",
          source: "scan",
          message: `Repository root does not exist or is not a directory: ${root}`,
        });
        dependencies.setExitCode(EXIT_CODES.validation);
        return;
      }
      const config = await loadEffectiveConfig({
        repositoryRoot: root,
        environment: {},
      });
      const cliRules = explicitRules(options.include, options.exclude, "CLI");
      const projectRules = explicitRules(
        config.values.include,
        config.values.exclude,
        "project configuration",
      );
      if (mode === "explainPath") {
        const path = normalizeRepositoryRelativePath(options.explainPath!);
        const builtIn = evaluateBuiltInExclusion(path);
        if (builtIn.rule !== null) {
          dependencies.writeData(builtIn);
        } else {
          dependencies.writeData(
            evaluateIgnorePrecedence({
              path,
              isDirectory: false,
              cliRules,
              projectRules,
              fuzitignoreRules: await loadFuzitignoreRulesForPath(root),
              gitignoreRules: await loadGitignoreRulesForPath(root, path),
            }),
          );
        }
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      if (mode === "paths") {
        for await (const entry of traverseDirectory(root, {
          cliRules,
          projectRules,
        })) {
          dependencies.writeData(entry.path);
        }
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      if (mode === "metadata") {
        for await (const entry of traverseDirectory(root, {
          cliRules,
          projectRules,
        })) {
          if (entry.kind === "directory") continue;
          dependencies.writeData(
            await classifyFile(
              join(root, ...entry.path.split("/")),
              entry.path,
            ),
          );
        }
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      if (mode === "items") {
        for await (const entry of traverseDirectory(root, {
          cliRules,
          projectRules,
        })) {
          if (entry.kind !== "file") continue;
          const absolutePath = join(root, ...entry.path.split("/"));
          dependencies.writeData(
            createFileContextItem(
              await classifyFile(absolutePath, entry.path),
              await readTextContent(absolutePath),
            ),
          );
        }
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      if (mode === "content") {
        for await (const entry of traverseDirectory(root, {
          cliRules,
          projectRules,
        })) {
          if (entry.kind !== "file") continue;
          dependencies.writeData({
            path: entry.path,
            ...(await readTextContent(join(root, ...entry.path.split("/")))),
          });
        }
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      if (mode === "summary") {
        const counts = { files: 0, directories: 0, symlinks: 0 };
        for await (const entry of traverseDirectory(root, {
          cliRules,
          projectRules,
        })) {
          if (entry.kind === "file") counts.files += 1;
          else if (entry.kind === "directory") counts.directories += 1;
          else counts.symlinks += 1;
        }
        dependencies.writeData({
          schemaVersion: 1,
          root,
          counts,
          status: "complete",
          nextSteps: ["fuzit pack --root .", "fuzit graph build --root . --output .fuzit-graph.json"],
        });
        dependencies.setExitCode(EXIT_CODES.success);
        return;
      }

      try {
        const resolution = await resolveRepositoryRoots({
          currentDirectory: dependencies.currentDirectory,
          ...(options.root === undefined ? {} : { explicitPath: options.root }),
        });
        dependencies.writeData(canonicalizeRepositoryRootList(resolution));
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        if (error instanceof RepositoryRootError) {
          dependencies.writeDiagnostic({
            schemaVersion: 1,
            code: error.code,
            severity: "error",
            source: "discovery",
            message: error.message,
          });
          dependencies.setExitCode(EXIT_CODES.validation);
          return;
        }
        throw error;
      }
    });
}

import { createServer } from "node:http";
import { resolve } from "node:path";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";
import { acquireRepository, analyzeRepository } from "../../application/repository.js";

interface ServeDependencies {
  readonly currentDirectory: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (code: ExitCode) => void;
}

export function registerServeCommand(
  program: Command,
  dependencies: ServeDependencies,
): void {
  program
    .command("serve [port]")
    .description("Start local RAG / Context REST API server over the repository")
    .option("--root <path>", "Repository root", ".")
    .option("--host <host>", "Host address to bind", "127.0.0.1")
    .action(async (portArg: string | undefined, options: { root: string; host: string }) => {
      const port = parseInt(portArg ?? "3000", 10);
      const root = resolve(dependencies.currentDirectory, options.root);

      const server = createServer(async (req, res) => {
        const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

        res.setHeader("Content-Type", "application/json");
        res.setHeader("Access-Control-Allow-Origin", "*");
        res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
        res.setHeader("Access-Control-Allow-Headers", "Content-Type");

        if (req.method === "OPTIONS") {
          res.writeHead(204);
          res.end();
          return;
        }

        if (url.pathname === "/" || url.pathname === "/health") {
          res.writeHead(200);
          res.end(
            JSON.stringify({
              status: "ok",
              service: "fuzit-rag",
              repository: root,
            }),
          );
          return;
        }

        if (url.pathname === "/api/context" || url.pathname === "/context") {
          try {
            let body = "";
            if (req.method === "POST") {
              for await (const chunk of req) body += chunk;
            }
            const query = url.searchParams.get("q") ?? (body ? JSON.parse(body).query : "");

            const acquisition = await acquireRepository(root, dependencies.environment);
            const intelligence = analyzeRepository(acquisition);

            let items = acquisition.items;
            if (query) {
              const q = String(query).toLowerCase();
              items = items.filter(
                (item) =>
                  item.path.toLowerCase().includes(q) ||
                  (item.content && item.content.toLowerCase().includes(q)),
              );
            }

            res.writeHead(200);
            res.end(
              JSON.stringify({
                status: "success",
                query,
                repository: root,
                filesCount: items.length,
                languages: intelligence.languages,
                items: items.map((i) => ({
                  path: i.path,
                  sha256: i.sha256,
                  content: i.content,
                })),
              }),
            );
          } catch (error) {
            res.writeHead(500);
            res.end(
              JSON.stringify({
                status: "error",
                message: error instanceof Error ? error.message : String(error),
              }),
            );
          }
          return;
        }

        res.writeHead(404);
        res.end(JSON.stringify({ status: "not_found" }));
      });

      server.listen(port, options.host, () => {
        dependencies.writeData({
          kind: "serve",
          status: "running",
          host: options.host,
          port,
          root,
          endpoint: `http://${options.host}:${port}/api/context`,
        });
      });
    });
}

import { resolve } from "node:path";

import {
  createSnapshot,
  listSnapshots,
  readSnapshot,
  saveSnapshot,
} from "@fuzit/snapshots";
import type { Command } from "commander";

import {
  acquireRepository,
  repositorySnapshotIdentity,
} from "../../application/repository.js";

export function registerSnapshotCommand(
  program: Command,
  runtime: {
    readonly environment: Readonly<Record<string, string | undefined>>;
    readonly writeData: (value: unknown) => void;
  },
): void {
  const command = program.command("snapshot").description("Manage snapshots.");
  const directory = () =>
    resolve(runtime.environment.FUZIT_CACHE_HOME ?? ".cache", "snapshots");

  command
    .command("create")
    .requiredOption("--root <path>")
    .option("--json")
    .action(async ({ root }: { root: string }) => {
      const acquisition = await acquireRepository(root, runtime.environment);
      const identity = await repositorySnapshotIdentity(acquisition);
      const snapshot = createSnapshot({
        repositoryRevision: identity.revision,
        dirty: identity.dirty,
        configHash: acquisition.configHash,
        fileFingerprints: acquisition.items.map(({ path, sha256 }) => ({
          path,
          sha256,
        })),
        bundleIdentityInputs: [
          "scanner:1",
          "security-policy:1",
          "snapshot-schema:1",
        ],
        complete: acquisition.complete,
        diagnostics: acquisition.omissions
          .filter(({ failure }) => failure)
          .map(({ path, reason }) => `${path}: ${reason}`),
      });
      await saveSnapshot(directory(), snapshot);
      runtime.writeData(snapshot);
    });
  command
    .command("list")
    .action(async () => runtime.writeData(await listSnapshots(directory())));
  command
    .command("show")
    .argument("<id>")
    .action(async (id: string) =>
      runtime.writeData(await readSnapshot(directory(), id)),
    );
}

import { createSupportBundlePreview } from "@fuzit/security";
import type { Command } from "commander";

export function registerSupportCommand(
