import { resolve } from "node:path";
import { BUILT_IN_PROFILES } from "@fuzit/profiles";
import { EXIT_CODES, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";
import { acquireRepository, analyzeRepository } from "../../application/repository.js";

interface UiDependencies {
  readonly currentDirectory: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly setExitCode: (code: ExitCode) => void;
}

export function registerUiCommand(
  program: Command,
  dependencies: UiDependencies,
): void {
  program
    .command("ui")
    .alias("interactive")
    .description("Interactive CLI dashboard and context bundle inspector")
    .option("--root <path>", "Repository root path", ".")
    .action(async (options: { root: string }) => {
      try {
        const root = resolve(dependencies.currentDirectory, options.root);
        const acquisition = await acquireRepository(root, dependencies.environment);
        const intelligence = analyzeRepository(acquisition);

        dependencies.writeData({
          kind: "ui-dashboard",
          repository: root,
          totalFiles: acquisition.items.length,
          omissions: acquisition.omissions.length,
          languages: intelligence.languages,
          packages: intelligence.packages,
          frameworks: intelligence.frameworks,
          profilesCount: BUILT_IN_PROFILES.length,
        });
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        dependencies.writeData({
          error: error instanceof Error ? error.message : String(error),
        });
        dependencies.setExitCode(EXIT_CODES.internal);
      }
    });
}

import { resolve } from "node:path";
import {
  createIndexIdentitySet,
  createRepositoryId,
  getLocalIndexPath,
  openLocalIndex,
  readLocalIndexSemanticState,
  writeLocalIndexSemanticState,
  type LocalIndexSemanticState,
} from "@fuzit/index";
import {
  LOCAL_INDEX_SCHEMA_VERSION,
  type Diagnostic,
  type ExitCode,
} from "@fuzit/schemas";
import { WatcherDaemon } from "@fuzit/watcher";
import { Command } from "commander";
import {
  acquireRepository,
  acquisitionContentHash,
  repositoryIdentity,
} from "../../application/repository.js";
import { executeDualPack } from "../pack/register.js";

const versions = {
  scannerVersion: "1",
  parserVersion: "1",
  securityPolicyVersion: "1",
  schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
} as const;

const componentIdentities = {
  parser: { name: "fuzit-built-in-parsers", version: versions.parserVersion },
  analysis: { name: "fuzit-analysis", version: "1" },
  graph: { name: "fuzit-context-graph", schemaVersion: 1 },
  schema: { name: "fuzit-incremental-index", schemaVersion: 1 },
  securityPolicy: {
    name: "fuzit-security-policy",
    version: versions.securityPolicyVersion,
  },
} as const;

interface WatchCommandDependencies {
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

export function registerWatchCommand(
  program: Command,
  dependencies: WatchCommandDependencies,
): void {
  program
    .command("watch")
    .description("Watch repository for changes and update local index")
    .option("--root <path>", "Repository root path", ".")
    .option("--debounce-ms <ms>", "Debounce window in milliseconds", "100")
    .option("--json", "Emit status in machine-readable JSON format", false)
    .option("--quiet", "Suppress non-essential log output", false)
    .option("--once", "Process one update batch and exit immediately", false)
    .option("--foreground", "Run in foreground process", false)
    .option("--pack", "Automatically sync fuzit-pack.md and fuzit-pack.xml on file changes", false)
    .option("--reconcile", "Trigger explicit canonical reconciliation", false)
    .option("--status", "Report current watch status and exit", false)
    .action(async (options) => {
      const repositoryRoot = resolve(options.root);
      const identity = await repositoryIdentity(repositoryRoot);
      const repoId = createRepositoryId(identity.fingerprint);

      const cacheHome = resolve(
        process.env.FUZIT_CACHE_HOME ?? process.env.LOCALAPPDATA ?? ".cache",
      );

      const indexPath = getLocalIndexPath({
        cacheHome,
        repositoryFingerprint: identity.fingerprint,
      });

      await openLocalIndex(indexPath, repoId);

      let semanticState: LocalIndexSemanticState | undefined =
        await readLocalIndexSemanticState(indexPath);

      if (!semanticState) {
        const acquisition = await acquireRepository(
          repositoryRoot,
          process.env,
        );
        const contentHash = acquisitionContentHash(acquisition);

        semanticState = {
          ...versions,
          contentHash,
          configHash: acquisition.configHash,
          identities: createIndexIdentitySet({
            effectiveConfiguration: acquisition.configHash,
            ignorePolicy: acquisition.configHash,
            securityPolicy: componentIdentities.securityPolicy,
            parser: componentIdentities.parser,
            analysis: componentIdentities.analysis,
            graph: componentIdentities.graph,
            schema: componentIdentities.schema,
          }),
        };
        await writeLocalIndexSemanticState(indexPath, semanticState);
      }

      const daemon = new WatcherDaemon({
        repositoryRoot,
        indexPath,
        repositoryId: repoId,
        semanticState,
        debounceMs: parseInt(options.debounceMs, 10),
      });

      if (options.status) {
        dependencies.writeData(daemon.status);
        return;
      }

      await daemon.start();

      if (options.once) {
        await daemon.processPendingBatch("batch-cli-once");
        if (options.pack) {
          await executeDualPack(repositoryRoot, process.env);
        }
        await daemon.stop();
        dependencies.writeData({ status: "complete", mode: "once", ...(options.pack ? { packSynced: true } : {}) });
        return;
      }

      if (options.foreground) {
        if (!options.quiet) {
          dependencies.writeData(
            `Watching repository in foreground: ${repositoryRoot}\n`,
          );
        }
        await new Promise<void>((resolveSignal) => {
          const shutdown = async () => {
            await daemon.stop();
            resolveSignal();
          };
          process.once("SIGINT", shutdown);
          process.once("SIGTERM", shutdown);
        });
      } else {
        await daemon.stop();
      }
    });
}

import {
  ConfigLoadError,
  loadEffectiveConfig,
  type ConfigOverrides,
} from "@fuzit/config";
import { EXIT_CODES, type Diagnostic, type ExitCode } from "@fuzit/schemas";
import type { Command } from "commander";

interface ConfigCommandDependencies {
  readonly repositoryRoot: string;
  readonly environment: Readonly<Record<string, string | undefined>>;
  readonly writeData: (value: unknown) => void;
  readonly writeDiagnostic: (diagnostic: Diagnostic, cause?: unknown) => void;
  readonly setExitCode: (exitCode: ExitCode) => void;
}

function configDiagnostic(error: ConfigLoadError): Diagnostic {
  const details =
    error.issues.length === 0 ? "" : ` ${error.issues.join("; ")}`;

  return {
    schemaVersion: 1,
    code: error.code,
    severity: "error",
    source: "config",
    message: `${error.message}${details}`,
  };
}

function positiveInteger(value: string): number {
  return Number(value);
}

export function registerConfigCommand(
  program: Command,
  dependencies: ConfigCommandDependencies,
): void {
  const config = program
    .command("config")
    .description("inspect effective configuration")
    .action(async () => {
      try {
        const effectiveConfig = await loadEffectiveConfig({
          repositoryRoot: dependencies.repositoryRoot,
          environment: dependencies.environment,
          cli: {},
        });
        dependencies.writeData(effectiveConfig);
        dependencies.setExitCode(EXIT_CODES.success);
      } catch (error) {
        if (error instanceof ConfigLoadError) {
          dependencies.writeDiagnostic(configDiagnostic(error), error);
          dependencies.setExitCode(EXIT_CODES.validation);
          return;
        }
        throw error;
      }
    });

  config
    .command("show")
    .description("show effective configuration and provenance")
    .option("--output-format <format>", "override the output format")
    .option(
      "--max-files <count>",
      "override the maximum file count",
      positiveInteger,
    )
    .option("--diagnostic-level <level>", "override the diagnostic level")
    .action(
      async (options: {
        outputFormat?: string;
        maxFiles?: number;
        diagnosticLevel?: string;
      }) => {
        const cli: ConfigOverrides = {
          ...(options.outputFormat === undefined
            ? {}
            : { outputFormat: options.outputFormat }),
          ...(options.maxFiles === undefined
            ? {}
            : { maxFiles: options.maxFiles }),
          ...(options.diagnosticLevel === undefined
            ? {}
            : { diagnosticLevel: options.diagnosticLevel }),
        };

        try {
          const effectiveConfig = await loadEffectiveConfig({
            repositoryRoot: dependencies.repositoryRoot,
            environment: dependencies.environment,
            cli,
          });
          dependencies.writeData(effectiveConfig);
          dependencies.setExitCode(EXIT_CODES.success);
        } catch (error) {
          if (error instanceof ConfigLoadError) {
            dependencies.writeDiagnostic(configDiagnostic(error), error);
            dependencies.setExitCode(EXIT_CODES.validation);
            return;
          }

          throw error;
        }
      },
    );
}

import { CLI_USAGE_ERROR_EXIT_CODE, CLI_VERSION, runCli } from "./cli.js";

export { CLI_USAGE_ERROR_EXIT_CODE, CLI_VERSION, runCli };

export async function runCliProcess(
  arguments_: readonly string[],
): Promise<number> {
  return runCli(arguments_, {
    writeOut: (value) => process.stdout.write(value),
    writeErr: (value) => process.stderr.write(value),
  });
}

export interface CliPackageBoundary {
  readonly packageName: "@fuzit/cli";
}

import { execSync } from "node:child_process";

export interface ClipboardResult {
  readonly ok: boolean;
  readonly message: string;
}

/**
 * Copy text to the OS clipboard cross-platform (clip on Windows, pbcopy on macOS, xclip/wl-copy on Linux).
 */
export function copyToClipboard(text: string): ClipboardResult {
  try {
    const platform = process.platform;
    if (platform === "win32") {
      execSync("clip", { input: text, encoding: "utf8", stdio: ["pipe", "ignore", "ignore"] });
      return { ok: true, message: "Copied to clipboard." };
    }
    if (platform === "darwin") {
      execSync("pbcopy", { input: text, encoding: "utf8", stdio: ["pipe", "ignore", "ignore"] });
      return { ok: true, message: "Copied to clipboard." };
    }
    if (platform === "linux") {
      try {
        execSync("wl-copy", { input: text, encoding: "utf8", stdio: ["pipe", "ignore", "ignore"] });
        return { ok: true, message: "Copied to clipboard (wl-clipboard)." };
      } catch {
        execSync("xclip -selection clipboard", { input: text, encoding: "utf8", stdio: ["pipe", "ignore", "ignore"] });
        return { ok: true, message: "Copied to clipboard (xclip)." };
      }
    }
    return { ok: false, message: `Clipboard copy not supported on platform '${platform}'.` };
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    return { ok: false, message: `Clipboard copy failed: ${msg}` };
  }
}

type MaybeRecord = Record<string, unknown>;

export interface Theme {
  readonly color: boolean;
  readonly unicode: boolean;
}

export function resolveTheme(overrides?: Partial<Theme>): Theme {
  const color =
    overrides?.color !== undefined
      ? overrides.color
      : process.env.NO_COLOR === undefined && Boolean(process.stdout.isTTY);
  const unicode =
    overrides?.unicode !== undefined
      ? overrides.unicode
      : Boolean(process.stdout.isTTY);
  return { color, unicode };
}

const ANSI = {
  reset: "\u001B[0m",
  bold: "\u001B[1m",
  dim: "\u001B[2m",
  red: "\u001B[31m",
  green: "\u001B[32m",
  yellow: "\u001B[33m",
  cyan: "\u001B[36m",
  blue: "\u001B[34m",
};

// Maximum visible character width for a box body line.
// Keeps output safe on 80-column terminals; borders add 4 chars.
const MAX_BOX_INNER_WIDTH = 76;

function paint(theme: Theme, code: string, value: string): string {
  return theme.color ? `${code}${value}${ANSI.reset}` : value;
}

function icon(theme: Theme, name: "success" | "error" | "warning" | "info" | "next") {
  if (!theme.unicode) {
    return { success: "OK", error: "ERR", warning: "WARN", info: "INFO", next: "->" }[name];
  }
  return { success: "✓", error: "✖", warning: "⚠", info: "ℹ", next: "→" }[name];
}

/** Truncate a string to at most `max` visible characters, adding "…" if cut. */
function truncate(s: string, max: number): string {
  if (s.length <= max) return s;
  return `${s.slice(0, max - 1)}…`;
}

export function box(theme: Theme, title: string, body: string[]): string {
  const cappedTitle = truncate(title, MAX_BOX_INNER_WIDTH);
  const cappedBody = body.map((line) => truncate(line, MAX_BOX_INNER_WIDTH));

  const innerWidth = Math.min(
    MAX_BOX_INNER_WIDTH,
    Math.max(
      cappedTitle.length,
      ...cappedBody.map((line) => line.length),
    ),
  );
  // Total line width = 1 (border) + 1 (space) + innerWidth + 1 (space) + 1 (border) = innerWidth + 4
  const fillWidth = innerWidth + 2;
  const fill = theme.unicode ? "─".repeat(fillWidth) : "-".repeat(fillWidth);
  const top = `${theme.unicode ? "╭" : "+"}${fill}${theme.unicode ? "╮" : "+"}`;
  const bottom = `${theme.unicode ? "╰" : "+"}${fill}${theme.unicode ? "╯" : "+"}`;
  const titleLine = `${theme.unicode ? "│" : "|"} ${paint(theme, ANSI.bold, cappedTitle.padEnd(innerWidth))} ${theme.unicode ? "│" : "|"}`;
  const padded = cappedBody.map((line) => `${theme.unicode ? "│" : "|"} ${line.padEnd(innerWidth)} ${theme.unicode ? "│" : "|"}`);
  return [top, titleLine, ...padded, bottom].join("\n");
}

function pair(label: string, value: string): string {
  return `${label.padEnd(18)} ${value}`;
}

function statusColor(theme: Theme, status: string, ok: string, warn?: string): string {
  if (status === ok) return paint(theme, ANSI.green, status.toUpperCase());
  if (warn && status === warn) return paint(theme, ANSI.yellow, status.toUpperCase());
  return paint(theme, ANSI.yellow, status.toUpperCase());
}

function formatCounts(counts: MaybeRecord): string[] {
  return [
    pair("Files", String(counts.files ?? 0)),
    pair("Directories", String(counts.directories ?? 0)),
    pair("Symlinks", String(counts.symlinks ?? 0)),
  ];
}

// ---------------------------------------------------------------------------
// Scan
// ---------------------------------------------------------------------------

function formatScan(value: MaybeRecord, theme: Theme): string {
  const lines = [
    pair("Repository", truncate(String(value.root ?? "."), 55)),
    "",
    ...formatCounts((value.counts as MaybeRecord) ?? {}),
    "",
    pair(
      "Status",
      paint(
        theme,
        value.status === "complete" ? ANSI.green : ANSI.yellow,
        String(value.status ?? "unknown").toUpperCase(),
      ),
    ),
  ];
  if (Array.isArray(value.nextSteps) && value.nextSteps.length > 0) {
    lines.push("", "Next steps");
    for (const step of value.nextSteps.slice(0, 3)) {
      lines.push(`${icon(theme, "next")} ${String(step)}`);
    }
  }
  return box(theme, "Fuzit · Repository Scan", lines);
}

// ---------------------------------------------------------------------------
// Pack
// ---------------------------------------------------------------------------

function formatPack(value: MaybeRecord, theme: Theme): string {
  const redactions = value.redactions as MaybeRecord | undefined;
  const findings = Number(redactions?.findings ?? 0);
  const redactedItems = Number(redactions?.redactedItems ?? 0);
  const omittedItems = Number(redactions?.omittedItems ?? 0);
  const selected = (value.selected as unknown[] | undefined) ?? [];
  const lines = [
    pair("Selected files", String(selected.length)),
    pair("Redaction findings", paint(theme, findings > 0 ? ANSI.yellow : ANSI.green, String(findings))),
    pair("Redacted items", paint(theme, redactedItems > 0 ? ANSI.yellow : ANSI.green, String(redactedItems))),
    pair("Omitted items", paint(theme, omittedItems > 0 ? ANSI.yellow : ANSI.green, String(omittedItems))),
  ];
  if (typeof value.output === "string") lines.push("", pair("Output", truncate(value.output, 55)));
  return box(theme, "Fuzit · Repository Pack", lines);
}

// ---------------------------------------------------------------------------
// Graph Stats
// ---------------------------------------------------------------------------

export function formatGraphStats(value: MaybeRecord, theme: Theme): string {
  const lines = [
    pair("Nodes", String(value.nodes ?? 0)),
    pair("Edges", String(value.edges ?? 0)),
    pair(
      "Completeness",
      paint(
        theme,
        value.completeness === "complete" ? ANSI.green : ANSI.yellow,
        String(value.completeness ?? "unknown").toUpperCase(),
      ),
    ),
  ];
  const nodeKinds = value.nodeKinds as MaybeRecord | undefined;
  if (nodeKinds && Object.keys(nodeKinds).length > 0) {
    lines.push("", "Node kinds");
    for (const [kind, count] of Object.entries(nodeKinds)) lines.push(pair(kind, String(count)));
  }
  const edgeKinds = value.edgeKinds as MaybeRecord | undefined;
  if (edgeKinds && Object.keys(edgeKinds).length > 0) {
    lines.push("", "Edge kinds");
    for (const [kind, count] of Object.entries(edgeKinds)) lines.push(pair(kind, String(count)));
  }
  lines.push("", pair("Diagnostics", String((value.diagnostics as unknown[] | undefined)?.length ?? 0)));
  return box(theme, "Fuzit · Graph Statistics", lines);
}

// ---------------------------------------------------------------------------
// Graph Build
// ---------------------------------------------------------------------------

export function formatGraphBuild(value: MaybeRecord, theme: Theme): string {
  return box(theme, "Fuzit · Repository Graph", [
    pair("Nodes", String(value.nodes ?? 0)),
    pair("Edges", String(value.edges ?? 0)),
    pair("Completeness", String(value.completeness ?? "unknown").toUpperCase()),
    "",
    pair("Output", truncate(String(value.output ?? ""), 55)),
  ]);
}

// ---------------------------------------------------------------------------
// Graph Query / Neighbors / Impact
// ---------------------------------------------------------------------------

function formatGraphQuery(value: MaybeRecord, theme: Theme): string {
  const results = Array.isArray(value.results) ? value.results : [];
  const lines = [
    pair("Results", String(results.length)),
  ];
  if (value.truncated) lines.push(pair("Truncated", paint(theme, ANSI.yellow, "YES")));
  if (results.length > 0) {
    lines.push("", "Results");
    for (const result of results.slice(0, 12)) {
      if (typeof result === "string") {
        lines.push(truncate(result, MAX_BOX_INNER_WIDTH - 2));
      } else if (result && typeof result === "object") {
        const record = result as MaybeRecord;
        lines.push(
          truncate(
            `${String(record.kind ?? "node").toUpperCase()}: ${String(record.path ?? record.id ?? "")}`,
            MAX_BOX_INNER_WIDTH - 2,
          ),
        );
      }
    }
    if (results.length > 12) {
      lines.push(`… and ${results.length - 12} more`);
    }
  }
  const diagnostics = Array.isArray(value.diagnostics) ? value.diagnostics : [];
  if (diagnostics.length > 0) {
    lines.push("", "Diagnostics");
    for (const diagnostic of diagnostics.slice(0, 5)) lines.push(truncate(String(diagnostic), MAX_BOX_INNER_WIDTH - 2));
  }
  return box(theme, "Fuzit · Repository Graph Query", lines);
}

// ---------------------------------------------------------------------------
// Auth
// ---------------------------------------------------------------------------

function formatAuth(value: MaybeRecord, theme: Theme): string {
  const isAuthenticated =
    value.status === "Authenticated" || value.status === "Already authenticated";
  const lines = [
    pair(
      "Status",
      paint(
        theme,
        isAuthenticated
          ? ANSI.green
          : value.status === "Not authenticated"
            ? ANSI.yellow
            : ANSI.red,
        String(value.status ?? "unknown"),
      ),
    ),
    pair("Host", String(value.host ?? "github.com")),
  ];
  if (typeof value.account === "string") lines.push(pair("Account", value.account));
  if (typeof value.source === "string") lines.push(pair("Source", value.source));
  if (typeof value.permission === "string") {
    // permission is a required capability, not a verified scope claim
    lines.push("", pair("Required for review", value.permission));
  }
  if (typeof value.error === "string") lines.push("", paint(theme, ANSI.red, truncate(value.error, MAX_BOX_INNER_WIDTH - 4)));
  if (typeof value.nextStep === "string") lines.push("", `Next: ${value.nextStep}`);
  return box(theme, "Fuzit · GitHub Authentication", lines);
}

// ---------------------------------------------------------------------------
// Review
// ---------------------------------------------------------------------------

function formatReview(value: MaybeRecord, theme: Theme): string {
  const findings = Array.isArray(value.findings) ? value.findings : [];
  const lines: string[] = [
    pair("Repository", truncate(String(value.repository ?? ""), 55)),
    pair("PR", `#${String(value.prNumber ?? "")}`),
  ];
  if (typeof value.title === "string") lines.push(pair("Title", truncate(value.title, 55)));
  if (typeof value.state === "string") lines.push(pair("State", value.state.toUpperCase()));
  if (typeof value.author === "string") lines.push(pair("Author", value.author));
  if (typeof value.baseRef === "string" && typeof value.headRef === "string") {
    lines.push(pair("Branch", `${value.baseRef} ← ${value.headRef}`));
  }
  lines.push("", "Findings");
  if (findings.length === 0) {
    lines.push(paint(theme, ANSI.green, "No high-confidence findings detected."));
  } else {
    lines.push(paint(theme, ANSI.yellow, `${findings.length} finding(s) detected`));
    for (const finding of (findings as MaybeRecord[]).slice(0, 5)) {
      const severity = typeof finding.severity === "string" ? finding.severity : "info";
      const message = truncate(
        typeof finding.message === "string"
          ? finding.message
          : typeof finding.description === "string"
            ? finding.description
            : String(finding),
        MAX_BOX_INNER_WIDTH - 8,
      );
      const color = severity === "error" ? ANSI.red : severity === "warning" ? ANSI.yellow : ANSI.cyan;
      lines.push(`  ${paint(theme, color, severity.toUpperCase())} ${message}`);
    }
    if (findings.length > 5) lines.push(`  … and ${findings.length - 5} more`);
  }
  if (typeof value.summary === "string") {
    // Render a bounded excerpt of the summary (first 3 non-empty lines)
    const summaryLines = value.summary
      .split("\n")
      .map((l: string) => l.trim())
      .filter(Boolean)
      .slice(0, 3);
    if (summaryLines.length > 0) {
      lines.push("", "Summary excerpt");
      for (const line of summaryLines) {
        lines.push(truncate(line, MAX_BOX_INNER_WIDTH - 2));
      }
    }
  }
  if (typeof value.output === "string") lines.push("", pair("Saved to", truncate(value.output, 55)));
  return box(theme, "Fuzit · Pull Request Review", lines);
}

// ---------------------------------------------------------------------------
// Error
// ---------------------------------------------------------------------------

function formatError(value: MaybeRecord, theme: Theme): string {
  const message = truncate(String(value.error ?? value.message ?? "Unknown error."), MAX_BOX_INNER_WIDTH - 4);
  return box(theme, "Fuzit Error", [
    paint(theme, ANSI.red, `${icon(theme, "error")} ${message}`),
  ]);
}

// ---------------------------------------------------------------------------
// Doctor
// ---------------------------------------------------------------------------

export function formatDoctorReport(
  report: { status: string; checks: Array<{ id: string; status: string; message: string }> },
  theme: Theme = resolveTheme({ color: false, unicode: false }),
): string {
  const statusBadge =
    report.status === "ready"
      ? paint(theme, ANSI.green, "READY")
      : paint(theme, ANSI.yellow, report.status.toUpperCase());
  const lines: string[] = [pair("Status", statusBadge), ""];
  for (const check of report.checks) {
    const label =
      check.status === "pass"
        ? paint(theme, ANSI.green, "PASS")
        : check.status === "warning"
          ? paint(theme, ANSI.yellow, "WARN")
          : paint(theme, ANSI.red, "FAIL");
    lines.push(`${label} ${check.id}: ${truncate(check.message, MAX_BOX_INNER_WIDTH - check.id.length - 8)}`);
  }
  return box(theme, "Fuzit · Environment Check", lines);
}

// ---------------------------------------------------------------------------
// Git
// ---------------------------------------------------------------------------

function formatGitStatus(value: MaybeRecord, theme: Theme): string {
  const changes = Array.isArray(value.changes) ? value.changes : [];
  const lines: string[] = [pair("Changes", String(changes.length)), ""];
  for (const change of (changes as MaybeRecord[]).slice(0, 20)) {
    const status = String(change.status ?? change.kind ?? "?").padEnd(8);
    const file = truncate(String(change.path ?? change.file ?? ""), MAX_BOX_INNER_WIDTH - 10);
    lines.push(`${status} ${file}`);
  }
  if (changes.length > 20) lines.push(`… and ${changes.length - 20} more`);
  if (changes.length === 0) lines.push(paint(theme, ANSI.green, "Working tree clean"));
  return box(theme, "Fuzit · Git Status", lines);
}

function formatGitLog(value: MaybeRecord, theme: Theme): string {
  const entries = Array.isArray(value.entries) ? value.entries : [];
  const lines: string[] = [pair("Commits", String(entries.length)), ""];
  for (const entry of (entries as MaybeRecord[]).slice(0, 15)) {
    const hash = truncate(String(entry.hash ?? entry.sha ?? entry.commit ?? "").slice(0, 8), 8);
    const msg = truncate(String(entry.message ?? entry.subject ?? ""), MAX_BOX_INNER_WIDTH - 12);
    const author = truncate(String(entry.author ?? ""), 16);
    lines.push(`${hash} ${author.padEnd(16)} ${msg}`);
  }
  if (entries.length > 15) lines.push(`… and ${entries.length - 15} more`);
  return box(theme, "Fuzit · Git Log", lines);
}

function formatGitDiff(value: MaybeRecord, theme: Theme): string {
  const files = Array.isArray(value.files)
    ? value.files
    : Array.isArray((value as MaybeRecord).changedFiles)
      ? (value as MaybeRecord).changedFiles as unknown[]
      : [];
  const base = typeof value.base === "string" ? value.base : "HEAD";
  const lines: string[] = [
    pair("Base", truncate(base, 55)),
    pair("Changed files", String(files.length)),
  ];
  for (const f of (files as MaybeRecord[]).slice(0, 20)) {
    lines.push(truncate(`  ${String(f.path ?? f.file ?? f)}`, MAX_BOX_INNER_WIDTH - 2));
  }
  if (files.length > 20) lines.push(`  … and ${files.length - 20} more`);
  return box(theme, "Fuzit · Git Diff", lines);
}

function formatGitBlame(value: MaybeRecord, theme: Theme): string {
  const lines_arr = Array.isArray(value.lines) ? value.lines : [];
  const lines: string[] = [pair("Lines", String(lines_arr.length)), ""];
  for (const entry of (lines_arr as MaybeRecord[]).slice(0, 15)) {
    const num = String(entry.line ?? entry.lineNumber ?? "").padStart(4);
    const hash = truncate(String(entry.hash ?? entry.commit ?? "").slice(0, 8), 8);
    const content = truncate(String(entry.content ?? ""), MAX_BOX_INNER_WIDTH - 16);
    lines.push(`${num} ${hash} ${content}`);
  }
  if (lines_arr.length > 15) lines.push(`… and ${lines_arr.length - 15} more`);
  return box(theme, "Fuzit · Git Blame", lines);
}

// ---------------------------------------------------------------------------
// Cache
// ---------------------------------------------------------------------------

function formatCacheResult(kind: string, value: MaybeRecord, theme: Theme): string {
  const lines: string[] = [];
  if (typeof value.path === "string") lines.push(pair("Path", truncate(value.path, 55)));
  if (typeof value.repositoryId === "string") lines.push(pair("Repository ID", truncate(value.repositoryId.slice(0, 32), 32)));
  if (typeof value.state === "string") {
    lines.push(pair("State", statusColor(theme, value.state, "ready", "stale")));
  }
  if (typeof value.valid === "boolean") {
    lines.push(pair("Valid", value.valid ? paint(theme, ANSI.green, "YES") : paint(theme, ANSI.red, "NO")));
  }
  if (typeof value.rebuildRequired === "boolean" && value.rebuildRequired) {
    lines.push(pair("Rebuild required", paint(theme, ANSI.yellow, "YES")));
  }
  if (Array.isArray(value.reasons) && value.reasons.length > 0) {
    lines.push("", "Reasons");
    for (const r of (value.reasons as string[]).slice(0, 5)) lines.push(`  ${truncate(r, MAX_BOX_INNER_WIDTH - 4)}`);
  }
  if (typeof value.dryRun === "boolean") lines.push("", pair("Dry run", value.dryRun ? "YES" : "NO"));
  if (typeof value.action === "string") lines.push(pair("Action", truncate(value.action, 55)));
  const decision = value.decision as MaybeRecord | undefined;
  if (decision && typeof decision.action === "string") {
    lines.push("", pair("Decision", decision.action.toUpperCase()));
    if (Array.isArray(decision.reasons)) {
      for (const r of (decision.reasons as string[]).slice(0, 3)) lines.push(`  ${truncate(r, MAX_BOX_INNER_WIDTH - 4)}`);
    }
  }
  const titles: Record<string, string> = {
    "cache-init": "Fuzit · Cache Init",
    "cache-status": "Fuzit · Cache Status",
    "cache-rebuild": "Fuzit · Cache Rebuild",
    "cache-verify": "Fuzit · Cache Verify",
    "cache-purge": "Fuzit · Cache Purge",
  };
  return box(theme, titles[kind] ?? "Fuzit · Cache", lines);
}

// ---------------------------------------------------------------------------
// Snapshot
// ---------------------------------------------------------------------------

function formatSnapshotCreate(value: MaybeRecord, theme: Theme): string {
  const lines: string[] = [];
  if (typeof value.id === "string") lines.push(pair("ID", truncate(value.id, 55)));
  if (typeof value.repositoryRevision === "string") lines.push(pair("Revision", truncate(value.repositoryRevision, 40)));
  if (typeof value.dirty === "boolean") lines.push(pair("Dirty", value.dirty ? paint(theme, ANSI.yellow, "YES") : "NO"));
  if (typeof value.complete === "boolean") {
    lines.push(pair("Complete", value.complete ? paint(theme, ANSI.green, "YES") : paint(theme, ANSI.yellow, "NO")));
  }
  const diags = Array.isArray(value.diagnostics) ? value.diagnostics : [];
  lines.push(pair("Diagnostics", String(diags.length)));
  return box(theme, "Fuzit · Snapshot Created", lines);
}

function formatSnapshotList(value: unknown, theme: Theme): string {
  const items = Array.isArray(value) ? value : [];
  const lines: string[] = [pair("Snapshots", String(items.length)), ""];
  for (const item of (items as MaybeRecord[]).slice(0, 15)) {
    const id = truncate(String(item.id ?? ""), 55);
    const rev = truncate(String(item.repositoryRevision ?? ""), 20);
    lines.push(`${id}  ${rev}`);
  }
  if (items.length > 15) lines.push(`… and ${items.length - 15} more`);
  if (items.length === 0) lines.push("No snapshots found.");
  return box(theme, "Fuzit · Snapshots", lines);
}

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

function formatConfig(value: MaybeRecord, theme: Theme): string {
  const vals = (value.values as MaybeRecord) ?? {};
  const prov = (value.provenance as MaybeRecord) ?? {};
  const lines: string[] = [];
  for (const [key, val] of Object.entries(vals)) {
    const source = String(prov[key] ?? "");
    const sourceLabel = source !== "default" ? paint(theme, ANSI.dim, `(${source})`) : paint(theme, ANSI.dim, "(default)");
    const display = Array.isArray(val) ? (val.length === 0 ? "[]" : val.join(", ")) : String(val);
    lines.push(`${key.padEnd(18)} ${truncate(display, 40).padEnd(40)} ${sourceLabel}`);
  }
  return box(theme, "Fuzit · Effective Configuration", lines);
}

// ---------------------------------------------------------------------------
// Support
// ---------------------------------------------------------------------------

function formatSupport(value: MaybeRecord, theme: Theme): string {
  const checks = Array.isArray(value.checks) ? value.checks : [];
  const lines: string[] = [];
  if (typeof value.productVersion === "string") lines.push(pair("Version", value.productVersion));
  if (typeof value.id === "string") lines.push(pair("Bundle ID", truncate(value.id, 40)));
  if (checks.length > 0) {
    lines.push("", "Checks");
    for (const check of (checks as MaybeRecord[]).slice(0, 10)) {
      const status = String(check.status ?? "");
      const surface = String(check.surface ?? "");
      const label = status === "pass"
        ? paint(theme, ANSI.green, "PASS")
        : paint(theme, ANSI.yellow, status.toUpperCase());
      lines.push(`${label} ${surface}`);
    }
  }
  return box(theme, "Fuzit · Support Bundle Preview", lines);
}

// ---------------------------------------------------------------------------
// Profile list
// ---------------------------------------------------------------------------

function formatProfileList(value: unknown, theme: Theme): string {
  const profiles = Array.isArray(value) ? value : (value && typeof value === "object" ? Object.values(value) : []);
  const lines: string[] = [pair("Profiles", String(profiles.length)), ""];
  for (const p of (profiles as MaybeRecord[]).slice(0, 20)) {
    const name = truncate(String(p.name ?? p.id ?? ""), 22);
    const desc = truncate(String(p.description ?? ""), MAX_BOX_INNER_WIDTH - 26);
    lines.push(`${name.padEnd(22)} ${desc}`);
  }
  return box(theme, "Fuzit · Built-in Profiles", lines);
}

// ---------------------------------------------------------------------------
// Context result (when output written to file)
// ---------------------------------------------------------------------------

function formatContextResult(value: MaybeRecord, theme: Theme): string {
  const selected = Array.isArray(value.selected) ? value.selected : [];
  const lines: string[] = [
    pair("Selected files", String(selected.length)),
  ];
  if (typeof value.output === "string") lines.push(pair("Output", truncate(value.output, 55)));
  const report = value.report as MaybeRecord | undefined;
  if (report) {
    if (typeof report.budgetTokens === "number") lines.push(pair("Budget tokens", String(report.budgetTokens)));
    if (typeof report.usedTokens === "number") lines.push(pair("Used tokens", String(report.usedTokens)));
  }
  return box(theme, "Fuzit · Task Context", lines);
}

// ---------------------------------------------------------------------------
// Repository Roots
// ---------------------------------------------------------------------------

function formatRepositoryRoots(value: MaybeRecord, theme: Theme): string {
  const nested = (value.nestedRoots as unknown[] | undefined) ?? [];
  return box(theme, "Fuzit · Repository Roots", [
    pair("Selected root", truncate(String(value.selectedRoot ?? "."), 55)),
    pair("Nested roots", String(nested.length)),
  ]);
}

function formatIssueResult(value: MaybeRecord, theme: Theme): string {
  const result = (value.result as MaybeRecord) ?? value;
  const lines: string[] = [];
  if (result.targetRepo || value.repository) {
    lines.push(pair("Repository", truncate(String(result.targetRepo ?? value.repository ?? ""), 55)));
  }
  if (result.issueNumber || value.issueNumber) {
    lines.push(pair("Issue", `#${String(result.issueNumber ?? value.issueNumber ?? "")}`));
  }
  if (typeof result.title === "string") lines.push(pair("Title", truncate(result.title, 55)));
  if (typeof result.state === "string") lines.push(pair("State", result.state.toUpperCase()));
  if (typeof result.author === "string") lines.push(pair("Author", result.author));
  if (typeof value.output === "string") lines.push(pair("Output", truncate(value.output, 55)));
  return box(theme, "Fuzit · GitHub Issue", lines);
}

function formatInitPlanBox(value: MaybeRecord, theme: Theme): string {
  const changes = Array.isArray(value.changes) ? value.changes : [];
  const lines: string[] = [
    pair("Status", value.applied ? paint(theme, ANSI.green, "APPLIED") : "DRY RUN"),
    pair("Changes", String(changes.length)),
    "",
  ];
  for (const c of (changes as MaybeRecord[]).slice(0, 15)) {
    const action = String(c.action ?? "create").toUpperCase();
    lines.push(`  ${action.padEnd(8)} ${truncate(String(c.path ?? ""), 55)}`);
  }
  return box(theme, "Fuzit · Project Initialization", lines);
}

function formatDualPack(value: MaybeRecord, theme: Theme): string {
  const lines: string[] = [
    pair("Markdown output", "fuzit-pack.md"),
    pair("XML output", "fuzit-pack.xml"),
    pair("Files packed", String(value.files ?? value.filesCount ?? 0)),
    pair("Estimated tokens", String(value.tokens ?? value.tokensCount ?? 0)),
  ];
  return box(theme, "Fuzit · Dual Context Pack Complete", lines);
}

function formatServe(value: MaybeRecord, theme: Theme): string {
  return box(theme, "Fuzit · RAG API Server", [
    pair("Status", paint(theme, ANSI.green, "RUNNING")),
    pair("Endpoint", String(value.endpoint ?? "")),
    pair("Host", String(value.host ?? "")),
    pair("Port", String(value.port ?? "")),
    pair("Repository", truncate(String(value.root ?? "."), 55)),
  ]);
}

function formatApply(value: MaybeRecord, theme: Theme): string {
  const applied = Array.isArray(value.applied) ? value.applied : [];
  const lines: string[] = [
    pair("Status", value.status === "success" ? paint(theme, ANSI.green, "SUCCESS") : String(value.status).toUpperCase()),
    pair("Applied files", String(applied.length)),
    "",
  ];
  for (const f of (applied as string[]).slice(0, 15)) {
    lines.push(`  APPLIED  ${truncate(f, 55)}`);
  }
  return box(theme, "Fuzit · Code Patch Application", lines);
}

function formatUiDashboard(value: MaybeRecord, theme: Theme): string {
  const languages = Array.isArray(value.languages) ? value.languages.join(", ") : "";
  const lines: string[] = [
    pair("Repository", truncate(String(value.repository ?? "."), 55)),
    pair("Files discovered", String(value.totalFiles ?? 0)),
    pair("Omitted files", String(value.omissions ?? 0)),
    pair("Languages", truncate(languages || "None", 55)),
    pair("Profiles available", String(value.profilesCount ?? 6)),
  ];
  return box(theme, "Fuzit · Interactive UI Dashboard", lines);
}

// ---------------------------------------------------------------------------
// Main dispatch
// ---------------------------------------------------------------------------

export function formatHumanValue(value: unknown, themeOverrides?: Partial<Theme>): string | null {
  if (!value || (typeof value !== "object" && !Array.isArray(value))) return null;
  const theme = resolveTheme(themeOverrides);

  if (Array.isArray(value)) {
    if (value.length > 0 && typeof value[0] === "object" && value[0] !== null) {
      const first = value[0] as MaybeRecord;
      if ("repositoryRevision" in first) {
        return formatSnapshotList(value, theme);
      }
      if ("weights" in first || "expansion" in first || "id" in first) {
        return formatProfileList(value, theme);
      }
    }
    return null;
  }

  const record = value as MaybeRecord;

  // Error envelope (always first)
  if ("error" in record && typeof record.error === "string") {
    return formatError(record, theme);
  }

  // Named kind discriminators (human-only)
  switch (record.kind) {
    case "auth":         return formatAuth(record, theme);
    case "review":       return formatReview(record, theme);
    case "graph-build":  return formatGraphBuild(record, theme);
    case "graph-stats":  return formatGraphStats(record, theme);
    case "pack":         return formatPack(record, theme);
    case "dual-pack":    return formatDualPack(record, theme);
    case "serve":        return formatServe(record, theme);
    case "apply":        return formatApply(record, theme);
    case "ui-dashboard": return formatUiDashboard(record, theme);
    case "cache-init":
    case "cache-status":
    case "cache-rebuild":
    case "cache-verify":
    case "cache-purge":  return formatCacheResult(String(record.kind), record, theme);
    case "snapshot-created": return formatSnapshotCreate(record, theme);
    case "snapshot-list":    return formatSnapshotList(record.items, theme);
    case "git-status":       return formatGitStatus(record, theme);
    case "git-log":          return formatGitLog(record, theme);
    case "git-diff":         return formatGitDiff(record, theme);
    case "git-blame":        return formatGitBlame(record, theme);
    case "git-file-history": return formatGitLog({ entries: record.entries }, theme);
    case "doctor":           return formatDoctorReport(record as Parameters<typeof formatDoctorReport>[0], theme);
    case "config":           return formatConfig(record, theme);
    case "support":          return formatSupport(record, theme);
    case "profile-list":     return formatProfileList(record.profiles, theme);
    case "context-result":   return formatContextResult(record, theme);
  }

  // Structural fingerprints for objects without kind discriminators
  // (backwards-compatible for shapes emitted before kind was added, keeping JSON pure)
  if ("schemaVersion" in record && "counts" in record && "status" in record) {
    return formatScan(record, theme);
  }
  if ("selected" in record && "redactions" in record) {
    return formatPack(record, theme);
  }
  if ("outputs" in record && "files" in record) {
    return formatDualPack(record, theme);
  }
  if ("results" in record && "truncated" in record) {
    return formatGraphQuery(record, theme);
  }
  if ("selectedRoot" in record && "nestedRoots" in record) {
    return formatRepositoryRoots(record, theme);
  }
  if ("values" in record && "provenance" in record) {
    return formatConfig(record, theme);
  }
  if ("productVersion" in record && "checks" in record) {
    return formatSupport(record, theme);
  }
  if ("status" in record && "checks" in record && Array.isArray(record.checks)) {
    return formatDoctorReport(record as Parameters<typeof formatDoctorReport>[0], theme);
  }
  if ("changes" in record && Array.isArray(record.changes) && "applied" in record) {
    return formatInitPlanBox(record, theme);
  }
  if ("changes" in record && Array.isArray(record.changes)) {
    return formatGitStatus(record, theme);
  }
  if ("entries" in record && Array.isArray(record.entries)) {
    return formatGitLog(record, theme);
  }
  if ("files" in record && Array.isArray(record.files)) {
    return formatGitDiff(record, theme);
  }
  if ("lines" in record && Array.isArray(record.lines)) {
    return formatGitBlame(record, theme);
  }
  if ("issueNumber" in record || ("output" in record && "result" in record)) {
    return formatIssueResult(record, theme);
  }
  if ("output" in record && "selected" in record && "report" in record) {
    return formatContextResult(record, theme);
  }
  if ("code-review" in record || "bug-fix" in record) {
    return formatProfileList(record, theme);
  }
  if ("repositoryRevision" in record && "fileFingerprints" in record) {
    return formatSnapshotCreate(record, theme);
  }
  if ("cacheHome" in record && "repositoryFingerprint" in record) {
    return formatCacheResult("cache-status", record, theme);
  }
  if ("path" in record && "decision" in record) {
    return formatCacheResult("cache-rebuild", record, theme);
  }
  if ("path" in record && "valid" in record && "rebuildRequired" in record) {
    return formatCacheResult("cache-verify", record, theme);
  }
  if ("path" in record && "action" in record && typeof record.action === "string" && record.action.includes("purge")) {
    return formatCacheResult("cache-purge", record, theme);
  }
  if ("path" in record && "repositoryId" in record && "state" in record) {
    return formatCacheResult("cache-init", record, theme);
  }

  return null;
}

import type { Diagnostic } from "@fuzit/schemas";

import { redactSensitiveText } from "./redact.js";
import { formatHumanValue } from "./presentation.js";

export interface OutputIo {
  readonly writeOut: (value: string) => void;
  readonly writeErr: (value: string) => void;
}

export interface OutputOptions {
  readonly debug: boolean;
  readonly json: boolean;
  readonly quiet: boolean;
}

function redactDiagnostic(diagnostic: Diagnostic): Diagnostic {
  return {
    ...diagnostic,
    source: redactSensitiveText(diagnostic.source),
    message: redactSensitiveText(diagnostic.message),
    ...(diagnostic.remediation
      ? { remediation: redactSensitiveText(diagnostic.remediation) }
      : {}),
    ...(diagnostic.location
      ? {
          location: {
            ...diagnostic.location,
            path: redactSensitiveText(diagnostic.location.path),
          },
        }
      : {}),
  };
}

export function createOutputRouter(io: OutputIo, options: OutputOptions) {
  return {
    writeActivity(value: string): void {
      if (options.json || options.quiet) return;
      io.writeErr(`${redactSensitiveText(value)}\n`);
    },

    writeData(value: unknown): void {
      if (options.json) {
        io.writeOut(`${JSON.stringify(value)}\n`);
      } else if (typeof value === "string") {
        io.writeOut(value.endsWith("\n") ? value : `${value}\n`);
      } else {
        const formatted = formatHumanValue(value);
        io.writeOut(`${formatted ?? JSON.stringify(value, null, 2)}\n`);
      }
    },

    writeDiagnostic(diagnostic: Diagnostic, cause?: unknown): void {
      const safeDiagnostic = redactDiagnostic(diagnostic);

      if (options.json) {
        io.writeOut(
          `${JSON.stringify({
            schemaVersion: 1,
            diagnostics: [safeDiagnostic],
          })}\n`,
        );
        return;
      }

      if (options.quiet && safeDiagnostic.severity === "info") {
        return;
      }

      io.writeErr(
        `${safeDiagnostic.severity} ${safeDiagnostic.code}: ${safeDiagnostic.message}\n`,
      );

      if (options.debug && cause instanceof Error && cause.stack) {
        io.writeErr(`${redactSensitiveText(cause.stack)}\n`);
      }
    },
  };
}

import { beforeEach, describe, expect, it, vi } from "vitest";
import { runCli } from "../src/cli.js";

const spawnSync = vi.hoisted(() => vi.fn());

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return {
    ...actual,
    spawnSync,
  };
});

async function capture(
  args: readonly string[],
  environment: Record<string, string | undefined> = {},
) {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(
    args,
    {
      writeOut: (value) => {
        stdout += value;
      },
      writeErr: (value) => {
        stderr += value;
      },
    },
    { environment, repositoryRoot: process.cwd() },
  );
  return { exitCode, stdout, stderr };
}

function installUserFetch(login = "aadit") {
  const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const headers = new Headers(init?.headers);
    expect(headers.get("authorization")).toMatch(/^Bearer\s+/);
    return new Response(JSON.stringify({ login }), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  });
  vi.stubGlobal("fetch", fetchMock as typeof fetch);
  return fetchMock;
}

beforeEach(() => {
  spawnSync.mockReset();
  vi.unstubAllGlobals();
});

describe("auth command", () => {
  it("shows anonymous status with next steps", async () => {
    spawnSync.mockImplementation((command: string) => {
      if (command !== "gh") return { status: 1, stdout: "", stderr: "" };
      if (spawnSync.mock.calls.some((call) => call[1]?.[0] === "--version")) {
        return { status: 1, stdout: "", stderr: "" };
      }
      return { status: 1, stdout: "", stderr: "" };
    });
    const result = await capture(["auth", "status"]);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("GitHub Authentication");
    expect(result.stdout).toContain("Not authenticated");
    expect(result.stdout).toContain("fuzit auth github");
  });

  it("reports environment token authentication", async () => {
    spawnSync.mockImplementation(() => ({ status: 1, stdout: "", stderr: "" }));
    installUserFetch("env-user");
    const result = await capture(["auth", "status"], {
      GH_TOKEN: "gh-token-for-tests",
    });
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Authenticated");
    expect(result.stdout).toContain("GH_TOKEN");
    expect(result.stdout).not.toContain("gh-token-for-tests");
  });

  it("reports authenticated GitHub CLI status when gh is logged in", async () => {
    spawnSync.mockImplementation((command: string, args?: readonly string[]) => {
      if (command !== "gh") return { status: 1, stdout: "", stderr: "" };
      if (args?.[0] === "--version") {
        return { status: 0, stdout: "gh version 2.0.0", stderr: "" };
      }
      if (args?.[0] === "auth" && args?.[1] === "token") {
        return { status: 0, stdout: "mock-gh-token\n", stderr: "" };
      }
      return { status: 1, stdout: "", stderr: "" };
    });
    installUserFetch("github-cli-user");

    const result = await capture(["auth", "status"]);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Authenticated");
    expect(result.stdout).toContain("Source             github-cli");
    expect(result.stdout).not.toContain("mock-gh-token");
  });
});

import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { CLI_USAGE_ERROR_EXIT_CODE, CLI_VERSION, runCli } from "../src/cli.js";

interface CapturedRun {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
}

async function captureRun(arguments_: readonly string[]): Promise<CapturedRun> {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(arguments_, {
    writeOut: (value) => {
      stdout += value;
    },
    writeErr: (value) => {
      stderr += value;
    },
  });

  return { exitCode, stdout, stderr };
}

describe("fuzit process shell", () => {
  it("matches the help golden output", async () => {
    const goldenPath = join(
      dirname(fileURLToPath(import.meta.url)),
      "golden",
      "help.txt",
    );
    const golden = await readFile(goldenPath, "utf8");

    expect(await captureRun(["--help"])).toEqual({
      exitCode: 0,
      stdout: golden,
      stderr: "",
    });
  });

  it("prints the package version", async () => {
    expect(await captureRun(["--version"])).toEqual({
      exitCode: 0,
      stdout: `${CLI_VERSION}\n`,
      stderr: "",
    });
  });

  it("returns a deterministic nonzero status for an unknown command", async () => {
    expect(await captureRun(["unknown"])).toEqual({
      exitCode: CLI_USAGE_ERROR_EXIT_CODE,
      stdout: "",
      stderr: "error CLI.UNKNOWN_COMMAND: unknown command 'unknown'\n",
    });
  });

  it("rejects quiet and debug together", async () => {
    const result = await captureRun(["--quiet", "--debug"]);

    expect(result.exitCode).toBe(CLI_USAGE_ERROR_EXIT_CODE);
    expect(result.stdout).toBe("");
    expect(result.stderr).toContain(
      "option '--quiet' cannot be used with option '--debug'",
    );
  });

  it("emits a stable JSON error envelope", async () => {
    expect(await captureRun(["--json", "unknown"])).toEqual({
      exitCode: CLI_USAGE_ERROR_EXIT_CODE,
      stdout: `{"schemaVersion":1,"diagnostics":[{"schemaVersion":1,"code":"CLI.UNKNOWN_COMMAND","severity":"error","source":"cli","message":"unknown command 'unknown'"}]}\n`,
      stderr: "",
    });
  });

  it("shows effective configuration and provenance as JSON", async () => {
    let stdout = "";
    let stderr = "";
    const exitCode = await runCli(
      ["config", "show", "--json"],
      {
        writeOut: (value) => {
          stdout += value;
        },
        writeErr: (value) => {
          stderr += value;
        },
      },
      {
        repositoryRoot: dirname(fileURLToPath(import.meta.url)),
        environment: {},
      },
    );

    expect({ exitCode, stdout, stderr }).toEqual({
      exitCode: 0,
      stdout:
        '{"schemaVersion":1,"values":{"outputFormat":"markdown","maxFiles":120,"diagnosticLevel":"info","include":[],"exclude":[]},"provenance":{"outputFormat":"default","maxFiles":"default","diagnosticLevel":"default","include":"default","exclude":"default"}}\n',
      stderr: "",
    });
  });
});

import { describe, expect, it } from "vitest";

import { formatDoctorReport } from "../src/commands/doctor/register.js";

describe("doctor human output", () => {
  it("does not leak private paths", () => {
    const privatePath = "C:\\Users\\private-user\\secret-repository";
    const output = formatDoctorReport({
      schemaVersion: 1,
      status: "attention",
      checks: [
        {
          id: "repository",
          status: "fail",
          message: "Repository not detected.",
          metadata: { detected: false },
        },
      ],
    });

    expect(output).toContain("FAIL repository: Repository not detected.");
    expect(output).not.toContain(privatePath);
    expect(output).not.toContain("C:\\Users");
  });
});

import { mkdir, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { buildFilePackageGraph } from "@fuzit/graph";
import { EXIT_CODES, type NormalizedAnalysis } from "@fuzit/schemas";
import { describe, expect, it } from "vitest";
import { runCli } from "../src/cli.js";
import { isGraphPathInsideRepository } from "../src/commands/graph/register.js";

const repositoryId = `sha256:${"a".repeat(64)}`;
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: [
    {
      id: `analysis:file:${"1".padStart(64, "0")}`,
      repositoryId,
      kind: "file",
      path: "src/a.ts",
      language: "typescript",
      contentHash: `sha256:${"2".padStart(64, "0")}`,
    },
  ],
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};

async function run(args: readonly string[], partial = false) {
  const root = await mkdtemp(join(tmpdir(), "fuzit-graph-cli-"));
  let stdout = "";
  let stderr = "";
  const graph = buildFilePackageGraph({
    analysis,
    revision: "r1",
    packages: [],
  });
  await writeFile(
    join(root, "graph.json"),
    JSON.stringify(
      partial
        ? {
            ...graph,
            completeness: "partial",
            diagnostics: ["parser unavailable"],
          }
        : graph,
    ),
  );
  const exitCode = await runCli(
    args,
    {
      writeOut: (value) => {
        stdout += value;
      },
      writeErr: (value) => {
        stderr += value;
      },
    },
    { repositoryRoot: root, environment: {} },
  );
  return { exitCode, stdout, stderr, graph };
}

async function execute(args: readonly string[], repositoryRoot: string) {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(
    args,
    {
      writeOut: (value) => {
        stdout += value;
      },
      writeErr: (value) => {
        stderr += value;
      },
    },
    { repositoryRoot, environment: {} },
  );
  return { exitCode, stdout, stderr };
}

describe("graph CLI", () => {
  it("round-trips a built artifact through every persisted-graph command", async () => {
    const invocationRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-cwd-"));
    const repositoryRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-repo-"));
    await mkdir(join(repositoryRoot, ".git"));
    await mkdir(join(repositoryRoot, "src"));
    await writeFile(join(repositoryRoot, "src", "a.ts"), "export {};");
    const graphPath = join(repositoryRoot, ".fuzit-final-graph.json");

    const built = await execute(
      ["graph", "build", "--root", repositoryRoot, "--output", graphPath],
      invocationRoot,
    );
    expect(built.exitCode).toBe(0);
    expect(built.stderr).toContain("Building repository graph");

    const persisted = JSON.parse(await readFile(graphPath, "utf8"));
    const repositoryNode = persisted.nodes.find(
      (node: { kind: string }) => node.kind === "repository",
    );
    expect(repositoryNode).toBeDefined();

    const stats = await execute(
      ["--json", "graph", "stats", "--input", graphPath],
      invocationRoot,
    );
    expect(stats.exitCode).toBe(0);
    expect(JSON.parse(stats.stdout)).toMatchObject({ nodes: 2, edges: 1 });
    expect(stats.stderr).toBe("");

    const neighbors = await execute(
      ["graph", "neighbors", "--input", graphPath, repositoryNode.id],
      invocationRoot,
    );
    expect(neighbors.exitCode).toBe(0);
    expect(neighbors.stdout).toContain("Fuzit · Repository Graph Query");
    expect(neighbors.stdout).toContain("FILE: src/a.ts");
    expect(neighbors.stderr).toContain("Finding graph neighbors");

    const impact = await execute(
      ["graph", "impact", "--input", graphPath, repositoryNode.id],
      invocationRoot,
    );
    expect(impact.exitCode).toBe(0);
    expect(impact.stderr).toContain("Analyzing graph impact");

    const query = await execute(
      ["graph", "query", "--input", graphPath, "--kind", "file"],
      invocationRoot,
    );
    expect(query.exitCode).toBe(0);
    expect(query.stdout).toContain("FILE: src/a.ts");
    expect(query.stderr).toContain("Querying repository graph");
  });

  it("rejects outside artifacts and traversal even with a valid graph", async () => {
    const repositoryRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-safe-"));
    const outsideRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-outside-"));
    const outsideGraph = join(outsideRoot, "graph.json");
    const graph = buildFilePackageGraph({
      analysis,
      revision: "r1",
      packages: [],
    });
    await writeFile(outsideGraph, JSON.stringify(graph));

    const absolute = await execute(
      ["graph", "stats", "--root", repositoryRoot, "--input", outsideGraph],
      repositoryRoot,
    );
    expect(absolute.exitCode).toBe(EXIT_CODES.validation);
    expect(absolute.stderr).toContain(
      "Graph input must remain inside the repository root",
    );

    const traversal = await execute(
      [
        "graph",
        "stats",
        "--root",
        repositoryRoot,
        "--input",
        relative(repositoryRoot, outsideGraph),
      ],
      repositoryRoot,
    );
    expect(traversal.exitCode).toBe(EXIT_CODES.validation);
    expect(traversal.stderr).toContain("repository root");
  });

  it("uses correct Windows and POSIX containment semantics", () => {
    expect(
      isGraphPathInsideRepository(
        "C:\\Work\\Repo",
        "c:\\work\\repo\\.fuzit\\graph.json",
      ),
    ).toBe(true);
    expect(
      isGraphPathInsideRepository("C:\\Work\\Repo", "D:\\graph.json"),
    ).toBe(false);
    expect(
      isGraphPathInsideRepository("/work/repo", "/work/repo/.fuzit/graph.json"),
    ).toBe(true);
    expect(isGraphPathInsideRepository("/work/repo", "/work/graph.json")).toBe(
      false,
    );
  });

  it("builds graph statistics directly from a repository", async () => {
    const result = await run(["--json", "graph", "stats"]);
    expect(result.exitCode).toBe(0);
    expect(JSON.parse(result.stdout)).toMatchObject({
      schemaVersion: 1,
      nodes: expect.any(Number),
      edges: expect.any(Number),
    });
    expect(result.stderr).toBe("");
  });

  it("returns deterministic JSON stats and human neighbors", async () => {
    const stats = await run([
      "--json",
      "graph",
      "stats",
      "--input",
      "graph.json",
    ]);
    expect(stats.exitCode).toBe(0);
    expect(JSON.parse(stats.stdout)).toMatchObject({
      schemaVersion: 1,
      nodes: 2,
      edges: 1,
    });
    expect(stats.stderr).toBe("");
    const repositoryNode = stats.graph.nodes.find(
      (node) => node.kind === "repository",
    )!;
    const neighbors = await run([
      "graph",
      "neighbors",
      repositoryNode.id,
      "--input",
      "graph.json",
    ]);
    expect(neighbors.exitCode).toBe(0);
    expect(neighbors.stdout).toContain("FILE: src/a.ts");
    expect(neighbors.stderr).toContain("Finding graph neighbors");
    expect(neighbors.stderr).toContain("graph complete");
  });

  it("routes partial diagnostics to stderr and preserves safe stdout", async () => {
    const result = await run(
      ["graph", "query", "--input", "graph.json", "--kind", "file"],
      true,
    );
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("FILE: src/a.ts");
    expect(result.stderr).toContain(
      "warning GRAPH.PARTIAL: parser unavailable\n",
    );
    expect(result.stderr).toContain("Querying repository graph");
    expect(result.stderr).toContain("graph complete");
  });

  it("uses validation exit codes for bounds and root escape", async () => {
    const bounded = await run([
      "graph",
      "query",
      "--input",
      "graph.json",
      "--limit",
      "1001",
    ]);
    expect(bounded.exitCode).toBe(EXIT_CODES.validation);
    expect(bounded.stdout).toBe("");
    expect(bounded.stderr).toContain("item limit");
    const escaped = await run(["graph", "stats", "--input", "../graph.json"]);
    expect(escaped.exitCode).toBe(EXIT_CODES.validation);
    expect(escaped.stderr).toContain("repository root");
  });

  it("graph stats human mode shows statistics, not graph-build output", async () => {
    const result = await run(["graph", "stats", "--input", "graph.json"]);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Graph Statistics");
    expect(result.stdout).toContain("Nodes");
    expect(result.stdout).toContain("Edges");
    expect(result.stdout).toContain("Node kinds");
    expect(result.stdout).not.toContain("Graph built");
  });

  it("graph stats --json preserves existing JSON shape (no kind field)", async () => {
    const result = await run(["--json", "graph", "stats", "--input", "graph.json"]);
    expect(result.exitCode).toBe(0);
    const parsed = JSON.parse(result.stdout);
    expect(parsed).toMatchObject({ schemaVersion: 1, nodes: 2, edges: 1 });
    expect(parsed.kind).toBeUndefined();
    expect(result.stderr).toBe("");
  });

  it("graph build human mode shows polished graph-build box", async () => {
    const invocationRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-build-human-"));
    const repositoryRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-build-repo-"));
    await mkdir(join(repositoryRoot, ".git"));
    await mkdir(join(repositoryRoot, "src"));
    await writeFile(join(repositoryRoot, "src", "b.ts"), "export {};");
    const graphPath = join(repositoryRoot, ".fuzit-build-test.json");

    const built = await execute(
      ["graph", "build", "--root", repositoryRoot, "--output", graphPath],
      invocationRoot,
    );
    expect(built.exitCode).toBe(0);
    expect(built.stdout).toContain("Repository Graph");
    expect(built.stdout).toContain("Nodes");
    expect(built.stdout).toContain("Output");
    expect(() => JSON.parse(built.stdout)).toThrow();
  });

  it("graph build --json preserves existing JSON shape (no kind field)", async () => {
    const invocationRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-build-json-"));
    const repositoryRoot = await mkdtemp(join(tmpdir(), "fuzit-graph-build-json-repo-"));
    await mkdir(join(repositoryRoot, ".git"));
    await writeFile(join(repositoryRoot, "c.ts"), "export {};");
    const graphPath = join(repositoryRoot, ".fuzit-json-build.json");

    const built = await execute(
      ["--json", "graph", "build", "--root", repositoryRoot, "--output", graphPath],
      invocationRoot,
    );
    expect(built.exitCode).toBe(0);
    const parsed = JSON.parse(built.stdout);
    expect(typeof parsed.output).toBe("string");
    expect(typeof parsed.nodes).toBe("number");
    expect(typeof parsed.edges).toBe("number");
    expect(typeof parsed.completeness).toBe("string");
    expect(parsed.kind).toBeUndefined();
    expect(built.stderr).toBe("");
  });
});

import { describe, expect, it } from "vitest";

import {
  box,
  formatGraphBuild,
  formatGraphStats,
  formatHumanValue,
  resolveTheme,
} from "../src/output/presentation.js";

const ascii = resolveTheme({ color: false, unicode: false });
const unicode = resolveTheme({ color: false, unicode: true });

// ---------------------------------------------------------------------------
// box() — border rendering
// ---------------------------------------------------------------------------

describe("box() border rendering", () => {
  it("ASCII: top border uses - repeated to full width", () => {
    const output = box(ascii, "TITLE", ["body"]);
    const lines = output.split("\n");
    // "+---...---+" where interior width >= title.length + 2
    expect(lines[0]).toMatch(/^\+[-]+\+$/);
    // width must match body lines
    expect(lines[0].length).toBe(lines[1].length);
  });

  it("ASCII: bottom border uses - repeated to full width", () => {
    const output = box(ascii, "TITLE", ["body"]);
    const lines = output.split("\n");
    const lastLine = lines[lines.length - 1];
    expect(lastLine).toMatch(/^\+[-]+\+$/);
    expect(lastLine.length).toBe(lines[0].length);
  });

  it("Unicode: top border repeats ─ to the full width", () => {
    const output = box(unicode, "TITLE", ["body"]);
    const lines = output.split("\n");
    const top = lines[0];
    // must start with ╭ and end with ╮
    expect(top.startsWith("╭")).toBe(true);
    expect(top.endsWith("╮")).toBe(true);
    // the fill between ╭ and ╮ must be all ─ (U+2500)
    const fill = top.slice(1, -1);
    expect(fill).toMatch(/^─+$/);
    // fill length must equal the body/title width
    const bodyLine = lines[2]; // "│ body... │"
    expect(top.length).toBe(bodyLine.length);
  });

  it("Unicode: bottom border repeats ─ to the full width", () => {
    const output = box(unicode, "TITLE", ["body"]);
    const lines = output.split("\n");
    const bottom = lines[lines.length - 1];
    expect(bottom.startsWith("╰")).toBe(true);
    expect(bottom.endsWith("╯")).toBe(true);
    const fill = bottom.slice(1, -1);
    expect(fill).toMatch(/^─+$/);
    // bottom must equal top in length
    expect(bottom.length).toBe(lines[0].length);
  });

  it("Unicode: wider body line drives border width, not title", () => {
    const longBody = "a very long body line that exceeds the title length";
    const output = box(unicode, "Short", [longBody]);
    const lines = output.split("\n");
    const top = lines[0];
    const fill = top.slice(1, -1);
    // fill should be at least as long as the body line
    expect(fill.length).toBeGreaterThanOrEqual(longBody.length);
  });

  it("Unicode: content does not overflow the border width", () => {
    const body = ["short", "a longer line here", "medium length"];
    const output = box(unicode, "Test Title", body);
    const lines = output.split("\n");
    const topWidth = lines[0].length;
    // every line must have the same width
    for (const line of lines) {
      expect(line.length).toBe(topWidth);
    }
  });

  it("ASCII: all lines have equal width", () => {
    const body = ["short", "a longer body line to test alignment"];
    const output = box(ascii, "Title", body);
    const lines = output.split("\n");
    const topWidth = lines[0].length;
    for (const line of lines) {
      expect(line.length).toBe(topWidth);
    }
  });
});

