      redactions: { findings: 0, redactedItems: 0, omittedItems: 0 },
      output: "/out.md",
    }, ascii)!;
    expect(output).toContain("Fuzit · Repository Pack");
    const count = (output.match(/Repository Pack/g) ?? []).length;
    expect(count).toBe(1);
