    )!;
    expect(result).not.toBeNull();
    expect(result).toContain("Environment Check");
    expect(result).toContain("PASS node: Node version 20.0.0");
  });

  it("formats git status", () => {
    const result = formatHumanValue(
      {
        schemaVersion: 1,
        changes: [{ path: "src/main.ts", kind: "modified" }],
      },
      ascii,
    )!;
    expect(result).toContain("Git Status");
    expect(result).toContain("src/main.ts");
  });

  it("formats git log", () => {
    const result = formatHumanValue(
      {
        schemaVersion: 1,
        entries: [
          { hash: "abc123456789", author: "Alice", message: "feat: add CLI" },
        ],
      },
      ascii,
    )!;
    expect(result).toContain("Git Log");
    expect(result).toContain("abc12345");
    expect(result).toContain("Alice");
  });

  it("formats config show", () => {
    const result = formatHumanValue(
      {
        schemaVersion: 1,
        values: { maxFiles: 120, outputFormat: "markdown" },
        provenance: { maxFiles: "default", outputFormat: "cli" },
      },
      ascii,
    )!;
    expect(result).toContain("Effective Configuration");
    expect(result).toContain("maxFiles");
    expect(result).toContain("120");
  });

  it("formats context result", () => {
    const result = formatHumanValue(
      {
        output: "/tmp/context.md",
        selected: ["a.ts", "b.ts"],
        report: { budgetTokens: 1000, usedTokens: 500 },
      },
      ascii,
    )!;
    expect(result).toContain("Task Context");
    expect(result).toContain("Selected files     2");
  });

  it("formats review metadata and findings cleanly", () => {
    const result = formatHumanValue(
      {
        kind: "review",
        repository: "fuzit/fuzit",
        prNumber: 99,
        title: "Fix box borders",
        state: "open",
        author: "bob",
        baseRef: "main",
        headRef: "patch-1",
        findings: [
          { severity: "warning", message: "Missing error check" },
        ],
      },
      ascii,
    )!;
    expect(result).toContain("fuzit/fuzit");
    expect(result).toContain("#99");
    expect(result).toContain("Fix box borders");
    expect(result).toContain("main ← patch-1");
    expect(result).toContain("WARNING Missing error check");
  });
});

// ---------------------------------------------------------------------------
// P2 Box hardening: Display width & Windows paths
// ---------------------------------------------------------------------------

describe("P2 Box hardening and width safety", () => {
  it("truncates extremely long paths so box border does not exceed MAX_BOX_INNER_WIDTH", () => {
    const longPath = "C:\\Users\\very-long-user-name\\AppData\\Local\\Deeply\\Nested\\Directory\\Path\\That\\Is\\Extremely\\Long\\Project\\File.ts";
    const result = formatHumanValue(
      {
        kind: "review",
        repository: longPath,
        prNumber: 1,
      },
      ascii,
    )!;
    const lines = result.split("\n");
    const topWidth = lines[0].length;
    // max inner width is 76, total line length including borders (+ 4) is 80
    expect(topWidth).toBeLessThanOrEqual(80);
    for (const line of lines) {
      expect(line.length).toBe(topWidth);
    }
  });

  it("safely handles Windows backslashes in path fields", () => {
    const winPath = "C:\\projects\\fuzit\\apps\\cli\\src\\index.ts";
    const result = formatHumanValue(
      {
        output: winPath,
        selected: [winPath],
        report: { budgetTokens: 500, usedTokens: 200 },
      },
      ascii,
    )!;
    expect(result).toContain("C:\\projects\\fuzit\\apps");
  });
});

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

import { runCli } from "../src/cli.js";

async function help(arguments_: readonly string[]): Promise<string> {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli([...arguments_, "--help"], {
    writeOut: (value) => {
      stdout += value;
    },
    writeErr: (value) => {
      stderr += value;
    },
  });
  expect({ exitCode, stderr }).toEqual({ exitCode: 0, stderr: "" });
  return stdout;
}

describe("core CLI reference", () => {
  it("tracks every documented core command and option", async () => {
    const reference = await readFile(
      resolve(import.meta.dirname, "../../../docs/reference/cli.md"),
      "utf8",
    );
    const surfaces = [
      { args: [], tokens: ["--version", "--json", "--quiet", "--debug"] },
      { args: ["init"], tokens: ["--dry-run", "--force"] },
      {
        args: ["scan"],
        tokens: [
          "--root",
          "--list-roots",
          "--paths",
          "--metadata",
          "--items",
          "--content",
          "--summary",
          "--include",
          "--exclude",
          "--explain-path",
        ],
      },
      {
        args: ["pack"],
        tokens: [
          "--format",
          "--output",
          "--root",
          "--dry-run",
          "--git",
          "--since",
        ],
      },
      {
        args: ["context"],
        tokens: [
          "--task",
          "--profile",
          "--budget-tokens",
          "--format",
          "--output",
          "--root",
          "--no-index",
          "--explain",
        ],
      },
      { args: ["diff"], tokens: ["--json", "<snapshot-a>", "<snapshot-b>"] },
    ] as const;

    for (const { args, tokens } of surfaces) {
      const output = await help(args);
      for (const token of tokens) {
        expect(output, `${args.join(" ") || "root"} help`).toContain(token);
        expect(reference, `reference for ${token}`).toContain(token);
      }
    }
  });

  it("names each core command and stable exit code", async () => {
    const reference = await readFile(
      resolve(import.meta.dirname, "../../../docs/reference/cli.md"),
      "utf8",
    );
    const rootHelp = await help([]);
    for (const command of [
      "config",
      "doctor",
      "init",
      "scan",
      "pack",
      "git",
      "cache",
      "snapshot",
      "diff",
      "profile",
      "context",
      "explain",
    ]) {
      expect(rootHelp).toMatch(new RegExp(`\\n  ${command}(?: |\\n)`));
      expect(reference).toContain(`fuzit ${command}`);
    }
    for (const code of [0, 2, 3, 4, 70, 130]) {
      expect(reference).toContain(`| \`${code}\` |`);
    }
  });
});

import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import {
  compressCodeContent,
  removeComments,
  removeEmptyLines,
  addLineNumbers,
  transformCodeContent,
  parseByteSize,
  splitPackedOutput,
} from "@fuzit/core";
import { runCli } from "../src/cli.js";

async function captureRun(args: readonly string[], root: string) {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(
    args,
    {
      writeOut: (val) => {
        stdout += val;
      },
      writeErr: (val) => {
        stderr += val;
      },
    },
    { repositoryRoot: root, environment: {} },
  );
  return { exitCode, stdout, stderr };
}

describe("Repomix Gaps Feature Suite", () => {
  describe("Code transformations & compression", () => {
    it("removeComments strips single and multi-line comments", () => {
      const code = `// header comment\nfunction test() {\n  /* inner comment */\n  return 42;\n}`;
      const cleaned = removeComments(code, "test.ts");
      expect(cleaned).not.toContain("header comment");
      expect(cleaned).not.toContain("inner comment");
      expect(cleaned).toContain("function test()");
    });

    it("removeEmptyLines removes blank lines", () => {
      const code = "a\n\n\nb\n\nc";
      const cleaned = removeEmptyLines(code);
      expect(cleaned).toBe("a\nb\nc");
    });

    it("addLineNumbers prepends 1-indexed line numbers", () => {
      const code = "first\nsecond";
      const numbered = addLineNumbers(code);
      expect(numbered).toContain("1 | first");
      expect(numbered).toContain("2 | second");
    });

    it("compressCodeContent skeletonizes code bodies", () => {
      const code = `export function add(a: number, b: number): number {\n  const res = a + b;\n  return res;\n}`;
      const compressed = compressCodeContent(code, "math.ts");
      expect(compressed).toContain("export function add");
      expect(compressed).toContain("implementation hidden");
      expect(compressed).not.toContain("const res = a + b");
    });
  });

  describe("Split output & size parsing", () => {
    it("parseByteSize handles kb, mb, and raw bytes", () => {
      expect(parseByteSize("500kb")).toBe(500 * 1024);
      expect(parseByteSize("1mb")).toBe(1024 * 1024);
      expect(parseByteSize("1000")).toBe(1000);
    });

    it("splitPackedOutput chunks large content into multiple output files", () => {
      const content = "line 1\nline 2\nline 3\nline 4\nline 5";
      const chunks = splitPackedOutput(content, "/tmp/out.md", 15);
      expect(chunks.length).toBeGreaterThan(1);
      expect(chunks[0]!.filename).toContain("_part1.md");
    });
  });

  describe("Pack CLI command extensions", () => {
    it("filters files by --include and --ignore patterns", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-pack-patterns-"));
      try {
        await writeFile(join(root, "app.ts"), "export const a = 1;");
        await writeFile(join(root, "test.spec.ts"), "describe('test', () => {});");

        const result = await captureRun(
          ["--json", "pack", "--root", root, "--format", "markdown", "--output", "-", "--ignore", "*.spec.ts"],
          root,
        );

        expect(result.exitCode).toBe(0);
        expect(result.stdout).toContain("app.ts");
        expect(result.stdout).not.toContain("## test.spec.ts");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });

    it("supports code transformation flags on pack", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-pack-transform-"));
      try {
        await writeFile(
          join(root, "service.ts"),
          "// comment\nexport function service() {\n  return 'ok';\n}",
        );

        const result = await captureRun(
          ["--json", "pack", "--root", root, "--format", "markdown", "--output", "-", "--remove-comments", "--line-numbers"],
          root,
        );

        expect(result.exitCode).toBe(0);
        expect(result.stdout).not.toContain("// comment");
        expect(result.stdout).toContain("1 |");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });
    it("supports zero-argument dual-packing into fuzit-pack.md and fuzit-pack.xml", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-zero-arg-"));
      try {
        await writeFile(join(root, "main.ts"), "console.log('hello');");
        const result = await captureRun(["--json"], root);
        expect(result.exitCode).toBe(0);
        const mdExists = await readFile(join(root, "fuzit-pack.md"), "utf8");
        const xmlExists = await readFile(join(root, "fuzit-pack.xml"), "utf8");
        expect(mdExists).toContain("main.ts");
        expect(xmlExists).toContain("<contextBundle");
        expect(xmlExists).toContain('<file path="main.ts"');
        expect(xmlExists).toContain("console.log(&apos;hello&apos;);");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });

    it("supports --instruction option prepending system prompt to bundle", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-instruction-"));
      try {
        await writeFile(join(root, "api.ts"), "export const get = () => {};");
        const result = await captureRun(
          ["--json", "pack", "--root", root, "--format", "markdown", "--output", "-", "--instruction", "Focus on REST API"],
          root,
        );
        expect(result.exitCode).toBe(0);
        expect(result.stdout).toContain("Focus on REST API");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });
  });

  describe("MCP and Agent Skills CLI extension", () => {
    it("plugin mcp returns MCP server configuration", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-mcp-"));
      try {
        const result = await captureRun(["--json", "plugin", "mcp"], root);
        expect(result.exitCode).toBe(0);
        const parsed = JSON.parse(result.stdout) as { mcpServers: { fuzit: { command: string } } };
        expect(parsed.mcpServers.fuzit.command).toBe("fuzit");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });

    it("init --mcp initializes MCP config and Agent Skills", async () => {
      const root = await mkdtemp(join(tmpdir(), "fuzit-init-mcp-"));
      try {
        const result = await captureRun(["init", "--mcp", "--dry-run"], root);
        expect(result.exitCode).toBe(0);
        expect(result.stdout).toContain(".vscode/mcp.json");
        expect(result.stdout).toContain(".agents/skills/fuzit-pack/SKILL.md");
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });
  });
});

import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import { CLI_VERSION, runCli } from "../src/cli.js";

async function scan(root: string, mode = "--items", json = false) {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(
    json
      ? ["--json", "scan", "--root", root, mode]
      : ["scan", "--root", root, mode],
    {
      writeOut: (value) => {
        stdout += value;
      },
      writeErr: (value) => {
        stderr += value;
      },
    },
    { repositoryRoot: root, environment: {} },
  );
  return { exitCode, stdout, stderr };
}

async function capture(root: string, args: readonly string[]) {
  let stdout = "";
  let stderr = "";
  const exitCode = await runCli(
    args,
    {
      writeOut: (value) => (stdout += value),
      writeErr: (value) => (stderr += value),
    },
    { repositoryRoot: root, environment: {} },
  );
  return { exitCode, stdout, stderr };
}

describe("scan baseline", () => {
  it("shows restrained progress in human mode and suppresses it for JSON", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-progress-scan-"));
    await writeFile(join(root, "app.ts"), "export {};");
    let stdout = "";
    let stderr = "";
    const exitCode = await runCli(
      ["scan", "--root", root],
      {
        writeOut: (value) => (stdout += value),
        writeErr: (value) => (stderr += value),
      },
      { repositoryRoot: root, environment: {} },
    );
    expect(exitCode).toBe(0);
    expect(stdout).toContain("Fuzit · Repository Scan");
    expect(stdout).toContain("Status");
    expect(stderr).toContain(`Fuzit v${CLI_VERSION} · Scanning repository...`);
    expect(stderr).toContain("scan complete");

    const machine = await scan(root, "--summary", true);
    expect(machine.stderr).toBe("");
    expect(() => JSON.parse(machine.stdout)).not.toThrow();
  });

  it("uses a useful summary for a bare scan", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-default-scan-"));
    await writeFile(join(root, "app.jsx"), "export const App = () => null;");
    const result = await scan(root, "");

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Fuzit · Repository Scan");
    expect(result.stdout).toContain("Files");
    expect(result.stdout).toContain("Status");
  });

  it("keeps the default summary useful in quiet mode", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-quiet-scan-"));
    await writeFile(join(root, "app.ts"), "export {};");
    const result = await capture(root, ["--quiet", "scan", "--root", root]);

    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(result.stdout).toContain("Fuzit · Repository Scan");
    expect(result.stdout).toContain("Status");
  });

  it("preserves explicit root listing", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-roots-scan-"));
    await mkdir(join(root, ".git"));
    const result = await capture(root, [
      "--json",
      "scan",
      "--root",
      root,
      "--list-roots",
    ]);

    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(JSON.parse(result.stdout)).toEqual({
      schemaVersion: 1,
      selectedRoot: ".",
      nestedRoots: [],
      inputWasSymlink: false,
    });
  });

  it("rejects conflicting explicit scan modes", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-mode-scan-"));
    const result = await capture(root, [
      "scan",
      "--root",
      root,
      "--summary",
      "--list-roots",
    ]);

    expect(result.exitCode).toBe(2);
    expect(result.stdout).toBe("");
    expect(result.stderr).toContain("SCAN.MODE_CONFLICT");
    expect(result.stderr).toContain("--summary, --list-roots");
  });

  it("rejects a missing repository root", async () => {
    const parent = await mkdtemp(join(tmpdir(), "fuzit-missing-scan-"));
    const result = await capture(parent, [
      "scan",
      "--root",
      join(parent, "missing"),
    ]);

    expect(result.exitCode).toBe(2);
    expect(result.stdout).toBe("");
    expect(result.stderr).toContain("SCAN.INVALID_ROOT");
  });

  it("handles an empty repository", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-empty-"));
    expect(await scan(root, "--summary", true)).toMatchObject({
      exitCode: 0,
      stderr: "",
    });
  });

  it("handles a large synthetic repository deterministically", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-large-"));
    await Promise.all(
      Array.from({ length: 100 }, (_, index) =>
        writeFile(join(root, `${index.toString().padStart(3, "0")}.txt`), "x"),
      ),
    );

    expect((await scan(root)).stdout).toBe((await scan(root)).stdout);
  }, 30_000);

  it("keeps JSON output free of TTY progress", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-json-"));
    await writeFile(join(root, "a.txt"), "x");
    const result = await scan(root, "--summary", true);

    expect(result.stderr).toBe("");
    expect(() => JSON.parse(result.stdout.trim())).not.toThrow();
  });
});

