#!/usr/bin/env node

import { MCP_SERVER_VERSION } from "./config.js";
import { startMcpServer } from "./server.js";

const roots = process.argv.slice(2);

if (roots.length === 0) {
  process.stderr.write(
    `fuzit-mcp v${MCP_SERVER_VERSION}: usage: fuzit-mcp <root1> [root2...]\n`,
  );
  process.exit(1);
}

await startMcpServer({ allowedRoots: roots });

import { isAbsolute, relative, resolve } from "node:path";

export const MCP_SERVER_VERSION = "0.0.1";
export const MCP_PROTOCOL_VERSION = "1";

/** Maximum allowed workspace roots per session */
export const MAX_ALLOWED_ROOTS = 8;

/** Maximum tool output payload in bytes */
export const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MB

/** Maximum inbound JSON-RPC request line in bytes */
export const MAX_REQUEST_BYTES = 1024 * 1024;

/** Maximum normalized task description in bytes */
export const MAX_TASK_BYTES = 2048;

/** Maximum duration for any single tool call (ms) */
export const MAX_TOOL_DURATION_MS = 30_000;

/** Maximum number of files returned in a single search result */
export const MAX_SEARCH_RESULTS = 200;

/** Maximum graph traversal depth */
export const MAX_GRAPH_DEPTH = 4;

/** Maximum graph nodes returned */
export const MAX_GRAPH_NODES = 300;

/**
 * Canonicalize and validate an absolute path.
 * Throws if path is not absolute.
 */
export function canonicalizePath(p: string): string {
  if (!isAbsolute(p)) throw new TypeError("path must be absolute");
  return resolve(p);
}

function comparablePath(path: string): string {
  return process.platform === "win32" ? path.toLowerCase() : path;
}

/**
 * Check that a candidate path is strictly within one of the allowed roots.
 * Returns the matching root, or throws if no root matches.
 */
export function assertWithinAllowedRoots(
  candidate: string,
  allowedRoots: readonly string[],
): string {
  const abs = canonicalizePath(candidate);
  for (const root of allowedRoots) {
    const canonRoot = canonicalizePath(root);
    const rel = relative(comparablePath(canonRoot), comparablePath(abs));
    if (rel === "" || (!rel.startsWith("..") && !isAbsolute(rel))) {
      return abs;
    }
  }
  throw new RangeError(
    `Path "${candidate}" is not within any allowed workspace root.`,
  );
}

export interface McpServerPackageBoundary {
  readonly packageName: "@fuzit/mcp-server";
}

import { pathToFileURL } from "node:url";
import { resolve } from "node:path";

import { startMcpServer } from "./server.js";
import { MCP_SERVER_VERSION } from "./config.js";

export { startMcpServer } from "./server.js";
export {
  MCP_SERVER_VERSION,
  MCP_PROTOCOL_VERSION,
  MAX_ALLOWED_ROOTS,
  MAX_OUTPUT_BYTES,
  MAX_TOOL_DURATION_MS,
  MAX_SEARCH_RESULTS,
  MAX_GRAPH_DEPTH,
  MAX_GRAPH_NODES,
  canonicalizePath,
  assertWithinAllowedRoots,
} from "./config.js";
export {
  runTool,
  boundPayload,
  validateRoot,
  withTimeout,
  type McpCallContext,
  type McpToolResult,
} from "./tool-runner.js";
export {
  validateAllowedRoots,
  validatePath,
  WorkspaceCache,
  type RepositoryAcquisition,
} from "./workspace.js";

export interface McpServerPackageBoundary {
  readonly packageName: "@fuzit/mcp-server";
}

// CLI entry point
if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  const roots = process.argv.slice(2);
  if (roots.length === 0) {
    process.stderr.write(
      `fuzit-mcp v${MCP_SERVER_VERSION}: usage: node dist/index.js <root1> [root2...]\n`,
    );
    process.exit(1);
  }
  await startMcpServer({ allowedRoots: roots });
}

import { MCP_SERVER_VERSION } from "./config.js";
import { StdioTransport, serverInfo } from "./transport.js";
import { validateAllowedRoots, WorkspaceCache } from "./workspace.js";
import { fuzitStatus, fuzitProfiles } from "./tools/status.js";
import { fuzitSearch, fuzitGetContext } from "./tools/context.js";
import { fuzitExplainSelection } from "./tools/explain.js";
import { fuzitGraphNeighbors, fuzitGraphImpact } from "./tools/graph.js";
import { fuzitRecentChanges } from "./tools/changes.js";
import { fuzitCreateBundle } from "./tools/bundle.js";

/** Valid tool names */
const TOOL_NAMES = [
  "fuzit_status",
  "fuzit_profiles",
  "fuzit_search",
  "fuzit_get_context",
  "fuzit_explain_selection",
  "fuzit_graph_neighbors",
  "fuzit_graph_impact",
  "fuzit_recent_changes",
  "fuzit_create_bundle",
] as const;

type ToolName = (typeof TOOL_NAMES)[number];

export interface McpServerOptions {
  readonly allowedRoots: readonly string[];
}

export async function startMcpServer(options: McpServerOptions): Promise<void> {
  const allowedRoots = await validateAllowedRoots(options.allowedRoots);
  const cache = new WorkspaceCache();

  const context = { allowedRoots };

  const transport = new StdioTransport(async (method, params) => {
    // Initialization / capabilities
    if (method === "initialize") {
      return {
        serverInfo: serverInfo(),
        capabilities: { tools: {} },
      };
    }

    // List tools
    if (method === "tools/list") {
      return {
        tools: TOOL_NAMES.map((name) => ({
          name,
          description: getToolDescription(name),
          inputSchema: getToolInputSchema(name),
        })),
      };
    }

    // Tool call dispatch
    if (method === "tools/call") {
      const p = params as { name: string; arguments: unknown };
      const toolName = p?.name as ToolName | undefined;
      const args = (p?.arguments ?? {}) as Record<string, unknown>;

      if (!toolName || !TOOL_NAMES.includes(toolName as ToolName)) {
        throw new Error(`Unknown tool: ${toolName}`);
      }

      switch (toolName) {
        case "fuzit_status":
          return fuzitStatus(args["root"], context);
        case "fuzit_profiles":
          return fuzitProfiles(context);
        case "fuzit_search":
          return fuzitSearch(
            args as Parameters<typeof fuzitSearch>[0],
            context,
            cache,
          );
        case "fuzit_get_context":
          return fuzitGetContext(
            args as Parameters<typeof fuzitGetContext>[0],
            context,
            cache,
          );
        case "fuzit_explain_selection":
          return fuzitExplainSelection(
            args as Parameters<typeof fuzitExplainSelection>[0],
            context,
            cache,
          );
        case "fuzit_graph_neighbors":
          return fuzitGraphNeighbors(
            args as Parameters<typeof fuzitGraphNeighbors>[0],
            context,
            (root) => cache.getSnapshot(root),
          );
        case "fuzit_graph_impact":
          return fuzitGraphImpact(
            args as Parameters<typeof fuzitGraphImpact>[0],
            context,
            (root) => cache.getSnapshot(root),
          );
        case "fuzit_recent_changes":
          return fuzitRecentChanges(
            args as Parameters<typeof fuzitRecentChanges>[0],
            context,
          );
        case "fuzit_create_bundle":
          return fuzitCreateBundle(
            args as Parameters<typeof fuzitCreateBundle>[0],
            context,
            cache,
          );
      }
    }

    // Notifications do not return results
    if (method.startsWith("notifications/")) {
      return null;
    }

    throw new Error(`Method not supported: ${method}`);
  });

  process.stderr.write(
    `[fuzit-mcp] v${MCP_SERVER_VERSION} starting (roots: ${allowedRoots.length})\n`,
  );

  transport.start();
}

function getToolDescription(name: ToolName): string {
  switch (name) {
    case "fuzit_status":
      return "Run Fuzit doctor checks for the given workspace root.";
    case "fuzit_profiles":
      return "List available Fuzit context profiles.";
    case "fuzit_search":
      return "Search repository files by task relevance.";
    case "fuzit_get_context":
      return "Get full task context for a given workspace root and task description.";
    case "fuzit_explain_selection":
      return "Explain why files were selected or excluded for a given task.";
    case "fuzit_graph_neighbors":
      return "Get bounded graph neighborhood of a file.";
    case "fuzit_graph_impact":
      return "Get bounded impact set of files affected by a change.";
    case "fuzit_recent_changes":
      return "Get recent Git commits for the workspace root.";
    case "fuzit_create_bundle":
      return "Create a context bundle file within the workspace root.";
  }
}

function getToolInputSchema(name: ToolName): object {
  const withRoot = {
    type: "object" as const,
    required: ["root"],
    properties: {
      root: { type: "string", description: "Absolute workspace root path." },
    },
    additionalProperties: true,
  };

  switch (name) {
    case "fuzit_status":
    case "fuzit_recent_changes":
      return withRoot;
    case "fuzit_profiles":
      return { type: "object" as const, properties: {} };
    default:
      return withRoot;
  }
}

import {
  MAX_OUTPUT_BYTES,
  MAX_TASK_BYTES,
  MAX_TOOL_DURATION_MS,
  assertWithinAllowedRoots,
} from "./config.js";
import { redactSensitiveText } from "@fuzit/security";

export type McpToolResult =
  | { readonly ok: true; readonly payload: unknown }
  | { readonly ok: false; readonly error: string; readonly code: string };

export interface McpCallContext {
  readonly allowedRoots: readonly string[];
  readonly abortSignal?: AbortSignal;
}

export function validateTask(task: unknown): string {
  if (typeof task !== "string" || task.trim().length === 0)
    throw new TypeError("task must be a non-empty string");
  if (Buffer.byteLength(task, "utf8") > MAX_TASK_BYTES)
    throw new RangeError(`task exceeds ${MAX_TASK_BYTES} byte limit`);
  return redactSensitiveText(task, MAX_TASK_BYTES);
}

/**
 * Validate that a root argument is a non-empty string within allowed roots.
 */
export async function validateRoot(
  root: unknown,
  context: McpCallContext,
): Promise<string> {
  if (typeof root !== "string" || root.trim().length === 0) {
    throw new TypeError("root must be a non-empty string");
  }
  const canonical = await realpath(root);
  const matched = assertWithinAllowedRoots(canonical, context.allowedRoots);
  const exact = context.allowedRoots.some((allowed) =>
    process.platform === "win32"
      ? allowed.toLowerCase() === matched.toLowerCase()
      : allowed === matched,
  );
  if (!exact) throw new RangeError(`Unknown workspace root: ${root}`);
  return matched;
}

/**
 * Truncate a JSON-serialisable payload if it exceeds the output size limit.
 */
export function boundPayload(payload: unknown): unknown {
  const serialized = JSON.stringify(payload);
  if (Buffer.byteLength(serialized) <= MAX_OUTPUT_BYTES) return payload;
  return {
    truncated: true,
    bytes: Buffer.byteLength(serialized),
    limit: MAX_OUTPUT_BYTES,
    message: "Response payload exceeded output size limit and was truncated.",
  };
}

/**
 * Run a tool handler with a timeout and optional AbortSignal.
 */
export async function withTimeout<T>(
  handler: (signal: AbortSignal) => Promise<T>,
  signal?: AbortSignal,
  timeoutMs = MAX_TOOL_DURATION_MS,
): Promise<T> {
  if (signal?.aborted) {
    throw signal.reason ?? new Error("tool cancelled");
  }

  const controller = new AbortController();
  const onAbort = () => {
    controller.abort(signal?.reason ?? new Error("tool cancelled"));
  };
  signal?.addEventListener("abort", onAbort, { once: true });

  const timer = setTimeout(
    () => controller.abort(new Error("tool timeout")),
    timeoutMs,
  );

  const abortPromise = new Promise<never>((_, reject) => {
    if (controller.signal.aborted) {
      reject(controller.signal.reason);
      return;
    }
    controller.signal.addEventListener(
      "abort",
      () => reject(controller.signal.reason),
      { once: true },
    );
  });

  try {
    return await Promise.race([handler(controller.signal), abortPromise]);
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener("abort", onAbort);
  }
}

/**
 * Wrap a tool call to produce a structured McpToolResult, catching errors.
 */
export async function runTool(
  handler: () => Promise<unknown>,
): Promise<McpToolResult> {
  try {
    const payload = await handler();
    return { ok: true, payload: boundPayload(payload) };
  } catch (error) {
    const message = redactSensitiveText(
      error instanceof Error ? error.message : String(error),
    );
    const code =
      error instanceof RangeError
        ? "RANGE_ERROR"
        : error instanceof TypeError
          ? "TYPE_ERROR"
          : "INTERNAL_ERROR";
    return { ok: false, error: message, code };
  }
}
import { realpath } from "node:fs/promises";

import { writeFile, mkdir } from "node:fs/promises";
import { join } from "node:path";

import { assertWithinAllowedRoots } from "../config.js";
import {
  type McpCallContext,
  runTool,
  validateRoot,
  validateTask,
} from "../tool-runner.js";
import type { RepositoryAcquisition } from "../workspace.js";
import { getProfile } from "@fuzit/profiles";
import { createTaskContext, renderTaskContext } from "@fuzit/core";

const ALLOWED_FORMATS = ["markdown", "json", "text", "xml"] as const;
type BundleFormat = (typeof ALLOWED_FORMATS)[number];

/**
 * fuzit_create_bundle — creates a context bundle file within the workspace root.
 * Output is written to a bounded, approved directory under the workspace root.
 */
export async function fuzitCreateBundle(
  args: {
    root: unknown;
    task: unknown;
    profile?: unknown;
    budgetTokens?: unknown;
    format?: unknown;
    outputSubpath?: unknown;
  },
  context: McpCallContext,
  acquisition: RepositoryAcquisition,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    const task = validateTask(args.task);

    const profileId =
      typeof args.profile === "string" && args.profile.trim().length > 0
        ? args.profile.trim()
        : "feature-development";

    const budget =
      typeof args.budgetTokens === "number" && args.budgetTokens > 0
        ? Math.floor(args.budgetTokens)
        : 8000;

    const format: BundleFormat =
      typeof args.format === "string" &&
      ALLOWED_FORMATS.includes(args.format as BundleFormat)
        ? (args.format as BundleFormat)
        : "markdown";

    // Output must stay within workspace root under .fuzit-bundles/
    const outputSubpath =
      typeof args.outputSubpath === "string" &&
      args.outputSubpath.trim().length > 0
        ? args.outputSubpath.trim()
        : `bundle-${Date.now()}.${format === "markdown" ? "md" : format}`;

    // Validate the output path stays within the workspace root
    const outputDir = join(validRoot, ".fuzit-bundles");
    const outputPath = join(outputDir, outputSubpath);
    assertWithinAllowedRoots(outputPath, context.allowedRoots);

    // Build context
    const profile = getProfile(profileId);
    const items = acquisition.getItems(validRoot);
    const result = createTaskContext({
      items,
      task,
      profile,
      budgetTokens: budget,
    });
    const rendered = renderTaskContext(result, format);

    // Write to disk
    await mkdir(outputDir, { recursive: true });
    await writeFile(outputPath, rendered, "utf8");

    return {
      schemaVersion: 1,
      root: validRoot,
      outputPath: outputPath.replace(validRoot, "<root>"),
      format,
      task: result.task,
      profile: result.profile,
      selected: result.selected.length,
      budget: result.budget,
    };
  });
}

import { collectGitHistory } from "@fuzit/git";

import { type McpCallContext, runTool, validateRoot } from "../tool-runner.js";

/** Maximum commits returned by fuzit_recent_changes */
const MAX_COMMITS = 50;

/**
 * fuzit_recent_changes — returns bounded recent Git commits.
 * Author emails are omitted for privacy. Absolute paths are redacted.
 */
export async function fuzitRecentChanges(
  args: {
    root: unknown;
    limit?: unknown;
  },
  context: McpCallContext,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    const limit =
      typeof args.limit === "number" && args.limit > 0
        ? Math.min(Math.floor(args.limit), MAX_COMMITS)
        : 20;

    const entries = await collectGitHistory(validRoot, {
      limit,
      emailPolicy: "omit",
    });

    return {
      schemaVersion: 1,
      root: validRoot,
      commits: entries.map((e) => ({
        hash: e.hash,
        authorName: e.authorName,
        timestamp: e.timestamp,
        subject: e.subject,
        changedPaths: e.changedPaths.slice(0, 100),
      })),
    };
  });
}

import { createTaskContext } from "@fuzit/core";
import { getProfile } from "@fuzit/profiles";

import { MAX_SEARCH_RESULTS } from "../config.js";
import {
  type McpCallContext,
  runTool,
  validateRoot,
  validateTask,
} from "../tool-runner.js";
import type { RepositoryAcquisition } from "../workspace.js";

/**
 * fuzit_search — keyword search over repository items.
 * Returns bounded list of paths ranked by relevance score.
 */
export async function fuzitSearch(
  args: {
    root: unknown;
    task: unknown;
    profile?: unknown;
    budgetTokens?: unknown;
  },
  context: McpCallContext,
  acquisition: RepositoryAcquisition,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    const task = validateTask(args.task);

    const profileId =
      typeof args.profile === "string" && args.profile.trim().length > 0
        ? args.profile.trim()
        : "feature-development";

    const budget =
      typeof args.budgetTokens === "number" && args.budgetTokens > 0
        ? Math.floor(args.budgetTokens)
        : 8000;

    const profile = getProfile(profileId);
    const items = acquisition.getItems(validRoot);

    const result = createTaskContext({
      items,
      task,
      profile,
      budgetTokens: budget,
    });

    return {
      schemaVersion: 1,
      root: validRoot,
      task: result.task,
      profile: result.profile,
      selected: result.selected.slice(0, MAX_SEARCH_RESULTS).map((s) => ({
        path: s.path,
        reason: s.reason,
      })),
      excluded: result.excluded.length,
      budget: result.budget,
      index: result.index,
    };
  });
}

/**
 * fuzit_get_context — get full context bundle for a task.
 * Returns selected file paths and content within budget limits.
 */
export async function fuzitGetContext(
  args: {
    root: unknown;
    task: unknown;
    profile?: unknown;
    budgetTokens?: unknown;
    explain?: unknown;
  },
  context: McpCallContext,
  acquisition: RepositoryAcquisition,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    const task = validateTask(args.task);

    const profileId =
      typeof args.profile === "string" && args.profile.trim().length > 0
        ? args.profile.trim()
        : "feature-development";

    const budget =
      typeof args.budgetTokens === "number" && args.budgetTokens > 0
        ? Math.floor(args.budgetTokens)
        : 8000;

    const explain = args.explain === true;
    const profile = getProfile(profileId);
    const items = acquisition.getItems(validRoot);

    const result = createTaskContext({
      items,
      task,
      profile,
      budgetTokens: budget,
      explain,
    });

    return result;
  });
}

import { createTaskContext } from "@fuzit/core";
import { getProfile } from "@fuzit/profiles";

import {
  type McpCallContext,
  runTool,
  validateRoot,
  validateTask,
} from "../tool-runner.js";
import type { RepositoryAcquisition } from "../workspace.js";

/**
 * fuzit_explain_selection — explains why each file was selected or excluded.
 * Returns structured safe evidence. No raw secret content is exposed.
 */
export async function fuzitExplainSelection(
  args: {
    root: unknown;
    task: unknown;
    profile?: unknown;
    budgetTokens?: unknown;
  },
  context: McpCallContext,
  acquisition: RepositoryAcquisition,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    const task = validateTask(args.task);

    const profileId =
      typeof args.profile === "string" && args.profile.trim().length > 0
        ? args.profile.trim()
        : "feature-development";

    const budget =
      typeof args.budgetTokens === "number" && args.budgetTokens > 0
        ? Math.floor(args.budgetTokens)
        : 8000;

    const profile = getProfile(profileId);
    const items = acquisition.getItems(validRoot);

    // Sanitize task: reject strings that look like secret-shaped input
    const sanitizedTask = task
      .replace(/[A-Za-z0-9+/]{40,}={0,2}/g, "<redacted>")
      .slice(0, 2048);

    const result = createTaskContext({
      items,
      task: sanitizedTask,
      profile,
      budgetTokens: budget,
      explain: true,
    });

    // Strip content from evidence, expose only path, score, decision, and non-redacted flag
    const safeEvidence = (result.evidence ?? []).map((e) => ({
      path: e.path,
      score: e.score,
      decision: e.decision,
      reason: e.reason,
      redacted: e.redacted,
      components: e.components,
    }));

    return {
      schemaVersion: 1,
      root: validRoot,
      task: sanitizedTask,
      profile: result.profile,
      budget: result.budget,
      selected: result.selected.map((s) => ({
        path: s.path,
        reason: s.reason,
      })),
      excluded: result.excluded,
      evidence: safeEvidence,
      index: result.index,
    };
  });
}

import { graphNeighbors, graphImpact, type GraphSnapshot } from "@fuzit/graph";

import { MAX_GRAPH_DEPTH, MAX_GRAPH_NODES } from "../config.js";
import { type McpCallContext, runTool, validateRoot } from "../tool-runner.js";

/**
 * fuzit_graph_neighbors — returns bounded graph neighborhood of a file.
 * Respects depth, node, and edge limits. Cancellation-aware.
 */
export async function fuzitGraphNeighbors(
  args: {
    root: unknown;
    path: unknown;
    depth?: unknown;
    edgeKinds?: unknown;
  },
  context: McpCallContext,
  getSnapshot: (root: string) => GraphSnapshot | null,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    if (typeof args.path !== "string" || args.path.trim().length === 0)
      throw new TypeError("path must be a non-empty string");

    const depth =
      typeof args.depth === "number" && Number.isInteger(args.depth)
        ? Math.min(Math.max(0, args.depth), MAX_GRAPH_DEPTH)
        : 2;

    const snapshot = getSnapshot(validRoot);
    if (!snapshot)
      return {
        schemaVersion: 1,
        nodes: [],
        truncated: false,
        diagnostics: ["no-graph"],
      };

    const result = graphNeighbors(snapshot, args.path, {
      repositoryId: snapshot.repositoryId,
      limits: { depth, maxItems: MAX_GRAPH_NODES },
    });

    return {
      schemaVersion: 1,
      root: validRoot,
      startPath: args.path,
      nodes: result.nodes.map((n) => ({ id: n.id, kind: n.kind })),
      truncated: result.truncated,
      diagnostics: result.diagnostics,
    };
  });
}

/**
 * fuzit_graph_impact — returns bounded impact set from a changed file.
 * Rejects unbounded requests and preserves policy filtering.
 */
export async function fuzitGraphImpact(
  args: {
    root: unknown;
    path: unknown;
    depth?: unknown;
  },
  context: McpCallContext,
  getSnapshot: (root: string) => GraphSnapshot | null,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(args.root, context);
    if (typeof args.path !== "string" || args.path.trim().length === 0)
      throw new TypeError("path must be a non-empty string");

    const depth =
      typeof args.depth === "number" && Number.isInteger(args.depth)
        ? Math.min(Math.max(0, args.depth), MAX_GRAPH_DEPTH)
        : 2;

    const snapshot = getSnapshot(validRoot);
    if (!snapshot)
      return {
        schemaVersion: 1,
        nodes: [],
        truncated: false,
        diagnostics: ["no-graph"],
      };

    const result = graphImpact(snapshot, args.path, {
      repositoryId: snapshot.repositoryId,
      limits: { depth, maxItems: MAX_GRAPH_NODES },
    });

    return {
      schemaVersion: 1,
      root: validRoot,
      startPath: args.path,
      nodes: result.nodes.map((n) => ({ id: n.id, kind: n.kind })),
      truncated: result.truncated,
      diagnostics: result.diagnostics,
    };
  });
}

import { runDoctor } from "@fuzit/core";
import { BUILT_IN_PROFILES } from "@fuzit/profiles";

import { type McpCallContext, runTool, validateRoot } from "../tool-runner.js";

/**
 * fuzit_status — returns doctor report equivalent to CLI doctor --json.
 * All absolute paths and environment-specific metadata are redacted.
 */
export async function fuzitStatus(
  root: unknown,
  context: McpCallContext,
): Promise<ReturnType<typeof runTool>> {
  return runTool(async () => {
    const validRoot = await validateRoot(root, context);
    const report = await runDoctor(validRoot);
    // Redact any absolute paths that may appear in check metadata
    const redactedChecks = report.checks.map((check) => ({
      ...check,
      metadata: check.metadata
        ? Object.fromEntries(
            Object.entries(check.metadata).map(([k, v]) => [
              k,
              typeof v === "string" && v.includes(validRoot)
                ? v.replaceAll(validRoot, "<root>")
                : v,
            ]),
          )
        : undefined,
    }));
    return { ...report, checks: redactedChecks };
  });
}

/**
 * fuzit_profiles — returns list of available built-in profiles.
 */
export async function fuzitProfiles(
  context: McpCallContext,
): Promise<ReturnType<typeof runTool>> {
  void context;
  return runTool(async () => {
    return {
      schemaVersion: 1,
      profiles: BUILT_IN_PROFILES.map((p) => ({
        id: p.id,
        version: p.version,
        weights: p.weights,
        expansion: p.expansion,
      })),
    };
  });
}

import {
  MAX_REQUEST_BYTES,
  MCP_SERVER_VERSION,
  MCP_PROTOCOL_VERSION,
} from "./config.js";
import { redactSensitiveText } from "@fuzit/security";

export type McpRequest = {
  readonly jsonrpc: "2.0";
  readonly id: string | number;
  readonly method: string;
  readonly params?: unknown;
};

export type McpNotification = {
  readonly jsonrpc: "2.0";
  readonly method: string;
  readonly params?: unknown;
};

export type McpResponse = {
  readonly jsonrpc: "2.0";
  readonly id: string | number;
} & (
  | { readonly result: unknown }
  | { readonly error: { code: number; message: string } }
);

type MessageHandler = (
  method: string,
  params: unknown,
  id: string | number,
) => Promise<unknown>;

/**
 * Stdio MCP transport.
 * Reads JSON-RPC 2.0 messages from stdin (newline-delimited).
 * Writes responses to stdout.
 * No network listener is opened.
 */
export class StdioTransport {
  private readonly handler: MessageHandler;
  private buffer = "";
  private closed = false;

  constructor(handler: MessageHandler) {
    this.handler = handler;
  }

  start(): void {
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk: string) => {
      this.buffer += chunk;
      this.processBuffer();
    });
    process.stdin.on("end", () => {
      this.closed = true;
    });
    process.stdin.resume();
  }

  private processBuffer(): void {
    let newlineIndex: number;
    while ((newlineIndex = this.buffer.indexOf("\n")) !== -1) {
      const line = this.buffer.slice(0, newlineIndex).trim();
      this.buffer = this.buffer.slice(newlineIndex + 1);
      if (line.length > 0) {
        if (Buffer.byteLength(line, "utf8") > MAX_REQUEST_BYTES) {
          this.writeError(null, -32600, "Request exceeds maximum size.");
        } else {
          void this.handleLine(line);
        }
      }
    }
  }

  private async handleLine(line: string): Promise<void> {
    let request: McpRequest;
    try {
      request = JSON.parse(line) as McpRequest;
    } catch {
      // malformed JSON — write error but continue
      this.writeError(null, -32700, "Parse error");
      return;
    }

    if (request.jsonrpc !== "2.0") {
      this.writeError(request.id ?? null, -32600, "Invalid Request");
      return;
    }

    try {
      const result = await this.handler(
        request.method,
        request.params,
        request.id,
      );
      this.writeResult(request.id, result);
    } catch (error) {
      const message = redactSensitiveText(
        error instanceof Error ? error.message : "Internal error",
      );
      this.writeError(request.id, -32603, message);
    }
  }

  private writeResult(id: string | number, result: unknown): void {
    const response: McpResponse = { jsonrpc: "2.0", id, result };
    process.stdout.write(`${JSON.stringify(response)}\n`);
  }

  private writeError(
    id: string | number | null,
    code: number,
    message: string,
  ): void {
    const response = {
      jsonrpc: "2.0",
      id: id ?? 0,
      error: { code, message },
    };
    process.stdout.write(`${JSON.stringify(response)}\n`);
  }
}

/**
 * Build a server info response consistent with the MCP protocol.
 */
export function serverInfo() {
  return {
    name: "fuzit",
    version: MCP_SERVER_VERSION,
    protocol: MCP_PROTOCOL_VERSION,
    capabilities: {
      tools: true,
    },
  };
}

import { lstat, realpath } from "node:fs/promises";
import { resolve } from "node:path";

import type { SecurityFilteredItem } from "@fuzit/core";
import type { GraphSnapshot } from "@fuzit/graph";

import {
  assertWithinAllowedRoots,
  canonicalizePath,
  MAX_ALLOWED_ROOTS,
} from "./config.js";

export interface RepositoryAcquisition {
  /** Get security-filtered items for a given root path */
  getItems(root: string): readonly SecurityFilteredItem[];
  /** Get graph snapshot for a given root path */
  getSnapshot(root: string): GraphSnapshot | null;
}

/**
 * Validate and canonicalize workspace allowed roots.
 * - Requires at least one root
 * - Enforces maximum root count
 * - Resolves all roots to canonical absolute paths
 * - Rejects symlinks that point outside the root itself
 */
export async function validateAllowedRoots(
  roots: readonly string[],
): Promise<readonly string[]> {
  if (roots.length === 0)
    throw new RangeError("At least one allowed workspace root is required.");
  if (roots.length > MAX_ALLOWED_ROOTS)
    throw new RangeError(
      `Maximum ${MAX_ALLOWED_ROOTS} allowed workspace roots permitted.`,
    );

  const canonicalized: string[] = [];
  for (const root of roots) {
    if (typeof root !== "string" || root.trim().length === 0)
      throw new TypeError("Each allowed root must be a non-empty string.");

    const abs = canonicalizePath(root);

    // Resolve each root to its current filesystem identity before accepting it.
    try {
      const canonical = resolve(await realpath(abs));
      const stat = await lstat(canonical);
      if (!stat.isDirectory()) {
        throw new RangeError(`Allowed root is not a directory: ${abs}`);
      }
      canonicalized.push(canonical);
    } catch {
      throw new RangeError(`Allowed root does not exist: ${abs}`);
    }
  }
  return [...new Set(canonicalized)].sort((a, b) =>
    Buffer.from(a).compare(Buffer.from(b)),
  );
}

/**
 * Validate that a path is within the allowed roots.
 * Throws if not within any root.
 */
export async function validatePath(
  candidate: string,
  allowedRoots: readonly string[],
): Promise<string> {
  const canonical = resolve(await realpath(canonicalizePath(candidate)));
  return assertWithinAllowedRoots(canonical, allowedRoots);
}

/**
 * Simple in-memory workspace cache.
 * Holds items per root for the lifetime of the server session.
 * Not populated until the first tool call for that root.
 */
export class WorkspaceCache implements RepositoryAcquisition {
  private readonly items = new Map<string, readonly SecurityFilteredItem[]>();
  private readonly snapshots = new Map<string, GraphSnapshot | null>();

  setItems(root: string, items: readonly SecurityFilteredItem[]): void {
    this.items.set(root, items);
  }

  getItems(root: string): readonly SecurityFilteredItem[] {
    return this.items.get(root) ?? [];
  }

  setSnapshot(root: string, snapshot: GraphSnapshot | null): void {
    this.snapshots.set(root, snapshot);
  }

  getSnapshot(root: string): GraphSnapshot | null {
    return this.snapshots.get(root) ?? null;
  }
}

