import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { redactSensitiveText } from "@fuzit/security";

const execFileAsync = promisify(execFile);

export interface EngineAdapterOptions {
  readonly cliPath?: string;
  readonly cwd?: string;
  readonly signal?: AbortSignal;
}

export interface EngineAdapterResult {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
}

/**
 * Executes Fuzit engine commands safely using explicit argument arrays.
 * Never uses shell: true or string concatenation to prevent argument injection.
 */
export async function executeEngineCommand(
  args: readonly string[],
  options: EngineAdapterOptions = {},
): Promise<EngineAdapterResult> {
  const binary = options.cliPath ?? "fuzit";
  const cwd = options.cwd ?? process.cwd();

  // Validate argument elements to ensure no dangerous types
  for (const arg of args) {
    if (typeof arg !== "string") {
      throw new TypeError("Engine command arguments must all be strings");
    }
  }

  try {
    const { stdout, stderr } = await execFileAsync(binary, [...args], {
      cwd,
      signal: options.signal,
      shell: false, // Strict: no shell invocation
      windowsHide: true,
      maxBuffer: 10 * 1024 * 1024,
    });

    return {
      exitCode: 0,
      stdout: redactSensitiveText(stdout.toString()),
      stderr: redactSensitiveText(stderr.toString()),
    };
  } catch (error: unknown) {
    const err = error as {
      code?: string;
      exitCode?: number;
      stdout?: string;
      stderr?: string;
      message?: string;
    };
    if (err.code === "ENOENT") {
      throw new Error(
        redactSensitiveText(`Fuzit CLI binary not found at "${binary}"`),
        { cause: error },
      );
    }
    return {
      exitCode: typeof err.exitCode === "number" ? err.exitCode : 1,
      stdout: redactSensitiveText((err.stdout ?? "").toString()),
      stderr: redactSensitiveText(
        (err.stderr ?? err.message ?? String(error)).toString(),
      ),
    };
  }
}

import { runDoctor } from "@fuzit/core";
import { executeEngineCommand } from "./adapter.js";
import type { EngineAdapterOptions } from "./adapter.js";

function makeOpts(context: CommandContext): EngineAdapterOptions {
  return {
    cwd: context.workspaceRoot,
    ...(context.cliPath !== undefined ? { cliPath: context.cliPath } : {}),
  };
}

export interface CommandContext {
  readonly isTrusted: boolean;
  readonly workspaceRoot: string;
  readonly cliPath?: string;
}

export interface CommandResponse {
  readonly ok: boolean;
  readonly message?: string;
  readonly data?: unknown;
}

/**
 * Executes the `fuzit.init` command.
 * Respects Workspace Trust and prevents overwriting existing configuration silently.
 */
export async function initializeWorkspaceCommand(
  context: CommandContext,
): Promise<CommandResponse> {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: "Workspace Trust is required to initialize Fuzit workspace.",
    };
  }

  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return {
      ok: false,
      message: "No workspace root selected.",
    };
  }

  try {
    const result = await executeEngineCommand(["init"], makeOpts(context));

    if (result.exitCode !== 0) {
      return {
        ok: false,
        message: result.stderr || "Initialization failed",
      };
    }

    return {
      ok: true,
      message: "Workspace initialized successfully.",
      data: { root: context.workspaceRoot },
    };
  } catch (error: unknown) {
    const err = error as Error;
    return {
      ok: false,
      message: err.message || "Failed to initialize workspace",
    };
  }
}

/**
 * Executes the `fuzit.doctor` command.
 * Respects Workspace Trust and returns path-redacted doctor diagnostic report.
 */
export async function runDoctorCommand(
  context: CommandContext,
): Promise<CommandResponse> {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: "Workspace Trust is required to run Fuzit doctor checks.",
    };
  }

  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return {
      ok: false,
      message: "No workspace root selected.",
    };
  }

  try {
    const report = await runDoctor(context.workspaceRoot);
    const redactedChecks = report.checks.map((check) => ({
      ...check,
      metadata: check.metadata
        ? Object.fromEntries(
            Object.entries(check.metadata).map(([k, v]) => [
              k,
              typeof v === "string" && v.includes(context.workspaceRoot)
                ? v.replaceAll(context.workspaceRoot, "<root>")
                : v,
            ]),
          )
        : undefined,
    }));

    return {
      ok: true,
      data: { ...report, checks: redactedChecks },
    };
  } catch (error: unknown) {
    const err = error as Error;
    return {
      ok: false,
      message: err.message || "Doctor check failed",
    };
  }
}

export interface GetContextOptions {
  readonly task: string;
  readonly profile?: string;
  readonly budgetTokens?: number;
  readonly format?: string;
}

/**
 * Executes the `fuzit.scan` command.
 * Respects Workspace Trust and returns scan metadata.
 */
export async function scanCommand(
  context: CommandContext,
): Promise<CommandResponse> {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: "Workspace Trust is required to scan repository.",
    };
  }

  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return {
      ok: false,
      message: "No workspace root selected.",
    };
  }

  try {
    const result = await executeEngineCommand(
      ["scan", "--json"],
      makeOpts(context),
    );

    if (result.exitCode !== 0) {
      return {
        ok: false,
        message: result.stderr || "Scan failed",
      };
    }

    return {
      ok: true,
      data: JSON.parse(result.stdout || "{}"),
    };
  } catch (error: unknown) {
    const err = error as Error;
    return {
      ok: false,
      message: err.message || "Scan failed",
    };
  }
}

/**
 * Executes the `fuzit.getContext` command.
 * Respects Workspace Trust and builds task-aware context bundle with budget and profile controls.
 */
export async function getContextCommand(
  context: CommandContext,
  options: GetContextOptions,
): Promise<CommandResponse> {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: "Workspace Trust is required to build task context.",
    };
  }

  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return {
      ok: false,
      message: "No workspace root selected.",
    };
  }

  if (!options.task || options.task.trim().length === 0) {
    return {
      ok: false,
      message: "Task description must be a non-empty string.",
    };
  }

  const profile = options.profile ?? "feature-development";
  const budget = options.budgetTokens ?? 8000;
  const format = options.format ?? "markdown";

  try {
    const args = [
      "context",
      "--task",
      options.task,
      "--profile",
      profile,
      "--budget-tokens",
      String(budget),
      "--format",
      format,
    ];

    const result = await executeEngineCommand(args, makeOpts(context));

    if (result.exitCode !== 0) {
      return {
        ok: false,
        message: result.stderr || "Get context failed",
      };
    }

    return {
      ok: true,
      data: {
        root: context.workspaceRoot,
        task: options.task,
        profile,
        budget,
        format,
        content: result.stdout,
      },
    };
  } catch (error: unknown) {
    const err = error as Error;
    return {
      ok: false,
      message: err.message || "Get context failed",
    };
  }
}

export interface ExtensionContextLike {
  subscriptions: { dispose(): void }[];
}

export interface ExtensionApi {
  readonly version: string;
  readonly isActivated: boolean;
}

let activated = false;
const deactivationCleanups = new Set<() => void>();

export function registerDeactivationCleanup(cleanup: () => void): {
  dispose(): void;
} {
  deactivationCleanups.add(cleanup);
  return { dispose: () => deactivationCleanups.delete(cleanup) };
}

/**
 * Activate function called when VS Code extension is activated.
 * Bound to command execution only; performs no automatic process spawning or repo scanning.
 */
export function activate(context: ExtensionContextLike): ExtensionApi {
  activated = true;

  const statusDisposable = {
    dispose() {
      // Disposable cleanup
    },
  };

  context.subscriptions.push(statusDisposable);

  return {
    version: "0.0.1",
    get isActivated() {
      return activated;
    },
  };
}

/**
 * Deactivate function called when VS Code extension is deactivated.
 */
export function deactivate(): void {
  for (const cleanup of deactivationCleanups) cleanup();
  deactivationCleanups.clear();
  activated = false;
}

