export interface WorkspaceFolderLike {
  readonly name: string;
  readonly uri: {
    readonly fsPath: string;
  };
}

export interface QuickPickItemLike {
  readonly label: string;
  readonly description?: string | undefined;
  readonly detail?: string | undefined;
  readonly folder: WorkspaceFolderLike;
}

/**
 * Normalizes root paths for consistent per-root state keying across platforms.
 */
export function normalizeRootPath(path: string): string {
  if (!path) return "";
  let normalized = path.replace(/\\/g, "/").trim();
  if (normalized.length > 1 && normalized.endsWith("/")) {
    normalized = normalized.slice(0, -1);
  }
  if (normalized.length > 0 && /^[a-zA-Z]:/.test(normalized)) {
    const driveLetter = normalized[0];
    if (driveLetter !== undefined) {
      normalized = driveLetter.toLowerCase() + normalized.slice(1);
    }
  }
  return normalized;
}

/**
 * Formats quick pick items for multi-root selection.
 * Explicitly disambiguates folders with the same basename by rendering their distinct parent paths.
 */
export function formatWorkspaceRootPicks(
  folders: readonly WorkspaceFolderLike[],
): QuickPickItemLike[] {
  const nameCounts = new Map<string, number>();
  for (const folder of folders) {
    const count = nameCounts.get(folder.name) ?? 0;
    nameCounts.set(folder.name, count + 1);
  }

  return folders.map((folder) => {
    const count = nameCounts.get(folder.name);
    const isDuplicateName = count !== undefined && count > 1;
    const normalized = normalizeRootPath(folder.uri.fsPath);

    return {
      label: folder.name,
      ...(isDuplicateName ? { description: normalized } : {}),
      detail: normalized,
      folder,
    };
  });
}

/**
 * Selects an explicit workspace root from multiple folders.
 * If preferredPath is provided, returns the matching folder.
 * If single folder, returns it.
 */
export function resolveWorkspaceRoot(
  folders: readonly WorkspaceFolderLike[],
  preferredPath?: string,
): WorkspaceFolderLike | null {
  if (folders.length === 0) return null;

  if (preferredPath) {
    const target = normalizeRootPath(preferredPath);
    const matched = folders.find(
      (f) => normalizeRootPath(f.uri.fsPath) === target,
    );
    if (matched) return matched;
  }

  if (folders.length === 1) {
    return folders[0] ?? null;
  }

  return null;
}

export interface PerRootState {
  readonly rootPath: string;
  readonly normalizedPath: string;
  readonly outputs: string[];
  readonly cache: Map<string, unknown>;
  readonly activeTasks: Set<string>;
}

/**
 * Manages isolated per-root state to prevent cross-root output or cache confusion.
 */
export class PerRootStateManager {
  private readonly states = new Map<string, PerRootState>();

  getOrCreateState(rootPath: string): PerRootState {
    const key = normalizeRootPath(rootPath);
    if (!key) {
      throw new Error("Workspace root path cannot be empty.");
    }
    let state = this.states.get(key);
    if (!state) {
      state = {
        rootPath,
        normalizedPath: key,
        outputs: [],
        cache: new Map<string, unknown>(),
        activeTasks: new Set<string>(),
      };
      this.states.set(key, state);
    }
    return state;
  }

  appendOutput(rootPath: string, message: string): void {
    const state = this.getOrCreateState(rootPath);
    state.outputs.push(message);
  }

  getOutputs(rootPath: string): readonly string[] {
    const key = normalizeRootPath(rootPath);
    return this.states.get(key)?.outputs ?? [];
  }

  setCache(rootPath: string, cacheKey: string, value: unknown): void {
    const state = this.getOrCreateState(rootPath);
    state.cache.set(cacheKey, value);
  }

  getCache(rootPath: string, cacheKey: string): unknown | undefined {
    const key = normalizeRootPath(rootPath);
    return this.states.get(key)?.cache.get(cacheKey);
  }

  clearCache(rootPath: string): void {
    const key = normalizeRootPath(rootPath);
    this.states.get(key)?.cache.clear();
  }

  clearAll(): void {
    this.states.clear();
  }
}

export interface ProgressReport {
  readonly message: string;
  readonly increment?: number;
}

export interface TaskExecutionResult<T = unknown> {
  readonly ok: boolean;
  readonly cancelled?: boolean;
  readonly data?: T;
  readonly message?: string;
}

/**
 * Manages cancellable tasks per workspace root.
 * Ensures cancellation stops owned work cleanly and leaves per-root state valid.
 */
export class CancellableTaskRunner {
  private readonly controllers = new Map<
    string,
    Map<string, AbortController>
  >();

  async runTask<T>(
    rootPath: string,
    taskId: string,
    operation: (
      signal: AbortSignal,
      reportProgress: (report: ProgressReport) => void,
    ) => Promise<T>,
    onProgress?: (report: ProgressReport) => void,
  ): Promise<TaskExecutionResult<T>> {
    const rootKey = normalizeRootPath(rootPath);
    if (!rootKey) {
      return { ok: false, message: "Workspace root path cannot be empty." };
    }

    let rootMap = this.controllers.get(rootKey);
    if (!rootMap) {
      rootMap = new Map<string, AbortController>();
      this.controllers.set(rootKey, rootMap);
    }

    if (rootMap.has(taskId)) {
      return {
        ok: false,
        message: `Task "${taskId}" is already running for root "${rootPath}".`,
      };
    }

    const controller = new AbortController();
    rootMap.set(taskId, controller);

    try {
      if (controller.signal.aborted) {
        return {
          ok: false,
          cancelled: true,
          message: `Task "${taskId}" was cancelled before starting.`,
        };
      }

      const resultData = await operation(controller.signal, (report) => {
        if (!controller.signal.aborted && onProgress) {
          onProgress(report);
        }
      });

      if (controller.signal.aborted) {
        return {
          ok: false,
          cancelled: true,
          message: `Task "${taskId}" was cancelled.`,
        };
      }

      return {
        ok: true,
        data: resultData,
      };
    } catch (error: unknown) {
      if (controller.signal.aborted) {
        return {
          ok: false,
          cancelled: true,
          message: `Task "${taskId}" was cancelled.`,
        };
      }
      return {
        ok: false,
        message: (error as Error).message || `Task "${taskId}" failed.`,
      };
    } finally {
      rootMap.delete(taskId);
      if (rootMap.size === 0) {
        this.controllers.delete(rootKey);
      }
    }
  }

  cancelTask(rootPath: string, taskId: string): boolean {
    const rootKey = normalizeRootPath(rootPath);
    const controller = this.controllers.get(rootKey)?.get(taskId);
    if (controller) {
      controller.abort();
      return true;
    }
    return false;
  }

  cancelAllTasks(rootPath?: string): void {
    if (rootPath) {
      const rootKey = normalizeRootPath(rootPath);
      const rootMap = this.controllers.get(rootKey);
      if (rootMap) {
        for (const controller of rootMap.values()) {
          controller.abort();
        }
        rootMap.clear();
        this.controllers.delete(rootKey);
      }
    } else {
      for (const rootMap of this.controllers.values()) {
        for (const controller of rootMap.values()) {
          controller.abort();
        }
      }
      this.controllers.clear();
    }
  }

  isTaskRunning(rootPath: string, taskId: string): boolean {
    const rootKey = normalizeRootPath(rootPath);
    return this.controllers.get(rootKey)?.has(taskId) ?? false;
  }
}

export interface OutputChannelLike {
  appendLine(message: string): void;
  clear(): void;
  show(): void;
}

export interface PreviewRendererOptions {
  readonly workspaceRoot: string;
  readonly maxOutputBytes?: number;
}

const MAX_PREVIEW_BYTES = 512 * 1024; // 512 KB

/**
 * Redact absolute paths in output content, replacing them with <root>.
 */
export function redactAbsolutePaths(
  content: string,
  workspaceRoot: string,
): string {
  if (!workspaceRoot) return content;
  // Normalize separators
  const escaped = workspaceRoot.replace(/[/\\]/g, "[/\\\\]");
  const re = new RegExp(escaped, "g");
  return content.replace(re, "<root>");
}

/**
 * Render a safe, redacted, bounded preview of context/explanation output.
 * Strips absolute paths and enforces an output size cap.
 */
export function renderPreview(
  content: string,
  opts: PreviewRendererOptions,
): string {
  const cap = opts.maxOutputBytes ?? MAX_PREVIEW_BYTES;
  const redacted = redactSensitiveText(
    redactAbsolutePaths(content, opts.workspaceRoot),
    cap + 16,
  );
  const bytes = Buffer.byteLength(redacted, "utf8");
  if (bytes <= cap) return redacted;
  const truncated = Buffer.from(redacted).slice(0, cap).toString("utf8");
  return (
    truncated +
    `\n\n[Output truncated: ${bytes} bytes exceeds limit of ${cap} bytes]`
  );
}

/**
 * Append redacted content to the VS Code output channel.
 */
export function writeToOutputChannel(
  channel: OutputChannelLike,
  content: string,
  opts: PreviewRendererOptions,
): void {
  const preview = renderPreview(content, opts);
  channel.clear();
  channel.appendLine(preview);
  channel.show();
}
import { redactSensitiveText } from "@fuzit/security";

import { executeEngineCommand } from "./adapter.js";
import type { EngineAdapterOptions } from "./adapter.js";

export interface SnapshotCommandContext {
  readonly isTrusted: boolean;
  readonly workspaceRoot: string;
  readonly cliPath?: string;
}

export interface SnapshotCommandResponse {
  readonly ok: boolean;
  readonly message?: string;
  readonly data?: unknown;
}

function ensureTrusted(
  context: SnapshotCommandContext,
  label: string,
): SnapshotCommandResponse | null {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: `Workspace Trust is required to ${label}.`,
    };
  }
  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return { ok: false, message: "No workspace root selected." };
  }
  return null;
}

function adapterOpts(ctx: SnapshotCommandContext): EngineAdapterOptions {
  return {
    cwd: ctx.workspaceRoot,
    ...(ctx.cliPath !== undefined ? { cliPath: ctx.cliPath } : {}),
  };
}

/**
 * Create a new repository snapshot through the engine adapter.
 */
export async function createSnapshotCommand(
  context: SnapshotCommandContext,
): Promise<SnapshotCommandResponse> {
  const guard = ensureTrusted(context, "create snapshot");
  if (guard) return guard;

  try {
    const result = await executeEngineCommand(
      ["snapshot", "create", "--json"],
      adapterOpts(context),
    );
    if (result.exitCode !== 0) {
      return {
        ok: false,
        message: result.stderr || "Snapshot creation failed",
      };
    }
    return { ok: true, data: JSON.parse(result.stdout || "{}") };
  } catch (error: unknown) {
    return {
      ok: false,
      message: (error as Error).message || "Snapshot creation failed",
    };
  }
}

/**
 * Compare two snapshots through the engine adapter.
 */
export async function diffSnapshotCommand(
  context: SnapshotCommandContext,
  snapshotIdA: string,
  snapshotIdB: string,
): Promise<SnapshotCommandResponse> {
  const guard = ensureTrusted(context, "compare snapshots");
  if (guard) return guard;

  if (!snapshotIdA || !snapshotIdB) {
    return { ok: false, message: "Two snapshot IDs are required for diff." };
  }

  try {
    const result = await executeEngineCommand(
      ["snapshot", "diff", "--json", snapshotIdA, snapshotIdB],
      adapterOpts(context),
    );
    if (result.exitCode !== 0) {
      return { ok: false, message: result.stderr || "Snapshot diff failed" };
    }
    return { ok: true, data: JSON.parse(result.stdout || "{}") };
  } catch (error: unknown) {
    return {
      ok: false,
      message: (error as Error).message || "Snapshot diff failed",
    };
  }
}

/**
 * Get graph neighbors for a given file path through the engine adapter.
 */
export async function graphNeighborsCommand(
  context: SnapshotCommandContext,
  filePath: string,
): Promise<SnapshotCommandResponse> {
  const guard = ensureTrusted(context, "get graph neighbors");
  if (guard) return guard;

  if (!filePath || filePath.trim().length === 0) {
    return {
      ok: false,
      message: "A file path is required for graph neighbors.",
    };
  }

  try {
    const result = await executeEngineCommand(
      ["graph", "neighbors", "--json", filePath],
      adapterOpts(context),
    );
    if (result.exitCode !== 0) {
      return { ok: false, message: result.stderr || "Graph neighbors failed" };
    }
    return { ok: true, data: JSON.parse(result.stdout || "{}") };
  } catch (error: unknown) {
    return {
      ok: false,
      message: (error as Error).message || "Graph neighbors failed",
    };
  }
}

/**
 * Get cache status through the engine adapter.
 */
export async function cacheStatusCommand(
  context: SnapshotCommandContext,
): Promise<SnapshotCommandResponse> {
  const guard = ensureTrusted(context, "check cache status");
  if (guard) return guard;

  try {
    const result = await executeEngineCommand(
      ["cache", "status", "--json"],
      adapterOpts(context),
    );
    if (result.exitCode !== 0) {
      return {
        ok: false,
        message: result.stderr || "Cache status check failed",
      };
    }
    return { ok: true, data: JSON.parse(result.stdout || "{}") };
  } catch (error: unknown) {
    return {
      ok: false,
      message: (error as Error).message || "Cache status check failed",
    };
  }
}

/**
 * Centralized Workspace Trust enforcement module.
 * All extension commands that read or write workspace state MUST call
 * `assertTrusted()` before any side-effectful operation.
 */

export interface TrustContext {
  readonly isTrusted: boolean;
  readonly workspaceRoot: string;
}

export interface TrustRefusal {
  readonly ok: false;
  readonly message: string;
}

export type TrustCheckResult = { ok: true } | TrustRefusal;

/**
 * Validate that a workspace context has Workspace Trust before executing any
 * command that reads or writes workspace state. Returns `{ ok: true }` when
 * safe to proceed, or a refusal with an actionable message.
 *
 * @param context - The trust context (isTrusted, workspaceRoot).
 * @param commandLabel - Human-readable label used in refusal messages.
 */
export function assertTrusted(
  context: TrustContext,
  commandLabel: string,
): TrustCheckResult {
  if (!context.isTrusted) {
    return {
      ok: false,
      message: `Workspace Trust is required to ${commandLabel}. Open the Trust dialog to allow Fuzit to operate in this workspace.`,
    };
  }
  if (!context.workspaceRoot || context.workspaceRoot.trim().length === 0) {
    return {
      ok: false,
      message: `No workspace root is available to ${commandLabel}. Open a folder in VS Code first.`,
    };
  }
  return { ok: true };
}

/**
 * Type guard — returns true when the result indicates a refusal.
 */
export function isTrustRefusal(
  result: TrustCheckResult,
): result is TrustRefusal {
  return !result.ok;
}

export type WatchState = "idle" | "running" | "stopping";

export interface WatchController {
  readonly root: string;
  readonly state: WatchState;
  stop(): void;
}

export interface WatchRegistryEntry {
  controller: AbortController;
  state: WatchState;
}

/**
 * Manages watch controller instances per workspace root.
 * Enforces one-watcher-per-root and prevents duplicate watchers.
 */
export class WatchRegistry {
  private readonly entries = new Map<string, WatchRegistryEntry>();

  isWatching(root: string): boolean {
    const entry = this.entries.get(root);
    return entry?.state === "running";
  }

  start(root: string): AbortController {
    if (this.isWatching(root)) {
      throw new Error(`A watcher is already running for root: ${root}`);
    }
    const controller = new AbortController();
    this.entries.set(root, { controller, state: "running" });
    return controller;
  }

  stop(root: string): void {
    const entry = this.entries.get(root);
    if (!entry || entry.state !== "running") return;
    entry.state = "stopping";
    entry.controller.abort(new Error("watch stopped"));
    this.entries.delete(root);
  }

  stopAll(): void {
    for (const root of this.entries.keys()) {
      this.stop(root);
    }
  }

  getState(root: string): WatchState {
    return this.entries.get(root)?.state ?? "idle";
  }
}

/**
 * Start watching a workspace root. Enforces one watcher per root.
 */
export async function startWatchCommand(
  registry: WatchRegistry,
  root: string,
  isTrusted: boolean,
): Promise<{ ok: boolean; message?: string }> {
  if (!isTrusted) {
    return {
      ok: false,
      message: "Workspace Trust is required to start watch.",
    };
  }
  if (!root || root.trim().length === 0) {
    return { ok: false, message: "No workspace root selected." };
  }
  if (registry.isWatching(root)) {
    return {
      ok: false,
      message: `A watcher is already active for this root.`,
    };
  }
  registry.start(root);
  return { ok: true };
}

/**
 * Stop watching a workspace root.
 */
export function stopWatchCommand(
  registry: WatchRegistry,
  root: string,
): { ok: boolean; message?: string } {
  if (!registry.isWatching(root)) {
    return { ok: false, message: "No active watcher for this root." };
  }
  registry.stop(root);
  return { ok: true };
}

