  type NormalizedAnalysis,
} from "@fuzit/schemas";

export const PARSER_AVAILABILITY_DIAGNOSTICS = Object.freeze({
  missing: "ANALYSIS_PARSER_MISSING: optional parser unavailable",
  crash: "ANALYSIS_PARSER_CRASH: parser failed safely",
  timeout: "ANALYSIS_PARSER_TIMEOUT: parser exceeded bounded duration",
  syntax: "ANALYSIS_SYNTAX_ERROR: parser returned partial syntax results",
  unsupported: "ANALYSIS_FEATURE_UNSUPPORTED: feature is not supported",
  partial: "ANALYSIS_PARTIAL_RESULT: parser returned incomplete analysis",
});

export interface SafeParserOptions {
  readonly parserIdentity: string;
  readonly timeoutMs: number;
  readonly independentAnalysis: NormalizedAnalysis;
  readonly parse?:
    (() => NormalizedAnalysis | Promise<NormalizedAnalysis>) | null;
}

function mergeById<T extends { readonly id: string }>(
  independent: readonly T[],
  parsed: readonly T[],
): T[] {
  return [
    ...new Map(
      [...independent, ...parsed].map((item) => [item.id, item]),
    ).values(),
  ].sort((left, right) => left.id.localeCompare(right.id));
}

function partial(
  independent: NormalizedAnalysis,
  diagnostic: string,
): NormalizedAnalysis {
  return parseNormalizedAnalysis({
    ...independent,
    completeness: "partial",
    diagnostics: [...independent.diagnostics, diagnostic].slice(0, 128),
  });
}

export async function runParserSafely(
  options: SafeParserOptions,
): Promise<NormalizedAnalysis> {
  if (!options.parse) {
    return partial(
      options.independentAnalysis,
      PARSER_AVAILABILITY_DIAGNOSTICS.missing,
    );
  }
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    const timedOut = new Promise<never>((_, reject) => {
      timeout = setTimeout(
        () => reject(new Error("bounded parser timeout")),
        options.timeoutMs,
      );
    });
    const parsed = await Promise.race([
      Promise.resolve().then(options.parse),
      timedOut,
    ]);
    if (timeout) clearTimeout(timeout);
    const syntaxPartial =
      parsed.completeness === "partial" &&
      parsed.diagnostics.some((diagnostic) =>
        /(?:SYNTAX|syntax diagnostic)/u.test(diagnostic),
      );
    return parseNormalizedAnalysis({
      ...parsed,
      files: mergeById(options.independentAnalysis.files, parsed.files),
      modules: mergeById(options.independentAnalysis.modules, parsed.modules),
      symbols: mergeById(options.independentAnalysis.symbols, parsed.symbols),
      relationships: mergeById(
        options.independentAnalysis.relationships,
        parsed.relationships,
      ),
      completeness:
        options.independentAnalysis.completeness === "partial" ||
        parsed.completeness !== "complete"
          ? "partial"
          : "complete",
      diagnostics: [
        ...options.independentAnalysis.diagnostics,
        ...parsed.diagnostics,
        ...(parsed.completeness === "partial"
          ? [
              syntaxPartial
                ? PARSER_AVAILABILITY_DIAGNOSTICS.syntax
                : PARSER_AVAILABILITY_DIAGNOSTICS.partial,
            ]
          : []),
      ].slice(0, 128),
    });
  } catch (error) {
    if (timeout) clearTimeout(timeout);
    return partial(
      options.independentAnalysis,
      error instanceof Error && error.message === "bounded parser timeout"
        ? PARSER_AVAILABILITY_DIAGNOSTICS.timeout
        : PARSER_AVAILABILITY_DIAGNOSTICS.crash,
    );
  }
}

export function markUnsupportedFeature(
  analysis: NormalizedAnalysis,
): NormalizedAnalysis {
  return partial(analysis, PARSER_AVAILABILITY_DIAGNOSTICS.unsupported);
}

export interface DependencyEdge {
  readonly from: string;
  readonly specifier: string;
  readonly kind: "relative" | "workspace" | "external" | "dynamic";
  readonly resolved: boolean;
}

export function extractDependencies(
  path: string,
  source: string,
): DependencyEdge[] {
  const edges: DependencyEdge[] = [];
  const pattern =
    /(?:import\s+(?:[^"'()]+?\s+from\s+)?|require\s*\(|import\s*\()\s*["']([^"']+)["']/g;
  for (const match of source.matchAll(pattern)) {
    const specifier = match[1]!;
    const dynamic = match[0].startsWith("import(");
    const relative = specifier.startsWith(".");
    const workspace = specifier.startsWith("@") && !specifier.includes("/");
    edges.push({
      from: path,
      specifier,
      kind: dynamic
        ? "dynamic"
        : relative
          ? "relative"
          : workspace
            ? "workspace"
            : "external",
      resolved: relative && !specifier.includes("*"),
    });
  }
  return edges.sort((a, b) => a.specifier.localeCompare(b.specifier));
}

export function dependencyCycles(edges: readonly DependencyEdge[]): string[][] {
  return edges
    .filter(
      (edge) =>
        edge.resolved &&
        edge.specifier.includes(edge.from.replace(/\.[^.]+$/, "")),
    )
    .map((edge) => [edge.from, edge.specifier]);
}

export {
  dependencyCycles,
  extractDependencies,
  type DependencyEdge,
} from "./extract.js";

export interface DetectorInput {
  readonly packageName: string;
  readonly dependencies: readonly string[];
  readonly scripts: Readonly<Record<string, string>>;
  readonly packageRoot?: string;
  readonly dependencyVersions?: Readonly<Record<string, string>>;
  readonly configurationPaths?: readonly string[];
  readonly sourcePaths?: readonly string[];
  readonly imports?: readonly string[];
  readonly apiUsage?: readonly string[];
}

export interface FrameworkEvidence {
  readonly framework: string;
  readonly packageName: string;
  readonly packageRoot: string;
  readonly support: "confirmed" | "declared";
  readonly versionHint: string | null;
  readonly evidence: readonly string[];
  readonly detector: "framework-manifest-analysis";
  readonly detectorVersion: "1";
}

export interface DetectorResult {
  readonly frameworks: readonly string[];
  readonly tests: readonly string[];
  readonly entryPoints: readonly string[];
  readonly conflicts: readonly string[];
  readonly evidence: readonly FrameworkEvidence[];
  readonly testEvidence: readonly FrameworkEvidence[];
  readonly partial: boolean;
}

export function detectFrameworks(input: DetectorInput): DetectorResult {
  const frameworks = [
    "next",
    "react",
    "express",
    "fastify",
    "@nestjs/core",
    "fastapi",
    "flask",
    "django",
  ].filter((name) => input.dependencies.includes(name));
  const tests = ["vitest", "jest", "pytest"].filter((name) =>
    input.dependencies.includes(name),
  );
  const entryPoints = Object.entries(input.scripts)
    .filter(([name]) => ["start", "serve", "dev"].includes(name))
    .map(([name, command]) => `${name}:${command}`)
    .sort();
  const paths = [
    ...(input.configurationPaths ?? []),
    ...(input.sourcePaths ?? []),
  ].map((path) => path.replaceAll("\\", "/"));
  const imports = new Set(input.imports ?? []);
  const evidence: FrameworkEvidence[] = [];
  if (input.dependencies.includes("react")) {
    const usage = imports.has("react") || imports.has("react-dom");
    evidence.push({
      framework: "react",
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: usage ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.react ?? null,
      evidence: ["dependency:react", ...(usage ? ["import:react"] : [])],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  if (input.dependencies.includes("next")) {
    const appRouter = paths.some((path) =>
      /(^|\/)app\/(?:layout|page)\.[cm]?[jt]sx?$/u.test(path),
    );
    const pagesRouter = paths.some((path) =>
      /(^|\/)pages\/.+\.[cm]?[jt]sx?$/u.test(path),
    );
    const config = paths.some((path) =>
      /(^|\/)next\.config\.[cm]?[jt]s$/u.test(path),
    );
    const usage =
      appRouter ||
      pagesRouter ||
      config ||
      imports.has("next") ||
      [...imports].some((item) => item.startsWith("next/"));
    evidence.push({
      framework: "next",
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: usage ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.next ?? null,
      evidence: [
        "dependency:next",
        ...(appRouter ? ["layout:app-router"] : []),
        ...(pagesRouter ? ["layout:pages-router"] : []),
        ...(config ? ["configuration:next"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const apiUsage = [...(input.apiUsage ?? [])].sort();
  for (const [dependency, framework, importNames, usagePrefix] of [
    ["express", "express", ["express"], "express:"],
    ["fastify", "fastify", ["fastify"], "fastify:"],
    ["@nestjs/core", "nestjs", ["@nestjs/core", "@nestjs/common"], "nestjs:"],
  ] as const) {
    if (!input.dependencies.includes(dependency)) continue;
    const imported = importNames.some((name) => imports.has(name));
    const routes = apiUsage.filter((item) => item.startsWith(usagePrefix));
    const config = paths.filter(
      (path) => framework === "nestjs" && /(^|\/)nest-cli\.json$/u.test(path),
    );
    const confirmed = imported || routes.length > 0 || config.length > 0;
    evidence.push({
      framework,
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.[dependency] ?? null,
      evidence: [
        `dependency:${dependency}`,
        ...(imported ? [`import:${dependency}`] : []),
        ...routes.map((route) => `route:${route.slice(usagePrefix.length)}`),
        ...config.map(() => "configuration:nest-cli"),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  for (const [dependency, framework, importNames, usagePrefix] of [
    ["fastapi", "fastapi", ["fastapi"], "fastapi:"],
    ["flask", "flask", ["flask"], "flask:"],
    ["django", "django", ["django"], "django:"],
  ] as const) {
    if (!input.dependencies.includes(dependency)) continue;
    const imported = importNames.some((name) => imports.has(name));
    const routes = apiUsage.filter((item) => item.startsWith(usagePrefix));
    const config = paths.some((path) =>
      framework === "django"
        ? /(^|\/)(?:settings|urls|manage)\.py$/u.test(path)
        : false,
    );
    const entryPoint = entryPoints.some((entry) =>
      new RegExp(`(?:^|[: ])${framework}(?:[.: ]|$)`, "iu").test(entry),
    );
    const confirmed = imported || routes.length > 0 || config || entryPoint;
    evidence.push({
      framework,
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.[dependency] ?? null,
      evidence: [
        `dependency:${dependency}`,
        ...(imported ? [`import:${dependency}`] : []),
        ...routes.map((route) => `route:${route.slice(usagePrefix.length)}`),
        ...(config ? ["configuration:django"] : []),
        ...(entryPoint ? ["entry-point"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  for (const [depName, framework, importPrefix] of [
    ["github.com/gin-gonic/gin", "gin", "github.com/gin-gonic/gin"],
    ["github.com/labstack/echo", "echo", "github.com/labstack/echo"],
    ["github.com/gofiber/fiber", "fiber", "github.com/gofiber/fiber"],
    ["github.com/go-chi/chi", "chi", "github.com/go-chi/chi"],
    ["github.com/gorilla/mux", "gorilla/mux", "github.com/gorilla/mux"],
  ] as const) {
    const dep = input.dependencies.find(
      (d) => d === depName || d.startsWith(`${depName}/`) || d === framework,
    );
    if (!dep) continue;
    frameworks.push(framework);
    const imported = [...imports].some(
      (item) => item === importPrefix || item.startsWith(`${importPrefix}/`),
    );
    const routes = apiUsage.filter(
      (item) =>
        item.startsWith(`go:route:`) || item.startsWith(`${framework}:route:`),
    );
    const entryPoint = paths.some((path) => /(^|\/)main\.go$/u.test(path));
    const confirmed = imported || routes.length > 0 || entryPoint;
    evidence.push({
      framework,
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.[dep] ?? null,
      evidence: [
        `dependency:${dep}`,
        ...(imported ? [`import:${framework}`] : []),
        ...routes.map((r) => `route:${r.split(":").slice(2).join(":")}`),
        ...(entryPoint ? ["entry-point"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const springBootDep = input.dependencies.find(
    (dep) =>
      dep === "spring-boot" ||
      dep.includes("spring-boot") ||
      dep.startsWith("org.springframework.boot") ||
      dep.startsWith("org.springframework:"),
  );
  if (springBootDep) {
    frameworks.push("spring-boot");
    const imported =
      imports.has(
        "org.springframework.boot.autoconfigure.SpringBootApplication",
      ) ||
      imports.has("org.springframework.web.bind.annotation.RestController") ||
      imports.has("org.springframework.context.annotation.Configuration") ||
      imports.has("org.springframework.stereotype.Controller") ||
      [...imports].some((item) => item.startsWith("org.springframework"));
    const annotations = apiUsage.filter(
      (item) =>
        item.startsWith("spring:annotation:") ||
        item.startsWith("spring:controller:") ||
        item.startsWith("spring:configuration:"),
    );
    const routes = apiUsage.filter((item) => item.startsWith("spring:route:"));
    const config = paths.some((path) =>
      /(^|\/)application(?:-[^/]+)?\.(?:properties|yml|yaml)$/u.test(path),
    );
    const entryPoint =
      Object.keys(input.scripts).some((name) => /spring-boot/iu.test(name)) ||
      paths.some((path) => /Application\.java$/u.test(path)) ||
      apiUsage.includes("spring:entry-point");
    const confirmed =
      imported ||
      annotations.length > 0 ||
      routes.length > 0 ||
      config ||
      entryPoint;
    evidence.push({
      framework: "spring-boot",
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint:
        input.dependencyVersions?.["spring-boot"] ??
        input.dependencyVersions?.[springBootDep] ??
        null,
      evidence: [
        `dependency:${springBootDep}`,
        ...(imported ? ["import:spring"] : []),
        ...annotations.map((item) =>
          item.startsWith("spring:annotation:")
            ? `annotation:${item.slice("spring:annotation:".length)}`
            : item,
        ),
        ...routes.map((item) => `route:${item.slice("spring:route:".length)}`),
        ...(config ? ["configuration:application-properties"] : []),
        ...(entryPoint ? ["entry-point"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const backend = evidence.filter(({ framework }) =>
    [
      "express",
      "fastify",
      "nestjs",
      "fastapi",
      "flask",
      "django",
      "spring-boot",
    ].includes(framework),
  );
  const backendConflicts =
    backend.filter(({ support }) => support === "confirmed").length > 1
      ? [
          `multiple confirmed server frameworks: ${backend
            .filter(({ support }) => support === "confirmed")
            .map(({ framework }) => framework)
            .sort()
            .join(", ")}`,
        ]
      : [];
  const testEvidence: FrameworkEvidence[] = [];
  for (const framework of ["vitest", "jest"] as const) {
    if (!input.dependencies.includes(framework)) continue;
    const imported =
      imports.has(framework) ||
      (framework === "jest" && imports.has("@jest/globals"));
    const config = paths.some((path) =>
      new RegExp(`(^|/)${framework}\\.config\\.[cm]?[jt]s$`, "u").test(path),
    );
    const scriptNames = Object.entries(input.scripts)
      .filter(([, command]) =>
        new RegExp(`(^|\\s)${framework}(\\s|$)`, "u").test(command),
      )
      .map(([name]) => name)
      .sort();
    const globals = apiUsage.filter((item) =>
      item.startsWith(`${framework}:global:`),
    );
    const layout = paths.some((path) =>
      /(^|\/)(?:__tests__|tests?)\/|\.(?:test|spec)\.[cm]?[jt]sx?$/u.test(path),
    );
    const confirmed =
      imported ||
      config ||
      scriptNames.length > 0 ||
      globals.length > 0 ||
      layout;
    testEvidence.push({
      framework,
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint: input.dependencyVersions?.[framework] ?? null,
      evidence: [
        `dependency:${framework}`,
        ...(imported ? [`import:${framework}`] : []),
        ...(config ? [`configuration:${framework}`] : []),
        ...scriptNames.map((name) => `script-metadata:${name}`),
        ...globals.map(
          (item) => `global-api:${item.slice(`${framework}:global:`.length)}`,
        ),
        ...(layout ? ["layout:test"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const junitDep = input.dependencies.find(
    (dep) =>
      dep === "junit" || dep.includes("junit") || dep.startsWith("org.junit"),
  );
  if (junitDep) {
    tests.push("junit");
    const isJunit5 =
      junitDep.includes("jupiter") ||
      junitDep.includes("junit5") ||
      junitDep.includes("junit-jupiter");
    const isJunit4 =
      junitDep === "junit" ||
      junitDep === "junit:junit" ||
      junitDep.includes("junit4");
    const imported =
      imports.has("org.junit.Test") ||
      imports.has("org.junit.jupiter.api.Test") ||
      [...imports].some((item) => item.startsWith("org.junit"));
    const annotations = apiUsage.filter((item) =>
      item.startsWith("junit:annotation:"),
    );
    const layout = paths.some((path) =>
      /(^|\/)src\/test\/java\/|\.(?:Test|Tests)\.java$/u.test(path),
    );
    const confirmed = imported || annotations.length > 0 || layout;
    testEvidence.push({
      framework: "junit",
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint:
        input.dependencyVersions?.junit ??
        input.dependencyVersions?.[junitDep] ??
        (isJunit5 ? "5" : isJunit4 ? "4" : null),
      evidence: [
        `dependency:${junitDep}`,
        ...(imported ? ["import:junit"] : []),
        ...annotations.map(
          (item) => `annotation:${item.slice("junit:annotation:".length)}`,
        ),
        ...(layout ? ["layout:test"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const goTestDep = input.dependencies.find(
    (dep) =>
      dep === "testing" ||
      dep === "github.com/stretchr/testify" ||
      dep.includes("testify"),
  );
  const goTestLayout = paths.some((path) => /_test\.go$/u.test(path));
  if (goTestDep || goTestLayout) {
    const framework = goTestDep?.includes("testify") ? "testify" : "testing";
    tests.push(framework);
    const imported =
      imports.has("testing") ||
      imports.has("github.com/stretchr/testify") ||
      [...imports].some((item) =>
        item.startsWith("github.com/stretchr/testify"),
      );
    const confirmed = imported || goTestLayout;
    testEvidence.push({
      framework,
      packageName: input.packageName,
      packageRoot: input.packageRoot ?? ".",
      support: confirmed ? "confirmed" : "declared",
      versionHint: goTestDep
        ? (input.dependencyVersions?.[goTestDep] ?? null)
        : null,
      evidence: [
        ...(goTestDep ? [`dependency:${goTestDep}`] : []),
        ...(imported ? [`import:${framework}`] : []),
        ...(goTestLayout ? ["layout:test"] : []),
      ],
      detector: "framework-manifest-analysis",
      detectorVersion: "1",
    });
  }
  const testConflicts =
    testEvidence.filter(({ support }) => support === "confirmed").length > 1
      ? [
          `multiple confirmed test frameworks: ${testEvidence
            .map(({ framework }) => framework)
            .sort()
            .join(", ")}`,
        ]
      : [];
  return {
    frameworks,
    tests,
    entryPoints,
    conflicts: [
      ...(backendConflicts.length > 0
        ? backendConflicts
        : frameworks.includes("express") && frameworks.includes("fastify")
          ? ["multiple server frameworks"]
          : []),
      ...testConflicts,
    ].sort(),
    evidence: evidence.sort((a, b) => a.framework.localeCompare(b.framework)),
    testEvidence: testEvidence.sort((a, b) =>
      a.framework.localeCompare(b.framework),
    ),
    partial: false,
  };
}

export {
  detectFrameworks,
  type DetectorInput,
  type DetectorResult,
  type FrameworkEvidence,
} from "./detect.js";

import { createHash } from "node:crypto";

import {
  repositoryFactSchema,
  type RepositoryFact,
  type RepositoryFactKind,
} from "@fuzit/schemas";

export * from "./languages/index.js";
export * from "./manifests/js/index.js";
export * from "./manifests/python/index.js";
export * from "./manifests/java/index.js";
export * from "./manifests/go/index.js";
export * from "./detectors/index.js";
export * from "./dependencies/index.js";
export * from "./contracts/index.js";
export * from "./parsers/index.js";
export * from "./relations/index.js";
export * from "./availability/index.js";

export type RepositoryFactInput = Omit<RepositoryFact, "schemaVersion" | "id">;

export function createRepositoryFact(
  input: RepositoryFactInput,
): RepositoryFact {
  const identity = JSON.stringify({
    kind: input.kind,
    value: input.value,
    detector: input.detector,
    evidence: input.evidence,
  });
  return repositoryFactSchema.parse({
    ...input,
    schemaVersion: 1,
    id: `fact:${createHash("sha256").update(identity).digest("hex")}`,
  });
}

export function conflictingFacts(
  facts: readonly RepositoryFact[],
  kind: RepositoryFactKind,
): RepositoryFact[] {
  return facts.filter(
    (fact) => fact.kind === kind && fact.conflictsWith.length > 0,
  );
}

import { extname } from "node:path";

import { createRepositoryFact } from "../index.js";

export interface LanguageFile {
  readonly path: string;
  readonly contentPrefix?: string;
  readonly generated?: boolean;
  readonly vendored?: boolean;
}

const extensions: Readonly<Record<string, string>> = {
  ".ts": "TypeScript",
  ".js": "JavaScript",
  ".py": "Python",
  ".java": "Java",
  ".go": "Go",
};

export function detectLanguages(files: readonly LanguageFile[]) {
  return files
    .filter((file) => !file.generated && !file.vendored)
    .flatMap((file) => {
      const extensionLanguage = extensions[extname(file.path).toLowerCase()];
      const shebangLanguage = file.contentPrefix?.startsWith("#!/usr/bin/env ")
        ? file.contentPrefix.slice(15).split(/\s/)[0]
        : undefined;
      const language =
        extensionLanguage ??
        (shebangLanguage === "python"
          ? "Python"
          : shebangLanguage === "node"
            ? "JavaScript"
            : undefined);
      if (!language) return [];
      return [
        createRepositoryFact({
          kind: "language",
          value: language,
          confidence: extensionLanguage ? 0.9 : 0.8,
          basis: "inferred",
          evidence: [file.path],
          detector: extensionLanguage ? "extension" : "shebang",
          conflictsWith: [],
        }),
      ];
    });
}

export function detectSourceRoots(paths: readonly string[]) {
  return [
    ...new Set(
      paths
        .map((path) => path.split("/")[0])
        .filter((root): root is string => root !== undefined && root !== ""),
    ),
  ]
    .filter((root) => ["src", "test", "tests", "app", "lib"].includes(root))
    .sort();
}

export {
  detectLanguages,
  detectSourceRoots,
  type LanguageFile,
} from "./detect.js";

export const GO_BUILD_DETECTOR_VERSION = "1";

export interface GoManifestResult {
  readonly ecosystem: "go";
  readonly path: string;
  readonly format: "go.mod" | "go.work";
  readonly module: string | null;
  readonly goVersion: string | null;
  readonly dependencies: readonly string[];
  readonly replacements: readonly {
    readonly from: string;
    readonly to: string;
  }[];
  readonly useDirectories: readonly string[];
  readonly dynamic: boolean;
  readonly completeness: "complete" | "partial";
  readonly diagnostics: readonly string[];
  readonly detectorVersion: string;
}

export function parseGoManifest(
  source: string,
  path = "go.mod",
): GoManifestResult {
  const normalizedPath = path.replaceAll("\\", "/");
  const isWork =
    normalizedPath.endsWith("go.work") || /^\s*use\s/m.test(source);
  const moduleMatch = /^module\s+(\S+)/m.exec(source);
  const moduleName = moduleMatch?.[1] ?? null;
  const goVersion = /^go\s+([0-9.]+)/m.exec(source)?.[1] ?? null;

  const dependencies: string[] = [];
  for (const match of source.matchAll(/^require\s+(\S+)(?:\s+\S+)?/gm)) {
    if (match[1] && match[1] !== "(") dependencies.push(match[1]);
  }
  for (const block of source.matchAll(/require\s*\(([\s\S]*?)\)/g)) {
    for (const line of block[1]!.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("//")) continue;
      const parts = trimmed.split(/\s+/);
      if (parts[0] && parts[0] !== ")") dependencies.push(parts[0]);
    }
  }

  const replacements: { from: string; to: string }[] = [];
  for (const match of source.matchAll(/^replace\s+(\S+)\s+=>\s+(\S+)/gm)) {
    replacements.push({ from: match[1]!, to: match[2]! });
  }
  for (const block of source.matchAll(/replace\s*\(([\s\S]*?)\)/g)) {
    for (const line of block[1]!.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("//")) continue;
      const parts = trimmed.split(/\s+=>\s+/);
      if (parts.length === 2) {
        const from = parts[0]!.trim().split(/\s+/)[0]!;
        const to = parts[1]!.trim().split(/\s+/)[0]!;
        replacements.push({ from, to });
      }
    }
  }

  const useDirectories: string[] = [];
  for (const match of source.matchAll(/^use\s+(\S+)/gm)) {
    if (match[1] && match[1] !== "(") useDirectories.push(match[1]);
  }
  for (const block of source.matchAll(/use\s*\(([\s\S]*?)\)/g)) {
    for (const line of block[1]!.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("//")) continue;
      const dir = trimmed.split(/\s+/)[0]!;
      if (dir && dir !== ")") useDirectories.push(dir);
    }
  }

  const hasBuildTag = /\/\/\s*(?:go:build|\+build)/u.test(source);
  const isMalformed = !isWork && !moduleName && /^\s*require\b/m.test(source);
  const diagnostics = [
    ...(hasBuildTag ? ["unsupported-build-tag"] : []),
    ...(isMalformed ? ["malformed-manifest"] : []),
  ].sort();

  return {
    ecosystem: "go",
    path: normalizedPath,
    format: isWork ? "go.work" : "go.mod",
    module: moduleName,
    goVersion,
    dependencies: [...new Set(dependencies)].sort(),
    replacements,
    useDirectories: [...new Set(useDirectories)].sort(),
    dynamic: false,
    completeness: diagnostics.length === 0 ? "complete" : "partial",
    diagnostics,
    detectorVersion: GO_BUILD_DETECTOR_VERSION,
  };
}

export const JAVA_BUILD_DETECTOR_VERSION = "1";

export function parseJavaManifest(source: string, path = "pom.xml") {
  const normalizedPath = path.replaceAll("\\", "/");
  const maven =
    normalizedPath.endsWith("pom.xml") || /<project[\s>]/u.test(source);
  const dynamic = /\$\{|project\.|System\.|providers\.|findProperty\(/u.test(
    source,
  );
  let dependencies = maven
    ? [
        ...source.matchAll(
          /<dependency>[\s\S]*?<groupId>\s*([^<]+)<\/groupId>[\s\S]*?<artifactId>\s*([^<]+)<\/artifactId>[\s\S]*?<\/dependency>/gu,
        ),
      ].map((match) => `${match[1]!.trim()}:${match[2]!.trim()}`)
    : [
        ...source.matchAll(
          /(?:implementation|api|testImplementation)\s*(?:\(|\s)\s*["']([^"']+)["']/gu,
        ),
      ].map((match) => match[1]!);
  if (maven && dependencies.length === 0) {
    dependencies = [
      ...source.matchAll(/<groupId>\s*([^<]+)\s*<\/groupId>/gu),
    ].map((match) => match[1]!.trim());
  }
  const modules = maven
    ? [...source.matchAll(/<module>\s*([^<]+)\s*<\/module>/gu)].map(
        (match) => match[1]!,
      )
    : [
        ...source.matchAll(/(?:^|\n)\s*include\s*\(?\s*["']([^"']+)["']/gu),
      ].flatMap((match) =>
        match[1]!
          .split(/\s*,\s*/u)
          .map((item) => item.replace(/^:/u, "").replaceAll(":", "/")),
      );
  const parent = maven
    ? (/<parent>[\s\S]*?<artifactId>\s*([^<]+)<\/artifactId>[\s\S]*?<\/parent>/u
        .exec(source)?.[1]
        ?.trim() ?? null)
    : null;
  const plugins = maven
    ? [
        ...source.matchAll(
          /<plugin>[\s\S]*?<artifactId>\s*([^<]+)<\/artifactId>[\s\S]*?<\/plugin>/gu,
        ),
      ].map((match) => match[1]!.trim())
    : [
        ...source.matchAll(/(?:id\s*\(?\s*["']|alias\s*\()([^"')]+)["']?\)?/gu),
      ].map((match) => match[1]!.trim());
  const sourceRoots = [
    ...source.matchAll(/(?:srcDir|sourceDirectory)>?\s*["']?([^<"'\r\n)]+)/gu),
  ].map((match) => match[1]!.trim());
  const entryPoints = [
    ...source.matchAll(
      /(?:mainClass(?:Name)?\s*=|mainClass\.set\()\s*["']([^"']+)["']/gu,
    ),
  ].map((match) => match[1]!);
  const diagnostics = [
    ...(dynamic ? ["dynamic-build-metadata"] : []),
    ...(!maven && /\.kts$/u.test(normalizedPath)
      ? ["kotlin-dsl-conservative"]
      : []),
  ].sort();
  return {
    ecosystem: "java",
    path: normalizedPath,
    format: maven ? "maven" : "gradle",
    dependencies: [...new Set(dependencies)].sort(),
    modules: [...new Set(modules)].sort(),
    parent,
    plugins: [...new Set(plugins)].sort(),
    sourceRoots: [...new Set(sourceRoots)].sort(),
    entryPoints: [...new Set(entryPoints)].sort(),
    dynamic,
    completeness: diagnostics.length === 0 ? "complete" : "partial",
    diagnostics,
    detectorVersion: JAVA_BUILD_DETECTOR_VERSION,
  };
}

export {
  detectJavascriptWorkspaceManagers,
  JAVASCRIPT_WORKSPACE_DETECTOR_VERSION,
  parsePackageJson,
  workspaceDiagnostics,
  type DependencyClass,
  type JsPackageFact,
} from "./parse.js";

export const JAVASCRIPT_WORKSPACE_DETECTOR_VERSION = "1" as const;

export type DependencyClass =
  "production" | "development" | "peer" | "optional";

export interface JsPackageFact {
  readonly name: string;
  readonly path: string;
  readonly packageRoot: string;
  readonly scripts: Readonly<Record<string, string>>;
  readonly dependencies: readonly string[];
  readonly dependencyClasses: Readonly<
    Record<DependencyClass, readonly string[]>
  >;
  readonly workspacePatterns: readonly string[];
  readonly entryPoints: readonly string[];
  readonly exports: readonly string[];
  readonly detector: "javascript-workspace";
  readonly detectorVersion: "1";
  readonly completeness: "complete" | "partial";
  readonly diagnostics: readonly string[];
}

const canonical = (path: string) =>
  path.replaceAll("\\", "/").replace(/^\.\//, "");
const stringRecord = (value: unknown): Record<string, string> =>
  typeof value === "object" && value !== null
    ? Object.fromEntries(
        Object.entries(value).filter(
          (entry): entry is [string, string] => typeof entry[1] === "string",
        ),
      )
    : {};
const sortedKeys = (value: unknown) => Object.keys(stringRecord(value)).sort();
const exportKeys = (value: unknown): string[] => {
  if (typeof value === "string") return ["."];
  if (typeof value !== "object" || value === null) return [];
  return Object.keys(value).sort();
};

export function parsePackageJson(path: string, source: string): JsPackageFact {
  const normalizedPath = canonical(path);
  const packageRoot = normalizedPath.includes("/")
    ? normalizedPath.slice(0, normalizedPath.lastIndexOf("/"))
    : ".";
  try {
    const value = JSON.parse(source) as Record<string, unknown>;
    const workspaceValue = Array.isArray(value.workspaces)
      ? value.workspaces
      : typeof value.workspaces === "object" &&
          value.workspaces !== null &&
          Array.isArray((value.workspaces as { packages?: unknown }).packages)
        ? (value.workspaces as { packages: unknown[] }).packages
        : [];
    const dependencyClasses = {
      production: sortedKeys(value.dependencies),
      development: sortedKeys(value.devDependencies),
      peer: sortedKeys(value.peerDependencies),
      optional: sortedKeys(value.optionalDependencies),
    } satisfies Record<DependencyClass, string[]>;
    const entryPoints = [value.main, value.module, value.browser, value.bin]
      .flatMap((item) =>
        typeof item === "string" ? [item] : Object.values(stringRecord(item)),
      )
      .map(canonical)
      .sort();
    return {
      name: typeof value.name === "string" ? value.name : normalizedPath,
      path: normalizedPath,
      packageRoot,
      scripts: Object.fromEntries(
        Object.entries(stringRecord(value.scripts)).sort(),
      ),
      dependencies: [
        ...new Set(Object.values(dependencyClasses).flat()),
      ].sort(),
      dependencyClasses,
      workspacePatterns: workspaceValue
        .filter((item): item is string => typeof item === "string")
        .map(canonical)
        .sort(),
      entryPoints,
      exports: exportKeys(value.exports),
      detector: "javascript-workspace",
      detectorVersion: JAVASCRIPT_WORKSPACE_DETECTOR_VERSION,
      completeness: "complete",
      diagnostics: [],
    };
  } catch {
    return {
      name: normalizedPath,
      path: normalizedPath,
      packageRoot,
      scripts: {},
      dependencies: [],
      dependencyClasses: {
        production: [],
        development: [],
        peer: [],
        optional: [],
      },
      workspacePatterns: [],
      entryPoints: [],
      exports: [],
      detector: "javascript-workspace",
      detectorVersion: JAVASCRIPT_WORKSPACE_DETECTOR_VERSION,
      completeness: "partial",
      diagnostics: ["invalid package.json"],
    };
  }
}

export function detectJavascriptWorkspaceManagers(paths: readonly string[]): {
  readonly managers: readonly ("npm" | "pnpm" | "yarn")[];
  readonly conflicts: readonly string[];
} {
  const names = new Set(paths.map((path) => canonical(path).split("/").at(-1)));
  const managers = (
    [
      ["npm", "package-lock.json"],
      ["pnpm", "pnpm-workspace.yaml"],
      ["yarn", "yarn.lock"],
    ] as const
  )
    .filter(([, marker]) => names.has(marker))
    .map(([manager]) => manager);
  return {
    managers,
    conflicts:
      managers.length > 1
        ? [`conflicting workspace managers: ${managers.join(", ")}`]
        : [],
  };
}

export function workspaceDiagnostics(packages: readonly JsPackageFact[]) {
  const seen = new Set<string>();
  const diagnostics: string[] = [];
  for (const package_ of [...packages].sort((a, b) =>
    a.path.localeCompare(b.path),
  )) {
    if (seen.has(package_.name))
      diagnostics.push(`duplicate package name: ${package_.name}`);
    seen.add(package_.name);
    diagnostics.push(
      ...package_.diagnostics.map((item) => `${package_.path}: ${item}`),
    );
  }
  return diagnostics.sort();
}

export {
  detectPythonPackageLayout,
  parsePythonManifest,
  PYTHON_PACKAGING_DETECTOR_VERSION,
  type PythonManifestFact,
} from "./parse.js";

export const PYTHON_PACKAGING_DETECTOR_VERSION = "1";

export interface PythonManifestFact {
  ecosystem: "python";
  path: string;
  format: "pyproject" | "requirements" | "metadata" | "lock" | "unknown";
  name: string | null;
  dependencies: string[];
  includes: string[];
  entryPoints: string[];
  testConfiguration: string[];
  detector: "python-packaging";
  version: typeof PYTHON_PACKAGING_DETECTOR_VERSION;
  completeness: "complete" | "partial";
  diagnostics: string[];
}

function normalizedDependency(value: string): string {
  return value
    .trim()
    .split(/[<>=~!;\s[]/, 1)[0]!
    .toLowerCase();
}

function section(source: string, name: string): string {
  const lines = source.split(/\r?\n/);
  const start = lines.findIndex((line) => line.trim() === `[${name}]`);
  if (start < 0) return "";
  const body: string[] = [];
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index]!;
    if (/^\s*\[.+\]\s*$/.test(line)) break;
    body.push(line);
  }
  return body.join("\n");
}

export function parsePythonManifest(
  source: string,
  path = "requirements.txt",
): PythonManifestFact {
  const lowerPath = path.toLowerCase();
  const isPyproject = lowerPath.endsWith("pyproject.toml");
  const isRequirements = /(^|\/)requirements[^/]*\.(txt|in)$/.test(lowerPath);
  const isMetadata = /(^|\/)(metadata|pkg-info)$/.test(lowerPath);
  const isLock = /(^|\/)(poetry\.lock|pdm\.lock|uv\.lock)$/.test(lowerPath);
  const format = isPyproject
    ? "pyproject"
    : isRequirements
      ? "requirements"
      : isMetadata
        ? "metadata"
        : isLock
          ? "lock"
          : "unknown";
  const diagnostics: string[] = [];
  const dependencies: string[] = [];
  const includes: string[] = [];
  const entryPoints: string[] = [];
  const testConfiguration: string[] = [];
  let name: string | null = null;

  if (isPyproject) {
    const project = section(source, "project");
    const poetry = section(source, "tool.poetry");
    const poetryDependencies = section(source, "tool.poetry.dependencies");
    name =
      /(?:^|\n)\s*name\s*=\s*["']([^"']+)["']/.exec(project)?.[1] ??
      /(?:^|\n)\s*name\s*=\s*["']([^"']+)["']/.exec(poetry)?.[1] ??
      null;
    const dependencyArray =
      /(?:^|\n)\s*dependencies\s*=\s*\[([\s\S]*?)\]/.exec(project)?.[1] ?? "";
    dependencies.push(
      ...[...dependencyArray.matchAll(/["']([^"']+)["']/g)].map((match) =>
        normalizedDependency(match[1]!),
      ),
    );
    dependencies.push(
      ...[...poetryDependencies.matchAll(/^\s*([A-Za-z0-9_.-]+)\s*=/gm)]
        .map((match) => match[1]!.toLowerCase())
        .filter((dependency) => dependency !== "python"),
    );
    for (const group of [
      "project.scripts",
      "project.entry-points.console_scripts",
      "tool.poetry.scripts",
    ]) {
      entryPoints.push(
        ...[
          ...section(source, group).matchAll(
            /^\s*([^#=]+?)\s*=\s*["']([^"']+)["']/gm,
          ),
        ].map((match) => `${match[1]!.trim()}:${match[2]}`),
      );
    }
    if (section(source, "tool.pytest.ini_options"))
      testConfiguration.push("pytest");
    if (
      (source.match(/\[/g)?.length ?? 0) !== (source.match(/\]/g)?.length ?? 0)
    )
      diagnostics.push("malformed-toml");
  } else if (isRequirements) {
    includes.push(
      ...[...source.matchAll(/^\s*(?:-r|--requirement)\s+([^\s#]+).*$/gm)].map(
        (match) => match[1]!,
      ),
    );
    dependencies.push(
      ...[
        ...source.matchAll(/^\s*([A-Za-z0-9_.-]+)(?=\s*(?:\[|[=<>~!;]|$))/gm),
      ].map((match) => match[1]!.toLowerCase()),
    );
  } else if (isMetadata) {
    name = /^Name:\s*(.+)$/im.exec(source)?.[1]?.trim() ?? null;
    dependencies.push(
      ...[...source.matchAll(/^Requires-Dist:\s*(.+)$/gim)].map((match) =>
        normalizedDependency(match[1]!),
      ),
    );
  } else if (isLock) {
    dependencies.push(
      ...[...source.matchAll(/^name\s*=\s*["']([^"']+)["']/gm)].map((match) =>
        match[1]!.toLowerCase(),
      ),
    );
  } else diagnostics.push("unsupported-python-manifest");

  return {
    ecosystem: "python",
    path: path.replaceAll("\\", "/"),
    format,
    name,
    dependencies: [...new Set(dependencies)].sort(),
    includes: [...new Set(includes)].sort(),
    entryPoints: [...new Set(entryPoints)].sort(),
    testConfiguration: [...new Set(testConfiguration)].sort(),
    detector: "python-packaging",
    version: PYTHON_PACKAGING_DETECTOR_VERSION,
    completeness: diagnostics.length === 0 ? "complete" : "partial",
    diagnostics: [...new Set(diagnostics)].sort(),
  };
}

export function detectPythonPackageLayout(paths: readonly string[]): string[] {
  return [
    ...new Set(
      paths
        .map((path) => path.replaceAll("\\", "/"))
        .filter((path) =>
          /(^|\/)(?:src\/)?[A-Za-z_][A-Za-z0-9_]*\/(?:__init__\.py|py\.typed)$/.test(
            path,
          ),
        )
        .map((path) => path.replace(/\/(?:__init__\.py|py\.typed)$/, "")),
    ),
  ].sort();
}

import { createHash } from "node:crypto";
import {
  NORMALIZED_ANALYSIS_SCHEMA_VERSION,
  parseNormalizedAnalysis,
  type AnalysisRelationship,
  type AnalysisSymbol,
  type NormalizedAnalysis,
} from "@fuzit/schemas";
import { parseGoManifest } from "../../manifests/go/parse.js";

export const GO_ANALYSIS_ADAPTER_VERSION = 1 as const;
export const GO_ANALYSIS_IDENTITY = `go:bounded-adapter@${GO_ANALYSIS_ADAPTER_VERSION}`;
export interface GoAnalysisInput {
  readonly repositoryId: string;
  readonly path: string;
  readonly contentHash: string;
  readonly source: string;
  readonly goMod?: string;
  readonly knownPackages?: Readonly<Record<string, string>>;
}
const id = (kind: string, value: string) =>
  `analysis:${kind}:${createHash("sha256").update(value).digest("hex")}`;

export class GoAnalysisAdapter {
  public readonly adapterVersion = GO_ANALYSIS_ADAPTER_VERSION;
  public readonly parserIdentity = GO_ANALYSIS_IDENTITY;
  public parse(input: GoAnalysisInput): NormalizedAnalysis {
    const analysisIdentity = `normalized-analysis@${NORMALIZED_ANALYSIS_SCHEMA_VERSION};${this.parserIdentity}`;
    if (!input.path.endsWith(".go"))
      return parseNormalizedAnalysis({
        schemaVersion: 1,
        repositoryId: input.repositoryId,
        analysisIdentity,
        files: [],
        modules: [],
        symbols: [],
        relationships: [],
        completeness: "unsupported",
        diagnostics: ["Unsupported Go source extension"],
      });
    const fileId = id("file", `${input.repositoryId}\0${input.path}`);
    const packageName =
      /^\s*package\s+(\w+)/mu.exec(input.source)?.[1] ?? "<unknown>";
    const symbols: AnalysisSymbol[] = [];
    const relationships: AnalysisRelationship[] = [];
    const lines = input.source.split(/\r?\n/u);
    let offset = 0;
    let importBlock = false;
    const location = (line: string, index: number) => ({
      start: { offset, line: index + 1, column: 1 },
      end: {
        offset: offset + line.length,
        line: index + 1,
        column: line.length + 1,
      },
    });
    const symbol = (
      kind: AnalysisSymbol["kind"],
      name: string,
      line: string,
      index: number,
    ) => {
      const range = location(line, index);
      symbols.push({
        id: id(
          "symbol",
          `${input.repositoryId}\0${input.path}\0${kind}\0${name}\0${offset}`,
        ),
        repositoryId: input.repositoryId,
        kind,
        name,
        fileId,
        range,
        exported: /^[A-Z]/u.test(name),
      });
    };
    const relation = (
      kind: AnalysisRelationship["kind"],
      target: string,
      line: string,
      index: number,
      basis: "parsed" | "configured" = "parsed",
    ) => {
      const targetPath = input.knownPackages?.[target];
      const range = location(line, index);
      relationships.push({
        id: id(
          kind,
          `${input.repositoryId}\0${input.path}\0${kind}\0${target}\0${offset}`,
        ),
        repositoryId: input.repositoryId,
        kind,
        sourceId: fileId,
        targetId: targetPath
          ? id("file", `${input.repositoryId}\0${targetPath}`)
          : null,
        unresolvedTarget: targetPath ? null : target,
        provenance: {
          sourceFileId: fileId,
          sourceSymbolId: null,
          range,
          basis,
          parserIdentity: this.parserIdentity,
          analysisIdentity,
          confidence: targetPath ? 1 : 0,
          resolution: targetPath ? "resolved" : "unresolved",
        },
      });
    };
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (/^\/\/(?:go:build| \+build)\s+/u.test(trimmed))
        relation(
          "configuration-link",
          trimmed.replace(/^\/\/\s*/u, ""),
          line,
          index,
          "configured",
        );
      if (/^import\s*\($/u.test(trimmed)) importBlock = true;
      else if (importBlock && trimmed === ")") importBlock = false;
      const imported =
        /^import\s+(?:[\w.]+\s+)?["`]([^"`]+)["`]$/u.exec(trimmed)?.[1] ??
        (importBlock
          ? /^(?:[\w.]+\s+)?["`]([^"`]+)["`]$/u.exec(trimmed)?.[1]
          : undefined);
      if (imported) relation("import", imported, line, index);
      const iface = /^type\s+(\w+)\s+interface\s*\{/u.exec(trimmed);
      if (iface) symbol("interface", iface[1]!, line, index);
      const method = /^func\s*\([^)]+\)\s*(\w+)\s*\(/u.exec(trimmed);
      const fn = /^func\s+(\w+)\s*\(/u.exec(trimmed);
      if (method) symbol("method", method[1]!, line, index);
      else if (fn)
        symbol(
          input.path.endsWith("_test.go") || fn[1]!.startsWith("Test")
            ? "test"
            : "function",
          fn[1]!,
          line,
          index,
        );
      const endpoint =
        /(?:HandleFunc|\.(GET|POST|PUT|PATCH|DELETE))\s*\(\s*["`]([^"`]+)["`]/u.exec(
          trimmed,
        );
      if (endpoint)
        symbol(
          "endpoint",
          `${endpoint[1] ?? "HTTP"} ${endpoint[2]!}`,
          line,
          index,
        );
      offset += line.length + 1;
    });
    if (input.goMod) {
      const manifest = parseGoManifest(input.goMod);
      if (manifest.module)
        relation(
          "configuration-link",
          manifest.module,
          "go.mod",
          0,
          "configured",
        );
      for (const item of [...manifest.replacements].sort((a, b) =>
        a.from.localeCompare(b.from),
      ))
        relation(
          "configuration-link",
          `${item.from}=>${item.to}`,
          "go.mod",
          0,
          "configured",
        );
    }
    const opens = (input.source.match(/\{/gu) ?? []).length,
      closes = (input.source.match(/\}/gu) ?? []).length;
    const diagnostics =
      packageName === "<unknown>"
        ? ["GO_SYNTAX: missing package declaration"]
        : opens === closes
          ? []
          : ["GO_SYNTAX: unbalanced braces"];
    return parseNormalizedAnalysis({
      schemaVersion: 1,
      repositoryId: input.repositoryId,
      analysisIdentity,
      files: [
        {
          id: fileId,
          repositoryId: input.repositoryId,
          kind: "file",
          path: input.path,
          language: "go",
          contentHash: input.contentHash,
        },
      ],
      modules: [
        {
          id: id("module", `${input.repositoryId}\0${packageName}`),
          repositoryId: input.repositoryId,
          kind: packageName === "main" ? "module" : "package",
          name: packageName,
          path: input.path,
        },
      ],
      symbols: symbols.sort((a, b) => a.id.localeCompare(b.id)),
      relationships: relationships.sort((a, b) => a.id.localeCompare(b.id)),
      completeness: diagnostics.length ? "partial" : "complete",
      diagnostics,
    });
  }
}

export * from "./typescript/index.js";
export * from "./python/index.js";
export * from "./java/index.js";
export * from "./go/index.js";

import { createHash } from "node:crypto";
import {
  NORMALIZED_ANALYSIS_SCHEMA_VERSION,
  parseNormalizedAnalysis,
  type AnalysisRelationship,
  type AnalysisSymbol,
  type NormalizedAnalysis,
} from "@fuzit/schemas";
import { parseJavaManifest } from "../../manifests/java/parse.js";

export const JAVA_ANALYSIS_ADAPTER_VERSION = 1 as const;
export const JAVA_ANALYSIS_IDENTITY = `java:bounded-adapter@${JAVA_ANALYSIS_ADAPTER_VERSION}`;

export interface JavaAnalysisInput {
  readonly repositoryId: string;
  readonly path: string;
  readonly contentHash: string;
  readonly source: string;
  readonly knownTypes?: Readonly<Record<string, string>>;
  readonly buildFiles?: readonly {
    readonly path: string;
    readonly source: string;
  }[];
}

const id = (kind: string, value: string) =>
  `analysis:${kind}:${createHash("sha256").update(value).digest("hex")}`;

export class JavaAnalysisAdapter {
  public readonly adapterVersion = JAVA_ANALYSIS_ADAPTER_VERSION;
  public readonly parserIdentity = JAVA_ANALYSIS_IDENTITY;

  public parse(input: JavaAnalysisInput): NormalizedAnalysis {
    const analysisIdentity = `normalized-analysis@${NORMALIZED_ANALYSIS_SCHEMA_VERSION};${this.parserIdentity}`;
    if (!input.path.endsWith(".java"))
      return parseNormalizedAnalysis({
        schemaVersion: 1,
        repositoryId: input.repositoryId,
        analysisIdentity,
        files: [],
        modules: [],
        symbols: [],
        relationships: [],
        completeness: "unsupported",
        diagnostics: ["Unsupported Java source extension"],
      });
    const fileId = id("file", `${input.repositoryId}\0${input.path}`);
    const packageName =
      /\bpackage\s+([\w.]+)\s*;/u.exec(input.source)?.[1] ?? "<default>";
    const symbols: AnalysisSymbol[] = [];
    const relationships: AnalysisRelationship[] = [];
    const lines = input.source.split(/\r?\n/u);
    let offset = 0;
    let annotation = "";
    const range = (line: string, index: number, at: number) => ({
      start: { offset: at, line: index + 1, column: 1 },
      end: {
        offset: at + line.length,
        line: index + 1,
        column: line.length + 1,
      },
    });
    const addSymbol = (
      kind: AnalysisSymbol["kind"],
      name: string,
      line: string,
      index: number,
    ) => {
      const location = range(line, index, offset);
      symbols.push({
        id: id(
          "symbol",
          `${input.repositoryId}\0${input.path}\0${kind}\0${name}\0${offset}`,
        ),
        repositoryId: input.repositoryId,
        kind,
        name,
        fileId,
        range: location,
        exported: /\bpublic\b/u.test(line),
      });
      return symbols.at(-1)!;
    };
    const addRelation = (
      kind: AnalysisRelationship["kind"],
      target: string,
      line: string,
      index: number,
      basis: "parsed" | "configured" = "parsed",
      sourceSymbolId: string | null = null,
    ) => {
      const targetPath = input.knownTypes?.[target];
      const location = range(line, index, offset);
      relationships.push({
        id: id(
          kind,
          `${input.repositoryId}\0${input.path}\0${kind}\0${target}\0${offset}`,
        ),
        repositoryId: input.repositoryId,
        kind,
        sourceId: fileId,
        targetId: targetPath
          ? id("file", `${input.repositoryId}\0${targetPath}`)
          : null,
        unresolvedTarget: targetPath ? null : target,
        provenance: {
          sourceFileId: fileId,
          sourceSymbolId,
          range: location,
          basis,
          parserIdentity: this.parserIdentity,
          analysisIdentity,
          confidence: targetPath ? 1 : 0,
          resolution: targetPath ? "resolved" : "unresolved",
        },
      });
    };
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed.startsWith("@")) annotation = trimmed;
      const imported = /^import\s+(?:static\s+)?([\w.*]+)\s*;/u.exec(
        trimmed,
      )?.[1];
      if (imported) addRelation("import", imported, line, index);
      const declaration =
        /\b(class|interface|record)\s+(\w+)(?:\s+extends\s+([\w.]+))?(?:\s+implements\s+([\w., ]+))?/u.exec(
          trimmed,
        );
      if (declaration) {
        const symbol = addSymbol(
          declaration[1] === "interface"
            ? "interface"
            : declaration[1] === "record"
              ? "type"
              : "class",
          declaration[2]!,
          line,
          index,
        );
        for (const target of [
          declaration[3],
          ...(declaration[4]?.split(",").map((v) => v.trim()) ?? []),
        ].filter(Boolean) as string[])
          addRelation("inheritance", target, line, index, "parsed", symbol.id);
      }
      const method =
        /(?:public|protected|private|static|final|synchronized|\s)+[\w<>,?[\].]+\s+(\w+)\s*\([^;]*\)\s*(?:\{|throws)/u.exec(
          trimmed,
        );
      if (method) {
        addSymbol(
          annotation.includes("@Test") || method[1]!.startsWith("test")
            ? "test"
            : "method",
          method[1]!,
          line,
          index,
        );
        const route =
          /@(Get|Post|Put|Patch|Delete)Mapping\s*\(\s*["']([^"']+)/u.exec(
            annotation,
          );
        if (route)
          addSymbol(
            "endpoint",
            `${route[1]!.toUpperCase()} ${route[2]!}`,
            line,
            index,
          );
        annotation = "";
      }
      offset += line.length + 1;
    });
    for (const build of [...(input.buildFiles ?? [])].sort((a, b) =>
      a.path.localeCompare(b.path),
    )) {
      for (const dependency of parseJavaManifest(
        build.source,
      ).dependencies.sort())
        addRelation(
          "configuration-link",
          dependency,
          build.path,
          0,
          "configured",
        );
    }
    const opens = (input.source.match(/\{/gu) ?? []).length;
    const closes = (input.source.match(/\}/gu) ?? []).length;
    const diagnostics =
      opens === closes ? [] : ["JAVA_SYNTAX: unbalanced braces"];
    return parseNormalizedAnalysis({
      schemaVersion: 1,
      repositoryId: input.repositoryId,
      analysisIdentity,
      files: [
        {
          id: fileId,
          repositoryId: input.repositoryId,
          kind: "file",
          path: input.path,
          language: "java",
          contentHash: input.contentHash,
        },
      ],
      modules: [
        {
          id: id("module", `${input.repositoryId}\0${packageName}`),
          repositoryId: input.repositoryId,
          kind: "package",
          name: packageName,
          path: input.path,
        },
      ],
      symbols: symbols.sort((a, b) => a.id.localeCompare(b.id)),
      relationships: relationships.sort((a, b) => a.id.localeCompare(b.id)),
      completeness: diagnostics.length ? "partial" : "complete",
      diagnostics,
    });
  }
}

import { createHash } from "node:crypto";

import {
  NORMALIZED_ANALYSIS_SCHEMA_VERSION,
  parseNormalizedAnalysis,
  type AnalysisRelationship,
  type AnalysisSymbol,
  type NormalizedAnalysis,
} from "@fuzit/schemas";

export const PYTHON_PARSER_ADAPTER_VERSION = 1 as const;
export const PYTHON_PARSER_IDENTITY = `python:syntax-adapter@${PYTHON_PARSER_ADAPTER_VERSION}`;
export const PYTHON_PARSER_MAX_SOURCE_BYTES = 4 * 1024 * 1024;

export interface PythonParserInput {
  readonly repositoryId: string;
  readonly path: string;
  readonly contentHash: string;
  readonly source: string;
  readonly knownModules?: Readonly<Record<string, string>>;
}

function stableId(kind: string, value: string): string {
  return `analysis:${kind}:${createHash("sha256").update(value).digest("hex")}`;
}

function moduleName(path: string): string {
  const withoutExtension = path.replace(/\.py$/u, "");
  const withoutInit = withoutExtension.endsWith("/__init__")
    ? withoutExtension.slice(0, -9)
    : withoutExtension;
  return withoutInit.split("/").filter(Boolean).join(".");
}

function syntaxDiagnostics(source: string): string[] {
  const diagnostics: string[] = [];
  const stack: string[] = [];
  const pairs: Readonly<Record<string, string>> = {
    ")": "(",
    "]": "[",
    "}": "{",
  };
  let quote: "'" | '"' | null = null;
  let escaped = false;
  for (let offset = 0; offset < source.length; offset += 1) {
    const character = source[offset]!;
    if (escaped) {
      escaped = false;
      continue;
    }
    if (character === "\\" && quote) {
      escaped = true;
      continue;
    }
    if (character === "'" || character === '"') {
      quote = quote === character ? null : (quote ?? character);
      continue;
    }
    if (quote) continue;
    if (["(", "[", "{"].includes(character)) stack.push(character);
    else if (pairs[character] && stack.pop() !== pairs[character]) {
      diagnostics.push(`PY_SYNTAX: unmatched delimiter at offset ${offset}`);
      break;
    }
  }
  if (quote) diagnostics.push("PY_SYNTAX: unterminated string literal");
  if (stack.length > 0) diagnostics.push("PY_SYNTAX: unclosed delimiter");
  source.split(/\r?\n/u).forEach((line, index) => {
    if (/^(?:def|class)\s+[^:]+$/u.test(line.trim())) {
      diagnostics.push(`PY_SYNTAX: missing suite colon at line ${index + 1}`);
    }
  });
  return diagnostics.slice(0, 128);
}

function pythonRange(line: string, lineIndex: number, offset: number) {
  const startColumn = line.length - line.trimStart().length + 1;
  return {
    start: {
      offset: offset + startColumn - 1,
      line: lineIndex + 1,
      column: startColumn,
    },
    end: {
      offset: offset + line.length,
      line: lineIndex + 1,
      column: line.length + 1,
    },
  };
}

function extractPythonRecords(
  input: PythonParserInput,
  fileId: string,
  analysisIdentity: string,
): { symbols: AnalysisSymbol[]; relationships: AnalysisRelationship[] } {
  const symbols: AnalysisSymbol[] = [];
  const relationships: AnalysisRelationship[] = [];
  const lines = input.source.split(/\r?\n/u);
  let offset = 0;
  let classIndent: number | null = null;
  let decorators: Array<{ line: string; index: number; offset: number }> = [];
  const addSymbol = (
    kind: AnalysisSymbol["kind"],
    name: string,
    line: string,
    lineIndex: number,
    lineOffset: number,
  ) => {
    const range = pythonRange(line, lineIndex, lineOffset);
    symbols.push({
      id: stableId(
        "symbol",
        `${input.repositoryId}\0${input.path}\0${kind}\0${name}\0${range.start.offset}`,
      ),
      repositoryId: input.repositoryId,
      kind,
      name,
      fileId,
      range,
      exported: !name.startsWith("_"),
    });
  };
  const addImport = (
    specifier: string,
    line: string,
    lineIndex: number,
    lineOffset: number,
    dynamic = false,
  ) => {
    const range = pythonRange(line, lineIndex, lineOffset);
    const targetPath = dynamic ? undefined : input.knownModules?.[specifier];
    relationships.push({
      id: stableId(
        "import",
        `${input.repositoryId}\0${input.path}\0${specifier}\0${range.start.offset}`,
      ),
      repositoryId: input.repositoryId,
      kind: "import",
      sourceId: fileId,
      targetId: targetPath
        ? stableId("file", `${input.repositoryId}\0${targetPath}`)
        : null,
      unresolvedTarget: targetPath ? null : specifier,
      provenance: {
        sourceFileId: fileId,
        sourceSymbolId: null,
        range,
        basis: dynamic ? "inferred" : "parsed",
        parserIdentity: PYTHON_PARSER_IDENTITY,
        analysisIdentity,
        confidence: targetPath ? 1 : dynamic ? 0.5 : 0,
        resolution: targetPath ? "resolved" : "unresolved",
      },
    });
  };
  lines.forEach((line, index) => {
    const trimmed = line.trim();
    const indent = line.length - line.trimStart().length;
    if (
      classIndent !== null &&
      trimmed &&
      indent <= classIndent &&
      !trimmed.startsWith("@")
    ) {
      classIndent = null;
    }
    if (trimmed.startsWith("@")) {
      decorators.push({ line, index, offset });
      offset += line.length + 1;
      return;
    }
    const classMatch =
      /^(?:class)\s+([\p{L}_][\p{L}\p{N}_]*)(?:\(([^)]*)\))?\s*:/u.exec(
        trimmed,
      );
    const functionMatch =
      /^(?:async\s+)?def\s+([\p{L}_][\p{L}\p{N}_]*)\s*\(/u.exec(trimmed);
    if (classMatch) {
      const name = classMatch[1]!;
      const schema = /(?:Schema$|BaseModel)/u.test(
        `${name} ${classMatch[2] ?? ""}`,
      );
      addSymbol(schema ? "schema" : "class", name, line, index, offset);
      classIndent = indent;
    } else if (functionMatch) {
      const name = functionMatch[1]!;
      addSymbol(
        name.startsWith("test_")
          ? "test"
          : classIndent !== null && indent > classIndent
            ? "method"
            : "function",
        name,
        line,
        index,
        offset,
      );
      for (const decorator of decorators) {
        const route =
          /\.((?:get|post|put|patch|delete))\(\s*["']([^"']+)["']/u.exec(
            decorator.line,
          );
        if (route)
          addSymbol(
            "endpoint",
            `${route[1]!.toUpperCase()} ${route[2]!}`,
            decorator.line,
            decorator.index,
            decorator.offset,
          );
      }
    }
    const importMatch = /^import\s+(.+)$/u.exec(trimmed);
    const fromMatch = /^from\s+([^\s]+)\s+import\s+/u.exec(trimmed);
    if (importMatch) {
      for (const item of importMatch[1]!.split(","))
        addImport(item.trim().split(/\s+as\s+/u)[0]!, line, index, offset);
    } else if (fromMatch) {
      addImport(fromMatch[1]!, line, index, offset);
    }
    const dynamic = /(?:importlib\.import_module|__import__)\(\s*([^)]*)/u.exec(
      trimmed,
    );
    if (dynamic) addImport("<dynamic>", line, index, offset, true);
    decorators = [];
    offset += line.length + 1;
  });
  return {
    symbols: symbols.sort((a, b) => a.id.localeCompare(b.id)),
    relationships: relationships.sort((a, b) => a.id.localeCompare(b.id)),
  };
}

export class PythonParserAdapter {
  public readonly adapterVersion = PYTHON_PARSER_ADAPTER_VERSION;
  public readonly parserIdentity = PYTHON_PARSER_IDENTITY;

  public parse(input: PythonParserInput): NormalizedAnalysis {
    const base = {
      schemaVersion: NORMALIZED_ANALYSIS_SCHEMA_VERSION,
      repositoryId: input.repositoryId,
      analysisIdentity: `normalized-analysis@${NORMALIZED_ANALYSIS_SCHEMA_VERSION};${this.parserIdentity}`,
      symbols: [],
      relationships: [],
    } as const;
    if (!input.path.endsWith(".py")) {
      return parseNormalizedAnalysis({
        ...base,
        files: [],
        modules: [],
        completeness: "unsupported",
        diagnostics: ["Unsupported Python source extension"],
      });
    }
    if (
      Buffer.byteLength(input.source, "utf8") > PYTHON_PARSER_MAX_SOURCE_BYTES
    ) {
      return parseNormalizedAnalysis({
        ...base,
        files: [],
        modules: [],
        completeness: "failed",
        diagnostics: [
          `Source exceeds parser limit of ${PYTHON_PARSER_MAX_SOURCE_BYTES} bytes`,
        ],
      });
    }
    const diagnostics = syntaxDiagnostics(input.source);
    const fileId = stableId("file", `${input.repositoryId}\0${input.path}`);
    const name = moduleName(input.path);
    const extracted = extractPythonRecords(
      input,
      fileId,
      base.analysisIdentity,
    );
    return parseNormalizedAnalysis({
      ...base,
      files: [
        {
          id: fileId,
          repositoryId: input.repositoryId,
          kind: "file",
          path: input.path,
          language: "python",
          contentHash: input.contentHash,
        },
      ],
      modules: [
        {
          id: stableId("module", `${input.repositoryId}\0${name}`),
          repositoryId: input.repositoryId,
          kind: input.path.endsWith("/__init__.py") ? "package" : "module",
          name,
          path: input.path,
        },
      ],
      completeness: diagnostics.length > 0 ? "partial" : "complete",
      diagnostics,
      symbols: extracted.symbols,
      relationships: extracted.relationships,
    });
  }
}

import { createHash } from "node:crypto";
import { extname, posix } from "node:path";

import ts from "typescript";

import {
  NORMALIZED_ANALYSIS_SCHEMA_VERSION,
  parseNormalizedAnalysis,
  type AnalysisSymbol,
  type AnalysisRelationship,
  type NormalizedAnalysis,
} from "@fuzit/schemas";

export const TYPESCRIPT_PARSER_ADAPTER_VERSION = 1 as const;
export const TYPESCRIPT_PARSER_IDENTITY = `typescript@${ts.version}:syntax-adapter@${TYPESCRIPT_PARSER_ADAPTER_VERSION}`;
export const TYPESCRIPT_PARSER_MAX_SOURCE_BYTES = 4 * 1024 * 1024;

export interface TypeScriptParserInput {
  readonly repositoryId: string;
  readonly path: string;
  readonly contentHash: string;
  readonly source: string;
  readonly tsconfigPath?: string | null;
  readonly resolution?: TypeScriptModuleResolution;
}

export interface TypeScriptModuleResolution {
  readonly knownFiles: readonly string[];
  readonly pathAliases?: Readonly<Record<string, string>>;
  readonly packageExports?: Readonly<Record<string, string>>;
  readonly projectReferences?: Readonly<Record<string, string>>;
}

const scriptKinds: Readonly<Record<string, ts.ScriptKind>> = {
  ".ts": ts.ScriptKind.TS,
  ".tsx": ts.ScriptKind.TSX,
  ".js": ts.ScriptKind.JS,
  ".jsx": ts.ScriptKind.JSX,
  ".mjs": ts.ScriptKind.JS,
  ".cjs": ts.ScriptKind.JS,
  ".mts": ts.ScriptKind.TS,
  ".cts": ts.ScriptKind.TS,
};

function stableId(kind: string, identity: string): string {
  return `analysis:${kind}:${createHash("sha256").update(identity).digest("hex")}`;
}

function safeDiagnostic(diagnostic: ts.Diagnostic): string {
  return `TS${diagnostic.code}: syntax diagnostic at offset ${diagnostic.start ?? 0}`;
}

function rangeOf(sourceFile: ts.SourceFile, node: ts.Node) {
  const startOffset = node.getStart(sourceFile, false);
  const endOffset = node.getEnd();
  const start = sourceFile.getLineAndCharacterOfPosition(startOffset);
  const end = sourceFile.getLineAndCharacterOfPosition(endOffset);
  return {
    start: {
      offset: startOffset,
      line: start.line + 1,
      column: start.character + 1,
    },
    end: {
      offset: endOffset,
      line: end.line + 1,
      column: end.character + 1,
    },
  };
}

function hasExportModifier(node: ts.Node): boolean {
  return ts.canHaveModifiers(node)
    ? (ts
        .getModifiers(node)
        ?.some(
          (modifier) =>
            modifier.kind === ts.SyntaxKind.ExportKeyword ||
            modifier.kind === ts.SyntaxKind.DefaultKeyword,
        ) ?? false)
    : false;
}

function declarationName(node: ts.NamedDeclaration, fallback: string): string {
  const name = node.name;
  if (name && (ts.isIdentifier(name) || ts.isStringLiteral(name))) {
    return name.text;
  }
  return fallback;
}

function extractSymbols(
  sourceFile: ts.SourceFile,
  repositoryId: string,
  path: string,
  fileId: string,
): AnalysisSymbol[] {
  const symbols: AnalysisSymbol[] = [];
  const add = (
    node: ts.Node,
    kind: AnalysisSymbol["kind"],
    name: string,
    exported = false,
  ) => {
    const range = rangeOf(sourceFile, node);
    symbols.push({
      id: stableId(
        "symbol",
        `${repositoryId}\0${path}\0${kind}\0${name}\0${range.start.offset}`,
      ),
      repositoryId,
      kind,
      name,
      fileId,
      range,
      exported,
    });
  };
  const visit = (node: ts.Node) => {
    if (ts.isFunctionDeclaration(node)) {
      add(
        node,
        "function",
        declarationName(node, "default"),
        hasExportModifier(node),
      );
    } else if (ts.isClassDeclaration(node)) {
      add(
        node,
        "class",
        declarationName(node, "default"),
        hasExportModifier(node),
      );
    } else if (ts.isInterfaceDeclaration(node)) {
      add(node, "interface", node.name.text, hasExportModifier(node));
    } else if (ts.isTypeAliasDeclaration(node)) {
      add(node, "type", node.name.text, hasExportModifier(node));
    } else if (ts.isMethodDeclaration(node)) {
      add(node, "method", declarationName(node, "anonymous"));
    } else if (ts.isVariableStatement(node)) {
      for (const declaration of node.declarationList.declarations) {
        if (ts.isIdentifier(declaration.name)) {
          const name = declaration.name.text;
          const isSchema = /Schema$/u.test(name);
          add(
            declaration,
            isSchema ? "schema" : "variable",
            name,
            hasExportModifier(node),
          );
        }
      }
    } else if (ts.isCallExpression(node)) {
      const expressionName = ts.isIdentifier(node.expression)
        ? node.expression.text
        : ts.isPropertyAccessExpression(node.expression)
          ? node.expression.name.text
          : undefined;
      const firstArgument = node.arguments[0];
      if (
        expressionName &&
        ["describe", "it", "test"].includes(expressionName) &&
        firstArgument &&
        ts.isStringLiteral(firstArgument)
      ) {
        add(node, "test", firstArgument.text);
      } else if (
        expressionName &&
        ["get", "post", "put", "patch", "delete"].includes(expressionName) &&
        firstArgument &&
        ts.isStringLiteral(firstArgument)
      ) {
        add(
          node,
          "endpoint",
          `${expressionName.toUpperCase()} ${firstArgument.text}`,
        );
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  return symbols.sort((left, right) => left.id.localeCompare(right.id));
}

function resolveModulePath(
  sourcePath: string,
  specifier: string,
  resolution: TypeScriptModuleResolution | undefined,
): string | null {
  if (!resolution) return null;
  const known = new Set(resolution.knownFiles);
  let candidate: string | undefined;
  if (specifier.startsWith(".")) {
    candidate = posix.normalize(
      posix.join(posix.dirname(sourcePath), specifier),
    );
    if (
      candidate.startsWith("../") ||
      candidate === ".." ||
      posix.isAbsolute(candidate)
    ) {
      return null;
    }
  } else {
    candidate =
      resolution.packageExports?.[specifier] ??
      resolution.projectReferences?.[specifier];
    if (!candidate) {
      for (const [pattern, target] of Object.entries(
        resolution.pathAliases ?? {},
      ).sort(([left], [right]) => left.localeCompare(right))) {
        if (
          pattern.endsWith("*") &&
          specifier.startsWith(pattern.slice(0, -1))
        ) {
          candidate = target.replace("*", specifier.slice(pattern.length - 1));
          break;
        }
        if (pattern === specifier) candidate = target;
      }
    }
  }
  if (!candidate) return null;
  const candidates = [
    candidate,
    ...[".ts", ".tsx", ".js", ".jsx", ".mts", ".cts", ".mjs", ".cjs"].map(
      (extension) => `${candidate}${extension}`,
    ),
    ...["ts", "tsx", "js", "jsx"].map(
      (extension) => `${candidate}/index.${extension}`,
    ),
  ];
  return candidates.find((path) => known.has(path)) ?? null;
}

function extractRelationships(
  sourceFile: ts.SourceFile,
  input: TypeScriptParserInput,
  fileId: string,
  symbols: readonly AnalysisSymbol[],
): AnalysisRelationship[] {
  const relationships: AnalysisRelationship[] = [];
  const add = (
    node: ts.Node,
    kind: "import" | "export",
    specifier: string,
    basis: "parsed" | "inferred",
    forceUnresolved = false,
    explicitTargetId?: string,
  ) => {
    const targetPath = forceUnresolved
      ? null
      : resolveModulePath(input.path, specifier, input.resolution);
    const targetId =
      explicitTargetId ??
      (targetPath
        ? stableId("file", `${input.repositoryId}\0${targetPath}`)
        : null);
    const range = rangeOf(sourceFile, node);
    relationships.push({
      id: stableId(
        kind,
        `${input.repositoryId}\0${input.path}\0${kind}\0${specifier}\0${range.start.offset}`,
      ),
      repositoryId: input.repositoryId,
      kind,
      sourceId: fileId,
      targetId,
      unresolvedTarget: targetId ? null : specifier,
      provenance: {
        sourceFileId: fileId,
        sourceSymbolId: null,
        range,
        basis,
        parserIdentity: TYPESCRIPT_PARSER_IDENTITY,
        analysisIdentity: `normalized-analysis@${NORMALIZED_ANALYSIS_SCHEMA_VERSION}`,
        confidence: targetId ? 1 : basis === "inferred" ? 0.5 : 0,
        resolution: targetId ? "resolved" : "unresolved",
      },
    });
  };
  const visit = (node: ts.Node) => {
    if (
      hasExportModifier(node) &&
      (ts.isFunctionDeclaration(node) ||
        ts.isClassDeclaration(node) ||
        ts.isInterfaceDeclaration(node) ||
        ts.isTypeAliasDeclaration(node))
    ) {
      const name = declarationName(node, "default");
      const startOffset = node.getStart(sourceFile, false);
      const target = symbols.find(
        (symbol) =>
          symbol.name === name && symbol.range.start.offset === startOffset,
      );
      add(node, "export", name, "parsed", false, target?.id);
    } else if (ts.isVariableStatement(node) && hasExportModifier(node)) {
      for (const declaration of node.declarationList.declarations) {
        if (ts.isIdentifier(declaration.name)) {
          const name = declaration.name.text;
          const target = symbols.find(
            (symbol) =>
              symbol.name === name &&
              symbol.range.start.offset ===
                declaration.getStart(sourceFile, false),
          );
          add(declaration, "export", name, "parsed", false, target?.id);
        }
      }
    } else if (
      ts.isImportDeclaration(node) &&
      ts.isStringLiteral(node.moduleSpecifier)
    ) {
      add(node, "import", node.moduleSpecifier.text, "parsed");
    } else if (ts.isExportDeclaration(node)) {
      if (node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
        add(node, "export", node.moduleSpecifier.text, "parsed");
      } else if (node.exportClause && ts.isNamedExports(node.exportClause)) {
        for (const element of node.exportClause.elements) {
          const target = symbols.find(
            ({ name }) =>
              name === element.propertyName?.text || name === element.name.text,
          );
          add(
            element,
            "export",
            element.name.text,
            "parsed",
            false,
            target?.id,
          );
        }
      }
    } else if (ts.isExportAssignment(node)) {
      const target = symbols.find(({ name }) => name === "default");
      add(node, "export", "default", "parsed", false, target?.id);
    } else if (ts.isCallExpression(node)) {
      const first = node.arguments[0];
      if (
        ts.isIdentifier(node.expression) &&
        node.expression.text === "require" &&
        first &&
        ts.isStringLiteral(first)
      ) {
        add(node, "import", first.text, "parsed");
      } else if (node.expression.kind === ts.SyntaxKind.ImportKeyword) {
        add(
          node,
          "import",
          first && ts.isStringLiteral(first) ? first.text : "<dynamic>",
          "inferred",
          true,
        );
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  return relationships.sort((left, right) => left.id.localeCompare(right.id));
}

export class TypeScriptParserAdapter {
  public readonly adapterVersion = TYPESCRIPT_PARSER_ADAPTER_VERSION;
  public readonly parserIdentity = TYPESCRIPT_PARSER_IDENTITY;

  public parse(input: TypeScriptParserInput): NormalizedAnalysis {
    const extension = extname(input.path).toLowerCase();
    const scriptKind = scriptKinds[extension];
    const base = {
      schemaVersion: NORMALIZED_ANALYSIS_SCHEMA_VERSION,
      repositoryId: input.repositoryId,
      analysisIdentity: `normalized-analysis@${NORMALIZED_ANALYSIS_SCHEMA_VERSION};${this.parserIdentity}`,
      modules: [],
      symbols: [],
      relationships: [],
    } as const;

    if (scriptKind === undefined) {
      return parseNormalizedAnalysis({
        ...base,
        files: [],
        completeness: "unsupported",
        diagnostics: [`Unsupported source extension: ${extension || "none"}`],
      });
    }

    if (
      Buffer.byteLength(input.source, "utf8") >
      TYPESCRIPT_PARSER_MAX_SOURCE_BYTES
    ) {
      return parseNormalizedAnalysis({
        ...base,
        files: [],
        completeness: "failed",
        diagnostics: [
          `Source exceeds parser limit of ${TYPESCRIPT_PARSER_MAX_SOURCE_BYTES} bytes`,
        ],
      });
    }

    const transpiled = ts.transpileModule(input.source, {
      fileName: input.path,
      reportDiagnostics: true,
      compilerOptions: {
        target: ts.ScriptTarget.Latest,
        module: ts.ModuleKind.Preserve,
        jsx: ts.JsxEmit.Preserve,
      },
    });
    const diagnostics = (transpiled.diagnostics ?? [])
      .slice(0, 128)
      .map(safeDiagnostic);
    const sourceFile = ts.createSourceFile(
      input.path,
      input.source,
      ts.ScriptTarget.Latest,
      false,
      scriptKind,
    );
    const fileId = stableId("file", `${input.repositoryId}\0${input.path}`);
    const symbols = extractSymbols(
      sourceFile,
      input.repositoryId,
      input.path,
      fileId,
    );
    return parseNormalizedAnalysis({
      ...base,
      files: [
        {
          id: fileId,
          repositoryId: input.repositoryId,
          kind: "file",
          path: input.path,
          language:
            scriptKind === ts.ScriptKind.JS || scriptKind === ts.ScriptKind.JSX
              ? "javascript"
              : "typescript",
          contentHash: input.contentHash,
        },
      ],
      symbols,
      relationships: extractRelationships(sourceFile, input, fileId, symbols),
      completeness: diagnostics.length === 0 ? "complete" : "partial",
      diagnostics,
    });
  }
}

import { createHash } from "node:crypto";
import {
  parseNormalizedAnalysis,
  type AnalysisEvidenceBasis,
  type AnalysisRelationship,
  type NormalizedAnalysis,
} from "@fuzit/schemas";

export type CrossLanguageRelationKind =
  "test" | "endpoint" | "schema" | "configuration-link";

export interface CrossLanguageRelationCandidate {
  readonly kind: CrossLanguageRelationKind;
  readonly sourceSymbolId: string;
  readonly targetId?: string | null;
  readonly unresolvedTarget?: string | null;
  readonly basis: AnalysisEvidenceBasis;
  readonly originIdentity: string;
  readonly frameworkIdentity?: string | null;
  readonly confidence: number;
}

const relationshipId = (identity: string) =>
  `analysis:relation:${createHash("sha256").update(identity).digest("hex")}`;

export function enrichCrossLanguageRelations(
  analysis: NormalizedAnalysis,
  candidates: readonly CrossLanguageRelationCandidate[],
): NormalizedAnalysis {
  const symbols = new Map(
    analysis.symbols.map((symbol) => [symbol.id, symbol]),
  );
  const validIds = new Set([
    ...analysis.files.map(({ id }) => id),
    ...analysis.modules.map(({ id }) => id),
    ...analysis.symbols.map(({ id }) => id),
  ]);
  const diagnostics = [...analysis.diagnostics];
  const accepted = candidates
    .filter((candidate) => {
      if (!symbols.has(candidate.sourceSymbolId)) {
        diagnostics.push("ANALYSIS_RELATION_SKIPPED: unknown source symbol");
        return false;
      }
      if (
        (candidate.kind === "endpoint" || candidate.kind === "schema") &&
        !candidate.frameworkIdentity
      ) {
        diagnostics.push(
          `ANALYSIS_RELATION_SKIPPED: ${candidate.kind} candidate lacks framework evidence`,
        );
        return false;
      }
      if (candidate.targetId && !validIds.has(candidate.targetId)) {
        diagnostics.push("ANALYSIS_RELATION_SKIPPED: unknown target identity");
        return false;
      }
      return true;
    })
    .sort((left, right) =>
      JSON.stringify(left).localeCompare(JSON.stringify(right)),
    );
  const groups = new Map<string, Set<string>>();
  for (const candidate of accepted) {
    const key = `${candidate.kind}\0${candidate.sourceSymbolId}`;
    const targets = groups.get(key) ?? new Set<string>();
    targets.add(
      candidate.targetId ?? candidate.unresolvedTarget ?? "<unresolved>",
    );
    groups.set(key, targets);
  }
  const relationships: AnalysisRelationship[] = accepted.map((candidate) => {
    const source = symbols.get(candidate.sourceSymbolId)!;
    const ambiguous =
      (groups.get(`${candidate.kind}\0${candidate.sourceSymbolId}`)?.size ??
        0) > 1;
    const targetId = candidate.targetId ?? null;
    return {
      id: relationshipId(
        `${analysis.repositoryId}\0${candidate.kind}\0${candidate.sourceSymbolId}\0${targetId ?? candidate.unresolvedTarget}\0${candidate.originIdentity}`,
      ),
      repositoryId: analysis.repositoryId,
      kind: candidate.kind,
      sourceId: candidate.sourceSymbolId,
      targetId,
      unresolvedTarget: targetId
        ? null
        : (candidate.unresolvedTarget ?? "<unresolved>"),
      provenance: {
        sourceFileId: source.fileId,
        sourceSymbolId: source.id,
        range: source.range,
        basis: candidate.basis,
        parserIdentity: candidate.originIdentity,
        analysisIdentity: analysis.analysisIdentity,
        confidence: ambiguous
          ? Math.min(candidate.confidence, 0.5)
          : candidate.confidence,
        resolution: ambiguous
          ? "ambiguous"
          : targetId
            ? "resolved"
            : "unresolved",
      },
    };
  });
  return parseNormalizedAnalysis({
    ...analysis,
    relationships: [...analysis.relationships, ...relationships].sort((a, b) =>
      a.id.localeCompare(b.id),
    ),
    diagnostics: diagnostics.slice(0, 128),
    completeness:
      diagnostics.length > analysis.diagnostics.length &&
      analysis.completeness === "complete"
        ? "partial"
        : analysis.completeness,
  });
}

import { describe, expect, it } from "vitest";

import { createRepositoryFact } from "../src/index.js";

const fact = (basis: "direct" | "inferred", detector = "manifest") =>
  createRepositoryFact({
    kind: "language",
    value: "TypeScript",
    confidence: basis === "direct" ? 1 : 0.7,
    basis,
    evidence: ["package.json"],
    detector,
    conflictsWith: [],
  });

describe("repository facts", () => {
  it("distinguishes direct and inferred facts", () =>
    expect(fact("direct").basis).not.toBe(fact("inferred").basis));
  it("requires a confidence basis", () =>
    expect(fact("direct")).toMatchObject({
      confidence: 1,
      evidence: ["package.json"],
    }));
  it("preserves multiple detectors", () =>
    expect([fact("direct"), fact("inferred", "extension")]).toHaveLength(2));
  it("represents conflicts", () =>
    expect(
      createRepositoryFact({ ...fact("direct"), conflictsWith: ["fact:other"] })
        .conflictsWith,
    ).toEqual(["fact:other"]));
  it("creates stable IDs", () =>
    expect(fact("direct").id).toBe(fact("direct").id));
});

import { describe, expect, it } from "vitest";
import { dependencyCycles, extractDependencies } from "../src/index.js";
describe("dependency extraction", () => {
  it("extracts relative imports", () =>
    expect(extractDependencies("a.ts", 'import "./b"')[0]).toMatchObject({
      kind: "relative",
      resolved: true,
    }));
  it("extracts workspace imports", () =>
    expect(extractDependencies("a.ts", 'import "@scope/pkg"')[0]?.kind).toBe(
      "external",
    ));
  it("keeps aliases unresolved", () =>
    expect(extractDependencies("a.ts", 'import "alias/*"')[0]?.resolved).toBe(
      false,
    ));
  it("marks dynamic imports", () =>
    expect(extractDependencies("a.ts", 'import("./b")')[0]?.kind).toBe(
      "dynamic",
    ));
  it("reports deterministic cycles", () =>
    expect(
      dependencyCycles([
        { from: "a.ts", specifier: "./a", kind: "relative", resolved: true },
      ]),
    ).toHaveLength(1));
  it("extracts external dependencies", () =>
    expect(extractDependencies("a.ts", 'import "zod"')[0]?.kind).toBe(
      "external",
    ));
});

import { describe, expect, it } from "vitest";
import { detectFrameworks } from "../src/index.js";
const detect = (dependencies: string[], scripts: Record<string, string> = {}) =>
  detectFrameworks({ packageName: "x", dependencies, scripts });
describe("framework detectors", () => {
  it("represents conflicting frameworks", () =>
    expect(detect(["express", "fastify"]).conflicts).toEqual([
      "multiple server frameworks",
    ]));
  it("keeps monorepo packages independent", () =>
    expect([detect(["react"]), detect(["express"])]).toHaveLength(2));
  it("detects test-only dependencies", () =>
    expect(detect(["vitest"]).tests).toEqual(["vitest"]));
  it("avoids name-only false positives", () =>
    expect(detect(["not-react"]).frameworks).toEqual([]));
  it("preserves custom entry points", () =>
    expect(detect([], { start: "node custom.js" }).entryPoints).toEqual([
      "start:node custom.js",
    ]));
  it("distinguishes React-only from confirmed Next.js App Router", () => {
    const react = detectFrameworks({
      packageName: "ui",
      packageRoot: "packages/ui",
      dependencies: ["react"],
      dependencyVersions: { react: "^19" },
      scripts: {},
      imports: ["react"],
    });
    const next = detectFrameworks({
      packageName: "web",
      packageRoot: "apps/web",
      dependencies: ["next", "react"],
      dependencyVersions: { next: "15" },
      scripts: {},
      sourcePaths: ["apps/web/app/layout.tsx"],
    });
    expect(react.evidence).toEqual([
      {
        framework: "react",
        packageName: "ui",
        packageRoot: "packages/ui",
        support: "confirmed",
        versionHint: "^19",
        evidence: ["dependency:react", "import:react"],
        detector: "framework-manifest-analysis",
        detectorVersion: "1",
      },
    ]);
    expect(
      next.evidence.find(({ framework }) => framework === "next"),
    ).toMatchObject({
      support: "confirmed",
      evidence: ["dependency:next", "layout:app-router"],
    });
  });
  it("detects Pages Router and package-scoped configuration evidence", () => {
    const result = detectFrameworks({
      packageName: "web",
      dependencies: ["next"],
      scripts: {},
      sourcePaths: ["pages/index.tsx"],
      configurationPaths: ["next.config.mjs"],
    });
    expect(result.evidence[0]?.evidence).toEqual([
      "dependency:next",
      "layout:pages-router",
      "configuration:next",
    ]);
  });
  it("keeps installed-but-unused Next.js declared and ignores filename lookalikes", () => {
    expect(
      detectFrameworks({
        packageName: "x",
        dependencies: ["next"],
        scripts: {},
        sourcePaths: ["next-notes.ts"],
      }).evidence[0]?.support,
    ).toBe("declared");
    expect(
      detectFrameworks({
        packageName: "x",
        dependencies: [],
        scripts: {},
        sourcePaths: ["app/page.tsx"],
      }).evidence,
    ).toEqual([]);
  });
  it.each([
    ["express", "express", "express", "express:get:/users"],
    ["fastify", "fastify", "fastify", "fastify:post:/users"],
    ["@nestjs/core", "nestjs", "@nestjs/core", "nestjs:Get:/users"],
  ] as const)(
    "detects attributable %s route evidence",
    (dependency, framework, imported, route) => {
      const result = detectFrameworks({
        packageName: "api",
        dependencies: [dependency],
        scripts: { start: "metadata-only" },
        imports: [imported],
        apiUsage: [route],
      });
      expect(result.evidence[0]).toMatchObject({
        framework,
        support: "confirmed",
        evidence: [
          `dependency:${dependency}`,
          `import:${dependency}`,
          `route:${route.split(":").slice(1).join(":")}`,
        ],
      });
    },
  );
  it("keeps unused backend dependencies declared and represents confirmed conflicts", () => {
    expect(
      detectFrameworks({
        packageName: "api",
        dependencies: ["express"],
        scripts: {},
      }).evidence[0]?.support,
    ).toBe("declared");
    const mixed = detectFrameworks({
      packageName: "api",
      dependencies: ["express", "fastify"],
      scripts: {},
      imports: ["express", "fastify"],
    });
    expect(mixed.conflicts).toEqual([
      "multiple confirmed server frameworks: express, fastify",
    ]);
  });
  it("requires dependency evidence for route-like API usage", () => {
    expect(
      detectFrameworks({
        packageName: "api",
        dependencies: [],
        scripts: {},
        apiUsage: ["express:get:/fake"],
      }).evidence,
    ).toEqual([]);
  });
  it.each([
    ["fastapi", "fastapi", "fastapi:get:/users"],
    ["flask", "flask", "flask:route:/users"],
    ["django", "django", "django:path:/users"],
  ] as const)(
    "detects confirmed Python framework %s evidence",
    (dependency, imported, route) => {
      const result = detectFrameworks({
        packageName: "py",
        dependencies: [dependency],
        scripts: {},
        imports: [imported],
        apiUsage: [route],
      });
      expect(result.evidence[0]).toMatchObject({
        framework: dependency,
        support: "confirmed",
        evidence: [
          `dependency:${dependency}`,
          `import:${dependency}`,
          `route:${route.split(":").slice(1).join(":")}`,
        ],
      });
    },
  );
  it("keeps installed-but-unused Python frameworks declared and reports mixed confirmed frameworks", () => {
    expect(
      detectFrameworks({
        packageName: "py",
        dependencies: ["fastapi"],
        scripts: {},
      }).evidence[0]?.support,
    ).toBe("declared");
    const mixed = detectFrameworks({
      packageName: "py",
      dependencies: ["fastapi", "flask"],
      scripts: {},
      imports: ["fastapi", "flask"],
    });
    expect(mixed.conflicts).toEqual([
      "multiple confirmed server frameworks: fastapi, flask",
    ]);
  });
  it("uses Django URL configuration and console entry-point evidence", () => {
    expect(
      detectFrameworks({
        packageName: "py",
        dependencies: ["django"],
        scripts: {},
        configurationPaths: ["project/urls.py"],
      }).evidence[0]?.evidence,
    ).toContain("configuration:django");
    expect(
      detectFrameworks({
        packageName: "py",
        dependencies: ["flask"],
        scripts: { start: "flask run" },
      }).evidence[0]?.evidence,
    ).toContain("entry-point");
  });
  it("confirms Vitest and Jest from config aliases, imports, globals, scripts, and layout", () => {
    const result = detectFrameworks({
      packageName: "mixed-tests",
      dependencies: ["vitest", "jest"],
      scripts: { unit: "vitest --config aliases.ts", legacy: "jest" },
      configurationPaths: ["vitest.config.ts", "jest.config.cjs"],
      sourcePaths: ["tests/a.test.ts"],
      imports: ["vitest", "@jest/globals"],
      apiUsage: ["vitest:global:describe", "jest:global:expect"],
    });
    expect(
      result.testEvidence.map(({ framework, support }) => [framework, support]),
    ).toEqual([
      ["jest", "confirmed"],
      ["vitest", "confirmed"],
    ]);
    expect(result.conflicts).toContain(
      "multiple confirmed test frameworks: jest, vitest",
    );
  });
  it("keeps unused test dependencies declared and produces no fact for no-test fixtures", () => {
    expect(
      detectFrameworks({
        packageName: "declared",
        dependencies: ["vitest"],
        scripts: {},
      }).testEvidence[0]?.support,
    ).toBe("declared");
    expect(
      detectFrameworks({
        packageName: "none",
        dependencies: [],
        scripts: {},
        sourcePaths: ["tests/a.test.ts"],
      }).testEvidence,
    ).toEqual([]);
  });
  it("detects Spring Boot framework with annotation, configuration, and entry-point evidence", () => {
    const result = detectFrameworks({
      packageName: "java-service",
      dependencies: ["org.springframework.boot:spring-boot-starter-web"],
      dependencyVersions: {
        "org.springframework.boot:spring-boot-starter-web": "3.2.0",
      },
      scripts: {},
      configurationPaths: ["src/main/resources/application.yml"],
      sourcePaths: ["src/main/java/com/example/DemoApplication.java"],
      imports: ["org.springframework.boot.autoconfigure.SpringBootApplication"],
      apiUsage: ["spring:annotation:@SpringBootApplication"],
    });
    expect(result.frameworks).toEqual(["spring-boot"]);
    expect(result.evidence[0]).toMatchObject({
      framework: "spring-boot",
      support: "confirmed",
      versionHint: "3.2.0",
    });
    expect(result.evidence[0]?.evidence).toEqual([
      "dependency:org.springframework.boot:spring-boot-starter-web",
      "import:spring",
      "annotation:@SpringBootApplication",
      "configuration:application-properties",
      "entry-point",
    ]);
  });
  it("detects JUnit 4 and JUnit 5 evidence and version hints", () => {
    const junit4Result = detectFrameworks({
      packageName: "legacy-java",
      dependencies: ["junit:junit"],
      scripts: {},
      imports: ["org.junit.Test"],
      apiUsage: ["junit:annotation:Test"],
    });
    expect(junit4Result.tests).toEqual(["junit"]);
    expect(junit4Result.testEvidence[0]).toMatchObject({
      framework: "junit",
      support: "confirmed",
      versionHint: "4",
    });

    const junit5Result = detectFrameworks({
      packageName: "modern-java",
      dependencies: ["org.junit.jupiter:junit-jupiter-api"],
      scripts: {},
      sourcePaths: ["src/test/java/com/example/AppTest.java"],
    });
    expect(junit5Result.tests).toEqual(["junit"]);
    expect(junit5Result.testEvidence[0]).toMatchObject({
      framework: "junit",
      support: "confirmed",
      versionHint: "5",
    });

    expect(
      detectFrameworks({
        packageName: "declared-java",
        dependencies: ["org.junit.jupiter:junit-jupiter-api"],
        scripts: {},
      }).testEvidence[0]?.support,
    ).toBe("declared");
  });
  it("detects Go frameworks and testing evidence", () => {
    const ginResult = detectFrameworks({
      packageName: "go-service",
      dependencies: ["github.com/gin-gonic/gin"],
      scripts: {},
      sourcePaths: ["main.go"],
      imports: ["github.com/gin-gonic/gin"],
    });
    expect(ginResult.frameworks).toEqual(["gin"]);
    expect(ginResult.evidence[0]).toMatchObject({
      framework: "gin",
      support: "confirmed",
    });

    const goTestResult = detectFrameworks({
      packageName: "go-lib",
      dependencies: ["github.com/stretchr/testify"],
      scripts: {},
      sourcePaths: ["lib_test.go"],
      imports: ["github.com/stretchr/testify"],
    });
    expect(goTestResult.tests).toEqual(["testify"]);
    expect(goTestResult.testEvidence[0]).toMatchObject({
      framework: "testify",
      support: "confirmed",
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  detectPythonPackageLayout,
  parseGoManifest,
  parseJavaManifest,
  parsePythonManifest,
} from "../src/index.js";

describe("ecosystem manifests", () => {
  it("handles malformed files without execution", () =>
    expect(parseGoManifest("???").module).toBeNull());
  it("supports multiple manifest adapters", () =>
    expect([
      parsePythonManifest("a==1"),
      parseJavaManifest("<groupId>x</groupId>"),
    ]).toHaveLength(2));
  it("reports dynamic Gradle limitations", () =>
    expect(parseJavaManifest('implementation "${lib}"').dynamic).toBe(true));
  it("parses Maven parent, modules, dependencies, and plugins", () => {
    const result = parseJavaManifest(
      "<project><parent><artifactId>parent</artifactId></parent><modules><module>api</module><module>web</module></modules><dependencies><dependency><groupId>org.demo</groupId><artifactId>core</artifactId></dependency></dependencies><build><plugins><plugin><artifactId>spring-boot-maven-plugin</artifactId></plugin></plugins></build></project>",
      "pom.xml",
    );
    expect(result).toMatchObject({
      parent: "parent",
      modules: ["api", "web"],
      dependencies: ["org.demo:core"],
      plugins: ["spring-boot-maven-plugin"],
    });
  });
  it("parses Gradle module relationships and reports Kotlin DSL conservatively", () => {
    const settings = parseJavaManifest(
      'include(":api")\ninclude(":libs:core")',
      "settings.gradle.kts",
    );
    expect(settings.modules).toEqual(["api", "libs/core"]);
    expect(settings.diagnostics).toContain("kotlin-dsl-conservative");
  });
  it("parses requirements includes", () =>
    expect(parsePythonManifest("-r base.txt").includes).toEqual(["base.txt"]));
  it("parses PEP 621 and Poetry packaging metadata deterministically", () => {
    const pep = parsePythonManifest(
      '[project]\nname="demo"\ndependencies=["FastAPI>=1", "uvicorn"]\n[project.scripts]\ndemo="demo:main"\n[tool.pytest.ini_options]\naddopts="-q"',
      "pyproject.toml",
    );
    const poetry = parsePythonManifest(
      '[tool.poetry]\nname="poem"\n[tool.poetry.dependencies]\npython="^3.11"\nflask="^3"',
      "pyproject.toml",
    );
    expect(pep).toMatchObject({
      name: "demo",
      dependencies: ["fastapi", "uvicorn"],
      entryPoints: ["demo:demo:main"],
      testConfiguration: ["pytest"],
    });
    expect(poetry.dependencies).toEqual(["flask"]);
    expect(
      parsePythonManifest(
        "-r base.txt\n--requirement dev.in\nrequests>=2",
        "requirements-dev.txt",
      ).includes,
    ).toEqual(["base.txt", "dev.in"]);
  });
  it("reports malformed TOML and detects canonical package layouts", () => {
    expect(
      parsePythonManifest('[project]\ndependencies=["x"', "pyproject.toml"),
    ).toMatchObject({
      completeness: "partial",
      diagnostics: ["malformed-toml"],
    });
    expect(
      detectPythonPackageLayout([
        "src/demo/__init__.py",
        "other/py.typed",
        "README.md",
      ]),
    ).toEqual(["other", "src/demo"]);
  });
  it("parses Go replace directives, go.work files, require blocks, and reports build tags", () => {
    const mod = parseGoManifest(
      "// +build linux\nmodule github.com/example/demo\ngo 1.21\nrequire (\n\tgithub.com/gin-gonic/gin v1.9.1\n\tgithub.com/stretchr/testify v1.8.4\n)\nreplace a => ../a",
      "go.mod",
    );
    expect(mod).toMatchObject({
      format: "go.mod",
      module: "github.com/example/demo",
      goVersion: "1.21",
      dependencies: ["github.com/gin-gonic/gin", "github.com/stretchr/testify"],
      replacements: [{ from: "a", to: "../a" }],
      completeness: "partial",
      diagnostics: ["unsupported-build-tag"],
    });

    const work = parseGoManifest(
      "go 1.21\nuse (\n\t./app\n\t./lib\n)\nreplace (\n\tx => ../x\n)",
      "go.work",
    );
    expect(work).toMatchObject({
      format: "go.work",
      goVersion: "1.21",
      useDirectories: ["./app", "./lib"],
      replacements: [{ from: "x", to: "../x" }],
      completeness: "complete",
    });

    expect(
      parseGoManifest("require github.com/a/b v1", "go.mod"),
    ).toMatchObject({
      completeness: "partial",
      diagnostics: ["malformed-manifest"],
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  detectJavascriptWorkspaceManagers,
  parsePackageJson,
  workspaceDiagnostics,
} from "../src/index.js";

describe("JS manifests", () => {
  it("parses pnpm workspace package facts", () =>
    expect(
      parsePackageJson(
        "package.json",
        '{"name":"x","workspaces":["packages/*"]}',
      ).workspacePatterns,
    ).toEqual(["packages/*"]));
  it("parses npm workspaces", () =>
    expect(
      parsePackageJson("package.json", '{"workspaces":["apps/*"]}')
        .workspacePatterns,
    ).toEqual(["apps/*"]));
  it("diagnoses invalid manifests", () =>
    expect(parsePackageJson("bad", "{").diagnostics).toEqual([
      "invalid package.json",
    ]));
  it("diagnoses duplicate package names", () =>
    expect(
      workspaceDiagnostics([
        parsePackageJson("a", '{"name":"x"}'),
        parsePackageJson("b", '{"name":"x"}'),
      ]),
    ).toEqual(["duplicate package name: x"]));
  it("preserves workspace globs", () =>
    expect(
      parsePackageJson("x", '{"workspaces":["packages/**"]}')
        .workspacePatterns[0],
    ).toBe("packages/**"));
  it("can report lockfile mismatch as caller evidence", () =>
    expect(
      parsePackageJson("x", '{"dependencies":{"a":"1"}}').dependencies,
    ).toEqual(["a"]));
  it("preserves package boundaries, exports, entry points, dependency classes, and scripts as metadata", () => {
    const fact = parsePackageJson(
      "packages/a/package.json",
      JSON.stringify({
        name: "a",
        main: "dist/index.js",
        exports: { ".": "./dist/index.js", "./feature": "./feature.js" },
        scripts: { postinstall: "do-not-run" },
        dependencies: { react: "1" },
        devDependencies: { vitest: "1" },
        peerDependencies: { typescript: "1" },
        optionalDependencies: { fsevents: "1" },
      }),
    );
    expect(fact).toMatchObject({
      packageRoot: "packages/a",
      entryPoints: ["dist/index.js"],
      exports: [".", "./feature"],
      completeness: "complete",
    });
    expect(fact.dependencyClasses).toEqual({
      production: ["react"],
      development: ["vitest"],
      peer: ["typescript"],
      optional: ["fsevents"],
    });
    expect(fact.scripts.postinstall).toBe("do-not-run");
  });
  it("detects npm, pnpm, and Yarn markers with explicit conflict evidence", () => {
    expect(
      detectJavascriptWorkspaceManagers([
        "package-lock.json",
        "pnpm-workspace.yaml",
        "yarn.lock",
      ]),
    ).toEqual({
      managers: ["npm", "pnpm", "yarn"],
      conflicts: ["conflicting workspace managers: npm, pnpm, yarn"],
    });
  });
  it("parses Yarn object-form workspaces deterministically", () => {
    expect(
      parsePackageJson(
        "package.json",
        '{"workspaces":{"packages":["packages/*","apps/*"]}}',
      ).workspacePatterns,
    ).toEqual(["apps/*", "packages/*"]);
  });
});

import { describe, expect, it } from "vitest";
import { detectLanguages, detectSourceRoots } from "../src/index.js";

describe("language detection", () => {
