    expect(detectLanguages([{ path: "README" }])).toEqual([]));
  it("finds likely source and test roots", () =>
    expect(detectSourceRoots(["src/a.ts", "tests/a.ts"])).toEqual([
      "src",
      "tests",
    ]));
});

