import { measureRetrieval, type RetrievalMetrics } from "./index.js";

export const RETRIEVAL_BASELINE_SCHEMA_VERSION = 1 as const;
export type ContributionSource = "lexical" | "git" | "dependency" | "profile";

export interface AblationCandidate {
  readonly path: string;
  readonly language: string;
  readonly tokens: number;
  readonly contributions: Readonly<Record<ContributionSource, number>>;
}

export function evaluateAblation(input: {
  readonly id: string;
  readonly repositoryFixture: "small" | "medium" | "monorepo";
  readonly task: string;
  readonly expected: Readonly<Record<string, number>>;
  readonly candidates: readonly AblationCandidate[];
  readonly budgetTokens: number;
  readonly disabled?: readonly ContributionSource[];
}): RetrievalMetrics {
  const disabled = new Set(input.disabled ?? []);
  let used = 0;
  const selected = [...input.candidates]
    .map((candidate) => ({
      candidate,
      score: Object.entries(candidate.contributions).reduce(
        (sum, [source, value]) =>
          sum + (disabled.has(source as ContributionSource) ? 0 : value),
        0,
      ),
    }))
    .filter(({ score }) => score > 0)
    .sort(
      (left, right) =>
        right.score - left.score ||
        left.candidate.path.localeCompare(right.candidate.path),
    )
    .filter(({ candidate }) => {
      if (used + candidate.tokens > input.budgetTokens) return false;
      used += candidate.tokens;
      return true;
    })
    .map(({ candidate }) => candidate.path);
  return measureRetrieval({
    id: input.id,
    repositoryFixture: input.repositoryFixture,
    task: input.task,
    expected: input.expected,
    selected,
    symbolHints: [],
    budgetTokens: input.budgetTokens,
  });
}

export interface RetrievalCase {
  readonly id: string;
  readonly repositoryFixture: string;
  readonly task: string;
  readonly expected: Readonly<Record<string, number>>;
  readonly selected: readonly string[];
  readonly symbolHints: readonly string[];
  readonly budgetTokens: number;
  readonly itemTokens?: Readonly<Record<string, number>>;
  readonly estimatorId?: string;
  readonly maxByteBudget?: number;
}

export interface RetrievalMetrics {
  readonly precision: number;
  readonly recall: number;
  readonly ndcg: number;
  readonly mrr: number;
  readonly bundleSize: number;
  readonly missingItems?: readonly string[];
  readonly extraItems?: readonly string[];
  readonly totalTokens?: number;
  readonly irrelevantTokens?: number;
  readonly irrelevantTokenRatio?: number;
  readonly totalBytes?: number;
  readonly estimatorId?: string;
  readonly exceedsByteBudget?: boolean;
}

export function measureRetrieval(input: RetrievalCase): RetrievalMetrics {
  const selectedDeduplicated = [...new Set(input.selected)];
  const relevant = Object.keys(input.expected);
  const hits = selectedDeduplicated.filter((path) => path in input.expected);
  const missingItems = relevant.filter(
    (path) => !selectedDeduplicated.includes(path),
  );
  const extraItems = selectedDeduplicated.filter(
    (path) => !(path in input.expected),
  );

  let totalTokens = 0;
  let irrelevantTokens = 0;
  if (input.itemTokens) {
    for (const path of selectedDeduplicated) {
      const tokens = input.itemTokens[path] ?? 0;
      totalTokens += tokens;
      if (!(path in input.expected)) {
        irrelevantTokens += tokens;
      }
    }
  }

  const estimatorId = input.estimatorId ?? "utf8-bytes-per-token:v1";
  const totalBytes = selectedDeduplicated.reduce(
    (acc, p) => acc + Buffer.byteLength(p, "utf8"),
    0,
  );
  const exceedsByteBudget =
    input.maxByteBudget !== undefined && totalBytes > input.maxByteBudget;

  const ideal = Object.values(input.expected).sort((a, b) => b - a);
  const gain = (grade: number, index: number) =>
    (2 ** grade - 1) / Math.log2(index + 2);
  const dcg = selectedDeduplicated.reduce(
    (sum, path, index) => sum + gain(input.expected[path] ?? 0, index),
    0,
  );
  const idcg = ideal.reduce((sum, grade, index) => sum + gain(grade, index), 0);
  const firstRelevant = selectedDeduplicated.findIndex(
    (path) => path in input.expected,
  );
  return {
    precision:
      selectedDeduplicated.length === 0
        ? 0
        : hits.length / selectedDeduplicated.length,
    recall: relevant.length === 0 ? 1 : hits.length / relevant.length,
    ndcg: idcg === 0 ? 1 : dcg / idcg,
    mrr: firstRelevant < 0 ? 0 : 1 / (firstRelevant + 1),
    bundleSize: selectedDeduplicated.length,
    missingItems,
    extraItems,
    totalTokens,
    irrelevantTokens,
    irrelevantTokenRatio:
      totalTokens === 0 ? 0 : irrelevantTokens / totalTokens,
    totalBytes,
    estimatorId,
    exceedsByteBudget,
  };
}

export function aggregateRetrievalMetrics(
  metricsList: readonly RetrievalMetrics[],
): RetrievalMetrics & { readonly caseCount: number } {
  if (metricsList.length === 0) {
    return {
      precision: 0,
      recall: 0,
      ndcg: 0,
      mrr: 0,
      bundleSize: 0,
      caseCount: 0,
    };
  }
  const sum = metricsList.reduce(
    (acc, m) => ({
      precision: acc.precision + m.precision,
      recall: acc.recall + m.recall,
      ndcg: acc.ndcg + m.ndcg,
      mrr: acc.mrr + m.mrr,
      bundleSize: acc.bundleSize + m.bundleSize,
    }),
    { precision: 0, recall: 0, ndcg: 0, mrr: 0, bundleSize: 0 },
  );
  const count = metricsList.length;
  return {
    precision: sum.precision / count,
    recall: sum.recall / count,
    ndcg: sum.ndcg / count,
    mrr: sum.mrr / count,
    bundleSize: sum.bundleSize / count,
    caseCount: count,
  };
}

export function compareBaseline(
  current: RetrievalMetrics,
  baseline: RetrievalMetrics,
  tolerance = 0.001,
): { readonly regressed: boolean; readonly deltas: RetrievalMetrics } {
  const deltas = {
    precision: current.precision - baseline.precision,
    recall: current.recall - baseline.recall,
    ndcg: current.ndcg - baseline.ndcg,
    mrr: current.mrr - baseline.mrr,
    bundleSize: current.bundleSize - baseline.bundleSize,
  };
  const numericKeys: readonly (keyof typeof deltas)[] = [
    "precision",
    "recall",
    "ndcg",
    "mrr",
  ];
  return {
    regressed: numericKeys.some((key) => deltas[key] < -tolerance),
    deltas,
  };
}

export * from "./ablation.js";
export * from "./schema.js";

export const V1_RETRIEVAL_BENCHMARK_SCHEMA_VERSION = 1 as const;

export type BenchmarkTaskCategory =
  | "bug-fix"
  | "architecture-security"
  | "feature"
  | "test"
  | "dependency"
  | "endpoint"
  | "migration";

export type BenchmarkItemClassification =
  "required" | "useful" | "irrelevant" | "prohibited";

export interface BenchmarkItemExpectation {
  readonly path: string;
  readonly classification: BenchmarkItemClassification;
  readonly relevanceGrade: number;
}

export interface GraphExpectation {
  readonly maxDistance?: number;
  readonly requiredNodeIds?: readonly string[];
  readonly requiredEdgeKinds?: readonly string[];
}

export interface RetrievalBenchmarkCase {
  readonly schemaVersion: typeof V1_RETRIEVAL_BENCHMARK_SCHEMA_VERSION;
  readonly id: string;
  readonly name: string;
  readonly category: BenchmarkTaskCategory;
  readonly repositoryFixture: string;
  readonly task: string;
  readonly profile: string;
  readonly budgetTokens: number;
  readonly expectedItems: readonly BenchmarkItemExpectation[];
  readonly graphExpectations?: GraphExpectation;
  readonly environmentMetadata?: Readonly<Record<string, string>>;
}

export function validateBenchmarkCase(
  item: unknown,
): item is RetrievalBenchmarkCase {
  if (typeof item !== "object" || item === null) return false;
  const candidate = item as Partial<RetrievalBenchmarkCase>;
  return (
    candidate.schemaVersion === V1_RETRIEVAL_BENCHMARK_SCHEMA_VERSION &&
    typeof candidate.id === "string" &&
    candidate.id.length > 0 &&
    typeof candidate.name === "string" &&
    typeof candidate.task === "string" &&
    typeof candidate.repositoryFixture === "string" &&
    typeof candidate.profile === "string" &&
    typeof candidate.budgetTokens === "number" &&
    candidate.budgetTokens > 0 &&
    Array.isArray(candidate.expectedItems) &&
    candidate.expectedItems.every(
      (expected) =>
        typeof expected?.path === "string" &&
        ["required", "useful", "irrelevant", "prohibited"].includes(
          expected.classification,
        ) &&
        typeof expected.relevanceGrade === "number",
    )
  );
}

import { describe, expect, it } from "vitest";
import {
  compareBaseline,
  measureRetrieval,
  type RetrievalCase,
} from "../src/index.js";

const base: RetrievalCase = {
  id: "auth",
  repositoryFixture: "fixtures/selection/lexical",
  task: "fix authentication failure",
  expected: { "authentication.ts": 3, "test.ts": 1 },
  selected: ["authentication.ts", "other.ts"],
  symbolHints: ["reportAuthenticationFailure"],
  budgetTokens: 16_000,
};

describe("retrieval benchmark", () => {
  it("measures expected sets and graded relevance", () => {
    expect(measureRetrieval(base)).toMatchObject({
      precision: 0.5,
      recall: 0.5,
      mrr: 1,
    });
    expect(measureRetrieval(base).ndcg).toBeGreaterThan(0.8);
  });
  it("defines empty relevance without division by zero", () => {
    expect(
      measureRetrieval({ ...base, expected: {}, selected: [] }),
    ).toMatchObject({
      precision: 0,
      recall: 1,
      ndcg: 1,
      mrr: 0,
      bundleSize: 0,
    });
  });
  it("supports budget variants as explicit case data", () => {
    expect(
      measureRetrieval({ ...base, budgetTokens: 1, selected: [] }).bundleSize,
    ).toBe(0);
  });
  it("is stable for repeated inputs", () => {
    expect(measureRetrieval(base)).toEqual(measureRetrieval(base));
  });
  it("detects baseline regressions", () => {
    const baseline = measureRetrieval(base);
    expect(
      compareBaseline({ ...baseline, recall: 0 }, baseline).regressed,
    ).toBe(true);
    expect(compareBaseline(baseline, baseline).regressed).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import {
  aggregateRetrievalMetrics,
  evaluateAblation,
  measureRetrieval,
  validateBenchmarkCase,
} from "../src/index.js";

const candidates = [
  {
    path: "src/auth.ts",
    language: "typescript",
    tokens: 40,
    contributions: { lexical: 3, git: 1, dependency: 1, profile: 1 },
  },
  {
    path: "lib/auth.py",
    language: "python",
    tokens: 35,
    contributions: { lexical: 2, git: 0, dependency: 1, profile: 0 },
  },
  {
    path: "docs/readme.md",
    language: "markdown",
    tokens: 20,
    contributions: { lexical: 0, git: 1, dependency: 0, profile: 0 },
  },
] as const;

const base = {
  id: "v1",
  repositoryFixture: "monorepo" as const,
  task: "fix authentication",
  expected: { "src/auth.ts": 3, "lib/auth.py": 2 },
  candidates,
  budgetTokens: 100,
};

describe("v1 baseline", () => {
  it.each(["lexical", "git", "dependency", "profile"] as const)(
    "measures the %s ablation deterministically",
    (source) => {
      expect(evaluateAblation({ ...base, disabled: [source] })).toEqual(
        evaluateAblation({ ...base, disabled: [source] }),
      );
    },
  );
  it.each(["small", "medium", "monorepo"] as const)(
    "covers the %s fixture class across languages",
    (repositoryFixture) => {
      expect(evaluateAblation({ ...base, repositoryFixture }).recall).toBe(1);
      expect(new Set(candidates.map(({ language }) => language)).size).toBe(3);
    },
  );
  it("enforces token-budget variants", () => {
    expect(evaluateAblation({ ...base, budgetTokens: 39 }).bundleSize).toBe(1);
    expect(evaluateAblation(base).bundleSize).toBe(3);
  });
  it("is equivalent for indexed and direct candidate inputs", () => {
    const direct = evaluateAblation(base);
    const indexed = evaluateAblation({
      ...base,
      candidates: JSON.parse(JSON.stringify(candidates)),
    });
    expect(indexed).toEqual(direct);
  });
  it("validates V1 retrieval benchmark case schema", () => {
    const benchmarkCase = {
      schemaVersion: 1,
      id: "bm-001",
      name: "Authentication Fix",
      category: "bug-fix" as const,
      repositoryFixture: "small",
      task: "Fix auth login flow",
      profile: "default",
      budgetTokens: 500,
      expectedItems: [
        {
          path: "src/auth.ts",
          classification: "required" as const,
          relevanceGrade: 3,
        },
        {
          path: "src/utils.ts",
          classification: "useful" as const,
          relevanceGrade: 1,
        },
      ],
      graphExpectations: { maxDistance: 2 },
    };
    expect(validateBenchmarkCase(benchmarkCase)).toBe(true);
    expect(validateBenchmarkCase({ schemaVersion: 2 })).toBe(false);
  });
  it("validates architecture and security benchmark case schema and expectations", () => {
    const archSecurityCase = {
      schemaVersion: 1,
      id: "architecture-security-audit",
      name: "Architecture Boundary and Security Audit Case",
      category: "architecture-security" as const,
      repositoryFixture: "small",
      task: "review system boundaries and security filter policies",
      profile: "security",
      budgetTokens: 16000,
      expectedItems: [
        {
          path: "src/security/filter.ts",
          classification: "required" as const,
          relevanceGrade: 3,
        },
        {
          path: "secrets/raw-credentials.pem",
          classification: "prohibited" as const,
          relevanceGrade: 0,
        },
      ],
      graphExpectations: { maxDistance: 2 },
    };
    expect(validateBenchmarkCase(archSecurityCase)).toBe(true);
    const prohibitedItems = archSecurityCase.expectedItems.filter(
      (item) => item.classification === "prohibited",
    );
    expect(prohibitedItems).toHaveLength(1);
    expect(prohibitedItems[0].relevanceGrade).toBe(0);
  });
  it("validates polyglot feature and migration benchmark case schema and expectations", () => {
    const polyglotCase = {
      schemaVersion: 1,
      id: "polyglot-feature-migration",
      name: "Polyglot Monorepo Feature and Migration Task",
      category: "feature" as const,
      repositoryFixture: "monorepo",
      task: "add polyglot feature and run schema migration across packages",
      profile: "default",
      budgetTokens: 16000,
      expectedItems: [
        {
          path: "packages/core/src/index.ts",
          classification: "required" as const,
          relevanceGrade: 3,
        },
        {
          path: "packages/schemas/src/index/contracts.ts",
          classification: "useful" as const,
          relevanceGrade: 2,
        },
        {
          path: "tests/migrations/migration.test.ts",
          classification: "useful" as const,
          relevanceGrade: 1,
        },
      ],
      graphExpectations: { maxDistance: 2 },
    };
    expect(validateBenchmarkCase(polyglotCase)).toBe(true);
    expect(polyglotCase.expectedItems).toHaveLength(3);
  });
  it("calculates metrics for zero-result, duplicates, and missing/extra items accurately", () => {
    const zeroResult = measureRetrieval({
      id: "zero",
      repositoryFixture: "small",
      task: "task",
      expected: { "a.ts": 1 },
      selected: [],
      symbolHints: [],
      budgetTokens: 1000,
    });
    expect(zeroResult.precision).toBe(0);
    expect(zeroResult.recall).toBe(0);
    expect(zeroResult.mrr).toBe(0);
    expect(zeroResult.missingItems).toEqual(["a.ts"]);

    const withDuplicates = measureRetrieval({
      id: "dups",
      repositoryFixture: "small",
      task: "task",
      expected: { "a.ts": 1 },
      selected: ["a.ts", "a.ts", "b.ts"],
      symbolHints: [],
      budgetTokens: 1000,
    });
    expect(withDuplicates.bundleSize).toBe(2);
    expect(withDuplicates.extraItems).toEqual(["b.ts"]);

    const agg = aggregateRetrievalMetrics([zeroResult, withDuplicates]);
    expect(agg.caseCount).toBe(2);
    expect(agg.precision).toBe(0.25);
  });
  it("measures irrelevant-token ratio, token estimator, byte budget use, and multibyte text", () => {
    const res = measureRetrieval({
      id: "budget-test",
      repositoryFixture: "small",
      task: "task",
      expected: { "relevant.ts": 3 },
      selected: ["relevant.ts", "irrelevant.ts", "multibyte_🚀.ts"],
      symbolHints: [],
      budgetTokens: 1000,
      itemTokens: {
        "relevant.ts": 100,
        "irrelevant.ts": 50,
        "multibyte_🚀.ts": 50,
      },
      estimatorId: "custom-estimator:v1",
      maxByteBudget: 20,
    });
    expect(res.totalTokens).toBe(200);
    expect(res.irrelevantTokens).toBe(100);
    expect(res.irrelevantTokenRatio).toBe(0.5);
    expect(res.estimatorId).toBe("custom-estimator:v1");
    expect(res.exceedsByteBudget).toBe(true);
  });
  it("verifies release performance baseline results structure and evaluation report", () => {
    const payload = {
      schemaVersion: 1,
      environment: { nodeVersion: "v24.12.0", platform: "win32", arch: "x64" },
      results: [],
    };
    expect(payload.schemaVersion).toBe(1);
    expect(payload.environment.nodeVersion).toBeTruthy();
  });
});

