export interface BudgetItem {
  readonly id: string;
  readonly content: string;
  readonly mandatory?: boolean;
}
export interface BudgetLimits {
  readonly bytes: number;
  readonly tokens: number;
  readonly files: number;
  readonly perItemBytes: number;
  readonly manifestBytes: number;
}
export function enforceBudget(
  items: readonly BudgetItem[],
  limits: BudgetLimits,
) {
  let bytes = limits.manifestBytes;
  let tokens = Math.ceil(bytes / 4);
  const selected: { id: string; content: string; truncated: boolean }[] = [];
  const excluded: { id: string; reason: string }[] = [];
  for (const item of items) {
    if (selected.length >= limits.files) {
      excluded.push({ id: item.id, reason: "file limit" });
      continue;
    }
    const available = Math.max(
      0,
      Math.min(
        limits.perItemBytes,
        limits.bytes - bytes,
        (limits.tokens - tokens) * 4,
      ),
    );
    if (available === 0) {
      excluded.push({
        id: item.id,
        reason: item.mandatory
          ? "mandatory item exceeds budget"
          : "budget exhausted",
      });
      continue;
    }
    const buffer = Buffer.from(item.content);
    const content = buffer
      .subarray(0, available)
      .toString("utf8")
      .replace(/\uFFFD$/, "");
    const used = Buffer.byteLength(content);
    selected.push({ id: item.id, content, truncated: used < buffer.length });
    bytes += used;
    tokens += Math.ceil(used / 4);
  }
  return {
    selected,
    excluded,
    bytes,
    tokens,
    overflow: bytes > limits.bytes || tokens > limits.tokens,
  };
}

export {
  enforceBudget,
  type BudgetItem,
  type BudgetLimits,
} from "./enforce.js";

import { budgetEstimateSchema, type BudgetEstimate } from "@fuzit/schemas";

export * from "./enforcement/index.js";

export interface TokenEstimator {
  readonly id: string;
  readonly uncertainty: number;
  readonly estimate: (content: string) => number;
}

export const utf8BytesPerTokenEstimator: TokenEstimator = {
  id: "utf8-bytes-per-token:v1",
  uncertainty: 0.25,
  estimate: (content) => Math.ceil(Buffer.byteLength(content, "utf8") / 4),
};

export function estimateBudget(
  content: string,
  options: {
    readonly metadata?: unknown;
    readonly estimator?: TokenEstimator;
    readonly maximumTokens?: number;
  } = {},
): BudgetEstimate {
  const estimator = options.estimator ?? utf8BytesPerTokenEstimator;
  const metadataBytes =
    options.metadata === undefined
      ? 0
      : Buffer.byteLength(JSON.stringify(options.metadata), "utf8");
  const estimatedTokens = estimator.estimate(content);
  return budgetEstimateSchema.parse({
    schemaVersion: 1,
    bytes: Buffer.byteLength(content, "utf8") + metadataBytes,
    metadataBytes,
    estimatedTokens,
    estimator: estimator.id,
    uncertainty: estimator.uncertainty,
    exceedsBudget:
      options.maximumTokens !== undefined &&
      estimatedTokens > options.maximumTokens,
  });
}

import { describe, expect, it } from "vitest";
import { enforceBudget } from "../src/index.js";
const limits = {
  bytes: 20,
  tokens: 5,
  files: 2,
  perItemBytes: 10,
  manifestBytes: 0,
};
describe("hard budgets", () => {
  it("handles tiny budgets", () =>
    expect(
      enforceBudget([{ id: "a", content: "abc" }], {
        ...limits,
        bytes: 0,
        tokens: 0,
      }).selected,
    ).toEqual([]));
  it("uses exact boundaries", () =>
    expect(
      enforceBudget([{ id: "a", content: "1234" }], {
        ...limits,
        bytes: 4,
        tokens: 1,
      }).overflow,
    ).toBe(false));
  it("does not split Unicode invalidly", () =>
    expect(
      enforceBudget([{ id: "a", content: "éé" }], {
        ...limits,
        bytes: 3,
        tokens: 1,
      }).selected[0]?.content,
    ).not.toContain("�"));
  it("reports mandatory too large", () =>
    expect(
      enforceBudget([{ id: "a", content: "x", mandatory: true }], {
        ...limits,
        bytes: 0,
        tokens: 0,
      }).excluded[0]?.reason,
    ).toContain("mandatory"));
  it("marks truncation", () =>
    expect(
      enforceBudget([{ id: "a", content: "123456" }], {
        ...limits,
        perItemBytes: 3,
      }).selected[0]?.truncated,
    ).toBe(true));
  it("supports metadata-only fallback", () =>
    expect(
      enforceBudget([{ id: "a", content: "x" }], {
        ...limits,
        manifestBytes: 20,
      }).selected,
    ).toEqual([]));
  it("enforces file redundancy caps", () =>
    expect(
      enforceBudget(
        [
          { id: "a", content: "x" },
          { id: "b", content: "x" },
        ],
        { ...limits, files: 1 },
      ).excluded,
    ).toHaveLength(1));
});

import { describe, expect, it } from "vitest";

import { estimateBudget } from "../src/index.js";

describe("budget estimation", () => {
  it("accounts for ASCII bytes", () => {
    expect(estimateBudget("abcd")).toMatchObject({
      bytes: 4,
      estimatedTokens: 1,
    });
  });

  it("accounts for Unicode UTF-8 bytes", () => {
    expect(estimateBudget("🙂").bytes).toBe(4);
  });

  it("handles large content deterministically", () => {
    expect(estimateBudget("x".repeat(1_000_000)).estimatedTokens).toBe(250_000);
  });

  it("includes metadata overhead", () => {
    expect(estimateBudget("", { metadata: { path: "a" } })).toMatchObject({
      bytes: 12,
      metadataBytes: 12,
    });
  });

  it("supports a different named estimator", () => {
    expect(
      estimateBudget("abc", {
        estimator: {
          id: "characters:v1",
          uncertainty: 0.5,
          estimate: (content) => content.length,
        },
      }),
    ).toMatchObject({
      estimatedTokens: 3,
      estimator: "characters:v1",
      uncertainty: 0.5,
    });
  });

  it("reports a zero budget without division", () => {
    expect(estimateBudget("x", { maximumTokens: 0 }).exceedsBudget).toBe(true);
  });
});

