export {
  CONFIG_ENVIRONMENT_VARIABLES,
  DEFAULT_CONFIG,
  ConfigLoadError,
  loadEffectiveConfig,
} from "./load.js";
export {
  INIT_CONFIG_CONTENT,
  INIT_IGNORE_ENTRIES,
  InitConflictError,
  applyInitialization,
  planInitialization,
} from "./init.js";
export type {
  InitAction,
  InitChange,
  InitFileSystem,
  InitPlan,
  PlanInitInput,
} from "./init.js";
export type {
  ConfigKey,
  ConfigLoadInput,
  ConfigOverrides,
  ConfigProvenance,
  ConfigSource,
  ConfigValues,
  EffectiveConfig,
} from "./load.js";

import { appendFile, readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

import { DEFAULT_CONFIG, validateRepositoryConfig } from "./load.js";

export const INIT_CONFIG_CONTENT = `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`;
export const INIT_IGNORE_ENTRIES = Object.freeze([
  ".fuzit/",
  ".fuzit-index/",
  ".fuzit/local/",
]);

export type InitAction = "create" | "replace" | "append";

export interface InitChange {
  readonly path: "fuzit.config.json" | ".gitignore";
  readonly action: InitAction;
  readonly content?: string;
  readonly lines?: readonly string[];
}

export interface InitPlan {
  readonly schemaVersion: 1;
  readonly status: "changes-planned" | "no-change";
  readonly changes: readonly InitChange[];
}

export interface InitFileSystem {
  readonly readText: (path: string) => Promise<string | undefined>;
  readonly createText: (path: string, contents: string) => Promise<void>;
  readonly replaceText: (path: string, contents: string) => Promise<void>;
  readonly appendText: (path: string, contents: string) => Promise<void>;
}

export interface PlanInitInput {
  readonly repositoryRoot: string;
  readonly force?: boolean;
  readonly fileSystem?: InitFileSystem;
}

export class InitConflictError extends Error {
  readonly code = "INIT.CONFLICT";

  constructor() {
    super(
      "Existing fuzit.config.json is incompatible; rerun with --force to replace it.",
    );
    this.name = "InitConflictError";
  }
}

async function defaultReadText(path: string): Promise<string | undefined> {
  try {
    return await readFile(path, "utf8");
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === "ENOENT"
    ) {
      return undefined;
    }
    throw error;
  }
}

const defaultFileSystem: InitFileSystem = {
  readText: defaultReadText,
  createText: async (path, contents) => {
    await writeFile(path, contents, { encoding: "utf8", flag: "wx" });
  },
  replaceText: async (path, contents) => {
    await writeFile(path, contents, { encoding: "utf8", flag: "w" });
  },
  appendText: async (path, contents) => {
    await appendFile(path, contents, { encoding: "utf8" });
  },
};

function missingIgnoreEntries(contents: string | undefined): readonly string[] {
  const existing = new Set(
    (contents ?? "")
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean),
  );

  return INIT_IGNORE_ENTRIES.filter((entry) => !existing.has(entry));
}

export async function planInitialization(
  input: PlanInitInput,
): Promise<InitPlan> {
  const fileSystem = input.fileSystem ?? defaultFileSystem;
  const configPath = resolve(input.repositoryRoot, "fuzit.config.json");
  const ignorePath = resolve(input.repositoryRoot, ".gitignore");
  const [configContents, ignoreContents] = await Promise.all([
    fileSystem.readText(configPath),
    fileSystem.readText(ignorePath),
  ]);
  const changes: InitChange[] = [];

  if (configContents === undefined) {
    changes.push({
      path: "fuzit.config.json",
      action: "create",
      content: INIT_CONFIG_CONTENT,
    });
  } else {
    let compatible: boolean;
    try {
      compatible = validateRepositoryConfig(JSON.parse(configContents));
    } catch {
      compatible = false;
    }

    if (!compatible) {
      if (!input.force) {
        throw new InitConflictError();
      }
      changes.push({
        path: "fuzit.config.json",
        action: "replace",
        content: INIT_CONFIG_CONTENT,
      });
    }
  }

  const missingEntries = missingIgnoreEntries(ignoreContents);
  if (missingEntries.length > 0) {
    changes.push({
      path: ".gitignore",
      action: ignoreContents === undefined ? "create" : "append",
      lines: missingEntries,
    });
  }

  return {
    schemaVersion: 1,
    status: changes.length === 0 ? "no-change" : "changes-planned",
    changes,
  };
}

function appendedIgnoreText(
  existingContents: string | undefined,
  lines: readonly string[],
): string {
  const prefix =
    existingContents === undefined || existingContents.length === 0
      ? ""
      : existingContents.endsWith("\n")
        ? ""
        : "\n";
  return `${prefix}${lines.join("\n")}\n`;
}

export async function applyInitialization(
  input: PlanInitInput,
  plan: InitPlan,
): Promise<void> {
  const fileSystem = input.fileSystem ?? defaultFileSystem;

  for (const change of plan.changes) {
    const path = resolve(input.repositoryRoot, change.path);

    if (change.path === "fuzit.config.json" && change.content !== undefined) {
      if (change.action === "create") {
        await fileSystem.createText(path, change.content);
      } else {
        await fileSystem.replaceText(path, change.content);
      }
      continue;
    }

    if (change.path === ".gitignore" && change.lines !== undefined) {
      if (change.action === "create") {
        await fileSystem.createText(
          path,
          appendedIgnoreText(undefined, change.lines),
        );
      } else {
        const existingContents = await fileSystem.readText(path);
        await fileSystem.appendText(
          path,
          appendedIgnoreText(existingContents, change.lines),
        );
      }
    }
  }
}

import { readFile } from "node:fs/promises";
import { extname, isAbsolute, relative, resolve } from "node:path";

import { z } from "zod";

const configValuesSchema = z
  .object({
    outputFormat: z.enum(["markdown", "json", "xml", "text"]),
    maxFiles: z.number().int().positive(),
    diagnosticLevel: z.enum(["error", "warning", "info", "debug"]),
    include: z.array(z.string().min(1)),
    exclude: z.array(z.string().min(1)),
  })
  .strict();

const repositoryConfigSchema = configValuesSchema.partial().strict();

export function validateRepositoryConfig(input: unknown): boolean {
  return repositoryConfigSchema.safeParse(input).success;
}

export type ConfigValues = z.infer<typeof configValuesSchema>;
export type ConfigKey = keyof ConfigValues;
export type ConfigSource = "default" | "repository" | "environment" | "cli";
export type ConfigOverrides = Partial<Record<ConfigKey, unknown>>;
export type ConfigProvenance = Record<ConfigKey, ConfigSource>;

export interface ConfigLoadInput {
  readonly repositoryRoot: string;
  readonly configPath?: string;
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly cli?: ConfigOverrides;
}

export interface EffectiveConfig {
  readonly schemaVersion: 1;
  readonly values: ConfigValues;
  readonly provenance: ConfigProvenance;
}

export const DEFAULT_CONFIG: Readonly<ConfigValues> = Object.freeze({
  outputFormat: "markdown",
  maxFiles: 120,
  diagnosticLevel: "info",
  include: [],
  exclude: [],
});

export const CONFIG_ENVIRONMENT_VARIABLES = Object.freeze({
  outputFormat: "FUZIT_OUTPUT_FORMAT",
  maxFiles: "FUZIT_MAX_FILES",
  diagnosticLevel: "FUZIT_DIAGNOSTIC_LEVEL",
} satisfies Record<"outputFormat" | "maxFiles" | "diagnosticLevel", string>);

export class ConfigLoadError extends Error {
  readonly code: "CONFIG.INVALID" | "CONFIG.OUTSIDE_REPOSITORY";
  readonly issues: readonly string[];

  constructor(
    code: ConfigLoadError["code"],
    message: string,
    issues: readonly string[] = [],
  ) {
    super(message);
    this.name = "ConfigLoadError";
    this.code = code;
    this.issues = issues;
  }
}

function assertInsideRepository(
  repositoryRoot: string,
  configPath: string,
): void {
  const pathFromRoot = relative(repositoryRoot, configPath);

  if (
    pathFromRoot === ".." ||
    pathFromRoot.startsWith(`..\\`) ||
    pathFromRoot.startsWith("../") ||
    isAbsolute(pathFromRoot)
  ) {
    throw new ConfigLoadError(
      "CONFIG.OUTSIDE_REPOSITORY",
      "Configuration must be located inside the repository.",
    );
  }
}

function formatIssues(error: z.ZodError): readonly string[] {
  return error.issues.map((issue) => {
    const path =
      issue.path.length === 0 ? "configuration" : issue.path.join(".");
    return `${path}: ${issue.message}`;
  });
}

async function readRepositoryConfig(
  configPath: string,
): Promise<ConfigOverrides> {
  let contents: string;

  try {
    contents = await readFile(configPath, "utf8");
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === "ENOENT"
    ) {
      return {};
    }

    throw new ConfigLoadError(
      "CONFIG.INVALID",
      "Unable to read repository configuration.",
    );
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(contents.replace(/^\uFEFF/, ""));
  } catch {
    throw new ConfigLoadError(
      "CONFIG.INVALID",
      "Repository configuration must contain valid JSON.",
    );
  }

  const result = repositoryConfigSchema.safeParse(parsed);
  if (!result.success) {
    throw new ConfigLoadError(
      "CONFIG.INVALID",
      "Repository configuration is invalid.",
      formatIssues(result.error),
    );
  }

  return result.data;
}

function readEnvironment(
  environment: Readonly<Record<string, string | undefined>>,
): ConfigOverrides {
  const outputFormat = environment[CONFIG_ENVIRONMENT_VARIABLES.outputFormat];
  const maxFiles = environment[CONFIG_ENVIRONMENT_VARIABLES.maxFiles];
  const diagnosticLevel =
    environment[CONFIG_ENVIRONMENT_VARIABLES.diagnosticLevel];

  return {
    ...(outputFormat === undefined ? {} : { outputFormat }),
    ...(maxFiles === undefined ? {} : { maxFiles: Number(maxFiles) }),
    ...(diagnosticLevel === undefined ? {} : { diagnosticLevel }),
  };
}

function applyLayer(
  values: ConfigOverrides,
  provenance: ConfigProvenance,
  layer: ConfigOverrides,
  source: ConfigSource,
): void {
  for (const key of Object.keys(layer) as ConfigKey[]) {
    const value = layer[key];
    if (value !== undefined) {
      values[key] = value;
      provenance[key] = source;
    }
  }
}

export async function loadEffectiveConfig(
  input: ConfigLoadInput,
): Promise<EffectiveConfig> {
  const repositoryRoot = resolve(input.repositoryRoot);
  const configPath = resolve(
    input.configPath ?? resolve(repositoryRoot, "fuzit.config.json"),
  );

  assertInsideRepository(repositoryRoot, configPath);
  if (extname(configPath).toLowerCase() !== ".json") {
    throw new ConfigLoadError(
      "CONFIG.INVALID",
      "Repository configuration must use the .json file extension.",
    );
  }

  const values: ConfigOverrides = { ...DEFAULT_CONFIG };
  const provenance: ConfigProvenance = {
    outputFormat: "default",
    maxFiles: "default",
    diagnosticLevel: "default",
    include: "default",
    exclude: "default",
  };

  applyLayer(
    values,
    provenance,
    await readRepositoryConfig(configPath),
    "repository",
  );
  applyLayer(
    values,
    provenance,
    readEnvironment(input.environment ?? {}),
    "environment",
  );
  applyLayer(values, provenance, input.cli ?? {}, "cli");

  const result = configValuesSchema.safeParse(values);
  if (!result.success) {
    throw new ConfigLoadError(
      "CONFIG.INVALID",
      "Effective configuration is invalid.",
      formatIssues(result.error),
    );
  }

  return {
    schemaVersion: 1,
    values: result.data,
    provenance,
  };
}

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import {
  INIT_CONFIG_CONTENT,
  InitConflictError,
  applyInitialization,
  planInitialization,
  type InitFileSystem,
} from "../src/index.js";

const temporaryDirectories: string[] = [];

async function createRepository(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-init-"));
  temporaryDirectories.push(directory);
  return directory;
}

afterEach(async () => {
  await Promise.all(
    temporaryDirectories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

describe("safe initialization", () => {
  it("initializes an empty repository with only approved files", async () => {
    const repositoryRoot = await createRepository();
    const input = { repositoryRoot };
    const plan = await planInitialization(input);

    expect(plan.changes.map(({ action, path }) => ({ action, path }))).toEqual([
      { action: "create", path: "fuzit.config.json" },
      { action: "create", path: ".gitignore" },
    ]);

    await applyInitialization(input, plan);

    await expect(
      readFile(join(repositoryRoot, "fuzit.config.json"), "utf8"),
    ).resolves.toBe(INIT_CONFIG_CONTENT);
    await expect(
      readFile(join(repositoryRoot, ".gitignore"), "utf8"),
    ).resolves.toBe(".fuzit/\n.fuzit-index/\n.fuzit/local/\n");
  });

  it("preserves an existing compatible configuration", async () => {
    const repositoryRoot = await createRepository();
    const existing = '{\n  "maxFiles": 20\n}\n';
    await writeFile(join(repositoryRoot, "fuzit.config.json"), existing);

    const input = { repositoryRoot };
    const plan = await planInitialization(input);
    await applyInitialization(input, plan);

    expect(plan.changes).not.toEqual(
      expect.arrayContaining([
        expect.objectContaining({ path: "fuzit.config.json" }),
      ]),
    );
    await expect(
      readFile(join(repositoryRoot, "fuzit.config.json"), "utf8"),
    ).resolves.toBe(existing);
  });

  it("reports a conflicting configuration", async () => {
    const repositoryRoot = await createRepository();
    await writeFile(
      join(repositoryRoot, "fuzit.config.json"),
      '{"unknown":true}\n',
    );

    await expect(planInitialization({ repositoryRoot })).rejects.toBeInstanceOf(
      InitConflictError,
    );
  });

  it("reports a read-only repository without creating files", async () => {
    const repositoryRoot = await createRepository();
    const readOnlyFileSystem: InitFileSystem = {
      readText: async () => undefined,
      createText: async () => {
        const error = new Error("read only");
        Object.assign(error, { code: "EACCES" });
        throw error;
      },
      replaceText: async () => {
        throw new Error("unexpected replace");
      },
      appendText: async () => {
        throw new Error("unexpected append");
      },
    };
    const input = { repositoryRoot, fileSystem: readOnlyFileSystem };
    const plan = await planInitialization(input);

    await expect(applyInitialization(input, plan)).rejects.toMatchObject({
      code: "EACCES",
    });
  });

  it("does not overwrite without the explicit force flag", async () => {
    const repositoryRoot = await createRepository();
    const configPath = join(repositoryRoot, "fuzit.config.json");
    const conflicting = "not json\n";
    await writeFile(configPath, conflicting);

    await expect(planInitialization({ repositoryRoot })).rejects.toBeInstanceOf(
      InitConflictError,
    );
    await expect(readFile(configPath, "utf8")).resolves.toBe(conflicting);

    const input = { repositoryRoot, force: true };
    const plan = await planInitialization(input);
    await applyInitialization(input, plan);
    await expect(readFile(configPath, "utf8")).resolves.toBe(
      INIT_CONFIG_CONTENT,
    );
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { ConfigLoadError, loadEffectiveConfig } from "../src/index.js";

const temporaryDirectories: string[] = [];

async function createRepository(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-config-"));
  temporaryDirectories.push(directory);
  return directory;
}

afterEach(async () => {
  await Promise.all(
    temporaryDirectories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

describe("loadEffectiveConfig", () => {
  it("applies defaults, repository, environment, and CLI precedence", async () => {
    const repositoryRoot = await createRepository();
    await writeFile(
      join(repositoryRoot, "fuzit.config.json"),
      JSON.stringify({
        outputFormat: "text",
        maxFiles: 80,
        diagnosticLevel: "warning",
        include: [],
        exclude: [],
      }),
    );

    const result = await loadEffectiveConfig({
      repositoryRoot,
      environment: {
        FUZIT_OUTPUT_FORMAT: "xml",
        FUZIT_MAX_FILES: "40",
      },
      cli: {
        outputFormat: "json",
      },
    });

    expect(result).toEqual({
      schemaVersion: 1,
      values: {
        outputFormat: "json",
        maxFiles: 40,
        diagnosticLevel: "warning",
        include: [],
        exclude: [],
      },
      provenance: {
        outputFormat: "cli",
        maxFiles: "environment",
        diagnosticLevel: "repository",
        include: "repository",
        exclude: "repository",
      },
    });
  });

  it("rejects unknown repository keys", async () => {
    const repositoryRoot = await createRepository();
    await writeFile(
      join(repositoryRoot, "fuzit.config.json"),
      JSON.stringify({ unexpected: true }),
    );

    await expect(loadEffectiveConfig({ repositoryRoot })).rejects.toMatchObject(
      {
        code: "CONFIG.INVALID",
        issues: [expect.stringContaining("unexpected")],
      },
    );
  });

  it("returns diagnostics for invalid types without exposing values", async () => {
    const repositoryRoot = await createRepository();
    const secretLikeValue = "do-not-echo-this-value";
    await writeFile(
      join(repositoryRoot, "fuzit.config.json"),
      JSON.stringify({ maxFiles: secretLikeValue }),
    );

    let caught: unknown;
    try {
      await loadEffectiveConfig({ repositoryRoot });
    } catch (error) {
      caught = error;
    }

    expect(caught).toBeInstanceOf(ConfigLoadError);
    expect(JSON.stringify(caught)).not.toContain(secretLikeValue);
  });

  it("rejects a configuration path outside the repository", async () => {
    const repositoryRoot = await createRepository();
    const outsidePath = join(repositoryRoot, "..", "fuzit.config.json");

    await expect(
      loadEffectiveConfig({ repositoryRoot, configPath: outsidePath }),
    ).rejects.toMatchObject({
      code: "CONFIG.OUTSIDE_REPOSITORY",
    });
  });

  it("does not execute JavaScript configuration", async () => {
    const repositoryRoot = await createRepository();
    const markerPath = join(repositoryRoot, "executed");
    await writeFile(
      join(repositoryRoot, "fuzit.config.js"),
      `require("node:fs").writeFileSync(${JSON.stringify(markerPath)}, "executed");`,
    );

    const result = await loadEffectiveConfig({ repositoryRoot });

    expect(result.provenance).toEqual({
      outputFormat: "default",
      maxFiles: "default",
      diagnosticLevel: "default",
      include: "default",
      exclude: "default",
    });
    await expect(
      import("node:fs/promises").then(({ stat }) => stat(markerPath)),
    ).rejects.toMatchObject({
      code: "ENOENT",
    });
  });
});

