/**
 * Direct issue-context workflow runner.
 *
 * @module
 */

import {
  githubRequest,
  normalizeIssue,
  normalizeIssueComment,
  resolveCredential,
  type FixtureTransport,
} from "@fuzit/provider-github";
import type { GitHubIssueRef, IssueCommentRecord } from "@fuzit/schemas";

export interface IssueRunOptions {
  readonly issueRef: GitHubIssueRef;
  readonly profileName?: string;
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly fixtureTransport?: FixtureTransport;
}

export interface IssueRunResult {
  readonly ok: boolean;
  readonly issueNumber: number;
  readonly targetRepo: string;
  readonly summary: string;
  readonly title: string;
  readonly body: string;
  readonly state: string;
  readonly author: string;
  readonly comments: readonly IssueCommentRecord[];
}

export async function runIssueContext(
  options: IssueRunOptions,
): Promise<IssueRunResult> {
  const { issueRef } = options;
  const credential = resolveCredential({
    host: issueRef.host.webHost,
    env: { ...(options.environment ?? process.env) },
  });
  const apiRoot = `https://${issueRef.host.apiHost}`;
  const requestOptions = {
    credential,
    allowedHosts: [issueRef.host.webHost, issueRef.host.apiHost],
    ...(options.fixtureTransport
      ? { fixtureTransport: options.fixtureTransport }
      : {}),
  };
  const baseUrl = `${apiRoot}/repos/${encodeURIComponent(issueRef.owner)}/${encodeURIComponent(issueRef.repo)}/issues/${issueRef.number}`;
  const [issueResponse, commentsResponse] = await Promise.all([
    githubRequest(baseUrl, requestOptions),
    githubRequest(`${baseUrl}/comments?per_page=100`, requestOptions),
  ]);
  if (!issueResponse.ok)
    throw new Error(
      `GitHub issue acquisition failed: ${issueResponse.diagnostic}`,
    );
  if (issueResponse.status !== 200)
    throw new Error(
      `GitHub issue acquisition failed (HTTP ${issueResponse.status}). Check the issue number and repository access.`,
    );
  if (!commentsResponse.ok)
    throw new Error(
      `GitHub issue comments acquisition failed: ${commentsResponse.diagnostic}`,
    );
  if (commentsResponse.status !== 200)
    throw new Error(
      `GitHub issue comments acquisition failed (HTTP ${commentsResponse.status}).`,
    );
  let rawIssue: unknown;
  let rawComments: unknown;
  try {
    rawIssue = JSON.parse(issueResponse.body);
    rawComments = JSON.parse(commentsResponse.body);
  } catch {
    throw new Error(
      "GitHub returned malformed JSON while acquiring the issue.",
    );
  }
  if (!Array.isArray(rawComments))
    throw new Error("GitHub returned an invalid issue comment list.");
  const issue = normalizeIssue(issueRef, rawIssue);
  const comments = rawComments.map((comment) =>
    normalizeIssueComment(issueRef, comment),
  );
  const summary = [
    `# Issue #${issueRef.number}: ${issue.title}`,
    "",
    `Repository: ${issue.repositoryFullName}`,
    `State: ${issue.state}`,
    `Author: ${issue.authorLogin}`,
    `Labels: ${issue.labels.join(", ") || "none"}`,
    "",
    "## Description",
    issue.body || "No description was provided.",
    "",
    `## Comments (${comments.length})`,
    ...(comments.length === 0
      ? ["No comments."]
      : comments.map(
          (comment) => `### ${comment.authorLogin}\n\n${comment.body}`,
        )),
  ].join("\n");
  return {
    ok: true,
    issueNumber: issueRef.number,
    targetRepo: `${issueRef.owner}/${issueRef.repo}`,
    summary,
    title: issue.title,
    body: issue.body,
    state: issue.state,
    author: issue.authorLogin,
    comments,
  };
}

/**
 * Local GitHub enrichment manager.
 *
 * @module
 */

export interface LocalEnrichmentOptions {
  readonly enrichGithub?: boolean;
}

export interface LocalEnrichmentResult {
  readonly isEnriched: boolean;
  readonly isPartial: boolean;
}

export async function applyLocalGithubEnrichment(
  options: LocalEnrichmentOptions,
): Promise<LocalEnrichmentResult> {
  if (!options.enrichGithub) {
    return { isEnriched: false, isPartial: false };
  }
  return { isEnriched: true, isPartial: false };
}

/**
 * Remote source pipeline bridge.
 *
 * Connects disposable remote worktrees to Fuzit's canonical scanner and selection engine.
 *
 * @module
 */

import type { GitHubRepositoryRef } from "@fuzit/schemas";

export interface RemotePipelineRunOptions {
  readonly ref: GitHubRepositoryRef;
  readonly task?: string;
  readonly profileName?: string;
}

export interface RemotePipelineRunResult {
  readonly success: boolean;
  readonly remoteProvenance: {
    readonly host: string;
    readonly owner: string;
    readonly repo: string;
    readonly revision?: string;
  };
  readonly scannedPath: string;
}

export async function prepareRemotePipeline(
  options: RemotePipelineRunOptions,
  worktreePath: string,
): Promise<RemotePipelineRunResult> {
  return {
    success: true,
    remoteProvenance: {
      host: options.ref.host.webHost,
      owner: options.ref.owner,
      repo: options.ref.repo,
      ...(options.ref.revision ? { revision: options.ref.revision } : {}),
    },
    scannedPath: worktreePath,
  };
}

/**
 * Top-level URL and source dispatch router.
 *
 * @module
 */

import { parseGitHubUrl } from "@fuzit/provider-github";

export type DispatchRouteTarget = "context" | "review" | "issue" | "local";

export interface DispatchRouteResult {
  readonly target: DispatchRouteTarget;
  readonly parsedSource?: unknown;
}

export function routeSourceInput(input: string): DispatchRouteResult {
  if (input.startsWith("http://") || input.startsWith("https://")) {
    const res = parseGitHubUrl(input);
    if (res.ok) {
      if (res.ref.kind === "github-pull-request")
        return { target: "review", parsedSource: res.ref };
      if (res.ref.kind === "github-issue")
        return { target: "issue", parsedSource: res.ref };
      return { target: "context", parsedSource: res.ref };
    }
  }
  return { target: "local" };
}

/**
 * Flagship read-only PR review command service.
 *
 * @module
 */

import {
  githubRequest,
  normalizePrFile,
  normalizePullRequestData,
  resolveBestGitHubCredential,
  type FixtureTransport,
} from "@fuzit/provider-github";
import type {
  GitHubPullRequestRef,
  PullRequestFileRecord,
} from "@fuzit/schemas";

export interface ReviewRunOptions {
  readonly prRef: GitHubPullRequestRef;
  readonly task?: string;
  readonly profileName?: string;
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly fixtureTransport?: FixtureTransport;
}

export interface ReviewRunResult {
  readonly ok: boolean;
  readonly prNumber: number;
  readonly targetRepo: string;
  readonly summary: string;
  readonly title: string;
  readonly state: string;
  readonly author: string;
  readonly baseRef: string;
  readonly headRef: string;
  readonly files: readonly PullRequestFileRecord[];
  readonly patches: readonly {
    path: string;
    content: string;
    truncated: boolean;
  }[];
  readonly findings: readonly string[];
}

export async function runPrReview(
  options: ReviewRunOptions,
): Promise<ReviewRunResult> {
  const { prRef } = options;
  const credential = await resolveBestGitHubCredential({
    host: prRef.host.webHost,
    env: { ...(options.environment ?? process.env) },
  });
  const apiRoot = `https://${prRef.host.apiHost}`;
  const requestOptions = {
    credential,
    allowedHosts: [prRef.host.webHost, prRef.host.apiHost],
    ...(options.fixtureTransport
      ? { fixtureTransport: options.fixtureTransport }
      : {}),
  };
  const metadataResponse = await githubRequest(
    `${apiRoot}/repos/${encodeURIComponent(prRef.owner)}/${encodeURIComponent(prRef.repo)}/pulls/${prRef.number}`,
    requestOptions,
  );
  if (!metadataResponse.ok) {
    if (metadataResponse.kind === "rate-limited") {
      throw new Error(
        `GitHub rate limited the request. Retry after ${metadataResponse.retryAfterSeconds ?? "a short delay"} seconds.`,
      );
    }
    if (metadataResponse.kind === "network-error") {
      throw new Error(`GitHub network failure: ${metadataResponse.diagnostic}`);
    }
    throw new Error(
      credential.isAuthenticated
        ? "GitHub resource not accessible with the current credentials (HTTP 404)."
        : "GitHub resource not found or not accessible anonymously (HTTP 404).",
    );
  }
  if (metadataResponse.status === 401)
    throw new Error("GitHub credentials are invalid or expired.");
  if (metadataResponse.status === 403)
    throw new Error(
      credential.isAuthenticated
        ? "GitHub access is forbidden for the authenticated account."
        : "GitHub authentication required or access forbidden.",
    );
  if (metadataResponse.status === 404)
    throw new Error(
      credential.isAuthenticated
        ? "GitHub resource not accessible with the current credentials (HTTP 404)."
        : "GitHub resource not found or not accessible anonymously (HTTP 404).",
    );
  if (metadataResponse.status !== 200)
    throw new Error(`GitHub PR acquisition failed (HTTP ${metadataResponse.status}).`);
  const filesResponse = await githubRequest(
    `${apiRoot}/repos/${encodeURIComponent(prRef.owner)}/${encodeURIComponent(prRef.repo)}/pulls/${prRef.number}/files?per_page=100`,
    requestOptions,
  );
  if (!filesResponse.ok) {
    throw new Error(
      filesResponse.kind === "rate-limited"
        ? `GitHub rate limited the file request. Retry after ${filesResponse.retryAfterSeconds ?? "a short delay"} seconds.`
        : `GitHub PR files acquisition failed: ${filesResponse.diagnostic}`,
    );
  }
  if (filesResponse.status === 401)
    throw new Error("GitHub credentials are invalid or expired.");
  if (filesResponse.status === 403)
    throw new Error("GitHub access is forbidden for the authenticated account.");
  if (filesResponse.status === 404)
    throw new Error("GitHub resource not accessible with the current credentials.");
  if (filesResponse.status !== 200)
    throw new Error(`GitHub PR files acquisition failed (HTTP ${filesResponse.status}).`);

  let rawMetadata: unknown;
  let rawFiles: unknown;
  try {
    rawMetadata = JSON.parse(metadataResponse.body);
    rawFiles = JSON.parse(filesResponse.body);
  } catch {
    throw new Error(
      "GitHub returned malformed JSON while acquiring the pull request.",
    );
  }
  if (!Array.isArray(rawFiles))
    throw new Error("GitHub returned an invalid pull-request file list.");
  const metadata = normalizePullRequestData(prRef, rawMetadata);
  const normalized = rawFiles.map((file) => normalizePrFile(prRef, file));
  const files = normalized.map(({ fileRecord }) => fileRecord);
  const patches = normalized.flatMap(({ patchRecord }) =>
    patchRecord
      ? [
          {
            path: patchRecord.path,
            content: patchRecord.patchContent,
            truncated: patchRecord.isTruncated,
          },
        ]
      : [],
  );
  const findings: string[] = [];
  for (const patch of patches) {
    if (/^\+.*(?:password|secret|api[_-]?key)\s*[:=]/im.test(patch.content))
      findings.push(
        `${patch.path}: added text resembles a hard-coded credential; verify and remove it.`,
      );
    if (/^\+.*(?:eval\(|child_process|shell\s*:\s*true)/im.test(patch.content))
      findings.push(
        `${patch.path}: added code uses a high-risk execution primitive; review input handling.`,
      );
  }
  const summary = [
    `# Pull request #${prRef.number}: ${metadata.title}`,
    "",
    `Repository: ${metadata.repositoryFullName}`,
    `State: ${metadata.state}${metadata.isDraft ? " (draft)" : ""}`,
    `Author: ${metadata.authorLogin}`,
    `Change: ${metadata.baseRef} <- ${metadata.headRef}`,
    `Changed files: ${files.length}`,
    "",
    "## Files",
    ...(files.length === 0
      ? ["No changed files were reported by GitHub."]
      : files.map(
          (file) =>
            `- ${file.status}: ${file.path} (+${file.additions}/-${file.deletions})`,
        )),
    "",
    "## Findings",
    ...(findings.length === 0
      ? [
          "No high-confidence findings were detected by the bounded automated patch inspection.",
        ]
      : findings.map((finding) => `- ${finding}`)),
    ...(patches.some(({ truncated }) => truncated)
      ? ["", "Note: one or more patches were truncated at the safety limit."]
      : []),
  ].join("\n");
  return {
    ok: true,
    prNumber: prRef.number,
    targetRepo: `${prRef.owner}/${prRef.repo}`,
    summary,
    title: metadata.title,
    state: metadata.state,
    author: metadata.authorLogin,
    baseRef: metadata.baseRef,
    headRef: metadata.headRef,
    files,
    patches,
    findings,
  };
}

/**
 * Code content transformations and skeletonization/compression.
 *
 * @module
 */

export interface CodeTransformOptions {
  readonly compress?: boolean;
  readonly removeComments?: boolean;
  readonly removeEmptyLines?: boolean;
  readonly lineNumbers?: boolean;
}

/**
 * Remove single-line and multi-line comments from code content.
 */
export function removeComments(content: string, filePath = ""): string {
  const ext = filePath.includes(".") ? filePath.split(".").pop()?.toLowerCase() ?? "" : "";

  if (["py", "sh", "bash", "yaml", "yml", "dockerfile", "r", "rb"].includes(ext)) {
    return content
      .split("\n")
      .map((line) => {
        const idx = line.indexOf("#");
        if (idx === -1) return line;
        const quoteBefore = line.slice(0, idx).split(/["']/);
        if (quoteBefore.length % 2 === 0) return line;
        return line.slice(0, idx).trimEnd();
      })
      .join("\n");
  }

  // C-style comment languages (js, ts, java, c, cpp, go, rust, cs, etc.)
  let cleaned = content.replace(/\/\*[\s\S]*?\*\//g, "");
  cleaned = cleaned
    .split("\n")
    .map((line) => {
      const idx = line.indexOf("//");
      if (idx === -1) return line;
      const quoteBefore = line.slice(0, idx).split(/["']/);
      if (quoteBefore.length % 2 === 0) return line;
      return line.slice(0, idx).trimEnd();
    })
    .join("\n");

  return cleaned;
}

/**
 * Strip consecutive empty lines from code content.
 */
export function removeEmptyLines(content: string): string {
  return content
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .join("\n");
}

/**
 * Prepend 1-indexed line numbers to each line of code content.
 */
export function addLineNumbers(content: string): string {
  const lines = content.split("\n");
  const padWidth = String(lines.length).length;
  return lines
    .map((line, idx) => `${String(idx + 1).padStart(padWidth, " ")} | ${line}`)
    .join("\n");
}

/**
 * Compress/skeletonize source code by keeping declarations, signatures, and structures
 * while stripping function/method bodies.
 */
export function compressCodeContent(content: string, filePath = ""): string {
  const ext = filePath.includes(".") ? filePath.split(".").pop()?.toLowerCase() ?? "" : "";

  if (["py", "rb"].includes(ext)) {
    return content
      .split("\n")
      .map((line) => {
        if (/^\s*(def |class |module |import|from|require|attr_)/.test(line)) return line;
        if (/^\s*#/.test(line)) return line;
        if (line.trim().length === 0) return line;
        if (!line.startsWith(" ")) return line;
        return null;
      })
      .filter((line): line is string => line !== null)
      .join("\n");
  }

  // C-style languages (TS, JS, Go, Rust, Java, C, C++, C#)
  return content
    .replace(/(\b(?:function|class|interface|type|async|export|public|private|protected|static|fn|def|struct|enum)\s+[a-zA-Z0-9_$]+\s*(?:\([^)]*\))?[^{]*)\{[\s\S]*?\}/g, "$1{ /* implementation hidden */ }")
    .replace(/(const|let|var)\s+([a-zA-Z0-9_$]+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>\s*\{[\s\S]*?\}/g, "$1 $2 = (...) => { /* implementation hidden */ }");
}

/**
 * Apply selected transformation controls sequentially to code content.
 */
export function transformCodeContent(
  content: string,
  filePath: string,
  options: CodeTransformOptions,
): string {
  let transformed = content;

  if (options.compress) {
    transformed = compressCodeContent(transformed, filePath);
  }
  if (options.removeComments) {
    transformed = removeComments(transformed, filePath);
  }
  if (options.removeEmptyLines) {
    transformed = removeEmptyLines(transformed);
  }
  if (options.lineNumbers) {
    transformed = addLineNumbers(transformed);
  }

  return transformed;
}

/**
 * Output splitting and size parsing utilities.
 *
 * @module
 */

import { extname } from "node:path";

export interface OutputChunk {
  readonly filename: string;
  readonly path: string;
  readonly content: string;
  readonly bytes: number;
}

/**
 * Parse a human-readable size string like "500kb", "1mb", "100000" into bytes.
 */
export function parseByteSize(sizeSpec: string): number {
  const normalized = sizeSpec.trim().toLowerCase();
  const match = normalized.match(/^(\d+(?:\.\d+)?)\s*([a-z]*)$/);
  if (!match) {
    throw new Error(`Invalid size specification: '${sizeSpec}'. Use formats like 500kb, 1mb, or 100000.`);
  }

  const value = Number.parseFloat(match[1]!);
  const unit = match[2]!;

  if (unit === "" || unit === "b" || unit === "bytes") return Math.round(value);
  if (unit === "k" || unit === "kb") return Math.round(value * 1024);
  if (unit === "m" || unit === "mb") return Math.round(value * 1024 * 1024);
  if (unit === "g" || unit === "gb") return Math.round(value * 1024 * 1024 * 1024);

  throw new Error(`Unknown size unit '${unit}' in '${sizeSpec}'. Supported units: B, KB, MB, GB.`);
}

/**
 * Split rendered markdown bundle content into multiple chunks of at most `maxBytes`.
 */
export function splitPackedOutput(
  content: string,
  outputPath: string,
  maxBytes: number,
): OutputChunk[] {
  if (maxBytes <= 0 || Buffer.byteLength(content, "utf8") <= maxBytes) {
    return [
      {
        filename: outputPath,
        path: outputPath,
        content,
        bytes: Buffer.byteLength(content, "utf8"),
      },
    ];
  }

  const ext = extname(outputPath);
  const basePath = outputPath.slice(0, outputPath.length - ext.length);
  const lines = content.split("\n");
  const chunks: OutputChunk[] = [];

  let currentLines: string[] = [];
  let currentBytes = 0;
  let partIndex = 1;

  for (const line of lines) {
    const lineBytes = Buffer.byteLength(`${line}\n`, "utf8");
    if (currentLines.length > 0 && currentBytes + lineBytes > maxBytes) {
      const partPath = `${basePath}_part${partIndex}${ext}`;
      const chunkText = `${currentLines.join("\n")}\n`;
      chunks.push({
        filename: `${basePath}_part${partIndex}${ext}`,
        path: partPath,
        content: chunkText,
        bytes: Buffer.byteLength(chunkText, "utf8"),
      });
      partIndex += 1;
      currentLines = [];
      currentBytes = 0;
    }
    currentLines.push(line);
    currentBytes += lineBytes;
  }

  if (currentLines.length > 0) {
    const partPath = `${basePath}_part${partIndex}${ext}`;
    const chunkText = `${currentLines.join("\n")}\n`;
    chunks.push({
      filename: `${basePath}_part${partIndex}${ext}`,
      path: partPath,
      content: chunkText,
      bytes: Buffer.byteLength(chunkText, "utf8"),
    });
  }

  return chunks;
}

