export type {
  PathNormalizationErrorCode,
  RepositoryRelativePath,
} from "./repository-relative-path.js";

import { posix, win32 } from "node:path";

declare const repositoryRelativePathBrand: unique symbol;

export type RepositoryRelativePath = string & {
  readonly [repositoryRelativePathBrand]: true;
};

export type PathNormalizationErrorCode =
  "PATH.ABSOLUTE" | "PATH.ESCAPE" | "PATH.ROOT_MISMATCH";

export class PathNormalizationError extends Error {
  readonly code: PathNormalizationErrorCode;

  constructor(code: PathNormalizationErrorCode, message: string) {
    super(message);
    this.name = "PathNormalizationError";
    this.code = code;
  }
}

function isWindowsAbsolute(path: string): boolean {
  return (
    /^[A-Za-z]:[\\/]/.test(path) || /^[\\/]{2}[^\\/]+[\\/][^\\/]+/.test(path)
  );
}

export function normalizeRepositoryRelativePath(
  input: string,
): RepositoryRelativePath {
  if (isWindowsAbsolute(input) || input.startsWith("/")) {
    throw new PathNormalizationError(
      "PATH.ABSOLUTE",
      "Repository-relative paths cannot be absolute.",
    );
  }

  const segments: string[] = [];
  for (const segment of input.replaceAll("\\", "/").split("/")) {
    if (segment === "" || segment === ".") {
      continue;
    }
    if (segment === "..") {
      if (segments.length === 0) {
        throw new PathNormalizationError(
          "PATH.ESCAPE",
          "Path escapes the repository root.",
        );
      }
      segments.pop();
      continue;
    }
    segments.push(segment);
  }

  return (
    segments.length === 0 ? "." : segments.join("/")
  ) as RepositoryRelativePath;
}

function usesWindowsSemantics(path: string): boolean {
  return isWindowsAbsolute(path) || path.includes("\\");
}

export function toRepositoryRelativePath(
  repositoryRoot: string,
  targetPath: string,
): RepositoryRelativePath {
  const windowsSemantics =
    usesWindowsSemantics(repositoryRoot) || usesWindowsSemantics(targetPath);
  const pathApi = windowsSemantics ? win32 : posix;
  const relativePath = pathApi.relative(
    pathApi.resolve(repositoryRoot),
    pathApi.resolve(targetPath),
  );

  if (pathApi.isAbsolute(relativePath)) {
    throw new PathNormalizationError(
      "PATH.ROOT_MISMATCH",
      "Path does not share the repository root.",
    );
  }

  try {
    return normalizeRepositoryRelativePath(relativePath);
  } catch (error) {
    if (
      error instanceof PathNormalizationError &&
      error.code === "PATH.ESCAPE"
    ) {
      throw new PathNormalizationError(
        "PATH.ESCAPE",
        "Path is outside the repository root.",
      );
    }
    throw error;
  }
}

export {
  assertSecurityFilteredItem,
  registerSecurityFilteredItem,
  securityFilter,
  type SecurityFilteredItem,
  type SecurityFilterInput,
  type SecurityFilterResult,
} from "./security-filter.js";

import type { FileContextItem, SecurityFinding } from "@fuzit/schemas";
import {
  detectAndRedactCredentials,
  evaluateSensitivePath,
} from "@fuzit/security";

const filteredItems = new WeakSet<object>();
declare const securityFilteredBrand: unique symbol;

export interface SecurityFilteredItem extends FileContextItem {
  readonly findings: readonly SecurityFinding[];
  readonly [securityFilteredBrand]: true;
}

export type SecurityFilterResult =
  | {
      readonly status: "success";
      readonly item: SecurityFilteredItem;
    }
  | {
      readonly status: "omitted" | "partial";
      readonly path: string;
      readonly reason: string;
    };

export interface SecurityFilterInput {
  readonly path: string;
  readonly createItem: (
    content: string,
    findings: readonly SecurityFinding[],
  ) => FileContextItem;
  readonly readContent: () => Promise<string>;
  readonly detect?: typeof detectAndRedactCredentials;
}

export async function securityFilter(
  input: SecurityFilterInput,
): Promise<SecurityFilterResult> {
  if (evaluateSensitivePath(input.path).excluded) {
    return {
      status: "omitted",
      path: input.path,
      reason: "excluded-sensitive-path",
    };
  }

  let content: string;
  try {
    content = await input.readContent();
  } catch {
    return {
      status: "partial",
      path: input.path,
      reason: "content-read-failed",
    };
  }

  try {
    const filtered = (input.detect ?? detectAndRedactCredentials)(
      content,
      input.path,
    );
    const item = {
      ...input.createItem(filtered.content, filtered.findings),
      findings: filtered.findings,
    } as SecurityFilteredItem;
    filteredItems.add(item);
    return { status: "success", item };
  } catch {
    return {
      status: "partial",
      path: input.path,
      reason: "detector-failed-content-omitted",
    };
  }
}

export function assertSecurityFilteredItem(
  value: unknown,
): asserts value is SecurityFilteredItem {
  if (
    typeof value !== "object" ||
    value === null ||
    !filteredItems.has(value)
  ) {
    throw new TypeError("Renderer input must pass the security pipeline.");
  }
}

export function registerSecurityFilteredItem<T extends object>(item: T): T {
  filteredItems.add(item);
  return item;
}

import { mkdir, rename, unlink, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";

export class ResourceLimitError extends Error {
  constructor(
    readonly code: "ABORTED" | "TIMEOUT" | "OUTPUT_LIMIT" | "WRITE_FAILED",
    message: string,
  ) {
    super(message);
    this.name = "ResourceLimitError";
  }
}

export function operationSignal(
  signal: AbortSignal | undefined,
  timeoutMs: number,
): { readonly signal: AbortSignal; readonly dispose: () => void } {
  const controller = new AbortController();
  const abort = () =>
    controller.abort(new ResourceLimitError("ABORTED", "Operation cancelled."));
  signal?.addEventListener("abort", abort, { once: true });
  const timer = setTimeout(
    () =>
      controller.abort(
        new ResourceLimitError("TIMEOUT", "Operation timed out."),
      ),
    timeoutMs,
  );
  timer.unref();
  return {
    signal: controller.signal,
    dispose: () => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
    },
  };
}

export async function mapConcurrent<T, R>(
  values: readonly T[],
  concurrency: number,
  worker: (value: T, signal: AbortSignal) => Promise<R>,
  signal: AbortSignal,
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency < 1)
    throw new RangeError("concurrency must be positive");
  const results = new Array<R>(values.length);
  let cursor = 0;
  await Promise.all(
    Array.from({ length: Math.min(concurrency, values.length) }, async () => {
      while (cursor < values.length) {
        signal.throwIfAborted();
        const index = cursor++;
        results[index] = await worker(values[index]!, signal);
      }
    }),
  );
  return results;
}

export function enforceOutputLimit(
  data: Uint8Array | string,
  maximumBytes: number,
): void {
  const bytes =
    typeof data === "string" ? Buffer.byteLength(data) : data.byteLength;
  if (bytes > maximumBytes)
    throw new ResourceLimitError(
      "OUTPUT_LIMIT",
      `Output exceeds ${maximumBytes} bytes.`,
    );
}

interface AtomicWriteOperations {
  readonly mkdir: (
    path: string,
    options: { readonly recursive: true },
  ) => Promise<unknown>;
  readonly writeFile: (
    path: string,
    data: Uint8Array | string,
  ) => Promise<unknown>;
  readonly rename: (source: string, destination: string) => Promise<unknown>;
  readonly unlink: (path: string) => Promise<unknown>;
}

export async function atomicWrite(
  destination: string,
  data: Uint8Array | string,
  maximumBytes: number,
  operations: AtomicWriteOperations = { mkdir, writeFile, rename, unlink },
): Promise<void> {
  enforceOutputLimit(data, maximumBytes);
  const temporary = `${destination}.${randomUUID()}.tmp`;
  try {
    await operations.mkdir(dirname(destination), { recursive: true });
    await operations.writeFile(temporary, data);
    await operations.rename(temporary, destination);
  } catch (error) {
    await operations.unlink(temporary).catch(() => undefined);
    throw new ResourceLimitError(
      "WRITE_FAILED",
      error instanceof Error ? error.message : String(error),
    );
  }
}

export async function withRollback<T>(
  operation: () => Promise<T>,
  rollback: () => Promise<void>,
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    await rollback();
    throw error;
  }
}

import type { Diagnostic } from "@fuzit/schemas";

export interface SuccessResult<Value> {
  readonly status: "success";
  readonly value: Value;
  readonly diagnostics: readonly Diagnostic[];
}

export interface PartialResult<Value> {
  readonly status: "partial";
  readonly value: Value;
  readonly diagnostics: readonly Diagnostic[];
}

export interface FailureResult {
  readonly status: "failure";
  readonly diagnostics: readonly Diagnostic[];
}

export type Result<Value> =
  SuccessResult<Value> | PartialResult<Value> | FailureResult;

export function successResult<Value>(
  value: Value,
  diagnostics: readonly Diagnostic[] = [],
): SuccessResult<Value> {
  return { status: "success", value, diagnostics: [...diagnostics] };
}

export function partialResult<Value>(
  value: Value,
  diagnostics: readonly Diagnostic[],
): PartialResult<Value> {
  return { status: "partial", value, diagnostics: [...diagnostics] };
}

export function failureResult(
  diagnostics: readonly Diagnostic[],
): FailureResult {
  return { status: "failure", diagnostics: [...diagnostics] };
}

import { describe, expect, it } from "vitest";

import {
  createContextBundle,
  serializeContextBundle,
  type ContextBundleInput,
} from "../src/index.js";

const digest = "a".repeat(64);

function input(
  overrides: Partial<ContextBundleInput> = {},
): ContextBundleInput {
  return {
    schemaVersion: 1,
    source: { kind: "repository", root: "." },
    revision: null,
    items: [],
    redactionSummary: { findings: 0, redactedItems: 0, omittedItems: 0 },
    warnings: [],
    failedSources: [],
    budget: { bytes: 0, tokens: 0, truncated: false },
    ...overrides,
  };
}

describe("ContextBundle", () => {
  it("creates an empty schema-versioned bundle", () => {
    expect(createContextBundle(input())).toMatchObject({
      schemaVersion: 1,
      items: [],
    });
  });

  it("records partial bundles and failed sources", () => {
    expect(
      createContextBundle(
        input({ warnings: ["partial"], failedSources: ["unreadable"] }),
      ),
    ).toMatchObject({ warnings: ["partial"], failedSources: ["unreadable"] });
  });

  it.each([
    ["redacted", true, "complete"],
    ["truncated", false, "truncated"],
  ] as const)("records a %s item", (_name, redacted, contentStatus) => {
    const bundle = createContextBundle(
      input({
        items: [
          {
            id: "file:test",
            path: "a.ts",
            sha256: digest,
            contentStatus,
            redacted,
          },
        ],
      }),
    );
    expect(bundle.items[0]).toMatchObject({ redacted, contentStatus });
  });

  it("serializes with stable ordering", () => {
    const items = ["b.ts", "a.ts"].map((path) => ({
      id: `file:${path}`,
      path,
      sha256: digest,
      contentStatus: "complete" as const,
      redacted: false,
    }));
    const first = createContextBundle(input({ items }));
    const second = createContextBundle(input({ items: [...items].reverse() }));
    expect(serializeContextBundle(first)).toBe(serializeContextBundle(second));
    expect(first.id).toBe(second.id);
  });
});

import { constants } from "node:fs";

import { describe, expect, it } from "vitest";

import {
  DOCTOR_REPORT_JSON_SCHEMA,
  runDoctor,
  type DoctorDependencies,
} from "../src/index.js";

const passingDependencies: DoctorDependencies = {
  nodeVersion: "24.0.0",
  pnpmUserAgent: "pnpm/11.9.0 npm/? node/v24.0.0",
  checkGit: () => "2.50.0",
  checkPnpm: () => "11.9.0",
  platform: "linux",
  checkAccess: async () => {},
  checkPath: async (path) => path.endsWith(".git"),
  checkConfiguration: async () => {},
};

describe("environment doctor", () => {
  it("reports Git missing", async () => {
    const report = await runDoctor("repository", {
      ...passingDependencies,
      checkGit: () => undefined,
    });

    expect(report.status).toBe("attention");
    expect(report.checks.find(({ id }) => id === "git")).toMatchObject({
      status: "fail",
      message: "Git is unavailable.",
    });
  });

  it("reports when not in a repository", async () => {
    const report = await runDoctor("directory", {
      ...passingDependencies,
      checkPath: async () => false,
    });

    expect(report.checks.find(({ id }) => id === "repository")).toMatchObject({
      status: "fail",
      metadata: { detected: false },
    });
  });

  it("reports a read-only directory", async () => {
    const report = await runDoctor("repository", {
      ...passingDependencies,
      checkAccess: async (_path, mode) => {
        if (mode === constants.W_OK) {
          const error = new Error("read only");
          Object.assign(error, { code: "EACCES" });
          throw error;
        }
      },
    });

    expect(report.checks.find(({ id }) => id === "filesystem")).toMatchObject({
      status: "fail",
      metadata: { readable: true, writable: false },
    });
  });

  it("publishes a stable JSON schema and matching report shape", async () => {
    const report = await runDoctor("repository", passingDependencies);

    expect(DOCTOR_REPORT_JSON_SCHEMA).toMatchObject({
      type: "object",
      additionalProperties: false,
      required: ["schemaVersion", "status", "checks"],
    });
    expect(report).toMatchObject({
      schemaVersion: 1,
      status: "ready",
      checks: expect.arrayContaining([
        expect.objectContaining({ id: "node" }),
        expect.objectContaining({ id: "pnpm" }),
        expect.objectContaining({ id: "git" }),
        expect.objectContaining({ id: "filesystem" }),
        expect.objectContaining({ id: "repository" }),
        expect.objectContaining({ id: "configuration" }),
      ]),
    });
    expect(report.checks).toHaveLength(12);
  });

  it("reports installed pnpm without relying on user-agent metadata", async () => {
    const report = await runDoctor("repository", {
      ...passingDependencies,
      pnpmUserAgent: "npm/11 node/v24",
      checkPnpm: () => "11.9.0",
    });
    expect(report.checks.find(({ id }) => id === "pnpm")).toMatchObject({
      status: "pass",
      metadata: { version: "11.9.0" },
    });
  });

  it("returns actionable warnings for missing tools and optional surfaces", async () => {
    const report = await runDoctor("repository", {
      ...passingDependencies,
      pnpmUserAgent: "npm/11 node/v24",
      checkPnpm: () => undefined,
      checkPath: async (path) => path.endsWith(".git"),
    });
    expect(report.checks.find(({ id }) => id === "pnpm")?.message).toContain(
      "unavailable",
    );
    expect(report.checks.find(({ id }) => id === "mcp")?.status).toBe(
      "warning",
    );
    expect(report.checks.find(({ id }) => id === "extension")?.status).toBe(
      "warning",
    );
  });
});

import { describe, expect, it } from "vitest";

import type { FileRecord } from "@fuzit/schemas";

import { createFileContextItem } from "../src/index.js";

const digest = "a".repeat(64);

function record(path: string, overrides: Partial<FileRecord> = {}): FileRecord {
  return {
    schemaVersion: 1,
    path,
    kind: "text",
    extension: ".ts",
    language: { name: "TypeScript", confidence: 1 },
    sizeBytes: 4,
    symlink: false,
    generated: false,
    vendored: false,
    readable: true,
    ...overrides,
  };
}

describe("createFileContextItem", () => {
  it("produces a stable ID across repeated scans", () => {
    const first = createFileContextItem(record("src/a.ts"), {
      status: "complete",
      content: "test",
      sha256: digest,
    });
    const second = createFileContextItem(record("src/a.ts"), {
      status: "complete",
      content: "test",
      sha256: digest,
    });

    expect(second.id).toBe(first.id);
  });

  it("produces a new file ID after a rename", () => {
    const before = createFileContextItem(record("src/a.ts"), {
      status: "complete",
      content: "test",
      sha256: digest,
    });
    const after = createFileContextItem(record("src/b.ts"), {
      status: "complete",
      content: "test",
      sha256: digest,
    });

    expect(after.id).not.toBe(before.id);
  });

  it("records omitted content", () => {
    const item = createFileContextItem(record("src/a.ts"), {
      status: "omitted",
      content: null,
      sha256: digest,
    });

    expect(item).toMatchObject({
      content: null,
      contentStatus: "omitted",
      transformations: ["canonical-path", "content-omitted"],
    });
  });

  it("records truncated content", () => {
    const item = createFileContextItem(record("src/a.ts"), {
      status: "truncated",
      content: "test",
      sha256: digest,
    });

    expect(item.transformations).toContain("bounded-truncation");
  });

  it.each([
    [{ generated: true }, "generated"],
    [{ vendored: true }, "vendored"],
  ] as const)("records %s lifecycle", (overrides, lifecycle) => {
    const item = createFileContextItem(record("src/a.ts", overrides), {
      status: "complete",
      content: "test",
      sha256: digest,
    });

    expect(item.lifecycle).toBe(lifecycle);
  });
});

