import { detectAndRedactCredentials } from "@fuzit/security";

import { runGit } from "../index.js";

export interface GitDiffResult {
  readonly available: boolean;
  readonly paths: readonly string[];
  readonly patch: string;
  readonly truncated: boolean;
  readonly binary: boolean;
  readonly findings: number;
  readonly diagnostic: string | null;
}

export function normalizeGitDiff(
  patch: string,
  paths: readonly string[],
  options: { readonly maximumBytes: number; readonly maximumFiles: number },
): GitDiffResult {
  const selectedPaths = [...paths]
    .map((path) => path.replaceAll("\\", "/"))
    .sort()
    .slice(0, options.maximumFiles);
  const bytes = Buffer.from(patch, "utf8");
  const bounded = bytes.subarray(0, options.maximumBytes).toString("utf8");
  const filtered = detectAndRedactCredentials(bounded, "git-diff");
  return {
    available: true,
    paths: selectedPaths,
    patch: filtered.content,
    truncated:
      bytes.byteLength > options.maximumBytes ||
      paths.length > options.maximumFiles,
    binary: /Binary files .+ differ|GIT binary patch/.test(patch),
    findings: filtered.findings.length,
    diagnostic: null,
  };
}

export async function collectGitDiff(
  cwd: string,
  options: {
    readonly base?: string;
    readonly maximumBytes?: number;
    readonly maximumFiles?: number;
  } = {},
): Promise<GitDiffResult> {
  const range = options.base === undefined ? [] : [`${options.base}..HEAD`];
  const names = await runGit(
    ["diff", "--name-only", "--no-ext-diff", "--no-color", ...range],
    { cwd },
  );
  const patch = await runGit(
    ["diff", "--no-ext-diff", "--no-color", "--binary", ...range],
    { cwd, maximumBytes: (options.maximumBytes ?? 1024 * 1024) + 1 },
  );
  if (!names.ok || !patch.ok)
    return {
      available: false,
      paths: [],
      patch: "",
      truncated: false,
      binary: false,
      findings: 0,
      diagnostic: "Git diff is unavailable for the requested revision.",
    };
  return normalizeGitDiff(
    patch.stdout,
    names.stdout.split(/\r?\n/).filter(Boolean),
    {
      maximumBytes: options.maximumBytes ?? 1024 * 1024,
      maximumFiles: options.maximumFiles ?? 100,
    },
  );
}

export {
  collectGitDiff,
  normalizeGitDiff,
  type GitDiffResult,
} from "./collect-diff.js";

import { runGit } from "../index.js";

export interface FileHistoryEntry {
  readonly hash: string;
  readonly timestamp: string;
  readonly subject: string;
}

export interface BlameLine {
  readonly line: number;
  readonly hash: string | null;
  readonly author: string | null;
  readonly timestamp: number | null;
  readonly content: string;
}

export function parseLineRange(value: string): { start: number; end: number } {
  const match = value.match(/^(\d+):(\d+)$/);
  if (!match) throw new TypeError("Line range must be start:end.");
  const start = Number(match[1]);
  const end = Number(match[2]);
  if (start < 1 || end < start || end - start + 1 > 500)
    throw new RangeError("Line range must contain 1 to 500 lines.");
  return { start, end };
}

export async function collectFileHistory(
  cwd: string,
  path: string,
  limit = 20,
): Promise<FileHistoryEntry[]> {
  const result = await runGit(
    [
      "log",
      "--follow",
      `-${Math.max(1, Math.min(limit, 100))}`,
      "--format=%H%x1f%aI%x1f%s",
      "--",
      path,
    ],
    { cwd, maximumBytes: 512 * 1024 },
  );
  if (!result.ok) return [];
  return result.stdout
    .split(/\r?\n/)
    .filter(Boolean)
    .map((line) => {
      const [hash, timestamp, subject] = line.split("\u001f");
      return {
        hash: hash!,
        timestamp: timestamp!,
        subject: subject!.slice(0, 500),
      };
    });
}

export function parseBlame(output: string): BlameLine[] {
  const lines = output.split(/\r?\n/);
  const result: BlameLine[] = [];
  let hash: string | null = null;
  let line = 0;
  let author: string | null = null;
  let timestamp: number | null = null;
  for (const value of lines) {
    const header = value.match(/^([a-f0-9^]{40,64}) \d+ (\d+)/);
    if (header) {
      hash = header[1]!.startsWith("^") ? null : header[1]!;
      line = Number(header[2]);
    } else if (value.startsWith("author ")) author = value.slice(7);
    else if (value.startsWith("author-time "))
      timestamp = Number(value.slice(12));
    else if (value.startsWith("\t")) {
      result.push({ line, hash, author, timestamp, content: value.slice(1) });
      author = null;
      timestamp = null;
    }
  }
  return result;
}

export async function collectBlame(
  cwd: string,
  path: string,
  range: string,
): Promise<BlameLine[]> {
  const { start, end } = parseLineRange(range);
  const result = await runGit(
    ["blame", "--line-porcelain", "-L", `${start},${end}`, "--", path],
    { cwd, maximumBytes: 2 * 1024 * 1024 },
  );
  return result.ok ? parseBlame(result.stdout) : [];
}

export {
  collectBlame,
  collectFileHistory,
  parseBlame,
  parseLineRange,
  type BlameLine,
  type FileHistoryEntry,
} from "./file-history.js";

import { createHash } from "node:crypto";

import { runGit } from "../index.js";

export interface GitHistoryEntry {
  readonly hash: string;
  readonly parents: readonly string[];
  readonly authorName: string;
  readonly authorEmail: string | null;
  readonly timestamp: string;
  readonly subject: string;
  readonly changedPaths: readonly string[];
}

export type AuthorEmailPolicy = "omit" | "hash";

export function parseGitHistory(
  output: string,
  emailPolicy: AuthorEmailPolicy = "omit",
): GitHistoryEntry[] {
  return output
    .split("\u001e")
    .map((record) => record.trim())
    .filter(Boolean)
    .map((record) => {
      const [header, ...pathLines] = record.split(/\r?\n/);
      const [hash, parents, authorName, authorEmail, timestamp, subject] =
        header!.split("\u001f");
      return {
        hash: hash!,
        parents: parents ? parents.split(" ").filter(Boolean) : [],
        authorName: authorName!,
        authorEmail:
          emailPolicy === "hash"
            ? createHash("sha256").update(authorEmail!, "utf8").digest("hex")
            : null,
        timestamp: timestamp!,
        subject: (subject ?? "").slice(0, 500),
        changedPaths: pathLines
          .map((path) => path.trim().replaceAll("\\", "/"))
          .filter(Boolean)
          .sort(),
      };
    });
}

export async function collectGitHistory(
  cwd: string,
  options: {
    readonly limit?: number;
    readonly emailPolicy?: AuthorEmailPolicy;
  } = {},
): Promise<GitHistoryEntry[]> {
  const limit = Math.max(0, Math.min(options.limit ?? 20, 100));
  if (limit === 0) return [];
  const result = await runGit(
    [
      "log",
      `-${limit}`,
      "--no-decorate",
      "--date=iso-strict",
      "--format=%x1e%H%x1f%P%x1f%an%x1f%ae%x1f%aI%x1f%s",
      "--name-only",
    ],
    { cwd, maximumBytes: 2 * 1024 * 1024 },
  );
  return result.ok ? parseGitHistory(result.stdout, options.emailPolicy) : [];
}

export {
  collectGitHistory,
  parseGitHistory,
  type AuthorEmailPolicy,
  type GitHistoryEntry,
} from "./collect-history.js";

import { gitIdentitySchema, type GitIdentity } from "@fuzit/schemas";

import { runGit, type GitProcessResult } from "../index.js";

type Runner = (
  arguments_: readonly string[],
  options?: { readonly cwd?: string },
) => Promise<GitProcessResult>;

function sanitizeRemote(url: string): string {
  return url.replace(/:\/\/[^/\s:@]+:[^/\s@]+@/g, "://[REDACTED]@");
}

export async function collectGitIdentity(
  cwd: string,
  runner: Runner = runGit,
): Promise<GitIdentity> {
  const root = await runner(["rev-parse", "--show-toplevel"], { cwd });
  if (!root.ok)
    return gitIdentitySchema.parse({
      schemaVersion: 1,
      available: false,
      root: null,
      head: null,
      branch: null,
      detached: false,
      dirty: false,
      remotes: [],
    });
  const [head, branch, status, remotes] = await Promise.all([
    runner(["rev-parse", "--verify", "HEAD"], { cwd }),
    runner(["symbolic-ref", "--short", "-q", "HEAD"], { cwd }),
    runner(["status", "--porcelain=v1", "--untracked-files=normal"], { cwd }),
    runner(["remote", "-v"], { cwd }),
  ]);
  const remoteMap = new Map<string, string>();
  for (const line of remotes.stdout.split(/\r?\n/)) {
    const match = line.match(/^(\S+)\s+(\S+)\s+\(fetch\)$/);
    if (match) remoteMap.set(match[1]!, sanitizeRemote(match[2]!));
  }
  return gitIdentitySchema.parse({
    schemaVersion: 1,
    available: true,
    root: root.stdout.trim(),
    head: head.ok ? head.stdout.trim() : null,
    branch: branch.ok ? branch.stdout.trim() : null,
    detached: head.ok && !branch.ok,
    dirty: status.ok && status.stdout.length > 0,
    remotes: [...remoteMap].map(([name, url]) => ({ name, url })),
  });
}

import { spawn, type SpawnOptionsWithoutStdio } from "node:child_process";
import { redactSensitiveText } from "@fuzit/security";

export interface GitProcessResult {
  readonly ok: boolean;
  readonly exitCode: number | null;
  readonly stdout: string;
  readonly stderr: string;
  readonly timedOut: boolean;
  readonly cancelled: boolean;
  readonly error?: string;
}

export interface GitProcessOptions {
  readonly cwd?: string;
  readonly timeoutMs?: number;
  readonly maximumBytes?: number;
  readonly signal?: AbortSignal;
  readonly executable?: string;
  readonly spawnProcess?: typeof spawn;
}

function sanitize(value: string): string {
  const redacted = redactSensitiveText(value).replace(/\r?\n/g, " ");
  return [...redacted]
    .filter((character) => {
      const code = character.codePointAt(0) ?? 0;
      return code >= 32 && code !== 127;
    })
    .join("");
}

export async function runGit(
  arguments_: readonly string[],
  options: GitProcessOptions = {},
): Promise<GitProcessResult> {
  const maximumBytes = options.maximumBytes ?? 1024 * 1024;
  const spawnOptions: SpawnOptionsWithoutStdio = {
    cwd: options.cwd,
    shell: false,
    windowsHide: true,
    env: { ...process.env, GIT_TERMINAL_PROMPT: "0" },
  };
  return new Promise((resolve) => {
    let settled = false;
    let stdout: Uint8Array = new Uint8Array();
    let stderr: Uint8Array = new Uint8Array();
    let timedOut = false;
    let cancelled = false;
    let child;
    try {
      child = (options.spawnProcess ?? spawn)(
        options.executable ?? "git",
        [...arguments_],
        spawnOptions,
      );
    } catch (error) {
      resolve({
        ok: false,
        exitCode: null,
        stdout: "",
        stderr: "",
        timedOut: false,
        cancelled: false,
        error: sanitize(error instanceof Error ? error.message : String(error)),
      });
      return;
    }
    const append = (current: Uint8Array, chunk: Uint8Array): Uint8Array =>
      Buffer.concat([current, chunk]).subarray(0, maximumBytes);
    child.stdout?.on("data", (chunk: Buffer) => {
      stdout = append(stdout, chunk);
    });
    child.stderr?.on("data", (chunk: Buffer) => {
      stderr = append(stderr, chunk);
    });
    const finish = (exitCode: number | null, error?: string) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      options.signal?.removeEventListener("abort", abort);
      resolve({
        ok: exitCode === 0 && !timedOut && !cancelled && error === undefined,
        exitCode,
        stdout: Buffer.from(stdout).toString("utf8"),
        stderr: sanitize(Buffer.from(stderr).toString("utf8")),
        timedOut,
        cancelled,
        ...(error === undefined ? {} : { error: sanitize(error) }),
      });
    };
    const abort = () => {
      cancelled = true;
      child.kill();
    };
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill();
    }, options.timeoutMs ?? 10_000);
    options.signal?.addEventListener("abort", abort, { once: true });
    if (options.signal?.aborted) abort();
    child.on("error", (error) => finish(null, error.message));
    child.on("close", (code) => finish(code));
  });
}

export async function detectGitCapability(): Promise<boolean> {
  return (await runGit(["--version"], { timeoutMs: 2_000 })).ok;
}

