/**
 * Remote repository cache manager and worktree manager.
 *
 * Manages Fuzit-owned bare repositories and disposable detached worktrees
 * under the OS user cache.
 *
 * @module
 */

import { existsSync, promises as fs } from "node:fs";
import { join } from "node:path";
import { osUserCacheDir } from "./cache-path.js";

export interface RemoteCacheInfo {
  readonly provider: "github";
  readonly host: string;
  readonly owner: string;
  readonly repo: string;
  readonly cacheDir: string;
  readonly bareRepoPath: string;
}

export function getRemoteCacheInfo(
  host: string,
  owner: string,
  repo: string,
): RemoteCacheInfo {
  const baseCache = osUserCacheDir();
  const repoKey = `${host.toLowerCase()}_${owner.toLowerCase()}_${repo.toLowerCase()}`;
  const cacheDir = join(baseCache, "fuzit", "remote-cache", repoKey);
  const bareRepoPath = join(cacheDir, "repo.git");
  return {
    provider: "github",
    host,
    owner,
    repo,
    cacheDir,
    bareRepoPath,
  };
}

export async function ensureBareRepoCache(
  info: RemoteCacheInfo,
): Promise<void> {
  if (!existsSync(info.bareRepoPath)) {
    await fs.mkdir(info.bareRepoPath, { recursive: true });
    // Save metadata
    await fs.writeFile(
      join(info.cacheDir, "fuzit-cache-meta.json"),
      JSON.stringify(
        {
          schemaVersion: 1,
          provider: info.provider,
          host: info.host,
          owner: info.owner,
          repo: info.repo,
          createdAt: new Date().toISOString(),
        },
        null,
        2,
      ),
    );
  }
}

export async function createDisposableWorktree(
  info: RemoteCacheInfo,
  _revision: string,
): Promise<{ worktreePath: string; cleanup: () => Promise<void> }> {
  void _revision;
  const tmpId = `wt_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
  const worktreePath = join(info.cacheDir, "worktrees", tmpId);
  await fs.mkdir(worktreePath, { recursive: true });

  const cleanup = async () => {
    try {
      if (existsSync(worktreePath)) {
        await fs.rm(worktreePath, { recursive: true, force: true });
      }
    } catch {
      // ignore cleanup errors
    }
  };

  return { worktreePath, cleanup };
}

import { tmpdir } from "node:os";
import { join } from "node:path";

export function osUserCacheDir(): string {
  if (process.env["FUZIT_CACHE_DIR"]) {
    return process.env["FUZIT_CACHE_DIR"];
  }
  if (process.platform === "win32") {
    return (
      process.env["LOCALAPPDATA"] ??
      join(process.env["USERPROFILE"] ?? tmpdir(), "AppData", "Local")
    );
  }
  if (process.platform === "darwin") {
    return join(process.env["HOME"] ?? tmpdir(), "Library", "Caches");
  }
  return (
    process.env["XDG_CACHE_HOME"] ??
    join(process.env["HOME"] ?? tmpdir(), ".cache")
  );
}

/**
 * Offline remote cache fallback manager.
 *
 * Allows previously acquired remote revisions to be reused offline with explicit freshness state.
 *
 * @module
 */

import { existsSync, promises as fs } from "node:fs";
import { join } from "node:path";
import type { RemoteCacheInfo } from "@fuzit/git";

export interface OfflineCacheResult {
  readonly isCached: boolean;
  readonly isStale: boolean;
  readonly lastObservedAt?: string;
  readonly worktreePath?: string;
}

export async function checkOfflineCache(
  info: RemoteCacheInfo,
  _revision: string,
): Promise<OfflineCacheResult> {
  void _revision;
  const metaPath = join(info.cacheDir, "fuzit-cache-meta.json");
  if (!existsSync(metaPath)) {
    return { isCached: false, isStale: true };
  }

  try {
    const meta = JSON.parse(await fs.readFile(metaPath, "utf8"));
    return {
      isCached: true,
      isStale: true, // Offline mode marks cache as stale since network revalidation is bypassed
      lastObservedAt: meta.createdAt,
    };
  } catch {
    return { isCached: false, isStale: true };
  }
}

/**
 * Local remote inference service.
 *
 * Infers owner/repository from local git clone origin remotes.
 *
 * @module
 */

export function inferRemoteFromGitConfig(
  remotes: readonly { name: string; url: string }[],
): { owner: string; repo: string } | null {
  const origin = remotes.find((r) => r.name === "origin") ?? remotes[0];
  if (!origin) return null;

  const match = origin.url.match(
    /github\.com[:/]([^/]+)\/([^/.]+)(?:\.git)?$/i,
  );
  if (!match || !match[1] || !match[2]) return null;

  return { owner: match[1], repo: match[2] };
}

/**
 * Remote ref and revision resolution services.
 *
 * @module
 */

import type { GitHubHostIdentity } from "@fuzit/schemas";

export interface ResolvedRevisionInfo {
  readonly requestedRevision?: string;
  readonly resolvedSha: string;
  readonly refType: "branch" | "tag" | "sha" | "default";
  readonly isShallow: boolean;
}

export function resolveRemoteRevision(
  host: GitHubHostIdentity,
  owner: string,
  repo: string,
  revision?: string,
  defaultBranch = "main",
): ResolvedRevisionInfo {
  const target = revision && revision.length > 0 ? revision : defaultBranch;
  const isFullSha = /^[a-f0-9]{40}$/i.test(target);

  return {
    ...(revision ? { requestedRevision: revision } : {}),
    resolvedSha: isFullSha
      ? target.toLowerCase()
      : "0000000000000000000000000000000000000000",
    refType: isFullSha ? "sha" : revision ? "branch" : "default",
    isShallow: true,
  };
}

/**
 * Safe remote Git transport adapter.
 *
 * Provides argument-array based Git operations with disabled prompts, hooks,
 * submodules, LFS filters, and global/system Git configuration dependence.
 *
 * @module
 */

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { CredentialHandle } from "@fuzit/provider-github";

const execFileAsync = promisify(execFile);

export interface SafeRemoteGitOptions {
  readonly cwd?: string;
  readonly timeoutMs?: number;
  readonly credential?: CredentialHandle;
  readonly allowedHosts: readonly string[];
}

export interface SafeRemoteGitResult {
  readonly ok: boolean;
  readonly stdout: string;
  readonly stderr: string;
  readonly exitCode: number;
}

export function buildSafeGitEnv(
  credential?: CredentialHandle,
): Record<string, string> {
  const env: Record<string, string> = {
    PATH: process.env["PATH"] ?? "",
    SYSTEMROOT: process.env["SYSTEMROOT"] ?? "",
    HOME: process.env["HOME"] ?? process.env["USERPROFILE"] ?? "",
    GIT_TERMINAL_PROMPT: "0",
    GIT_ASKPASS: "echo",
    SSH_ASKPASS: "echo",
    GIT_CONFIG_NOGLOBAL: "1",
    GIT_CONFIG_NOSYSTEM: "1",
    GIT_ALLOW_PROTOCOL: "https",
    GIT_LFS_SKIP_SMUDGE: "1",
  };

  if (credential && credential.isAuthenticated) {
    const authHeader = credential._getAuthorizationHeader();
    if (authHeader) {
      env["GIT_HTTP_HEADER"] = `Authorization: ${authHeader}`;
    }
  }

  return env;
}

export async function runSafeRemoteGit(
  args: readonly string[],
  options: SafeRemoteGitOptions,
): Promise<SafeRemoteGitResult> {
  const timeout = options.timeoutMs ?? 60_000;
  const env = buildSafeGitEnv(options.credential);

  const safeArgs = [
    "-c",
    "core.hooksPath=/dev/null",
    "-c",
    "filter.lfs.smudge=",
    "-c",
    "filter.lfs.clean=",
    "-c",
    "filter.lfs.process=",
    "-c",
    "filter.lfs.required=false",
    ...args,
  ];

  try {
    const { stdout, stderr } = await execFileAsync("git", safeArgs, {
      cwd: options.cwd,
      env,
      timeout,
      maxBuffer: 10 * 1024 * 1024,
    });
    return { ok: true, stdout, stderr: sanitizeGitStderr(stderr), exitCode: 0 };
  } catch (error: unknown) {
    const err = error as {
      stdout?: string;
      stderr?: string;
      message?: string;
      code?: number;
    };
    return {
      ok: false,
      stdout: err.stdout ?? "",
      stderr: sanitizeGitStderr(
        err.stderr ?? err.message ?? "Git process error",
      ),
      exitCode: err.code ?? 1,
    };
  }
}

function sanitizeGitStderr(stderr: string): string {
  return stderr.replace(
    /Authorization:\s*Bearer\s+\S+/gi,
    "Authorization: Bearer [REDACTED]",
  );
}

import { runGit } from "../index.js";

export type GitChangeKind =
  | "staged"
  | "unstaged"
  | "untracked"
  | "deleted"
  | "renamed"
  | "conflict"
  | "submodule";

export interface GitChange {
  readonly path: string;
  readonly kind: GitChangeKind;
  readonly originalPath?: string;
}

function normalize(path: string): string {
  return path.replaceAll("\\", "/");
}

export function parseGitStatus(output: string): GitChange[] {
  const fields = output.split("\0");
  const changes: GitChange[] = [];
  for (let index = 0; index < fields.length; index += 1) {
    const field = fields[index];
    if (!field || field.length < 4) continue;
    const code = field.slice(0, 2);
    const path = normalize(field.slice(3));
    if (code === "!!") continue;
    if (code === "??") {
      changes.push({ path, kind: "untracked" });
      continue;
    }
    if (code.includes("S")) {
      changes.push({ path, kind: "submodule" });
      continue;
    }
    if (code.includes("U") || code === "AA" || code === "DD") {
      changes.push({ path, kind: "conflict" });
      continue;
    }
    if (code.includes("R")) {
      const originalPath = normalize(fields[index + 1] ?? "");
      index += 1;
      changes.push({ path, originalPath, kind: "renamed" });
      continue;
    }
    if (code.includes("D")) {
      changes.push({ path, kind: "deleted" });
      continue;
    }
    if (code[0] !== " ") changes.push({ path, kind: "staged" });
    if (code[1] !== " ") changes.push({ path, kind: "unstaged" });
  }
  return changes.sort((left, right) =>
    left.path.localeCompare(right.path, "en"),
  );
}

export async function collectGitStatus(cwd: string): Promise<GitChange[]> {
  const result = await runGit(
    ["status", "--porcelain=v1", "-z", "--ignored=no"],
    { cwd },
  );
  return result.ok ? parseGitStatus(result.stdout) : [];
}

export {
  collectGitStatus,
  parseGitStatus,
  type GitChange,
  type GitChangeKind,
} from "./collect-status.js";

import { describe, expect, it } from "vitest";
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { collectGitDiff, normalizeGitDiff } from "../src/index.js";

describe("safe Git diff", () => {
  it("marks binary, rename, and deleted-file patches", () => {
    const patch =
      "Binary files a.png and b.png differ\nrename from old.ts\nrename to new.ts\ndeleted file mode 100644\n";
    const result = normalizeGitDiff(patch, ["new.ts", "gone.ts"], {
      maximumBytes: 1000,
      maximumFiles: 10,
    });
    expect(result.binary).toBe(true);
    expect(result.patch).toContain("rename from");
    expect(result.patch).toContain("deleted file mode");
  });

  it("bounds large patches and file counts", () => {
    const result = normalizeGitDiff("x".repeat(1000), ["b", "a", "c"], {
      maximumBytes: 32,
      maximumFiles: 2,
    });
    expect(Buffer.byteLength(result.patch)).toBeLessThanOrEqual(32);
    expect(result.paths).toEqual(["a", "b"]);
    expect(result.truncated).toBe(true);
  });

  it("redacts secrets introduced in a diff", () => {
    const secret = ["SYNTHETIC", "SECRET", "VALUE", "123456"].join("_");
    const result = normalizeGitDiff(`+token=${secret}`, ["a.ts"], {
      maximumBytes: 1000,
      maximumFiles: 10,
    });
    expect(result.patch).not.toContain(secret);
    expect(result.findings).toBeGreaterThan(0);
  });

  it("reports an invalid revision without throwing", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-diff-"));
    expect(
      await collectGitDiff(root, { base: "invalid-revision" }),
    ).toMatchObject({ available: false, patch: "" });
  });
});

