import { describe, expect, it } from "vitest";

import { parseGitHistory } from "../src/index.js";

const separator = "\u001f";
const end = "\u001e";

describe("bounded Git history", () => {
  it("parses merge commits and changed paths", () => {
    const output = [
      "a".repeat(40),
      `${"b".repeat(40)} ${"c".repeat(40)}`,
      "Author",
      "author@example.test",
      "2026-01-01T00:00:00Z",
      "merge",
    ].join(separator);
    expect(
      parseGitHistory(`${output}\nspace file.ts\n${end}`)[0],
    ).toMatchObject({
      parents: ["b".repeat(40), "c".repeat(40)],
      changedPaths: ["space file.ts"],
    });
  });

  it("bounds long and non-UTF8 replacement subjects", () => {
    const subject = `bad�${"x".repeat(1000)}`;
    const output = [
      "a".repeat(40),
      "",
      "Author",
      "author@example.test",
      "2026-01-01T00:00:00Z",
      subject,
    ].join(separator);
    expect(parseGitHistory(`${output}${end}`)[0]!.subject).toHaveLength(500);
  });

  it("omits or hashes author email and tolerates shallow history", () => {
    const output = [
      "a".repeat(40),
      "",
      "Author",
      "author@example.test",
      "2026-01-01T00:00:00Z",
      "initial",
    ].join(separator);
    expect(parseGitHistory(`${output}${end}`)[0]!.authorEmail).toBeNull();
    expect(parseGitHistory(`${output}${end}`, "hash")[0]!.authorEmail).toMatch(
      /^[a-f0-9]{64}$/,
    );
    expect(parseGitHistory("")).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";

import { collectGitIdentity, type GitProcessResult } from "../src/index.js";

const result = (stdout: string, ok = true): GitProcessResult => ({
  ok,
  exitCode: ok ? 0 : 1,
  stdout,
  stderr: "",
  timedOut: false,
  cancelled: false,
});

function runner(values: Record<string, GitProcessResult>) {
  return async (arguments_: readonly string[]) =>
    values[arguments_.join(" ")] ?? result("", false);
}

describe("Git identity", () => {
  it("handles detached HEAD and worktree roots", async () => {
    const identity = await collectGitIdentity(
      "worktree",
      runner({
        "rev-parse --show-toplevel": result("/repo/worktree\n"),
        "rev-parse --verify HEAD": result("a".repeat(40)),
        "status --porcelain=v1 --untracked-files=normal": result(""),
        "remote -v": result(""),
      }),
    );
    expect(identity).toMatchObject({
      root: "/repo/worktree",
      detached: true,
      branch: null,
    });
  });

  it("handles unborn and dirty branches", async () => {
    const identity = await collectGitIdentity(
      ".",
      runner({
        "rev-parse --show-toplevel": result("/repo"),
        "rev-parse --verify HEAD": result("", false),
        "symbolic-ref --short -q HEAD": result("main\n"),
        "status --porcelain=v1 --untracked-files=normal": result("?? a\n"),
        "remote -v": result(""),
      }),
    );
    expect(identity).toMatchObject({ head: null, branch: "main", dirty: true });
  });

  it("sanitizes credential-bearing remotes", async () => {
    const identity = await collectGitIdentity(
      ".",
      runner({
        "rev-parse --show-toplevel": result("/repo"),
        "rev-parse --verify HEAD": result("b".repeat(40)),
        "symbolic-ref --short -q HEAD": result("main"),
        "status --porcelain=v1 --untracked-files=normal": result(""),
        "remote -v": result(
          "origin [REDACTED:url-credential]example.test/repo (fetch)\n",
        ),
      }),
    );
    expect(identity.remotes[0]?.url).toBe(
      "https://[REDACTED]@example.test/repo",
    );
  });
});

import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "node:child_process";
import { describe, expect, it } from "vitest";

import { runGit } from "../src/index.js";

describe("safe Git process", () => {
  it("reports a missing executable", async () => {
    expect(
      (await runGit([], { executable: "fuzit-git-does-not-exist" })).ok,
    ).toBe(false);
  });

  it("times out and handles non-repositories", async () => {
    expect(
      (
        await runGit(["-e", "setTimeout(()=>{},1000)"], {
          executable: process.execPath,
          timeoutMs: 10,
        })
      ).timedOut,
    ).toBe(true);
    const root = await mkdtemp(join(tmpdir(), "fuzit-git-"));
    expect((await runGit(["rev-parse", "HEAD"], { cwd: root })).ok).toBe(false);
  });

  it("bounds and sanitizes hostile stderr", async () => {
    const result = await runGit(
      ["-e", "process.stderr.write('evil\\n'.repeat(1000)+'\\u0000')"],
      { executable: process.execPath, maximumBytes: 64 },
    );
    expect(Buffer.byteLength(result.stderr)).toBeLessThanOrEqual(64);
    expect(result.stderr).not.toContain("\n");
    expect(result.stderr).not.toContain("\u0000");
  });

  it("never invokes a shell", async () => {
    let shell: unknown;
    await runGit(["--version"], {
      spawnProcess(command, arguments_, options) {
        shell = options.shell;
        return spawn(command, arguments_, options);
      },
    });
    expect(shell).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

