import type { GraphEdge, GraphNode, NormalizedAnalysis } from "@fuzit/schemas";
import { createGraphEdge } from "./edges.js";
import { createGraphNode } from "./nodes.js";

export interface GraphDependencyInput {
  readonly name: string;
  readonly optional?: boolean;
}
export interface GraphPackageInput {
  readonly name: string;
  readonly path: string;
  readonly manifestPath: string;
  readonly dependencies: readonly (string | GraphDependencyInput)[];
}
export interface BuildFilePackageGraphInput {
  readonly analysis: NormalizedAnalysis;
  readonly revision: string;
  readonly packages: readonly GraphPackageInput[];
}
export interface GraphSnapshot {
  readonly schemaVersion: 1;
  readonly repositoryId: string;
  readonly nodes: readonly GraphNode[];
  readonly edges: readonly GraphEdge[];
  readonly diagnostics: readonly string[];
  readonly completeness: "complete" | "partial";
}
const byId = <T extends { readonly id: string }>(a: T, b: T) =>
  a.id.localeCompare(b.id);
const provenance = (revision: string, sourcePath: string | null) => ({
  collector: "graph-builder",
  collectorVersion: "1",
  basis: "observed" as const,
  revision,
  sourcePath,
  sourceRange: null,
});
const evidence = (sourcePath: string, reason: string) => [
  {
    basis: "direct" as const,
    collector: "graph-builder",
    collectorVersion: "1",
    sourcePath,
    reason,
  },
];

export function buildFilePackageGraph(
  input: BuildFilePackageGraphInput,
): GraphSnapshot {
  const { analysis, revision } = input;
  const diagnostics: string[] = [];
  const repository = createGraphNode({
    repositoryId: analysis.repositoryId,
    kind: "repository",
    identity: ".",
    path: null,
    parentId: null,
    provenance: provenance(revision, null),
  });
  const packages = [...input.packages].sort(
    (a, b) => a.path.localeCompare(b.path) || a.name.localeCompare(b.name),
  );
  const names = new Map<string, GraphNode[]>();
  const packageNodes = packages.map((item) => {
    const node = createGraphNode({
      repositoryId: analysis.repositoryId,
      kind: "package",
      identity: `${item.path}\0${item.name}`,
      path: item.path === "." ? null : item.path,
      parentId: repository.id,
      provenance: provenance(revision, item.manifestPath),
    });
    names.set(item.name, [...(names.get(item.name) ?? []), node]);
    return node;
  });
  for (const [name, matches] of names)
    if (matches.length > 1)
      diagnostics.push(`conflicting package manifest name: ${name}`);
  const packageByPath = new Map(
    packages.map((item, index) => [item.path, packageNodes[index]!]),
  );
  const nearestPackage = (path: string) =>
    [...packageByPath.entries()]
      .filter(
        ([root]) =>
          root === "." || path === root || path.startsWith(`${root}/`),
      )
      .sort(([a], [b]) => b.length - a.length || a.localeCompare(b))[0]?.[1] ??
    repository;
  const fileNodes = analysis.files.map((file) =>
    createGraphNode({
      repositoryId: analysis.repositoryId,
      kind: "file",
      identity: file.path,
      path: file.path,
      parentId: nearestPackage(file.path).id,
      provenance: provenance(revision, file.path),
    }),
  );
  const edges: GraphEdge[] = [...packageNodes, ...fileNodes].map((node) =>
    createGraphEdge({
      repositoryId: analysis.repositoryId,
      kind: "contains",
      sourceId: node.parentId!,
      sourceKind: node.parentId === repository.id ? "repository" : "package",
      targetId: node.id,
      targetKind: node.kind,
      unresolvedTarget: null,
      resolution: "resolved",
      evidence: evidence(
        node.provenance.sourcePath ?? "package.json",
        "canonical containment",
      ),
      revision: { validFrom: revision, validThrough: null },
    }),
  );
  packages.forEach((item, index) =>
    item.dependencies
      .map((dependency) =>
        typeof dependency === "string"
          ? { name: dependency, optional: false }
          : { name: dependency.name, optional: dependency.optional ?? false },
      )
      .sort((a, b) => a.name.localeCompare(b.name))
      .forEach((dependency) => {
        const matches = names.get(dependency.name) ?? [];
        edges.push(
          createGraphEdge({
            repositoryId: analysis.repositoryId,
            kind: "depends-on",
            sourceId: packageNodes[index]!.id,
            sourceKind: "package",
            targetId: matches.length === 1 ? matches[0]!.id : null,
            targetKind: matches.length === 1 ? "package" : null,
            unresolvedTarget: matches.length === 1 ? null : dependency.name,
            resolution: matches.length === 1 ? "resolved" : "unresolved",
            evidence: evidence(
              item.manifestPath,
              `${dependency.optional ? "optional " : ""}manifest dependency ${dependency.name}`,
            ),
            revision: { validFrom: revision, validThrough: null },
          }),
        );
      }),
  );
  return {
    schemaVersion: 1,
    repositoryId: analysis.repositoryId,
    nodes: [repository, ...packageNodes, ...fileNodes].sort(byId),
    edges: edges.sort(byId),
    diagnostics: diagnostics.sort(),
    completeness: diagnostics.length ? "partial" : "complete",
  };
}

import type { GraphEdgeKind, NormalizedAnalysis } from "@fuzit/schemas";
import { createGraphEdge } from "./edges.js";
import type { GraphSnapshot } from "./build.js";

export interface MaterializeDependencyOptions {
  readonly revision: string;
  readonly collectorVersion: string;
}
const edgeKind = (kind: string): GraphEdgeKind | null =>
  kind === "import"
    ? "imports"
    : kind === "export"
      ? "exports"
      : kind === "reference"
        ? "references"
        : kind === "call"
          ? "calls"
          : null;

export function materializeImportDependencyEdges(
  snapshot: GraphSnapshot,
  analysis: NormalizedAnalysis,
  options: MaterializeDependencyOptions,
): GraphSnapshot {
  if (snapshot.repositoryId !== analysis.repositoryId)
    throw new Error("Graph and analysis repository identities must match");
  const fileByAnalysisId = new Map(
    analysis.files.map((file) => [
      file.id,
      snapshot.nodes.find(
        (node) => node.kind === "file" && node.path === file.path,
      ),
    ]),
  );
  const symbolByAnalysisId = new Map(
    analysis.symbols.map((symbol) => {
      const file = analysis.files.find((item) => item.id === symbol.fileId);
      const node = snapshot.nodes.find(
        (item) =>
          item.path === file?.path &&
          item.provenance.sourceRange?.start.offset ===
            symbol.range.start.offset &&
          ["symbol", "test", "endpoint", "schema-model"].includes(item.kind),
      );
      return [symbol.id, node] as const;
    }),
  );
  const resolve = (id: string) =>
    fileByAnalysisId.get(id) ?? symbolByAnalysisId.get(id);
  const edges = [...snapshot.edges];
  const diagnostics = [...snapshot.diagnostics];
  for (const relation of [...analysis.relationships].sort((a, b) =>
    a.id.localeCompare(b.id),
  )) {
    const kind = edgeKind(relation.kind);
    if (!kind) continue;
    const source = resolve(relation.sourceId);
    const target = relation.targetId ? resolve(relation.targetId) : undefined;
    if (!source) {
      diagnostics.push(`dependency source unavailable: ${relation.id}`);
      continue;
    }
    const unresolvedTarget = target
      ? null
      : (relation.unresolvedTarget ?? relation.targetId ?? "deleted-target");
    edges.push(
      createGraphEdge({
        repositoryId: snapshot.repositoryId,
        kind,
        sourceId: source.id,
        sourceKind: source.kind,
        targetId: target?.id ?? null,
        targetKind: target?.kind ?? null,
        unresolvedTarget,
        resolution: target ? "resolved" : "unresolved",
        evidence: [
          {
            basis: "parsed",
            collector: relation.provenance.parserIdentity,
            collectorVersion: options.collectorVersion,
            sourcePath: source.path,
            reason: target
              ? `${relation.kind} resolved`
              : `${relation.kind} unresolved: ${unresolvedTarget}`,
          },
        ],
        revision: { validFrom: options.revision, validThrough: null },
      }),
    );
  }
  return {
    ...snapshot,
    edges: edges.sort((a, b) => a.id.localeCompare(b.id)),
    diagnostics: diagnostics.sort(),
    completeness: diagnostics.length ? "partial" : snapshot.completeness,
  };
}

import type {
  GraphEdgeKind,
  GraphNode,
  NormalizedAnalysis,
} from "@fuzit/schemas";
import type { GraphSnapshot } from "./build.js";
import { createGraphEdge } from "./edges.js";
import { createGraphNode } from "./nodes.js";

export interface MaterializeDomainRelationOptions {
  readonly revision: string;
  readonly collectorVersion: string;
}
const specializedKinds = new Set(["test", "endpoint", "schema-model"]);
const findNode = (
  snapshot: GraphSnapshot,
  analysis: NormalizedAnalysis,
  id: string,
): GraphNode | undefined => {
  const file = analysis.files.find((item) => item.id === id);
  if (file)
    return snapshot.nodes.find(
      (node) => node.kind === "file" && node.path === file.path,
    );
  const symbol = analysis.symbols.find((item) => item.id === id);
  const symbolFile =
    symbol && analysis.files.find((item) => item.id === symbol.fileId);
  return symbol && symbolFile
    ? snapshot.nodes.find(
        (node) =>
          node.path === symbolFile.path &&
          node.provenance.sourceRange?.start.offset ===
            symbol.range.start.offset &&
          (node.kind === "symbol" || specializedKinds.has(node.kind)),
      )
    : undefined;
};

export function materializeDomainRelations(
  snapshot: GraphSnapshot,
  analysis: NormalizedAnalysis,
  options: MaterializeDomainRelationOptions,
): GraphSnapshot {
  if (snapshot.repositoryId !== analysis.repositoryId)
    throw new Error("Graph and analysis repository identities must match");
  const nodes = [...snapshot.nodes];
  const edges = [...snapshot.edges];
  const diagnostics = [...snapshot.diagnostics];
  for (const relation of [...analysis.relationships].sort((a, b) =>
    a.id.localeCompare(b.id),
  )) {
    if (
      !["test", "endpoint", "schema", "configuration-link"].includes(
        relation.kind,
      )
    )
      continue;
    let source = findNode({ ...snapshot, nodes }, analysis, relation.sourceId);
    const target = relation.targetId
      ? findNode({ ...snapshot, nodes }, analysis, relation.targetId)
      : undefined;
    const kind: GraphEdgeKind =
      relation.kind === "test"
        ? "tests"
        : relation.kind === "configuration-link"
          ? "configures"
          : "references";
    if (relation.kind === "configuration-link") {
      const sourceFile = analysis.files.find(
        (file) => file.id === relation.provenance.sourceFileId,
      );
      const parent =
        sourceFile &&
        nodes.find(
          (node) => node.kind === "file" && node.path === sourceFile.path,
        );
      if (sourceFile && parent) {
        source = createGraphNode({
          repositoryId: snapshot.repositoryId,
          kind: "configuration",
          identity: `${sourceFile.path}\0${relation.id}`,
          path: sourceFile.path,
          parentId: parent.id,
          provenance: {
            collector: relation.provenance.parserIdentity,
            collectorVersion: options.collectorVersion,
            basis: relation.provenance.basis,
            revision: options.revision,
            sourcePath: sourceFile.path,
            sourceRange: relation.provenance.range,
          },
        });
        nodes.push(source);
      }
    }
    if (!source) {
      diagnostics.push(`domain relation source unavailable: ${relation.id}`);
      continue;
    }
    const unresolvedTarget = target
      ? null
      : (relation.unresolvedTarget ??
        relation.targetId ??
        `${relation.kind}-target`);
    edges.push(
      createGraphEdge({
        repositoryId: snapshot.repositoryId,
        kind,
        sourceId: source.id,
        sourceKind: source.kind,
        targetId: target?.id ?? null,
        targetKind: target?.kind ?? null,
        unresolvedTarget,
        resolution: target ? "resolved" : "unresolved",
        evidence: [
          {
            basis:
              relation.provenance.basis === "parsed" ? "parsed" : "heuristic",
            collector: relation.provenance.parserIdentity,
            collectorVersion: options.collectorVersion,
            sourcePath: source.path,
            reason: `${relation.kind} evidence`,
          },
        ],
        revision: { validFrom: options.revision, validThrough: null },
      }),
    );
  }
  return {
    ...snapshot,
    nodes: nodes.sort((a, b) => a.id.localeCompare(b.id)),
    edges: edges.sort((a, b) => a.id.localeCompare(b.id)),
    diagnostics: diagnostics.sort(),
    completeness: diagnostics.length ? "partial" : snapshot.completeness,
  };
}

import { createHash } from "node:crypto";
import {
  parseGraphEdge,
  type GraphEdge,
  type GraphEdgeKind,
} from "@fuzit/schemas";

export type CreateGraphEdgeInput = Omit<GraphEdge, "id" | "schemaVersion">;
export function createGraphEdgeId(
  repositoryId: string,
  kind: GraphEdgeKind,
  sourceId: string,
  targetIdentity: string,
): string {
  const digest = createHash("sha256")
    .update(
      `${repositoryId}\0${kind}\0${sourceId}\0${targetIdentity.normalize("NFC")}`,
    )
    .digest("hex");
  return `graph:edge:${digest}`;
}
export function createGraphEdge(input: CreateGraphEdgeInput): GraphEdge {
  const targetIdentity = input.targetId ?? input.unresolvedTarget ?? "";
  return parseGraphEdge({
    schemaVersion: 1,
    ...input,
    unresolvedTarget: input.unresolvedTarget?.normalize("NFC") ?? null,
    id: createGraphEdgeId(
      input.repositoryId,
      input.kind,
      input.sourceId,
      targetIdentity,
    ),
  });
}

