export * from "@fuzit/schemas";

import type { GraphSnapshot } from "./build.js";
import { createGraphEdge } from "./edges.js";
import { createGraphNode } from "./nodes.js";

export interface GraphChangeInput {
  readonly revision: string;
  readonly path: string;
  readonly previousPath?: string;
  readonly introduced?: boolean;
  readonly changedWith?: readonly string[];
}
export interface MaterializeLifecycleOptions {
  readonly historyAvailable: boolean;
  readonly shallow: boolean;
  readonly changes: readonly GraphChangeInput[];
}

export function materializeLifecycleRelations(
  snapshot: GraphSnapshot,
  options: MaterializeLifecycleOptions,
): GraphSnapshot {
  const nodes = [...snapshot.nodes];
  const edges = [...snapshot.edges];
  const diagnostics = [...snapshot.diagnostics];
  if (!options.historyAvailable) diagnostics.push("git history unavailable");
  if (options.shallow)
    diagnostics.push("git history is shallow; lifecycle evidence is partial");
  for (const change of [...options.changes].sort(
    (a, b) =>
      a.revision.localeCompare(b.revision) || a.path.localeCompare(b.path),
  )) {
    const file = nodes.find(
      (node) => node.kind === "file" && node.path === change.path,
    );
    if (!file) {
      diagnostics.push(`changed file unavailable: ${change.path}`);
      continue;
    }
    const changeNode = createGraphNode({
      repositoryId: snapshot.repositoryId,
      kind: "change",
      identity: `${change.revision}\0${change.path}`,
      path: change.path,
      parentId: nodes.find((node) => node.kind === "repository")!.id,
      provenance: {
        collector: "git",
        collectorVersion: "1",
        basis: "observed",
        revision: change.revision,
        sourcePath: change.path,
        sourceRange: null,
      },
    });
    nodes.push(changeNode);
    const evidence = [
      {
        basis: "direct" as const,
        collector: "git",
        collectorVersion: "1",
        sourcePath: change.path,
        reason: change.previousPath
          ? `renamed from ${change.previousPath}`
          : "observed Git change",
      },
    ];
    edges.push(
      createGraphEdge({
        repositoryId: snapshot.repositoryId,
        kind: "modifies",
        sourceId: changeNode.id,
        sourceKind: "change",
        targetId: file.id,
        targetKind: "file",
        unresolvedTarget: null,
        resolution: "resolved",
        evidence,
        revision: { validFrom: change.revision, validThrough: null },
      }),
    );
    if (change.introduced)
      edges.push(
        createGraphEdge({
          repositoryId: snapshot.repositoryId,
          kind: "introduced-by",
          sourceId: file.id,
          sourceKind: "file",
          targetId: changeNode.id,
          targetKind: "change",
          unresolvedTarget: null,
          resolution: "resolved",
          evidence,
          revision: { validFrom: change.revision, validThrough: null },
        }),
      );
    for (const peerPath of [...(change.changedWith ?? [])].sort()) {
      const peer = nodes.find(
        (node) => node.kind === "file" && node.path === peerPath,
      );
      if (peer)
        edges.push(
          createGraphEdge({
            repositoryId: snapshot.repositoryId,
            kind: "changed-with",
            sourceId: file.id,
            sourceKind: "file",
            targetId: peer.id,
            targetKind: "file",
            unresolvedTarget: null,
            resolution: "resolved",
            evidence,
            revision: { validFrom: change.revision, validThrough: null },
          }),
        );
    }
  }
  return {
    ...snapshot,
    nodes: nodes.sort((a, b) => a.id.localeCompare(b.id)),
    edges: edges.sort((a, b) => a.id.localeCompare(b.id)),
    diagnostics: diagnostics.sort(),
    completeness: diagnostics.length ? "partial" : snapshot.completeness,
  };
}

import { createHash } from "node:crypto";

import {
  GRAPH_SCHEMA_VERSION,
  parseGraphNode,
  type GraphNode,
  type GraphNodeKind,
  type GraphProvenance,
} from "@fuzit/schemas";

export interface CreateGraphNodeInput {
  readonly repositoryId: string;
  readonly kind: GraphNodeKind;
  readonly identity: string;
  readonly path: string | null;
  readonly parentId: string | null;
  readonly provenance: GraphProvenance;
}

export function createGraphNodeId(
  repositoryId: string,
  kind: GraphNodeKind,
  identity: string,
): string {
  const digest = createHash("sha256")
    .update(`${repositoryId}\0${kind}\0${identity.normalize("NFC")}`)
    .digest("hex");
  return `graph:node:${digest}`;
}

export function createGraphNode(input: CreateGraphNodeInput): GraphNode {
  return parseGraphNode({
    schemaVersion: GRAPH_SCHEMA_VERSION,
    ...input,
    identity: input.identity.normalize("NFC"),
    path: input.path?.normalize("NFC") ?? null,
    id: createGraphNodeId(input.repositoryId, input.kind, input.identity),
  });
}

import type { GraphEdgeKind, GraphNode, GraphNodeKind } from "@fuzit/schemas";
import type { GraphSnapshot } from "./build.js";

export const GRAPH_QUERY_MAX_DEPTH = 10;
export const GRAPH_QUERY_MAX_ITEMS = 1_000;
export interface GraphQueryLimits {
  readonly depth: number;
  readonly maxItems: number;
}
export interface GraphQueryOptions {
  readonly repositoryId: string;
  readonly limits: GraphQueryLimits;
  readonly signal?: AbortSignal;
  readonly allowNode?: (node: GraphNode) => boolean;
  readonly nodeKinds?: readonly GraphNodeKind[];
  readonly edgeKinds?: readonly GraphEdgeKind[];
}
export interface GraphQueryResult {
  readonly nodes: readonly GraphNode[];
  readonly truncated: boolean;
  readonly diagnostics: readonly string[];
}
const byId = <T extends { readonly id: string }>(a: T, b: T) =>
  a.id.localeCompare(b.id);
const validate = (snapshot: GraphSnapshot, options: GraphQueryOptions) => {
  if (options.repositoryId !== snapshot.repositoryId)
    throw new Error("Cross-repository graph queries are forbidden");
  if (
    !Number.isInteger(options.limits.depth) ||
    options.limits.depth < 0 ||
    options.limits.depth > GRAPH_QUERY_MAX_DEPTH
  )
    throw new Error(
      `Graph query depth must be between 0 and ${GRAPH_QUERY_MAX_DEPTH}`,
    );
  if (
    !Number.isInteger(options.limits.maxItems) ||
    options.limits.maxItems < 1 ||
    options.limits.maxItems > GRAPH_QUERY_MAX_ITEMS
  )
    throw new Error(
      `Graph query item limit must be between 1 and ${GRAPH_QUERY_MAX_ITEMS}`,
    );
};
const checkCancelled = (signal?: AbortSignal) => {
  if (signal?.aborted) throw new Error("Graph query cancelled");
};

export function graphStats(snapshot: GraphSnapshot) {
  const count = (values: readonly string[]) =>
    Object.fromEntries(
      [...new Set(values)]
        .sort()
        .map((kind) => [kind, values.filter((item) => item === kind).length]),
    );
  return {
    schemaVersion: 1 as const,
    repositoryId: snapshot.repositoryId,
    nodes: snapshot.nodes.length,
    edges: snapshot.edges.length,
    nodeKinds: count(snapshot.nodes.map((node) => node.kind)),
    edgeKinds: count(snapshot.edges.map((edge) => edge.kind)),
    completeness: snapshot.completeness,
    diagnostics: [...snapshot.diagnostics].sort(),
  };
}

export function graphNeighbors(
  snapshot: GraphSnapshot,
  startId: string,
  options: GraphQueryOptions,
): GraphQueryResult {
  validate(snapshot, options);
  checkCancelled(options.signal);
  if (!snapshot.nodes.some((node) => node.id === startId))
    throw new Error("Graph query start node is unavailable");
  const allowedKinds = options.edgeKinds ? new Set(options.edgeKinds) : null;
  const allowedNodes = options.nodeKinds ? new Set(options.nodeKinds) : null;
  const visited = new Set([startId]);
  let frontier = [startId];
  let truncated = false;
  for (
    let depth = 0;
    depth < options.limits.depth && frontier.length;
    depth += 1
  ) {
    const next: string[] = [];
    for (const id of frontier.sort()) {
      checkCancelled(options.signal);
      for (const edge of snapshot.edges) {
        if (allowedKinds && !allowedKinds.has(edge.kind)) continue;
        const neighbor =
          edge.sourceId === id
            ? edge.targetId
            : edge.targetId === id
              ? edge.sourceId
              : null;
        if (neighbor && !visited.has(neighbor)) {
          visited.add(neighbor);
          next.push(neighbor);
        }
      }
    }
    frontier = [...new Set(next)].sort();
  }
  const nodes = snapshot.nodes
    .filter((node) => visited.has(node.id) && node.id !== startId)
    .filter(
      (node) =>
        (!allowedNodes || allowedNodes.has(node.kind)) &&
        (options.allowNode?.(node) ?? true),
    )
    .sort(byId);
  if (nodes.length > options.limits.maxItems) truncated = true;
  return {
    nodes: nodes.slice(0, options.limits.maxItems),
    truncated,
    diagnostics: truncated
      ? [`graph query truncated at ${options.limits.maxItems} items`]
      : [],
  };
}

export const graphImpact = graphNeighbors;
export function graphQuery(
  snapshot: GraphSnapshot,
  options: GraphQueryOptions,
): GraphQueryResult {
  validate(snapshot, options);
  checkCancelled(options.signal);
  const kinds = options.nodeKinds ? new Set(options.nodeKinds) : null;
  const nodes = snapshot.nodes
    .filter(
      (node) =>
        (!kinds || kinds.has(node.kind)) && (options.allowNode?.(node) ?? true),
    )
    .sort(byId);
  return {
    nodes: nodes.slice(0, options.limits.maxItems),
    truncated: nodes.length > options.limits.maxItems,
    diagnostics:
      nodes.length > options.limits.maxItems
        ? [`graph query truncated at ${options.limits.maxItems} items`]
        : [],
  };
}

import type { GraphNodeKind, NormalizedAnalysis } from "@fuzit/schemas";
import { createGraphEdge } from "./edges.js";
import { createGraphNode } from "./nodes.js";
import type { GraphSnapshot } from "./build.js";

export interface MaterializeSymbolOptions {
  readonly parserIdentity: string;
  readonly parserVersion: string;
  readonly revision: string;
}
const byId = <T extends { readonly id: string }>(a: T, b: T) =>
  a.id.localeCompare(b.id);
const nodeKind = (kind: string): GraphNodeKind =>
  kind === "test"
    ? "test"
    : kind === "endpoint"
      ? "endpoint"
      : kind === "schema"
        ? "schema-model"
        : "symbol";

export function materializeSymbolNodes(
  snapshot: GraphSnapshot,
  analysis: NormalizedAnalysis,
  options: MaterializeSymbolOptions,
): GraphSnapshot {
  if (snapshot.repositoryId !== analysis.repositoryId)
    throw new Error("Graph and analysis repository identities must match");
  const analysisFiles = new Map(analysis.files.map((file) => [file.id, file]));
  const graphFiles = new Map(
    snapshot.nodes
      .filter((node) => node.kind === "file" && node.path)
      .map((node) => [node.path!, node]),
  );
  const diagnostics = [...snapshot.diagnostics];
  const nodes = [...snapshot.nodes];
  const edges = [...snapshot.edges];
  for (const symbol of [...analysis.symbols].sort((a, b) =>
    a.id.localeCompare(b.id),
  )) {
    const file = analysisFiles.get(symbol.fileId);
    const parent = file ? graphFiles.get(file.path) : undefined;
    if (!file || !parent) {
      diagnostics.push(`symbol parent unavailable: ${symbol.id}`);
      continue;
    }
    const identity = `${file.path}\0${symbol.kind}\0${symbol.name}\0${symbol.range.start.offset}\0${symbol.range.end.offset}`;
    const node = createGraphNode({
      repositoryId: snapshot.repositoryId,
      kind: nodeKind(symbol.kind),
      identity,
      path: file.path,
      parentId: parent.id,
      provenance: {
        collector: options.parserIdentity,
        collectorVersion: options.parserVersion,
        basis: "parsed",
        revision: options.revision,
        sourcePath: file.path,
        sourceRange: symbol.range,
      },
    });
    nodes.push(node);
    edges.push(
      createGraphEdge({
        repositoryId: snapshot.repositoryId,
        kind: "contains",
        sourceId: parent.id,
        sourceKind: "file",
        targetId: node.id,
        targetKind: node.kind,
        unresolvedTarget: null,
        resolution: "resolved",
        evidence: [
          {
            basis: "parsed",
            collector: options.parserIdentity,
            collectorVersion: options.parserVersion,
            sourcePath: file.path,
            reason: `parsed ${symbol.kind} ${symbol.name}`,
          },
        ],
        revision: { validFrom: options.revision, validThrough: null },
      }),
    );
  }
  return {
    ...snapshot,
    nodes: nodes.sort(byId),
    edges: edges.sort(byId),
    diagnostics: diagnostics.sort(),
    completeness: diagnostics.length ? "partial" : snapshot.completeness,
  };
}

import type { GraphEdge, GraphNode } from "@fuzit/schemas";
import type { GraphSnapshot } from "./build.js";

export interface GraphTombstone {
  readonly id: string;
  readonly kind: "node" | "edge";
  readonly revision: string;
  readonly reason: "deleted" | "replaced" | "incident";
}
export interface GraphTransactionState extends GraphSnapshot {
  readonly tombstones: readonly GraphTombstone[];
}
export interface GraphTransaction {
  readonly revision: string;
  readonly replaceNodes?: readonly GraphNode[];
  readonly replaceEdges?: readonly GraphEdge[];
  readonly deleteNodeIds?: readonly string[];
  readonly deleteEdgeIds?: readonly string[];
  readonly beforeCommit?: () => void;
}
const byId = <T extends { readonly id: string }>(a: T, b: T) =>
  a.id.localeCompare(b.id);
export function withGraphTransactions(
  snapshot: GraphSnapshot,
): GraphTransactionState {
  return { ...snapshot, tombstones: [] };
}
export function applyGraphTransaction(
  current: GraphTransactionState,
  transaction: GraphTransaction,
): GraphTransactionState {
  const deleteNodes = new Set(transaction.deleteNodeIds ?? []);
  const deleteEdges = new Set(transaction.deleteEdgeIds ?? []);
  for (const edge of current.edges)
    if (
      deleteNodes.has(edge.sourceId) ||
      (edge.targetId && deleteNodes.has(edge.targetId))
    )
      deleteEdges.add(edge.id);
  const replacementNodes = new Map(
    (transaction.replaceNodes ?? []).map((node) => [node.id, node]),
  );
  const replacementEdges = new Map(
    (transaction.replaceEdges ?? []).map((edge) => [edge.id, edge]),
  );
  const tombstones = [...current.tombstones];
  for (const id of [...deleteNodes].sort())
    tombstones.push({
      id,
      kind: "node",
      revision: transaction.revision,
      reason: replacementNodes.has(id) ? "replaced" : "deleted",
    });
  for (const id of [...deleteEdges].sort())
    tombstones.push({
      id,
      kind: "edge",
      revision: transaction.revision,
      reason: "incident",
    });
  const nodes = current.nodes.filter(
    (node) => !deleteNodes.has(node.id) && !replacementNodes.has(node.id),
  );
  const edges = current.edges.filter(
    (edge) => !deleteEdges.has(edge.id) && !replacementEdges.has(edge.id),
  );
  nodes.push(...replacementNodes.values());
  edges.push(...replacementEdges.values());
  const nodeIds = new Set(nodes.map((node) => node.id));
  if (
    edges.some(
      (edge) =>
        !nodeIds.has(edge.sourceId) ||
        (edge.targetId !== null && !nodeIds.has(edge.targetId)),
    )
  )
    throw new Error("Graph transaction would create a dangling edge");
  transaction.beforeCommit?.();
  return {
    ...current,
    nodes: nodes.sort(byId),
    edges: edges.sort(byId),
    tombstones: tombstones.sort(
      (a, b) =>
        a.id.localeCompare(b.id) || a.revision.localeCompare(b.revision),
    ),
  };
}

