import { LOCAL_INDEX_SCHEMA_VERSION } from "@fuzit/schemas";

export type MigrationAction =
  | { readonly kind: "compatible"; readonly schemaVersion: number }
  | {
      readonly kind: "migrated";
      readonly fromVersion: number;
      readonly toVersion: number;
    }
  | {
      readonly kind: "rebuild-required";
      readonly reason: string;
      readonly fromVersion: number | null;
    }
  | {
      readonly kind: "unsupported-future-version";
      readonly schemaVersion: number;
      readonly reason: string;
    };

export interface MigrationEvaluationOptions {
  readonly storedSchemaVersion: number | null;
  readonly supportedVersions?: readonly number[] | undefined;
}

export function evaluateIndexMigration(
  options: MigrationEvaluationOptions,
): MigrationAction {
  const {
    storedSchemaVersion,
    supportedVersions = [LOCAL_INDEX_SCHEMA_VERSION],
  } = options;

  if (storedSchemaVersion === null || typeof storedSchemaVersion !== "number") {
    return {
      kind: "rebuild-required",
      reason: "Missing or invalid schema version in index metadata",
      fromVersion: null,
    };
  }

  if (storedSchemaVersion === LOCAL_INDEX_SCHEMA_VERSION) {
    return {
      kind: "compatible",
      schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
    };
  }

  if (storedSchemaVersion > LOCAL_INDEX_SCHEMA_VERSION) {
    return {
      kind: "unsupported-future-version",
      schemaVersion: storedSchemaVersion,
      reason: `Index schema version ${storedSchemaVersion} is newer than maximum supported version ${LOCAL_INDEX_SCHEMA_VERSION}. Writing or converting this format is refused for safety.`,
    };
  }

  if (supportedVersions.includes(storedSchemaVersion)) {
    return {
      kind: "migrated",
      fromVersion: storedSchemaVersion,
      toVersion: LOCAL_INDEX_SCHEMA_VERSION,
    };
  }

  return {
    kind: "rebuild-required",
    reason: `Schema version ${storedSchemaVersion} is obsolete and cannot be migrated automatically; rebuild is required.`,
    fromVersion: storedSchemaVersion,
  };
}

import { lstat, readdir, rm, stat } from "node:fs/promises";
import { join, resolve } from "node:path";

import { verifyLocalIndex } from "../verification/verify.js";
import type { IndexSemanticVersions } from "../invalidation/evaluate.js";

export interface CorruptionRecoveryOptions {
  readonly indexPath: string;
  readonly expectedRepositoryId: string;
  readonly currentSemanticState?: IndexSemanticVersions | undefined;
  readonly maxStaleLockAgeMs?: number | undefined; // default 30000 ms (30s)
}

export interface CorruptionRecoveryResult {
  readonly recovered: boolean;
  readonly actionTaken:
    | "none"
    | "cleaned-stale-lock"
    | "cleaned-staging-files"
    | "quarantined-corrupt-index"
    | "rebuilt-index";
  readonly details: string;
  readonly quarantinedPath?: string;
}

export async function recoverCorruptIndex(
  options: CorruptionRecoveryOptions,
): Promise<CorruptionRecoveryResult> {
  const {
    indexPath,
    expectedRepositoryId,
    currentSemanticState,
    maxStaleLockAgeMs = 30000,
  } = options;

  // Verify path confinement: index path must be within safe parent structure and not symlinked outside
  try {
    const lstatResult = await lstat(indexPath);
    if (lstatResult.isSymbolicLink()) {
      return {
        recovered: false,
        actionTaken: "none",
        details:
          "Refusing to operate on symlinked index directory for security",
      };
    }
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return {
        recovered: true,
        actionTaken: "none",
        details: "Index directory absent, no recovery needed",
      };
    }
  }

  // 1. Clean abandoned staging files and temporary files first
  let cleanedStaging = false;
  const transactionsDir = join(indexPath, "transactions");
  try {
    const entries = await readdir(transactionsDir);
    for (const entry of entries) {
      if (entry.endsWith(".staged.json") || entry.endsWith(".tmp")) {
        await rm(join(transactionsDir, entry), { force: true });
        cleanedStaging = true;
      }
    }
  } catch {
    // ignore if transactions dir does not exist
  }

  try {
    const rootEntries = await readdir(indexPath);
    for (const entry of rootEntries) {
      if (entry.endsWith(".tmp")) {
        await rm(join(indexPath, entry), { force: true });
        cleanedStaging = true;
      }
    }
  } catch {
    // ignore
  }

  // 2. Check verification status
  const initialVerification = await verifyLocalIndex({
    indexPath,
    expectedRepositoryId,
    currentSemanticState,
  });

  if (initialVerification.status === "ready") {
    return {
      recovered: true,
      actionTaken: cleanedStaging ? "cleaned-staging-files" : "none",
      details: cleanedStaging
        ? "Cleaned abandoned staging/temporary files; index state restored to ready"
        : "Index is ready and verified intact",
    };
  }

  // Handle stale locks if locked
  if (initialVerification.status === "locked") {
    const lockPath = join(indexPath, "index.lock");
    try {
      const lockStat = await stat(lockPath);
      const ageMs = Date.now() - lockStat.mtimeMs;
      if (ageMs > maxStaleLockAgeMs) {
        await rm(lockPath, { force: true });
        return {
          recovered: true,
          actionTaken: "cleaned-stale-lock",
          details: `Removed stale lock file older than ${maxStaleLockAgeMs}ms`,
        };
      }
    } catch {
      // ignore
    }
  }

  // If index is corrupt, schema-mismatch, repo-mismatch, or incomplete, purge Fuzit-owned index path safely
  if (
    initialVerification.status === "corrupt" ||
    initialVerification.status === "schema-mismatch" ||
    initialVerification.status === "repository-mismatch" ||
    initialVerification.status === "incomplete" ||
    initialVerification.status === "rebuild-required" ||
    initialVerification.status === "stale" ||
    initialVerification.status === "policy-mismatch"
  ) {
    // Enforce path safety: must contain 'fuzit/indexes' in path to prevent deleting unrelated user directories
    const normalized = resolve(indexPath).replace(/\\/g, "/");
    if (!normalized.includes("fuzit/indexes")) {
      return {
        recovered: false,
        actionTaken: "none",
        details:
          "Refusing to purge path that does not match Fuzit index structure",
      };
    }

    await rm(indexPath, { recursive: true, force: true });
    return {
      recovered: true,
      actionTaken: "rebuilt-index",
      details: `Safely purged corrupt/stale index directory (${initialVerification.status}); ready for clean rebuild`,
    };
  }

  return {
    recovered: false,
    actionTaken: "none",
    details: `No recovery action applied for status: ${initialVerification.status}`,
  };
}

export interface FileFingerprint {
  readonly path: string;
  readonly size: number;
  readonly modifiedAtMs: number;
  readonly sha256: string;
  readonly acquisitionState: "complete" | "partial" | "unreadable";
}

export interface ScanFingerprintSet {
  readonly scannerVersion: string;
  readonly configHash: string;
  readonly files: readonly FileFingerprint[];
}

export type FingerprintChange = "unchanged" | "modified" | "deleted" | "new";

export function compareFingerprint(
  previous: FileFingerprint | undefined,
  current: FileFingerprint | undefined,
): FingerprintChange {
  if (!previous) return "new";
  if (!current) return "deleted";
  return previous.sha256 === current.sha256 &&
    previous.size === current.size &&
    previous.modifiedAtMs === current.modifiedAtMs
    ? "unchanged"
    : "modified";
}

export function canReuseScan(
  previous: ScanFingerprintSet,
  current: Pick<ScanFingerprintSet, "scannerVersion" | "configHash">,
): boolean {
  return (
    previous.scannerVersion === current.scannerVersion &&
    previous.configHash === current.configHash
  );
}

export function reconcileFingerprints(
  previous: readonly FileFingerprint[],
  current: readonly FileFingerprint[],
): ReadonlyMap<string, FingerprintChange> {
  const before = new Map(previous.map((file) => [file.path, file]));
  const after = new Map(current.map((file) => [file.path, file]));
  const paths = [...new Set([...before.keys(), ...after.keys()])].sort();
  return new Map(
    paths.map((path) => [
      path,
      compareFingerprint(before.get(path), after.get(path)),
    ]),
  );
}

export async function writeFingerprintSet(
  indexDirectory: string,
  value: ScanFingerprintSet,
): Promise<void> {
  const target = join(indexDirectory, "fingerprints.json");
  const temporary = `${target}.${randomUUID()}.tmp`;
  await writeFile(temporary, `${JSON.stringify(value)}\n`, {
    encoding: "utf8",
    flag: "wx",
    mode: 0o600,
  });
  await rename(temporary, target);
}

export async function readFingerprintSet(
  indexDirectory: string,
): Promise<ScanFingerprintSet | undefined> {
  try {
    return JSON.parse(
      await readFile(join(indexDirectory, "fingerprints.json"), "utf8"),
    ) as ScanFingerprintSet;
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return undefined;
    }
    throw error;
  }
}
import { readFile, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

export {
  canReuseScan,
  compareFingerprint,
  reconcileFingerprints,
  readFingerprintSet,
  writeFingerprintSet,
  type FileFingerprint,
  type FingerprintChange,
  type ScanFingerprintSet,
} from "./fingerprints.js";

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

import {
  canonicalIndexFileRecordSchema,
  serializeIncrementalIndexRecord,
  type IncrementalIndexRecord,
} from "@fuzit/schemas";

export type CanonicalIndexFileRecord = Extract<
  IncrementalIndexRecord,
  { readonly recordType: "file" }
>;

const FILE_RECORDS_FILE = "files.jsonl";

function compareUtf8(left: string, right: string): number {
  return Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"));
}

function canonicalizeRecords(
  records: readonly CanonicalIndexFileRecord[],
): CanonicalIndexFileRecord[] {
  const validated = records.map((record) =>
    canonicalIndexFileRecordSchema.parse(record),
  );
  validated.sort((left, right) => compareUtf8(left.path, right.path));

  for (let index = 1; index < validated.length; index += 1) {
    if (validated[index - 1]?.path === validated[index]?.path) {
      throw new Error(
        `Duplicate canonical file record: ${validated[index]?.path}`,
      );
    }
  }

  return validated;
}

export async function writeCanonicalFileRecords(
  directory: string,
  records: readonly CanonicalIndexFileRecord[],
): Promise<void> {
  const canonical = canonicalizeRecords(records);
  const serialized = canonical.map(serializeIncrementalIndexRecord).join("");
  await mkdir(directory, { recursive: true, mode: 0o700 });

  const target = join(directory, FILE_RECORDS_FILE);
  const temporary = join(directory, `${FILE_RECORDS_FILE}.${randomUUID()}.tmp`);
  try {
    await writeFile(temporary, serialized, {
      encoding: "utf8",
      flag: "wx",
      mode: 0o600,
    });
    await rename(temporary, target);
  } finally {
    await rm(temporary, { force: true });
  }
}

export async function readCanonicalFileRecords(
  directory: string,
): Promise<CanonicalIndexFileRecord[]> {
  let serialized: string;
  try {
    serialized = await readFile(join(directory, FILE_RECORDS_FILE), "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return [];
    }
    throw error;
  }

  const records = serialized
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) => canonicalIndexFileRecordSchema.parse(JSON.parse(line)));
  return canonicalizeRecords(records);
}

export {
  assertIndexLocation,
  inspectLocalIndex,
  openLocalIndex,
  readLocalIndexSemanticState,
  writeLocalIndexSemanticState,
  type LocalIndexMetadata,
  type LocalIndexSemanticState,
  type LocalIndexStore,
} from "./store.js";
export {
  readCanonicalFileRecords,
  writeCanonicalFileRecords,
  type CanonicalIndexFileRecord,
} from "./file-record-store.js";
export {
  commitAtomicIndexTransaction,
  readCommittedIndexState,
  type AtomicIndexTransactionInput,
  type AtomicIndexTransactionOptions,
  type CommittedIndexState,
  type IndexTransactionBoundary,
  type DurableIndexTombstone,
  type IndexRemoval,
} from "./transaction-store.js";

import {
  mkdir,
  open,
  readFile,
  rename,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import { dirname, join } from "node:path";
import { randomUUID } from "node:crypto";

import { LOCAL_INDEX_SCHEMA_VERSION } from "@fuzit/schemas";
import type { IndexIdentitySet } from "../invalidation/identities.js";

export interface LocalIndexMetadata {
  readonly schemaVersion: typeof LOCAL_INDEX_SCHEMA_VERSION;
  readonly repositoryId: string;
  readonly createdAt: string;
}

export interface LocalIndexStore {
  readonly directory: string;
  readonly metadata: LocalIndexMetadata;
}

export interface LocalIndexSemanticState {
  readonly contentHash: string;
  readonly configHash: string;
  readonly scannerVersion: string;
  readonly parserVersion: string;
  readonly securityPolicyVersion: string;
  readonly schemaVersion: number;
  readonly identities?: IndexIdentitySet;
}

const METADATA_FILE = "index.json";
const LOCK_FILE = "index.lock";
const SEMANTIC_FILE = "semantic.json";

function parseMetadata(raw: string): LocalIndexMetadata {
  const value = JSON.parse(raw) as Partial<LocalIndexMetadata>;
  if (
    value.schemaVersion !== LOCAL_INDEX_SCHEMA_VERSION ||
    typeof value.repositoryId !== "string" ||
    typeof value.createdAt !== "string"
  ) {
    throw new Error("Corrupt or incompatible local index metadata.");
  }
  return value as LocalIndexMetadata;
}

export async function openLocalIndex(
  directory: string,
  repositoryId: string,
): Promise<LocalIndexStore> {
  await mkdir(directory, { recursive: true, mode: 0o700 });
  const metadataPath = join(directory, METADATA_FILE);

  try {
    const metadata = parseMetadata(await readFile(metadataPath, "utf8"));
    if (metadata.repositoryId !== repositoryId) {
      throw new Error("Local index belongs to a different repository.");
    }
    return { directory, metadata };
  } catch (error) {
    if (!(
      error instanceof Error &&
      "code" in error &&
      error.code === "ENOENT"
    )) {
      throw error;
    }
  }

  const lockPath = join(directory, LOCK_FILE);
  let lock;
  try {
    lock = await open(lockPath, "wx", 0o600);
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "EEXIST") {
      throw new Error("Local index is locked by another writer.", {
        cause: error,
      });
    }
    throw error;
  }

  const temporaryPath = join(directory, `${METADATA_FILE}.${randomUUID()}.tmp`);
  try {
    const metadata: LocalIndexMetadata = {
      schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
      repositoryId,
      createdAt: new Date().toISOString(),
    };
    await writeFile(temporaryPath, `${JSON.stringify(metadata)}\n`, {
      encoding: "utf8",
      flag: "wx",
      mode: 0o600,
    });
    await rename(temporaryPath, metadataPath);
    return { directory, metadata };
  } finally {
    await lock.close();
    await rm(lockPath, { force: true });
    await rm(temporaryPath, { force: true });
  }
}

export async function assertIndexLocation(directory: string): Promise<void> {
  const parent = dirname(directory);
  const parentStat = await stat(parent);
  if (!parentStat.isDirectory()) {
    throw new Error("Local index parent is not a directory.");
  }
}

export async function inspectLocalIndex(
  directory: string,
  repositoryId: string,
): Promise<
  | { readonly kind: "absent" }
  | { readonly kind: "locked"; readonly lockOwner: string }
  | { readonly kind: "schema-mismatch"; readonly schemaVersion: number }
  | { readonly kind: "repository-mismatch" }
  | { readonly kind: "corrupt" }
  | { readonly kind: "ready"; readonly schemaVersion: number }
> {
  try {
    await stat(join(directory, LOCK_FILE));
    return { kind: "locked", lockOwner: "local-index-writer" };
  } catch (error) {
    if (!(error instanceof Error && "code" in error && error.code === "ENOENT"))
      return { kind: "corrupt" };
  }
  try {
    const raw = JSON.parse(
      await readFile(join(directory, METADATA_FILE), "utf8"),
    ) as Partial<LocalIndexMetadata>;
    if (typeof raw.schemaVersion !== "number") return { kind: "corrupt" };
    if (raw.schemaVersion !== LOCAL_INDEX_SCHEMA_VERSION)
      return { kind: "schema-mismatch", schemaVersion: raw.schemaVersion };
    if (raw.repositoryId !== repositoryId)
      return { kind: "repository-mismatch" };
    if (typeof raw.createdAt !== "string") return { kind: "corrupt" };
    return { kind: "ready", schemaVersion: raw.schemaVersion };
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return { kind: "absent" };
    return { kind: "corrupt" };
  }
}

export async function writeLocalIndexSemanticState(
  directory: string,
  state: LocalIndexSemanticState,
): Promise<void> {
  const target = join(directory, SEMANTIC_FILE);
  const temporary = join(directory, `${SEMANTIC_FILE}.${randomUUID()}.tmp`);
  await writeFile(temporary, `${JSON.stringify(state)}\n`, {
    encoding: "utf8",
    flag: "wx",
    mode: 0o600,
  });
  await rename(temporary, target);
}

export async function readLocalIndexSemanticState(
  directory: string,
): Promise<LocalIndexSemanticState | undefined> {
  try {
    return JSON.parse(
      await readFile(join(directory, SEMANTIC_FILE), "utf8"),
    ) as LocalIndexSemanticState;
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return undefined;
    throw error;
  }
}

import { createHash } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

import {
  canonicalIndexFileRecordSchema,
  incrementalTombstoneSchema,
  incrementalTransactionSchema,
} from "@fuzit/schemas";

import type { CanonicalIndexFileRecord } from "./file-record-store.js";
import type { LocalIndexSemanticState } from "./store.js";

const COMMITTED_STATE_FILE = "committed-state.json";
const STAGING_DIRECTORY = "transactions";

export type IndexTransactionBoundary =
  | "before-stage"
  | "after-stage"
  | "after-validation"
  | "before-commit"
  | "after-commit";

export interface AtomicIndexTransactionInput {
  readonly transactionId: string;
  readonly repositoryId: string;
  readonly startedAt: string;
  readonly completedAt: string;
  readonly records: readonly CanonicalIndexFileRecord[];
  readonly semanticState: LocalIndexSemanticState;
  readonly removals?: readonly IndexRemoval[];
}

export interface IndexRemoval {
  readonly path: string;
  readonly reason: "deleted" | "renamed" | "excluded" | "unavailable";
  readonly deletionBasis:
    "canonical-state-diff" | "verified-filesystem" | "policy-change";
  readonly invalidationIdentity: string;
  readonly renamedTo?: string;
}

export type DurableIndexTombstone = ReturnType<typeof createTombstone>;

export interface CommittedIndexState {
  readonly transaction: {
    readonly recordType: "transaction";
    readonly schemaVersion: 1;
    readonly transactionId: string;
    readonly repositoryId: string;
    readonly state: "committed";
    readonly startedAt: string;
    readonly completedAt: string;
    readonly changes: readonly {
      readonly operation: "upsert";
      readonly path: string;
    }[];
  };
  readonly records: readonly CanonicalIndexFileRecord[];
  readonly tombstones: readonly DurableIndexTombstone[];
  readonly semanticState: LocalIndexSemanticState;
}

export interface AtomicIndexTransactionOptions {
  readonly onBoundary?: (
    boundary: IndexTransactionBoundary,
  ) => void | Promise<void>;
}

function compareUtf8(left: string, right: string): number {
  return Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"));
}

function createTombstone(
  removal: IndexRemoval,
  previousContentHash: string | null,
  deletedAt: string,
) {
  const stableIdentity = JSON.stringify({
    path: removal.path,
    previousContentHash,
    reason: removal.reason,
    deletionBasis: removal.deletionBasis,
    invalidationIdentity: removal.invalidationIdentity,
    renamedTo: removal.renamedTo ?? null,
  });
  return incrementalTombstoneSchema.parse({
    recordType: "tombstone",
    schemaVersion: 1,
    tombstoneId: `sha256:${createHash("sha256")
      .update(stableIdentity, "utf8")
      .digest("hex")}`,
    path: removal.path,
    previousContentHash,
    deletedAt,
    reason: removal.reason,
    deletionBasis: removal.deletionBasis,
    invalidationIdentity: removal.invalidationIdentity,
    renamedTo: removal.renamedTo ?? null,
    invalidatedRecordTypes: ["file", "analysis", "graph"],
  });
}

function validateSemanticState(
  value: LocalIndexSemanticState,
): LocalIndexSemanticState {
  for (const key of [
    "contentHash",
    "configHash",
    "scannerVersion",
    "parserVersion",
    "securityPolicyVersion",
  ] as const) {
    if (typeof value[key] !== "string" || value[key].length === 0) {
      throw new Error(`Invalid semantic state field: ${key}`);
    }
  }
  if (!Number.isInteger(value.schemaVersion) || value.schemaVersion < 1) {
    throw new Error("Invalid semantic state field: schemaVersion");
  }
  return value;
}

function validateCommittedState(value: unknown): CommittedIndexState {
  if (value === null || typeof value !== "object") {
    throw new Error("Invalid committed index state.");
  }
  const candidate = value as Partial<CommittedIndexState>;
  const transaction = incrementalTransactionSchema.parse(candidate.transaction);
  if (transaction.state !== "committed") {
    throw new Error(
      "Committed index state must contain a committed transaction.",
    );
  }
  if (!Array.isArray(candidate.records)) {
    throw new Error("Committed index state records must be an array.");
  }
  const records = candidate.records
    .map((record) => canonicalIndexFileRecordSchema.parse(record))
    .sort((left, right) => compareUtf8(left.path, right.path));
  if (new Set(records.map(({ path }) => path)).size !== records.length) {
    throw new Error("Committed index state contains duplicate paths.");
  }
  const tombstones = (candidate.tombstones ?? [])
    .map((tombstone) => incrementalTombstoneSchema.parse(tombstone))
    .sort((left, right) => compareUtf8(left.path, right.path));
  return {
    transaction: transaction as CommittedIndexState["transaction"],
    records,
    tombstones: tombstones as DurableIndexTombstone[],
    semanticState: validateSemanticState(
      candidate.semanticState as LocalIndexSemanticState,
    ),
  };
}

export async function commitAtomicIndexTransaction(
  directory: string,
  input: AtomicIndexTransactionInput,
  options: AtomicIndexTransactionOptions = {},
): Promise<CommittedIndexState> {
  const notify = async (boundary: IndexTransactionBoundary) =>
    options.onBoundary?.(boundary);
  await notify("before-stage");
  await mkdir(join(directory, STAGING_DIRECTORY), {
    recursive: true,
    mode: 0o700,
  });

  const records = [...input.records].sort((left, right) =>
    compareUtf8(left.path, right.path),
  );
  const previous = await readCommittedIndexState(directory);
  const previousRecords = new Map(
    previous?.records.map((record) => [record.path, record]) ?? [],
  );
  const newTombstones = (input.removals ?? []).map((removal) =>
    createTombstone(
      removal,
      previousRecords.get(removal.path)?.contentHash ?? null,
      input.completedAt,
    ),
  );
  const tombstones = [...(previous?.tombstones ?? []), ...newTombstones].sort(
    (left, right) => compareUtf8(left.path, right.path),
  );
  const stagedState = validateCommittedState({
    transaction: {
      recordType: "transaction",
      schemaVersion: 1,
      transactionId: input.transactionId,
      repositoryId: input.repositoryId,
      state: "committed",
      startedAt: input.startedAt,
      completedAt: input.completedAt,
      changes: [
        ...records.map(({ path }) => ({ operation: "upsert" as const, path })),
        ...newTombstones.map(({ path }) => ({
          operation: "tombstone" as const,
          path,
        })),
      ],
    },
    records,
    tombstones,
    semanticState: input.semanticState,
  });
  const stagedPath = join(
    directory,
    STAGING_DIRECTORY,
    `${input.transactionId}.staged.json`,
  );
  const targetPath = join(directory, COMMITTED_STATE_FILE);

  try {
    await writeFile(stagedPath, `${JSON.stringify(stagedState)}\n`, {
      encoding: "utf8",
      flag: "wx",
      mode: 0o600,
    });
    await notify("after-stage");
    validateCommittedState(JSON.parse(await readFile(stagedPath, "utf8")));
    await notify("after-validation");
    await notify("before-commit");
    await rename(stagedPath, targetPath);
    await notify("after-commit");
    return stagedState;
  } finally {
    await rm(stagedPath, { force: true });
  }
}

export async function readCommittedIndexState(
  directory: string,
): Promise<CommittedIndexState | undefined> {
  try {
    return validateCommittedState(
      JSON.parse(await readFile(join(directory, COMMITTED_STATE_FILE), "utf8")),
    );
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return undefined;
    }
    throw error;
  }
}

import { readFile, stat } from "node:fs/promises";
import { join } from "node:path";

import { LOCAL_INDEX_SCHEMA_VERSION } from "@fuzit/schemas";
import {
  evaluateInvalidation,
  type IndexSemanticVersions,
} from "../invalidation/evaluate.js";

export type IndexVerificationStatusKind =
  | "ready"
  | "stale"
  | "incomplete"
  | "corrupt"
  | "schema-mismatch"
  | "repository-mismatch"
  | "policy-mismatch"
  | "rebuild-required"
  | "absent"
  | "locked";

export interface IndexVerificationResult {
  readonly status: IndexVerificationStatusKind;
  readonly valid: boolean;
  readonly rebuildRequired: boolean;
  readonly reasons: readonly string[];
  readonly details: {
    readonly schemaVersion: number | null;
    readonly repositoryId: string | null;
    readonly lockOwner: string | null;
  };
}

export interface VerifyIndexOptions {
  readonly indexPath: string;
  readonly expectedRepositoryId: string;
  readonly currentSemanticState?: IndexSemanticVersions | undefined;
}

export async function verifyLocalIndex(
  options: VerifyIndexOptions,
): Promise<IndexVerificationResult> {
  const { indexPath, expectedRepositoryId, currentSemanticState } = options;

  // 1. Check lock
  try {
    await stat(join(indexPath, "index.lock"));
    return {
      status: "locked",
      valid: false,
      rebuildRequired: false,
      reasons: ["index is locked by another process"],
      details: {
        schemaVersion: LOCAL_INDEX_SCHEMA_VERSION,
        repositoryId: expectedRepositoryId,
        lockOwner: "local-index-writer",
      },
    };
  } catch (error) {
    if (!(
      error instanceof Error &&
      "code" in error &&
      error.code === "ENOENT"
    )) {
      return {
        status: "corrupt",
        valid: false,
        rebuildRequired: true,
        reasons: ["unable to inspect index lock file"],
        details: { schemaVersion: null, repositoryId: null, lockOwner: null },
      };
    }
  }

  // 2. Read index.json metadata
  let metadataRaw: string;
  try {
    metadataRaw = await readFile(join(indexPath, "index.json"), "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return {
        status: "absent",
        valid: false,
        rebuildRequired: true,
        reasons: ["index metadata file absent"],
        details: { schemaVersion: null, repositoryId: null, lockOwner: null },
      };
    }
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["unable to read index metadata file"],
      details: { schemaVersion: null, repositoryId: null, lockOwner: null },
    };
  }

  let metadata: {
    schemaVersion?: unknown;
    repositoryId?: unknown;
    createdAt?: unknown;
  };
  try {
    metadata = JSON.parse(metadataRaw);
  } catch {
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["index metadata file is not valid JSON"],
      details: { schemaVersion: null, repositoryId: null, lockOwner: null },
    };
  }

  if (
    typeof metadata.schemaVersion !== "number" ||
    typeof metadata.repositoryId !== "string" ||
    typeof metadata.createdAt !== "string"
  ) {
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["index metadata contains malformed or missing fields"],
      details: {
        schemaVersion:
          typeof metadata.schemaVersion === "number"
            ? metadata.schemaVersion
            : null,
        repositoryId:
          typeof metadata.repositoryId === "string"
            ? metadata.repositoryId
            : null,
        lockOwner: null,
      },
    };
  }

  const schemaVersion = metadata.schemaVersion;
  const repositoryId = metadata.repositoryId;

  if (schemaVersion !== LOCAL_INDEX_SCHEMA_VERSION) {
    return {
      status: "schema-mismatch",
      valid: false,
      rebuildRequired: true,
      reasons: [
        `index schema version mismatch: stored ${schemaVersion}, expected ${LOCAL_INDEX_SCHEMA_VERSION}`,
      ],
      details: { schemaVersion, repositoryId, lockOwner: null },
    };
  }

  if (repositoryId !== expectedRepositoryId) {
    return {
      status: "repository-mismatch",
      valid: false,
      rebuildRequired: true,
      reasons: ["index repository identity mismatch"],
      details: { schemaVersion, repositoryId, lockOwner: null },
    };
  }

  // 3. Read semantic.json state
  let semanticRaw: string;
  try {
    semanticRaw = await readFile(join(indexPath, "semantic.json"), "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return {
        status: "incomplete",
        valid: false,
        rebuildRequired: true,
        reasons: ["semantic state file absent"],
        details: { schemaVersion, repositoryId, lockOwner: null },
      };
    }
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["unable to read semantic state file"],
      details: { schemaVersion, repositoryId, lockOwner: null },
    };
  }

  let storedSemanticState: IndexSemanticVersions;
  try {
    storedSemanticState = JSON.parse(semanticRaw);
  } catch {
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["semantic state file is not valid JSON"],
      details: { schemaVersion, repositoryId, lockOwner: null },
    };
  }

  // Check required fields in stored semantic state
  if (
    !storedSemanticState ||
    typeof storedSemanticState.contentHash !== "string" ||
    typeof storedSemanticState.configHash !== "string" ||
    typeof storedSemanticState.scannerVersion !== "string" ||
    typeof storedSemanticState.parserVersion !== "string" ||
    typeof storedSemanticState.securityPolicyVersion !== "string" ||
    typeof storedSemanticState.schemaVersion !== "number"
  ) {
    return {
      status: "corrupt",
      valid: false,
      rebuildRequired: true,
      reasons: ["semantic state contains malformed or missing fields"],
      details: { schemaVersion, repositoryId, lockOwner: null },
    };
  }

  // 4. Compare with current repository state if provided
  if (currentSemanticState) {
    const invalidation = evaluateInvalidation(
      storedSemanticState,
      currentSemanticState,
    );
    if (!invalidation.valid) {
      let status: IndexVerificationStatusKind = "rebuild-required";
      if (
        invalidation.reasons.some(
          (r) => r.includes("securityPolicy") || r.includes("policy"),
        )
      ) {
        status = "policy-mismatch";
      } else if (invalidation.reasons.some((r) => r.includes("contentHash"))) {
        status = "stale";
      }

      return {
        status,
        valid: false,
        rebuildRequired: invalidation.action === "rebuild",
        reasons: invalidation.reasons,
        details: { schemaVersion, repositoryId, lockOwner: null },
      };
    }
  }

  return {
    status: "ready",
    valid: true,
    rebuildRequired: false,
    reasons: [],
    details: { schemaVersion, repositoryId, lockOwner: null },
  };
}

import { accessSync, constants, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import {
  createRepositoryId,
  getLocalIndexPath,
  getLocalIndexStatus,
} from "../src/index.js";

describe("local index contract", () => {
  it("separates multiple repositories without exposing their paths", () => {
    const cacheHome = join(tmpdir(), "fuzit-contract");
    const first = getLocalIndexPath({
      cacheHome,
      repositoryFingerprint: "git:origin.example/alpha",
    });
    const second = getLocalIndexPath({
      cacheHome,
      repositoryFingerprint: "git:origin.example/beta",
    });

    expect(first).not.toBe(second);
    expect(first).not.toContain("alpha");
    expect(second).not.toContain("beta");
  });

  it("keeps identity stable when a repository moves", () => {
    const fingerprint = "git:origin.example/project";
    expect(createRepositoryId(fingerprint)).toBe(
      createRepositoryId(fingerprint),
    );
  });

  it("requires rebuild on schema mismatch", () => {
    const status = getLocalIndexStatus(
      {
        cacheHome: join(tmpdir(), "fuzit-contract"),
        repositoryFingerprint: "git:origin.example/project",
      },
      { kind: "ready", schemaVersion: 2 },
    );

    expect(status).toMatchObject({
      schemaVersion: 1,
      state: "schema-mismatch",
      rebuildRequired: true,
    });
  });

  it("does not write while resolving a path in a read-only home", () => {
    const readOnlyHome = mkdtempSync(join(tmpdir(), "fuzit-read-only-"));
    accessSync(readOnlyHome, constants.R_OK);

    const path = getLocalIndexPath({
      cacheHome: readOnlyHome,
      repositoryFingerprint: "git:origin.example/project",
    });

    expect(path).toContain(readOnlyHome);
    expect(() => accessSync(path)).toThrow();
  });

  it("reports privacy-safe repository identifiers", () => {
    const secretPath = "C:\\Users\\private-user\\secret-project";
    const status = getLocalIndexStatus({
      cacheHome: join(tmpdir(), "fuzit-contract"),
      repositoryFingerprint: `git:${secretPath}`,
    });

    expect(status.repositoryId).toMatch(/^sha256:[a-f0-9]{64}$/);
    expect(status.path).not.toContain("private-user");
    expect(JSON.stringify(status)).not.toContain(secretPath);
  });
});

import { describe, expect, it } from "vitest";

import {
  canReuseScan,
  reconcileFingerprints,
  type FileFingerprint,
} from "../src/index.js";

const file = (
  path: string,
  sha256 = "a",
  modifiedAtMs = 1,
): FileFingerprint => ({
  path,
  sha256,
  modifiedAtMs,
  size: 1,
  acquisitionState: "complete",
});

describe("file fingerprint repository", () => {
  it("classifies unchanged and modified files", () => {
    expect(reconcileFingerprints([file("a")], [file("a")]).get("a")).toBe(
      "unchanged",
    );
    expect(
      reconcileFingerprints([file("a")], [file("a", "b", 2)]).get("a"),
    ).toBe("modified");
  });

  it("classifies deleted files", () => {
    expect(reconcileFingerprints([file("a")], []).get("a")).toBe("deleted");
  });

  it("treats a rename as delete plus new", () => {
    expect([...reconcileFingerprints([file("old")], [file("new")])]).toEqual([
      ["new", "new"],
      ["old", "deleted"],
    ]);
  });

  it("invalidates reuse on config change", () => {
    expect(
      canReuseScan(
        { scannerVersion: "1", configHash: "a", files: [] },
        { scannerVersion: "1", configHash: "b" },
      ),
    ).toBe(false);
  });

  it("invalidates reuse on scanner version change", () => {
    expect(
      canReuseScan(
        { scannerVersion: "1", configHash: "a", files: [] },
        { scannerVersion: "2", configHash: "a" },
      ),
    ).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

import { describePurgeScope, evaluateInvalidation } from "../src/index.js";

const version = {
  contentHash: "content",
  configHash: "config",
  scannerVersion: "scanner",
  parserVersion: "parser",
  securityPolicyVersion: "policy",
  schemaVersion: 1,
};

describe("index invalidation", () => {
  for (const [name, change] of [
    ["version change", { scannerVersion: "scanner-2" }],
    ["config change", { configHash: "config-2" }],
    ["policy change", { securityPolicyVersion: "policy-2" }],
  ] as const) {
    it(name, () => {
      expect(
        evaluateInvalidation(version, { ...version, ...change }),
      ).toMatchObject({
        valid: false,
        action: "rebuild",
        affectedRecordTypes: ["file", "analysis", "graph"],
      });
    });
  }
  it("invalidates corruption", () => {
    expect(
      evaluateInvalidation(version, version, { corrupt: true }).valid,
    ).toBe(false);
  });
  it("gives concurrent rebuild callers the same deterministic decision", () => {
    expect(evaluateInvalidation(version, version)).toEqual(
      evaluateInvalidation(version, version),
    );
  });
  it("restricts purge scope to the exact owned directory", () => {
    expect(describePurgeScope("/cache/repo", "/cache").allowed).toBe(false);
    expect(describePurgeScope("/cache/repo", "/cache/repo").allowed).toBe(true);
  });
});

import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { openLocalIndex } from "../src/index.js";

async function location(): Promise<string> {
  return join(await mkdtemp(join(tmpdir(), "fuzit-index-")), "index");
}

describe("atomic local index storage", () => {
  it("allows concurrent opens to observe one initialized index", async () => {
    const directory = await location();
    const outcomes = await Promise.allSettled([
      openLocalIndex(directory, "repo"),
      openLocalIndex(directory, "repo"),
    ]);
    expect(outcomes.some((outcome) => outcome.status === "fulfilled")).toBe(
      true,
    );
    expect(await openLocalIndex(directory, "repo")).toMatchObject({
      metadata: { schemaVersion: 1, repositoryId: "repo" },
    });
  });

  it("ignores a crash-left temporary file", async () => {
    const directory = await location();
    await openLocalIndex(directory, "repo");
    await writeFile(join(directory, "index.json.crash.tmp"), "partial");
    expect(
      (await openLocalIndex(directory, "repo")).metadata.repositoryId,
    ).toBe("repo");
  });

  it("creates the versioned schema atomically", async () => {
    const directory = await location();
    await openLocalIndex(directory, "repo");
    expect(
      JSON.parse(await readFile(join(directory, "index.json"), "utf8")),
    ).toMatchObject({ schemaVersion: 1, repositoryId: "repo" });
  });

  it("fails safely when the location cannot be created", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-index-blocked-"));
    const blocker = join(root, "file");
    await writeFile(blocker, "not a directory");
    await expect(
      openLocalIndex(join(blocker, "index"), "repo"),
    ).rejects.toThrow();
  });

  it("detects corrupt metadata without replacing it", async () => {
    const directory = await location();
    await openLocalIndex(directory, "repo");
    await writeFile(join(directory, "index.json"), "{bad json");
    await expect(openLocalIndex(directory, "repo")).rejects.toThrow();
    expect(await readFile(join(directory, "index.json"), "utf8")).toBe(
      "{bad json",
    );
  });
});

