import {
  PLUGIN_MANIFEST_SCHEMA_VERSION,
  PLUGIN_PROTOCOL_VERSION,
  pluginCapabilitySchema,
  type PluginManifest,
} from "@fuzit/plugin-sdk";

export interface CompatibilityValidationOptions {
  readonly hostVersion?: string;
  readonly supportedProtocol?: string;
}

export interface CompatibilityValidationResult {
  readonly compatible: boolean;
  readonly reasons: readonly string[];
}

/**
 * Checks if a semver string satisfies a version requirement range string.
 */
export function satisfiesSemver(version: string, range: string): boolean {
  const cleanRange = range.trim();
  if (cleanRange === "*" || cleanRange === "") return true;

  const versionMatch = /^(\d+)\.(\d+)\.(\d+)/.exec(version.trim());
  if (!versionMatch) return false;

  const vMajor = parseInt(versionMatch[1] ?? "0", 10);
  const vMinor = parseInt(versionMatch[2] ?? "0", 10);
  const vPatch = parseInt(versionMatch[3] ?? "0", 10);

  if (cleanRange.startsWith("^")) {
    const rMatch = /^\^\s*(\d+)\.(\d+)\.(\d+)/.exec(cleanRange);
    if (!rMatch) return false;
    const rMajor = parseInt(rMatch[1] ?? "0", 10);
    const rMinor = parseInt(rMatch[2] ?? "0", 10);

    if (vMajor !== rMajor) return false;
    if (vMinor < rMinor) return false;
    return true;
  }

  if (cleanRange.startsWith("~")) {
    const rMatch = /^~\s*(\d+)\.(\d+)\.(\d+)/.exec(cleanRange);
    if (!rMatch) return false;
    const rMajor = parseInt(rMatch[1] ?? "0", 10);
    const rMinor = parseInt(rMatch[2] ?? "0", 10);

    if (vMajor !== rMajor || vMinor !== rMinor) return false;
    return true;
  }

  if (cleanRange.startsWith(">=")) {
    const rMatch = /^>=\s*(\d+)\.(\d+)\.(\d+)/.exec(cleanRange);
    if (!rMatch) return false;
    const rMajor = parseInt(rMatch[1] ?? "0", 10);
    const rMinor = parseInt(rMatch[2] ?? "0", 10);
    const rPatch = parseInt(rMatch[3] ?? "0", 10);

    if (vMajor > rMajor) return true;
    if (vMajor < rMajor) return false;
    if (vMinor > rMinor) return true;
    if (vMinor < rMinor) return false;
    return vPatch >= rPatch;
  }

  // Exact version match fallback
  const exactMatch = /^(\d+)\.(\d+)\.(\d+)/.exec(cleanRange);
  if (exactMatch) {
    const rMajor = parseInt(exactMatch[1] ?? "0", 10);
    const rMinor = parseInt(exactMatch[2] ?? "0", 10);
    const rPatch = parseInt(exactMatch[3] ?? "0", 10);
    return vMajor === rMajor && vMinor === rMinor && vPatch === rPatch;
  }

  return true;
}

/**
 * Validates protocol, Fuzit host range, capability, schema version, and integrity metadata before activation.
 */
export function validatePluginCompatibility(
  manifest: PluginManifest,
  options?: CompatibilityValidationOptions,
): CompatibilityValidationResult {
  const reasons: string[] = [];
  const hostVersion = options?.hostVersion ?? "1.0.0";
  const supportedProtocol =
    options?.supportedProtocol ?? PLUGIN_PROTOCOL_VERSION;

  // 1. Schema version check
  if (manifest.schemaVersion !== PLUGIN_MANIFEST_SCHEMA_VERSION) {
    reasons.push(
      `Unsupported manifest schemaVersion '${manifest.schemaVersion}'. Expected '${PLUGIN_MANIFEST_SCHEMA_VERSION}'.`,
    );
  }

  // 2. Protocol version check
  if (manifest.protocol !== supportedProtocol) {
    reasons.push(
      `Incompatible plugin protocol '${manifest.protocol}'. Host supports protocol '${supportedProtocol}'.`,
    );
  }

  // 3. Host Fuzit version range check
  if (!satisfiesSemver(hostVersion, manifest.fuzitVersion)) {
    reasons.push(
      `Plugin '${manifest.id}' requires Fuzit version '${manifest.fuzitVersion}', but current host is '${hostVersion}'.`,
    );
  }

  // 4. Capability validation
  const validCapabilities = new Set(pluginCapabilitySchema.options);
  for (const cap of manifest.capabilities) {
    if (!validCapabilities.has(cap)) {
      reasons.push(
        `Plugin declared unknown or unsupported capability '${cap}'.`,
      );
    }
  }

  // 5. Integrity metadata format check if provided
  if (manifest.integrity) {
    if (
      manifest.integrity.checksum &&
      !/^[a-fA-F0-9]{64}$/.test(manifest.integrity.checksum)
    ) {
      reasons.push(
        `Invalid SHA-256 integrity checksum format in plugin manifest: '${manifest.integrity.checksum}'.`,
      );
    }
  }

  return {
    compatible: reasons.length === 0,
    reasons,
  };
}

import { spawn, type ChildProcess } from "node:child_process";
import { readFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import {
  encodePluginFrame,
  parsePluginManifest,
  PLUGIN_PROTOCOL_VERSION,
  PluginFrameDecoder,
  type Diagnostic,
  type PluginCapability,
  type PluginExecuteResponse,
  type PluginHandshakeResponse,
  type PluginManifest,
  type PluginMessage,
} from "@fuzit/plugin-sdk";
import { validatePluginCompatibility } from "./compatibility.js";
import { enforceDiagnosticLimits } from "./resource-limits.js";
import { redactSensitiveText } from "@fuzit/security";

export interface PluginHostOptions {
  readonly pluginDir: string;
  readonly manifestPath?: string;
  readonly nodeExecutable?: string;
  readonly defaultTimeoutMs?: number;
}

export interface PluginExecutionResult {
  readonly success: boolean;
  readonly data?: unknown | undefined;
  readonly error?: string | undefined;
  readonly diagnostics?: readonly Diagnostic[] | undefined;
}

export class PluginClient {
  private process: ChildProcess;
  private decoder: PluginFrameDecoder;
  private manifest: PluginManifest;
  private pendingRequests = new Map<
    string,
    {
      resolve: (value: PluginMessage) => void;
      reject: (reason: Error) => void;
      timer?: NodeJS.Timeout;
    }
  >();
  private requestCounter = 0;
  private isAlive = true;

  constructor(process: ChildProcess, manifest: PluginManifest) {
    this.process = process;
    this.manifest = manifest;
    this.decoder = new PluginFrameDecoder();

    if (this.process.stdout) {
      this.process.stdout.on("data", (chunk: Buffer) => {
        try {
          const messages = this.decoder.push(chunk);
          for (const msg of messages) {
            this.handleIncomingMessage(msg);
          }
        } catch (err) {
          this.handleFatalError(
            new Error(
              `Protocol frame decoding failed: ${err instanceof Error ? err.message : String(err)}`,
              { cause: err },
            ),
          );
        }
      });
    }

    this.process.on("exit", (code, signal) => {
      this.isAlive = false;
      const errorMsg = `Plugin process exited unexpectedly with code ${code ?? "unknown"} (signal: ${signal ?? "none"})`;
      this.handleFatalError(new Error(errorMsg));
    });

    this.process.on("error", (err) => {
      this.isAlive = false;
      this.handleFatalError(err);
    });
  }

  public get pluginManifest(): PluginManifest {
    return this.manifest;
  }

  public get running(): boolean {
    return this.isAlive;
  }

  private generateRequestId(): string {
    return `req-${++this.requestCounter}-${Date.now()}`;
  }

  private sendFrame(message: PluginMessage): void {
    if (!this.isAlive || !this.process.stdin || this.process.stdin.destroyed) {
      throw new Error(
        `Cannot send message to plugin '${this.manifest.id}': process is not active.`,
      );
    }
    const buffer = encodePluginFrame(message);
    this.process.stdin.write(buffer);
  }

  private handleIncomingMessage(message: PluginMessage): void {
    const pending = this.pendingRequests.get(message.requestId);
    if (pending) {
      if (pending.timer) clearTimeout(pending.timer);
      this.pendingRequests.delete(message.requestId);
      pending.resolve(message);
    }
  }

  private handleFatalError(error: Error): void {
    for (const [id, pending] of this.pendingRequests.entries()) {
      if (pending.timer) clearTimeout(pending.timer);
      pending.reject(error);
      this.pendingRequests.delete(id);
    }
  }

  public async performHandshake(
    timeoutMs = 5000,
  ): Promise<PluginHandshakeResponse> {
    const requestId = this.generateRequestId();
    const handshakeReq: PluginMessage = {
      requestId,
      type: "handshake_request",
      pluginId: this.manifest.id,
      protocolVersion: PLUGIN_PROTOCOL_VERSION,
      requestedCapabilities: this.manifest.capabilities,
      permissions: this.manifest.permissions,
    };

    const response = await this.sendRequest(handshakeReq, timeoutMs);
    if (response.type !== "handshake_response") {
      throw new Error(
        `Expected handshake_response but received '${response.type}'`,
      );
    }
    return response;
  }

  public async executeCapability<C extends PluginCapability>(
    capability: C,
    payload: unknown,
    options?: { timeoutMs?: number },
  ): Promise<PluginExecutionResult> {
    if (!this.manifest.capabilities.includes(capability)) {
      return {
        success: false,
        error: `Capability '${capability}' is not declared in plugin manifest for '${this.manifest.id}'`,
      };
    }

    const requestId = this.generateRequestId();
    const executeReq: PluginMessage = {
      requestId,
      type: "execute_request",
      capability,
      payload,
      timeoutMs: options?.timeoutMs,
    };

    try {
      const response = await this.sendRequest(
        executeReq,
        options?.timeoutMs ?? 10000,
      );
      if (response.type !== "execute_response") {
        return {
          success: false,
          error: `Unexpected response type '${response.type}' received for execute_request`,
        };
      }
      const execRes = response as PluginExecuteResponse;
      return {
        success: execRes.success,
        data: execRes.data,
        error:
          execRes.error === undefined
            ? undefined
            : redactSensitiveText(execRes.error),
        diagnostics: enforceDiagnosticLimits(execRes.diagnostics),
      };
    } catch (err) {
      // Attempt cancellation on request timeout
      this.cancelRequest(requestId).catch(() => {});
      return {
        success: false,
        error: redactSensitiveText(
          `Plugin execution failed: ${err instanceof Error ? err.message : String(err)}`,
        ),
      };
    }
  }

  public async cancelRequest(targetRequestId: string): Promise<void> {
    const requestId = this.generateRequestId();
    const cancelReq: PluginMessage = {
      requestId,
      type: "cancel_request",
      targetRequestId,
    };
    this.sendFrame(cancelReq);
  }

  public async shutdown(timeoutMs = 3000): Promise<void> {
    if (!this.isAlive) return;

    try {
      const requestId = this.generateRequestId();
      const shutdownReq: PluginMessage = {
        requestId,
        type: "shutdown_request",
      };
      await this.sendRequest(shutdownReq, timeoutMs);
    } catch {
      // Ignore shutdown errors during cleanup
    } finally {
      this.kill();
    }
  }

  public kill(): void {
    this.isAlive = false;
    if (this.process && !this.process.killed) {
      this.process.kill("SIGTERM");
      setTimeout(() => {
        if (this.process && !this.process.killed) {
          this.process.kill("SIGKILL");
        }
      }, 500);
    }
  }

  private sendRequest(
    message: PluginMessage,
    timeoutMs: number,
  ): Promise<PluginMessage> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingRequests.delete(message.requestId);
        reject(
          new Error(
            `Plugin request '${message.requestId}' timed out after ${timeoutMs}ms`,
          ),
        );
      }, timeoutMs);

      this.pendingRequests.set(message.requestId, { resolve, reject, timer });

      try {
        this.sendFrame(message);
      } catch (err) {
        clearTimeout(timer);
        this.pendingRequests.delete(message.requestId);
        reject(err instanceof Error ? err : new Error(String(err)));
      }
    });
  }
}

export class PluginHost {
  /**
   * Spawns an out-of-process plugin worker over stdio.
   */
  public static async spawnPlugin(
    options: PluginHostOptions,
  ): Promise<PluginClient> {
    const resolvedDir = resolve(options.pluginDir);
    const manifestPath = options.manifestPath
      ? resolve(options.manifestPath)
      : join(resolvedDir, "fuzit-plugin.json");

    const manifestContent = await readFile(manifestPath, "utf-8");
    const manifest = parsePluginManifest(
      JSON.parse(manifestContent.replace(/^\uFEFF/, "")),
    );

    const compatResult = validatePluginCompatibility(manifest);
    if (!compatResult.compatible) {
      throw new Error(
        `Plugin '${manifest.id}' is incompatible: ${compatResult.reasons.join("; ")}`,
      );
    }

    const entryPointPath = join(resolvedDir, manifest.entryPoint);
    const nodeBin = options.nodeExecutable ?? process.execPath;

    // Launch plugin by argument array without invoking a shell
    const child = spawn(nodeBin, [entryPointPath], {
      cwd: resolvedDir,
      stdio: ["pipe", "pipe", "pipe"],
      env: {
        NODE_ENV: "production",
      },
    });

    const client = new PluginClient(child, manifest);

    // Perform initial handshake
    const handshakeResult = await client.performHandshake(
      options.defaultTimeoutMs ?? 5000,
    );
    if (!handshakeResult.success) {
      client.kill();
      throw new Error(
        `Plugin handshake failed for '${manifest.id}': ${handshakeResult.error ?? "Unknown handshake rejection"}`,
      );
    }

    return client;
  }
}

export {
  PluginClient,
  PluginHost,
  type PluginExecutionResult,
  type PluginHostOptions,
} from "./host.js";

export {
  satisfiesSemver,
  validatePluginCompatibility,
  type CompatibilityValidationOptions,
  type CompatibilityValidationResult,
} from "./compatibility.js";

export {
  PermissionBroker,
  type PermissionAuditRecord,
  type PermissionBrokerOptions,
  type PermissionOperation,
} from "./permission-broker.js";

export {
  DEFAULT_PLUGIN_RESOURCE_LIMITS,
  enforceDiagnosticLimits,
  type PluginResourceLimits,
} from "./resource-limits.js";

export interface PluginHostBoundary {
  readonly packageName: "@fuzit/plugin-host";
}

import { isAbsolute, normalize, resolve } from "node:path";
import type { PluginPermissions } from "@fuzit/plugin-sdk";
import { redactSensitiveText } from "@fuzit/security";

export type PermissionOperation =
  | { readonly kind: "filesystem:read"; readonly path: string }
  | { readonly kind: "filesystem:write"; readonly path: string }
  | { readonly kind: "network:connect"; readonly host: string }
  | { readonly kind: "shell:execute"; readonly command: string }
  | { readonly kind: "environment:read"; readonly varName: string }
  | { readonly kind: "credentials:read"; readonly key: string }
  | { readonly kind: "runtime:spawnProcess" }
  | { readonly kind: "persistence:write"; readonly key: string };

export interface PermissionAuditRecord {
  readonly timestamp: string;
  readonly operation: PermissionOperation;
  readonly allowed: boolean;
  readonly reason: string;
}

export interface PermissionBrokerOptions {
  readonly permissions?: PluginPermissions | undefined;
  readonly workspaceRoot?: string | undefined;
}

export class PermissionBroker {
  private readonly permissions: PluginPermissions | undefined;
  private readonly workspaceRoot: string;
  private readonly auditLogs: PermissionAuditRecord[] = [];

  constructor(options?: PermissionBrokerOptions) {
    this.permissions = options?.permissions;
    this.workspaceRoot = resolve(options?.workspaceRoot ?? process.cwd());
  }

  public getAuditLogs(): readonly PermissionAuditRecord[] {
    return [...this.auditLogs];
  }

  /**
   * Authorize a requested plugin operation against deny-by-default security policies.
   */
  public authorize(operation: PermissionOperation): {
    allowed: boolean;
    reason: string;
  } {
    let result: { allowed: boolean; reason: string };

    switch (operation.kind) {
      case "filesystem:read":
        result = this.authorizePath(
          operation.path,
          this.permissions?.filesystem?.readPaths,
          "read",
        );
        break;
      case "filesystem:write":
        result = this.authorizePath(
          operation.path,
          this.permissions?.filesystem?.writePaths,
          "write",
        );
        break;
      case "network:connect":
        result = this.authorizeNetwork(operation.host);
        break;
      case "shell:execute":
        result = this.authorizeShell();
        break;
      case "environment:read":
        result = this.authorizeEnv(operation.varName);
        break;
      case "credentials:read":
        result = this.authorizeCredentials(operation.key);
        break;
      case "runtime:spawnProcess":
        result = {
          allowed: false,
          reason: "Runtime process spawning by plugins is denied by default.",
        };
        break;
      case "persistence:write":
        result = this.authorizePersistence();
        break;
      default:
        result = {
          allowed: false,
          reason: "Unknown operation kind denied by default policy.",
        };
    }

    this.auditLogs.push({
      timestamp: new Date().toISOString(),
      operation: redactOperation(operation),
      allowed: result.allowed,
      reason: redactSensitiveText(result.reason),
    });

    return result;
  }

  private authorizePath(
    targetPath: string,
    allowedPatterns: readonly string[] | undefined,
    action: "read" | "write",
  ): { allowed: boolean; reason: string } {
    if (!targetPath || typeof targetPath !== "string") {
      return { allowed: false, reason: `Invalid ${action} path provided.` };
    }

    // Path traversal / confused-deputy protection
    if (targetPath.includes("\0")) {
      return {
        allowed: false,
        reason: `Path contains null bytes: '${targetPath}'.`,
      };
    }
    if (targetPath.includes("..")) {
      return {
        allowed: false,
        reason: `Path traversal '..' is strictly forbidden: '${targetPath}'.`,
      };
    }

    const resolved = isAbsolute(targetPath)
      ? normalize(targetPath)
      : resolve(this.workspaceRoot, targetPath);

    if (!resolved.startsWith(this.workspaceRoot)) {
      return {
        allowed: false,
        reason: `Path '${targetPath}' resolves outside workspace root directory.`,
      };
    }

    if (!allowedPatterns || allowedPatterns.length === 0) {
      return {
        allowed: false,
        reason: `Plugin has no allowed filesystem ${action} paths configured (deny by default).`,
      };
    }

    const relPath = normalize(resolved.substring(this.workspaceRoot.length))
      .replaceAll("\\", "/")
      .replace(/^\/+/, "");
    const match = allowedPatterns.some((pattern) => {
      const normPattern = normalize(pattern)
        .replaceAll("\\", "/")
        .replace(/^\/+/, "");
      return relPath === normPattern || relPath.startsWith(normPattern + "/");
    });

    if (!match) {
      return {
        allowed: false,
        reason: `Path '${relPath}' is not in configured allowed ${action} paths: [${allowedPatterns.join(", ")}].`,
      };
    }

    return {
      allowed: true,
      reason: `Access granted for ${action} on path '${relPath}'.`,
    };
  }

  private authorizeNetwork(host: string): { allowed: boolean; reason: string } {
    if (!host) return { allowed: false, reason: "Invalid network host." };
    const allowedHosts = this.permissions?.network?.allowedHosts;
    if (!allowedHosts || allowedHosts.length === 0) {
      return {
        allowed: false,
        reason:
          "Network access is denied by default (no allowed hosts configured).",
      };
    }

    if (allowedHosts.includes(host) || allowedHosts.includes("*")) {
      return {
        allowed: true,
        reason: `Network connection to '${host}' granted.`,
      };
    }

    return {
      allowed: false,
      reason: `Network host '${host}' is not in configured allowedHosts: [${allowedHosts.join(", ")}].`,
    };
  }

  private authorizeShell(): { allowed: boolean; reason: string } {
    if (this.permissions?.shell === true) {
      return {
        allowed: true,
        reason: "Shell execution granted by explicit plugin permissions.",
      };
    }
    return { allowed: false, reason: "Shell execution is denied by default." };
  }

  private authorizeEnv(varName: string): { allowed: boolean; reason: string } {
    const allowedVars = this.permissions?.environment?.allowedVars;
    if (!allowedVars || allowedVars.length === 0) {
      return {
        allowed: false,
        reason: "Environment variable access denied by default.",
      };
    }

    if (allowedVars.includes(varName) || allowedVars.includes("*")) {
      return {
        allowed: true,
        reason: `Environment variable '${varName}' access granted.`,
      };
    }

    return {
      allowed: false,
      reason: `Environment variable '${varName}' is not in configured allowed envVars.`,
    };
  }

  private authorizeCredentials(key: string): {
    allowed: boolean;
    reason: string;
  } {
    const allowedKeys = this.permissions?.credentials?.allowedKeys;
    if (!allowedKeys || allowedKeys.length === 0) {
      return { allowed: false, reason: "Credential access denied by default." };
    }

    if (allowedKeys.includes(key)) {
      return { allowed: true, reason: `Credential '${key}' access granted.` };
    }

    return {
      allowed: false,
      reason: `Credential key '${key}' is not in configured allowed credentials.`,
    };
  }

  private authorizePersistence(): { allowed: boolean; reason: string } {
    if (this.permissions?.persistence === true) {
      return {
        allowed: true,
        reason: "Persistence mutation granted by explicit plugin permissions.",
      };
    }
    return {
      allowed: false,
      reason: "Persistence mutation is denied by default.",
    };
  }
}

function redactOperation(operation: PermissionOperation): PermissionOperation {
  switch (operation.kind) {
    case "filesystem:read":
    case "filesystem:write":
      return { ...operation, path: redactSensitiveText(operation.path, 512) };
    case "network:connect":
      return { ...operation, host: redactSensitiveText(operation.host, 256) };
    case "shell:execute":
      return {
        ...operation,
        command: redactSensitiveText(operation.command, 512),
      };
    case "environment:read":
      return {
        ...operation,
        varName: redactSensitiveText(operation.varName, 128),
      };
    case "credentials:read":
      return { ...operation, key: redactSensitiveText(operation.key, 128) };
    case "persistence:write":
      return { ...operation, key: redactSensitiveText(operation.key, 256) };
    case "runtime:spawnProcess":
      return operation;
  }
}

import type { Diagnostic } from "@fuzit/plugin-sdk";

export interface PluginResourceLimits {
  readonly maxOutputBytes?: number;
  readonly maxDiagnosticsPerRequest?: number;
  readonly maxRequestsPerMinute?: number;
  readonly startupTimeoutMs?: number;
  readonly requestTimeoutMs?: number;
  readonly maxStderrBytes?: number;
}

export const DEFAULT_PLUGIN_RESOURCE_LIMITS: Required<PluginResourceLimits> = {
  maxOutputBytes: 16 * 1024 * 1024, // 16MB
  maxDiagnosticsPerRequest: 100,
  maxRequestsPerMinute: 600,
  startupTimeoutMs: 5000,
  requestTimeoutMs: 10000,
  maxStderrBytes: 1024 * 1024, // 1MB
};

/**
 * Truncates diagnostic array if it exceeds maxDiagnosticsPerRequest and appends a truncation warning.
 */
export function enforceDiagnosticLimits(
  diagnostics: readonly Diagnostic[] | undefined,
  maxDiagnostics: number = DEFAULT_PLUGIN_RESOURCE_LIMITS.maxDiagnosticsPerRequest,
): readonly Diagnostic[] | undefined {
  if (!diagnostics || diagnostics.length <= maxDiagnostics) {
    return diagnostics;
  }

  const truncated = diagnostics.slice(0, maxDiagnostics - 1);
  const warning: Diagnostic = {
    schemaVersion: 1,
    code: "PLUGIN_DIAGNOSTIC_TRUNCATED",
    severity: "warning",
    source: "plugin-host",
    message: `Diagnostic list truncated: exceeded max limit of ${maxDiagnostics} diagnostics per request.`,
  };

  return [...truncated, warning];
}

