export function normalizePullRequestData(
  ref: GitHubPullRequestRef,
  rawRecord: unknown,
): PullRequestRecord {
  const raw = rawRecord as Record<string, any>;
  return {
    schemaVersion: PROVIDER_RECORDS_SCHEMA_VERSION,
    id: buildStableRecordId(
      "github",
      ref.host.webHost,
      `${ref.owner}/${ref.repo}`,
      "pull-request",
      ref.number,
    ),
    kind: "pull-request",
    provider: "github",
    host: ref.host,
    repositoryFullName: `${ref.owner}/${ref.repo}`,
    observedAt: new Date().toISOString(),
    completeness: "full",
    sensitivity: "public",
    number: ref.number,
    title: raw.title ?? "",
    body: raw.body ?? "",
    state: raw.merged ? "merged" : raw.state === "closed" ? "closed" : "open",
    isDraft: Boolean(raw.draft),
    authorLogin: raw.user?.login ?? "ghost",
    baseRef: raw.base?.ref ?? "main",
    baseSha: raw.base?.sha ?? "",
    headRef: raw.head?.ref ?? "",
    headSha: raw.head?.sha ?? "",
    labels: Array.isArray(raw.labels)
      ? raw.labels.map((l: Record<string, unknown>) => String(l.name ?? ""))
      : [],
  };
}

/**
 * GitHub repository resolution.
 *
 * Fetches and normalizes canonical repository identity, default branch,
 * visibility, archived/disabled/fork state, and sanitized web URL.
 * Handles renamed/transferred repositories via redirect provenance.
 *
 * @module
 */

import type { GitHubHostIdentity } from "@fuzit/schemas";
import type { CredentialHandle } from "./auth.js";
import type { FixtureTransport } from "./transport.js";
import { githubRequest } from "./transport.js";

// ---------------------------------------------------------------------------
// Repository record
// ---------------------------------------------------------------------------

export interface RepositoryRecord {
  readonly schemaVersion: 1;
  readonly kind: "repository";
  readonly host: GitHubHostIdentity;
  /** Canonical owner at time of observation. */
  readonly owner: string;
  /** Canonical repository name at time of observation. */
  readonly name: string;
  /** Full name: owner/name */
  readonly fullName: string;
  /** Node ID where available. */
  readonly nodeId?: string;
  readonly defaultBranch: string;
  readonly visibility: "public" | "private" | "internal" | "unknown";
  readonly isArchived: boolean;
  readonly isDisabled: boolean;
  readonly isFork: boolean;
  /** Sanitized web URL — no credentials. */
  readonly webUrl: string;
  /** If the canonical URL differs from the requested URL (transfer/rename). */
  readonly canonicalUrlChanged: boolean;
  /** Prior owner/name if transferred. */
  readonly priorFullName?: string;
  /** ISO timestamp of observation. */
  readonly observedAt: string;
  readonly completeness: "full" | "partial";
}

// ---------------------------------------------------------------------------
// Resolution result
// ---------------------------------------------------------------------------

export type ResolveRepositoryResult =
  | { readonly ok: true; readonly record: RepositoryRecord }
  | {
      readonly ok: false;
      readonly kind:
        | "not-found"
        | "forbidden"
        | "gone"
        | "network-error"
        | "invalid-response";
      readonly diagnostic: string;
    };

// ---------------------------------------------------------------------------
// Raw GitHub API shape (private — never exported from this module)
// ---------------------------------------------------------------------------

interface GhApiRepository {
  id: number;
  node_id?: string;
  name: string;
  full_name: string;
  owner: { login: string };
  private: boolean;
  visibility?: string;
  default_branch: string;
  archived: boolean;
  disabled: boolean;
  fork: boolean;
  html_url: string;
}

// ---------------------------------------------------------------------------
// Resolution function
// ---------------------------------------------------------------------------

export async function resolveRepository(options: {
  readonly host: GitHubHostIdentity;
  readonly owner: string;
  readonly repo: string;
  readonly credential: CredentialHandle;
  readonly allowedHosts: readonly string[];
  readonly fixtureTransport?: FixtureTransport;
}): Promise<ResolveRepositoryResult> {
  const { host, owner, repo, credential, allowedHosts } = options;
  const apiBase = host.isEnterprise
    ? `https://${host.apiHost}`
    : `https://api.github.com`;
  const url = `${apiBase}/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;

  const transport = await githubRequest(
    url,
    options.fixtureTransport
      ? { allowedHosts, credential, fixtureTransport: options.fixtureTransport }
      : { allowedHosts, credential },
  );

  if (!transport.ok) {
    if (transport.kind === "server-error") {
      return {
        ok: false,
        kind: "network-error",
        diagnostic: transport.diagnostic,
      };
    }
    return {
      ok: false,
      kind: "network-error",
      diagnostic: transport.diagnostic,
    };
  }

  if (transport.status === 404) {
    return {
      ok: false,
      kind: "not-found",
      diagnostic: `Repository ${owner}/${repo} not found on ${host.webHost}`,
    };
  }
  if (transport.status === 403) {
    return {
      ok: false,
      kind: "forbidden",
      diagnostic: `Access forbidden to ${owner}/${repo} on ${host.webHost}`,
    };
  }
  if (transport.status === 410) {
    return {
      ok: false,
      kind: "gone",
      diagnostic: `Repository ${owner}/${repo} has been deleted`,
    };
  }
  if (transport.status !== 200) {
    return {
      ok: false,
      kind: "invalid-response",
      diagnostic: `Unexpected status ${transport.status}`,
    };
  }

  let data: GhApiRepository;
  try {
    data = JSON.parse(transport.body) as GhApiRepository;
  } catch {
    return {
      ok: false,
      kind: "invalid-response",
      diagnostic: "Invalid JSON from GitHub API",
    };
  }

  // Detect canonical URL change (transfer/rename)
  const canonicalOwner = data.owner.login;
  const canonicalName = data.name;
  const canonicalUrlChanged =
    canonicalOwner.toLowerCase() !== owner.toLowerCase() ||
    canonicalName.toLowerCase() !== repo.toLowerCase();

  const visibility: RepositoryRecord["visibility"] =
    data.visibility === "public"
      ? "public"
      : data.visibility === "private" || data.private
        ? "private"
        : data.visibility === "internal"
          ? "internal"
          : "unknown";

  const record: RepositoryRecord = {
    schemaVersion: 1,
    kind: "repository",
    host,
    owner: canonicalOwner,
    name: canonicalName,
    fullName: data.full_name,
    ...(data.node_id ? { nodeId: data.node_id } : {}),
    defaultBranch: data.default_branch,
    visibility,
    isArchived: data.archived,
    isDisabled: data.disabled,
    isFork: data.fork,
    webUrl: sanitizeUrl(data.html_url),
    canonicalUrlChanged,
    ...(canonicalUrlChanged ? { priorFullName: `${owner}/${repo}` } : {}),
    observedAt: new Date().toISOString(),
    completeness: "full",
  };

  return { ok: true, record };
}

function sanitizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    // Strip any credentials (should never be present but defensive)
    parsed.username = "";
    parsed.password = "";
    return parsed.toString();
  } catch {
    return url;
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * PR reviews, review comments, and thread grouping service.
 *
 * @module
 */

import {
  buildStableRecordId,
  PROVIDER_RECORDS_SCHEMA_VERSION,
  type ReviewCommentRecord,
  type ReviewRecord,
  type ReviewThreadRecord,
} from "@fuzit/schemas";
import type { GitHubPullRequestRef } from "@fuzit/schemas";

export function normalizeReview(
  ref: GitHubPullRequestRef,
  rawReviewRecord: unknown,
): ReviewRecord {
  const rawReview = rawReviewRecord as Record<string, any>;
  const repoFullName = `${ref.owner}/${ref.repo}`;
  const state =
    rawReview.state === "APPROVED"
      ? "APPROVED"
      : rawReview.state === "CHANGES_REQUESTED"
        ? "CHANGES_REQUESTED"
        : rawReview.state === "DISMISSED"
          ? "DISMISSED"
          : "COMMENTED";
  return {
    schemaVersion: PROVIDER_RECORDS_SCHEMA_VERSION,
    id: buildStableRecordId(
      "github",
      ref.host.webHost,
      repoFullName,
      "review",
      rawReview.id,
    ),
    kind: "review",
    provider: "github",
    host: ref.host,
    repositoryFullName: repoFullName,
    observedAt: new Date().toISOString(),
    completeness: "full",
    sensitivity: "public",
    prNumber: ref.number,
    reviewId: Number(rawReview.id),
    authorLogin: rawReview.user?.login ?? "ghost",
    state,
    body: rawReview.body ?? "",
  };
}

export function groupReviewCommentsIntoThreads(
  ref: GitHubPullRequestRef,
  rawComments: readonly unknown[],
): readonly ReviewThreadRecord[] {
  const repoFullName = `${ref.owner}/${ref.repo}`;
  const threadsByInReplyTo = new Map<number, ReviewCommentRecord[]>();
  const rootComments: Record<string, any>[] = [];

  for (const rawC of rawComments) {
    const c = rawC as Record<string, any>;
    const commentRecord: ReviewCommentRecord = {
      schemaVersion: PROVIDER_RECORDS_SCHEMA_VERSION,
      id: buildStableRecordId(
        "github",
        ref.host.webHost,
        repoFullName,
        "review-comment",
        c.id,
      ),
      kind: "review-comment",
      provider: "github",
      host: ref.host,
      repositoryFullName: repoFullName,
      observedAt: new Date().toISOString(),
      completeness: "full",
      sensitivity: "public",
      prNumber: ref.number,
      commentId: Number(c.id),
      path: c.path ?? "",
      line: c.line ?? c.original_line,
      authorLogin: c.user?.login ?? "ghost",
      body: c.body ?? "",
    };

    if (c.in_reply_to_id) {
      const parentId = Number(c.in_reply_to_id);
      if (!threadsByInReplyTo.has(parentId)) {
        threadsByInReplyTo.set(parentId, []);
      }
      threadsByInReplyTo.get(parentId)!.push(commentRecord);
    } else {
      rootComments.push(c);
      if (!threadsByInReplyTo.has(Number(c.id))) {
        threadsByInReplyTo.set(Number(c.id), [commentRecord]);
      } else {
        threadsByInReplyTo.get(Number(c.id))!.unshift(commentRecord);
      }
    }
  }

  return rootComments.map((root) => {
    const threadComments = threadsByInReplyTo.get(Number(root.id)) ?? [];
    return {
      schemaVersion: PROVIDER_RECORDS_SCHEMA_VERSION,
      id: buildStableRecordId(
        "github",
        ref.host.webHost,
        repoFullName,
        "review-thread",
        root.id,
      ),
      kind: "review-thread",
      provider: "github",
      host: ref.host,
      repositoryFullName: repoFullName,
      observedAt: new Date().toISOString(),
      completeness: "full",
      sensitivity: "public",
      prNumber: ref.number,
      threadId: String(root.id),
      path: root.path ?? "",
      isResolved: false,
      comments: threadComments,
    };
  });
}

/**
 * GitHub source URL and shorthand parser.
 *
 * Parses all supported GitHub source forms into normalized `SourceRef` objects
 * without contacting the network. Credential-bearing URLs, unsupported schemes,
 * encoded path traversal, and non-GitHub hosts are rejected immediately.
 *
 * @module
 */

import type {
  GitHubHostIdentity,
  GitHubIssueRef,
  GitHubPullRequestRef,
  GitHubRepositoryRef,
  ParseSourceRefResult,
} from "@fuzit/schemas";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const GITHUB_COM_WEB_HOST = "github.com";
const GITHUB_COM_API_HOST = "api.github.com";

/**
 * URL schemes that are supported for GitHub sources.
 * Only https is permitted; git+https and git+ssh are not supported as direct
 * source inputs (they are used internally for safe Git transport).
 */
const SUPPORTED_SCHEMES = new Set(["https:"]);

/**
 * Segments that indicate a credential might be embedded in the URL.
 */
const CREDENTIAL_INDICATORS = /[@:][^/]/;

// ---------------------------------------------------------------------------
// Host resolution
// ---------------------------------------------------------------------------

/**
 * Resolve a `GitHubHostIdentity` from a parsed URL's hostname.
 *
 * For github.com the API host is `api.github.com`.
 * For a GitHub Enterprise host the API base is derived as
 * `<host>/api/v3` unless `apiBase` is explicitly overridden.
 *
 * This function performs no network calls.
 */
function resolveHost(
  hostname: string,
  apiBase?: string,
): GitHubHostIdentity | null {
  if (!hostname || hostname.length === 0) return null;
  // Reject IP addresses and localhost
  if (/^\d+\.\d+\.\d+\.\d+$/.test(hostname) || hostname === "localhost") {
    return null;
  }
  const isEnterprise = hostname !== GITHUB_COM_WEB_HOST;
  const apiHost = apiBase
    ? apiBase
    : isEnterprise
      ? `${hostname}/api/v3`
      : GITHUB_COM_API_HOST;
  return { webHost: hostname, apiHost, isEnterprise };
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Validate an owner or repository name component.
 * GitHub allows letters, digits, hyphens, underscores, and dots.
 * Empty names, names starting with a hyphen, and names with double-dots are
 * rejected.
 */
function isValidOwnerOrRepo(name: string): boolean {
  if (!name || name.length === 0) return false;
  if (name.startsWith("-")) return false;
  if (name.includes("..")) return false;
  if (name.includes("%")) return false; // encoded traversal
  return /^[\w.-]+$/.test(name);
}

/**
 * Validate a pull-request or issue number string.
 */
function parsePositiveInteger(s: string): number | null {
  if (!/^\d+$/.test(s)) return null;
  const n = Number.parseInt(s, 10);
  if (!Number.isFinite(n) || n <= 0) return null;
  return n;
}

// ---------------------------------------------------------------------------
// URL-based parsers
// ---------------------------------------------------------------------------

/**
 * Parse a `https://HOST/OWNER/REPO[.git][/...]` URL.
 *
 * Supported path forms after `/OWNER/REPO`:
 *   - (empty or /) → repository
 *   - `/pull/N`    → pull request
 *   - `/issues/N`  → issue
 */
function parseGitHubUrl(
  input: string,
): ParseSourceRefResult<
  GitHubRepositoryRef | GitHubPullRequestRef | GitHubIssueRef
> {
  let url: URL;
  try {
    url = new URL(input);
  } catch {
    return { ok: false, reason: "input is not a valid URL" };
  }

  if (!SUPPORTED_SCHEMES.has(url.protocol)) {
    return {
      ok: false,
      reason: `unsupported URL scheme '${url.protocol}'; only https is allowed`,
    };
  }

  // Reject credentials embedded in the URL
  if (url.username || url.password) {
    return {
      ok: false,
      reason: "credentials must not be embedded in GitHub URLs",
    };
  }

  // Extra check on raw input for credential-like patterns before URL parsing
  // strips them (some environments normalise before throwing)
  const hostPart = input.slice("https://".length).split("/")[0] ?? "";
  if (CREDENTIAL_INDICATORS.test(hostPart)) {
    return {
      ok: false,
      reason: "credentials must not be embedded in GitHub URLs",
    };
  }

  const host = resolveHost(url.hostname);
  if (!host) {
    return {
      ok: false,
      reason: `unresolvable or disallowed GitHub host: ${url.hostname}`,
    };
  }

  // Reject hash fragments with non-trivial content that might indicate a
  // misrouted URL
  if (url.hash && url.hash.length > 1) {
    return {
      ok: false,
      reason:
        "URL fragments are ambiguous in GitHub source references; use a path-based revision",
    };
  }

  // Strip leading slash and optional .git suffix from pathname
  let pathname = url.pathname;
  if (pathname.endsWith(".git")) {
    pathname = pathname.slice(0, -4);
  }

  const segments = pathname.split("/").filter(Boolean);

  if (segments.length < 2) {
    return {
      ok: false,
      reason: "GitHub URL must include at least OWNER and REPO path segments",
    };
  }

  const owner = segments[0];
  const repoRaw = segments[1];
  const rest = segments.slice(2);

  if (!owner || !isValidOwnerOrRepo(owner)) {
    return { ok: false, reason: `invalid GitHub owner: '${owner}'` };
  }
  if (!repoRaw || !isValidOwnerOrRepo(repoRaw)) {
    return {
      ok: false,
      reason: `invalid GitHub repository name: '${repoRaw}'`,
    };
  }

  // No further path → repository source
  if (rest.length === 0) {
    const ref: GitHubRepositoryRef = {
      kind: "github-repository",
      host,
      owner,
      repo: repoRaw,
    };
    return { ok: true, ref };
  }

  const firstRest = rest[0];
  const secondRest = rest[1];

  // Pull request: /pull/N
  if (firstRest === "pull" && rest.length === 2 && secondRest) {
    const number = parsePositiveInteger(secondRest);
    if (number === null) {
      return {
        ok: false,
        reason: `invalid pull request number: '${secondRest}'`,
      };
    }
    const ref: GitHubPullRequestRef = {
      kind: "github-pull-request",
      host,
      owner,
      repo: repoRaw,
      number,
    };
    return { ok: true, ref };
  }

  // Issue: /issues/N
  if (firstRest === "issues" && rest.length === 2 && secondRest) {
    const number = parsePositiveInteger(secondRest);
    if (number === null) {
      return { ok: false, reason: `invalid issue number: '${secondRest}'` };
    }
    const ref: GitHubIssueRef = {
      kind: "github-issue",
      host,
      owner,
      repo: repoRaw,
      number,
    };
    return { ok: true, ref };
  }

  // Tree/blob paths → treat as repository with revision context
  if (firstRest === "tree" && rest.length >= 2) {
    const ref: GitHubRepositoryRef = {
      kind: "github-repository",
      host,
      owner,
      repo: repoRaw,
      revision: rest.slice(1).join("/"),
    };
    return { ok: true, ref };
  }

  return {
    ok: false,
    reason: `unsupported GitHub URL path: '${url.pathname}'`,
  };
}

// ---------------------------------------------------------------------------
// Shorthand parsers
// ---------------------------------------------------------------------------

/**
 * Parse `OWNER/REPO` shorthand (github.com implied).
 */
function parseOwnerRepo(
  input: string,
): ParseSourceRefResult<GitHubRepositoryRef> {
  const parts = input.split("/");
  if (parts.length !== 2) {
    return {
      ok: false,
      reason: "OWNER/REPO must have exactly two slash-separated components",
    };
  }
  const owner = parts[0];
  const repo = parts[1];
  if (!owner || !isValidOwnerOrRepo(owner)) {
    return { ok: false, reason: `invalid owner: '${owner}'` };
  }
  if (!repo || !isValidOwnerOrRepo(repo)) {
    return { ok: false, reason: `invalid repository name: '${repo}'` };
  }
  const host = resolveHost(GITHUB_COM_WEB_HOST)!;
  return { ok: true, ref: { kind: "github-repository", host, owner, repo } };
}

/**
 * Parse `OWNER/REPO#N` shorthand with explicit PR/issue disambiguation.
 *
 * When `recordKind` is `"pull-request"` → `GitHubPullRequestRef`.
 * When `recordKind` is `"issue"` → `GitHubIssueRef`.
 * When omitted the parser rejects with an ambiguity error.
 */
function parseOwnerRepoHash(
  input: string,
  recordKind: "pull-request",
): ParseSourceRefResult<GitHubPullRequestRef>;
function parseOwnerRepoHash(
  input: string,
  recordKind: "issue",
): ParseSourceRefResult<GitHubIssueRef>;
function parseOwnerRepoHash(
  input: string,
  recordKind?: "pull-request" | "issue",
): ParseSourceRefResult<GitHubPullRequestRef | GitHubIssueRef>;
function parseOwnerRepoHash(
  input: string,
  recordKind?: "pull-request" | "issue",
): ParseSourceRefResult<GitHubPullRequestRef | GitHubIssueRef> {
  const hashIndex = input.indexOf("#");
  if (hashIndex === -1) {
    return { ok: false, reason: "OWNER/REPO#N must include a '#' separator" };
  }
  const repoPath = input.slice(0, hashIndex);
  const numberStr = input.slice(hashIndex + 1);

  const repoResult = parseOwnerRepo(repoPath);
  if (!repoResult.ok) return repoResult as ParseSourceRefResult<never>;

  const number = parsePositiveInteger(numberStr);
  if (number === null) {
    return { ok: false, reason: `invalid number after '#': '${numberStr}'` };
  }

  const { owner, repo, host } = repoResult.ref;

  if (!recordKind) {
    return {
      ok: false,
      reason:
        "OWNER/REPO#N is ambiguous without command context; use 'fuzit pr' or 'fuzit issue'",
    };
  }

  if (recordKind === "pull-request") {
    const ref: GitHubPullRequestRef = {
      kind: "github-pull-request",
      host,
      owner,
      repo,
      number,
    };
    return { ok: true, ref };
  }

  const ref: GitHubIssueRef = {
    kind: "github-issue",
    host,
    owner,
    repo,
    number,
  };
  return { ok: true, ref };
}

/**
 * Parse a numeric ID with an explicit `--repo OWNER/REPO` providing context.
 */
function parseNumericWithRepo(
  numberStr: string,
  repoStr: string,
  recordKind: "pull-request",
): ParseSourceRefResult<GitHubPullRequestRef>;
function parseNumericWithRepo(
  numberStr: string,
  repoStr: string,
  recordKind: "issue",
): ParseSourceRefResult<GitHubIssueRef>;
function parseNumericWithRepo(
  numberStr: string,
  repoStr: string,
  recordKind: "pull-request" | "issue",
): ParseSourceRefResult<GitHubPullRequestRef | GitHubIssueRef>;
function parseNumericWithRepo(
  numberStr: string,
  repoStr: string,
  recordKind: "pull-request" | "issue",
): ParseSourceRefResult<GitHubPullRequestRef | GitHubIssueRef> {
  const number = parsePositiveInteger(numberStr);
  if (number === null) {
    return { ok: false, reason: `invalid number: '${numberStr}'` };
  }
  const repoResult = parseOwnerRepo(repoStr);
  if (!repoResult.ok) return repoResult as ParseSourceRefResult<never>;
  const { owner, repo, host } = repoResult.ref;
  if (recordKind === "pull-request") {
    return {
      ok: true,
      ref: { kind: "github-pull-request", host, owner, repo, number },
    };
  }
  return {
    ok: true,
    ref: { kind: "github-issue", host, owner, repo, number },
  };
}

// ---------------------------------------------------------------------------
// Public surface
// ---------------------------------------------------------------------------

export {
  parseGitHubUrl,
  parseOwnerRepo,
  parseOwnerRepoHash,
  parseNumericWithRepo,
  resolveHost,
  isValidOwnerOrRepo,
  GITHUB_COM_WEB_HOST,
  GITHUB_COM_API_HOST,
};

/**
 * Bounded GitHub HTTP transport.
 *
 * Wraps Node's fetch with strict bounds: timeout, cancellation, response-size
 * limits, redirect limits, content-type validation, safe user-agent, and API
 * version headers.
 *
 * SECURITY INVARIANTS:
 * - Authorization headers are never logged or recorded
 * - Response bodies are never serialized to disk by this layer
 * - Redirects are validated against the allowed host set before following
 * - Fixture transport injection is supported for deterministic tests
 *
 * @module
 */

import type { CredentialHandle } from "./auth.js";

// ---------------------------------------------------------------------------
// Bounds (configurable, with hard ceilings)
// ---------------------------------------------------------------------------

export interface TransportBounds {
  /** Request timeout in milliseconds. Default 30 000. Max 120 000. */
  readonly requestTimeoutMs: number;
  /** Maximum response body bytes. Default 8 MB. Max 32 MB. */
  readonly maxResponseBytes: number;
  /** Maximum redirects to follow. Default 3. Max 10. */
  readonly maxRedirects: number;
  /** Maximum retry attempts on transient 5xx. Default 2. Max 5. */
  readonly maxRetries: number;
}

const DEFAULT_BOUNDS: TransportBounds = {
  requestTimeoutMs: 30_000,
  maxResponseBytes: 8 * 1024 * 1024,
  maxRedirects: 3,
  maxRetries: 2,
};

const HARD_CEILING: TransportBounds = {
  requestTimeoutMs: 120_000,
  maxResponseBytes: 32 * 1024 * 1024,
  maxRedirects: 10,
  maxRetries: 5,
};

function clampBounds(bounds?: Partial<TransportBounds>): TransportBounds {
  return {
    requestTimeoutMs: Math.min(
      bounds?.requestTimeoutMs ?? DEFAULT_BOUNDS.requestTimeoutMs,
      HARD_CEILING.requestTimeoutMs,
    ),
    maxResponseBytes: Math.min(
      bounds?.maxResponseBytes ?? DEFAULT_BOUNDS.maxResponseBytes,
      HARD_CEILING.maxResponseBytes,
    ),
    maxRedirects: Math.min(
      bounds?.maxRedirects ?? DEFAULT_BOUNDS.maxRedirects,
      HARD_CEILING.maxRedirects,
    ),
    maxRetries: Math.min(
      bounds?.maxRetries ?? DEFAULT_BOUNDS.maxRetries,
      HARD_CEILING.maxRetries,
    ),
  };
}

// ---------------------------------------------------------------------------
// Transport result
// ---------------------------------------------------------------------------

export type TransportSuccess = {
  readonly ok: true;
  readonly status: number;
  readonly headers: Record<string, string>;
  readonly body: string;
};

export type TransportFailure = {
  readonly ok: false;
  readonly kind:
    | "timeout"
    | "cancelled"
    | "oversized"
    | "invalid-json"
    | "invalid-content-type"
    | "untrusted-redirect"
    | "network-error"
    | "server-error"
    | "rate-limited";
  /** Human-readable sanitized explanation. Never contains tokens or auth headers. */
  readonly diagnostic: string;
  readonly status?: number;
  /** Retry-After seconds if provided by server (rate-limited). */
  readonly retryAfterSeconds?: number;
};

export type TransportResult = TransportSuccess | TransportFailure;

// ---------------------------------------------------------------------------
// Fixture transport for deterministic tests
// ---------------------------------------------------------------------------

export type FixtureTransport = (
  url: string,
  method: string,
) => Promise<TransportResult>;

// ---------------------------------------------------------------------------
// Transport options
// ---------------------------------------------------------------------------

export interface TransportRequestOptions {
  readonly method?: "GET" | "HEAD";
  readonly credential?: CredentialHandle;
  readonly allowedHosts: readonly string[];
  readonly bounds?: Partial<TransportBounds>;
  readonly cancellationSignal?: AbortSignal;
  /** If provided, uses this instead of real fetch (for tests). */
  readonly fixtureTransport?: FixtureTransport;
}

// ---------------------------------------------------------------------------
// Main transport function
// ---------------------------------------------------------------------------

const FUZIT_USER_AGENT = "Fuzit/1 (+https://fuzit.dev; read-only context tool)";
const GITHUB_API_VERSION = "2022-11-28";

/**
 * Make a bounded read-only request to a GitHub API endpoint.
 *
 * Authorization headers are injected from the credential handle and are never
 * logged, returned, or stored outside the active request.
 */
export async function githubRequest(
  url: string,
  options: TransportRequestOptions,
): Promise<TransportResult> {
  const { fixtureTransport } = options;
  const bounds = clampBounds(options.bounds);
  const method = options.method ?? "GET";

  // Validate host before any request
  const hostCheck = validateRequestHost(url, options.allowedHosts);
  if (!hostCheck.ok) {
    return {
      ok: false,
      kind: "untrusted-redirect",
      diagnostic: hostCheck.reason,
    };
  }

  // Use fixture transport in tests
  if (fixtureTransport) {
    return fixtureTransport(url, method);
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(
    () => controller.abort("timeout"),
    bounds.requestTimeoutMs,
  );

  // Merge external cancellation signal
  const externalSignal = options.cancellationSignal;
  let externalAbortListener: (() => void) | undefined;
  if (externalSignal) {
    externalAbortListener = () => controller.abort("cancelled");
    externalSignal.addEventListener("abort", externalAbortListener);
  }

  try {
    const headers: Record<string, string> = {
      Accept: "application/vnd.github+json",
      "User-Agent": FUZIT_USER_AGENT,
      "X-GitHub-Api-Version": GITHUB_API_VERSION,
    };

    // Inject auth header from opaque credential handle — never logged
    const authHeader = options.credential?._getAuthorizationHeader();
    if (authHeader) {
      headers["Authorization"] = authHeader;
    }

    let response: Response;
    try {
      response = await fetch(url, {
        method,
        headers,
        signal: controller.signal,
        redirect: "manual", // we handle redirects ourselves
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "network error";
      if (
        message.includes("timeout") ||
        controller.signal.reason === "timeout"
      ) {
        return { ok: false, kind: "timeout", diagnostic: "Request timed out" };
      }
      if (controller.signal.reason === "cancelled") {
        return {
          ok: false,
          kind: "cancelled",
          diagnostic: "Request cancelled",
        };
      }
      return {
        ok: false,
        kind: "network-error",
        diagnostic: `Network error: ${sanitizeErrorMessage(message)}`,
      };
    }

    // Handle manual redirect
    if (response.status >= 300 && response.status < 400) {
      const location = response.headers.get("location");
      if (!location) {
        return {
          ok: false,
          kind: "untrusted-redirect",
          diagnostic: "Redirect with missing Location header",
        };
      }
      if (!isRedirectHostAllowed(location, options.allowedHosts)) {
        return {
          ok: false,
          kind: "untrusted-redirect",
          diagnostic: `Redirect to disallowed host rejected (${sanitizeRedirectUrl(location)})`,
        };
      }
      // Follow redirect recursively with decremented limit
      return githubRequest(location, {
        ...options,
        bounds: {
          ...bounds,
          maxRedirects: bounds.maxRedirects - 1,
        },
      });
    }

    // Rate limit
    if (response.status === 429 || response.status === 403) {
      const retryAfter = response.headers.get("retry-after");
      const remaining = response.headers.get("x-ratelimit-remaining");
      if (remaining === "0" || response.status === 429) {
        const parsedRetry = retryAfter ? Number.parseInt(retryAfter, 10) : NaN;
        if (Number.isFinite(parsedRetry)) {
          return {
            ok: false,
            kind: "rate-limited",
            status: response.status,
            diagnostic: "GitHub API rate limit reached",
            retryAfterSeconds: parsedRetry,
          };
        }
        return {
          ok: false,
          kind: "rate-limited",
          status: response.status,
          diagnostic: "GitHub API rate limit reached",
        };
      }
    }

    // 5xx server errors
    if (response.status >= 500) {
      return {
        ok: false,
        kind: "server-error",
        status: response.status,
        diagnostic: `GitHub API server error (HTTP ${response.status})`,
      };
    }

    // Read body with size limit
    const bodyResult = await readBoundedBody(response, bounds.maxResponseBytes);
    if (!bodyResult.ok) {
      return bodyResult;
    }

    // Extract safe headers (excluding authorization)
    const safeHeaders: Record<string, string> = {};
    for (const [key, value] of response.headers.entries()) {
      if (key.toLowerCase() !== "authorization") {
        safeHeaders[key] = value;
      }
    }

    return {
      ok: true,
      status: response.status,
      headers: safeHeaders,
      body: bodyResult.body,
    };
  } finally {
    clearTimeout(timeoutId);
    if (externalSignal && externalAbortListener) {
      externalSignal.removeEventListener("abort", externalAbortListener);
    }
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function validateRequestHost(
  url: string,
  allowedHosts: readonly string[],
): { ok: true } | { ok: false; reason: string } {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, reason: "Invalid request URL" };
  }
  if (parsed.protocol !== "https:") {
    return { ok: false, reason: "Only https requests are allowed" };
  }
  const allowed = allowedHosts.some(
    (h) =>
      parsed.hostname === h ||
      parsed.hostname.endsWith(`.${h}`) ||
      // handle "host/api/v3" style apiHost entries
      h.startsWith(parsed.hostname),
  );
  if (!allowed) {
    return {
      ok: false,
      reason: `Host '${parsed.hostname}' is not in the allowed host set`,
    };
  }
  return { ok: true };
}

function isRedirectHostAllowed(
  location: string,
  allowedHosts: readonly string[],
): boolean {
  try {
    const url = new URL(location);
    if (url.protocol !== "https:") return false;
    return allowedHosts.some(
      (h) =>
        url.hostname === h ||
        url.hostname.endsWith(`.${h}`) ||
        h.startsWith(url.hostname),
    );
  } catch {
    return false;
  }
}

function sanitizeErrorMessage(message: string): string {
  // Remove anything that looks like a URL with credentials
  return message.replace(/https?:\/\/[^@\s]+@[^\s]+/g, "<url>");
}

function sanitizeRedirectUrl(url: string): string {
  try {
    const parsed = new URL(url);
    return `${parsed.protocol}//${parsed.hostname}${parsed.pathname}`;
  } catch {
    return "<invalid-url>";
  }
}

async function readBoundedBody(
  response: Response,
  maxBytes: number,
): Promise<{ ok: true; body: string } | TransportFailure> {
  const contentLength = response.headers.get("content-length");
  if (contentLength) {
    const length = Number.parseInt(contentLength, 10);
    if (Number.isFinite(length) && length > maxBytes) {
      return {
        ok: false,
        kind: "oversized",
        diagnostic: `Response exceeds ${maxBytes} byte limit (Content-Length: ${length})`,
      };
    }
  }

  // Stream with byte counting
  const reader = response.body?.getReader();
  if (!reader) {
    return { ok: true, body: "" };
  }

  const chunks: Uint8Array[] = [];
  let totalBytes = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    totalBytes += value.byteLength;
    if (totalBytes > maxBytes) {
      reader.cancel();
      return {
        ok: false,
        kind: "oversized",
        diagnostic: `Response body exceeds ${maxBytes} byte limit`,
      };
    }
    chunks.push(value);
  }

  const combined = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.byteLength;
  }

  return { ok: true, body: new TextDecoder().decode(combined) };
}

/**
 * Tests for GitHub authentication broker (GH-004).
 */

import { describe, it } from "vitest";
import { expect } from "vitest";
import {
  resolveCredential,
  describeCredential,
  assertNoTokenInObject,
} from "@fuzit/provider-github";

describe("GH-004: authentication", () => {
  it("public anonymous mode (no env vars)", () => {
    const cred = resolveCredential({ host: "github.com", env: {} });
    expect(cred.isAuthenticated).toBe(false);
    expect(cred.source).toBe("anonymous");
    expect(cred._getAuthorizationHeader()).toBe(null);
  });

  it("FUZIT token precedence over GH_TOKEN", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: {
        FUZIT_GITHUB_TOKEN: "fuzit-secret-token",
        GH_TOKEN: "gh-fallback-token",
      },
    });
    expect(cred.isAuthenticated).toBe(true);
    expect(cred.source).toBe("FUZIT_GITHUB_TOKEN");
  });

  it("GH_TOKEN fallback when FUZIT_GITHUB_TOKEN absent", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { GH_TOKEN: "gh-fallback-token" },
    });
    expect(cred.isAuthenticated).toBe(true);
    expect(cred.source).toBe("GH_TOKEN");
  });

  it("no token in credential handle JSON serialization", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { FUZIT_GITHUB_TOKEN: "ghp_supersecretvalue12345" },
    });
    // Serialize the handle's safe fields only
    const safeRepresentation = {
      isAuthenticated: cred.isAuthenticated,
      host: cred.host,
      source: cred.source,
    };
    const serialized = JSON.stringify(safeRepresentation);
    expect(serialized).not.toContain("ghp_supersecretvalue12345");
    expect(serialized).not.toContain("supersecret");
  });

  it("no token in cache keys or command arguments simulation", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { FUZIT_GITHUB_TOKEN: "ghp_cachetest12345" },
    });
    // Simulate cache key construction — must use only host, not token
    const cacheKey = `github:${cred.host}:owner:repo`;
    expect(cacheKey).not.toContain("ghp_");
    expect(cacheKey).not.toContain("cachetest");
  });

  it("no token in git config or remote URL simulation", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { FUZIT_GITHUB_TOKEN: "ghp_gitconfigtest12345" },
    });
    // Simulate remote URL construction — must never embed token
    const remoteUrl = `https://github.com/owner/repo.git`;
    expect(remoteUrl).not.toContain(cred.source);
    // The token itself is accessed only through _getAuthorizationHeader
    // and must not appear in URLs
    expect(remoteUrl).not.toMatch(/ghp_/);
  });

  it("describeCredential does not include token value", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { FUZIT_GITHUB_TOKEN: "ghp_describetest12345" },
    });
    const description = describeCredential(cred);
    expect(description).not.toContain("ghp_describetest12345");
    expect(description).toContain("github.com");
    expect(description).toContain("FUZIT_GITHUB_TOKEN");
  });

  it("assertNoTokenInObject throws on token-shaped value", () => {
    expect(() =>
      assertNoTokenInObject({ [REDACTED:api-key] }, "test"),
    ).toThrow(/Security violation/);
  });

  it("assertNoTokenInObject passes on clean object", () => {
    expect(() =>
      assertNoTokenInObject({ host: "github.com", owner: "acme" }, "test"),
    ).not.toThrow();
  });
});

/**
 * Tests for GitHub provider capabilities (GH-006).
 */

import { describe, it } from "vitest";
import { expect } from "vitest";
import {
  resolveCapabilities,
  anonymousCapabilities,
  resolveCredential,
} from "@fuzit/provider-github";
import type { GitHubHostIdentity } from "@fuzit/schemas";

const githubCom: GitHubHostIdentity = {
  webHost: "github.com",
  apiHost: "api.github.com",
  isEnterprise: false,
};

const enterprise: GitHubHostIdentity = {
  webHost: "ghe.example.com",
  apiHost: "ghe.example.com/api/v3",
  isEnterprise: true,
};

describe("GH-006: provider capabilities", () => {
  it("anonymous public capability lists all types as available or unknown", () => {
    const cap = anonymousCapabilities(githubCom);
    expect(cap.isAuthenticated).toBe(false);
    expect(cap.credentialSource).toBe("anonymous");
    expect(cap.capabilities.length).toBeGreaterThan(0);
    const states = cap.capabilities.map((c) => c.state);
    // All should be available or unknown, none unavailable for anonymous public
    expect(states.every((s) => s === "available" || s === "unknown")).toBe(
      true,
    );
  });

  it("authenticated capability fixture marks all types available", () => {
    const cred = resolveCredential({
      host: "github.com",
      env: { FUZIT_GITHUB_TOKEN: "fake-token-for-test" },
    });
    const cap = resolveCapabilities(githubCom, cred);
    expect(cap.isAuthenticated).toBe(true);
    const unavailable = cap.capabilities.filter(
      (c) => c.state === "unavailable",
    );
    expect(unavailable).toHaveLength(0);
  });

  it("missing issue/check permission produces partial diagnostic", () => {
    const cred = resolveCredential({ host: "github.com", env: {} });
    const cap = resolveCapabilities(githubCom, cred, {
      missingPermissions: ["issue", "check-run"],
    });
    expect(cap.partial).toBe(true);
    const issueCapability = cap.capabilities.find(
      (c) => c.recordType === "issue",
    );
    expect(issueCapability?.state).toBe("unavailable");
    expect(issueCapability?.reason).toBe("permission-denied");
    expect(cap.diagnostics.length).toBeGreaterThan(0);
    // Diagnostics must not contain tokens
    for (const d of cap.diagnostics) {
      expect(d).not.toMatch(/ghp_|Bearer|token/i);
    }
  });

  it("unknown enterprise version resolves with enterprise host", () => {
    const cred = resolveCredential({ host: "ghe.example.com", env: {} });
    const cap = resolveCapabilities(enterprise, cred);
    expect(cap.host.isEnterprise).toBe(true);
    expect(cap.host.webHost).toBe("ghe.example.com");
  });

  it("capabilities have deterministic ordering", () => {
    const cred = resolveCredential({ host: "github.com", env: {} });
    const cap1 = resolveCapabilities(githubCom, cred);
    const cap2 = resolveCapabilities(githubCom, cred);
    const types1 = cap1.capabilities.map((c) => c.recordType);
    const types2 = cap2.capabilities.map((c) => c.recordType);
    expect(types1).toEqual(types2);
  });
});

/**
 * Tests for pagination, rate limits, revalidation (GH-008).
 */

import { describe, it } from "vitest";
import { expect } from "vitest";
import {
  fetchAllPages,
  parseLinkHeader,
  extractRateLimit,
  resolveCredential,
} from "@fuzit/provider-github";

const cred = resolveCredential({ host: "github.com", env: {} });
const ALLOWED = ["github.com", "api.github.com"];

describe("GH-008: pagination and rate limits", () => {
  it("multi-page response collects all items", async () => {
    let call = 0;
    const result = await fetchAllPages<string>(
      "https://api.github.com/items",
      (body) => JSON.parse(body) as string[],
      {
        credential: cred,
        allowedHosts: ALLOWED,
        fixtureTransport: async () => {
          call++;
          if (call === 1) {
            return {
              ok: true,
              status: 200,
              headers: {
                "content-type": "application/json",
                link: '<https://api.github.com/items?page=2>; rel="next"',
              },
              body: JSON.stringify(["a", "b"]),
            };
          }
          return {
            ok: true,
            status: 200,
            headers: { "content-type": "application/json" },
            body: JSON.stringify(["c"]),
          };
        },
      },
    );
    expect(result.items).toEqual(["a", "b", "c"]);
    expect(result.isComplete).toBe(true);
    expect(result.pagesConsumed).toBe(2);
  });

  it("page ceiling produces partial result", async () => {
    const result = await fetchAllPages<string>(
      "https://api.github.com/items",
      (body) => JSON.parse(body) as string[],
      {
        credential: cred,
        allowedHosts: ALLOWED,
        bounds: { maxPages: 1 },
        fixtureTransport: async () => ({
          ok: true,
          status: 200,
          headers: {
            link: '<https://api.github.com/items?page=2>; rel="next"',
          },
          body: JSON.stringify(["a", "b"]),
        }),
      },
    );
    expect(result.isComplete).toBe(false);
    expect(result.partialReason).toMatch(/ceiling/i);
    expect(result.pagesConsumed).toBe(1);
  });

  it("304 revalidation stops pagination", async () => {
    const result = await fetchAllPages<string>(
      "https://api.github.com/items",
      (body) => JSON.parse(body) as string[],
      {
        credential: cred,
        allowedHosts: ALLOWED,
        fixtureTransport: async () => ({
          ok: true,
          status: 304,
          headers: {},
          body: "",
        }),
      },
    );
    expect(result.pagesConsumed).toBe(0);
    expect(result.partialReason).toMatch(/304/);
  });

  it("primary rate limit exhausted produces partial", async () => {
    const result = await fetchAllPages<string>(
      "https://api.github.com/items",
      (body) => JSON.parse(body) as string[],
      {
        credential: cred,
        allowedHosts: ALLOWED,
        fixtureTransport: async () => ({
          ok: false,
          kind: "rate-limited" as const,
          status: 429,
          diagnostic: "Rate limit reached",
          retryAfterSeconds: 30,
        }),
      },
    );
    expect(result.isComplete).toBe(false);
    expect(result.rateLimit.isExhausted).toBe(true);
    expect(result.rateLimit.retryAfterSeconds).toBe(30);
  });

  it("secondary limit/Retry-After header parsed", () => {
    const state = extractRateLimit({
      "x-ratelimit-remaining": "0",
      "x-ratelimit-limit": "60",
      "retry-after": "45",
    });
    expect(state.isExhausted).toBe(true);
    expect(state.retryAfterSeconds).toBe(45);
  });

  it("cancellation between pages (fixture simulates)", async () => {
    let call = 0;
    const result = await fetchAllPages<string>(
      "https://api.github.com/items",
      (body) => JSON.parse(body) as string[],
      {
        credential: cred,
        allowedHosts: ALLOWED,
        fixtureTransport: async () => {
          call++;
          if (call === 1) {
            return {
              ok: true,
              status: 200,
              headers: {
                link: '<https://api.github.com/items?page=2>; rel="next"',
              },
              body: JSON.stringify(["x"]),
            };
          }
          return {
            ok: false,
            kind: "cancelled" as const,
            diagnostic: "Request cancelled",
          };
        },
      },
    );
    expect(result.items).toEqual(["x"]);
    expect(result.isComplete).toBe(false);
    expect(result.partialReason).toMatch(/Fetch failed/);
  });
});

describe("parseLinkHeader", () => {
  it("parses next and last", () => {
    const links = parseLinkHeader(
      '<https://a.com/page2>; rel="next", <https://a.com/page5>; rel="last"',
    );
    expect(links.next).toBe("https://a.com/page2");
    expect(links.last).toBe("https://a.com/page5");
    expect(links.prev).toBe(null);
  });

  it("returns all null for empty header", () => {
    const links = parseLinkHeader(null);
    expect(links.next).toBe(null);
  });
});

/**
 * Tests for repository resolution (GH-007).
 */

import { describe, it } from "vitest";
import { expect } from "vitest";
import { resolveRepository, resolveCredential } from "@fuzit/provider-github";
import type { GitHubHostIdentity } from "@fuzit/schemas";

const host: GitHubHostIdentity = {
  webHost: "github.com",
  apiHost: "api.github.com",
  isEnterprise: false,
};
const enterpriseHost: GitHubHostIdentity = {
  webHost: "ghe.example.com",
  apiHost: "ghe.example.com/api/v3",
  isEnterprise: true,
};
const cred = resolveCredential({ host: "github.com", env: {} });
const ALLOWED = ["github.com", "api.github.com"];

function fixture(status: number, body: object | null) {
  return async () => ({
    ok: true as const,
    status,
    headers: { "content-type": "application/vnd.github+json" },
    body: body ? JSON.stringify(body) : "",
  });
}

const publicRepo = {
  id: 1,
  node_id: "R_abc",
  name: "repo",
  full_name: "owner/repo",
  owner: { login: "owner" },
  private: false,
  visibility: "public",
  default_branch: "main",
  archived: false,
  disabled: false,
  fork: false,
  html_url: "https://github.com/owner/repo",
};

describe("GH-007: repository resolution", () => {
  it("public repository resolves correctly", async () => {
    const result = await resolveRepository({
      host,
      owner: "owner",
      repo: "repo",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(200, publicRepo),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.record.visibility).toBe("public");
    expect(result.record.defaultBranch).toBe("main");
    expect(result.record.owner).toBe("owner");
    expect(result.record.webUrl).not.toMatch(/@/); // no credentials
  });

  it("private authorized repository resolves", async () => {
    const priv = { ...publicRepo, private: true, visibility: "private" };
    const result = await resolveRepository({
      host,
      owner: "owner",
      repo: "repo",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(200, priv),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.record.visibility).toBe("private");
  });

  it("transferred repository detects canonical URL change", async () => {
    const transferred = {
      ...publicRepo,
      owner: { login: "new-owner" },
      full_name: "new-owner/repo",
    };
    const result = await resolveRepository({
      host,
      owner: "old-owner",
      repo: "repo",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(200, transferred),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.record.canonicalUrlChanged).toBe(true);
    expect(result.record.priorFullName).toBe("old-owner/repo");
    expect(result.record.owner).toBe("new-owner");
  });

  it("archived repository", async () => {
    const archived = { ...publicRepo, archived: true };
    const result = await resolveRepository({
      host,
      owner: "owner",
      repo: "repo",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(200, archived),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.record.isArchived).toBe(true);
  });

  it("enterprise API path used for enterprise host", async () => {
    // The fixture just returns a valid repo; we're verifying the host metadata
    const result = await resolveRepository({
      host: enterpriseHost,
      owner: "owner",
      repo: "repo",
      credential: resolveCredential({ host: "ghe.example.com", env: {} }),
      allowedHosts: ["ghe.example.com"],
      fixtureTransport: fixture(200, publicRepo),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.record.host.isEnterprise).toBe(true);
  });

  it("404 returns not-found", async () => {
    const result = await resolveRepository({
      host,
      owner: "owner",
      repo: "missing",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(404, null),
    });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.kind).toBe("not-found");
  });

  it("403 returns forbidden", async () => {
    const result = await resolveRepository({
      host,
      owner: "owner",
      repo: "private",
      credential: cred,
      allowedHosts: ALLOWED,
      fixtureTransport: fixture(403, null),
    });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.kind).toBe("forbidden");
  });
});

/**
 * Tests for GitHub source URL and shorthand parsing (GH-002).
 */

import { describe, it } from "vitest";
import { expect } from "vitest";
import {
  parseGitHubUrl,
  parseOwnerRepo,
  parseOwnerRepoHash,
  parseNumericWithRepo,
} from "@fuzit/provider-github";

// ---------------------------------------------------------------------------
// URL parsing
// ---------------------------------------------------------------------------

describe("parseGitHubUrl: github.com repository", () => {
  it("parses basic repository URL", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.ref.kind).toBe("github-repository");
    expect(result.ref.host.webHost).toBe("github.com");
    expect(result.ref.host.apiHost).toBe("api.github.com");
    expect(result.ref.host.isEnterprise).toBe(false);
    expect(result.ref.owner).toBe("owner");
    expect(result.ref.repo).toBe("repo");
  });

  it("strips .git suffix", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo.git");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.ref.kind).toBe("github-repository");
  });

  it("parses tree/branch URL as repository with revision", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo/tree/main");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    if (result.ref.kind !== "github-repository") throw new Error("wrong kind");
    expect(result.ref.revision).toBe("main");
  });
});

describe("parseGitHubUrl: pull request URL", () => {
  it("parses PR URL", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo/pull/123");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.ref.kind).toBe("github-pull-request");
    if (result.ref.kind !== "github-pull-request") return;
    expect(result.ref.number).toBe(123);
    expect(result.ref.owner).toBe("owner");
    expect(result.ref.repo).toBe("repo");
  });

  it("rejects PR URL with non-numeric number", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo/pull/abc");
    expect(result.ok).toBe(false);
  });
});

describe("parseGitHubUrl: issue URL", () => {
  it("parses issue URL", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo/issues/456");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.ref.kind).toBe("github-issue");
    if (result.ref.kind !== "github-issue") return;
    expect(result.ref.number).toBe(456);
  });
});

describe("parseGitHubUrl: enterprise URL", () => {
  it("parses GitHub Enterprise repository URL", () => {
    const result = parseGitHubUrl("https://github.example.com/owner/repo");
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    if (result.ref.kind !== "github-repository") return;
    expect(result.ref.host.isEnterprise).toBe(true);
    expect(result.ref.host.webHost).toBe("github.example.com");
    expect(result.ref.host.apiHost).toBe("github.example.com/api/v3");
  });

  it("parses GitHub Enterprise PR URL", () => {
    const result = parseGitHubUrl(
      "https://github.example.com/owner/repo/pull/42",
    );
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.ref.kind).toBe("github-pull-request");
  });
});

describe("parseGitHubUrl: credential-bearing URL rejection", () => {
  it("rejects URL with username", () => {
    const result = parseGitHubUrl("https://user@github.com/owner/repo");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.reason).toMatch(/credential/i);
    }
  });

  it("rejects URL with username:password", () => {
    const credentialBearingUrl = [
      "https://user",
      ":",
      "pass",
      "@github.com/owner/repo",
    ].join("");
    const result = parseGitHubUrl(credentialBearingUrl);
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.reason).toMatch(/credential/i);
    }
  });

  it("rejects http:// scheme", () => {
    const result = parseGitHubUrl("http://github.com/owner/repo");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.reason).toMatch(/scheme/i);
    }
  });

  it("rejects URL fragment with content", () => {
    const result = parseGitHubUrl("https://github.com/owner/repo#readme");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.reason).toMatch(/fragment/i);
    }
  });
});

describe("parseGitHubUrl: unsupported paths", () => {
  it("rejects URL with only one path segment", () => {
    const result = parseGitHubUrl("https://github.com/owner");
    expect(result.ok).toBe(false);
  });

  it("rejects unsupported path segment (compare)", () => {
    const result = parseGitHubUrl(
      "https://github.com/owner/repo/compare/main...dev",
    );
    expect(result.ok).toBe(false);
  });
});

