import type { Renderer, RendererOptionSchema } from "@fuzit/renderer-core";
import { contextBundleSchema, type ContextBundle } from "@fuzit/schemas";

export interface JsonRendererOptions {
  readonly pretty: boolean;
}

export function renderJson(
  bundle: ContextBundle,
  options: JsonRendererOptions = { pretty: true },
): string {
  const validated = contextBundleSchema.parse(bundle);
  const serialized = JSON.stringify(
    validated,
    (_key, value: unknown) => {
      if (
        typeof value === "number" &&
        Number.isInteger(value) &&
        !Number.isSafeInteger(value)
      )
        throw new RangeError("JSON renderer refuses unsafe integers.");
      return value;
    },
    options.pretty ? 2 : undefined,
  );
  return `${serialized}\n`;
}

const jsonOptions: RendererOptionSchema<JsonRendererOptions> = {
  parse(value): JsonRendererOptions {
    if (typeof value !== "object" || value === null || Array.isArray(value))
      throw new TypeError("JSON renderer options must be an object.");
    const entries = Object.entries(value);
    if (
      entries.some(([key]) => key !== "pretty") ||
      ("pretty" in value && typeof value.pretty !== "boolean")
    )
      throw new TypeError("JSON renderer accepts only boolean pretty.");
    return { pretty: "pretty" in value ? value.pretty === true : true };
  },
};

export const jsonRenderer: Renderer = {
  metadata: {
    schemaVersion: 1,
    format: "json",
    mediaType: "application/json",
    extension: ".json",
    capabilities: { binary: false, diagnostics: true, provenance: true },
    deterministic: true,
  },
  options: jsonOptions,
  render: (bundle, _items, options) =>
    renderJson(bundle, jsonOptions.parse(options)),
};

import { describe, expect, it } from "vitest";

import { createContextBundle } from "@fuzit/core";
import { contextBundleSchema } from "@fuzit/schemas";

import { renderJson } from "../src/index.js";

function bundle(overrides: Record<string, unknown> = {}) {
  return createContextBundle({
    schemaVersion: 1,
    source: { kind: "repository", root: "." },
    revision: null,
    items: [],
    redactionSummary: { findings: 0, redactedItems: 0, omittedItems: 0 },
    warnings: [],
    failedSources: [],
    budget: { bytes: 0, tokens: 0, truncated: false },
    ...overrides,
  });
}

describe("canonical JSON renderer", () => {
  it("supports pretty and compact modes", () => {
    expect(renderJson(bundle(), { pretty: true })).toContain("\n  ");
    expect(renderJson(bundle(), { pretty: false }).split("\n")).toHaveLength(2);
  });

  it("preserves Unicode and validates against the schema", () => {
    const output = renderJson(bundle({ warnings: ["世界"] }));
    expect(output).toContain("世界");
    expect(contextBundleSchema.parse(JSON.parse(output))).toBeDefined();
  });

  it("avoids unsafe large integers", () => {
    const value = bundle();
    Object.assign(value.budget, { bytes: Number.MAX_SAFE_INTEGER + 1 });
    expect(() => renderJson(value)).toThrow();
  });

  it("renders redaction and partial bundle metadata", () => {
    const output = JSON.parse(
      renderJson(
        bundle({
          redactionSummary: {
            findings: 1,
            redactedItems: 1,
            omittedItems: 0,
          },
          warnings: ["partial"],
          failedSources: ["a.ts"],
        }),
      ),
    ) as Record<string, unknown>;
    expect(output).toMatchObject({
      redactionSummary: { findings: 1, redactedItems: 1 },
      warnings: ["partial"],
      failedSources: ["a.ts"],
    });
  });
});

