import {
  assertSecurityFilteredItem,
  type SecurityFilteredItem,
} from "@fuzit/core";
import type { ContextBundle } from "@fuzit/schemas";
import { noRendererOptions, type Renderer } from "@fuzit/renderer-core";

function fenceFor(content: string): string {
  const longest =
    [...content.matchAll(/`+/g)].reduce(
      (maximum, match) => Math.max(maximum, match[0].length),
      0,
    ) + 1;
  return "`".repeat(Math.max(3, longest));
}

export function renderMarkdown(
  bundle: ContextBundle,
  items: readonly SecurityFilteredItem[],
): string {
  for (const item of items) assertSecurityFilteredItem(item);
  const ordered = [...items].sort((left, right) =>
    left.path.localeCompare(right.path, "en"),
  );
  const lines = [
    ...(bundle.instruction ? ["## User Instruction", "", bundle.instruction, "", "---", ""] : []),
    "# Fuzit Context Bundle",
    "",
    `- Bundle: \`${bundle.id}\``,
    `- Root: \`${bundle.source.root}\``,
    `- Files: ${ordered.length}`,
    `- Estimated tokens: ${bundle.budget.tokens}`,
    "",
    "## Manifest",
    "",
    "```json",
    JSON.stringify(bundle),
    "```",
  ];

  for (const item of ordered) {
    lines.push(
      "",
      "---",
      "",
      `## ${item.path}`,
      "",
      `Provenance: ${item.provenance.source} (${item.provenance.confidenceBasis})`,
    );
    if (item.contentStatus === "omitted" || item.content === null) {
      lines.push("", "[CONTENT OMITTED]");
      continue;
    }
    if (item.findings.length > 0) lines.push("", "[CONTENT REDACTED]");
    if (item.contentStatus === "truncated")
      lines.push("", "[CONTENT TRUNCATED]");
    const fence = fenceFor(item.content);
    lines.push("", fence, item.content, fence);
  }

  if (bundle.warnings.length > 0 || bundle.failedSources.length > 0) {
    lines.push("", "## Diagnostics", "");
    for (const warning of bundle.warnings) lines.push(`- Warning: ${warning}`);
    for (const source of bundle.failedSources)
      lines.push(`- Failed source: ${source}`);
  }

  return `${lines.join("\n")}\n`;
}

export const markdownRenderer: Renderer = {
  metadata: {
    schemaVersion: 1,
    format: "markdown",
    mediaType: "text/markdown",
    extension: ".md",
    capabilities: { binary: false, diagnostics: true, provenance: true },
    deterministic: true,
  },
  options: noRendererOptions,
  render: (bundle, items) => renderMarkdown(bundle, items),
};

import { describe, expect, it } from "vitest";

import {
  createContextBundle,
  securityFilter,
  type SecurityFilteredItem,
} from "@fuzit/core";
import type { FileContextItem } from "@fuzit/schemas";

import { renderMarkdown } from "../src/index.js";

const digest = "a".repeat(64);

async function filtered(
  path: string,
  content: string,
  status: FileContextItem["contentStatus"] = "complete",
): Promise<SecurityFilteredItem> {
  const result = await securityFilter({
    path,
    readContent: async () => content,
    createItem: (safeContent) => ({
      schemaVersion: 1,
      id: `file:${digest}`,
      kind: "file",
      path,
      content: safeContent,
      contentStatus: status,
      provenance: { source: "scanner", confidenceBasis: "test fixture" },
      lifecycle: "source",
      sensitivity: "unclassified",
      sha256: digest,
      transformations: [],
    }),
  });
  if (result.status !== "success") throw new Error(result.reason);
  return result.item;
}

function bundle(paths: readonly string[]) {
  return createContextBundle({
    schemaVersion: 1,
    source: { kind: "repository", root: "." },
    revision: null,
    items: paths.map((path) => ({
      id: `file:${path}`,
      path,
      sha256: digest,
      contentStatus: "complete",
      redacted: false,
    })),
    redactionSummary: { findings: 0, redactedItems: 0, omittedItems: 0 },
    warnings: [],
    failedSources: [],
    budget: { bytes: 0, tokens: 0, truncated: false },
  });
}

describe("Markdown renderer", () => {
  it("escapes embedded fences", async () => {
    expect(
      renderMarkdown(bundle(["a.md"]), [await filtered("a.md", "```")]),
    ).toContain("````\n```\n````");
  });

  it("marks binary omission", async () => {
    const item = await filtered("a.bin", "", "omitted");
    expect(renderMarkdown(bundle(["a.bin"]), [item])).toContain(
      "[CONTENT OMITTED]",
    );
  });

  it("marks redaction", async () => {
    const value = ["SYNTHETIC", "TOKEN", "VALUE", "123456"].join("_");
    const output = renderMarkdown(bundle(["a.ts"]), [
      await filtered("a.ts", `token=${value}`),
    ]);
    expect(output).toContain("[CONTENT REDACTED]");
    expect(output).not.toContain(value);
  });

  it("marks truncation and renders empty files", async () => {
    expect(
      renderMarkdown(bundle(["a.ts"]), [
        await filtered("a.ts", "", "truncated"),
      ]),
    ).toContain("[CONTENT TRUNCATED]");
    expect(
      renderMarkdown(bundle(["a.ts"]), [await filtered("a.ts", "")]),
    ).toContain("```\n\n```");
  });

  it("orders paths and repeats byte-identically", async () => {
    const items = [await filtered("b.ts", "b"), await filtered("a.ts", "a")];
    const manifest = bundle(["b.ts", "a.ts"]);
    const first = renderMarkdown(manifest, items);
    expect(first.indexOf("## a.ts")).toBeLessThan(first.indexOf("## b.ts"));
    expect(renderMarkdown(manifest, items)).toBe(first);
  });
});

