      content: status === "omitted" ? null : safe,
      contentStatus: status,
      provenance: { source: "scanner", confidenceBasis: "test" },
      lifecycle: "source",
      sensitivity: "unclassified",
      sha256: digest,
      transformations: [],
    }),
  });
  if (result.status !== "success") throw new Error(result.reason);
