import { open, lstat } from "node:fs/promises";
import { extname } from "node:path";

import type { RepositoryRelativePath } from "@fuzit/core";
import type { FileRecord } from "@fuzit/schemas";

const PREFIX_BYTES = 4096;

const languages: Readonly<Record<string, string>> = {
  ".ts": "TypeScript",
  ".tsx": "TypeScript",
  ".js": "JavaScript",
  ".jsx": "JavaScript",
  ".mjs": "JavaScript",
  ".cjs": "JavaScript",
  ".json": "JSON",
  ".md": "Markdown",
  ".mdx": "Markdown",
  ".py": "Python",
  ".go": "Go",
  ".java": "Java",
  ".css": "CSS",
  ".scss": "SCSS",
  ".sass": "Sass",
  ".html": "HTML",
  ".xml": "XML",
  ".yaml": "YAML",
  ".yml": "YAML",
  ".toml": "TOML",
  ".rs": "Rust",
  ".rb": "Ruby",
  ".php": "PHP",
  ".cs": "C#",
  ".cpp": "C++",
  ".c": "C",
  ".h": "C/C++ Header",
  ".sh": "Shell",
  ".ps1": "PowerShell",
  ".sql": "SQL",
};

export interface ClassifyFileOptions {
  readonly readPrefix?: (
    path: string,
    maximumBytes: number,
  ) => Promise<Uint8Array>;
}

async function defaultReadPrefix(path: string, maximumBytes: number) {
  const handle = await open(path, "r");
  try {
    const buffer = Buffer.alloc(maximumBytes);
    const { bytesRead } = await handle.read(buffer, 0, maximumBytes, 0);
    return buffer.subarray(0, bytesRead);
  } finally {
    await handle.close();
  }
}

export async function classifyFile(
  absolutePath: string,
  path: RepositoryRelativePath,
  options: ClassifyFileOptions = {},
): Promise<FileRecord> {
  const metadata = await lstat(absolutePath);
  const symlink = metadata.isSymbolicLink();
  const extension = extname(path);
  let prefix: Uint8Array = new Uint8Array();
  let readable = true;
  if (!symlink && metadata.isFile()) {
    try {
      prefix = await (options.readPrefix ?? defaultReadPrefix)(
        absolutePath,
        PREFIX_BYTES,
      );
    } catch {
      readable = false;
    }
  }
  const binary = prefix.includes(0);
  const prefixText = binary ? "" : Buffer.from(prefix).toString("utf8");
  const languageName = languages[extension.toLowerCase()] ?? "Unknown";
  return {
    schemaVersion: 1,
    path,
    kind: symlink
      ? "symlink"
      : binary
        ? "binary"
        : metadata.isFile()
          ? "text"
          : "other",
    extension,
    language: {
      name: languageName,
      confidence: languageName === "Unknown" ? 0 : 0.8,
    },
    sizeBytes: metadata.size,
    symlink,
    generated:
      !path.endsWith(".gitignore") &&
      /(?:^|\W)generated(?:\W|$)|do not edit/i.test(prefixText),
    vendored: path
      .split("/")
      .some((segment) =>
        ["vendor", "vendors", "third_party"].includes(segment),
      ),
    readable,
  };
}

import { open, stat } from "node:fs/promises";

import { sha256Hex } from "@fuzit/core";

export interface TextContentResult {
  readonly schemaVersion: 1;
  readonly status: "complete" | "truncated" | "omitted" | "changed";
  readonly encoding: "utf-8" | "utf-16le" | "utf-16be" | "invalid";
  readonly content: string | null;
  readonly bytesRead: number;
  readonly truncated: boolean;
  readonly sha256: string;
}

export async function readTextContent(
  path: string,
  options: {
    readonly maximumBytes?: number;
    readonly signal?: AbortSignal;
  } = {},
): Promise<TextContentResult> {
  const maximumBytes = options.maximumBytes ?? 64 * 1024;
  const before = await stat(path);
  const handle = await open(path, "r");
  const chunks: Buffer[] = [];
  let total = 0;
  let truncated = false;
  try {
    while (total <= maximumBytes) {
      if (options.signal?.aborted)
        throw new DOMException("Cancelled", "AbortError");
      const buffer = Buffer.alloc(Math.min(8192, maximumBytes + 1 - total));
      const { bytesRead } = await handle.read(buffer, 0, buffer.length, null);
      if (bytesRead === 0) break;
      chunks.push(buffer.subarray(0, bytesRead));
      total += bytesRead;
      if (total > maximumBytes) {
        truncated = true;
        break;
      }
    }
  } finally {
    await handle.close();
  }
  const bytes = Buffer.concat(chunks).subarray(0, maximumBytes);
  const after = await stat(path);
  const changed =
    before.size !== after.size || before.mtimeMs !== after.mtimeMs;
  let encoding: TextContentResult["encoding"] = "utf-8";
  let body: Uint8Array = bytes;
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf)
    body = bytes.subarray(3);
  else if (bytes[0] === 0xff && bytes[1] === 0xfe) {
    encoding = "utf-16le";
    body = bytes.subarray(2);
  } else if (bytes[0] === 0xfe && bytes[1] === 0xff) {
    const swapped = Buffer.from(bytes.subarray(2));
    for (let index = 0; index + 1 < swapped.length; index += 2)
      [swapped[index], swapped[index + 1]] = [
        swapped[index + 1] ?? 0,
        swapped[index] ?? 0,
      ];
    body = swapped;
    encoding = "utf-16le";
  }
  let content: string | null;
  try {
    content = new TextDecoder(encoding, { fatal: true }).decode(body);
  } catch {
    encoding = "invalid";
    content = null;
  }
  return {
    schemaVersion: 1,
    status: changed
      ? "changed"
      : content === null
        ? "omitted"
        : truncated
          ? "truncated"
          : "complete",
    encoding,
    content,
    bytesRead: bytes.length,
    truncated,
    sha256: sha256Hex(bytes),
  };
}

import type { RepositoryRelativePath } from "@fuzit/core";

export type BuiltInExclusionRuleId =
  | "safety.vcs"
  | "safety.dependencies"
  | "default.cache"
  | "default.build-output"
  | "safety.fuzit-state"
  | "default.os-metadata";

export interface BuiltInExclusionRule {
  readonly id: BuiltInExclusionRuleId;
  readonly hard: boolean;
  readonly reason: string;
}

export interface ExclusionDecision {
  readonly schemaVersion: 1;
  readonly path: RepositoryRelativePath;
  readonly excluded: boolean;
  readonly explicitlyIncluded: boolean;
  readonly rule: BuiltInExclusionRule | null;
}

const directoryRules: readonly {
  readonly names: ReadonlySet<string>;
  readonly rule: BuiltInExclusionRule;
}[] = [
  {
    names: new Set([".git", ".hg", ".svn"]),
    rule: {
      id: "safety.vcs",
      hard: true,
      reason: "Version-control internals are never scanned.",
    },
  },
  {
    names: new Set(["node_modules", ".pnpm-store", "bower_components"]),
    rule: {
      id: "safety.dependencies",
      hard: true,
      reason: "Dependency stores are never scanned.",
    },
  },
  {
    names: new Set([".cache", ".turbo"]),
    rule: {
      id: "default.cache",
      hard: false,
      reason: "Generated cache directories are excluded by default.",
    },
  },
  {
    names: new Set(["dist", "build", "out", "coverage"]),
    rule: {
      id: "default.build-output",
      hard: false,
      reason: "Generated build output is excluded by default.",
    },
  },
  {
    names: new Set([".fuzit", ".fuzit-index"]),
    rule: {
      id: "safety.fuzit-state",
      hard: true,
      reason: "Fuzit output and index state are never scanned.",
    },
  },
];

const osMetadata = new Set([".DS_Store", "Thumbs.db", "Desktop.ini"]);
const osMetadataRule: BuiltInExclusionRule = {
  id: "default.os-metadata",
  hard: false,
  reason: "Operating-system metadata is excluded by default.",
};

export function evaluateBuiltInExclusion(
  path: RepositoryRelativePath,
  options: { readonly explicitlyIncluded?: boolean } = {},
): ExclusionDecision {
  const segments = path.split("/");
  let rule =
    directoryRules.find(({ names }) =>
      segments.some((segment) => names.has(segment)),
    )?.rule ?? null;

  if (rule === null && osMetadata.has(segments.at(-1) ?? "")) {
    rule = osMetadataRule;
  }

  const explicitlyIncluded = options.explicitlyIncluded ?? false;
  return {
    schemaVersion: 1,
    path,
    excluded: rule !== null && (rule.hard || !explicitlyIncluded),
    explicitlyIncluded,
    rule,
  };
}

export { evaluateBuiltInExclusion } from "./built-in-exclusions.js";
export type {
  BuiltInExclusionRule,
  BuiltInExclusionRuleId,
  ExclusionDecision,
} from "./built-in-exclusions.js";

import { readFile } from "node:fs/promises";
import { join } from "node:path";

import {
  normalizeRepositoryRelativePath,
  type RepositoryRelativePath,
} from "@fuzit/core";

export interface GitignoreRule {
  readonly source: RepositoryRelativePath;
  readonly line: number;
  readonly pattern: string;
  readonly negated: boolean;
  readonly directoryOnly: boolean;
  readonly scope: RepositoryRelativePath;
  readonly matcher: RegExp;
}

export interface GitignoreDecision {
  readonly ignored: boolean;
  readonly rule: Omit<GitignoreRule, "matcher"> | null;
}

function escapeRegex(value: string): string {
  return value.replace(/[|\\{}()[\]^$+?.]/g, "\\$&");
}

function globRegex(pattern: string, anchored: boolean): RegExp {
  let source = "";
  for (let index = 0; index < pattern.length; index += 1) {
    const character = pattern[index];
    if (character === "*") {
      if (pattern[index + 1] === "*") {
        source += ".*";
        index += 1;
      } else {
        source += "[^/]*";
      }
    } else if (character === "?") {
      source += "[^/]";
    } else if (character === "\\") {
      const next = pattern[index + 1];
      source += next === undefined ? "\\\\" : escapeRegex(next);
      if (next !== undefined) index += 1;
    } else {
      source += escapeRegex(character ?? "");
    }
  }
  return new RegExp(anchored ? `^${source}$` : `(?:^|/)${source}(?:$|/)`);
}

export function parseGitignore(
  contents: string,
  source: RepositoryRelativePath,
  scope: RepositoryRelativePath,
): readonly GitignoreRule[] {
  const rules: GitignoreRule[] = [];
  for (const [index, rawLine] of contents.split(/\r?\n/).entries()) {
    if (rawLine === "" || rawLine.startsWith("#")) continue;
    let pattern = rawLine;
    let negated = false;
    if (pattern.startsWith("\\!") || pattern.startsWith("\\#")) {
      pattern = pattern.slice(1);
    } else if (pattern.startsWith("!")) {
      negated = true;
      pattern = pattern.slice(1);
    }
    const directoryOnly = pattern.endsWith("/");
    if (directoryOnly) pattern = pattern.slice(0, -1);
    const anchored = pattern.startsWith("/") || pattern.includes("/");
    if (pattern.startsWith("/")) pattern = pattern.slice(1);
    if (pattern === "") continue;
    rules.push({
      source,
      line: index + 1,
      pattern: rawLine,
      negated,
      directoryOnly,
      scope,
      matcher: globRegex(pattern, anchored),
    });
  }
  return rules;
}

function relativeToScope(
  path: RepositoryRelativePath,
  scope: RepositoryRelativePath,
): string | undefined {
  if (scope === ".") return path;
  if (path === scope) return ".";
  return path.startsWith(`${scope}/`)
    ? path.slice(scope.length + 1)
    : undefined;
}

export function evaluateGitignore(
  path: RepositoryRelativePath,
  isDirectory: boolean,
  rules: readonly GitignoreRule[],
): GitignoreDecision {
  let matched: GitignoreRule | null = null;
  let ignored = false;
  for (const rule of rules) {
    const scopedPath = relativeToScope(path, rule.scope);
    if (scopedPath === undefined) continue;
    if (
      rule.matcher.test(scopedPath) &&
      (!rule.directoryOnly || isDirectory || scopedPath.includes("/"))
    ) {
      matched = rule;
      ignored = !rule.negated;
    }
  }
  if (matched === null) return { ignored: false, rule: null };
  return {
    ignored,
    rule: {
      source: matched.source,
      line: matched.line,
      pattern: matched.pattern,
      negated: matched.negated,
      directoryOnly: matched.directoryOnly,
      scope: matched.scope,
    },
  };
}

export async function loadGitignoreRulesForPath(
  root: string,
  path: RepositoryRelativePath,
): Promise<readonly GitignoreRule[]> {
  const rules: GitignoreRule[] = [];
  const segments = path === "." ? [] : path.split("/");
  const scopes = [
    ".",
    ...segments
      .slice(0, -1)
      .map((_, index) => segments.slice(0, index + 1).join("/")),
  ];
  for (const scopeValue of scopes) {
    const scope = normalizeRepositoryRelativePath(scopeValue);
    const source = normalizeRepositoryRelativePath(
      scope === "." ? ".gitignore" : `${scope}/.gitignore`,
    );
    try {
      const contents = await readFile(join(root, ...source.split("/")), "utf8");
      rules.push(...parseGitignore(contents, source, scope));
    } catch (error) {
      if (
        typeof error === "object" &&
        error !== null &&
        "code" in error &&
        error.code === "ENOENT"
      )
        continue;
      throw error;
    }
  }
  return rules;
}

export async function loadFuzitignoreRulesForPath(
  root: string,
): Promise<readonly GitignoreRule[]> {
  const source = normalizeRepositoryRelativePath(".fuzitignore");
  try {
    const contents = await readFile(join(root, ".fuzitignore"), "utf8");
    return parseGitignore(
      contents,
      source,
      normalizeRepositoryRelativePath("."),
    );
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === "ENOENT"
    )
      return [];
    throw error;
  }
}

import type { RepositoryRelativePath } from "@fuzit/core";

import { evaluateBuiltInExclusion } from "../exclusions/index.js";
import { evaluateGitignore, type GitignoreRule } from "./gitignore.js";

export type IgnoreLayer =
  | "hard-exclusion"
  | "cli"
  | "project-config"
  | "fuzitignore"
  | "gitignore"
  | "built-in-default";

export interface ExplicitPathRule {
  readonly pattern: string;
  readonly action: "include" | "exclude";
  readonly reason: string;
}

export interface IgnorePrecedenceInput {
  readonly path: RepositoryRelativePath;
  readonly isDirectory: boolean;
  readonly cliRules?: readonly ExplicitPathRule[];
  readonly projectRules?: readonly ExplicitPathRule[];
  readonly fuzitignoreRules?: readonly GitignoreRule[];
  readonly gitignoreRules?: readonly GitignoreRule[];
}

export interface IgnorePrecedenceDecision {
  readonly schemaVersion: 1;
  readonly path: RepositoryRelativePath;
  readonly excluded: boolean;
  readonly winningLayer: IgnoreLayer | null;
  readonly winningRule: string | null;
  readonly reason: string;
  readonly shadowedRules: readonly {
    readonly layer: IgnoreLayer;
    readonly rule: string;
  }[];
}

function match(pattern: string, path: RepositoryRelativePath): boolean {
  const escaped = pattern
    .replace(/[|\\{}()[\]^$+?.]/g, "\\$&")
    .replaceAll("**", "\0")
    .replaceAll("*", "[^/]*")
    .replaceAll("\0", ".*");
  return new RegExp(`^(?:${escaped})$`).test(path);
}

function lastExplicitMatch(
  rules: readonly ExplicitPathRule[],
  path: RepositoryRelativePath,
): ExplicitPathRule | undefined {
  return [...rules].reverse().find((rule) => match(rule.pattern, path));
}

export function evaluateIgnorePrecedence(
  input: IgnorePrecedenceInput,
): IgnorePrecedenceDecision {
  const candidates: {
    layer: IgnoreLayer;
    rule: string;
    excluded: boolean;
    reason: string;
  }[] = [];
  const builtIn = evaluateBuiltInExclusion(input.path);
  if (builtIn.rule?.hard) {
    return {
      schemaVersion: 1,
      path: input.path,
      excluded: true,
      winningLayer: "hard-exclusion",
      winningRule: builtIn.rule.id,
      reason: builtIn.rule.reason,
      shadowedRules: [],
    };
  }

  for (const [layer, rules] of [
    ["cli", input.cliRules ?? []],
    ["project-config", input.projectRules ?? []],
  ] as const) {
    const rule = lastExplicitMatch(rules, input.path);
    if (rule)
      candidates.push({
        layer,
        rule: rule.pattern,
        excluded: rule.action === "exclude",
        reason: rule.reason,
      });
  }
  for (const [layer, rules] of [
    ["fuzitignore", input.fuzitignoreRules ?? []],
    ["gitignore", input.gitignoreRules ?? []],
  ] as const) {
    const decision = evaluateGitignore(input.path, input.isDirectory, rules);
    if (decision.rule)
      candidates.push({
        layer,
        rule: decision.rule.pattern,
        excluded: decision.ignored,
        reason: `${decision.rule.source}:${decision.rule.line}`,
      });
  }
  if (builtIn.rule)
    candidates.push({
      layer: "built-in-default",
      rule: builtIn.rule.id,
      excluded: builtIn.excluded,
      reason: builtIn.rule.reason,
    });

  const winner = candidates[0];
  return {
    schemaVersion: 1,
    path: input.path,
    excluded: winner?.excluded ?? false,
    winningLayer: winner?.layer ?? null,
    winningRule: winner?.rule ?? null,
    reason: winner?.reason ?? "No rule matched.",
    shadowedRules: candidates
      .slice(1)
      .map(({ layer, rule }) => ({ layer, rule })),
  };
}

