import { lstat, readlink, realpath } from "node:fs/promises";
import { dirname, resolve } from "node:path";

import {
  PathNormalizationError,
  toRepositoryRelativePath,
  type RepositoryRelativePath,
} from "@fuzit/core";

export type SymlinkStatus =
  "not-followed" | "followed" | "broken" | "loop" | "outside-root";

export interface SymlinkResolution {
  readonly schemaVersion: 1;
  readonly path: RepositoryRelativePath;
  readonly target: string;
  readonly followed: boolean;
  readonly status: SymlinkStatus;
  readonly targetPath?: RepositoryRelativePath;
}

export async function resolveSymlinkSafely(
  repositoryRoot: string,
  absoluteLinkPath: string,
  path: RepositoryRelativePath,
  options: { readonly follow?: boolean } = {},
): Promise<SymlinkResolution> {
  const metadata = await lstat(absoluteLinkPath);
  if (!metadata.isSymbolicLink())
    throw new Error("Path is not a symbolic link.");
  const target = await readlink(absoluteLinkPath);
  if (!options.follow)
    return {
      schemaVersion: 1,
      path,
      target,
      followed: false,
      status: "not-followed",
    };
  let canonicalTarget: string;
  try {
    canonicalTarget = await realpath(
      resolve(dirname(absoluteLinkPath), target),
    );
  } catch (error) {
    const code =
      typeof error === "object" && error !== null && "code" in error
        ? error.code
        : undefined;
    return {
      schemaVersion: 1,
      path,
      target,
      followed: false,
      status: code === "ELOOP" ? "loop" : "broken",
    };
  }
  try {
    const targetPath = toRepositoryRelativePath(
      await realpath(repositoryRoot),
      canonicalTarget,
    );
    return {
      schemaVersion: 1,
      path,
      target,
      followed: true,
      status: "followed",
      targetPath,
    };
  } catch (error) {
    if (error instanceof PathNormalizationError)
      return {
        schemaVersion: 1,
        path,
        target,
        followed: false,
        status: "outside-root",
      };
    throw error;
  }
}

import { readdir } from "node:fs/promises";
import { join } from "node:path";

import {
  normalizeRepositoryRelativePath,
  type RepositoryRelativePath,
} from "@fuzit/core";
import { evaluateSensitivePath } from "@fuzit/security";

import {
  loadFuzitignoreRulesForPath,
  loadGitignoreRulesForPath,
} from "../ignore/gitignore.js";
import {
  evaluateIgnorePrecedence,
  type ExplicitPathRule,
} from "../ignore/precedence.js";

export type TraversalEntryKind = "file" | "directory" | "symlink";
export type TraversalErrorCode =
  | "TRAVERSAL.CANCELLED"
  | "TRAVERSAL.PERMISSION_DENIED"
  | "TRAVERSAL.READ_FAILED";

export class TraversalError extends Error {
  readonly code: TraversalErrorCode;

  constructor(code: TraversalErrorCode, message: string) {
    super(message);
    this.name = "TraversalError";
    this.code = code;
  }
}

export interface TraversalDirectoryEntry {
  readonly name: string;
  readonly isDirectory: () => boolean;
  readonly isSymbolicLink: () => boolean;
}

export interface TraversalEntry {
  readonly path: RepositoryRelativePath;
  readonly kind: TraversalEntryKind;
}

export interface TraversalOptions {
  readonly signal?: AbortSignal;
  readonly readDirectory?: (
    path: string,
  ) => Promise<readonly TraversalDirectoryEntry[]>;
  readonly cliRules?: readonly ExplicitPathRule[];
  readonly projectRules?: readonly ExplicitPathRule[];
  readonly onExcluded?: (decision: {
    readonly path: RepositoryRelativePath;
    readonly reason: string;
  }) => void;
}

interface PendingEntry extends TraversalEntry {
  readonly absolutePath: string;
}

function compareNames(left: string, right: string): number {
  return Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"));
}

function throwIfCancelled(signal: AbortSignal | undefined): void {
  if (signal?.aborted) {
    throw new TraversalError(
      "TRAVERSAL.CANCELLED",
      "Directory traversal was cancelled.",
    );
  }
}

async function defaultReadDirectory(
  path: string,
): Promise<readonly TraversalDirectoryEntry[]> {
  return readdir(path, { withFileTypes: true });
}

async function readEntries(
  rootPath: string,
  absolutePath: string,
  relativeDirectory: RepositoryRelativePath,
  options: TraversalOptions,
): Promise<readonly PendingEntry[]> {
  throwIfCancelled(options.signal);

  let entries: readonly TraversalDirectoryEntry[];
  try {
    entries = await (options.readDirectory ?? defaultReadDirectory)(
      absolutePath,
    );
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error.code === "EACCES" || error.code === "EPERM")
    ) {
      throw new TraversalError(
        "TRAVERSAL.PERMISSION_DENIED",
        `Permission denied while reading ${relativeDirectory}.`,
      );
    }
    throw new TraversalError(
      "TRAVERSAL.READ_FAILED",
      `Unable to read directory ${relativeDirectory}.`,
    );
  }

  const pendingEntries = [...entries]
    .sort((left, right) => compareNames(left.name, right.name))
    .map((entry) => {
      const path = normalizeRepositoryRelativePath(
        relativeDirectory === "."
          ? entry.name
          : `${relativeDirectory}/${entry.name}`,
      );
      const kind: TraversalEntryKind = entry.isSymbolicLink()
        ? "symlink"
        : entry.isDirectory()
          ? "directory"
          : "file";
      return {
        absolutePath: join(absolutePath, entry.name),
        path,
        kind,
      };
    });
  const included: PendingEntry[] = [];
  for (const entry of pendingEntries) {
    const sensitive = evaluateSensitivePath(entry.path);
    if (sensitive.excluded) {
      options.onExcluded?.({
        path: entry.path,
        reason: sensitive.ruleId ?? sensitive.reason,
      });
      continue;
    }
    const gitignoreRules =
      options.readDirectory === undefined
        ? await loadGitignoreRulesForPath(rootPath, entry.path)
        : [];
    const fuzitignoreRules =
      options.readDirectory === undefined
        ? await loadFuzitignoreRulesForPath(rootPath)
        : [];
    const ignore = evaluateIgnorePrecedence({
      path: entry.path,
      isDirectory: entry.kind === "directory",
      cliRules: options.cliRules ?? [],
      projectRules: options.projectRules ?? [],
      fuzitignoreRules,
      gitignoreRules,
    });
    if (ignore.excluded) {
      options.onExcluded?.({ path: entry.path, reason: ignore.reason });
      continue;
    }
    included.push(entry);
  }
  return included;
}

export async function* traverseDirectory(
  rootPath: string,
  options: TraversalOptions = {},
): AsyncGenerator<TraversalEntry> {
  const pending = [
    ...(await readEntries(
      rootPath,
      rootPath,
      "." as RepositoryRelativePath,
      options,
    )),
  ].reverse();

  while (pending.length > 0) {
    throwIfCancelled(options.signal);
    const entry = pending.pop();
    if (entry === undefined) {
      break;
    }

    yield { path: entry.path, kind: entry.kind };

    if (entry.kind === "directory") {
      const children = await readEntries(
        rootPath,
        entry.absolutePath,
        entry.path,
        options,
      );
      pending.push(...[...children].reverse());
    }
  }
}

import { describe, expect, it } from "vitest";

import { normalizeRepositoryRelativePath } from "@fuzit/core";

import { evaluateBuiltInExclusion } from "../src/index.js";

function decision(path: string, explicitlyIncluded = false) {
  return evaluateBuiltInExclusion(normalizeRepositoryRelativePath(path), {
    explicitlyIncluded,
  });
}

describe("built-in safe exclusions", () => {
  it("excludes node_modules by exact segment", () => {
    expect(decision("packages/cli/node_modules/tool/index.js")).toMatchObject({
      excluded: true,
      rule: { id: "safety.dependencies", hard: true },
    });
  });

  it("excludes Git internals", () => {
    expect(decision(".git/objects/pack/data")).toMatchObject({
      excluded: true,
      rule: { id: "safety.vcs", hard: true },
    });
  });

  it("excludes dist and build outputs", () => {
    expect(decision("packages/cli/dist/index.js")).toMatchObject({
      excluded: true,
      rule: { id: "default.build-output" },
    });
    expect(decision("build/report.txt")).toMatchObject({
      excluded: true,
      rule: { id: "default.build-output" },
    });
  });

  it("excludes Fuzit output and index state", () => {
    expect(decision(".fuzit/index/state.json")).toMatchObject({
      excluded: true,
      rule: { id: "safety.fuzit-state", hard: true },
    });
  });

  it("keeps similarly named legitimate directories", () => {
    expect(decision("node_modules_backup/index.js")).toMatchObject({
      excluded: false,
      rule: null,
    });
    expect(decision("distribution/index.js")).toMatchObject({
      excluded: false,
      rule: null,
    });
    expect(decision("builder/index.js")).toMatchObject({
      excluded: false,
      rule: null,
    });
  });

  it("does not let explicit includes bypass hard safety rules", () => {
    expect(decision(".git/config", true)).toMatchObject({
      excluded: true,
      explicitlyIncluded: true,
      rule: { hard: true },
    });
    expect(decision("dist/output.js", true)).toMatchObject({
      excluded: false,
      explicitlyIncluded: true,
      rule: { hard: false },
    });
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { normalizeRepositoryRelativePath } from "@fuzit/core";
import { classifyFile } from "../src/index.js";

const directories: string[] = [];
async function fixture(name: string, content: string | Buffer) {
  const root = await mkdtemp(join(tmpdir(), "fuzit-classify-"));
  directories.push(root);
  const absolute = join(root, name);
  await writeFile(absolute, content);
  return { absolute, path: normalizeRepositoryRelativePath(name) };
}
afterEach(async () => {
  await Promise.all(
    directories
      .splice(0)
      .map((path) => rm(path, { recursive: true, force: true })),
  );
});

describe("file classification", () => {
  it.each([
    ["component.jsx", "JavaScript"],
    ["styles.css", "CSS"],
    ["config.yaml", "YAML"],
    ["main.rs", "Rust"],
  ])("classifies mainstream file %s", async (name, language) => {
    const file = await fixture(name, "content");
    const result = await classifyFile(file.absolute, file.path);
    expect(result.language.name).toBe(language);
  });

  it("does not classify .gitignore as generated from its patterns", async () => {
    const file = await fixture(".gitignore", "generated/\n");
    const result = await classifyFile(file.absolute, file.path);
    expect(result.generated).toBe(false);
  });

  it("classifies extensionless files conservatively", async () => {
    const file = await fixture("LICENSE", "text");
    await expect(classifyFile(file.absolute, file.path)).resolves.toMatchObject(
      {
        extension: "",
        language: { name: "Unknown", confidence: 0 },
      },
    );
  });
  it("preserves Unicode names", async () => {
    const file = await fixture("文档.ts", "export {}");
    await expect(classifyFile(file.absolute, file.path)).resolves.toMatchObject(
      {
        path: "文档.ts",
        language: { name: "TypeScript" },
      },
    );
  });
  it("reads only a bounded prefix for a large file", async () => {
    const file = await fixture("large.txt", "x");
    let maximum = 0;
    await classifyFile(file.absolute, file.path, {
      readPrefix: async (_path, bytes) => {
        maximum = bytes;
        return Buffer.from("text");
      },
    });
    expect(maximum).toBe(4096);
  });
  it("detects a binary prefix", async () => {
    const file = await fixture("data.bin", Buffer.from([1, 0, 2]));
    await expect(classifyFile(file.absolute, file.path)).resolves.toMatchObject(
      {
        kind: "binary",
      },
    );
  });
  it("detects a generated header", async () => {
    const file = await fixture("generated.ts", "// generated; do not edit\n");
    await expect(classifyFile(file.absolute, file.path)).resolves.toMatchObject(
      {
        generated: true,
      },
    );
  });
  it("detects a vendored canonical path", async () => {
    const file = await fixture("x.js", "");
    await expect(
      classifyFile(
        file.absolute,
        normalizeRepositoryRelativePath("vendor/x.js"),
      ),
    ).resolves.toMatchObject({ vendored: true });
  });
  it("reports an unreadable file", async () => {
    const file = await fixture("private.txt", "private");
    await expect(
      classifyFile(file.absolute, file.path, {
        readPrefix: async () => {
          throw new Error("denied");
        },
      }),
    ).resolves.toMatchObject({ readable: false });
  });
});

import { describe, expect, it } from "vitest";

import { normalizeRepositoryRelativePath } from "@fuzit/core";

import { evaluateGitignore, parseGitignore } from "../src/index.js";

const path = normalizeRepositoryRelativePath;

function rules(contents: string, scope = ".") {
  const canonicalScope = path(scope);
  return parseGitignore(
    contents,
    path(scope === "." ? ".gitignore" : `${scope}/.gitignore`),
    canonicalScope,
  );
}

describe(".gitignore semantics", () => {
  it("applies nested ignore scope", () => {
    const nestedRules = rules("*.tmp\n", "packages/cli");
    expect(
      evaluateGitignore(path("packages/cli/cache.tmp"), false, nestedRules),
    ).toMatchObject({
      ignored: true,
      rule: { source: "packages/cli/.gitignore", line: 1 },
    });
    expect(
      evaluateGitignore(path("packages/core/cache.tmp"), false, nestedRules),
    ).toEqual({ ignored: false, rule: null });
  });

  it("uses the last matching negation", () => {
    const parsed = rules("*.log\n!important.log\n");
    expect(
      evaluateGitignore(path("important.log"), false, parsed),
    ).toMatchObject({
      ignored: false,
      rule: { line: 2, pattern: "!important.log", negated: true },
    });
  });

  it("supports escaped leading markers and spaces", () => {
    const parsed = rules("\\!important.txt\nspace\\ name.txt\n");
    expect(
      evaluateGitignore(path("!important.txt"), false, parsed).ignored,
    ).toBe(true);
    expect(
      evaluateGitignore(path("space name.txt"), false, parsed).ignored,
    ).toBe(true);
  });

  it("matches directory patterns and descendants", () => {
    const parsed = rules("logs/\n");
    expect(evaluateGitignore(path("logs"), true, parsed).ignored).toBe(true);
    expect(
      evaluateGitignore(path("logs/output.txt"), false, parsed).ignored,
    ).toBe(true);
  });

  it("honors root anchoring", () => {
    const parsed = rules("/root-only.txt\n");
    expect(
      evaluateGitignore(path("root-only.txt"), false, parsed).ignored,
    ).toBe(true);
    expect(
      evaluateGitignore(path("src/root-only.txt"), false, parsed).ignored,
    ).toBe(false);
  });

  it("parses CRLF with deterministic line provenance", () => {
    const parsed = rules("# comment\r\n*.tmp\r\n!keep.tmp\r\n");
    expect(evaluateGitignore(path("cache.tmp"), false, parsed)).toMatchObject({
      ignored: true,
      rule: { line: 2, pattern: "*.tmp" },
    });
  });
});

import { describe, expect, it } from "vitest";
import { normalizeRepositoryRelativePath } from "@fuzit/core";
import {
  evaluateIgnorePrecedence,
  parseGitignore,
  type ExplicitPathRule,
} from "../src/index.js";

const p = normalizeRepositoryRelativePath;
const rule = (
  pattern: string,
  action: "include" | "exclude",
): ExplicitPathRule => ({ pattern, action, reason: `${action} ${pattern}` });

describe("ignore precedence", () => {
  it("uses CLI over conflicting project and ignore rules", () => {
    const git = parseGitignore("src/**\n", p(".gitignore"), p("."));
    const fuzit = parseGitignore("!src/**\n", p(".fuzitignore"), p("."));
    const decision = evaluateIgnorePrecedence({
      path: p("src/index.ts"),
      isDirectory: false,
      cliRules: [rule("src/**", "exclude")],
      projectRules: [rule("src/**", "include")],
      fuzitignoreRules: fuzit,
      gitignoreRules: git,
    });
    expect(decision).toMatchObject({
      excluded: true,
      winningLayer: "cli",
      winningRule: "src/**",
    });
    expect(decision.shadowedRules.map(({ layer }) => layer)).toEqual([
      "project-config",
      "fuzitignore",
      "gitignore",
    ]);
  });

  it("uses the last matching rule within one layer", () => {
    expect(
      evaluateIgnorePrecedence({
        path: p("src/index.ts"),
        isDirectory: false,
        cliRules: [rule("src/**", "exclude"), rule("src/index.ts", "include")],
      }),
    ).toMatchObject({ excluded: false, winningLayer: "cli" });
  });

  it("never overrides a hard exclusion", () => {
    expect(
      evaluateIgnorePrecedence({
        path: p("node_modules/x.js"),
        isDirectory: false,
        cliRules: [rule("node_modules/**", "include")],
      }),
    ).toMatchObject({
      excluded: true,
      winningLayer: "hard-exclusion",
    });
  });

  it("deduplicates by selecting the last duplicate rule", () => {
    const duplicate = [rule("src/**", "exclude"), rule("src/**", "include")];
    expect(
      evaluateIgnorePrecedence({
        path: p("src/a.ts"),
        isDirectory: false,
        projectRules: duplicate,
      }),
    ).toMatchObject({ excluded: false, winningLayer: "project-config" });
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { readTextContent } from "../src/index.js";

const roots: string[] = [];
async function file(bytes: Uint8Array) {
  const root = await mkdtemp(join(tmpdir(), "fuzit-content-"));
  roots.push(root);
  const path = join(root, "file");
  await writeFile(path, bytes);
  return path;
}
afterEach(async () => {
  await Promise.all(
    roots.splice(0).map((x) => rm(x, { recursive: true, force: true })),
  );
});
describe("bounded text content", () => {
  it("reads UTF-8", async () =>
    expect(
      readTextContent(await file(Buffer.from("hello"))),
    ).resolves.toMatchObject({ encoding: "utf-8", content: "hello" }));
  it("removes a UTF-8 BOM", async () =>
    expect(
      readTextContent(await file(Buffer.from([0xef, 0xbb, 0xbf, 0x61]))),
    ).resolves.toMatchObject({ content: "a" }));
  it("reads UTF-16", async () =>
    expect(
      readTextContent(await file(Buffer.from([0xff, 0xfe, 0x61, 0]))),
    ).resolves.toMatchObject({ encoding: "utf-16le", content: "a" }));
  it("omits invalid encoding", async () =>
    expect(
      readTextContent(await file(Buffer.from([0xc3, 0x28]))),
    ).resolves.toMatchObject({
      status: "omitted",
      encoding: "invalid",
      content: null,
    }));
  it("truncates large text", async () =>
    expect(
      readTextContent(await file(Buffer.from("abcdef")), { maximumBytes: 3 }),
    ).resolves.toMatchObject({
      status: "truncated",
      content: "abc",
      truncated: true,
    }));
  it("reports file changes during read", async () => {
    const path = await file(Buffer.from("before"));
    const result = await readTextContent(path);
    expect(["complete", "changed"]).toContain(result.status);
  });
  it("honors cancellation", async () => {
    const controller = new AbortController();
    controller.abort();
    await expect(
      readTextContent(await file(Buffer.from("x")), {
        signal: controller.signal,
      }),
    ).rejects.toMatchObject({ name: "AbortError" });
  });
});

import { mkdir, mkdtemp, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { normalizeRepositoryRelativePath } from "@fuzit/core";
import { resolveSymlinkSafely } from "../src/index.js";

const roots: string[] = [];
async function root() {
  const value = await mkdtemp(join(tmpdir(), "fuzit-links-"));
  roots.push(value);
  return value;
}
afterEach(async () => {
  await Promise.all(
    roots.splice(0).map((x) => rm(x, { recursive: true, force: true })),
  );
});

async function safeSymlink(
  target: string,
  path: string,
  type?: "file" | "dir" | "junction",
): Promise<boolean> {
  try {
    const defaultType =
      type ?? (process.platform === "win32" ? "junction" : undefined);
    await symlink(target, path, defaultType);
    return true;
  } catch (error: unknown) {
    if (
      process.platform === "win32" &&
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === "EPERM"
    ) {
      try {
        await symlink(target, path, "junction");
        return true;
      } catch {
        return false;
      }
    }
    throw error;
  }
}

describe("symlink safety", () => {
  it("reports a file symlink without following by default", async () => {
    const r = await root();
    await writeFile(join(r, "target"), "x");
    const ok = await safeSymlink(join(r, "target"), join(r, "link"), "file");
    if (!ok) return; // Skip if Windows environment blocks unprivileged symlink creation

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "link"),
        normalizeRepositoryRelativePath("link"),
      ),
    ).resolves.toMatchObject({ status: "not-followed", followed: false });
  });

  it("safely follows an in-root directory symlink when explicit", async () => {
    const r = await root();
    await mkdir(join(r, "dir"));
    const ok = await safeSymlink(join(r, "dir"), join(r, "link"), "junction");
    if (!ok) return;

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "link"),
        normalizeRepositoryRelativePath("link"),
        { follow: true },
      ),
    ).resolves.toMatchObject({ status: "followed", targetPath: "dir" });
  });

  it("reports a loop", async () => {
    const r = await root();
    const ok1 = await safeSymlink(join(r, "b"), join(r, "a"));
    const ok2 = await safeSymlink(join(r, "a"), join(r, "b"));
    if (!ok1 || !ok2) return;

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "a"),
        normalizeRepositoryRelativePath("a"),
        { follow: true },
      ),
    ).resolves.toMatchObject({ status: "loop" });
  });

  it("reports a broken link", async () => {
    const r = await root();
    const ok = await safeSymlink(join(r, "missing"), join(r, "link"));
    if (!ok) return;

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "link"),
        normalizeRepositoryRelativePath("link"),
        { follow: true },
      ),
    ).resolves.toMatchObject({ status: "broken" });
  });

  it("blocks an outside-root target", async () => {
    const r = await root();
    const outside = await root();
    await writeFile(join(outside, "private"), "x");
    const ok = await safeSymlink(join(outside, "private"), join(r, "link"));
    if (!ok) return;

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "link"),
        normalizeRepositoryRelativePath("link"),
        { follow: true },
      ),
    ).resolves.toMatchObject({ status: "outside-root", followed: false });
  });

  it("applies the same boundary rule to a Windows junction", async () => {
    const r = await root();
    const outside = await root();
    await mkdir(join(outside, "dir"));
    const ok = await safeSymlink(join(outside, "dir"), join(r, "junction"), "junction");
    if (!ok) return;

    await expect(
      resolveSymlinkSafely(
        r,
        join(r, "junction"),
        normalizeRepositoryRelativePath("junction"),
        { follow: true },
      ),
    ).resolves.toMatchObject({ status: "outside-root" });
  });
});

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import {
  TraversalError,
  traverseDirectory,
  type TraversalDirectoryEntry,
  type TraversalEntry,
} from "../src/index.js";

const temporaryDirectories: string[] = [];

async function createDirectory(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-traversal-"));
  temporaryDirectories.push(directory);
  return directory;
}

function entry(
  name: string,
  kind: "file" | "directory" = "file",
): TraversalDirectoryEntry {
  return {
    name,
    isDirectory: () => kind === "directory",
    isSymbolicLink: () => false,
  };
}

async function collect(
  root: string,
  options: Parameters<typeof traverseDirectory>[1] = {},
): Promise<readonly TraversalEntry[]> {
  const entries: TraversalEntry[] = [];
  for await (const item of traverseDirectory(root, options)) {
    entries.push(item);
  }
  return entries;
}

afterEach(async () => {
  await Promise.all(
    temporaryDirectories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

describe("deterministic directory traversal", () => {
  it("returns identical bytewise ordering across repeated runs", async () => {
    const root = await createDirectory();
    await mkdir(join(root, "a"));
    await writeFile(join(root, "z.txt"), "");
    await writeFile(join(root, "A.txt"), "");
    await writeFile(join(root, "a", "one.txt"), "");

    const first = await collect(root);
    const second = await collect(root);

    expect(first).toEqual(second);
    expect(first.map(({ path }) => path)).toEqual([
      "A.txt",
      "a",
      "a/one.txt",
      "z.txt",
    ]);
  });

  it("yields empty directories without fabricating children", async () => {
    const root = await createDirectory();
    await mkdir(join(root, "empty"));

    await expect(collect(root)).resolves.toEqual([
      { path: "empty", kind: "directory" },
    ]);
  });

  it("returns a typed permission-denied failure", async () => {
    const readDirectory = async (path: string) => {
      if (path === "root") {
        return [entry("blocked", "directory")];
      }
      const error = new Error("denied");
      Object.assign(error, { code: "EACCES" });
      throw error;
    };

    await expect(collect("root", { readDirectory })).rejects.toMatchObject({
      code: "TRAVERSAL.PERMISSION_DENIED",
    });
  });

  it("handles a deep tree without recursive call-stack growth", async () => {
    const depth = 500;
    const readDirectory = async (path: string) => {
      const name = basename(path);
      const level = name === "root" ? 0 : Number(name.slice(1));
      return level < depth ? [entry(`d${level + 1}`, "directory")] : [];
    };

    const result = await collect("root", { readDirectory });

    expect(result).toHaveLength(depth);
    expect(result.at(-1)?.path.split("/")).toHaveLength(depth);
  });

  it("honors cancellation between streamed entries", async () => {
    const root = await createDirectory();
    await writeFile(join(root, "a.txt"), "");
    await writeFile(join(root, "b.txt"), "");
    const controller = new AbortController();
    const iterator = traverseDirectory(root, { signal: controller.signal });

    await expect(iterator.next()).resolves.toMatchObject({
      value: { path: "a.txt" },
      done: false,
    });
    controller.abort();
    await expect(iterator.next()).rejects.toBeInstanceOf(TraversalError);
  });

  it("streams a large file count with one bounded directory read", async () => {
    const fileCount = 5_000;
    let activeReads = 0;
    let maximumActiveReads = 0;
    const readDirectory = async () => {
      activeReads += 1;
      maximumActiveReads = Math.max(maximumActiveReads, activeReads);
      const entries = Array.from({ length: fileCount }, (_, index) =>
        entry(`file-${index.toString().padStart(5, "0")}.txt`),
      );
      activeReads -= 1;
      return entries;
    };

    const result = await collect("root", { readDirectory });

    expect(result).toHaveLength(fileCount);
    expect(maximumActiveReads).toBe(1);
  });
});

{
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "declaration": true,
    "declarationMap": true,
    "noEmit": false,
    "outDir": "dist",
    "rootDir": "src",
    "types": ["node"]
  },
  "include": ["src/**/*.ts"]
}

{
  "name": "@fuzit/schemas",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc --project tsconfig.json",
    "typecheck": "tsc --project tsconfig.json --noEmit"
  },
  "dependencies": {
    "zod": "4.4.3"
  }
}

import { z } from "zod";

export const NORMALIZED_ANALYSIS_SCHEMA_VERSION = 1 as const;

export const analysisRepositoryIdSchema = z
  .string()
  .regex(/^sha256:[a-f0-9]{64}$/u);

export const analysisIdentitySchema = z
  .string()
  .regex(/^analysis:[a-z][a-z0-9-]*:[a-f0-9]{64}$/u);

export const analysisPathSchema = z
  .string()
  .min(1)
  .max(4096)
  .refine(
    (path) =>
      path === path.normalize("NFC") &&
      !path.startsWith("/") &&
      !path.includes("\\") &&
      !path.split("/").some((segment) => segment === "." || segment === "..") &&
      !/^[A-Za-z]:/u.test(path),
    { message: "Analysis paths must be canonical repository-relative paths" },
  );

export const analysisPositionSchema = z.strictObject({
  offset: z.number().int().nonnegative(),
  line: z.number().int().positive(),
  column: z.number().int().positive(),
});

export const analysisRangeSchema = z
  .strictObject({
    start: analysisPositionSchema,
    end: analysisPositionSchema,
  })
  .refine(({ end, start }) => end.offset >= start.offset, {
    message: "Analysis range end must not precede start",
    path: ["end", "offset"],
  });

export const analysisEvidenceBasisSchema = z.enum([
  "observed",
  "parsed",
  "inferred",
  "configured",
]);

export const analysisCompletenessSchema = z.enum([
  "complete",
  "partial",
  "unsupported",
  "failed",
  "stale",
  "verified",
]);

export const analysisResolutionSchema = z.enum([
  "resolved",
  "unresolved",
  "ambiguous",
  "not-applicable",
]);

const scopedIdentitySchema = z.strictObject({
  id: analysisIdentitySchema,
  repositoryId: analysisRepositoryIdSchema,
});

export const analysisFileSchema = scopedIdentitySchema.extend({
  kind: z.literal("file"),
  path: analysisPathSchema,
  language: z.string().min(1),
  contentHash: z.string().regex(/^sha256:[a-f0-9]{64}$/u),
});

export const analysisModuleSchema = scopedIdentitySchema.extend({
  kind: z.enum(["module", "package"]),
  name: z.string().min(1),
  path: analysisPathSchema.nullable(),
});

export const analysisSymbolSchema = scopedIdentitySchema.extend({
  kind: z.enum([
    "class",
    "interface",
    "type",
    "function",
    "method",
    "property",
    "variable",
    "constant",
    "namespace",
    "module",
    "test",
    "endpoint",
    "schema",
  ]),
  name: z.string().min(1),
  fileId: analysisIdentitySchema,
  range: analysisRangeSchema,
  exported: z.boolean(),
});

export const analysisProvenanceSchema = z.strictObject({
  sourceFileId: analysisIdentitySchema,
  sourceSymbolId: analysisIdentitySchema.nullable(),
  range: analysisRangeSchema.nullable(),
  basis: analysisEvidenceBasisSchema,
  parserIdentity: z.string().min(1),
  analysisIdentity: z.string().min(1),
  confidence: z.number().min(0).max(1),
  resolution: analysisResolutionSchema,
});

export const analysisRelationshipSchema = scopedIdentitySchema.extend({
  kind: z.enum([
    "import",
    "export",
    "reference",
    "call",
    "inheritance",
    "test",
    "endpoint",
    "schema",
    "configuration-link",
  ]),
  sourceId: analysisIdentitySchema,
  targetId: analysisIdentitySchema.nullable(),
  unresolvedTarget: z.string().min(1).max(1024).nullable(),
  provenance: analysisProvenanceSchema,
});

export const normalizedAnalysisSchema = z
  .strictObject({
    schemaVersion: z.literal(NORMALIZED_ANALYSIS_SCHEMA_VERSION),
    repositoryId: analysisRepositoryIdSchema,
    analysisIdentity: z.string().min(1),
    files: z.array(analysisFileSchema).max(100_000),
    modules: z.array(analysisModuleSchema).max(100_000),
    symbols: z.array(analysisSymbolSchema).max(500_000),
    relationships: z.array(analysisRelationshipSchema).max(1_000_000),
    completeness: analysisCompletenessSchema,
    diagnostics: z.array(z.string().min(1).max(8192)).max(128),
  })
  .superRefine((record, context) => {
    for (const [collectionName, collection] of [
      ["files", record.files],
      ["modules", record.modules],
      ["symbols", record.symbols],
      ["relationships", record.relationships],
    ] as const) {
      collection.forEach((item, index) => {
        if (item.repositoryId !== record.repositoryId) {
          context.addIssue({
            code: "custom",
            message: "Analysis identities cannot cross repository roots",
            path: [collectionName, index, "repositoryId"],
          });
        }
      });
    }
  });

export type AnalysisRange = z.infer<typeof analysisRangeSchema>;
export type AnalysisEvidenceBasis = z.infer<typeof analysisEvidenceBasisSchema>;
export type AnalysisCompleteness = z.infer<typeof analysisCompletenessSchema>;
export type AnalysisFile = z.infer<typeof analysisFileSchema>;
export type AnalysisModule = z.infer<typeof analysisModuleSchema>;
export type AnalysisSymbol = z.infer<typeof analysisSymbolSchema>;
export type AnalysisRelationship = z.infer<typeof analysisRelationshipSchema>;
export type NormalizedAnalysis = z.infer<typeof normalizedAnalysisSchema>;

export function parseNormalizedAnalysis(value: unknown): NormalizedAnalysis {
  return normalizedAnalysisSchema.parse(value);
}

export function serializeNormalizedAnalysis(value: unknown): string {
  const parsed = parseNormalizedAnalysis(value);
  const byId = <T extends { readonly id: string }>(left: T, right: T) =>
    left.id.localeCompare(right.id);
  return `${JSON.stringify({
    ...parsed,
    files: [...parsed.files].sort(byId),
    modules: [...parsed.modules].sort(byId),
    symbols: [...parsed.symbols].sort(byId),
    relationships: [...parsed.relationships].sort(byId),
  })}\n`;
}

import { z } from "zod";

export const budgetEstimateSchema = z.strictObject({
  schemaVersion: z.literal(1),
  bytes: z.number().int().nonnegative(),
  metadataBytes: z.number().int().nonnegative(),
  estimatedTokens: z.number().int().nonnegative(),
  estimator: z.string().min(1),
  uncertainty: z.number().min(0).max(1),
  exceedsBudget: z.boolean(),
});

export type BudgetEstimate = z.infer<typeof budgetEstimateSchema>;

import { z } from "zod";

export const contextBundleSchema = z.strictObject({
  schemaVersion: z.literal(1),
  id: z.string().regex(/^bundle:[a-f0-9]{64}$/),
  source: z.strictObject({
    kind: z.literal("repository"),
    root: z.string().min(1),
  }),
  revision: z.string().nullable(),
  items: z.array(
    z.strictObject({
      id: z.string().min(1),
      path: z.string().min(1),
      sha256: z.string().regex(/^[a-f0-9]{64}$/),
      contentStatus: z.enum(["complete", "truncated", "omitted", "changed"]),
      redacted: z.boolean(),
    }),
  ),
  redactionSummary: z.strictObject({
    findings: z.number().int().nonnegative(),
    redactedItems: z.number().int().nonnegative(),
    omittedItems: z.number().int().nonnegative(),
  }),
  warnings: z.array(z.string()),
  failedSources: z.array(z.string()),
  budget: z.strictObject({
    bytes: z.number().int().nonnegative(),
    tokens: z.number().int().nonnegative(),
    truncated: z.boolean(),
  }),
  intelligence: z
    .strictObject({
      languages: z.array(z.string()),
      packages: z.array(z.string()),
      frameworks: z.array(z.string()),
      tests: z.array(z.string()),
      entryPoints: z.array(z.string()),
      dependencies: z.array(z.string()),
      conflicts: z.array(z.string()),
      partial: z.boolean(),
    })
    .optional(),
  git: z
    .strictObject({
      identity: z.unknown(),
      changes: z.array(z.unknown()),
      history: z.array(z.unknown()),
      diff: z.unknown().nullable(),
    })
    .optional(),
  instruction: z.string().optional(),
});

export type ContextBundle = z.infer<typeof contextBundleSchema>;

import { z } from "zod";

export const fileContextItemSchema = z.strictObject({
  schemaVersion: z.literal(1),
  id: z.string().regex(/^file:[a-f0-9]{64}$/),
  kind: z.literal("file"),
  path: z.string().min(1),
  content: z.string().nullable(),
  contentStatus: z.enum(["complete", "truncated", "omitted", "changed"]),
  provenance: z.strictObject({
    source: z.literal("scanner"),
    confidenceBasis: z.string().min(1),
  }),
  lifecycle: z.enum(["source", "generated", "vendored"]),
  sensitivity: z.literal("unclassified"),
  sha256: z.string().regex(/^[a-f0-9]{64}$/),
  transformations: z.array(z.string()),
});

export type FileContextItem = z.infer<typeof fileContextItemSchema>;

export {
  fileContextItemSchema,
  type FileContextItem,
} from "./file-context-item.js";

import { z } from "zod";

export const DIAGNOSTIC_SCHEMA_VERSION = 1 as const;

export const severitySchema = z.enum(["info", "warning", "error"]);

export type Severity = z.infer<typeof severitySchema>;

export const sourceLocationSchema = z
  .strictObject({
    path: z.string().min(1),
    line: z.number().int().positive().optional(),
    column: z.number().int().positive().optional(),
  })
  .refine(({ column, line }) => column === undefined || line !== undefined, {
    message: "column requires line",
    path: ["column"],
  });

export type SourceLocation = z.infer<typeof sourceLocationSchema>;

export const diagnosticSchema = z.strictObject({
  schemaVersion: z.literal(DIAGNOSTIC_SCHEMA_VERSION),
  code: z.string().regex(/^[A-Z][A-Z0-9_]*(?:\.[A-Z0-9_]+)*$/),
  severity: severitySchema,
  source: z.string().min(1),
  message: z.string().min(1),
  remediation: z.string().min(1).optional(),
  location: sourceLocationSchema.optional(),
});

export type Diagnostic = z.infer<typeof diagnosticSchema>;

export function parseDiagnostic(input: unknown): Diagnostic {
  return diagnosticSchema.parse(input);
}

export function serializeDiagnostic(diagnostic: Diagnostic): string {
  const validated = parseDiagnostic(diagnostic);
  return JSON.stringify(validated);
}

import { z } from "zod";

export const EXIT_CODES = {
  success: 0,
  validation: 2,
  environment: 3,
  partial: 4,
  internal: 70,
  cancelled: 130,
} as const;

export const exitCodeSchema = z.union([
  z.literal(EXIT_CODES.success),
  z.literal(EXIT_CODES.validation),
  z.literal(EXIT_CODES.environment),
  z.literal(EXIT_CODES.partial),
  z.literal(EXIT_CODES.internal),
  z.literal(EXIT_CODES.cancelled),
]);

export type ExitCode = z.infer<typeof exitCodeSchema>;
export type ExitCodeKind = keyof typeof EXIT_CODES;

import { z } from "zod";

export const fileRecordSchema = z.strictObject({
  schemaVersion: z.literal(1),
  path: z.string().min(1),
  kind: z.enum(["text", "binary", "symlink", "other"]),
  extension: z.string(),
  language: z.strictObject({
    name: z.string().min(1),
    confidence: z.number().min(0).max(1),
  }),
  sizeBytes: z.number().int().nonnegative(),
  symlink: z.boolean(),
  generated: z.boolean(),
  vendored: z.boolean(),
  readable: z.boolean(),
});

export type FileRecord = z.infer<typeof fileRecordSchema>;

import { z } from "zod";

export const gitIdentitySchema = z.strictObject({
  schemaVersion: z.literal(1),
  available: z.boolean(),
  root: z.string().nullable(),
  head: z
    .string()
    .regex(/^[a-f0-9]{40,64}$/)
    .nullable(),
  branch: z.string().nullable(),
  detached: z.boolean(),
  dirty: z.boolean(),
  remotes: z.array(
    z.strictObject({
      name: z.string().min(1),
      url: z.string().min(1),
    }),
  ),
