import { z } from "zod";
export const LOCAL_INDEX_SCHEMA_VERSION = 1 as const;
export const localIndexRepositoryIdSchema = z .string() .regex(/^sha256:[a-f0-9]{64}$/);
export const localIndexStatusSchema = z .object({ schemaVersion: z.literal(LOCAL_INDEX_SCHEMA_VERSION), repositoryId: localIndexRepositoryIdSchema, path: z.string().min(1), state: z.enum([ "absent", "ready", "stale", "incomplete", "corrupt", "schema-mismatch", "repository-mismatch", "policy-mismatch", "rebuild-required", "locked", ]), rebuildRequired: z.boolean(), lockOwner: z.string().min(1).nullable(), }) .strict();
export type LocalIndexStatus = z.infer<typeof localIndexStatusSchema>;

import { z } from "zod";

export const INCREMENTAL_INDEX_SCHEMA_VERSION = 1 as const;

export const INCREMENTAL_INDEX_LIMITS = Object.freeze({
  pathBytes: 4096,
  identityBytes: 512,
  diagnosticMessageBytes: 8192,
  metadataEntries: 128,
  symbolsPerAnalysis: 10_000,
  graphNodes: 100_000,
  graphEdges: 500_000,
  transactionChanges: 100_000,
  verificationChecks: 1_000,
});

const versionSchema = z.literal(INCREMENTAL_INDEX_SCHEMA_VERSION);
const repositoryIdSchema = z.string().regex(/^sha256:[a-f0-9]{64}$/u);
const contentHashSchema = z.string().regex(/^sha256:[a-f0-9]{64}$/u);
const timestampSchema = z.string().datetime({ offset: true });
const pathSchema = z
  .string()
  .min(1)
  .max(INCREMENTAL_INDEX_LIMITS.pathBytes)
  .refine(
    (path) =>
      path === path.normalize("NFC") &&
      !path.startsWith("/") &&
      !path.includes("\\") &&
      !path.split("/").some((segment) => segment === "." || segment === "..") &&
      !/^[A-Za-z]:/u.test(path),
    { message: "Index paths must be canonical repository-relative paths" },
  );
const identitySchema = z
  .string()
  .min(1)
  .max(INCREMENTAL_INDEX_LIMITS.identityBytes);
const safeMetadataSchema = z
  .record(
    z.string().min(1).max(128),
    z.string().max(INCREMENTAL_INDEX_LIMITS.identityBytes),
  )
  .refine(
    (metadata) =>
      Object.keys(metadata).length <= INCREMENTAL_INDEX_LIMITS.metadataEntries,
    { message: "Index metadata exceeds the bounded entry count" },
  );

export const incrementalRepositoryMetadataSchema = z.strictObject({
  recordType: z.literal("repository-metadata"),
  schemaVersion: versionSchema,
  repositoryId: repositoryIdSchema,
  fuzitVersion: identitySchema,
  createdAt: timestampSchema,
  updatedAt: timestampSchema,
  metadata: safeMetadataSchema,
});

export const canonicalIndexFileRecordSchema = z.strictObject({
  recordType: z.literal("file"),
  schemaVersion: versionSchema,
  path: pathSchema,
  contentHash: contentHashSchema,
  sizeBytes: z.number().int().nonnegative(),
  mtimeMs: z.number().finite().nonnegative().nullable(),
  classification: z.enum(["text", "binary", "symlink", "other"]),
  securityDecision: z.strictObject({
    outcome: z.enum(["include", "exclude", "redact"]),
    reason: z
      .string()
      .min(1)
      .max(INCREMENTAL_INDEX_LIMITS.diagnosticMessageBytes),
  }),
  completeness: z.enum(["complete", "partial", "unavailable"]),
});

export const incrementalAnalysisRecordSchema = z.strictObject({
  recordType: z.literal("analysis"),
  schemaVersion: versionSchema,
  path: pathSchema,
  contentHash: contentHashSchema,
  parserIdentity: identitySchema,
  policyIdentity: identitySchema,
  symbols: z
    .array(
      z.strictObject({
        id: identitySchema,
        kind: identitySchema,
        name: identitySchema,
      }),
    )
    .max(INCREMENTAL_INDEX_LIMITS.symbolsPerAnalysis),
  completeness: z.enum(["complete", "partial", "unavailable"]),
  diagnostics: z
    .array(z.string().max(INCREMENTAL_INDEX_LIMITS.diagnosticMessageBytes))
    .max(INCREMENTAL_INDEX_LIMITS.metadataEntries),
});

const graphNodeSchema = z.strictObject({
  id: identitySchema,
  kind: identitySchema,
  path: pathSchema.nullable(),
});
const graphEdgeSchema = z.strictObject({
  from: identitySchema,
  to: identitySchema,
  kind: identitySchema,
});

export const incrementalGraphRecordSchema = z.strictObject({
  recordType: z.literal("graph"),
  schemaVersion: versionSchema,
  graphIdentity: identitySchema,
  nodes: z.array(graphNodeSchema).max(INCREMENTAL_INDEX_LIMITS.graphNodes),
  edges: z.array(graphEdgeSchema).max(INCREMENTAL_INDEX_LIMITS.graphEdges),
  completeness: z.enum(["complete", "partial"]),
});

export const incrementalTombstoneSchema = z.strictObject({
  recordType: z.literal("tombstone"),
  schemaVersion: versionSchema,
  tombstoneId: z
    .string()
    .regex(/^sha256:[a-f0-9]{64}$/u)
    .optional(),
  path: pathSchema,
  previousContentHash: contentHashSchema.nullable(),
  deletedAt: timestampSchema,
  reason: z.enum(["deleted", "renamed", "excluded", "unavailable"]),
  deletionBasis: z
    .enum(["canonical-state-diff", "verified-filesystem", "policy-change"])
    .optional(),
  invalidationIdentity: identitySchema.optional(),
  renamedTo: pathSchema.nullable().optional(),
  invalidatedRecordTypes: z
    .array(z.enum(["file", "analysis", "graph"]))
    .max(3)
    .optional(),
});

const transactionChangeSchema = z.discriminatedUnion("operation", [
  z.strictObject({ operation: z.literal("upsert"), path: pathSchema }),
  z.strictObject({ operation: z.literal("tombstone"), path: pathSchema }),
]);

export const incrementalTransactionSchema = z.strictObject({
  recordType: z.literal("transaction"),
  schemaVersion: versionSchema,
  transactionId: identitySchema,
  repositoryId: repositoryIdSchema,
  state: z.enum(["staged", "committed", "aborted"]),
  startedAt: timestampSchema,
  completedAt: timestampSchema.nullable(),
  changes: z
    .array(transactionChangeSchema)
    .max(INCREMENTAL_INDEX_LIMITS.transactionChanges),
});

export const incrementalLockStateSchema = z.strictObject({
  recordType: z.literal("lock"),
  schemaVersion: versionSchema,
  repositoryId: repositoryIdSchema,
  ownerId: identitySchema,
  processId: z.number().int().positive(),
  acquiredAt: timestampSchema,
  heartbeatAt: timestampSchema,
});

export const incrementalDiagnosticRecordSchema = z.strictObject({
  recordType: z.literal("diagnostic"),
  schemaVersion: versionSchema,
  code: identitySchema,
  severity: z.enum(["info", "warning", "error"]),
  message: z
    .string()
    .min(1)
    .max(INCREMENTAL_INDEX_LIMITS.diagnosticMessageBytes),
  path: pathSchema.nullable(),
  recoverable: z.boolean(),
});

export const incrementalVerificationResultSchema = z.strictObject({
  recordType: z.literal("verification-result"),
  schemaVersion: versionSchema,
  repositoryId: repositoryIdSchema,
  verifiedAt: timestampSchema,
  status: z.enum(["valid", "invalid", "rebuild-required"]),
  checks: z
    .array(
      z.strictObject({
        name: identitySchema,
        status: z.enum(["pass", "fail", "skipped"]),
        reason: z
          .string()
          .max(INCREMENTAL_INDEX_LIMITS.diagnosticMessageBytes)
          .nullable(),
      }),
    )
    .max(INCREMENTAL_INDEX_LIMITS.verificationChecks),
});

export const incrementalIndexRecordSchema = z.discriminatedUnion("recordType", [
  incrementalRepositoryMetadataSchema,
  canonicalIndexFileRecordSchema,
  incrementalAnalysisRecordSchema,
  incrementalGraphRecordSchema,
  incrementalTombstoneSchema,
  incrementalTransactionSchema,
  incrementalLockStateSchema,
  incrementalDiagnosticRecordSchema,
  incrementalVerificationResultSchema,
]);

export type IncrementalIndexRecord = z.infer<
  typeof incrementalIndexRecordSchema
>;

export function parseIncrementalIndexRecord(
  value: unknown,
): IncrementalIndexRecord {
  return incrementalIndexRecordSchema.parse(value);
}

export function serializeIncrementalIndexRecord(
  value: IncrementalIndexRecord,
): string {
  return `${JSON.stringify(incrementalIndexRecordSchema.parse(value))}\n`;
}

import { z } from "zod";

export const PLUGIN_MANIFEST_SCHEMA_VERSION = 1 as const;

/**
 * Valid plugin capability identifier.
 */
export const pluginCapabilitySchema = z.enum([
  "provider",
  "parser",
  "collector",
  "renderer",
  "policy",
  "profile",
  "secret-detector",
  "ranker",
  "graph-enricher",
]);

export type PluginCapability = z.infer<typeof pluginCapabilitySchema>;

/**
 * Path string validator preventing path traversal, absolute paths, and null bytes.
 */
function isSafeRelativePath(pathStr: string): boolean {
  if (!pathStr || typeof pathStr !== "string") return false;
  if (pathStr.includes("\0")) return false;
  if (pathStr.includes("..")) return false;
  if (pathStr.startsWith("/") || pathStr.startsWith("\\")) return false;
  if (/^[a-zA-Z]:[/\\]/.test(pathStr)) return false;
  return true;
}

const safeRelativePathSchema = z
  .string()
  .min(1)
  .refine((val) => isSafeRelativePath(val), {
    message:
      "Path must be a safe relative path without leading slash, drive letter, or '..' traversal",
  });

/**
 * Plugin permission configuration schema (deny by default).
 */
export const pluginPermissionsSchema = z
  .strictObject({
    filesystem: z
      .strictObject({
        readPaths: z.array(safeRelativePathSchema).optional(),
        writePaths: z.array(safeRelativePathSchema).optional(),
      })
      .optional(),
    network: z
      .strictObject({
        allowedHosts: z
          .array(
            z
              .string()
              .min(1)
              .regex(/^[a-zA-Z0-9.-]+$/, {
                message:
                  "allowedHosts must be valid hostnames without scheme or path",
              }),
          )
          .optional(),
      })
      .optional(),
    shell: z.boolean().optional().default(false),
    environment: z
      .strictObject({
        allowedVars: z
          .array(
            z
              .string()
              .min(1)
              .regex(/^[a-zA-Z_][a-zA-Z0-9_]*$/, {
                message: "Environment variable names must be valid identifiers",
              }),
          )
          .optional(),
      })
      .optional(),
    credentials: z
      .strictObject({
        allowedKeys: z.array(z.string().min(1)).optional(),
      })
      .optional(),
    persistence: z.boolean().optional().default(false),
  })
  .optional();

export type PluginPermissions = z.infer<typeof pluginPermissionsSchema>;

/**
 * Signed metadata / integrity placeholder schema.
 */
export const pluginIntegritySchema = z.strictObject({
  checksum: z.string().min(1).optional(),
  signature: z.string().min(1).optional(),
  algorithm: z.string().min(1).optional(),
});

export type PluginIntegrity = z.infer<typeof pluginIntegritySchema>;

/**
 * Plugin output schema declaration.
 */
export const pluginOutputSchemaItemSchema = z.strictObject({
  type: z.string().min(1),
  schemaVersion: z.number().int().positive(),
});

export type PluginOutputSchemaItem = z.infer<
  typeof pluginOutputSchemaItemSchema
>;

/**
 * Semver string validation helper (matches standard semver like 1.0.0, 0.1.0-alpha.1).
 */
const semverRegex =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

/**
 * Compatible range string helper (e.g. >=1.0.0 <2.0.0, ^1.0.0, ~1.2.0, 1.0.0).
 */
const semverRangeRegex =
  /^[~^>=<]*\s*\d+\.\d+\.\d+(?:-[a-zA-Z0-9.-]+)?(?:\s+[~^>=<]*\s*\d+\.\d+\.\d+(?:-[a-zA-Z0-9.-]+)?)*$/;

/**
 * Plugin manifest schema.
 */
export const pluginManifestSchema = z.strictObject({
  schemaVersion: z
    .literal(PLUGIN_MANIFEST_SCHEMA_VERSION)
    .default(PLUGIN_MANIFEST_SCHEMA_VERSION),
  id: z
    .string()
    .min(1)
    .max(128)
    .regex(/^[a-z0-9-]+(?:\.[a-z0-9-]+)*$/, {
      message:
        "Plugin ID must consist of lowercase alphanumeric segments separated by dots or hyphens (e.g. org.plugin-name)",
    })
    .refine(
      (val) => !val.includes("/") && !val.includes("\\") && !val.includes(".."),
      {
        message:
          "Plugin ID must not contain path delimiters or traversal components",
      },
    ),
  name: z.string().min(1).max(128),
  version: z.string().min(1).regex(semverRegex, {
    message: "Version must be a valid semver string (e.g. 1.0.0)",
  }),
  protocol: z.string().min(1).default("fuzit-plugin-v1"),
  fuzitVersion: z.string().min(1).regex(semverRangeRegex, {
    message:
      "fuzitVersion must be a valid semver version or range (e.g. ^1.0.0 or >=1.0.0 <2.0.0)",
  }),
  entryPoint: safeRelativePathSchema,
  description: z.string().max(512).optional(),
  capabilities: z.array(pluginCapabilitySchema).min(1, {
    message: "Plugin must declare at least one capability",
  }),
  permissions: pluginPermissionsSchema,
  outputSchemas: z.array(pluginOutputSchemaItemSchema).optional(),
  integrity: pluginIntegritySchema.optional(),
});

export type PluginManifest = z.infer<typeof pluginManifestSchema>;

export function parsePluginManifest(input: unknown): PluginManifest {
  return pluginManifestSchema.parse(input);
}

export function validatePluginManifest(
  input: unknown,
):
  | { success: true; data: PluginManifest }
  | { success: false; errors: string[] } {
  const result = pluginManifestSchema.safeParse(input);
  if (result.success) {
    return { success: true, data: result.data };
  }
  return {
    success: false,
    errors: result.error.issues.map((e) => `${e.path.join(".")}: ${e.message}`),
  };
}

export function serializePluginManifest(manifest: PluginManifest): string {
  const validated = parsePluginManifest(manifest);
  return JSON.stringify(validated, null, 2);
}

import { Buffer } from "node:buffer";
import { z } from "zod";
import { diagnosticSchema } from "../diagnostic.js";
import { pluginCapabilitySchema, pluginPermissionsSchema } from "./manifest.js";

/**
 * Maximum permitted plugin payload size in bytes (16 MB).
 * Enforces bounded message size constraints to prevent unbounded memory allocation.
 */
export const MAX_PLUGIN_FRAME_BYTES = 16 * 1024 * 1024;

/**
 * Standard plugin protocol version identifier.
 */
export const PLUGIN_PROTOCOL_VERSION = "fuzit-plugin-v1" as const;

/**
 * Common base frame envelope schema.
 */
export const pluginMessageHeaderSchema = z.strictObject({
  requestId: z.string().min(1),
  timestamp: z.number().int().positive().optional(),
});

/**
 * Handshake Request (capability negotiation & version check).
 */
export const pluginHandshakeRequestSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("handshake_request"),
  pluginId: z.string().min(1),
  protocolVersion: z.string().min(1),
  requestedCapabilities: z.array(pluginCapabilitySchema).min(1),
  permissions: pluginPermissionsSchema.optional(),
});

export type PluginHandshakeRequest = z.infer<
  typeof pluginHandshakeRequestSchema
>;

/**
 * Handshake Response.
 */
export const pluginHandshakeResponseSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("handshake_response"),
  success: z.boolean(),
  acceptedCapabilities: z.array(pluginCapabilitySchema),
  error: z.string().optional(),
});

export type PluginHandshakeResponse = z.infer<
  typeof pluginHandshakeResponseSchema
>;

/**
 * Execution Request.
 */
export const pluginExecuteRequestSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("execute_request"),
  capability: pluginCapabilitySchema,
  payload: z.unknown(),
  timeoutMs: z.number().int().positive().optional(),
});

export type PluginExecuteRequest = z.infer<typeof pluginExecuteRequestSchema>;

/**
 * Execution Response.
 */
export const pluginExecuteResponseSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("execute_response"),
  success: z.boolean(),
  data: z.unknown().optional(),
  error: z.string().optional(),
  diagnostics: z.array(diagnosticSchema).optional(),
});

export type PluginExecuteResponse = z.infer<typeof pluginExecuteResponseSchema>;

/**
 * Cancellation Request.
 */
export const pluginCancelRequestSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("cancel_request"),
  targetRequestId: z.string().min(1),
  reason: z.string().optional(),
});

export type PluginCancelRequest = z.infer<typeof pluginCancelRequestSchema>;

/**
 * Diagnostic Event.
 */
export const pluginDiagnosticEventSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("diagnostic_event"),
  diagnostic: diagnosticSchema,
});

export type PluginDiagnosticEvent = z.infer<typeof pluginDiagnosticEventSchema>;

/**
 * Shutdown Request.
 */
export const pluginShutdownRequestSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("shutdown_request"),
});

export type PluginShutdownRequest = z.infer<typeof pluginShutdownRequestSchema>;

/**
 * Shutdown Response.
 */
export const pluginShutdownResponseSchema = pluginMessageHeaderSchema.extend({
  type: z.literal("shutdown_response"),
  success: z.boolean(),
});

export type PluginShutdownResponse = z.infer<
  typeof pluginShutdownResponseSchema
>;

/**
 * Discriminated union of all framed plugin protocol messages.
 */
export const pluginMessageSchema = z.discriminatedUnion("type", [
  pluginHandshakeRequestSchema,
  pluginHandshakeResponseSchema,
  pluginExecuteRequestSchema,
  pluginExecuteResponseSchema,
  pluginCancelRequestSchema,
  pluginDiagnosticEventSchema,
  pluginShutdownRequestSchema,
  pluginShutdownResponseSchema,
]);

export type PluginMessage = z.infer<typeof pluginMessageSchema>;

export function parsePluginMessage(input: unknown): PluginMessage {
  return pluginMessageSchema.parse(input);
}

/**
 * Encodes a PluginMessage into a length-prefixed frame Buffer.
 * Frame structure: [4 bytes uint32 BE length header][JSON payload UTF-8 bytes]
 */
export function encodePluginFrame(message: PluginMessage): Buffer {
  const validated = parsePluginMessage(message);
  const jsonStr = JSON.stringify(validated);
  const payloadBuffer = Buffer.from(jsonStr, "utf-8");

  if (payloadBuffer.length > MAX_PLUGIN_FRAME_BYTES) {
    throw new Error(
      `Plugin frame payload size (${payloadBuffer.length} bytes) exceeds maximum permitted limit (${MAX_PLUGIN_FRAME_BYTES} bytes)`,
    );
  }

  const frameHeader = Buffer.alloc(4);
  frameHeader.writeUInt32BE(payloadBuffer.length, 0);

  return Buffer.concat([frameHeader, payloadBuffer]);
}

/**
 * Stateful stream decoder for processing length-prefixed stdio plugin frames.
 * Handles fragmented chunks, coalesced messages, max size bounds, and malformed JSON.
 */
export class PluginFrameDecoder {
  private buffer: Buffer = Buffer.alloc(0);
  private maxFrameBytes: number;

  constructor(maxFrameBytes: number = MAX_PLUGIN_FRAME_BYTES) {
    this.maxFrameBytes = maxFrameBytes;
  }

  /**
   * Push incoming chunk to internal buffer and extract completed frames.
   */
  public push(chunk: Buffer): PluginMessage[] {
    this.buffer = Buffer.concat([this.buffer, chunk]);
    const messages: PluginMessage[] = [];

    while (this.buffer.length >= 4) {
      const payloadLength = this.buffer.readUInt32BE(0);

      if (payloadLength > this.maxFrameBytes) {
        // Reset buffer and fail closed to prevent memory allocation attack
        this.buffer = Buffer.alloc(0);
        throw new Error(
          `Oversized frame header encountered (${payloadLength} bytes). Maximum allowed limit is ${this.maxFrameBytes} bytes. Stream reset.`,
        );
      }

      if (this.buffer.length < 4 + payloadLength) {
        // Partial frame, await more data
        break;
      }

      const payloadBuffer = this.buffer.subarray(4, 4 + payloadLength);
      this.buffer = this.buffer.subarray(4 + payloadLength);

      try {
        const jsonStr = payloadBuffer.toString("utf-8");
        const jsonObject = JSON.parse(jsonStr);
        const message = parsePluginMessage(jsonObject);
        messages.push(message);
      } catch (err) {
        throw new Error(
          `Failed to parse plugin frame: ${err instanceof Error ? err.message : String(err)}`,
          { cause: err },
        );
      }
    }

    return messages;
  }

  /**
   * Reset the decoder buffer.
   */
  public reset(): void {
    this.buffer = Buffer.alloc(0);
  }

  /**
   * Returns current buffered byte length.
   */
  public get bufferedBytes(): number {
    return this.buffer.length;
  }
}

/**
 * Provider schema exports.
 */

export * from "./source-ref.js";
export * from "./network-policy.js";
export * from "./records.js";

/**
 * Provider network policy contracts.
 *
 * Defines deny-by-default network authorization for GitHub operations.
 * Local-only commands must perform zero network calls.
 *
 * @module
 */

import type { SourceRef } from "./source-ref.js";

// ---------------------------------------------------------------------------
// Authorization reasons
// ---------------------------------------------------------------------------

export type NetworkAuthorizationReason =
  | "source-is-github-url"
  | "source-is-github-pr"
  | "source-is-github-issue"
  | "command-is-review"
  | "command-is-pr"
  | "command-is-issue"
  | "command-is-provider"
  | "explicit-enrichment-option";

export type NetworkDenialReason =
  | "local-source-no-enrichment"
  | "unsupported-host"
  | "unrelated-redirect"
  | "enterprise-host-not-configured";

// ---------------------------------------------------------------------------
// Network policy result
// ---------------------------------------------------------------------------

export type NetworkPolicyResult =
  | {
      readonly authorized: true;
      readonly reason: NetworkAuthorizationReason;
      /** Exact set of hosts allowed. Never contains tokens or credentials. */
      readonly allowedHosts: readonly string[];
    }
  | {
      readonly authorized: false;
      readonly reason: NetworkDenialReason;
      /** Human-readable explanation safe to show in diagnostics. */
      readonly explanation: string;
    };

// ---------------------------------------------------------------------------
// Command context that triggers authorization
// ---------------------------------------------------------------------------

export type ProviderCommand =
  "review" | "pr" | "issue" | "provider" | "context" | "scan";

// ---------------------------------------------------------------------------
// Policy evaluation
// ---------------------------------------------------------------------------

/**
 * Evaluate the network policy for a given source and command context.
 *
 * Returns an authorized result with allowed hosts, or a denied result with
 * an explanation. Never contacts the network. Never includes tokens.
 */
export function evaluateNetworkPolicy(
  source: SourceRef,
  command: ProviderCommand,
  options?: {
    /** The user has explicitly requested GitHub enrichment for a local source. */
    readonly explicitEnrichment?: boolean;
    /** Allowed enterprise host set from configuration. */
    readonly allowedEnterpriseHosts?: readonly string[];
  },
): NetworkPolicyResult {
  const { explicitEnrichment = false, allowedEnterpriseHosts = [] } =
    options ?? {};

  // Remote GitHub sources always authorize network
  if (source.kind === "github-repository") {
    const hosts = buildAllowedHosts(source.host.webHost, source.host.apiHost);
    if (
      source.host.isEnterprise &&
      !isEnterpriseHostAllowed(source.host.webHost, allowedEnterpriseHosts)
    ) {
      return {
        authorized: false,
        reason: "enterprise-host-not-configured",
        explanation: `GitHub Enterprise host '${source.host.webHost}' is not in the configured allow list. Add it to your Fuzit configuration.`,
      };
    }
    return {
      authorized: true,
      reason: "source-is-github-url",
      allowedHosts: hosts,
    };
  }

  if (source.kind === "github-pull-request") {
    if (
      source.host.isEnterprise &&
      !isEnterpriseHostAllowed(source.host.webHost, allowedEnterpriseHosts)
    ) {
      return {
        authorized: false,
        reason: "enterprise-host-not-configured",
        explanation: `GitHub Enterprise host '${source.host.webHost}' is not in the configured allow list.`,
      };
    }
    return {
      authorized: true,
      reason: "source-is-github-pr",
      allowedHosts: buildAllowedHosts(source.host.webHost, source.host.apiHost),
    };
  }

  if (source.kind === "github-issue") {
    if (
      source.host.isEnterprise &&
      !isEnterpriseHostAllowed(source.host.webHost, allowedEnterpriseHosts)
    ) {
      return {
        authorized: false,
        reason: "enterprise-host-not-configured",
        explanation: `GitHub Enterprise host '${source.host.webHost}' is not in the configured allow list.`,
      };
    }
    return {
      authorized: true,
      reason: "source-is-github-issue",
      allowedHosts: buildAllowedHosts(source.host.webHost, source.host.apiHost),
    };
  }

  // Local source: deny by default unless explicit command or enrichment
  if (source.kind === "local") {
    if (command === "review") {
      return {
        authorized: true,
        reason: "command-is-review",
        allowedHosts: ["github.com", "api.github.com"],
      };
    }
    if (command === "pr") {
      return {
        authorized: true,
        reason: "command-is-pr",
        allowedHosts: ["github.com", "api.github.com"],
      };
    }
    if (command === "issue") {
      return {
        authorized: true,
        reason: "command-is-issue",
        allowedHosts: ["github.com", "api.github.com"],
      };
    }
    if (command === "provider") {
      return {
        authorized: true,
        reason: "command-is-provider",
        allowedHosts: ["github.com", "api.github.com"],
      };
    }
    if (explicitEnrichment) {
      return {
        authorized: true,
        reason: "explicit-enrichment-option",
        allowedHosts: ["github.com", "api.github.com"],
      };
    }
    return {
      authorized: false,
      reason: "local-source-no-enrichment",
      explanation:
        "Local repository operations do not contact GitHub by default. Use a GitHub URL, or pass --enrich-github for explicit enrichment.",
    };
  }

  // Unreachable for well-typed SourceRef, but kept for safety
  return {
    authorized: false,
    reason: "unsupported-host",
    explanation: "Unrecognized source kind; network access is denied.",
  };
}

/**
 * Validate that a redirect target is within the allowed host set.
 * Returns false for any redirect to an unrelated host.
 */
export function isRedirectAllowed(
  redirectUrl: string,
  allowedHosts: readonly string[],
): boolean {
  let url: URL;
  try {
    url = new URL(redirectUrl);
  } catch {
    return false;
  }
  if (url.protocol !== "https:") return false;
  return allowedHosts.some(
    (host) => url.hostname === host || url.hostname.endsWith(`.${host}`),
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function buildAllowedHosts(
  webHost: string,
  apiHost: string,
): readonly string[] {
  const hosts = new Set<string>();
  hosts.add(webHost);
  // apiHost may be "api.github.com" or "host/api/v3" — extract the hostname
  try {
    const url = new URL(`https://${apiHost}`);
    hosts.add(url.hostname);
  } catch {
    // apiHost already normalized
    const firstSeg = apiHost.split("/")[0];
    if (firstSeg) hosts.add(firstSeg);
  }
  return [...hosts];
}

function isEnterpriseHostAllowed(
  host: string,
  allowedEnterpriseHosts: readonly string[],
): boolean {
  return allowedEnterpriseHosts.some((h) => h === host);
}

/**
 * Strict generic provider schemas and GitHub record normalization.
 *
 * Defines versioned normalized provider record types used across core selection,
 * graph, budgeting, and rendering pipelines.
 *
 * @module
 */

import type { GitHubHostIdentity } from "./source-ref.js";

export const PROVIDER_RECORDS_SCHEMA_VERSION = 1 as const;

export type ProviderRecordKind =
  | "repository"
  | "ref"
  | "commit"
  | "comparison"
  | "pull-request"
  | "pull-request-file"
  | "patch"
  | "review"
  | "review-comment"
  | "review-thread"
  | "issue"
  | "issue-comment"
  | "check-suite"
  | "check-run"
  | "commit-status"
  | "diagnostic"
  | "tombstone";

export interface BaseProviderRecord {
  readonly schemaVersion: typeof PROVIDER_RECORDS_SCHEMA_VERSION;
  readonly id: string;
  readonly kind: ProviderRecordKind;
  readonly provider: "github";
  readonly host: GitHubHostIdentity;
  readonly repositoryFullName: string;
  readonly observedAt: string;
  readonly completeness: "full" | "partial";
  readonly sensitivity: "public" | "private" | "internal";
}

export interface RefRecord extends BaseProviderRecord {
  readonly kind: "ref";
  readonly refName: string;
  readonly sha: string;
  readonly isDefaultBranch: boolean;
}

export interface CommitRecord extends BaseProviderRecord {
  readonly kind: "commit";
  readonly sha: string;
  readonly authorName: string;
  readonly message: string;
  readonly parentShas: readonly string[];
}

export interface PullRequestRecord extends BaseProviderRecord {
  readonly kind: "pull-request";
  readonly number: number;
  readonly title: string;
  readonly body: string;
  readonly state: "open" | "closed" | "merged";
  readonly isDraft: boolean;
  readonly authorLogin: string;
  readonly baseRef: string;
  readonly baseSha: string;
  readonly headRef: string;
  readonly headSha: string;
  readonly labels: readonly string[];
}

export interface PullRequestFileRecord extends BaseProviderRecord {
  readonly kind: "pull-request-file";
  readonly prNumber: number;
  readonly path: string;
  readonly status: "added" | "modified" | "removed" | "renamed";
  readonly additions: number;
  readonly deletions: number;
  readonly previousPath?: string;
}

export interface PatchRecord extends BaseProviderRecord {
  readonly kind: "patch";
  readonly prNumber: number;
  readonly path: string;
  readonly patchContent: string;
  readonly isTruncated: boolean;
}

export interface ReviewRecord extends BaseProviderRecord {
  readonly kind: "review";
  readonly prNumber: number;
  readonly reviewId: number;
  readonly authorLogin: string;
  readonly state: "APPROVED" | "CHANGES_REQUESTED" | "COMMENTED" | "DISMISSED";
  readonly body: string;
}

export interface ReviewCommentRecord extends BaseProviderRecord {
  readonly kind: "review-comment";
  readonly prNumber: number;
  readonly commentId: number;
  readonly path: string;
  readonly line?: number;
  readonly authorLogin: string;
  readonly body: string;
}

export interface ReviewThreadRecord extends BaseProviderRecord {
  readonly kind: "review-thread";
  readonly prNumber: number;
  readonly threadId: string;
  readonly path: string;
  readonly isResolved: boolean;
  readonly comments: readonly ReviewCommentRecord[];
}

export interface IssueRecord extends BaseProviderRecord {
  readonly kind: "issue";
  readonly number: number;
  readonly title: string;
  readonly body: string;
  readonly state: "open" | "closed";
  readonly authorLogin: string;
  readonly labels: readonly string[];
}

export interface IssueCommentRecord extends BaseProviderRecord {
  readonly kind: "issue-comment";
  readonly issueNumber: number;
  readonly commentId: number;
  readonly authorLogin: string;
  readonly body: string;
}

export interface CheckRunRecord extends BaseProviderRecord {
  readonly kind: "check-run";
  readonly headSha: string;
  readonly name: string;
  readonly status: "queued" | "in_progress" | "completed";
  readonly conclusion?:
    | "success"
    | "failure"
    | "neutral"
    | "cancelled"
    | "timed_out"
    | "action_required";
  readonly summary?: string;
}

export interface CommitStatusRecord extends BaseProviderRecord {
  readonly kind: "commit-status";
  readonly headSha: string;
  readonly context: string;
  readonly state: "error" | "failure" | "pending" | "success";
  readonly description?: string;
}

export interface ProviderDiagnosticRecord extends BaseProviderRecord {
  readonly kind: "diagnostic";
  readonly category: string;
  readonly message: string;
  readonly severity: "info" | "warning" | "error";
}

export interface TombstoneRecord extends BaseProviderRecord {
  readonly kind: "tombstone";
  readonly originalKind: ProviderRecordKind;
  readonly reason: string;
}

export type NormalizedProviderRecord =
  | RefRecord
  | CommitRecord
  | PullRequestRecord
  | PullRequestFileRecord
  | PatchRecord
  | ReviewRecord
  | ReviewCommentRecord
  | ReviewThreadRecord
  | IssueRecord
  | IssueCommentRecord
  | CheckRunRecord
  | CommitStatusRecord
  | ProviderDiagnosticRecord
  | TombstoneRecord;

export function buildStableRecordId(
  provider: "github",
  host: string,
  repoFullName: string,
  kind: ProviderRecordKind,
  entityKey: string | number,
): string {
  return `${provider}:${host}:${repoFullName.toLowerCase()}:${kind}:${entityKey}`;
}

/**
 * Provider-neutral source reference contracts.
 *
 * These types represent the normalized source references consumed by the
 * application layer. GitHub REST shapes and endpoint details are private to
 * `packages/provider-github` and must never appear here.
 *
 * @module
 */

// ---------------------------------------------------------------------------
// Source kinds
// ---------------------------------------------------------------------------

/** A local filesystem path that Fuzit will scan directly. */
export type LocalSourceKind = "local";

/** A remote GitHub repository (github.com or GitHub Enterprise). */
export type GitHubRepositorySourceKind = "github-repository";

/** A GitHub pull request. */
export type GitHubPullRequestSourceKind = "github-pull-request";

/** A GitHub issue. */
export type GitHubIssueSourceKind = "github-issue";

export type SourceKind =
  | LocalSourceKind
  | GitHubRepositorySourceKind
  | GitHubPullRequestSourceKind
  | GitHubIssueSourceKind;

// ---------------------------------------------------------------------------
// GitHub host identity
// ---------------------------------------------------------------------------

/**
 * Identifies a GitHub or GitHub Enterprise host.
 *
 * `webHost` is the canonical web/clone host (e.g. `github.com`).
 * `apiHost` is the REST API host. For github.com this is `api.github.com`.
 * For GitHub Enterprise it is typically `<webHost>/api/v3` or a configured
 * override.
 */
export interface GitHubHostIdentity {
  /** Web and clone host. Never contains credentials. */
  readonly webHost: string;
  /** REST API host (never contains credentials). */
  readonly apiHost: string;
  /** True when this is a GitHub Enterprise (non-github.com) host. */
  readonly isEnterprise: boolean;
}

// ---------------------------------------------------------------------------
// Local source reference
// ---------------------------------------------------------------------------

export interface LocalSourceRef {
  readonly kind: LocalSourceKind;
  /** Absolute filesystem path. */
  readonly path: string;
}

// ---------------------------------------------------------------------------
// GitHub source references
// ---------------------------------------------------------------------------

/**
 * Identifies a GitHub repository without credentials.
 *
 * All fields are derived from parsing the user-supplied input; no network
 * contact occurs during construction.
 */
export interface GitHubRepositoryRef {
  readonly kind: GitHubRepositorySourceKind;
  readonly host: GitHubHostIdentity;
  /** GitHub owner (user or organization). */
  readonly owner: string;
  /** Repository name. */
  readonly repo: string;
  /**
   * Explicit revision (branch, tag, or full SHA). Omitted when the caller
   * intends to use the repository's default branch.
   */
  readonly revision?: string;
}

/**
 * A GitHub pull request identified without credentials.
 */
export interface GitHubPullRequestRef {
  readonly kind: GitHubPullRequestSourceKind;
  readonly host: GitHubHostIdentity;
  readonly owner: string;
  readonly repo: string;
  readonly number: number;
}

/**
 * A GitHub issue identified without credentials.
 */
export interface GitHubIssueRef {
  readonly kind: GitHubIssueSourceKind;
  readonly host: GitHubHostIdentity;
  readonly owner: string;
  readonly repo: string;
  readonly number: number;
}

export type GitHubSourceRef =
  GitHubRepositoryRef | GitHubPullRequestRef | GitHubIssueRef;

export type RemoteSourceRef = GitHubSourceRef;

export type SourceRef = LocalSourceRef | RemoteSourceRef;

// ---------------------------------------------------------------------------
// Parse result types
// ---------------------------------------------------------------------------

export type ParseSourceRefSuccess<T extends SourceRef = SourceRef> = {
  readonly ok: true;
  readonly ref: T;
};

export type ParseSourceRefFailure = {
  readonly ok: false;
  /** Human-readable explanation of why parsing failed. Never contains secrets. */
  readonly reason: string;
};

export type ParseSourceRefResult<T extends SourceRef = SourceRef> =
  ParseSourceRefSuccess<T> | ParseSourceRefFailure;

// ---------------------------------------------------------------------------
// Schema version
// ---------------------------------------------------------------------------

export const SOURCE_REF_SCHEMA_VERSION = 1 as const;

import { z } from "zod";

export const rendererMetadataSchema = z.strictObject({
  schemaVersion: z.literal(1),
  format: z.string().regex(/^[a-z][a-z0-9-]*$/),
  mediaType: z.string().min(1),
  extension: z.string().regex(/^\.[a-z0-9]+$/),
  capabilities: z.strictObject({
    binary: z.boolean(),
    diagnostics: z.boolean(),
    provenance: z.boolean(),
  }),
  deterministic: z.literal(true),
});

export type RendererMetadata = z.infer<typeof rendererMetadataSchema>;

import { z } from "zod";

export const repositoryFactKindSchema = z.enum([
  "language",
  "manifest",
  "package",
  "workspace",
  "framework",
  "test",
  "entry-point",
  "service",
  "dependency",
]);
export const repositoryFactSchema = z.strictObject({
  schemaVersion: z.literal(1),
  id: z.string().regex(/^fact:[a-f0-9]{64}$/),
  kind: repositoryFactKindSchema,
  value: z.string().min(1),
  confidence: z.number().min(0).max(1),
  basis: z.enum(["direct", "inferred"]),
  evidence: z.array(z.string()).min(1),
  detector: z.string().min(1),
  conflictsWith: z.array(z.string()),
});
export type RepositoryFact = z.infer<typeof repositoryFactSchema>;
export type RepositoryFactKind = z.infer<typeof repositoryFactKindSchema>;

export {
  repositoryFactKindSchema,
  repositoryFactSchema,
  type RepositoryFact,
