} from "./contracts.js";

import { z } from "zod";

export const sensitivitySchema = z.enum([
  "public",
  "internal",
  "sensitive",
  "restricted",
  "unknown",
]);

export const redactionActionSchema = z.enum([
  "allow",
  "redact",
  "omit",
  "block",
]);

export const findingSchema = z.strictObject({
  schemaVersion: z.literal(1),
