export type ScoreContribution = z.infer<typeof scoreContributionSchema>;
export type SelectionDecision = z.infer<typeof selectionDecisionSchema>;
export type SelectionReport = z.infer<typeof selectionReportSchema>;
export type TaskIntent = z.infer<typeof taskIntentSchema>;

import { z } from "zod";

export const SNAPSHOT_SCHEMA_VERSION = 1 as const;

export const snapshotManifestSchema = z
  .object({
    schemaVersion: z.literal(SNAPSHOT_SCHEMA_VERSION),
    id: z.string().regex(/^snapshot:[a-f0-9]{64}$/),
    repositoryRevision: z.string().nullable(),
    dirty: z.boolean(),
    configHash: z.string().min(1),
    fileFingerprints: z.array(
      z.object({
        path: z.string().min(1),
        sha256: z.string().min(1),
      }),
    ),
    bundleIdentityInputs: z.array(z.string()),
    complete: z.boolean(),
    diagnostics: z.array(z.string()),
    createdAt: z.string(),
  })
  .strict();

export type SnapshotManifest = z.infer<typeof snapshotManifestSchema>;

export {
  SNAPSHOT_SCHEMA_VERSION,
  snapshotManifestSchema,
  type SnapshotManifest,
} from "./contracts.js";

import { z } from "zod";

export const WATCHER_CONTRACT_VERSION = 1 as const;

export const filesystemEventKindSchema = z.enum([
  "add",
  "modify",
  "delete",
  "rename",
  "directory-rename",
  "overflow",
]);

export type FilesystemEventKind = z.infer<typeof filesystemEventKindSchema>;

export const watcherEventSchema = z
  .object({
    contractVersion: z.literal(WATCHER_CONTRACT_VERSION),
    kind: filesystemEventKindSchema,
    path: z.string().min(1),
    renamedTo: z.string().min(1).optional(),
    timestampMs: z.number().positive(),
  })
  .strict();

export type WatcherEvent = z.infer<typeof watcherEventSchema>;

export const watcherBatchSchema = z
  .object({
    contractVersion: z.literal(WATCHER_CONTRACT_VERSION),
    batchId: z.string().min(1),
    events: z.array(watcherEventSchema),
    reconciliationRequired: z.boolean(),
    overflowOccurred: z.boolean(),
  })
  .strict();

export type WatcherBatch = z.infer<typeof watcherBatchSchema>;

export const watcherStatusSchema = z
  .object({
    contractVersion: z.literal(WATCHER_CONTRACT_VERSION),
    state: z.enum([
      "stopped",
      "starting",
      "watching",
      "reconciling",
      "stopping",
      "error",
    ]),
    repositoryRoot: z.string().min(1),
    lockOwner: z.string().min(1).nullable(),
    activeWatchers: z.number().nonnegative(),
    eventsProcessed: z.number().nonnegative(),
    lastEventTimestampMs: z.number().nullable(),
  })
  .strict();

export type WatcherStatus = z.infer<typeof watcherStatusSchema>;

export function validateWatcherEvent(event: unknown): WatcherEvent {
  const parsed = watcherEventSchema.parse(event);
  if (
    parsed.path.startsWith("/") ||
    parsed.path.startsWith("\\") ||
    parsed.path.includes("..")
  ) {
    throw new Error(
      "Watcher event path must be relative to repository root and contain no path traversal.",
    );
  }
  if (
    parsed.renamedTo &&
    (parsed.renamedTo.startsWith("/") ||
      parsed.renamedTo.startsWith("\\") ||
      parsed.renamedTo.includes(".."))
  ) {
    throw new Error(
      "Watcher event renamedTo path must be relative to repository root and contain no path traversal.",
    );
  }
  return parsed;
}

import { describe, expect, it } from "vitest";

import { parseDiagnostic, serializeDiagnostic } from "../src/diagnostic.js";

describe("diagnostic contracts", () => {
  it("parses a valid diagnostic", () => {
    expect(
      parseDiagnostic({
        schemaVersion: 1,
        code: "CONFIG.INVALID",
        severity: "error",
        source: "config",
        message: "Configuration is invalid.",
        remediation: "Correct the configuration value.",
        location: {
          path: "fuzit.config.json",
          line: 3,
          column: 5,
        },
      }),
    ).toEqual({
      schemaVersion: 1,
      code: "CONFIG.INVALID",
      severity: "error",
      source: "config",
      message: "Configuration is invalid.",
      remediation: "Correct the configuration value.",
      location: {
        path: "fuzit.config.json",
        line: 3,
        column: 5,
      },
    });
  });

  it("rejects an invalid severity", () => {
    expect(() =>
      parseDiagnostic({
        schemaVersion: 1,
        code: "CONFIG.INVALID",
        severity: "critical",
        source: "config",
        message: "Configuration is invalid.",
      }),
    ).toThrow();
  });

  it("serializes deterministically without adding timestamps", () => {
    const diagnostic = parseDiagnostic({
      schemaVersion: 1,
      code: "SOURCE.PARTIAL",
      severity: "warning",
      source: "repository",
      message: "One optional source was unavailable.",
    });

    expect(serializeDiagnostic(diagnostic)).toBe(
      '{"schemaVersion":1,"code":"SOURCE.PARTIAL","severity":"warning","source":"repository","message":"One optional source was unavailable."}',
    );
    expect(serializeDiagnostic(diagnostic)).toBe(
      serializeDiagnostic(diagnostic),
    );
    expect(serializeDiagnostic(diagnostic)).not.toContain("timestamp");
  });
});

