export type ExpansionRelationship =
  "dependency" | "reverse-dependency" | "test";

export interface ExpansionEdge {
  readonly from: string;
  readonly to: string;
  readonly relationship: ExpansionRelationship;
  readonly resolved: boolean;
  readonly confidence?: number;
}

export interface ExpansionBounds {
  readonly maximumDepth: number;
  readonly maximumItems: number;
  readonly maximumEdges: number;
  readonly minimumConfidence: number;
  readonly tokenBudget: number;
}

export interface ExpandedCandidate {
  readonly path: string;
  readonly depth: number;
  readonly contribution: number;
  readonly relationshipPath: readonly string[];
  readonly origin: string;
  readonly edgeTypes: readonly ExpansionRelationship[];
  readonly reason: "required-anchor" | "initial-candidate" | "graph-expansion";
  readonly bounds: ExpansionBounds;
  readonly budgetDecision: "included";
  readonly securityDecision: "allowed";
}

export interface ExpansionOptions {
  readonly depth: number;
  readonly decay: number;
  readonly cap: number;
  readonly maximumEdges?: number;
  readonly minimumConfidence?: number;
  readonly tokenBudget?: number;
  readonly tokenCosts?: Readonly<Record<string, number>>;
  readonly allowedRelationships?: readonly ExpansionRelationship[];
  readonly requiredAnchors?: readonly string[];
  readonly securityAllowedPaths?: readonly string[];
  readonly signal?: AbortSignal;
}

/** Deterministic bounded expansion over approved, resolved graph edges. */
export function expandDependencies(
  seeds: readonly string[],
  edges: readonly ExpansionEdge[],
  options: ExpansionOptions,
): ExpandedCandidate[] {
  const anchors = [...new Set(options.requiredAnchors ?? [])].sort();
  const initial = [
    ...anchors,
    ...[...new Set(seeds)].sort().filter((path) => !anchors.includes(path)),
  ];
  const maximumItems = Math.max(options.cap, anchors.length);
  const bounds: ExpansionBounds = {
    maximumDepth: Math.max(0, options.depth),
    maximumItems,
    maximumEdges: Math.max(0, options.maximumEdges ?? edges.length),
    minimumConfidence: Math.max(0, Math.min(1, options.minimumConfidence ?? 0)),
    tokenBudget: Math.max(0, options.tokenBudget ?? Number.MAX_SAFE_INTEGER),
  };
  const allowedRelationships = new Set(
    options.allowedRelationships ?? [
      "dependency",
      "reverse-dependency",
      "test",
    ],
  );
  const securityAllowed =
    options.securityAllowedPaths === undefined
      ? null
      : new Set(options.securityAllowedPaths);
  const queue = initial.map((path) => ({
    path,
    depth: 0,
    contribution: 1,
    relationshipPath: [path],
    origin: path,
    edgeTypes: [] as ExpansionRelationship[],
  }));
  const seen = new Set<string>();
  const result: ExpandedCandidate[] = [];
  let traversedEdges = 0;
  let usedTokens = 0;
  while (
    queue.length &&
    result.length < bounds.maximumItems &&
    !options.signal?.aborted
  ) {
    const current = queue.shift()!;
    if (seen.has(current.path)) continue;
    const required = anchors.includes(current.path);
    if (!required && securityAllowed && !securityAllowed.has(current.path))
      continue;
    const cost = Math.max(0, options.tokenCosts?.[current.path] ?? 1);
    if (!required && usedTokens + cost > bounds.tokenBudget) continue;
    seen.add(current.path);
    usedTokens += cost;
    result.push({
      ...current,
      reason: required
        ? "required-anchor"
        : current.depth === 0
          ? "initial-candidate"
          : "graph-expansion",
      bounds,
      budgetDecision: "included",
      securityDecision: "allowed",
    });
    if (current.depth >= bounds.maximumDepth) continue;
    for (const edge of edges
      .filter(
        (edge) =>
          edge.resolved &&
          allowedRelationships.has(edge.relationship) &&
          (edge.confidence ?? 1) >= bounds.minimumConfidence &&
          (edge.from === current.path || edge.to === current.path),
      )
      .sort((a, b) =>
        `${a.relationship}:${a.from}:${a.to}`.localeCompare(
          `${b.relationship}:${b.from}:${b.to}`,
        ),
      )) {
      if (traversedEdges >= bounds.maximumEdges) break;
      traversedEdges += 1;
      const path = edge.from === current.path ? edge.to : edge.from;
      if (!seen.has(path))
        queue.push({
          path,
          depth: current.depth + 1,
          contribution: current.contribution * options.decay,
          relationshipPath: [
            ...current.relationshipPath,
            `${edge.relationship}:${path}`,
          ],
          origin: current.origin,
          edgeTypes: [...current.edgeTypes, edge.relationship],
        });
    }
  }
  return result;
}

export {
  expandDependencies,
  type ExpandedCandidate,
  type ExpansionEdge,
} from "./expand.js";

export const HYBRID_SCORING_SCHEMA_VERSION = 1 as const;

export interface HybridFeatureVector {
  readonly schemaVersion: 1;
  readonly candidateId: string;
  readonly path: string;
  readonly requiredAnchor: boolean;
  readonly features: Readonly<Record<string, number>>;
}

export interface HybridComponentScore {
  readonly component: string;
  readonly rawValue: number;
  readonly weight: number;
  readonly weightedValue: number;
  readonly basis: string;
}

export interface HybridExpansionEvidence {
  readonly originCandidateId: string;
  readonly graphPath: readonly string[];
  readonly edgeTypes: readonly string[];
  readonly reason: string;
  readonly bounds: Readonly<Record<string, number>>;
}

export interface HybridScoreRecord {
  readonly schemaVersion: 1;
  readonly featureVector: HybridFeatureVector;
  readonly profileId: string;
  readonly profileVersion: number;
  readonly components: readonly HybridComponentScore[];
  readonly aggregateScore: number;
  readonly expansion: HybridExpansionEvidence | null;
  readonly tieBreaker: readonly [path: string, candidateId: string];
}

const finite = (value: number, name: string): number => {
  if (!Number.isFinite(value)) throw new Error(`${name} must be finite`);
  return value;
};

export function createHybridScore(input: {
  readonly featureVector: HybridFeatureVector;
  readonly profileId: string;
  readonly profileVersion: number;
  readonly weights: Readonly<Record<string, number>>;
  readonly basis: Readonly<Record<string, string>>;
  readonly expansion?: HybridExpansionEvidence | null;
}): HybridScoreRecord {
  if (input.featureVector.schemaVersion !== HYBRID_SCORING_SCHEMA_VERSION) {
    throw new Error("Hybrid feature vector version is unsupported");
  }
  if (!Number.isInteger(input.profileVersion) || input.profileVersion < 1) {
    throw new Error("Profile version is required");
  }
  const components = Object.entries(input.featureVector.features)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([component, raw]) => {
      const basis = input.basis[component];
      if (!basis) throw new Error(`Score basis is required for ${component}`);
      const rawValue = finite(raw, `${component} feature`);
      const weight = finite(
        input.weights[component] ?? 0,
        `${component} weight`,
      );
      return {
        component,
        rawValue,
        weight,
        weightedValue: finite(rawValue * weight, `${component} score`),
        basis,
      };
    });
  const aggregateScore = finite(
    components.reduce((sum, component) => sum + component.weightedValue, 0),
    "Aggregate score",
  );
  return {
    schemaVersion: HYBRID_SCORING_SCHEMA_VERSION,
    featureVector: {
      ...input.featureVector,
      features: Object.fromEntries(
        Object.entries(input.featureVector.features).sort(([a], [b]) =>
          a.localeCompare(b),
        ),
      ),
    },
    profileId: input.profileId,
    profileVersion: input.profileVersion,
    components,
    aggregateScore,
    expansion: input.expansion ?? null,
    tieBreaker: [input.featureVector.path, input.featureVector.candidateId],
  };
}

export function compareHybridScores(
  left: HybridScoreRecord,
  right: HybridScoreRecord,
): number {
  return (
    right.aggregateScore - left.aggregateScore ||
    left.tieBreaker[0].localeCompare(right.tieBreaker[0]) ||
    left.tieBreaker[1].localeCompare(right.tieBreaker[1])
  );
}

export function serializeHybridScore(record: HybridScoreRecord): string {
  if (record.schemaVersion !== HYBRID_SCORING_SCHEMA_VERSION) {
    throw new Error("Hybrid score version is unsupported");
  }
  return `${JSON.stringify(record)}\n`;
}

export interface ExactIdentifierEvidence {
  readonly symbols?: readonly string[];
  readonly exports?: readonly string[];
  readonly routes?: readonly string[];
  readonly schemas?: readonly string[];
  readonly packages?: readonly string[];
  readonly aliases?: readonly string[];
  readonly paths?: readonly string[];
}

export interface ExactIdentifierScore {
  readonly value: number;
  readonly basis: string;
  readonly matchedTerms: readonly string[];
  readonly matchedIdentifiers: readonly string[];
}

const COMMON_TERMS = new Set([
  "app",
  "data",
  "file",
  "get",
  "index",
  "main",
  "set",
  "test",
  "type",
]);

export function normalizeIdentifierTokens(value: string): string[] {
  return value
    .normalize("NFKC")
    .replace(/([a-z\p{Ll}\d])([A-Z\p{Lu}])/gu, "$1 $2")
    .toLocaleLowerCase("en-US")
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
}

export function scoreExactIdentifiers(
  task: string,
  evidence: ExactIdentifierEvidence,
): ExactIdentifierScore {
  const taskTerms = [...new Set(normalizeIdentifierTokens(task))].filter(
    (term) => term.length > 1 && !COMMON_TERMS.has(term),
  );
  const entries = Object.entries(evidence)
    .flatMap(([source, values]) =>
      (values ?? []).map((value: string) => ({
        identifier: value.normalize("NFKC"),
        weight: source === "paths" ? 0.75 : 1,
      })),
    )
    .sort((a, b) => a.identifier.localeCompare(b.identifier));
  const identifiers = entries.map(({ identifier }) => identifier);
  const matchedIdentifiers = identifiers.filter((identifier) => {
    const tokens = new Set(normalizeIdentifierTokens(identifier));
    return taskTerms.some((term) => tokens.has(term));
  });
  const matchedTerms = taskTerms.filter((term) =>
    matchedIdentifiers.some((identifier) =>
      normalizeIdentifierTokens(identifier).includes(term),
    ),
  );
  const value =
    taskTerms.length === 0
      ? 0
      : taskTerms.reduce(
          (sum, term) =>
            sum +
            Math.max(
              0,
              ...entries
                .filter(({ identifier }) =>
                  normalizeIdentifierTokens(identifier).includes(term),
                )
                .map(({ weight }) => weight),
            ),
          0,
        ) / taskTerms.length;
  return {
    value,
    basis:
      matchedIdentifiers.length === 0
        ? "no exact normalized identifier match"
        : `exact normalized identifier match: ${matchedIdentifiers.join(", ")}`,
    matchedTerms,
    matchedIdentifiers,
  };
}

import type { GraphEdgeKind, GraphSnapshot } from "@fuzit/graph";

export interface GraphDistanceOptions {
  readonly requiredAnchorIds: readonly string[];
  readonly initialMatchIds?: readonly string[];
  readonly edgeWeights: Readonly<Partial<Record<GraphEdgeKind, number>>>;
  readonly maxDepth: number;
  readonly maxNodes: number;
  readonly maxEdges: number;
  readonly signal?: AbortSignal;
}

export interface GraphDistanceScore {
  readonly nodeId: string;
  readonly value: number;
  readonly basis: string;
  readonly distance: number;
  readonly graphPath: readonly string[];
  readonly edgeTypes: readonly GraphEdgeKind[];
}

interface PathState {
  readonly nodeId: string;
  readonly path: readonly string[];
  readonly edgeTypes: readonly GraphEdgeKind[];
  readonly weight: number;
}

const pathKey = (state: PathState) =>
  `${state.path.join("\0")}\0${state.edgeTypes.join("\0")}`;

export function scoreGraphDistance(
  graph: GraphSnapshot,
  options: GraphDistanceOptions,
): readonly GraphDistanceScore[] {
  if (
    !Number.isInteger(options.maxDepth) ||
    options.maxDepth < 0 ||
    options.maxDepth > 10
  ) {
    throw new Error("Graph distance depth must be between 0 and 10");
  }
  if (
    !Number.isInteger(options.maxNodes) ||
    options.maxNodes < 1 ||
    options.maxNodes > 1_000
  ) {
    throw new Error("Graph distance node limit must be between 1 and 1000");
  }
  if (
    !Number.isInteger(options.maxEdges) ||
    options.maxEdges < 1 ||
    options.maxEdges > 10_000
  ) {
    throw new Error("Graph distance edge limit must be between 1 and 10000");
  }
  const nodeIds = new Set(graph.nodes.map((node) => node.id));
  const anchors = [
    ...new Set([
      ...options.requiredAnchorIds,
      ...(options.initialMatchIds ?? []),
    ]),
  ]
    .filter((id) => nodeIds.has(id))
    .sort();
  const visited = new Map<string, PathState>();
  let frontier: PathState[] = anchors.map((nodeId) => ({
    nodeId,
    path: [nodeId],
    edgeTypes: [],
    weight: 1,
  }));
  let inspectedEdges = 0;
  for (
    let depth = 0;
    depth < options.maxDepth && frontier.length > 0;
    depth += 1
  ) {
    const next: PathState[] = [];
    for (const current of frontier.sort((a, b) =>
      pathKey(a).localeCompare(pathKey(b)),
    )) {
      if (options.signal?.aborted)
        throw new Error("Graph distance scoring cancelled");
      for (const edge of graph.edges) {
        if (edge.resolution !== "resolved") continue;
        const target =
          edge.sourceId === current.nodeId
            ? edge.targetId
            : edge.targetId === current.nodeId
              ? edge.sourceId
              : null;
        if (!target || current.path.includes(target)) continue;
        inspectedEdges += 1;
        if (inspectedEdges > options.maxEdges)
          return serializeScores(visited, graph.completeness, true);
        const edgeWeight = options.edgeWeights[edge.kind] ?? 0;
        if (edgeWeight <= 0) continue;
        const candidate: PathState = {
          nodeId: target,
          path: [...current.path, target],
          edgeTypes: [...current.edgeTypes, edge.kind],
          weight: current.weight * edgeWeight,
        };
        const previous = visited.get(target);
        if (
          !previous ||
          candidate.path.length < previous.path.length ||
          (candidate.path.length === previous.path.length &&
            pathKey(candidate).localeCompare(pathKey(previous)) < 0)
        ) {
          visited.set(target, candidate);
          next.push(candidate);
          if (visited.size >= options.maxNodes)
            return serializeScores(visited, graph.completeness, true);
        }
      }
    }
    frontier = next;
  }
  for (const anchor of anchors) visited.delete(anchor);
  return serializeScores(visited, graph.completeness, false);
}

function serializeScores(
  states: ReadonlyMap<string, PathState>,
  completeness: GraphSnapshot["completeness"],
  truncated: boolean,
): readonly GraphDistanceScore[] {
  return [...states.values()]
    .map((state) => ({
      nodeId: state.nodeId,
      value: state.weight / Math.max(1, state.path.length - 1),
      basis: `graph distance ${state.path.length - 1}; edges=${state.edgeTypes.join(",") || "none"}; graph=${completeness}${truncated ? "; bounded" : ""}`,
      distance: state.path.length - 1,
      graphPath: state.path,
      edgeTypes: state.edgeTypes,
    }))
    .sort(
      (a, b) =>
        b.value - a.value ||
        a.distance - b.distance ||
        a.nodeId.localeCompare(b.nodeId),
    );
}

export * from "./contract.js";
export * from "./exact.js";
export * from "./graph-distance.js";
export * from "./related-tests.js";
export * from "./metadata.js";

import type { GraphNode, GraphSnapshot } from "@fuzit/graph";

export interface MetadataRelevanceScore {
  readonly nodeId: string;
  readonly value: number;
  readonly basis: string;
}
const MANIFEST_PATTERN =
  /(^|\/)(package\.json|pnpm-workspace\.yaml|go\.mod|pyproject\.toml|pom\.xml|build\.gradle|cargo\.toml)$/iu;
const CONFIG_PATTERN =
  /(^|\/)(tsconfig(?:\.[^/]+)?\.json|[^/]+\.config\.[^/]+|\.fuzit\.ya?ml)$/iu;
const isMetadata = (node: GraphNode) =>
  node.kind === "configuration" ||
  (node.path !== null &&
    (MANIFEST_PATTERN.test(node.path) || CONFIG_PATTERN.test(node.path)));

export function scoreMetadataRelevance(
  graph: GraphSnapshot,
  targetIds: readonly string[],
  maxResults = 50,
): readonly MetadataRelevanceScore[] {
  if (!Number.isInteger(maxResults) || maxResults < 1 || maxResults > 200)
    throw new Error("Metadata result limit must be between 1 and 200");
  const targets = new Set(targetIds);
  const targetNodes = graph.nodes.filter((node) => targets.has(node.id));
  const scores = new Map<string, MetadataRelevanceScore>();
  const record = (node: GraphNode, value: number, basis: string) => {
    const previous = scores.get(node.id);
    if (!previous || value > previous.value)
      scores.set(node.id, { nodeId: node.id, value, basis });
  };
  for (const node of graph.nodes.filter(isMetadata)) {
    const configured = graph.edges.find(
      (edge) =>
        edge.kind === "configures" &&
        edge.sourceId === node.id &&
        edge.targetId !== null &&
        targets.has(edge.targetId),
    );
    if (configured) {
      record(
        node,
        1,
        `explicit configuration relation to ${configured.targetId}`,
      );
      continue;
    }
    const packageNode = graph.nodes.find(
      (candidate) =>
        candidate.kind === "package" &&
        (targetNodes.some((target) => target.parentId === candidate.id) ||
          targets.has(candidate.id)),
    );
    if (packageNode && node.path) {
      const packagePath = packageNode.path;
      const nested =
        packagePath === null ||
        node.path === packagePath ||
        node.path.startsWith(`${packagePath}/`);
      if (nested)
        record(
          node,
          MANIFEST_PATTERN.test(node.path) ? 0.8 : 0.6,
          `nearest package metadata for ${packageNode.id}`,
        );
    }
  }
  return [...scores.values()]
    .sort((a, b) => b.value - a.value || a.nodeId.localeCompare(b.nodeId))
    .slice(0, maxResults);
}

import type { GraphNode, GraphSnapshot } from "@fuzit/graph";

export interface RelatedTestScore {
  readonly nodeId: string;
  readonly value: number;
  readonly basis: string;
  readonly testKind: "unit" | "integration" | "e2e" | "unknown";
}

const classifyTestPath = (
  path: string | null,
): RelatedTestScore["testKind"] => {
  if (!path) return "unknown";
  const normalized = path.toLocaleLowerCase("en-US");
  if (/(^|\/)(e2e|end-to-end)(\/|$)|\.e2e\.[^.]+$/u.test(normalized))
    return "e2e";
  if (/(^|\/)(integration)(\/|$)|\.integration\.[^.]+$/u.test(normalized))
    return "integration";
  if (
    /(^|\/)(__tests__|tests?|spec)(\/|$)|\.(test|spec)\.[^.]+$/u.test(
      normalized,
    )
  )
    return "unit";
  return "unknown";
};

const testStem = (path: string) =>
  path
    .split("/")
    .at(-1)!
    .replace(/\.(test|spec|integration|e2e)?\.[^.]+$/u, "")
    .toLocaleLowerCase("en-US");

export function scoreRelatedTests(
  graph: GraphSnapshot,
  targetIds: readonly string[],
  maxResults = 50,
): readonly RelatedTestScore[] {
  if (!Number.isInteger(maxResults) || maxResults < 1 || maxResults > 200) {
    throw new Error("Related-test result limit must be between 1 and 200");
  }
  const targets = new Set(targetIds);
  const targetNodes = graph.nodes.filter((node) => targets.has(node.id));
  const candidates = graph.nodes.filter(
    (node) => node.kind === "test" || classifyTestPath(node.path) !== "unknown",
  );
  const scores = new Map<string, RelatedTestScore>();
  const record = (node: GraphNode, value: number, basis: string) => {
    const previous = scores.get(node.id);
    if (
      !previous ||
      value > previous.value ||
      (value === previous.value && basis.localeCompare(previous.basis) < 0)
    ) {
      scores.set(node.id, {
        nodeId: node.id,
        value,
        basis,
        testKind: classifyTestPath(node.path),
      });
    }
  };
  for (const candidate of candidates) {
    const explicit = graph.edges.find(
      (edge) =>
        edge.kind === "tests" &&
        edge.sourceId === candidate.id &&
        edge.targetId !== null &&
        targets.has(edge.targetId),
    );
    if (explicit) {
      record(candidate, 1, `explicit tests edge to ${explicit.targetId}`);
      continue;
    }
    const imported = graph.edges.find(
      (edge) =>
        edge.kind === "imports" &&
        edge.sourceId === candidate.id &&
        edge.targetId !== null &&
        targets.has(edge.targetId),
    );
    if (imported) {
      record(candidate, 0.8, `parsed test import to ${imported.targetId}`);
      continue;
    }
    if (candidate.path) {
      const stem = testStem(candidate.path);
      const target = targetNodes.find(
        (node) => node.path && stem === testStem(node.path),
      );
      if (target)
        record(candidate, 0.6, `exact test naming convention for ${target.id}`);
      else if (
        targetNodes.some(
          (node) =>
            node.parentId !== null && node.parentId === candidate.parentId,
        )
      )
        record(candidate, 0.25, "same package test convention");
    }
  }
  return [...scores.values()]
    .sort((a, b) => b.value - a.value || a.nodeId.localeCompare(b.nodeId))
    .slice(0, maxResults);
}

import type { Candidate, SelectionDecision } from "@fuzit/schemas";
export * from "./lexical/index.js";
export * from "./scorers/index.js";
export * from "./expansion/index.js";
export * from "./report/index.js";
export * from "./hybrid/index.js";
export * from "./provider-enrichment.js";
export function decideCandidates(
  candidates: readonly Candidate[],
): SelectionDecision[] {
  return [...candidates]
    .map((candidate) => {
      const score = candidate.contributions.reduce(
        (sum, contribution) => sum + contribution.value,
        0,
      );
      return {
        candidate,
        included: candidate.mandatory || score > 0,
        score,
        exclusionReason:
          candidate.mandatory || score > 0 ? null : "non-positive score",
      };
    })
    .sort(
      (a, b) =>
        b.score - a.score || a.candidate.path.localeCompare(b.candidate.path),
    );
}

export function normalizeTaskText(value: string): string[] {
  return value
    .normalize("NFKC")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[_/\\.-]+/g, " ")
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter(
      (token) =>
        token.length > 1 && !["the", "and", "for", "with"].includes(token),
    );
}
export function rankLexically(
  task: string,
  candidates: readonly { path: string; text: string }[],
) {
  const terms = normalizeTaskText(task);
  return candidates
    .map((candidate) => ({
      ...candidate,
      score: terms.reduce(
        (score, term) =>
          score +
          normalizeTaskText(`${candidate.path} ${candidate.text}`).filter(
            (token) => token === term,
          ).length,
        0,
      ),
    }))
    .sort((a, b) => b.score - a.score || a.path.localeCompare(b.path));
}

/**
 * Selection engine provider evidence merger.
 *
 * @module
 */

import type { NormalizedProviderRecord } from "@fuzit/schemas";

export interface ContextSelectionEnrichment {
  readonly providerRecords: readonly NormalizedProviderRecord[];
  readonly prioritizedPaths: readonly string[];
  readonly taskSeedText?: string;
}

export function mergeProviderEvidenceIntoSelection(
  records: readonly NormalizedProviderRecord[],
): ContextSelectionEnrichment {
  const paths = new Set<string>();
  let taskSeedText = "";

  for (const r of records) {
    if (r.kind === "pull-request-file") {
      paths.add(r.path);
    } else if (r.kind === "review-comment" || r.kind === "review-thread") {
      if (r.path) paths.add(r.path);
    } else if (r.kind === "issue") {
      taskSeedText += `${r.title}\n${r.body}\n`;
    }
  }

  const seed = taskSeedText.trim();
  return {
    providerRecords: records,
    prioritizedPaths: Array.from(paths),
    ...(seed ? { taskSeedText: seed } : {}),
  };
}

export type SelectionOutcome =
  | "included"
  | "excluded"
  | "redacted"
  | "truncated"
  | "dependency-expanded"
  | "failed-source";

export type ExplanationFormat = "json" | "markdown" | "text" | "xml" | "debug";

export const SELECTION_REPORT_SCHEMA_VERSION = 1 as const;

export interface SelectionEvidence {
  readonly path: string;
  readonly outcome: SelectionOutcome;
  readonly reason: string;
  readonly profile?: string;
  readonly contributions?: Readonly<Record<string, number>>;
  readonly profileWeights?: Readonly<Record<string, number>>;
  readonly aggregateScore?: number;
  readonly graphPath?: readonly string[];
  readonly lifecycle?: { readonly basis: string; readonly confidence: string };
  readonly expansionReason?: string;
  readonly budgetTokens?: number;
  readonly budgetDecision?: string;
  readonly indexState?: string;
  readonly securityDecision?: string;
  readonly omissionReason?: string;
  readonly tieBreak?: string;
}

export interface SelectionReport {
  readonly schemaVersion: 1;
  readonly entries: readonly SelectionEvidence[];
}

const sanitizeString = (value: string): string =>
  [
    ...value
      .replace(
        /\b(?:token|password|secret|api[_-]?key)\s*[:=]\s*[^\s,;]+/giu,
        "[REDACTED]",
      )
      .replace(/\b[A-Za-z]:[\\/][^\s"'<>]+/gu, "[unsafe-path]")
      .replace(
        /(^|\s)\/(?:Users|home|tmp|var|private|etc)\/[^\s"'<>]+/gu,
        "$1[unsafe-path]",
      ),
  ]
    .filter((character) => {
      const code = character.codePointAt(0) ?? 0;
      return (
        code === 9 || code === 10 || code === 13 || (code >= 32 && code !== 127)
      );
    })
    .join("");

const sanitizeValue = (value: unknown): unknown => {
  if (typeof value === "string") return sanitizeString(value);
  if (Array.isArray(value)) return value.map(sanitizeValue);
  if (value !== null && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, sanitizeValue(item)]),
    );
  return value;
};

export function createSelectionReport(
  entries: readonly SelectionEvidence[],
): SelectionReport {
  return {
    schemaVersion: SELECTION_REPORT_SCHEMA_VERSION,
    entries: [...entries].sort((left, right) =>
      left.path.localeCompare(right.path),
    ),
  };
}

export function explainPath(
  report: SelectionReport,
  path: string,
): SelectionEvidence {
  const evidence = report.entries.find((entry) => entry.path === path);
  if (evidence === undefined)
    throw new Error(`No selection evidence for ${sanitizeString(path)}.`);
  return evidence;
}

const linesFor = (unsafeEvidence: SelectionEvidence): string[] => {
  const evidence = sanitizeValue(unsafeEvidence) as SelectionEvidence;
  const record = (label: string, value: unknown) =>
    value === undefined
      ? ""
      : `${label}: ${typeof value === "string" ? value : JSON.stringify(value)}`;
  return [
    `${evidence.path}: ${evidence.outcome}`,
    record("reason", evidence.reason),
    record("profile", evidence.profile),
    record("score components", evidence.contributions),
    record("profile weights", evidence.profileWeights),
    record("aggregate score", evidence.aggregateScore),
    record("graph path", evidence.graphPath),
    record("lifecycle", evidence.lifecycle),
    record("expansion reason", evidence.expansionReason),
    evidence.budgetTokens === undefined
      ? ""
      : `budget removed: ${evidence.budgetTokens} tokens`,
    record("budget decision", evidence.budgetDecision),
    record("index state", evidence.indexState),
    record("security decision", evidence.securityDecision),
    record("omission reason", evidence.omissionReason),
    record("tie-break", evidence.tieBreak),
  ].filter(Boolean);
};

export function formatSelectionExplanation(
  evidence: SelectionEvidence,
): string {
  return linesFor(evidence).join("\n");
}

const xmlEscape = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");

export function renderSelectionExplanation(
  evidence: SelectionEvidence,
  format: ExplanationFormat,
): string {
  const safe = sanitizeValue(evidence) as SelectionEvidence;
  if (format === "json") return `${JSON.stringify(safe)}\n`;
  if (format === "text") return `${linesFor(safe).join("\n")}\n`;
  if (format === "markdown")
    return `### ${safe.path}\n\n${linesFor(safe)
      .slice(1)
      .map((line) => `- ${line}`)
      .join("\n")}\n`;
  if (format === "xml")
    return `<selection schema-version="1"><path>${xmlEscape(safe.path)}</path><outcome>${safe.outcome}</outcome><evidence>${xmlEscape(linesFor(safe).slice(1).join("\n"))}</evidence></selection>\n`;
  return `DEBUG selection-schema=${SELECTION_REPORT_SCHEMA_VERSION}\n${linesFor(safe).join("\n")}\n`;
}

export function renderSelectionFailure(
  error: unknown,
  format: ExplanationFormat,
): string {
  const message = sanitizeString(
    error instanceof Error ? error.message : String(error),
  );
  const evidence: SelectionEvidence = {
    path: "[unavailable]",
    outcome: "failed-source",
    reason: message,
    omissionReason: "selection evidence unavailable",
  };
  return renderSelectionExplanation(evidence, format);
}

export interface GitChangeEvidence {
  readonly revision: string;
  readonly paths: readonly string[];
  readonly previousPaths?: Readonly<Record<string, string>>;
}

export interface GitScoreInput {
  readonly path: string;
  readonly dirtyPaths: readonly string[];
  readonly recentPaths?: readonly string[];
  readonly historyAvailable: boolean;
  readonly history?: readonly GitChangeEvidence[];
  readonly taskPaths?: readonly string[];
  readonly maximumCommits?: number;
}

export interface GitScoreContribution {
  readonly source:
    | "git-dirty"
    | "git-recency"
    | "git-frequency"
    | "git-co-change"
    | "git-task-diff";
  readonly value: number;
  readonly reason: string;
  readonly evidence: readonly string[];
}

const canonical = (path: string) => path.replaceAll("\\", "/");
const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

/** Scores bounded Git evidence without wall-clock input or repository execution. */
export function scoreGitEvidence(input: GitScoreInput): GitScoreContribution[] {
  const path = canonical(input.path);
  const maximumCommits = Math.max(1, Math.min(input.maximumCommits ?? 50, 100));
  const history = (input.history ?? []).slice(0, maximumCommits);
  const aliases = new Set([path]);
  for (const commit of history) {
    const previous = commit.previousPaths?.[path];
    if (previous) aliases.add(canonical(previous));
  }
  const matching = history
    .map((commit, ordinal) => ({ commit, ordinal }))
    .filter(({ commit }) =>
      commit.paths.some((item) => aliases.has(canonical(item))),
    );
  const frequency = history.length === 0 ? 0 : matching.length / history.length;
  const recency =
    matching.length === 0 ? 0 : 1 - matching[0]!.ordinal / history.length;
  const taskPaths = new Set((input.taskPaths ?? []).map(canonical));
  const coChanges = matching.filter(({ commit }) =>
    commit.paths.some((item) => taskPaths.has(canonical(item))),
  );
  const legacyRecent = new Set((input.recentPaths ?? []).map(canonical));
  const dirty = new Set(input.dirtyPaths.map(canonical));
  const revisions = matching.map(({ commit }) => commit.revision);
  const unavailable = !input.historyAvailable
    ? "Git history unavailable"
    : "no matching history";
  return [
    {
      source: "git-dirty",
      value: dirty.has(path) ? 1 : 0,
      reason: dirty.has(path)
        ? "local working change"
        : "no local working change",
      evidence: [],
    },
    {
      source: "git-recency",
      value: clamp01(Math.max(recency, legacyRecent.has(path) ? 1 : 0)),
      reason:
        matching.length || legacyRecent.has(path)
          ? "bounded ordinal commit recency"
          : unavailable,
      evidence: revisions.slice(0, 1),
    },
    {
      source: "git-frequency",
      value: clamp01(frequency),
      reason: matching.length
        ? `${matching.length} of ${history.length} bounded commits`
        : unavailable,
      evidence: revisions,
    },
    {
      source: "git-co-change",
      value: matching.length ? clamp01(coChanges.length / matching.length) : 0,
      reason: coChanges.length
        ? "changed with task-relevant paths"
        : unavailable,
      evidence: coChanges.map(({ commit }) => commit.revision),
    },
    {
      source: "git-task-diff",
      value: dirty.has(path) && taskPaths.has(path) ? 1 : 0,
      reason:
        dirty.has(path) && taskPaths.has(path)
          ? "task path has a working change"
          : "no task-relevant working change",
      evidence: [],
    },
  ];
}

export {
  classifyLifecycle,
  scorePathLifecycle,
  type LifecycleClass,
  type LifecycleClassification,
  type ScoringInput,
} from "./path-lifecycle.js";
export { scoreGitEvidence } from "./git.js";

export interface ScoringInput {
  readonly path: string;
  readonly explicitPaths: readonly string[];
  readonly generated: boolean;
  readonly category: "source" | "test" | "doc";
  readonly lifecycle: "active" | "deprecated" | "unknown";
  readonly trust: number;
}

export type LifecycleClass =
  | "active"
  | "generated"
  | "deprecated"
  | "legacy"
  | "experimental"
  | "vendored"
  | "test"
  | "configuration"
  | "documentation"
  | "unknown";

export interface LifecycleClassification {
  readonly lifecycle: LifecycleClass;
  readonly confidence: "high" | "medium" | "low";
  readonly evidence: readonly string[];
}

const matchesSegment = (path: string, segments: readonly string[]) =>
  path
    .replaceAll("\\", "/")
    .toLowerCase()
    .split("/")
    .some((segment) => segments.includes(segment));

/** Classifies only controlled path, annotation, and observed-activity evidence. */
export function classifyLifecycle(input: {
  readonly path: string;
  readonly generatedMarker?: boolean;
  readonly annotations?: readonly ("deprecated" | "legacy" | "experimental")[];
  readonly activityEvidence?: readonly string[];
}): LifecycleClassification {
  const path = input.path.replaceAll("\\", "/");
  const annotations = new Set(input.annotations ?? []);
  const result = (
    lifecycle: LifecycleClass,
    confidence: LifecycleClassification["confidence"],
    evidence: readonly string[],
  ): LifecycleClassification => ({ lifecycle, confidence, evidence });
  if (
    input.generatedMarker ||
    matchesSegment(path, ["generated", "dist", "build"])
  )
    return result("generated", "high", [
      input.generatedMarker ? "generated marker" : "generated path segment",
    ]);
  if (
    matchesSegment(path, ["vendor", "vendored", "third_party", "node_modules"])
  )
    return result("vendored", "high", ["vendored path segment"]);
  for (const lifecycle of ["deprecated", "legacy", "experimental"] as const)
    if (annotations.has(lifecycle))
      return result(lifecycle, "high", [`${lifecycle} annotation`]);
  if (/(^|\/)(test|tests|__tests__)(\/|$)|\.(test|spec)\.[^/]+$/i.test(path))
    return result("test", "high", ["test path convention"]);
  if (/(^|\/)(docs?|documentation)(\/|$)|\.(md|mdx|rst)$/i.test(path))
    return result("documentation", "high", ["documentation path convention"]);
  if (
    /(^|\/)(config|configuration)(\/|$)|(^|\/)[^./]+\.config\.[^/]+$/i.test(
      path,
    )
  )
    return result("configuration", "high", ["configuration path convention"]);
  if ((input.activityEvidence?.length ?? 0) > 0)
    return result("active", "medium", [...input.activityEvidence!].sort());
  return result("unknown", "low", ["no controlled lifecycle evidence"]);
}
export function scorePathLifecycle(input: ScoringInput) {
  const contributions = [
    {
      source: "explicit-path",
      value: input.explicitPaths.includes(input.path) ? 10 : 0,
      reason: "explicit task path",
    },
    {
      source: "generated",
      value: input.generated ? -4 : 0,
      reason: "generated content penalty",
    },
    {
      source: "test",
      value: input.category === "test" ? 2 : 0,
      reason: "test relevance",
    },
    {
      source: "lifecycle",
      value: input.lifecycle === "deprecated" ? -2 : 0,
      reason: `${input.lifecycle} lifecycle`,
    },
    { source: "trust", value: input.trust, reason: "source provenance trust" },
  ];
  return contributions;
}

import { describe, expect, it } from "vitest";
import { decideCandidates } from "../src/index.js";
const candidate = (path: string, value: number, mandatory = false) => ({
  id: path,
  path,
  mandatory,
  uncertainty: 0.2,
  contributions: [{ source: "test", value, reason: "evidence" }],
});
describe("selection contracts", () => {
  it("has deterministic score vectors", () =>
    expect(decideCandidates([candidate("a", 1)])).toEqual(
      decideCandidates([candidate("a", 1)]),
    ));
  it("breaks ties by path", () =>
    expect(
      decideCandidates([candidate("b", 1), candidate("a", 1)])[0]?.candidate
        .path,
    ).toBe("a"));
  it("reports excluded items", () =>
    expect(decideCandidates([candidate("a", 0)])[0]?.included).toBe(false));
  it("includes mandatory items", () =>
    expect(decideCandidates([candidate("a", -1, true)])[0]?.included).toBe(
      true,
    ));
  it("preserves uncertainty", () =>
    expect(
      decideCandidates([candidate("a", 1)])[0]?.candidate.uncertainty,
    ).toBe(0.2));
  it("supports versioned profiles", () =>
    expect({ id: "bug-fix", version: 1, weights: {} }).toMatchObject({
      version: 1,
    }));
});

import { describe, expect, it } from "vitest";
import { expandDependencies, type ExpansionEdge } from "../src/index.js";
const edge = (
  from: string,
  to: string,
  resolved = true,
  relationship: "dependency" | "reverse-dependency" | "test" = "dependency",
): ExpansionEdge => ({ from, to, resolved, relationship });
describe("dependency expansion", () => {
  it("handles cycles", () =>
    expect(
      expandDependencies(["a"], [edge("a", "b"), edge("b", "a")], {
        depth: 3,
        decay: 0.5,
        cap: 10,
      }).map((x) => x.path),
    ).toEqual(["a", "b"]));
  it("caps high-degree nodes", () =>
    expect(
      expandDependencies(["a"], [edge("a", "b"), edge("a", "c")], {
        depth: 1,
        decay: 0.5,
        cap: 2,
      }),
    ).toHaveLength(2));
  it("skips unresolved edges", () =>
    expect(
      expandDependencies(["a"], [edge("a", "b", false)], {
        depth: 1,
        decay: 0.5,
        cap: 10,
      }),
    ).toHaveLength(1));
  it("honors depth zero", () =>
    expect(
      expandDependencies(["a"], [edge("a", "b")], {
        depth: 0,
        decay: 0.5,
        cap: 10,
      }),
    ).toHaveLength(1));
  it("deduplicates paths", () =>
    expect(
      expandDependencies(["a", "a"], [], { depth: 1, decay: 0.5, cap: 10 }),
    ).toHaveLength(1));
  it("preserves test relationships", () =>
    expect(
      expandDependencies(["a"], [edge("a", "a.test", true, "test")], {
        depth: 1,
        decay: 0.5,
        cap: 10,
      })[1]?.relationshipPath[1],
    ).toBe("test:a.test"));
  it("bounds expansion storms by edges and items", () => {
    const result = expandDependencies(
      ["a"],
      Array.from({ length: 100 }, (_, index) => edge("a", `node-${index}`)),
      { depth: 2, decay: 0.5, cap: 4, maximumEdges: 3 },
    );
    expect(result).toHaveLength(4);
    expect(result.every((item) => item.bounds.maximumEdges === 3)).toBe(true);
  });
  it("preserves required anchors even when the item cap is smaller", () => {
    const result = expandDependencies([], [], {
      depth: 0,
      decay: 0.5,
      cap: 1,
      requiredAnchors: ["b", "a"],
      tokenBudget: 0,
    });
    expect(result.map(({ path, reason }) => [path, reason])).toEqual([
      ["a", "required-anchor"],
      ["b", "required-anchor"],
    ]);
  });
  it("enforces confidence, relationship, security, budget, and cancellation bounds", () => {
    const controller = new AbortController();
    expect(
      expandDependencies(["a"], [edge("a", "b")], {
        depth: 1,
        decay: 0.5,
        cap: 10,
        signal: AbortSignal.abort(),
      }),
    ).toEqual([]);
    const result = expandDependencies(
      ["a"],
      [
        { ...edge("a", "low"), confidence: 0.1 },
        edge("a", "test", true, "test"),
        edge("a", "safe"),
      ],
      {
        depth: 1,
        decay: 0.5,
        cap: 10,
        minimumConfidence: 0.5,
        allowedRelationships: ["dependency"],
        securityAllowedPaths: ["a", "safe"],
        tokenBudget: 2,
        signal: controller.signal,
      },
    );
    expect(result.map(({ path }) => path)).toEqual(["a", "safe"]);
  });
});

import { describe, expect, it } from "vitest";
import { scoreGitEvidence } from "../src/index.js";
const score = (overrides = {}) =>
  scoreGitEvidence({
    path: "a",
    dirtyPaths: [],
    recentPaths: [],
    historyAvailable: true,
    ...overrides,
  });
describe("Git scoring", () => {
  it("handles no Git", () =>
    expect(score({ historyAvailable: false })[1]?.reason).toBe(
      "Git history unavailable",
    ));
  it("scores dirty files", () =>
    expect(score({ dirtyPaths: ["a"] })[0]?.value).toBe(1));
  it("does not score recent unrelated changes", () =>
    expect(score({ recentPaths: ["b"] })[1]?.value).toBe(0));
  it("keeps old relevant files neutral", () =>
    expect(score()[1]?.value).toBe(0));
  it("handles shallow history", () =>
    expect(score({ historyAvailable: false })).toHaveLength(5));
  it("uses ordinal recency and bounded frequency without a clock", () => {
    const result = score({
      history: [
        { revision: "new", paths: ["b"] },
        { revision: "middle", paths: ["a", "task"] },
        { revision: "old", paths: ["a"] },
      ],
      taskPaths: ["task"],
    });
    expect(result.map(({ source }) => source)).toEqual([
      "git-dirty",
      "git-recency",
      "git-frequency",
      "git-co-change",
      "git-task-diff",
    ]);
    expect(result[1]?.value).toBeCloseTo(2 / 3);
    expect(result[2]?.value).toBeCloseTo(2 / 3);
    expect(result[3]?.value).toBe(1 / 2);
  });
  it("follows bounded rename evidence", () => {
    const result = score({
      path: "new.ts",
      history: [
        {
          revision: "rename",
          paths: ["old.ts"],
          previousPaths: { "new.ts": "old.ts" },
        },
      ],
    });
    expect(result[2]).toMatchObject({ value: 1, evidence: ["rename"] });
  });
});

import { describe, expect, it } from "vitest";
import { normalizeTaskText, rankLexically } from "../src/index.js";
describe("lexical retrieval", () => {
  it("splits CamelCase", () =>
    expect(normalizeTaskText("AuthFailure")).toEqual(["auth", "failure"]));
  it("splits snake_case", () =>
    expect(normalizeTaskText("auth_failure")).toEqual(["auth", "failure"]));
  it("ranks path mentions", () =>
    expect(
      rankLexically("src/auth", [
        { path: "src/auth.ts", text: "" },
        { path: "x", text: "" },
      ])[0]?.path,
    ).toBe("src/auth.ts"));
  it("removes stop words", () =>
    expect(normalizeTaskText("the auth and code")).toEqual(["auth", "code"]));
  it("normalizes Unicode", () =>
    expect(normalizeTaskText("Ａuth")).toEqual(["auth"]));
  it("handles empty tasks", () =>
    expect(
      rankLexically("", [
        { path: "b", text: "" },
        { path: "a", text: "" },
      ]).map((x) => x.path),
    ).toEqual(["a", "b"]));
  it("breaks ties by path", () =>
    expect(
      rankLexically("none", [
        { path: "b", text: "" },
        { path: "a", text: "" },
      ])[0]?.path,
    ).toBe("a"));
});

import { describe, expect, it } from "vitest";
import {
  createSelectionReport,
  explainPath,
  formatSelectionExplanation,
  renderSelectionExplanation,
  renderSelectionFailure,
  type SelectionOutcome,
} from "../src/index.js";

describe("selection explanations", () => {
  it.each([
    "included",
    "excluded",
    "redacted",
    "truncated",
    "dependency-expanded",
    "failed-source",
  ] satisfies SelectionOutcome[])("preserves %s evidence", (outcome) => {
    const evidence = {
      path: `${outcome}.ts`,
      outcome,
      reason: `algorithm marked ${outcome}`,
      profile: "bug-fix",
      contributions: { lexical: 2, git: 1 },
      budgetTokens: outcome === "excluded" ? 40 : undefined,
    };
    const report = createSelectionReport([evidence]);
    expect(explainPath(report, evidence.path)).toEqual(evidence);
    expect(formatSelectionExplanation(evidence)).toContain(evidence.reason);
  });

  it("preserves deterministic tie-break evidence", () => {
    const evidence = {
      path: "a.ts",
      outcome: "included" as const,
      reason: "equal score",
      tieBreak: "canonical path ascending",
    };
    expect(formatSelectionExplanation(evidence)).toContain(
      "canonical path ascending",
    );
  });

  const completeEvidence = {
    path: "src/a.ts",
    outcome: "dependency-expanded" as const,
    reason: "resolved dependency",
    profile: "architecture-review",
    contributions: { dependency: 0.8 },
    profileWeights: { dependency: 4 },
    aggregateScore: 3.2,
    graphPath: ["src/root.ts", "dependency:src/a.ts"],
    lifecycle: { basis: "imported by src/root.ts", confidence: "medium" },
    expansionReason: "approved dependency edge",
    budgetDecision: "included within 400 tokens",
    indexState: "ready schema 1",
    securityDecision: "allowed after policy filter",
  };

  it.each(["json", "markdown", "text", "xml", "debug"] as const)(
    "renders complete safe %s evidence deterministically",
    (format) => {
      const output = renderSelectionExplanation(completeEvidence, format);
      expect(output).toBe(renderSelectionExplanation(completeEvidence, format));
      expect(output).toContain("dependency");
      expect(output).toContain("architecture-review");
      expect(output).toContain("ready schema 1");
    },
  );

  it("redacts secrets and unsafe absolute paths in every mode and failures", () => {
    const unsafe = {
      ...completeEvidence,
      path: "C:\\Users\\owner\\secret.ts",
      reason: "[REDACTED:api-key] from /home/owner/private.ts",
    };
    for (const format of [
      "json",
      "markdown",
      "text",
      "xml",
      "debug",
    ] as const) {
      const output = renderSelectionExplanation(unsafe, format);
      expect(output).not.toContain("super-secret");
      expect(output).not.toContain("owner");
    }
    const failure = renderSelectionFailure(
      new Error("password=hunter2 at /tmp/private.txt"),
      "debug",
    );
    expect(failure).not.toContain("hunter2");
    expect(failure).not.toContain("/tmp/private.txt");
  });
});

import { describe, expect, it } from "vitest";
import { classifyLifecycle, scorePathLifecycle } from "../src/index.js";
const score = (overrides = {}) =>
  scorePathLifecycle({
    path: "a",
    explicitPaths: [],
    generated: false,
    category: "source",
    lifecycle: "unknown",
    trust: 1,
    ...overrides,
  });
describe("path lifecycle scoring", () => {
  it("penalizes generated", () =>
    expect(
      score({ generated: true }).find((x) => x.source === "generated")?.value,
    ).toBe(-4));
  it("rewards relevant tests", () =>
    expect(
      score({ category: "test" }).find((x) => x.source === "test")?.value,
    ).toBe(2));
  it("lets explicit paths override", () =>
    expect(score({ explicitPaths: ["a"] })[0]?.value).toBe(10));
  it("keeps unknown lifecycle neutral", () =>
    expect(score().find((x) => x.source === "lifecycle")?.value).toBe(0));
  it("preserves deterministic ties", () => expect(score()).toEqual(score()));
});

describe("lifecycle classification", () => {
  it.each([
    ["src/generated/client.ts", "generated"],
    ["vendor/library.ts", "vendored"],
    ["tests/unit.test.ts", "test"],
    ["docs/guide.md", "documentation"],
    ["tool.config.ts", "configuration"],
  ])("classifies %s as %s from controlled paths", (path, lifecycle) => {
    expect(classifyLifecycle({ path })).toMatchObject({
      lifecycle,
      confidence: "high",
    });
  });
  it.each(["deprecated", "legacy", "experimental"] as const)(
    "honors the %s annotation",
    (annotation) =>
      expect(
        classifyLifecycle({ path: "src/a.ts", annotations: [annotation] }),
      ).toMatchObject({
        lifecycle: annotation,
        evidence: [`${annotation} annotation`],
      }),
  );
  it("keeps an old but observed file active without using age", () => {
    expect(
      classifyLifecycle({
        path: "src/old.ts",
        activityEvidence: ["imported by src/main.ts"],
      }),
    ).toEqual({
      lifecycle: "active",
      confidence: "medium",
      evidence: ["imported by src/main.ts"],
    });
  });
  it("returns explainable unknown evidence", () => {
    expect(classifyLifecycle({ path: "src/a.ts" })).toEqual({
      lifecycle: "unknown",
      confidence: "low",
      evidence: ["no controlled lifecycle evidence"],
    });
  });
});

