export interface FileDelta {
  readonly path: string;
  readonly previousPath: string | null;
  readonly kind: "added" | "modified" | "deleted" | "unchanged" | "renamed";
  readonly confidence: number;
  readonly evidence: readonly string[];
}

export interface SnapshotDelta {
  readonly from: string;
  readonly to: string;
  readonly complete: boolean;
  readonly configChanged: boolean;
  readonly files: readonly FileDelta[];
}

export function computeSnapshotDelta(
  before: SnapshotManifest,
  after: SnapshotManifest,
): SnapshotDelta {
  const oldFiles = new Map(
    before.fileFingerprints.map((file) => [file.path, file]),
  );
  const newFiles = new Map(
    after.fileFingerprints.map((file) => [file.path, file]),
  );
  const deleted = [...oldFiles.values()].filter(
    (file) => !newFiles.has(file.path),
  );
  const added = [...newFiles.values()].filter(
    (file) => !oldFiles.has(file.path),
  );
  const addedByHash = new Map<string, typeof added>();
  for (const file of added) {
    addedByHash.set(file.sha256, [
      ...(addedByHash.get(file.sha256) ?? []),
      file,
    ]);
  }
  const renamedTargets = new Set<string>();
  const files: FileDelta[] = [];

  for (const file of deleted) {
    const candidates = addedByHash.get(file.sha256) ?? [];
    if (candidates.length === 1) {
      const target = candidates[0]!;
      renamedTargets.add(target.path);
      files.push({
        path: target.path,
        previousPath: file.path,
        kind: "renamed",
        confidence: 1,
        evidence: ["identical content hash"],
      });
    } else {
      files.push({
        path: file.path,
        previousPath: file.path,
        kind: "deleted",
        confidence: 1,
        evidence:
          candidates.length > 1
            ? ["rename ambiguous: duplicate content hashes"]
            : ["path absent from target snapshot"],
      });
    }
  }

  for (const file of added) {
    if (!renamedTargets.has(file.path)) {
      files.push({
        path: file.path,
        previousPath: null,
        kind: "added",
        confidence: 1,
        evidence: ["path absent from baseline snapshot"],
      });
    }
  }

  for (const [path, oldFile] of oldFiles) {
    const newFile = newFiles.get(path);
    if (!newFile) continue;
    const unchanged = oldFile.sha256 === newFile.sha256;
    files.push({
      path,
      previousPath: path,
      kind: unchanged ? "unchanged" : "modified",
      confidence: 1,
      evidence: [unchanged ? "identical content hash" : "content hash changed"],
    });
  }

  return {
    from: before.id,
    to: after.id,
    complete: before.complete && after.complete,
    configChanged: before.configHash !== after.configHash,
    files: files.sort((left, right) => left.path.localeCompare(right.path)),
  };
}

export {
  computeSnapshotDelta,
  type FileDelta,
  type SnapshotDelta,
} from "./compute-delta.js";

import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";

import {
  SNAPSHOT_SCHEMA_VERSION,
  snapshotManifestSchema,
  type SnapshotManifest,
} from "@fuzit/schemas";

export * from "./delta/index.js";

export type SnapshotInput = Omit<
  SnapshotManifest,
  "schemaVersion" | "id" | "createdAt"
>;

export function createSnapshot(
  input: SnapshotInput,
  createdAt = new Date().toISOString(),
): SnapshotManifest {
  const identity = JSON.stringify({
    repositoryRevision: input.repositoryRevision,
    dirty: input.dirty,
    configHash: input.configHash,
    fileFingerprints: [...input.fileFingerprints].sort((a, b) =>
      a.path.localeCompare(b.path),
    ),
    bundleIdentityInputs: input.bundleIdentityInputs,
    complete: input.complete,
    diagnostics: input.diagnostics,
  });
  return snapshotManifestSchema.parse({
    ...input,
    schemaVersion: SNAPSHOT_SCHEMA_VERSION,
    id: `snapshot:${createHash("sha256").update(identity).digest("hex")}`,
    createdAt,
  });
}

export async function saveSnapshot(
  directory: string,
  snapshot: SnapshotManifest,
): Promise<void> {
  await mkdir(directory, { recursive: true, mode: 0o700 });
  const name = `${snapshot.id.slice("snapshot:".length)}.json`;
  const temporary = join(directory, `${name}.tmp`);
  await writeFile(temporary, `${JSON.stringify(snapshot)}\n`, { mode: 0o600 });
  await rename(temporary, join(directory, name));
}

export async function listSnapshots(directory: string): Promise<string[]> {
  try {
    return (await readdir(directory))
      .filter((name) => /^[a-f0-9]{64}\.json$/.test(name))
      .map((name) => `snapshot:${name.slice(0, -5)}`)
      .sort();
  } catch {
    return [];
  }
}

export async function readSnapshot(
  directory: string,
  id: string,
): Promise<SnapshotManifest> {
  return snapshotManifestSchema.parse(
    JSON.parse(
      (
        await readFile(
          join(directory, `${id.slice("snapshot:".length)}.json`),
          "utf8",
        )
      ).replace(/^\uFEFF/, ""),
    ),
  );
}

import { describe, expect, it } from "vitest";

import { computeSnapshotDelta, createSnapshot } from "../src/index.js";

const snapshot = (
  files: readonly { path: string; sha256: string }[],
  options: { complete?: boolean; configHash?: string } = {},
) =>
  createSnapshot({
    repositoryRevision: "head",
    dirty: false,
    configHash: options.configHash ?? "config",
    fileFingerprints: [...files],
    bundleIdentityInputs: [],
    complete: options.complete ?? true,
    diagnostics: [],
  });

describe("snapshot delta", () => {
  it("infers a rename from an identical hash", () => {
    const delta = computeSnapshotDelta(
      snapshot([{ path: "old", sha256: "a" }]),
      snapshot([{ path: "new", sha256: "a" }]),
    );
    expect(delta.files).toContainEqual(
      expect.objectContaining({
        kind: "renamed",
        path: "new",
        previousPath: "old",
        confidence: 1,
      }),
    );
  });

  it("does not infer a modify plus rename", () => {
    const delta = computeSnapshotDelta(
      snapshot([{ path: "old", sha256: "a" }]),
      snapshot([{ path: "new", sha256: "b" }]),
    );
    expect(delta.files.map((file) => file.kind).sort()).toEqual([
      "added",
      "deleted",
    ]);
  });

  it("does not invent a rename for duplicate hashes", () => {
    const delta = computeSnapshotDelta(
      snapshot([{ path: "old", sha256: "a" }]),
      snapshot([
        { path: "new-a", sha256: "a" },
        { path: "new-b", sha256: "a" },
      ]),
    );
    expect(delta.files.some((file) => file.kind === "renamed")).toBe(false);
  });

  it("marks a delta incomplete when either snapshot is partial", () => {
    expect(
      computeSnapshotDelta(snapshot([]), snapshot([], { complete: false }))
        .complete,
    ).toBe(false);
  });

  it("reports config-only changes", () => {
    const delta = computeSnapshotDelta(
      snapshot([], { configHash: "a" }),
      snapshot([], { configHash: "b" }),
    );
    expect(delta).toMatchObject({ configChanged: true, files: [] });
  });
});

import { describe, expect, it } from "vitest";

import { createSnapshot } from "../src/index.js";

const base = {
  repositoryRevision: "abc",
  dirty: false,
  configHash: "config",
  fileFingerprints: [{ path: "a.ts", sha256: "hash" }],
  bundleIdentityInputs: ["v1"],
  complete: true,
  diagnostics: [],
};

describe("immutable snapshots", () => {
  it("represents dirty repositories", () => {
    expect(createSnapshot({ ...base, dirty: true }).dirty).toBe(true);
  });
  it("represents non-Git directories", () => {
    expect(
      createSnapshot({ ...base, repositoryRevision: null }).repositoryRevision,
    ).toBeNull();
  });
  it("represents partial scans", () => {
    expect(createSnapshot({ ...base, complete: false }).complete).toBe(false);
  });
  it("gives the same meaningful state the same identity", () => {
    expect(createSnapshot(base).id).toBe(createSnapshot(base).id);
  });
  it("excludes volatile timestamps from identity", () => {
    expect(createSnapshot(base, "2020-01-01").id).toBe(
      createSnapshot(base, "2030-01-01").id,
    );
  });
});

