export {
  normalizeGoldenFields,
  type GoldenNormalizationOptions,
} from "./normalize-golden.js";

import { describe, expect, it } from "vitest";

import { normalizeGoldenFields } from "./normalize-golden.js";

describe("normalizeGoldenFields", () => {
  it("preserves meaningful collection ordering", () => {
    const normalized = normalizeGoldenFields(
      {
        generated: "first\r\nsecond\r\n",
        items: ["second", "first"],
      },
      { volatileFields: ["generated"] },
    );

    expect(normalized.generated).toBe("first\nsecond\n");
    expect(normalized.items).toEqual(["second", "first"]);
  });

  it("normalizes Windows separators only in a declared volatile field", () => {
    const normalized = normalizeGoldenFields(
      {
        sourcePath: "C:\\work\\fuzit\\src\\index.ts",
        renderedPath: "C:\\work\\fuzit\\src\\index.ts\r\n",
      },
      {
        volatileFields: ["renderedPath"],
        rootPath: "C:\\work\\fuzit",
      },
    );

    expect(normalized.sourcePath).toBe("C:\\work\\fuzit\\src\\index.ts");
    expect(normalized.renderedPath).toBe("<ROOT>/src/index.ts\n");
  });
});

export interface GoldenNormalizationOptions<
  RecordType extends Record<string, unknown>,
> {
  readonly volatileFields: readonly (keyof RecordType)[];
  readonly rootPath?: string;
}

function replaceAll(
  value: string,
  search: string,
  replacement: string,
): string {
  return value.split(search).join(replacement);
}

function normalizeVolatileString(value: string, rootPath?: string): string {
  let normalized = value.replace(/\r\n?/g, "\n");

  if (rootPath) {
    const slashPath = rootPath.replaceAll("\\", "/");
    const backslashPath = rootPath.replaceAll("/", "\\");

    normalized = replaceAll(normalized, rootPath, "<ROOT>");
    normalized = replaceAll(normalized, slashPath, "<ROOT>");
    normalized = replaceAll(normalized, backslashPath, "<ROOT>");
    normalized = normalized.replaceAll("\\", "/");
  }

  return normalized;
}

export function normalizeGoldenFields<
  RecordType extends Record<string, unknown>,
>(
  record: RecordType,
  options: GoldenNormalizationOptions<RecordType>,
): RecordType {
  const normalized = { ...record };

  for (const field of options.volatileFields) {
    const value = normalized[field];

    if (typeof value === "string") {
      normalized[field] = normalizeVolatileString(
        value,
        options.rootPath,
      ) as RecordType[typeof field];
    }
  }

  return normalized;
}

