  "exclude": ["src/**/*.test.ts"]
}

{
  "name": "@fuzit/watcher",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc --project tsconfig.json",
    "typecheck": "tsc --project tsconfig.json --noEmit"
  },
  "dependencies": {
    "@fuzit/index": "workspace:*",
    "@fuzit/schemas": "workspace:*"
  },
  "devDependencies": {
    "typescript": "6.0.3"
  }
}

import { isAbsolute, normalize, relative } from "node:path";
import {
  validateWatcherEvent,
  WATCHER_CONTRACT_VERSION,
  type WatcherEvent,
} from "@fuzit/schemas";

export interface FilesystemAdapterOptions {
  readonly repositoryRoot: string;
  readonly ignorePatterns?: readonly string[] | undefined;
  readonly onEvent?: ((event: WatcherEvent) => void) | undefined;
  readonly onError?: ((error: Error) => void) | undefined;
}

export interface FilesystemAdapter {
  readonly repositoryRoot: string;
  readonly isWatching: boolean;
  start(): Promise<void>;
  stop(): Promise<void>;
  emitSyntheticEvent(
    rawKind: string,
    rawPath: string,
    renamedTo?: string,
  ): WatcherEvent;
}

export class NativeFilesystemAdapter implements FilesystemAdapter {
  public readonly repositoryRoot: string;
  private readonly ignorePatterns: readonly string[];
  private readonly onEvent?: ((event: WatcherEvent) => void) | undefined;
  private readonly onError?: ((error: Error) => void) | undefined;
  private watching = false;

  constructor(options: FilesystemAdapterOptions) {
    if (!isAbsolute(options.repositoryRoot)) {
      throw new Error("Repository root must be an absolute path.");
    }
    this.repositoryRoot = normalize(options.repositoryRoot);
    this.ignorePatterns = options.ignorePatterns ?? [];
    this.onEvent = options.onEvent;
    this.onError = options.onError;
  }

  public get isWatching(): boolean {
    return this.watching;
  }

  public async start(): Promise<void> {
    this.watching = true;
  }

  public async stop(): Promise<void> {
    this.watching = false;
  }

  public emitSyntheticEvent(
    rawKind: string,
    rawPath: string,
    renamedTo?: string,
  ): WatcherEvent {
    if (!this.watching) {
      throw new Error("Cannot emit event while adapter is stopped.");
    }

    let relPath: string;
    if (isAbsolute(rawPath)) {
      const normalizedRaw = normalize(rawPath);
      if (!normalizedRaw.startsWith(this.repositoryRoot)) {
        throw new Error(
          "Path escape detected: path is outside repository root.",
        );
      }
      relPath = relative(this.repositoryRoot, normalizedRaw).replace(
        /\\/g,
        "/",
      );
    } else {
      relPath = rawPath.replace(/\\/g, "/");
    }

    let relRenamedTo: string | undefined;
    if (renamedTo) {
      if (isAbsolute(renamedTo)) {
        const normalizedRenamed = normalize(renamedTo);
        if (!normalizedRenamed.startsWith(this.repositoryRoot)) {
          throw new Error(
            "Path escape detected: renamedTo path is outside repository root.",
          );
        }
        relRenamedTo = relative(this.repositoryRoot, normalizedRenamed).replace(
          /\\/g,
          "/",
        );
      } else {
        relRenamedTo = renamedTo.replace(/\\/g, "/");
      }
    }

    for (const pattern of this.ignorePatterns) {
      if (relPath.startsWith(pattern) || relPath.includes(`/${pattern}`)) {
        throw new Error(`Ignored path change rejected: ${relPath}`);
      }
    }

    const event: WatcherEvent = validateWatcherEvent({
      contractVersion: WATCHER_CONTRACT_VERSION,
      kind: rawKind as WatcherEvent["kind"],
      path: relPath,
      ...(relRenamedTo ? { renamedTo: relRenamedTo } : {}),
      timestampMs: Date.now(),
    });

    this.onEvent?.(event);
    return event;
  }
}

import { randomUUID } from "node:crypto";
import {
  commitAtomicIndexTransaction,
  readCommittedIndexState,
  type AtomicIndexTransactionInput,
  type CanonicalIndexFileRecord,
  type IndexRemoval,
  type LocalIndexSemanticState,
} from "@fuzit/index";
import {
  verifyEventAgainstFilesystem,
  type VerifiedEventOutcome,
} from "./verifier.js";
import type { WatcherEvent } from "@fuzit/schemas";

export interface EventTransactionApplierOptions {
  readonly indexPath: string;
  readonly repositoryId: string;
  readonly repositoryRoot: string;
  readonly ignorePatterns?: readonly string[] | undefined;
  readonly semanticState: LocalIndexSemanticState;
}

export async function applyEventsToLocalIndex(
  events: readonly WatcherEvent[],
  options: EventTransactionApplierOptions,
): Promise<{ readonly transactionId: string; readonly appliedCount: number }> {
  const {
    indexPath,
    repositoryId,
    repositoryRoot,
    ignorePatterns = [],
    semanticState,
  } = options;

  const verifiedOutcomes: VerifiedEventOutcome[] = [];
  for (const event of events) {
    const outcome = await verifyEventAgainstFilesystem(event, {
      repositoryRoot,
      ignorePatterns,
    });
    verifiedOutcomes.push(outcome);
  }

  const existingState = await readCommittedIndexState(indexPath);
  const recordMap = new Map<string, CanonicalIndexFileRecord>(
    (existingState?.records ?? []).map((r: CanonicalIndexFileRecord) => [
      r.path,
      r,
    ]),
  );

  const removals: IndexRemoval[] = [];

  for (const outcome of verifiedOutcomes) {
    if (outcome.action === "upsert") {
      recordMap.set(outcome.path, {
        recordType: "file",
        schemaVersion: 1,
        path: outcome.path,
        contentHash: outcome.contentHash,
        sizeBytes: outcome.sizeBytes,
        mtimeMs: outcome.mtimeMs,
        classification: "text",
        securityDecision: {
          outcome: "include",
          reason: "watcher event verified",
        },
        completeness: "complete",
      });
    } else if (outcome.action === "delete") {
      if (recordMap.has(outcome.path)) {
        recordMap.delete(outcome.path);
        removals.push({
          path: outcome.path,
          reason: "deleted",
          deletionBasis: "verified-filesystem",
          invalidationIdentity: `watcher:${outcome.path}:${Date.now()}`,
        });
      }
    }
  }

  const transactionId = `tx-watcher-${randomUUID()}`;
  const now = new Date().toISOString();

  const transactionInput: AtomicIndexTransactionInput = {
    transactionId,
    repositoryId,
    startedAt: now,
    completedAt: now,
    records: Array.from(recordMap.values()),
    removals,
    semanticState,
  };

  await commitAtomicIndexTransaction(indexPath, transactionInput);

  return {
    transactionId,
    appliedCount: verifiedOutcomes.filter((o) => o.action !== "ignore").length,
  };
}

import {
  WATCHER_CONTRACT_VERSION,
  type WatcherBatch,
  type WatcherEvent,
} from "@fuzit/schemas";

export interface CoalescerOptions {
  readonly debounceMs?: number | undefined; // default 100ms
  readonly maxBatchSize?: number | undefined; // default 500
}

export class EventCoalescer {
  private readonly debounceMs: number;
  private readonly maxBatchSize: number;
  private pendingEvents: WatcherEvent[] = [];

  constructor(options: CoalescerOptions = {}) {
    this.debounceMs = options.debounceMs ?? 100;
    this.maxBatchSize = options.maxBatchSize ?? 500;
  }

  public push(event: WatcherEvent): void {
    this.pendingEvents.push(event);
  }

  public pushAll(events: readonly WatcherEvent[]): void {
    for (const e of events) {
      this.pendingEvents.push(e);
    }
  }

  public flush(batchId: string): WatcherBatch {
    const eventsToProcess = [...this.pendingEvents];
    this.pendingEvents = [];

    const overflowOccurred = eventsToProcess.length > this.maxBatchSize;
    const boundedEvents = eventsToProcess.slice(0, this.maxBatchSize);

    const isAtomicSaveTemp = (p: string) =>
      p.endsWith(".tmp") ||
      p.endsWith(".bak") ||
      p.endsWith("~") ||
      p.includes(".goutputstream-");

    const atomicSaveTargets = new Map<string, WatcherEvent>();
    for (const e of boundedEvents) {
      if (e.renamedTo && !isAtomicSaveTemp(e.renamedTo)) {
        atomicSaveTargets.set(e.renamedTo, {
          contractVersion: WATCHER_CONTRACT_VERSION,
          kind: "modify",
          path: e.renamedTo,
          timestampMs: e.timestampMs,
        });
      }
    }

    const map = new Map<string, WatcherEvent>();

    for (const event of boundedEvents) {
      if (isAtomicSaveTemp(event.path)) {
        if (event.renamedTo && atomicSaveTargets.has(event.renamedTo)) {
          const targetEvent = atomicSaveTargets.get(event.renamedTo)!;
          map.set(event.renamedTo, targetEvent);
        }
        continue;
      }

      const existing = map.get(event.path);
      if (!existing) {
        map.set(event.path, event);
        continue;
      }

      if (existing.kind === "add" && event.kind === "delete") {
        map.delete(event.path);
      } else if (existing.kind === "add" && event.kind === "modify") {
        map.set(event.path, { ...existing, timestampMs: event.timestampMs });
      } else if (existing.kind === "modify" && event.kind === "modify") {
        map.set(event.path, { ...existing, timestampMs: event.timestampMs });
      } else if (existing.kind === "modify" && event.kind === "delete") {
        map.set(event.path, event);
      } else {
        map.set(event.path, event);
      }
    }

    const coalescedEvents = Array.from(map.values()).sort((a, b) =>
      a.path.localeCompare(b.path),
    );

    return {
      contractVersion: WATCHER_CONTRACT_VERSION,
      batchId,
      events: coalescedEvents,
      reconciliationRequired: overflowOccurred,
      overflowOccurred,
    };
  }
}

import { NativeFilesystemAdapter } from "./adapter.js";
import { EventCoalescer } from "./coalescer.js";
import { IndexWriterLock } from "./lock.js";
import { reconcileRepositoryState } from "./reconciler.js";
import { applyEventsToLocalIndex } from "./applier.js";
import type { LocalIndexSemanticState } from "@fuzit/index";
import type { WatcherStatus } from "@fuzit/schemas";

export interface WatcherDaemonOptions {
  readonly repositoryRoot: string;
  readonly indexPath: string;
  readonly repositoryId: string;
  readonly semanticState: LocalIndexSemanticState;
  readonly ignorePatterns?: readonly string[] | undefined;
  readonly debounceMs?: number | undefined;
}

export class WatcherDaemon {
  private readonly options: WatcherDaemonOptions;
  private readonly adapter: NativeFilesystemAdapter;
  private readonly coalescer: EventCoalescer;
  private readonly lock: IndexWriterLock;
  private running = false;
  private currentStatus:
    "stopped" | "starting" | "watching" | "reconciling" | "stopping" | "error" =
    "stopped";
  private eventsProcessedCount = 0;
  private lastEventTs: number | null = null;
  private abortController?: AbortController | undefined;

  constructor(options: WatcherDaemonOptions) {
    this.options = options;
    this.coalescer = new EventCoalescer({ debounceMs: options.debounceMs });
    this.lock = new IndexWriterLock({
      indexPath: options.indexPath,
      repositoryId: options.repositoryId,
    });
    this.adapter = new NativeFilesystemAdapter({
      repositoryRoot: options.repositoryRoot,
      ignorePatterns: options.ignorePatterns,
      onEvent: (event) => {
        if (this.running) {
          this.coalescer.push(event);
          this.eventsProcessedCount++;
          this.lastEventTs = event.timestampMs;
        }
      },
    });
  }

  public get status(): WatcherStatus {
    return {
      contractVersion: 1,
      state: this.currentStatus,
      repositoryRoot: this.options.repositoryRoot,
      lockOwner:
        this.lock.isHeld && this.lock.metadata
          ? `pid:${this.lock.metadata.pid}`
          : null,
      activeWatchers: this.running ? 1 : 0,
      eventsProcessed: this.eventsProcessedCount,
      lastEventTimestampMs: this.lastEventTs,
    };
  }

  public async start(): Promise<void> {
    if (this.running) return;

    this.currentStatus = "starting";
    await this.lock.acquire();

    this.running = true;
    this.currentStatus = "watching";
    this.abortController = new AbortController();

    await this.adapter.start();
  }

  public async processPendingBatch(batchId: string): Promise<void> {
    if (!this.running) return;

    const batch = this.coalescer.flush(batchId);
    if (batch.events.length === 0 && !batch.reconciliationRequired) return;

    if (batch.reconciliationRequired) {
      this.currentStatus = "reconciling";
      await reconcileRepositoryState(batch, {
        indexPath: this.options.indexPath,
        repositoryId: this.options.repositoryId,
        repositoryRoot: this.options.repositoryRoot,
        ignorePatterns: this.options.ignorePatterns,
        semanticState: this.options.semanticState,
        signal: this.abortController?.signal,
      });
      this.currentStatus = "watching";
    } else {
      await applyEventsToLocalIndex(batch.events, {
        indexPath: this.options.indexPath,
        repositoryId: this.options.repositoryId,
        repositoryRoot: this.options.repositoryRoot,
        ignorePatterns: this.options.ignorePatterns,
        semanticState: this.options.semanticState,
      });
    }
  }

  public async stop(): Promise<void> {
    if (!this.running) {
      await this.lock.release();
      this.currentStatus = "stopped";
      return;
    }

    this.currentStatus = "stopping";
    this.running = false;

    this.abortController?.abort();

    try {
      await this.adapter.stop();
    } finally {
      await this.lock.release();
      this.currentStatus = "stopped";
    }
  }
}

export * from "./adapter.js";
export * from "./coalescer.js";
export * from "./verifier.js";
export * from "./applier.js";
export * from "./reconciler.js";
export * from "./lock.js";
export * from "./daemon.js";

export interface WatcherPackageBoundary {
  readonly packageName: "@fuzit/watcher";
}

import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { hostname } from "node:os";
import { join } from "node:path";

export interface LockMetadata {
  readonly lockVersion: 1;
  readonly pid: number;
  readonly createdAt: string;
  readonly repositoryId: string;
  readonly hostname: string;
  readonly sessionId: string;
}

export interface WriterLockOptions {
  readonly indexPath: string;
  readonly repositoryId: string;
  readonly staleThresholdMs?: number | undefined; // default 30,000ms
}

export class IndexWriterLock {
  private readonly lockFilePath: string;
  private readonly repositoryId: string;
  private readonly staleThresholdMs: number;
  private acquired = false;
  private lockMetadata?: LockMetadata | undefined;

  constructor(options: WriterLockOptions) {
    this.lockFilePath = join(options.indexPath, "writer.lock");
    this.repositoryId = options.repositoryId;
    this.staleThresholdMs = options.staleThresholdMs ?? 30_000;
  }

  public get isHeld(): boolean {
    return this.acquired;
  }

  public get metadata(): LockMetadata | undefined {
    return this.lockMetadata;
  }

  public async acquire(): Promise<void> {
    await mkdir(join(this.lockFilePath, ".."), { recursive: true });

    // Check if existing lock exists
    try {
      const raw = await readFile(this.lockFilePath, "utf8");
      const meta = JSON.parse(raw) as LockMetadata;

      // Validate lock schema
      if (meta.lockVersion !== 1 || typeof meta.pid !== "number") {
        // Corrupt lock file -> purge safely if stale
        await rm(this.lockFilePath, { force: true });
      } else {
        const lockAge = Date.now() - new Date(meta.createdAt).getTime();
        const isSamePid = meta.pid === process.pid;

        if (isSamePid) {
          // Re-acquisition by same process
          this.acquired = true;
          this.lockMetadata = meta;
          return;
        }

        if (lockAge < this.staleThresholdMs) {
          // Check if process is actually running
          let isAlive = false;
          try {
            isAlive = process.kill(meta.pid, 0);
          } catch {
            isAlive = false;
          }

          if (isAlive) {
            throw new Error(
              `Writer lock active and held by PID ${meta.pid} on ${meta.hostname} since ${meta.createdAt}`,
            );
          }
        }

        // Stale lock -> clear stale lock
        await rm(this.lockFilePath, { force: true });
      }
    } catch (error) {
      if (
        error instanceof Error &&
        "code" in error &&
        error.code === "ENOENT"
      ) {
        // File does not exist, proceed to create
      } else if (
        error instanceof Error &&
        error.message.startsWith("Writer lock active")
      ) {
        throw error;
      } else {
        // Corrupt lock file content -> purge safely
        await rm(this.lockFilePath, { force: true });
      }
    }

    const newMeta: LockMetadata = {
      lockVersion: 1,
      pid: process.pid,
      createdAt: new Date().toISOString(),
      repositoryId: this.repositoryId,
      hostname: hostname(),
      sessionId: `session-${process.pid}-${Date.now()}`,
    };

    await writeFile(this.lockFilePath, JSON.stringify(newMeta, null, 2), {
      flag: "wx",
    });
    this.acquired = true;
    this.lockMetadata = newMeta;
  }

  public async release(): Promise<void> {
    if (!this.acquired) return;
    try {
      await rm(this.lockFilePath, { force: true });
    } finally {
      this.acquired = false;
      this.lockMetadata = undefined;
    }
  }
}

import { createHash } from "node:crypto";
import { readdir, readFile, stat } from "node:fs/promises";
import { join, relative } from "node:path";
import {
  commitAtomicIndexTransaction,
  readCommittedIndexState,
  type AtomicIndexTransactionInput,
  type CanonicalIndexFileRecord,
  type IndexRemoval,
  type LocalIndexSemanticState,
} from "@fuzit/index";
import type { WatcherBatch } from "@fuzit/schemas";

export interface ReconciliationOptions {
  readonly indexPath: string;
  readonly repositoryId: string;
  readonly repositoryRoot: string;
  readonly ignorePatterns?: readonly string[] | undefined;
  readonly semanticState: LocalIndexSemanticState;
  readonly signal?: AbortSignal | undefined;
}

export interface ReconciliationResult {
  readonly transactionId: string;
  readonly isOverflowReconciled: boolean;
  readonly addedCount: number;
  readonly updatedCount: number;
  readonly deletedCount: number;
}

async function scanFilesystem(
  dir: string,
  root: string,
  ignorePatterns: readonly string[],
  signal?: AbortSignal,
): Promise<Map<string, { sizeBytes: number; mtimeMs: number }>> {
  const result = new Map<string, { sizeBytes: number; mtimeMs: number }>();

  async function walk(current: string) {
    if (signal?.aborted) {
      throw new Error("Reconciliation aborted by signal");
    }

    const entries = await readdir(current, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = join(current, entry.name);
      const relPath = relative(root, fullPath).replace(/\\/g, "/");

      let ignored = false;
      for (const pattern of ignorePatterns) {
        if (relPath.startsWith(pattern) || relPath.includes(`/${pattern}`)) {
          ignored = true;
          break;
        }
      }
      if (ignored) continue;

      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (entry.isFile()) {
        const st = await stat(fullPath);
        result.set(relPath, { sizeBytes: st.size, mtimeMs: st.mtimeMs });
      }
    }
  }

  await walk(dir);
  return result;
}

export async function reconcileRepositoryState(
  batch: WatcherBatch,
  options: ReconciliationOptions,
): Promise<ReconciliationResult> {
  const {
    indexPath,
    repositoryId,
    repositoryRoot,
    ignorePatterns = [],
    semanticState,
    signal,
  } = options;

  if (signal?.aborted) {
    throw new Error("Reconciliation aborted prior to execution");
  }

  const existingState = await readCommittedIndexState(indexPath);
  const existingMap = new Map<string, CanonicalIndexFileRecord>(
    (existingState?.records ?? []).map((r: CanonicalIndexFileRecord) => [
      r.path,
      r,
    ]),
  );

  const fsMap = await scanFilesystem(
    repositoryRoot,
    repositoryRoot,
    ignorePatterns,
    signal,
  );

  let addedCount = 0;
  let updatedCount = 0;
  let deletedCount = 0;

  const newRecords: CanonicalIndexFileRecord[] = [];
  const removals: IndexRemoval[] = [];

  // Check additions and updates
  for (const [relPath, fsMeta] of fsMap.entries()) {
    if (signal?.aborted) {
      throw new Error("Reconciliation aborted during record processing");
    }

    const existingRecord = existingMap.get(relPath);
    if (!existingRecord) {
      const fullPath = join(repositoryRoot, relPath);
      const buf = await readFile(fullPath);
      const contentHash = `sha256:${createHash("sha256").update(buf).digest("hex")}`;
      newRecords.push({
        recordType: "file",
        schemaVersion: 1,
        path: relPath,
        contentHash,
        sizeBytes: fsMeta.sizeBytes,
        mtimeMs: fsMeta.mtimeMs,
        classification: "text",
        securityDecision: {
          outcome: "include",
          reason: "reconciliation full scan",
        },
        completeness: "complete",
      });
      addedCount++;
    } else if (
      existingRecord.sizeBytes !== fsMeta.sizeBytes ||
      existingRecord.mtimeMs !== fsMeta.mtimeMs
    ) {
      const fullPath = join(repositoryRoot, relPath);
      const buf = await readFile(fullPath);
      const contentHash = `sha256:${createHash("sha256").update(buf).digest("hex")}`;
      newRecords.push({
        ...existingRecord,
        contentHash,
        sizeBytes: fsMeta.sizeBytes,
        mtimeMs: fsMeta.mtimeMs,
      });
      updatedCount++;
    } else {
      newRecords.push(existingRecord);
    }
  }

  // Check deletions
  for (const relPath of existingMap.keys()) {
    if (!fsMap.has(relPath)) {
      deletedCount++;
      removals.push({
        path: relPath,
        reason: "deleted",
        deletionBasis: "canonical-state-diff",
        invalidationIdentity: `reconcile:${relPath}:${Date.now()}`,
      });
    }
  }

  const transactionId = `tx-reconcile-${Date.now()}`;
  const now = new Date().toISOString();

  const transactionInput: AtomicIndexTransactionInput = {
    transactionId,
    repositoryId,
    startedAt: now,
    completedAt: now,
    records: newRecords,
    removals,
    semanticState,
  };

  await commitAtomicIndexTransaction(indexPath, transactionInput);

  return {
    transactionId,
    isOverflowReconciled: batch.overflowOccurred,
    addedCount,
    updatedCount,
    deletedCount,
  };
}

import { createHash } from "node:crypto";
import { readFile, stat } from "node:fs/promises";
import { join } from "node:path";
import type { WatcherEvent } from "@fuzit/schemas";

export interface EventVerificationOptions {
  readonly repositoryRoot: string;
  readonly ignorePatterns?: readonly string[] | undefined;
}

export type VerifiedEventOutcome =
  | {
      readonly action: "upsert";
      readonly path: string;
      readonly contentHash: string;
      readonly sizeBytes: number;
      readonly mtimeMs: number;
    }
  | { readonly action: "delete"; readonly path: string }
  | {
      readonly action: "ignore";
      readonly path: string;
      readonly reason: string;
    };

export async function verifyEventAgainstFilesystem(
  event: WatcherEvent,
  options: EventVerificationOptions,
): Promise<VerifiedEventOutcome> {
  const { repositoryRoot, ignorePatterns = [] } = options;
  const targetPath = join(repositoryRoot, event.path);

  // Check ignore patterns
  for (const pattern of ignorePatterns) {
    if (event.path.startsWith(pattern) || event.path.includes(`/${pattern}`)) {
      return {
        action: "ignore",
        path: event.path,
        reason: `Ignored pattern match: ${pattern}`,
      };
    }
  }

  // Check filesystem state
  let fileStat;
  try {
    fileStat = await stat(targetPath);
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return { action: "delete", path: event.path };
    }
    return {
      action: "ignore",
      path: event.path,
      reason: "Inaccessible filesystem path",
    };
  }

  if (!fileStat.isFile()) {
    return {
      action: "ignore",
      path: event.path,
      reason: "Target is not a regular file",
    };
  }

  // Compute content hash
  try {
    const buffer = await readFile(targetPath);
    const contentHash = `sha256:${createHash("sha256").update(buffer).digest("hex")}`;
    return {
      action: "upsert",
      path: event.path,
      contentHash,
      sizeBytes: fileStat.size,
      mtimeMs: fileStat.mtimeMs,
    };
  } catch {
    return {
      action: "ignore",
      path: event.path,
      reason: "Unable to read file content",
    };
  }
}

