    category: "security",
    command: ["pnpm", "audit:secrets"],
  },
  {
    id: "security-privacy",
    category: "security",
    command: ["pnpm", "audit:privacy"],
  },
  {
    id: "incremental-tests",
    category: "incremental",
    command: ["pnpm", "test:incremental"],
  },
  { id: "graph-tests", category: "graph", command: ["pnpm", "test:graph"] },
  { id: "mcp-tests", category: "mcp", command: ["pnpm", "test:mcp"] },
  { id: "plugin-tests", category: "plugin", command: ["pnpm", "test:plugins"] },
  {
    id: "extension-tests",
    category: "extension",
    command: ["pnpm", "test:vscode"],
  },
  {
    id: "packaging-smoke",
    category: "packaging",
    command: ["pnpm", "package:smoke"],
  },
  { id: "docs-build", category: "docs", command: ["pnpm", "docs:build"] },
  { id: "docs-check", category: "docs", command: ["pnpm", "docs:check"] },
  { id: "docs-tests", category: "docs", command: ["pnpm", "test:docs"] },
  {
    id: "cleanliness-diff",
    category: "cleanliness",
    command: ["git", "diff", "--check"],
  },
]);

function executeScenario(scenario) {
  const startedAt = performance.now();
  const [program, ...arguments_] = scenario.command;
  const executable = program === "pnpm" ? process.execPath : program;
  const effectiveArguments =
    program === "pnpm" ? [process.env.npm_execpath, ...arguments_] : arguments_;
  if (program === "pnpm" && !process.env.npm_execpath) {
    return {
      status: 1,
      error: "pnpm must invoke acceptance:v1",
      durationMs: 0,
    };
  }
  const result = spawnSync(executable, effectiveArguments, {
    encoding: "utf8",
    stdio: "inherit",
    shell: false,
    timeout: 15 * 60 * 1000,
  });
  return {
    status: result.status ?? 1,
    durationMs: Math.round(performance.now() - startedAt),
    ...(result.error ? { error: result.error.message } : {}),
  };
}

export function selectAcceptanceScenarios(filters = []) {
  const normalized = [...new Set(filters.map((value) => value.toLowerCase()))];
  const selected =
    normalized.length === 0
      ? acceptanceScenarios
      : acceptanceScenarios.filter(
          ({ id, category }) =>
            normalized.includes(category) || normalized.includes(id),
        );
  if (selected.length === 0) {
    throw new Error(`no acceptance scenarios match: ${normalized.join(", ")}`);
  }
  return selected;
}

export function runAcceptance({
  filters = [],
  execute = executeScenario,
} = {}) {
  const scenarios = selectAcceptanceScenarios(filters);
  const results = scenarios.map((scenario) => {
    const outcome = execute(scenario);
    return {
      id: scenario.id,
      category: scenario.category,
      command: scenario.command.join(" "),
      status: outcome.status === 0 ? "passed" : "failed",
      exitCode: outcome.status,
      durationMs: outcome.durationMs ?? 0,
      warnings: outcome.warnings ?? [],
      artifacts: outcome.artifacts ?? [],
      ...(outcome.error ? { error: outcome.error } : {}),
    };
  });
  return {
    schemaVersion: 1,
    gate: "acceptance:v1",
    status: results.every(({ exitCode }) => exitCode === 0)
      ? "passed"
      : "failed",
    filters: [...filters],
    scenarioCount: results.length,
    warningCount: results.reduce(
      (count, result) => count + result.warnings.length,
      0,
    ),
    results,
  };
}

function parseArguments(arguments_) {
  const filters = [];
  let list = false;
  for (let index = 0; index < arguments_.length; index += 1) {
    const argument = arguments_[index];
    if (argument === "--list") list = true;
    else if (argument === "--filter" && arguments_[index + 1])
      filters.push(...arguments_[++index].split(",").filter(Boolean));
    else throw new Error(`unknown or incomplete argument: ${argument}`);
  }
  return { filters, list };
}

async function main() {
  try {
    const { filters, list } = parseArguments(process.argv.slice(2));
    if (list) {
      process.stdout.write(
        `${JSON.stringify({ schemaVersion: 1, gate: "acceptance:v1", scenarios: selectAcceptanceScenarios(filters) })}\n`,
      );
      return;
    }
    const summary = runAcceptance({ filters });
    process.stdout.write(`${JSON.stringify(summary)}\n`);
    if (summary.status !== "passed") process.exitCode = 1;
  } catch (error) {
    process.stderr.write(
      `${JSON.stringify({ schemaVersion: 1, gate: "acceptance:v1", status: "failed", error: error.message })}\n`,
    );
    process.exitCode = 1;
  }
}

if (
  process.argv[1] &&
  pathToFileURL(process.argv[1]).href === import.meta.url
) {
  await main();
}

import { execFileSync } from "node:child_process";
import { describe, expect, it } from "vitest";
import {
  acceptanceScenarios,
  runAcceptance,
  selectAcceptanceScenarios,
} from "./acceptance-v1.mjs";

describe("unified V1 acceptance", () => {
  it("keeps a deterministic mandatory scenario order", () => {
    expect(selectAcceptanceScenarios()).toEqual(acceptanceScenarios);
    expect(
      new Set(acceptanceScenarios.map(({ category }) => category)),
    ).toEqual(
      new Set([
        "product",
        "platform",
        "security",
        "incremental",
        "graph",
        "mcp",
        "plugin",
        "extension",
        "packaging",
        "docs",
        "cleanliness",
      ]),
    );
  });

  it("records every result and fails when any mandatory scenario fails", () => {
    const invoked = [];
    const summary = runAcceptance({
      filters: ["graph", "mcp"],
      execute: ({ id }) => {
        invoked.push(id);
        return {
          status: id === "graph-tests" ? 7 : 0,
          durationMs: id === "graph-tests" ? 12 : 4,
          warnings: id === "graph-tests" ? ["synthetic warning"] : [],
          artifacts: id === "mcp-tests" ? ["synthetic artifact"] : [],
        };
      },
    });
    expect(invoked).toEqual(["graph-tests", "mcp-tests"]);
    expect(summary.status).toBe("failed");
    expect(summary.results.map(({ exitCode }) => exitCode)).toEqual([7, 0]);
    expect(summary.scenarioCount).toBe(2);
    expect(summary.warningCount).toBe(1);
    expect(summary.results.map(({ durationMs }) => durationMs)).toEqual([
      12, 4,
    ]);
    expect(summary.results[1].artifacts).toEqual(["synthetic artifact"]);
  });

  it("exposes stable structured scenario discovery through the CLI", () => {
    const output = execFileSync(
      process.execPath,
      ["scripts/acceptance-v1.mjs", "--list", "--filter", "platform"],
      { encoding: "utf8" },
    );
    expect(JSON.parse(output)).toEqual({
      schemaVersion: 1,
      gate: "acceptance:v1",
      scenarios: [
        {
          id: "platform-contracts",
          category: "platform",
          command: ["pnpm", "test:cross-platform"],
        },
      ],
    });
  });
});

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, readdir, writeFile } from "node:fs/promises";
import { basename, join, relative, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = resolve(".");

async function sha256(path) {
  return createHash("sha256")
    .update(await readFile(path))
    .digest("hex");
}

async function publicPackageVersions() {
  const manifests = [
    "apps/cli/package.json",
    "apps/mcp-server/package.json",
    "apps/vscode-extension/package.json",
    "packages/plugin-sdk/package.json",
  ];
  return Object.fromEntries(
    await Promise.all(
      manifests.map(async (path) => {
        const manifest = JSON.parse(await readFile(join(root, path), "utf8"));
        return [manifest.name, manifest.version];
      }),
    ),
  );
}

export async function createArtifactManifest({
  artifactDirectory,
  outputPath,
}) {
  const directory = resolve(artifactDirectory);
  const output = resolve(outputPath);
  const paths = (await readdir(directory))
    .filter((path) => path !== basename(output) && !path.endsWith(".json"))
    .sort();
  if (paths.length === 0) throw new Error("No release artifacts were found.");
  const artifacts = await Promise.all(
    paths.map(async (path) => ({
      path: relative(root, join(directory, path)).replaceAll("\\", "/"),
      bytes: (await readFile(join(directory, path))).length,
      sha256: await sha256(join(directory, path)),
    })),
  );
  const state = JSON.parse(
    await readFile(join(root, "docs/release/release-state.json"), "utf8"),
  );
  const manifest = {
    schemaVersion: 1,
    sourceCommit: execFileSync("git", ["rev-parse", "HEAD"], {
      cwd: root,
      encoding: "utf8",
    }).trim(),
    lockSha256: await sha256(join(root, "pnpm-lock.yaml")),
    packageVersions: await publicPackageVersions(),
    persistentSchemaVersions: state.persistentSchemaVersions,
    supportedMatrix: {
      node: ["24"],
      platforms: ["darwin-arm64", "linux-x64", "win32-x64"],
    },
    artifacts,
  };
  await writeFile(output, `${JSON.stringify(manifest, null, 2)}\n`);
  return manifest;
}

export async function assertArtifactChecksums(manifest, artifactDirectory) {
  const directory = resolve(artifactDirectory);
  for (const artifact of manifest.artifacts) {
    const actual = await sha256(join(directory, basename(artifact.path)));
    if (actual !== artifact.sha256) {
      throw new Error(`Artifact checksum mismatch: ${artifact.path}`);
    }
  }
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  const artifactDirectory = process.argv[2];
  const outputPath = process.argv[3];
  if (!artifactDirectory || !outputPath) {
    throw new Error(
      "usage: artifact-manifest <artifact-directory> <output-path>",
    );
  }
  const manifest = await createArtifactManifest({
    artifactDirectory,
    outputPath,
  });
  await assertArtifactChecksums(manifest, artifactDirectory);
  process.stdout.write(
    `${JSON.stringify({ manifest: outputPath, artifacts: manifest.artifacts.length })}\n`,
  );
}

import { performance } from "node:perf_hooks";
import {
  mkdir,
  readFile,
  readdir,
  writeFile as writeFsFile,
} from "node:fs/promises";
import { resolve } from "node:path";
import {
  compareBaseline,
  measureRetrieval,
} from "../packages/benchmark/dist/index.js";

const directory = resolve("benchmarks/retrieval");
const baseline = JSON.parse(
  await readFile(resolve(directory, "baseline.json"), "utf8"),
);
const cases = (await readdir(directory))
  .filter((path) => path !== "baseline.json" && path.endsWith(".json"))
  .sort();
const results = [];
for (const path of cases) {
  const input = JSON.parse(await readFile(resolve(directory, path), "utf8"));
  const start = performance.now();
  const metrics = measureRetrieval(input);
  const latencyMs = performance.now() - start;
  const comparison = compareBaseline(metrics, baseline[input.id] ?? metrics);
  results.push({
    id: input.id,
    ...metrics,
    latencyMs,
    regression: comparison.regressed,
  });
}
const outputPayload = {
  schemaVersion: 1,
  environment: {
    nodeVersion: process.version,
    platform: process.platform,
    arch: process.arch,
  },
  results,
};
const resultsDir = resolve("benchmarks/results");
await mkdir(resultsDir, { recursive: true });
await writeFsFile(
  resolve(resultsDir, "v1-release-baseline.json"),
  `${JSON.stringify(outputPayload, null, 2)}\n`,
);
process.stdout.write(`${JSON.stringify(outputPayload, null, 2)}\n`);
if (results.some(({ regression }) => regression)) process.exitCode = 1;

import { spawnSync } from "node:child_process";
import { Buffer } from "node:buffer";
import { createHash } from "node:crypto";
import {
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, resolve, sep } from "node:path";
import { pathToFileURL } from "node:url";
import { gzipSync } from "node:zlib";

const root = resolve(import.meta.dirname, "..");

function writeString(buffer, offset, length, value) {
  const bytes = Buffer.from(value, "utf8");
  if (bytes.length > length) throw new Error(`tar field too long: ${value}`);
  bytes.copy(buffer, offset);
}

function writeOctal(buffer, offset, length, value) {
  writeString(
    buffer,
    offset,
    length,
    `${value.toString(8).padStart(length - 1, "0")}\0`,
  );
}

function tarHeader(path, size, mode) {
  if (
    path.startsWith("/") ||
    /^[A-Za-z]:[\\/]/.test(path) ||
    path.includes("..")
  )
    throw new Error(`unsafe artifact path: ${path}`);
  const header = Buffer.alloc(512);
  writeString(header, 0, 100, path);
  writeOctal(header, 100, 8, mode);
  writeOctal(header, 108, 8, 0);
  writeOctal(header, 116, 8, 0);
  writeOctal(header, 124, 12, size);
  writeOctal(header, 136, 12, 0);
  header.fill(0x20, 148, 156);
  header[156] = "0".charCodeAt(0);
  writeString(header, 257, 6, "ustar\0");
  writeString(header, 263, 2, "00");
  writeString(header, 265, 32, "root");
  writeString(header, 297, 32, "root");
  const checksum = header.reduce((sum, byte) => sum + byte, 0);
  writeString(header, 148, 8, `${checksum.toString(8).padStart(6, "0")}\0 `);
  return header;
}

export function createCanonicalTarGzip(entries) {
  const chunks = [];
  for (const entry of [...entries].sort((left, right) =>
    left.path.localeCompare(right.path),
  )) {
    const mode = entry.path === "package/bin/fuzit.mjs" ? 0o755 : 0o644;
    chunks.push(tarHeader(entry.path, entry.bytes.length, mode), entry.bytes);
    const padding = (512 - (entry.bytes.length % 512)) % 512;
    if (padding > 0) chunks.push(Buffer.alloc(padding));
  }
  chunks.push(Buffer.alloc(1024));
  return gzipSync(Buffer.concat(chunks), { level: 9, mtime: 0 });
}

async function collectFiles(directory) {
  const entries = [];
  async function visit(current) {
    for (const item of (await readdir(current, { withFileTypes: true })).sort(
      (a, b) => a.name.localeCompare(b.name),
    )) {
      const absolute = join(current, item.name);
      if (item.isDirectory()) await visit(absolute);
      else if (item.isFile()) {
        let bytes = await readFile(absolute);
        if (item.name === "package.json") {
          const sortObject = (value) => {
            if (Array.isArray(value)) return value.map(sortObject);
            if (value !== null && typeof value === "object")
              return Object.fromEntries(
                Object.entries(value)
                  .sort(([left], [right]) => left.localeCompare(right))
                  .map(([key, child]) => [key, sortObject(child)]),
              );
            return value;
          };
          bytes = Buffer.from(
            `${JSON.stringify(sortObject(JSON.parse(bytes)), null, 2)}\n`,
          );
        }
        entries.push({
          path: `package/${relative(directory, absolute).split(sep).join("/")}`,
          bytes,
        });
      } else throw new Error(`unsupported artifact entry: ${absolute}`);
    }
  }
  await visit(directory);
  return entries;
}

function run(command, arguments_, cwd) {
  const result = spawnSync(command, arguments_, {
    cwd,
    encoding: "utf8",
    shell: false,
  });
  if (result.status !== 0)
    throw new Error(
      `${command} failed: ${result.error?.message ?? result.stderr ?? result.stdout}`,
    );
  return result.stdout;
}

export async function buildPrivateCliArtifact(outputDirectory) {
  if (!process.env.npm_execpath)
    throw new Error("npm_execpath is required; run through pnpm artifacts:cli");
  const temporary = await mkdtemp(join(tmpdir(), "fuzit-v1-132-"));
  try {
    const packed = join(temporary, "packed");
    const extracted = join(temporary, "extracted");
    await mkdir(packed);
    await mkdir(extracted);
    run(
      process.execPath,
      [
        process.env.npm_execpath,
        "--dir",
        "apps/cli",
        "pack",
        "--pack-destination",
        packed,
      ],
      root,
    );
    const tarballName = (await readdir(packed)).find((path) =>
      path.endsWith(".tgz"),
    );
    if (!tarballName) throw new Error("pnpm did not produce a CLI tarball");
    run("tar", ["-xf", join(packed, tarballName), "-C", extracted], root);
    const entries = await collectFiles(join(extracted, "package"));
    const bytes = createCanonicalTarGzip(entries);
    const sha256 = createHash("sha256").update(bytes).digest("hex");
    const target = resolve(outputDirectory);
    await mkdir(target, { recursive: true });
    await writeFile(join(target, tarballName), bytes);
    const manifest = {
      schemaVersion: 1,
      artifact: tarballName,
      sha256,
      bytes: bytes.length,
      sourceCommit: run("git", ["rev-parse", "HEAD"], root).trim(),
      package: "fuzit",
      version: "0.0.1",
      entries: entries.map(({ path, bytes: content }) => ({
        path,
        bytes: content.length,
        sha256: createHash("sha256").update(content).digest("hex"),
      })),
      publication: "none",
    };
    await writeFile(
      join(target, "fuzit-cli.manifest.json"),
      `${JSON.stringify(manifest, null, 2)}\n`,
    );
    return { output: target, manifest };
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const output =
    process.env.FUZIT_ARTIFACT_OUTPUT ?? join(root, "artifacts", "local", "v1");
  const result = await buildPrivateCliArtifact(output);
  process.stdout.write(
    `${JSON.stringify({ output: result.output, artifact: result.manifest.artifact, sha256: result.manifest.sha256, publication: "none" })}\n`,
  );
}

