import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";

export const READY = "PUBLIC-V1-RELEASE-READY — PUBLICATION NOT AUTHORIZED";
export const BLOCKED = "PUBLIC-V1-RELEASE-BLOCKED — PUBLICATION NOT AUTHORIZED";
export const AUTHORIZED = "PUBLIC-V1-RELEASE-READY — PUBLICATION AUTHORIZED";
export const BLOCKED_AUTHORIZED =
  "PUBLIC-V1-RELEASE-BLOCKED — PUBLICATION AUTHORIZED";

export function determineFinalVerdict({
  blockers,
  decisions,
  publicationAuthorized,
}) {
  const absent = decisions
    .filter(({ approved }) => approved !== true)
    .map(({ id }) => id)
    .sort();
  const open = [...blockers].sort();
  return {
    schemaVersion: 1,
    verdict:
      open.length === 0 && absent.length === 0
        ? publicationAuthorized
          ? AUTHORIZED
          : READY
        : publicationAuthorized
          ? BLOCKED_AUTHORIZED
          : BLOCKED,
    publicationAuthorized,
    openBlockers: open,
    absentDecisions: absent,
    publicationActionsPermitted:
      open.length === 0 &&
      absent.length === 0 &&
      publicationAuthorized === true,
  };
}

if (
  process.argv[1] &&
  pathToFileURL(process.argv[1]).href === import.meta.url
) {
  const state = JSON.parse(
    await readFile("docs/release/release-state.json", "utf8"),
  );
  const risks = JSON.parse(
    await readFile("docs/release/residual-risks.json", "utf8"),
  );
  const result = determineFinalVerdict({
    blockers: risks.risks
      .filter(
        ({ releaseBlocking, status }) => releaseBlocking && status === "open",
      )
      .map(({ id }) => id),
    decisions: state.releaseDecisions,
    publicationAuthorized: state.publicationAuthorized,
  });
  process.stdout.write(`${JSON.stringify(result)}\n`);
  if (
    ![AUTHORIZED, BLOCKED_AUTHORIZED].includes(result.verdict) ||
    result.publicationActionsPermitted !== (result.verdict === AUTHORIZED)
  )
    process.exitCode = 1;
}

import { describe, expect, it } from "vitest";
import {
  AUTHORIZED,
  BLOCKED,
  BLOCKED_AUTHORIZED,
  READY,
  determineFinalVerdict,
} from "./final-verdict.mjs";

describe("final V1 verdict", () => {
  it("blocks deterministically when a blocker or decision remains", () => {
    const input = {
      blockers: ["native"],
      decisions: [{ id: "publish", approved: false }],
      publicationAuthorized: false,
    };
    expect(determineFinalVerdict(input)).toEqual(determineFinalVerdict(input));
    expect(determineFinalVerdict(input)).toMatchObject({
      verdict: BLOCKED,
      publicationActionsPermitted: false,
    });
  });
  it("uses the preferred readiness verdict only when all prerequisites are satisfied", () => {
    expect(
      determineFinalVerdict({
        blockers: [],
        decisions: [{ id: "license", approved: true }],
        publicationAuthorized: false,
      }),
    ).toMatchObject({ verdict: READY, publicationAuthorized: false });
  });
  it("never permits publication from a technical verdict", () => {
    expect(
      determineFinalVerdict({
        blockers: [],
        decisions: [],
        publicationAuthorized: false,
      }).publicationActionsPermitted,
    ).toBe(false);
  });
  it("permits publication only after explicit authorization", () => {
    expect(
      determineFinalVerdict({
        blockers: [],
        decisions: [],
        publicationAuthorized: true,
      }),
    ).toMatchObject({ verdict: AUTHORIZED, publicationActionsPermitted: true });
  });
  it("keeps an authorized release blocked while a technical blocker is open", () => {
    expect(
      determineFinalVerdict({
        blockers: ["dependency-closure"],
        decisions: [],
        publicationAuthorized: true,
      }),
    ).toMatchObject({
      verdict: BLOCKED_AUTHORIZED,
      publicationActionsPermitted: false,
    });
  });
});

import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { tmpdir } from "node:os";
import { pathToFileURL } from "node:url";

const root = resolve(".");
const allowedLicenses = new Set([
  "0BSD",
  "Apache-2.0",
  "BSD-2-Clause",
  "BSD-3-Clause",
  "ISC",
  "MIT",
  "Python-2.0",
]);

function licenseId(value) {
  if (typeof value === "string") return value;
  if (value && typeof value.type === "string") return value.type;
  return "UNKNOWN";
}

async function locateDependency(packageDirectory, name) {
  let current = packageDirectory;
  for (;;) {
    const candidate = join(current, "node_modules", name, "package.json");
    try {
      await readFile(candidate);
      return candidate;
    } catch {
      const parent = dirname(current);
      if (parent === current)
        throw new Error(`Missing installed dependency: ${name}`);
      current = parent;
    }
  }
}

export async function generateSbom({ packageManifestPaths }) {
  const components = new Map();
  const relationships = new Set();
  const licenseFindings = [];

  async function visit(manifestPath, rootComponent = false) {
    const bytes = await readFile(manifestPath);
    const manifest = JSON.parse(bytes.toString("utf8"));
    const reference = `pkg:npm/${encodeURIComponent(manifest.name)}@${manifest.version}`;
    if (components.has(reference)) return reference;
    const license = licenseId(manifest.license);
    const approved = allowedLicenses.has(license);
    components.set(reference, {
      bomRef: reference,
      name: manifest.name,
      version: manifest.version,
      license,
      integrity: `sha256:${createHash("sha256").update(bytes).digest("hex")}`,
      root: rootComponent,
    });
    if (!approved) {
      licenseFindings.push({
        package: `${manifest.name}@${manifest.version}`,
        license,
        blocker: true,
        reason:
          license === "UNLICENSED" && manifest.name.startsWith("@fuzit/")
            ? "private package license requires owner authorization"
            : "unknown or disallowed dependency license",
      });
    }
    for (const name of Object.keys(manifest.dependencies ?? {}).sort()) {
      const dependencyPath = await locateDependency(
        dirname(manifestPath),
        name,
      );
      const dependencyReference = await visit(dependencyPath);
      relationships.add(`${reference}\0${dependencyReference}`);
    }
    return reference;
  }

  for (const path of [...packageManifestPaths].sort())
    await visit(resolve(path), true);
  return {
    bomFormat: "CycloneDX",
    specVersion: "1.6",
    serialNumber: "urn:uuid:00000000-0000-5000-8000-000000000001",
    version: 1,
    metadata: { tool: { name: "fuzit-sbom", version: "1" } },
    components: [...components.values()].sort((a, b) =>
      a.bomRef.localeCompare(b.bomRef),
    ),
    relationships: [...relationships].sort().map((value) => {
      const [from, to] = value.split("\0");
      return { from, to };
    }),
    licenseFindings: licenseFindings.sort((a, b) =>
      a.package.localeCompare(b.package),
    ),
    releaseEligible: licenseFindings.length === 0,
  };
}

export function assertDependencyLicenses(sbom) {
  const externalFindings = sbom.licenseFindings.filter(
    ({ package: name }) => !name.startsWith("@fuzit/"),
  );
  if (externalFindings.length > 0) {
    throw new Error(
      `SBOM contains blocked dependency licenses: ${externalFindings.map(({ package: name }) => name).join(", ")}`,
    );
  }
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  const output = process.argv[2] ?? join(tmpdir(), "fuzit-sbom.json");
  const manifests = [
    "apps/cli/package.json",
    "apps/mcp-server/package.json",
    "apps/vscode-extension/package.json",
    "packages/plugin-sdk/package.json",
  ].map((path) => join(root, path));
  const sbom = await generateSbom({ packageManifestPaths: manifests });
  assertDependencyLicenses(sbom);
  await writeFile(resolve(output), `${JSON.stringify(sbom, null, 2)}\n`);
  process.stdout.write(
    `${JSON.stringify({ output, components: sbom.components.length, releaseEligible: sbom.releaseEligible })}\n`,
  );
}

