      "v{version}",
      "--verify-tag",
      "--title",
      "Fuzit v{version}",
    ],
  },
]);

const requiredCredentials = Object.freeze([
  "NPM_TOKEN",
  "VSCE_PAT",
  "GITHUB_TOKEN",
]);

export function evaluateReleaseAuthorization({
  state,
  environment,
  head,
  version,
  branch,
  dirtyPaths = [],
}) {
  const reasons = [];
  const authorization = state.releaseAuthorization;
  if (state.publicationAuthorized !== true)
    reasons.push("publicationAuthorized is not true");
  if (state.publicationPaused === true) reasons.push("publication is paused");
  for (const blocker of state.releaseBlockers ?? []) {
    if (blocker.status === "open")
      reasons.push(`open release blocker: ${blocker.id}`);
  }
  if (!authorization?.approvedSourceCommit)
    reasons.push("owner-approved source commit is absent");
  if (!authorization || authorization.approvedVersion !== version)
    reasons.push("owner-approved version does not match candidate");
  if (authorization?.approvedBranch !== branch)
    reasons.push("owner-approved branch does not match current branch");
  const expectedPhrase = `publish:${version}:${head}`;
  if (environment.FUZIT_RELEASE_AUTHORIZATION !== expectedPhrase)
    reasons.push("explicit release authorization phrase is absent or invalid");
  for (const credential of requiredCredentials) {
    if (!environment[credential])
      reasons.push(`missing credential: ${credential}`);
  }
  if (dirtyPaths.length > 0) reasons.push("working tree is not clean");
  return {
    schemaVersion: 1,
    status: reasons.length === 0 ? "authorized" : "blocked",
    head,
    version,
    branch,
    requiredCredentials: [...requiredCredentials],
    reasons,
    publicationActionsPermitted: reasons.length === 0,
  };
}

export function materializeReleasePlan({ version, commit }) {
  return guardedReleasePlan.map((step) => ({
    ...step,
    arguments: step.arguments.map((value) =>
      value.replaceAll("{version}", version).replaceAll("{commit}", commit),
    ),
  }));
}

export function executeGuardedPlan({ decision, plan, execute }) {
  if (decision.status !== "authorized" || !decision.publicationActionsPermitted)
    throw new Error("guarded release is not authorized");
  const results = [];
  for (const step of plan) {
    const outcome = execute(step);
    results.push({
      id: step.id,
      phase: step.phase,
      exitCode: outcome.status ?? 1,
    });
    if (outcome.status !== 0) break;
  }
  return {
    status:
      results.length === plan.length &&
      results.every(({ exitCode }) => exitCode === 0)
        ? "complete"
        : "failed",
    results,
  };
}

function git(...arguments_) {
  const result = spawnSync("git", arguments_, {
    cwd: root,
    encoding: "utf8",
    shell: false,
  });
  if (result.status !== 0) throw new Error(result.stderr);
  return result.stdout.trim();
}

function execute(step) {
  const executable = step.command === "pnpm" ? process.execPath : step.command;
  const arguments_ =
    step.command === "pnpm"
      ? [process.env.npm_execpath, ...step.arguments]
      : step.arguments;
  const result = spawnSync(executable, arguments_, {
    cwd: root,
    encoding: "utf8",
    stdio: "inherit",
    shell: false,
    timeout: 30 * 60 * 1000,
  });
  return { status: result.status ?? 1 };
}

async function main() {
  const executeRequested = process.argv.includes("--execute");
  const state = JSON.parse(
    await readFile(resolve(root, "docs/release/release-state.json"), "utf8"),
  );
  const manifest = JSON.parse(
    await readFile(resolve(root, "package.json"), "utf8"),
  );
  const head = git("rev-parse", "HEAD");
  const version = manifest.version;
  const decision = evaluateReleaseAuthorization({
    state,
    environment: process.env,
    head,
    version,
    branch: git("branch", "--show-current"),
    dirtyPaths: git("status", "--porcelain", "--untracked-files=all")
      .split(/\r?\n/)
      .filter(Boolean),
  });
  if (!executeRequested || decision.status !== "authorized") {
    process.stdout.write(
      `${JSON.stringify({ gate: "release:guarded", executeRequested, decision, actionsExecuted: [] })}\n`,
    );
    process.exitCode = 1;
    return;
  }
  const result = executeGuardedPlan({
    decision,
    plan: materializeReleasePlan({ version, commit: head }),
    execute,
  });
  process.stdout.write(
    `${JSON.stringify({ gate: "release:guarded", decision, result })}\n`,
  );
  if (result.status !== "complete") process.exitCode = 1;
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  await main();
}

import { spawnSync } from "node:child_process";

import { describe, expect, it } from "vitest";

import {
  evaluateReleaseAuthorization,
  executeGuardedPlan,
  materializeReleasePlan,
} from "./guarded-release.mjs";

const head = "a".repeat(40);
const version = "1.0.0";
const branch = "release/v1.0.0";
const approval = {
  publicationAuthorized: true,
  releaseAuthorization: {
    approvedSourceCommit: head,
    approvedVersion: version,
    approvedBranch: branch,
  },
};
const credentials = {
  FUZIT_RELEASE_AUTHORIZATION: `publish:${version}:${head}`,
  NPM_TOKEN: "present",
  VSCE_PAT: "present",
  GITHUB_TOKEN: "present",
};

describe("guarded local release", () => {
  it("blocks normal sprint state before inspecting credentials", () => {
    const decision = evaluateReleaseAuthorization({
      state: { publicationAuthorized: false },
      environment: {},
      head,
      version,
      branch,
    });
    expect(decision.status).toBe("blocked");
    expect(decision.publicationActionsPermitted).toBe(false);
    expect(decision.reasons).toContain("publicationAuthorized is not true");
  });

  it("requires matching owner scope, all credentials, and a clean tree", () => {
    const decision = evaluateReleaseAuthorization({
      state: approval,
      environment: credentials,
      head,
      version,
      branch,
      dirtyPaths: ["owner-file.txt"],
    });
    expect(decision.status).toBe("blocked");
    expect(decision.reasons).toEqual(["working tree is not clean"]);
  });

  it("materializes a deterministic local plan with explicit mutation phases", () => {
    const first = materializeReleasePlan({ version, commit: head });
    expect(materializeReleasePlan({ version, commit: head })).toEqual(first);
    expect(first.map(({ phase }) => phase)).toEqual([
      "gate",
      "gate",
      "gate",
      "publish",
      "publish",
      "publish",
      "publish",
      "tag",
      "release",
    ]);
    expect(first.at(-2)?.arguments).toContain(`v${version}`);
    expect(first.at(-2)?.arguments).toContain(head);
  });

  it("cannot execute any step with a blocked decision", () => {
    let invoked = false;
    expect(() =>
      executeGuardedPlan({
        decision: { status: "blocked", publicationActionsPermitted: false },
        plan: materializeReleasePlan({ version, commit: head }),
        execute: () => {
          invoked = true;
          return { status: 0 };
        },
      }),
    ).toThrow("not authorized");
    expect(invoked).toBe(false);
  });

  it("normal CLI invocation is blocked with zero actions", () => {
    const result = spawnSync(
      process.execPath,
      ["scripts/guarded-release.mjs"],
      {
        encoding: "utf8",
        env: { ...process.env, FUZIT_RELEASE_AUTHORIZATION: "" },
      },
    );
    expect(result.status).toBe(1);
    expect(JSON.parse(result.stdout)).toMatchObject({
      gate: "release:guarded",
      executeRequested: false,
      actionsExecuted: [],
      decision: { status: "blocked", publicationActionsPermitted: false },
    });
  });
});

import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const patterns = [
  [
    "private-key",
    /-----BEGIN ([A-Z ]*PRIVATE KEY)-----[\s\S]{0,10000}?-----END \1-----/g,
  ],
  ["github-token", /\bgh[pousr]_[A-Za-z0-9]{36,}\b/g],
  ["aws-access-key", /\bAKIA[0-9A-Z]{16}\b/g],
  [
    "private-host",
    /https?:\/\/(?:localhost|127\.0\.0\.1|[^\s/]+\.(?:internal|corp|local))(?=[\s/:]|$)/gi,
  ],
];

const fingerprint = (value) =>
  createHash("sha256").update(value).digest("hex").slice(0, 16);

export const scanHistoryText = (text) => {
  const findings = [];
  for (const [category, pattern] of patterns) {
    for (const match of text.matchAll(pattern)) {
      findings.push({ category, fingerprint: fingerprint(match[0]) });
    }
  }
  return findings.sort(
    (a, b) =>
      a.category.localeCompare(b.category) ||
      a.fingerprint.localeCompare(b.fingerprint),
  );
};

const scanHistoryDiff = (history) => {
  const findings = [];
  for (const match of history.matchAll(
    /^diff --git a\/(.+?) b\/(.+?)\r?\n([\s\S]*?)(?=^diff --git |$(?![\s\S]))/gm,
  )) {
    for (const finding of scanHistoryText(match[3])) {
      findings.push({ ...finding, path: match[2] });
    }
  }
  return findings;
};

const git = (root, args, input) => {
  const result = spawnSync("git", args, {
    cwd: root,
    encoding: "utf8",
    input,
    maxBuffer: 256 * 1024 * 1024,
    shell: false,
  });
  if (result.status !== 0)
    throw new Error(`git ${args[0]} failed with exit ${result.status}`);
  return result.stdout;
};

export const auditHistory = (root = repositoryRoot) => {
  const head = git(root, ["rev-parse", "HEAD"]).trim();
  const commits = git(root, ["rev-list", "--all"])
    .trim()
    .split(/\r?\n/)
    .filter(Boolean);
  const history = git(root, [
    "log",
    "--all",
    "--format=commit:%H",
    "-p",
    "--no-ext-diff",
    "--text",
  ]);
  const findings = scanHistoryDiff(history);
  const objects = git(root, ["rev-list", "--objects", "--all"])
    .trim()
    .split(/\r?\n/)
    .filter(Boolean);
  const ids = objects.map((line) => line.split(" ", 1)[0]).join("\n");
  const sizes = git(
    root,
    ["cat-file", "--batch-check=%(objectname) %(objecttype) %(objectsize)"],
    `${ids}\n`,
  );
  const largeBlobs = sizes
    .trim()
    .split(/\r?\n/)
    .filter((line) => {
      const [, type, size] = line.split(" ");
      return type === "blob" && Number(size) > 5 * 1024 * 1024;
    }).length;
  const approvedFixturePaths = new Set([
    "packages/security/test/detectors.test.ts",
    "scripts/history-audit.test.mjs",
  ]);
  const approvedFixtures = findings.filter(
    ({ category, path }) =>
      category !== "private-host" && approvedFixturePaths.has(path),
  );
  const secretFindings = findings.filter(
    ({ category, path }) =>
      category !== "private-host" &&
      !(category !== "private-host" && approvedFixturePaths.has(path)),
  );
  if (secretFindings.length)
    throw new Error(
      `history audit found ${secretFindings.length} high-confidence secret finding(s)`,
    );
  return {
    schemaVersion: 1,
    tool: "fuzit-history-audit/1",
    head,
    commits: commits.length,
    highConfidenceSecrets: 0,
    approvedSecurityFixtureFindings: approvedFixtures.length,
    privateHostReferences: findings.filter(
      ({ category }) => category === "private-host",
    ).length,
    privateHostReviewPaths: [
      ...new Set(
        findings
          .filter(({ category }) => category === "private-host")
          .map(({ path }) => path),
      ),
    ].sort(),
    largeBlobs,
    fingerprints: [
      ...new Set(
        findings.map(
          ({ category, fingerprint: value }) => `${category}:${value}`,
        ),
      ),
    ].sort(),
  };
};

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  process.stdout.write(`${JSON.stringify(auditHistory())}\n`);
}

import { describe, expect, it } from "vitest";

import { scanHistoryText } from "./history-audit.mjs";

describe("full-history audit", () => {
  it("detects high-confidence credentials without retaining source content", () => {
    const source =
      "[REDACTED:private-key]\nAKIAABCDEFGHIJKLMNOP\n";
    const findings = scanHistoryText(source);
    expect(findings.map(({ category }) => category)).toEqual([
      "aws-access-key",
      "private-key",
    ]);
    expect(JSON.stringify(findings)).not.toContain("AKIAABCDEFGHIJKLMNOP");
    expect(JSON.stringify(findings)).not.toContain("PRIVATE KEY");
  });

  it("returns deterministic fingerprints for review-only private hosts", () => {
    const source =
      "+ endpoint=https://build.corp/path\n+ endpoint=https://build.corp/path\n";
    const first = scanHistoryText(source);
    expect(scanHistoryText(source)).toEqual(first);
    expect(first).toHaveLength(2);
    expect(first.every(({ category }) => category === "private-host")).toBe(
      true,
    );
  });
});

import { createRequire } from "node:module";
import { access, readFile, readdir, realpath } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const allowedLicenses = new Set([
  "Apache-2.0",
  "BSD-2-Clause",
  "BSD-3-Clause",
  "ISC",
  "MIT",
]);

const manifests = async (directory) => {
  const found = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const path = resolve(directory, entry.name);
    if (entry.isDirectory()) found.push(...(await manifests(path)));
    else if (entry.name === "package.json") found.push(path);
  }
  return found;
};

const dependencyManifest = async (requester, name) => {
  let current = dirname(createRequire(requester).resolve(name));
  for (;;) {
    const candidate = resolve(current, "package.json");
    try {
      await access(candidate);
      const manifest = JSON.parse(await readFile(candidate, "utf8"));
      if (manifest.name === name)
        return { manifest, path: await realpath(candidate) };
    } catch {
      // Continue upward until the dependency's own manifest is found.
    }
    const parent = dirname(current);
    if (parent === current)
      throw new Error(`cannot locate runtime manifest: ${name}`);
    current = parent;
  }
};

export const auditLicenses = async (root = repositoryRoot) => {
  const paths = [
    ...(await manifests(resolve(root, "apps"))),
    ...(await manifests(resolve(root, "packages"))),
  ].sort();
  const external = new Map();
  for (const path of paths) {
    const manifest = JSON.parse(await readFile(path, "utf8"));
    for (const [name, version] of Object.entries(
      manifest.dependencies ?? {},
    ).sort()) {
      if (String(version).startsWith("workspace:")) continue;
      const { manifest: dependency, path: packagePath } =
        await dependencyManifest(path, name);
      const license = dependency.license;
      if (typeof license !== "string" || !allowedLicenses.has(license)) {
        throw new Error(
          `unknown or blocked runtime license: ${name}@${dependency.version} (${String(license)})`,
        );
      }
      external.set(name, {
        name,
        version: dependency.version,
        license,
        status: "allowed",
        evidence: relative(root, packagePath).replaceAll("\\", "/"),
      });
    }
  }
  return {
    schemaVersion: 1,
    scope:
      "external runtime dependencies reachable from distributable workspaces",
    packages: [...external.values()].sort((a, b) =>
      a.name.localeCompare(b.name),
    ),
    findings: {
      blocked: 0,
      review: 0,
      unknown: 0,
      copyleft: 0,
      nativeOrWasm: 0,
      devOnlyExcluded: true,
    },
  };
};

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const actual = await auditLicenses();
  const reportPath = resolve(
    repositoryRoot,
    "docs/release/dependency-license-audit.json",
  );
  const expected = JSON.parse(await readFile(reportPath, "utf8"));
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error("dependency license audit report is stale or incomplete");
  }
  process.stdout.write(`${JSON.stringify(actual)}\n`);
}

import { mkdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { mkdtemp } from "node:fs/promises";

import { describe, expect, it } from "vitest";

import { auditLicenses } from "./license-audit.mjs";

describe("dependency license audit", () => {
  it("matches the committed deterministic report", async () => {
    const root = resolve(import.meta.dirname, "..");
    const [actual, expected] = await Promise.all([
      auditLicenses(root),
      import("../docs/release/dependency-license-audit.json", {
        with: { type: "json" },
      }).then((value) => value.default),
    ]);
    expect(actual).toEqual(expected);
  });

  it("fails closed on an unknown critical runtime license", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-license-audit-"));
    await mkdir(resolve(root, "apps/example/node_modules/unknown"), {
      recursive: true,
    });
    await mkdir(resolve(root, "packages"), { recursive: true });
    await writeFile(
      resolve(root, "apps/example/package.json"),
      JSON.stringify({ dependencies: { unknown: "1.0.0" } }),
    );
    await writeFile(
      resolve(root, "apps/example/node_modules/unknown/package.json"),
      JSON.stringify({ name: "unknown", version: "1.0.0" }),
    );
    await writeFile(
      resolve(root, "apps/example/node_modules/unknown/index.js"),
      "export {};\n",
    );
    await expect(auditLicenses(root)).rejects.toThrow(
      /unknown or blocked runtime license/,
    );
  });
});

import { spawn, spawnSync } from "node:child_process";
import {
  mkdtemp,
  mkdir,
  readFile,
  readdir,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { delimiter, join, resolve } from "node:path";
import { clearTimeout, setTimeout } from "node:timers";

const root = resolve(".");
const temporaryParent = process.env.FUZIT_PACKAGE_TEMP_PARENT ?? tmpdir();
await mkdir(temporaryParent, { recursive: true });
const temporary = await mkdtemp(join(temporaryParent, "fuzit-package-"));
const artifacts = join(temporary, "artifacts");
const installation = join(temporary, "install");

function run(command, arguments_, options = {}) {
  const executable = command === "pnpm" ? process.execPath : command;
  const safeArguments =
    command === "pnpm" ? [process.env.npm_execpath, ...arguments_] : arguments_;
  const result = spawnSync(executable, safeArguments, {
    cwd: options.cwd ?? root,
    encoding: "utf8",
    shell: false,
    env: options.env ?? process.env,
    input: options.input,
  });
  if (!(options.acceptedStatuses ?? [0]).includes(result.status)) {
    throw new Error(
      `${command} ${arguments_.join(" ")} failed:\n${result.stdout}\n${result.stderr}`,
    );
  }
  return result.stdout;
}

try {
  await mkdir(artifacts);
  await mkdir(installation);
  const packageDirectories = [
    "apps/cli",
    "apps/mcp-server",
    "packages/plugin-sdk",
  ];
  const packageNames = new Map();
  for (const directory of packageDirectories.sort()) {
    const manifest = JSON.parse(
      await readFile(join(root, directory, "package.json"), "utf8"),
    );
    run("pnpm", ["--dir", directory, "pack", "--pack-destination", artifacts]);
    packageNames.set(
      manifest.name,
      manifest.name.startsWith("@fuzit/")
        ? `fuzit-${manifest.name.split("/").at(-1)}-${manifest.version}.tgz`
        : `${manifest.name}-${manifest.version}.tgz`,
    );
  }
  const tarballs = (await readdir(artifacts))
    .filter((path) => path.endsWith(".tgz"))
    .map((path) => join(artifacts, path));
  if (tarballs.length !== packageDirectories.length)
    throw new Error("Not every public npm package produced a tarball.");
  const cliTarball = tarballs.find((path) =>
    /fuzit-cli-\d+\.\d+\.\d+\.tgz$/.test(path),
  );
  if (cliTarball === undefined) throw new Error("CLI tarball missing.");
  const contents = run("tar", ["-tf", cliTarball]);
  for (const required of [
    "package/bin/fuzit.mjs",
    "package/dist/bin.js",
    "package/package.json",
  ]) {
    if (!contents.includes(required))
      throw new Error(`CLI package content missing: ${required}`);
  }
  if (contents.includes("package/src/"))
    throw new Error("CLI tarball leaked workspace source.");
  const sdkTarball = tarballs.find((path) => /fuzit-plugin-sdk-/.test(path));
  if (sdkTarball === undefined) throw new Error("Plugin SDK tarball missing.");
  const sdkContents = run("tar", ["-tf", sdkTarball]);
  for (const forbidden of ["plugin-host", "testing", "node_modules", "src/"]) {
    if (sdkContents.includes(forbidden))
      throw new Error(`Plugin SDK package leaked ${forbidden}.`);
  }
  const privateWorkspaceNames = new Set([
    "@fuzit/analysis",
    "@fuzit/benchmark",
    "@fuzit/budgeting",
    "@fuzit/config",
    "@fuzit/core",
    "@fuzit/discovery",
    "@fuzit/git",
    "@fuzit/graph",
    "@fuzit/index",
    "@fuzit/plugin-host",
    "@fuzit/profiles",
    "@fuzit/provider-github",
    "@fuzit/renderer-core",
    "@fuzit/renderer-json",
    "@fuzit/renderer-markdown",
    "@fuzit/renderer-text",
    "@fuzit/renderer-xml",
    "@fuzit/scanner",
    "@fuzit/schemas",
    "@fuzit/security",
    "@fuzit/selection",
    "@fuzit/snapshots",
    "@fuzit/testing",
    "@fuzit/watcher",
  ]);
  for (const tarball of tarballs) {
    const packedManifest = JSON.parse(
      run("tar", ["-xOf", tarball, "package/package.json"]),
    );
    if (/"(?:workspace|file|link):/.test(JSON.stringify(packedManifest)))
      throw new Error(
        `Packed public package contains a local dependency reference: ${packedManifest.name}.`,
      );
    for (const [name, specification] of Object.entries({
      ...packedManifest.dependencies,
      ...packedManifest.optionalDependencies,
      ...packedManifest.peerDependencies,
    })) {
      if (privateWorkspaceNames.has(name))
        throw new Error(
          `Packed public package depends on private workspace ${name}.`,
        );
      if (/^(workspace|file|link):/.test(String(specification)))
        throw new Error(
          `Packed public package has local dependency ${name}@${specification}.`,
        );
    }
  }

  const publicDependencies = Object.fromEntries(
    [...packageNames].map(([name, tarball]) => [
      name,
      `file:${join(artifacts, tarball).replaceAll("\\", "/")}`,
    ]),
  );
  await writeFile(
    join(installation, "package.json"),
    JSON.stringify({
      private: true,
      dependencies: publicDependencies,
    }),
  );
  run("pnpm", ["install", "--offline"], { cwd: installation });
  const referencePlugin = join(installation, "reference-plugin");
  await mkdir(referencePlugin);
  await writeFile(
    join(referencePlugin, "plugin.ts"),
    `import { createPlugin, type PluginParserOutput } from "@fuzit/plugin-sdk";\n\nconst output: PluginParserOutput = { symbols: [] };\nexport default createPlugin({\n  manifest: {\n    schemaVersion: 1,\n    id: "com.example.reference",\n    name: "Reference Plugin",\n    version: "1.0.0",\n    protocol: "fuzit-plugin-v1",\n    fuzitVersion: "^1.0.0",\n    entryPoint: "dist/plugin.js",\n    capabilities: ["parser"],\n    permissions: {\n      shell: false,\n      persistence: false,\n      filesystem: { readPaths: ["src/"] },\n    },\n  },\n  handlers: { parser: () => output },\n});\n`,
  );
  await writeFile(
    join(referencePlugin, "tsconfig.json"),
    `${JSON.stringify({
      compilerOptions: {
        strict: true,
        noEmit: true,
        module: "NodeNext",
        moduleResolution: "NodeNext",
        target: "ES2022",
        skipLibCheck: true,
        types: [],
      },
