    const child = spawn(process.execPath, [installedMcp, fixture], {
      cwd: installation,
      env: environment,
      shell: false,
      stdio: ["pipe", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    let completed = false;
    const timeout = setTimeout(() => {
      child.kill();
      rejectMcp(new Error(`MCP clean-install startup timed out: ${stderr}`));
    }, 5_000);
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.stdout.on("data", (chunk) => {
      stdout += chunk;
      if (stdout.includes('"serverInfo"') && stdout.includes('"tools"')) {
        completed = true;
        clearTimeout(timeout);
        child.kill();
        resolveMcp(stdout);
      }
    });
    child.on("error", (error) => {
      clearTimeout(timeout);
      rejectMcp(error);
    });
    child.on("exit", (code) => {
      if (!completed) {
        clearTimeout(timeout);
        rejectMcp(
          new Error(
            `MCP clean-install startup exited with status ${String(code)}: ${stderr}`,
          ),
        );
      }
    });
    child.stdin.write(
      `${JSON.stringify({ jsonrpc: "2.0", id: 1, method: "initialize" })}\n` +
        `${JSON.stringify({ jsonrpc: "2.0", id: 2, method: "tools/list" })}\n`,
    );
  });
  if (!mcpOutput.includes('"serverInfo"') || !mcpOutput.includes('"tools"'))
    throw new Error(
      "MCP clean-install startup did not return capabilities and tools.",
    );
  run(
    process.execPath,
    [
      installedCli,
      "context",
      "--root",
      fixture,
      "--task",
      "authentication",
      "--profile",
      "bug-fix",
      "--budget-tokens",
      "1000",
      "--format",
      "markdown",
      "--output",
      join(installation, "context.md"),
    ],
    { cwd: installation, env: environment },
  );
  process.stdout.write(
    JSON.stringify({
      tarballs: tarballs.length,
      publicPackages: [...packageNames.keys()].sort(),
      packageContents: "audited",
      localInstall: "ok",
      isolation: "outside-monorepo",
      registryMode: "offline",
      privateWorkspacePackages: 0,
      globalBinShape: "ok",
      nativeDependencies: "none",
      nodeEngine: "validated",
      commands: [
        "--help",
        "--version",
        "doctor",
        "scan",
        "pack",
        "context",
        "watch --once",
        "graph stats",
        "snapshot create",
        "diff",
        "plugin validate",
        "plugin sdk compile",
        "plugin sdk internal export rejection",
        "mcp initialize",
        "mcp tools/list",
      ],
    }) + "\n",
  );
} finally {
  await rm(temporary, { recursive: true, force: true });
}

import { spawnSync } from "node:child_process";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = resolve(".");
const temporary = await mkdtemp(join(tmpdir(), "fuzit-privacy-"));
const protectedValue = ["PRIVATE", "FIXTURE", "VALUE", "123456789"].join("_");
function run(command, arguments_, options = {}) {
  const executable =
    command === "pnpm" || command === "node" ? process.execPath : command;
  const safeArguments =
    command === "pnpm" ? [process.env.npm_execpath, ...arguments_] : arguments_;
  const result = spawnSync(executable, safeArguments, {
    cwd: options.cwd ?? root,
    encoding: "utf8",
    shell: false,
  });
  if (!(options.acceptedStatuses ?? [0]).includes(result.status))
    throw new Error(`${command} failed: ${result.stderr}`);
  const output = `${result.stdout}${result.stderr}`;
  if (output.includes(protectedValue) || output.includes(temporary))
    throw new Error(
      "Privacy audit found a protected value or private absolute path.",
    );
  return output;
}
try {
  await writeFile(join(temporary, "secret.txt"), `token=${protectedValue}\n`);
  run("pnpm", [
    "exec",
    "vitest",
    "run",
    "--config",
    "vitest.workspace.ts",
    "tests/security/network",
  ]);
  run("node", [join(root, "apps/cli/dist/bin.js"), "--help"], {
    cwd: temporary,
  });
  run(
    "node",
    [join(root, "apps/cli/dist/bin.js"), "--json", "profile", "list"],
    { cwd: temporary },
  );
  run("node", [join(root, "apps/cli/dist/bin.js"), "unknown"], {
    cwd: temporary,
    acceptedStatuses: [2],
  });
  const remote = run("git", ["config", "--get", "remote.origin.url"], {
    cwd: root,
    acceptedStatuses: [0, 1],
  });
  if (/https?:\/\/[^/\s:@]+:[^/\s@]+@/u.test(remote))
    throw new Error("Credential-bearing Git remote URL detected.");
  process.stdout.write(
    `${JSON.stringify({ network: "denied", debugJsonCrashOutputs: "clean", gitRemoteCredentials: "absent" })}\n`,
  );
} finally {
  await rm(temporary, { recursive: true, force: true });
}

import { execFileSync } from "node:child_process";
import { readFile, readdir } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

export function validateReleasePolicy(input) {
  const errors = [];
  if (input.changesets.length === 0) errors.push("missing changeset");
  if (new Set(input.versions).size !== 1) errors.push("version mismatch");
  if (!input.changelog.includes(input.versions[0] ?? ""))
    errors.push("changelog version missing");
  if (
    !input.schemaPolicy.includes("rebuild") &&
    !input.schemaPolicy.includes("migration")
  )
    errors.push("schema bump lacks migration/rebuild note");
  if (input.unexpectedDirty.length > 0)
    errors.push(`unexpected dirty tree: ${input.unexpectedDirty.join(", ")}`);
  return errors;
}

export function findUnexpectedDirty(dirty, changed, preserved = []) {
  const allowed = new Set([...changed, ...preserved]);
  return dirty.filter((path) => !allowed.has(path));
}

export async function checkRepository(root = resolve(".")) {
  const packagePaths = [
    "apps/cli",
    ...(await readdir(resolve(root, "packages"), { withFileTypes: true }))
      .filter((entry) => entry.isDirectory() && entry.name !== "renderers")
      .map((entry) => `packages/${entry.name}`),
    ...(
      await readdir(resolve(root, "packages/renderers"), {
        withFileTypes: true,
      })
    )
      .filter((entry) => entry.isDirectory())
      .map((entry) => `packages/renderers/${entry.name}`),
  ];
  const versions = await Promise.all(
    packagePaths.map(
      async (path) =>
        JSON.parse(await readFile(resolve(root, path, "package.json"), "utf8"))
          .version,
    ),
  );
  const changesets = (await readdir(resolve(root, ".changeset"))).filter(
    (path) => path.endsWith(".md"),
  );
  const state = JSON.parse(
    await readFile(resolve(root, "docs/release/release-state.json"), "utf8"),
  );
  const preserved = (process.env.FUZIT_RELEASE_PRESERVED_PATHS ?? "")
    .split(";")
    .filter(Boolean);
  const dirty = execFileSync(
    "git",
    [
      "-c",
      "core.quotepath=false",
      "status",
      "--porcelain",
      "--untracked-files=all",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .split(/\r?\n/u)
    .filter(Boolean)
    .map((line) => line.slice(3).replaceAll("\\", "/"));
  const errors = validateReleasePolicy({
    changesets,
    versions,
    changelog: await readFile(resolve(root, "CHANGELOG.md"), "utf8"),
    schemaPolicy: await readFile(
      resolve(root, "docs/release/schema-compatibility.md"),
      "utf8",
    ),
    unexpectedDirty: findUnexpectedDirty(dirty, [], preserved),
  });
  if (errors.length > 0) throw new Error(errors.join("\n"));
  return {
    versions: [...new Set(versions)],
    changesets: changesets.length,
    dirtyPaths: dirty.length,
    schemas: state.persistentSchemaVersions,
  };
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  process.stdout.write(`${JSON.stringify(await checkRepository())}\n`);
}

import { describe, expect, it } from "vitest";
