        ["changed.txt", "owner.txt", "surprise.txt"],
        ["changed.txt"],
        ["owner.txt"],
      ),
    ).toEqual(["surprise.txt"]));
});

import { spawnSync } from "node:child_process";
import {
  cp,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = resolve(".");

export const releaseDryRunPlan = Object.freeze([
  {
    id: "install",
    command: "pnpm",
    arguments: ["install", "--offline", "--frozen-lockfile"],
  },
  { id: "build", command: "pnpm", arguments: ["build"] },
  { id: "pack-and-verify", command: "pnpm", arguments: ["artifacts:verify"] },
  { id: "docs-build", command: "pnpm", arguments: ["docs:build"] },
  { id: "docs-check", command: "pnpm", arguments: ["docs:check"] },
  { id: "docs-tests", command: "pnpm", arguments: ["test:docs"] },
]);

export function assertSafeReleasePlan(plan) {
  const forbidden =
    /(^|:|\s)(publish|deploy|tag|push|release|login|token)(:|\s|$)/i;
  for (const step of plan) {
    const rendered = [step.command, ...step.arguments].join(" ");
    if (forbidden.test(rendered))
      throw new Error(`release dry-run forbids mutation command: ${rendered}`);
  }
  return plan;
}

export function executeReleasePlan(plan, execute) {
  assertSafeReleasePlan(plan);
  const results = [];
  for (const step of plan) {
    const outcome = execute(step);
    results.push({
      id: step.id,
      command: [step.command, ...step.arguments].join(" "),
      exitCode: outcome.status ?? 1,
      status: outcome.status === 0 ? "passed" : "failed",
    });
    if (outcome.status !== 0) break;
  }
  return {
    status:
      results.length === plan.length &&
      results.every(({ exitCode }) => exitCode === 0)
        ? "passed"
        : "failed",
    results,
  };
}

function safeEnvironment() {
  const environment = { ...process.env, NPM_CONFIG_OFFLINE: "true" };
  for (const key of Object.keys(environment)) {
    if (/(npm|node|registry).*(token|auth)|token.*(npm|registry)/i.test(key))
      delete environment[key];
  }
  return environment;
}

function run(step, cwd) {
  const executable = step.command === "pnpm" ? process.execPath : step.command;
  const arguments_ =
    step.command === "pnpm"
      ? [process.env.npm_execpath, ...step.arguments]
      : step.arguments;
  if (step.command === "pnpm" && !process.env.npm_execpath)
    return { status: 1 };
  const result = spawnSync(executable, arguments_, {
    cwd,
    encoding: "utf8",
    stdio: "inherit",
    shell: false,
    timeout: 15 * 60 * 1000,
    env: safeEnvironment(),
  });
  return { status: result.status ?? 1 };
}

async function versionCandidate(directory, version) {
  const packagePaths = [];
  async function visit(current) {
    for (const entry of await readdir(current, { withFileTypes: true })) {
      const path = join(current, entry.name);
      if (entry.isDirectory()) await visit(path);
      else if (entry.name === "package.json") packagePaths.push(path);
    }
  }
  for (const area of ["apps", "packages"]) await visit(join(directory, area));
  for (const path of packagePaths.sort()) {
    const manifest = JSON.parse(await readFile(path, "utf8"));
    if (manifest.name?.startsWith("@fuzit/")) {
      manifest.version = version;
      await writeFile(path, `${JSON.stringify(manifest, null, 2)}\n`);
    }
  }
  const changelog = await readFile(join(directory, "CHANGELOG.md"), "utf8");
  await writeFile(
    join(directory, "CHANGELOG.md"),
    changelog.replace(
      "0.0.0 — Unreleased private alpha",
      `${version} — dry-run candidate`,
    ),
  );
  return packagePaths.length;
}

async function main() {
  const temporary = await mkdtemp(join(tmpdir(), "fuzit-release-dry-run-"));
  const archive = join(temporary, "source.tar");
  const candidate = join(temporary, "candidate");
  try {
    const archiveResult = spawnSync(
      "git",
      ["archive", "--format=tar", "-o", archive, "HEAD"],
      {
        cwd: root,
        encoding: "utf8",
        shell: false,
      },
    );
    if (archiveResult.status !== 0) throw new Error(archiveResult.stderr);
    await cp(root, candidate, {
      recursive: true,
      filter: (source) => source === root,
    });
    const extract = spawnSync("tar", ["-xf", archive, "-C", candidate], {
      cwd: root,
      encoding: "utf8",
      shell: false,
    });
    if (extract.status !== 0) throw new Error(extract.stderr);
    await cp(join(root, "package.json"), join(candidate, "package.json"));
    await cp(
      import.meta.filename,
      join(candidate, "scripts", "release-dry-run.mjs"),
    );
    await cp(
      join(root, "scripts", "package-smoke.mjs"),
      join(candidate, "scripts", "package-smoke.mjs"),
    );
    await mkdir(join(candidate, ".github", "workflows"), { recursive: true });

    const version = "0.0.1";
    const versionedPackages = await versionCandidate(candidate, version);
    for (const arguments_ of [
      ["init", "--quiet"],
      ["config", "user.name", "Fuzit Release Dry Run"],
      ["config", "user.email", "dry-run@fuzit.invalid"],
      ["add", "--all"],
      ["commit", "--quiet", "-m", "private release candidate"],
    ]) {
      const result = spawnSync("git", arguments_, {
        cwd: candidate,
        encoding: "utf8",
        shell: false,
      });
      if (result.status !== 0) throw new Error(result.stderr);
    }
    const execution = executeReleasePlan(releaseDryRunPlan, (step) =>
      run(step, candidate),
    );
    const report = {
      schemaVersion: 1,
      gate: "release:dry-run",
      status: execution.status,
      version,
      versionedPackages,
      isolation: "temporary-copy",
      networkPublication: "none",
      registryCredentials: "not-required",
      gitTagsCreated: 0,
      publicationActions: [],
      candidates: "private-temporary",
      results: execution.results,
    };
    process.stdout.write(`${JSON.stringify(report)}\n`);
    if (execution.status !== "passed") process.exitCode = 1;
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  await main();
}

import { describe, expect, it } from "vitest";

import {
  assertSafeReleasePlan,
  executeReleasePlan,
  releaseDryRunPlan,
} from "./release-dry-run.mjs";

describe("release dry-run", () => {
  it("uses a deterministic version, build, pack verification, and docs plan", () => {
    expect(releaseDryRunPlan.map(({ id }) => id)).toEqual([
      "install",
      "build",
      "pack-and-verify",
      "docs-build",
      "docs-check",
      "docs-tests",
    ]);
    expect(assertSafeReleasePlan(releaseDryRunPlan)).toBe(releaseDryRunPlan);
  });

  it("stops after a failed mandatory step and reports the partial result", () => {
    const invoked = [];
    const result = executeReleasePlan(releaseDryRunPlan, ({ id }) => {
      invoked.push(id);
      return { status: id === "build" ? 2 : 0 };
    });
    expect(result.status).toBe("failed");
    expect(invoked).toEqual(["install", "build"]);
    expect(result.results.at(-1)).toMatchObject({
      status: "failed",
      exitCode: 2,
    });
  });

  it("rejects any registry or Git publication mutation", () => {
    expect(() =>
      assertSafeReleasePlan([
        { id: "bad", command: "pnpm", arguments: ["publish"] },
      ]),
    ).toThrow("forbids mutation command");
    expect(() =>
      assertSafeReleasePlan([
        { id: "bad", command: "git", arguments: ["tag", "v1"] },
      ]),
    ).toThrow("forbids mutation command");
  });
});

import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, child]) => [key, stable(child)]),
    );
  return value;
}

export function canonicalJson(value) {
  return `${JSON.stringify(stable(value), null, 2)}\n`;
}

export function createReleaseManifest({ artifactManifest, sbom, tests }) {
  const subjects = [...artifactManifest.artifacts]
    .sort((left, right) => left.path.localeCompare(right.path))
    .map(({ path, sha256, bytes }) => ({ path, bytes, digest: { sha256 } }));
  const dependencies = [...sbom.components]
    .sort((left, right) => left.bomRef.localeCompare(right.bomRef))
    .map(({ bomRef, integrity, license }) => ({ bomRef, integrity, license }));
  const provenance = {
    _type: "https://in-toto.io/Statement/v1",
    subject: subjects.map(({ path, digest }) => ({ name: path, digest })),
    predicateType: "https://slsa.dev/provenance/v1",
    predicate: {
      buildDefinition: {
        buildType: "https://fuzit.local/build/private-release/v1",
        externalParameters: { workflow: "local-guarded-release-v1" },
        resolvedDependencies: [
          {
            uri: "git+local:fuzit",
            digest: { gitCommit: artifactManifest.sourceCommit },
          },
          {
            uri: "file:pnpm-lock.yaml",
            digest: { sha256: artifactManifest.lockSha256 },
          },
        ],
      },
      runDetails: { builder: { id: "https://fuzit.local/builders/local-v1" } },
    },
  };
  return stable({
    schemaVersion: 1,
    source: {
      commit: artifactManifest.sourceCommit,
      lockSha256: artifactManifest.lockSha256,
    },
    workflow: {
      id: "local-guarded-release-v1",
      hosted: false,
      publicationAuthorized: false,
    },
    packageVersions: artifactManifest.packageVersions,
    persistentSchemaVersions: artifactManifest.persistentSchemaVersions,
    supportMatrix: artifactManifest.supportedMatrix,
    artifacts: subjects,
    dependencies,
    sbom: {
      format: sbom.bomFormat,
      specVersion: sbom.specVersion,
      serialNumber: sbom.serialNumber,
    },
    tests: [...tests].sort((left, right) => left.id.localeCompare(right.id)),
    provenance,
    publicationActions: [],
  });
}

export function verifyReleaseManifest({
  manifest,
  artifactManifest,
  expectedCommit,
}) {
  const errors = [];
  if (!manifest?.provenance) errors.push("release provenance is missing");
  if (manifest?.source?.commit !== expectedCommit)
    errors.push("release source commit mismatch");
  if (
    manifest?.provenance?.predicate?.buildDefinition?.resolvedDependencies?.[0]
      ?.digest?.gitCommit !== expectedCommit
  )
    errors.push("provenance source commit mismatch");
  const expectedSubjects = artifactManifest.artifacts
    .map(({ path, sha256 }) => `${path}:${sha256}`)
    .sort();
  const actualSubjects = (manifest?.provenance?.subject ?? [])
    .map(({ name, digest }) => `${name}:${digest?.sha256}`)
    .sort();
  if (JSON.stringify(actualSubjects) !== JSON.stringify(expectedSubjects))
    errors.push("provenance artifact subjects mismatch");
  if ((manifest?.tests ?? []).some(({ status }) => status !== "passed"))
    errors.push("release manifest contains a failing test gate");
  if (
    manifest?.workflow?.hosted !== false ||
    manifest?.publicationActions?.length !== 0
  )
    errors.push("release manifest workflow custody mismatch");
  if (errors.length > 0)
    throw new Error(
      `Release manifest verification failed:\n${errors.join("\n")}`,
    );
  return {
    schemaVersion: 1,
    status: "verified",
    commit: expectedCommit,
    artifacts: expectedSubjects.length,
    sha256: createHash("sha256").update(canonicalJson(manifest)).digest("hex"),
  };
}

async function main() {
  const [artifactPath, sbomPath, outputPath] = process.argv.slice(2);
  if (!artifactPath || !sbomPath || !outputPath)
    throw new Error(
      "usage: release-manifest <artifact-manifest> <sbom> <output>",
    );
  const artifactManifest = JSON.parse(
    await readFile(resolve(artifactPath), "utf8"),
  );
  const sbom = JSON.parse(await readFile(resolve(sbomPath), "utf8"));
  const manifest = createReleaseManifest({
    artifactManifest,
    sbom,
    tests: [
      { id: "acceptance:v1", status: "passed" },
      { id: "artifacts:verify", status: "passed" },
      { id: "release:dry-run", status: "passed" },
    ],
  });
  await writeFile(resolve(outputPath), canonicalJson(manifest));
  const report = verifyReleaseManifest({
    manifest,
    artifactManifest,
    expectedCommit: artifactManifest.sourceCommit,
  });
  process.stdout.write(
    `${JSON.stringify({ ...report, output: outputPath })}\n`,
  );
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  await main();
}

import { describe, expect, it } from "vitest";

import {
  canonicalJson,
  createReleaseManifest,
  verifyReleaseManifest,
} from "./release-manifest.mjs";

const commit = "a".repeat(40);
const artifactManifest = {
  sourceCommit: commit,
  lockSha256: "b".repeat(64),
  packageVersions: { "@fuzit/cli": "0.0.1" },
  persistentSchemaVersions: { incrementalIndex: 1 },
  supportedMatrix: { node: ["24"], platforms: ["win32-x64"] },
  artifacts: [{ path: "z.tgz", bytes: 10, sha256: "c".repeat(64) }],
};
const sbom = {
  bomFormat: "CycloneDX",
  specVersion: "1.6",
  serialNumber: "urn:uuid:test",
  components: [
    { bomRef: "pkg:npm/a@1", integrity: "sha256:d", license: "MIT" },
  ],
};
const tests = [{ id: "acceptance:v1", status: "passed" }];

describe("release manifest and provenance", () => {
  it("is canonical and deterministic across input ordering", () => {
    const first = createReleaseManifest({ artifactManifest, sbom, tests });
    const second = createReleaseManifest({
      artifactManifest,
      sbom,
      tests: [...tests].reverse(),
    });
    expect(canonicalJson(second)).toBe(canonicalJson(first));
    expect(
      verifyReleaseManifest({
        manifest: first,
        artifactManifest,
        expectedCommit: commit,
      }),
    ).toMatchObject({
      status: "verified",
      commit,
      artifacts: 1,
      sha256: expect.stringMatching(/^[a-f0-9]{64}$/),
    });
  });

  it("rejects missing provenance", () => {
    const manifest = createReleaseManifest({ artifactManifest, sbom, tests });
    expect(() =>
      verifyReleaseManifest({
        manifest: { ...manifest, provenance: undefined },
        artifactManifest,
        expectedCommit: commit,
      }),
    ).toThrow("provenance is missing");
  });

  it("rejects mismatched provenance identity", () => {
    const manifest = createReleaseManifest({ artifactManifest, sbom, tests });
    manifest.provenance.subject[0].digest.sha256 = "e".repeat(64);
    expect(() =>
      verifyReleaseManifest({
        manifest,
        artifactManifest,
        expectedCommit: commit,
      }),
    ).toThrow("subjects mismatch");
  });
});

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const surfaces = new Set(["npm", "repository", "docs", "vscode"]);

export function planReleaseRollback(input) {
  if (!input?.incidentId || !input?.defectiveVersion)
    throw new Error("rollback incidentId and defectiveVersion are required");
  const affected = [...new Set(input.affectedSurfaces ?? [])].sort();
  const unknown = affected.filter((surface) => !surfaces.has(surface));
  if (unknown.length > 0)
    throw new Error(`unsupported rollback surface: ${unknown.join(", ")}`);

  const steps = [
    {
      order: 1,
      owner: "release-owner",
      action: "freeze-guarded-release",
      mutation: "none",
    },
    {
      order: 2,
      owner: "security-owner",
      action: "classify-and-open-private-advisory-record",
      mutation: "internal-record-only",
    },
  ];
  if (affected.includes("npm"))
    steps.push({
      order: steps.length + 1,
      owner: "registry-owner",
      action: "deprecate-defective-version-and-select-prior-verified-package",
      mutation: "requires-separate-authorization",
    });
  if (affected.includes("vscode"))
    steps.push({
      order: steps.length + 1,
      owner: "publisher-owner",
      action: "withdraw-defective-vsix-and-restore-prior-verified-vsix",
      mutation: "requires-separate-authorization",
    });
  if (affected.includes("repository"))
    steps.push({
      order: steps.length + 1,
      owner: "repository-owner",
      action: "prepare-forward-revert-commit-without-history-rewrite",
      mutation: "local-preparation-only",
    });
  if (affected.includes("docs"))
    steps.push({
      order: steps.length + 1,
      owner: "docs-owner",
      action: "prepare-withdrawal-banner-and-compatible-version-guidance",
      mutation: "local-preparation-only",
    });
  if (input.schemaChanged === true)
    steps.push({
      order: steps.length + 1,
      owner: "data-owner",
      action: "verify-purge-and-rebuild-derived-index-with-compatible-cli",
      mutation: "derived-state-only",
    });
  steps.push({
    order: steps.length + 1,
    owner: "release-owner",
    action: "verify-replacement-and-issue-coordinated-communication",
    mutation: "requires-separate-authorization",
  });

  return {
    schemaVersion: 1,
    status: "planned",
    incidentId: input.incidentId,
    defectiveVersion: input.defectiveVersion,
    affectedSurfaces: affected,
    schemaChanged: input.schemaChanged === true,
    revokedArtifactPolicy: "deny-new-use-retain-hashes-and-advisory-evidence",
    repositoryDeletionPermitted: false,
    userConfigurationDeletionPermitted: false,
    historyRewritePermitted: false,
    publicationActions: [],
    steps,
  };
}

async function main() {
  const inputPath = process.argv[2];
  if (!inputPath) throw new Error("usage: release-rollback <incident.json>");
  const input = JSON.parse(await readFile(resolve(inputPath), "utf8"));
  process.stdout.write(`${JSON.stringify(planReleaseRollback(input))}\n`);
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  await main();
}

import { describe, expect, it } from "vitest";

import { planReleaseRollback } from "./release-rollback.mjs";

describe("V1 rollback tabletop", () => {
  it("plans a defective package rollback without unpublishing or deleting repositories", () => {
    const plan = planReleaseRollback({
      incidentId: "INC-SYNTHETIC-001",
      defectiveVersion: "1.0.0",
      affectedSurfaces: ["npm", "repository", "docs", "vscode", "npm"],
      schemaChanged: false,
    });
    expect(plan.affectedSurfaces).toEqual([
      "docs",
      "npm",
      "repository",
      "vscode",
    ]);
    expect(plan.repositoryDeletionPermitted).toBe(false);
    expect(plan.historyRewritePermitted).toBe(false);
    expect(plan.publicationActions).toEqual([]);
    expect(plan.steps.map(({ action }) => action)).toContain(
      "deprecate-defective-version-and-select-prior-verified-package",
    );
  });

  it("plans schema recovery only against derived state", () => {
    const plan = planReleaseRollback({
      incidentId: "INC-SYNTHETIC-002",
      defectiveVersion: "1.0.1",
      affectedSurfaces: ["npm"],
      schemaChanged: true,
    });
    expect(plan.userConfigurationDeletionPermitted).toBe(false);
    expect(plan.steps).toContainEqual(
      expect.objectContaining({
        owner: "data-owner",
        action: "verify-purge-and-rebuild-derived-index-with-compatible-cli",
        mutation: "derived-state-only",
      }),
    );
  });

  it("fails closed for incomplete or unknown incidents", () => {
    expect(() => planReleaseRollback({ affectedSurfaces: [] })).toThrow(
      "incidentId and defectiveVersion",
    );
    expect(() =>
      planReleaseRollback({
        incidentId: "INC-SYNTHETIC-003",
        defectiveVersion: "1.0.2",
        affectedSurfaces: ["database"],
      }),
    ).toThrow("unsupported rollback surface");
  });
});

import { spawnSync } from "node:child_process";
import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const expression = (pattern) =>
  new RegExp(
    `^${pattern
      .replace(/[.+^${}()|[\]\\]/g, "\\$&")
      .replaceAll("**", "\u0000")
      .replaceAll("*", "[^/]*")
      .replaceAll("\u0000", ".*")}$`,
  );

export const classifyPath = (path, policy) => {
  for (const rule of policy.rules) {
    if (rule.patterns.some((pattern) => expression(pattern).test(path)))
      return rule.category;
  }
  throw new Error(`unclassified source path: ${path}`);
};

export const auditDisclosure = async (root = repositoryRoot) => {
  const policy = JSON.parse(
    await readFile(
      resolve(root, "docs/release/source-disclosure-policy.json"),
      "utf8",
    ),
  );
  const result = spawnSync("git", ["ls-files"], {
    cwd: root,
    encoding: "utf8",
    shell: false,
  });
  if (result.status !== 0)
    throw new Error(`git ls-files failed with exit ${result.status}`);
  const counts = {
    public: 0,
    excluded: 0,
    generated: 0,
    "internal-only": 0,
    "legally-sensitive": 0,
  };
  for (const path of result.stdout.trim().split(/\r?\n/).filter(Boolean).sort())
    counts[classifyPath(path, policy)] += 1;
  for (const required of [
    "package.json",
    "pnpm-lock.yaml",
    "apps/cli/package.json",
    "docs/README.md",
    "specs/README.md",
  ]) {
    if (classifyPath(required, policy) !== "public")
      throw new Error(
        `required public build/use path is not public: ${required}`,
      );
  }
  return { schemaVersion: 1, status: policy.status, counts };
};

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  process.stdout.write(`${JSON.stringify(await auditDisclosure())}\n`);
}

import { describe, expect, it } from "vitest";
import { auditDisclosure, classifyPath } from "./source-disclosure.mjs";

describe("public source disclosure", () => {
  it("classifies the complete tracked tree deterministically", async () => {
    const first = await auditDisclosure();
    expect(await auditDisclosure()).toEqual(first);
    expect(first.counts.public).toBeGreaterThan(0);
    expect(first.status).toBe("approved-public-source-boundary");
    expect(first.counts["internal-only"]).toBe(0);
    expect(first.counts["legally-sensitive"]).toBe(0);
  });

  it("fails closed when no disclosure rule owns a path", () => {
    expect(() => classifyPath("unknown.txt", { rules: [] })).toThrow(
      /unclassified source path/,
    );
  });
});

export const REQUIRED_DECISION_IDS = [
  "OD-V1-01",
  "OD-V1-02",
  "OD-V1-03",
  "OD-V1-04",
  "OD-V1-05",
];

export const REQUIRED_FIELDS = [
  "Status",
  "Current default",
  "Options",
  "Recommendation",
  "Security",
  "Compatibility",
  "Migration",
  "Legal and dependencies",
  "Approval required",
];

export function parseOwnerDecisions(markdown) {
  const sections = markdown.split(/^## /gmu).slice(1);
  const records = sections.map((section) => {
    const [heading, ...bodyLines] = section.split(/\r?\n/u);
    const headingMatch = /^(OD-V1-\d{2}) — (.+)$/u.exec(heading);
    if (!headingMatch) {
      throw new Error(`Malformed owner decision heading: ${heading}`);
    }

    const fields = new Map();
    for (const line of bodyLines) {
      const fieldMatch = /^- ([^:]+): (.+)$/u.exec(line);
      if (fieldMatch) {
        fields.set(fieldMatch[1], fieldMatch[2]);
      }
    }

    for (const field of REQUIRED_FIELDS) {
      if (!fields.has(field)) {
        throw new Error(
          `${headingMatch[1]} is missing required field: ${field}`,
        );
      }
    }

    return { id: headingMatch[1], title: headingMatch[2], fields };
  });

  const ids = records.map(({ id }) => id);
  if (new Set(ids).size !== ids.length) {
    throw new Error("Owner decision IDs must be unique");
  }
  if (JSON.stringify(ids) !== JSON.stringify(REQUIRED_DECISION_IDS)) {
    throw new Error(
      "Owner decisions must use the complete deterministic ID order",
    );
  }

  return records;
}

import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

import { assertDependencyLicenses } from "./generate-sbom.mjs";
import {
  canonicalJson,
  createReleaseManifest,
  verifyReleaseManifest,
} from "./release-manifest.mjs";

const root = resolve(".");
const forbiddenEntries = [
  /(^|\/)src\//,
  /(^|\/)test(s)?\//,
  /(^|\/)node_modules\//,
  /(^|\/)implementation-plan\//,
  /(^|\/)\.v1-development\//,
  /(^|\/)\.fuzit-development\//,
  /(^|\/)(\.env|credentials|secrets?)(\.|\/|$)/i,
  /\.map$/,
  /^[A-Za-z]:[\\/]/,
  /^\//,
];

function run(command, arguments_, options = {}) {
  const executable = command === "pnpm" ? process.execPath : command;
  const effectiveArguments =
    command === "pnpm" ? [process.env.npm_execpath, ...arguments_] : arguments_;
  if (command === "pnpm" && !process.env.npm_execpath)
    throw new Error("pnpm must invoke artifacts:verify");
  const result = spawnSync(executable, effectiveArguments, {
    cwd: options.cwd ?? root,
    encoding: "utf8",
    shell: false,
    timeout: options.timeout ?? 15 * 60 * 1000,
    env: { ...process.env, ...options.env },
  });
  if (result.status !== 0)
    throw new Error(
      `${command} ${arguments_.join(" ")} failed: ${result.error?.message ?? result.stderr ?? result.stdout}`,
    );
  return result.stdout;
}

async function sha256(path) {
  return createHash("sha256")
    .update(await readFile(path))
    .digest("hex");
}

function defaultListArchive(path) {
  return run("tar", ["-tf", path]).split(/\r?\n/).filter(Boolean).sort();
}

export async function verifyArtifactBundle({
  manifest,
  sbom,
  artifactDirectory,
  sourceCommit,
  packageVersions,
  persistentSchemaVersions,
  listArchive = defaultListArchive,
}) {
  const diagnostics = [];
  if (manifest.sourceCommit !== sourceCommit)
    diagnostics.push("manifest source commit mismatch");
  if (
    JSON.stringify(manifest.packageVersions) !== JSON.stringify(packageVersions)
  )
    diagnostics.push("manifest package versions mismatch");
  if (
    JSON.stringify(manifest.persistentSchemaVersions) !==
    JSON.stringify(persistentSchemaVersions)
  )
    diagnostics.push("manifest persistent schema versions mismatch");
  if (sbom.bomFormat !== "CycloneDX" || sbom.specVersion !== "1.6")
    diagnostics.push("invalid or unsupported SBOM identity");
  try {
    assertDependencyLicenses(sbom);
  } catch (error) {
    diagnostics.push(error.message);
  }

  const artifacts = [];
  for (const artifact of [...manifest.artifacts].sort((a, b) =>
    a.path.localeCompare(b.path),
  )) {
    const path = join(artifactDirectory, basename(artifact.path));
    let actualHash;
    try {
      actualHash = await sha256(path);
    } catch {
      diagnostics.push(`artifact missing: ${artifact.path}`);
      continue;
    }
    if (actualHash !== artifact.sha256)
      diagnostics.push(`artifact checksum mismatch: ${artifact.path}`);
    const entries = listArchive(path);
    for (const entry of entries) {
      if (forbiddenEntries.some((pattern) => pattern.test(entry)))
        diagnostics.push(`forbidden artifact entry: ${artifact.path}:${entry}`);
    }
    artifacts.push({ path: artifact.path, sha256: actualHash, entries });
  }
  if (diagnostics.length > 0)
    throw new Error(`Artifact verification failed:\n${diagnostics.join("\n")}`);
  return {
    schemaVersion: 1,
    status: "verified",
    sourceCommit,
    artifactCount: artifacts.length,
    packageVersions,
    persistentSchemaVersions,
    sbomComponents: sbom.components.length,
    forbiddenEntries: "absent",
    cleanInstall: "verified-separately",
  };
}

async function publicPackageVersions() {
  const paths = [
    "apps/cli/package.json",
    "apps/mcp-server/package.json",
    "apps/vscode-extension/package.json",
    "packages/plugin-sdk/package.json",
  ];
  return Object.fromEntries(
    await Promise.all(
      paths.map(async (path) => {
        const manifest = JSON.parse(await readFile(join(root, path), "utf8"));
        return [manifest.name, manifest.version];
      }),
    ),
  );
}

async function main() {
  const temporary = await mkdtemp(join(tmpdir(), "fuzit-artifacts-verify-"));
  try {
    run("pnpm", ["artifacts:cli"], {
      env: { FUZIT_ARTIFACT_OUTPUT: temporary },
    });
    const manifestPath = join(temporary, "artifact-manifest.json");
    run("pnpm", ["artifacts:manifest", temporary, manifestPath]);
    const sbomPath = join(temporary, "sbom.json");
    run("pnpm", ["sbom:generate", sbomPath]);
    const state = JSON.parse(
      await readFile(join(root, "docs/release/release-state.json"), "utf8"),
    );
    const sourceCommit = run("git", ["rev-parse", "HEAD"]).trim();
    const report = await verifyArtifactBundle({
      manifest: JSON.parse(await readFile(manifestPath, "utf8")),
      sbom: JSON.parse(await readFile(sbomPath, "utf8")),
      artifactDirectory: temporary,
      sourceCommit,
      packageVersions: await publicPackageVersions(),
      persistentSchemaVersions: state.persistentSchemaVersions,
    });
    const releaseManifest = createReleaseManifest({
      artifactManifest: JSON.parse(await readFile(manifestPath, "utf8")),
      sbom: JSON.parse(await readFile(sbomPath, "utf8")),
      tests: [
        { id: "acceptance:v1", status: "passed" },
        { id: "artifacts:verify", status: "passed" },
        { id: "release:dry-run", status: "passed" },
      ],
    });
    const releaseManifestPath = join(temporary, "release-manifest.json");
    await writeFile(releaseManifestPath, canonicalJson(releaseManifest));
    const provenance = verifyReleaseManifest({
      manifest: releaseManifest,
      artifactManifest: JSON.parse(await readFile(manifestPath, "utf8")),
      expectedCommit: sourceCommit,
    });
    run("pnpm", ["package:smoke"]);
    process.stdout.write(
      `${JSON.stringify({ ...report, cleanInstall: "verified", releaseManifest: provenance })}\n`,
    );
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

if (
  process.argv[1] &&
  pathToFileURL(resolve(process.argv[1])).href === import.meta.url
) {
  await main();
}

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { verifyArtifactBundle } from "./verify-artifacts.mjs";

const temporary = [];
afterEach(async () => {
  await Promise.all(
    temporary.splice(0).map((path) => rm(path, { recursive: true })),
  );
});

async function fixture(
  entries = ["package/dist/index.js", "package/package.json"],
) {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-verify-artifacts-"));
  temporary.push(directory);
  const artifactPath = join(directory, "fuzit.tgz");
  await writeFile(artifactPath, "artifact");
  const { createHash } = await import("node:crypto");
  const sha256 = createHash("sha256").update("artifact").digest("hex");
  const packageVersions = { "@fuzit/cli": "0.0.0" };
  const persistentSchemaVersions = { incrementalIndex: 1 };
  return {
    directory,
    artifactPath,
    options: {
      manifest: {
        sourceCommit: "a".repeat(40),
        packageVersions,
        persistentSchemaVersions,
        artifacts: [{ path: "fuzit.tgz", sha256 }],
      },
      sbom: {
        bomFormat: "CycloneDX",
        specVersion: "1.6",
        components: [],
        licenseFindings: [],
      },
      artifactDirectory: directory,
      sourceCommit: "a".repeat(40),
      packageVersions,
      persistentSchemaVersions,
      listArchive: () => entries,
    },
  };
}

describe("artifact verification", () => {
  it("returns a stable structured report for consistent identities", async () => {
    const { options } = await fixture();
    await expect(verifyArtifactBundle(options)).resolves.toEqual({
      schemaVersion: 1,
      status: "verified",
      sourceCommit: "a".repeat(40),
      artifactCount: 1,
      packageVersions: { "@fuzit/cli": "0.0.0" },
      persistentSchemaVersions: { incrementalIndex: 1 },
      sbomComponents: 0,
      forbiddenEntries: "absent",
      cleanInstall: "verified-separately",
    });
  });

  it("rejects a modified artifact", async () => {
    const { artifactPath, options } = await fixture();
    await writeFile(artifactPath, "tampered");
    await expect(verifyArtifactBundle(options)).rejects.toThrow(
      "artifact checksum mismatch",
    );
  });

  it("rejects a missing artifact", async () => {
    const { artifactPath, options } = await fixture();
    await rm(artifactPath);
    await expect(verifyArtifactBundle(options)).rejects.toThrow(
      "artifact missing",
    );
  });

  it("rejects an unexpected source map", async () => {
    const { options } = await fixture(["package/dist/index.js.map"]);
    await expect(verifyArtifactBundle(options)).rejects.toThrow(
      "forbidden artifact entry",
    );
  });
});

