  "tests/acceptance/github/run.mjs",
] as const;

describe("safe process execution (V1-111)", () => {
  it("uses executable and argument arrays without shell execution", async () => {
    for (const path of auditedFiles) {
      const source = await readFile(resolve(path), "utf8");
      expect(source, path).not.toMatch(/shell\s*:\s*true/u);
      expect(source, path).not.toMatch(/\bexec(?:Sync)?\s*\(/u);
    }
  });

  it("keeps injection-shaped arguments inert and byte-identical", () => {
    const arguments_ = [
      "space value",
      'quote"value',
      "semi;colon",
      "$(not-executed)",
      "日本語-路径",
      "--upload-pack=touch SHOULD_NOT_EXIST",
    ];
    expect(JSON.parse(JSON.stringify(arguments_))).toEqual(arguments_);
  });
});

import { describe, expect, it } from "vitest";
import {
  createSupportBundlePreview,
  redactErrorData,
  redactSensitiveText,
} from "@fuzit/security";

describe("central output and support redaction (V1-115)", () => {
  const [REDACTED:api-key];

  it("redacts stdout, stderr, and nested circular error objects deterministically", () => {
    const nested: Record<string, unknown> = {
      stdout: `token=${secret}`,
      stderr: `[REDACTED:url-credential]example.test/repo`,
      nested: { password: secret },
    };
    nested.circular = nested;
    Object.defineProperty(nested, "__proto__", {
      enumerable: true,
      value: secret,
    });
    const first = redactErrorData(nested);
    const second = redactErrorData(nested);
    expect(first).toEqual(second);
    expect(JSON.stringify(first)).not.toContain(secret);
    expect(JSON.stringify(first)).toContain("[CIRCULAR]");
    expect(Object.prototype.hasOwnProperty.call(first, "__proto__")).toBe(
      false,
    );
  });

  it("creates a bounded metadata-only local support preview", () => {
    const bundle = createSupportBundlePreview({
      productVersion: "1.0.0",
      checks: [
        {
          surface: "plugin",
          status: "fail",
          error: new Error(`secret=${secret}`),
        },
        { surface: "git", status: "warning", error: `token=${secret}` },
      ],
    });
    expect(bundle.checks.map(({ surface }) => surface)).toEqual([
      "git",
      "plugin",
    ]);
    expect(bundle.contentIncluded).toBe(false);
    expect(JSON.stringify(bundle)).not.toContain(secret);
    expect(redactSensitiveText(`token=${secret}`)).not.toContain(secret);
  });
});

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

const requiredSurfaces = [
  "discovery and configuration",
  "scanner and security filter",
  "incremental index and watcher",
  "analysis and graph",
  "CLI and renderers",
  "MCP server",
  "VS Code extension",
  "plugin SDK and host",
  "logs, crash output, support bundles, and archives",
  "packaging and release",
] as const;

function threatRows(markdown: string): string[][] {
  return markdown
    .split(/\r?\n/)
    .filter((line) => /^\| TM-\d{2} \|/.test(line))
    .map((line) =>
      line
        .split("|")
        .slice(1, -1)
        .map((cell) => cell.trim()),
    );
}

describe("V1 threat-model traceability", () => {
  it("maps every V1 attack surface to controls, tests, ownership, risk, and a blocker", async () => {
    const markdown = await readFile(
      resolve("docs/security/threat-model.md"),
      "utf8",
    );
    const rows = threatRows(markdown);

    expect(rows.map((row) => row[0])).toEqual(
      Array.from(
        { length: 10 },
        (_, index) => `TM-${String(index + 1).padStart(2, "0")}`,
      ),
    );
    expect(rows.map((row) => row[1])).toEqual(requiredSurfaces);
    for (const row of rows) {
      expect(row).toHaveLength(8);
      for (const evidence of row.slice(2))
        expect(evidence.length).toBeGreaterThan(8);
    }
  });

  it("fails traceability for a critical threat with missing evidence", () => {
    const incomplete =
      "| TM-01 | plugins | escape | deny |  | owner | risk | blocker |";
    const [row] = threatRows(incomplete);
    expect(row).toBeDefined();
    expect(row?.[4]).toBe("");
    expect(row?.every((cell) => cell.length > 0)).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

import {
  normalizedAnalysisSchema,
  parseNormalizedAnalysis,
  serializeNormalizedAnalysis,
} from "@fuzit/analysis";

const hash = (character: string) => `sha256:${character.repeat(64)}`;
const id = (kind: string, character: string) =>
  `analysis:${kind}:${character.repeat(64)}`;

const repositoryId = hash("a");
const range = {
  start: { offset: 0, line: 1, column: 1 },
  end: { offset: 10, line: 1, column: 11 },
};

function representativeRecord() {
  const fileId = id("file", "b");
  const symbolId = id("symbol", "c");
  return {
    schemaVersion: 1,
    repositoryId,
    analysisIdentity: "normalized-analysis@1",
    files: [
      {
        id: fileId,
        repositoryId,
        kind: "file",
        path: "src/index.ts",
        language: "typescript",
        contentHash: hash("d"),
      },
    ],
    modules: [
      {
        id: id("module", "e"),
        repositoryId,
        kind: "module",
        name: "src/index",
        path: "src/index.ts",
      },
    ],
    symbols: [
      {
        id: symbolId,
        repositoryId,
        kind: "function",
        name: "main",
        fileId,
        range,
        exported: true,
      },
    ],
    relationships: [
      {
        id: id("import", "f"),
        repositoryId,
        kind: "import",
        sourceId: fileId,
        targetId: null,
        unresolvedTarget: "./missing.js",
        provenance: {
          sourceFileId: fileId,
          sourceSymbolId: symbolId,
          range,
          basis: "parsed",
          parserIdentity: "typescript-parser@1",
          analysisIdentity: "normalized-analysis@1",
          confidence: 1,
          resolution: "unresolved",
        },
      },
    ],
    completeness: "partial",
    diagnostics: ["Unresolved import"],
  } as const;
}

describe("normalized analysis contracts", () => {
  it("validates and round-trips representative records without raw ASTs", () => {
    const parsed = parseNormalizedAnalysis(representativeRecord());
    expect(JSON.parse(serializeNormalizedAnalysis(parsed))).toEqual(parsed);
    expect(
      serializeNormalizedAnalysis({
        ...parsed,
        files: [...parsed.files].reverse(),
      }),
    ).toBe(serializeNormalizedAnalysis(parsed));
    expect(
      normalizedAnalysisSchema.safeParse({ ...parsed, rawAst: {} }).success,
    ).toBe(false);
  });

  it("rejects invalid source ranges", () => {
    const record = representativeRecord();
    const invalid = {
      ...record,
      symbols: [
        {
          ...record.symbols[0],
          range: {
            start: { offset: 10, line: 1, column: 11 },
            end: { offset: 1, line: 1, column: 2 },
          },
        },
      ],
    };
    expect(normalizedAnalysisSchema.safeParse(invalid).success).toBe(false);
  });

  it("rejects unknown evidence basis labels", () => {
    const record = representativeRecord();
    const invalid = {
      ...record,
      relationships: [
        {
          ...record.relationships[0],
          provenance: { ...record.relationships[0].provenance, basis: "guess" },
        },
      ],
    };
    expect(normalizedAnalysisSchema.safeParse(invalid).success).toBe(false);
  });

  it("rejects cross-root identities and non-canonical paths", () => {
    const record = representativeRecord();
    expect(
      normalizedAnalysisSchema.safeParse({
        ...record,
        files: [{ ...record.files[0], repositoryId: hash("9") }],
      }).success,
    ).toBe(false);
    expect(
      normalizedAnalysisSchema.safeParse({
        ...record,
        files: [{ ...record.files[0], path: "../outside.ts" }],
      }).success,
    ).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import {
  TypeScriptParserAdapter,
  enrichCrossLanguageRelations,
} from "@fuzit/analysis";

const parser = new TypeScriptParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;
const base = () =>
  parser.parse({
    repositoryId,
    contentHash,
    path: "src/app.test.ts",
    source:
      "function target() {}\ntest('target', () => {})\nconst UserSchema = z.object({})\n",
  });

describe("cross-language relation enrichment", () => {
  it("links tests, schemas, endpoints, and configuration with provenance", () => {
    const analysis = base();
    const test = analysis.symbols.find(({ kind }) => kind === "test")!;
    const target = analysis.symbols.find(({ name }) => name === "target")!;
    const schema = analysis.symbols.find(({ kind }) => kind === "schema")!;
    const enriched = enrichCrossLanguageRelations(analysis, [
      {
        kind: "test",
        sourceSymbolId: test.id,
        targetId: target.id,
        basis: "parsed",
        originIdentity: "typescript-test-detector@1",
        confidence: 1,
      },
      {
        kind: "schema",
        sourceSymbolId: schema.id,
        targetId: target.id,
        basis: "parsed",
        originIdentity: "zod-detector@1",
        frameworkIdentity: "zod",
        confidence: 0.9,
      },
      {
        kind: "configuration-link",
        sourceSymbolId: target.id,
        targetId: analysis.modules[0]?.id ?? null,
        unresolvedTarget: "package",
        basis: "configured",
        originIdentity: "package-json-detector@1",
        confidence: 1,
      },
    ]);
    expect(enriched.relationships.map(({ kind }) => kind)).toEqual(
      expect.arrayContaining(["test", "schema", "configuration-link"]),
    );
    expect(
      enriched.relationships.every(
        ({ provenance }) => provenance.parserIdentity.length > 0,
      ),
    ).toBe(true);
  });

  it("marks conflicting evidence ambiguous deterministically", () => {
    const analysis = base();
    const source = analysis.symbols[0]!,
      one = analysis.symbols[1]!;
    const candidates = [
      {
        kind: "test" as const,
        sourceSymbolId: source.id,
        targetId: one.id,
        basis: "inferred" as const,
        originIdentity: "detector-a@1",
        confidence: 0.8,
      },
      {
        kind: "test" as const,
        sourceSymbolId: source.id,
        unresolvedTarget: "other",
        basis: "inferred" as const,
        originIdentity: "detector-b@1",
        confidence: 0.8,
      },
    ];
    const result = enrichCrossLanguageRelations(analysis, candidates);
    expect(result).toEqual(
      enrichCrossLanguageRelations(analysis, [...candidates].reverse()),
    );
    expect(
      result.relationships.every(
        ({ provenance }) => provenance.resolution === "ambiguous",
      ),
    ).toBe(true);
  });

  it("rejects framework-absent lookalikes and unknown identities", () => {
    const analysis = base();
    const source = analysis.symbols[0]!;
    const result = enrichCrossLanguageRelations(analysis, [
      {
        kind: "endpoint",
        sourceSymbolId: source.id,
        unresolvedTarget: "/looks-like-route",
        basis: "inferred",
        originIdentity: "name-detector@1",
        confidence: 0.4,
      },
      {
        kind: "test",
        sourceSymbolId: "analysis:symbol:" + "f".repeat(64),
        unresolvedTarget: "missing",
        basis: "inferred",
        originIdentity: "test-detector@1",
        confidence: 0.4,
      },
    ]);
    expect(result.relationships).toEqual(analysis.relationships);
    expect(result.completeness).toBe("partial");
    expect(result.diagnostics).toHaveLength(2);
  });
});

