import { describe, expect, it } from "vitest";
import {
  PARSER_AVAILABILITY_DIAGNOSTICS,
  TypeScriptParserAdapter,
  markUnsupportedFeature,
  runParserSafely,
} from "@fuzit/analysis";

const parser = new TypeScriptParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;
const independent = () =>
  parser.parse({
    repositoryId,
    contentHash,
    path: "src/independent.ts",
    source: "export const manifestFact = true;",
  });

describe("parser availability semantics", () => {
  it("preserves independent facts when an optional parser is absent", async () => {
    const base = independent();
    const result = await runParserSafely({
      parserIdentity: "optional@1",
      timeoutMs: 20,
      independentAnalysis: base,
      parse: null,
    });
    expect(result.files).toEqual(base.files);
    expect(result.symbols).toEqual(base.symbols);
    expect(result.completeness).toBe("partial");
    expect(result.diagnostics).toContain(
      PARSER_AVAILABILITY_DIAGNOSTICS.missing,
    );
  });

  it("contains deliberate parser failures without leaking thrown content", async () => {
    const result = await runParserSafely({
      parserIdentity: "broken@1",
      timeoutMs: 20,
      independentAnalysis: independent(),
      parse: () => {
        throw new Error("SECRET_SOURCE_CONTENT");
      },
    });
    expect(result.diagnostics).toContain(PARSER_AVAILABILITY_DIAGNOSTICS.crash);
    expect(JSON.stringify(result)).not.toContain("SECRET_SOURCE_CONTENT");
  });

  it("bounds parser timeouts deterministically", async () => {
    const result = await runParserSafely({
      parserIdentity: "slow@1",
      timeoutMs: 5,
      independentAnalysis: independent(),
      parse: () => new Promise(() => {}),
    });
    expect(result.diagnostics).toContain(
      PARSER_AVAILABILITY_DIAGNOSTICS.timeout,
    );
  });

  it("standardizes syntax, partial, and unsupported outcomes", async () => {
    const malformed = parser.parse({
      repositoryId,
      contentHash,
      path: "src/broken.ts",
      source: "export const broken = {",
    });
    const result = await runParserSafely({
      parserIdentity: parser.parserIdentity,
      timeoutMs: 20,
      independentAnalysis: independent(),
      parse: () => malformed,
    });
    expect(result.diagnostics).toContain(
      PARSER_AVAILABILITY_DIAGNOSTICS.syntax,
    );
    expect(markUnsupportedFeature(independent()).diagnostics).toContain(
      PARSER_AVAILABILITY_DIAGNOSTICS.unsupported,
    );
  });
});

import { describe, expect, it } from "vitest";

import {
  PYTHON_PARSER_IDENTITY,
  PYTHON_PARSER_MAX_SOURCE_BYTES,
  PythonParserAdapter,
} from "@fuzit/analysis";

const adapter = new PythonParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;

function parse(path: string, source: string) {
  return adapter.parse({ repositoryId, contentHash, path, source });
}

describe("PythonParserAdapter", () => {
  it("accepts modules, imports, decorators, functions, classes, tests, and routes", () => {
    const result = parse(
      "services/api.py",
      `from .models import User\n@router.get("/users")\ndef test_users():\n    return User\nclass Service:\n    pass\n`,
    );
    expect(result.completeness).toBe("complete");
    expect(result.modules[0]).toMatchObject({
      kind: "module",
      name: "services.api",
    });
    expect(PYTHON_PARSER_IDENTITY).toContain("syntax-adapter@1");
  });

  it("supports regular and namespace package identities deterministically", () => {
    expect(parse("pkg/__init__.py", "").modules[0]).toMatchObject({
      kind: "package",
      name: "pkg",
    });
    expect(parse("namespace/pkg/module.py", "")).toEqual(
      parse("namespace/pkg/module.py", ""),
    );
  });

  it("supports Unicode and relative imports without executing them", () => {
    const result = parse(
      "pkg/module.py",
      "from ..shared import café\nname = 'नमस्ते'\n",
    );
    expect(result.completeness).toBe("complete");
    expect(result.relationships).toHaveLength(1);
    expect(result.relationships[0]).toMatchObject({
      targetId: null,
      unresolvedTarget: "..shared",
    });
  });

  it("returns bounded partial diagnostics for malformed files", () => {
    const result = parse("broken.py", "def broken(\n");
    expect(result.completeness).toBe("partial");
    expect(result.diagnostics).toEqual([
      "PY_SYNTAX: unclosed delimiter",
      "PY_SYNTAX: missing suite colon at line 1",
    ]);
    expect(result.diagnostics.join(" ")).not.toContain("def broken");
  });

  it("rejects unsupported and oversized files safely", () => {
    expect(parse("module.rb", "puts 1").completeness).toBe("unsupported");
    expect(
      parse("large.py", "x".repeat(PYTHON_PARSER_MAX_SOURCE_BYTES + 1))
        .completeness,
    ).toBe("failed");
  });
});

import { describe, expect, it } from "vitest";
import { PythonParserAdapter } from "@fuzit/analysis";

const adapter = new PythonParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;
const parse = (source: string, path = "pkg/module.py") =>
  adapter.parse({
    repositoryId,
    contentHash,
    path,
    source,
    knownModules: {
      ".models": "pkg/models.py",
      requests: "vendor/requests.py",
    },
  });

describe("Python normalized extraction", () => {
  it("extracts functions, classes, methods, tests, routes, and models", () => {
    const result = parse(`
class User(BaseModel):
    def save(self): pass
@router.get("/users")
def list_users(): pass
def test_users(): pass
`);
    expect(result.symbols.map(({ kind }) => kind)).toEqual(
      expect.arrayContaining([
        "schema",
        "method",
        "function",
        "test",
        "endpoint",
      ]),
    );
  });

  it("resolves aliased imports and from-imports including __init__.py", () => {
    const result = parse(
      "import requests as http\nfrom .models import User\n",
      "pkg/__init__.py",
    );
    expect(result.relationships).toHaveLength(2);
    expect(
      result.relationships.every(({ targetId }) => targetId !== null),
    ).toBe(true);
  });

  it("marks dynamic import helpers unresolved and inferred", () => {
    const relation = parse("module = importlib.import_module(name)\n")
      .relationships[0]!;
    expect(relation).toMatchObject({
      targetId: null,
      unresolvedTarget: "<dynamic>",
    });
    expect(relation.provenance.basis).toBe("inferred");
  });

  it("assigns duplicate names distinct deterministic identities", () => {
