import { describe, expect, it } from "vitest";

import { TypeScriptParserAdapter } from "@fuzit/analysis";

const adapter = new TypeScriptParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;
const resolution = {
  knownFiles: [
    "src/local.ts",
    "src/shared/util.ts",
    "packages/lib/src/index.ts",
    "packages/ref/src/index.ts",
  ],
  pathAliases: { "@shared/*": "src/shared/*" },
  packageExports: { "@scope/lib": "packages/lib/src/index.ts" },
  projectReferences: { ref: "packages/ref/src/index.ts" },
};

function parse(source: string) {
  return adapter.parse({
    repositoryId,
    contentHash,
    path: "src/index.ts",
    source,
    resolution,
  });
}

describe("TypeScript module relationships", () => {
  it("resolves ESM, aliases, monorepo packages, and project references", () => {
    const result = parse(`
      import "./local";
      import util from "@shared/util";
      export * from "@scope/lib";
      import "ref";
    `);
    expect(result.relationships).toHaveLength(4);
    expect(
      result.relationships.every(({ targetId }) => targetId !== null),
    ).toBe(true);
    expect(
      result.relationships.every(
        ({ provenance }) => provenance.basis === "parsed",
      ),
    ).toBe(true);
  });

  it("resolves CommonJS and preserves deterministic relationship IDs", () => {
    const source = `const local = require("./local");`;
    expect(parse(source).relationships).toEqual(parse(source).relationships);
    expect(parse(source).relationships[0]?.targetId).not.toBeNull();
  });

  it("keeps dynamic and missing targets explicitly unresolved", () => {
    const result = parse(`
      import("./local");
      import(name);
      import "./missing";
    `);
    expect(result.relationships).toHaveLength(3);
    expect(
      result.relationships.every(({ targetId }) => targetId === null),
    ).toBe(true);
    expect(
      result.relationships.map(({ unresolvedTarget }) => unresolvedTarget),
    ).toEqual(expect.arrayContaining(["./local", "<dynamic>", "./missing"]));
  });

  it("records named and default exports against extracted symbols", () => {
    const result = parse(`
      const value = 1;
      export { value };
      export default function () {}
    `);
    const exports = result.relationships.filter(
      ({ kind }) => kind === "export",
    );
    expect(exports).toHaveLength(2);
    expect(exports.every(({ targetId }) => targetId !== null)).toBe(true);
  });
});

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

import {
  TYPESCRIPT_PARSER_IDENTITY,
  TYPESCRIPT_PARSER_MAX_SOURCE_BYTES,
  TypeScriptParserAdapter,
} from "@fuzit/analysis";

const adapter = new TypeScriptParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;

async function fixture(name: string): Promise<string> {
  return readFile(resolve("fixtures/analysis/typescript", name), "utf8");
}

function parse(path: string, source: string, tsconfigPath?: string | null) {
  return adapter.parse({
    repositoryId,
    path,
    contentHash,
    source,
    tsconfigPath,
  });
}

describe("TypeScriptParserAdapter", () => {
  it.each([
    ["source.ts", "export const value: number = 1;"],
    ["source.tsx", "export const View = () => <main />;"],
    ["source.js", "module.exports = 1;"],
    ["source.jsx", "export const View = () => <main />;"],
    ["source.mjs", "export default 1;"],
    ["source.cjs", "module.exports = 1;"],
  ])("parses %s without executing repository code", (path, source) => {
    const result = parse(path, source);
    expect(result.completeness).toBe("complete");
    expect(result.files).toHaveLength(1);
    expect(JSON.stringify(result)).not.toContain("rawAst");
  });

  it("is deterministic without a tsconfig", async () => {
    const source = await fixture("valid.ts");
    expect(parse("src/index.ts", source, null)).toEqual(
      parse("src/index.ts", source),
    );
    expect(TYPESCRIPT_PARSER_IDENTITY).toMatch(/^typescript@/u);
  });

  it("returns bounded safe diagnostics for invalid syntax", async () => {
    const source = await fixture("malformed.ts.txt");
    const result = parse("src/malformed.ts", source);
    expect(result.completeness).toBe("partial");
    expect(result.diagnostics[0]).toMatch(
      /^TS\d+: syntax diagnostic at offset/u,
    );
    expect(result.diagnostics.join(" ")).not.toContain(source);
  });

  it("parses JSX and Unicode fixtures", async () => {
    expect(
      parse("src/component.tsx", await fixture("component.tsx")).completeness,
    ).toBe("complete");
    expect(
      parse("src/unicode.ts", await fixture("unicode.ts")).completeness,
    ).toBe("complete");
  });

  it("rejects unsupported and oversized sources safely", () => {
    expect(parse("src/data.py", "print('x')").completeness).toBe("unsupported");
    const result = parse(
      "src/large.ts",
      "x".repeat(TYPESCRIPT_PARSER_MAX_SOURCE_BYTES + 1),
    );
    expect(result.completeness).toBe("failed");
    expect(result.files).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";

import { TypeScriptParserAdapter } from "@fuzit/analysis";

const adapter = new TypeScriptParserAdapter();
const repositoryId = `sha256:${"a".repeat(64)}`;
const contentHash = `sha256:${"b".repeat(64)}`;

function symbols(source: string) {
  return adapter.parse({
    repositoryId,
    contentHash,
    path: "src/symbols.tsx",
    source,
  }).symbols;
}

describe("TypeScript symbol extraction", () => {
  it("extracts declarations, tests, endpoints, schemas, and exact ranges", () => {
    const result = symbols(`
      export function run(): void {}
      export class Service { execute(): void {} }
      interface Contract {}
      type Identifier = string;
      export const UserSchema = z.object({});
      describe("service", () => {});
      router.get("/users", handler);
    `);
    expect(result.map(({ kind, name }) => [kind, name])).toEqual(
      expect.arrayContaining([
        ["function", "run"],
        ["class", "Service"],
        ["method", "execute"],
        ["interface", "Contract"],
        ["type", "Identifier"],
        ["schema", "UserSchema"],
        ["test", "service"],
        ["endpoint", "GET /users"],
      ]),
    );
    expect(
      result.every(
        (symbol) => symbol.range.end.offset >= symbol.range.start.offset,
      ),
    ).toBe(true);
  });

  it("gives overloads and duplicate nested names distinct stable IDs", () => {
    const source = `
      function convert(value: string): string;
      function convert(value: number): number;
      function convert(value: string | number) { return value; }
      function outer() { function convert() {} return convert; }
    `;
    const first = symbols(source).filter(({ name }) => name === "convert");
    const second = symbols(source).filter(({ name }) => name === "convert");
    expect(new Set(first.map(({ id }) => id)).size).toBe(4);
    expect(second.map(({ id }) => id)).toEqual(first.map(({ id }) => id));
  });

  it("names anonymous default declarations deterministically", () => {
    const result = symbols(
      "export default function () {}; export default class {};",
    );
    expect(result.map(({ kind, name }) => [kind, name])).toEqual(
      expect.arrayContaining([
        ["function", "default"],
        ["class", "default"],
      ]),
    );
  });
});

import { spawnSync } from "node:child_process";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

const cli = resolve("apps/cli/dist/bin.js");
let root: string;

function run(args: string[]) {
  const result = spawnSync(process.execPath, [cli, ...args], {
    encoding: "utf8",
    shell: false,
  });
  expect(result.stderr).not.toContain("SECRET_MONOREPO_VALUE");
  expect(result.status, result.stderr || result.stdout).toBe(0);
  return result.stdout;
}

beforeAll(async () => {
  root = await mkdtemp(join(tmpdir(), "fuzit-next-monorepo-"));
  for (const directory of [
    "apps/web/app",
    "packages/ui/src",
    "packages/private/src",
  ])
    await mkdir(join(root, directory), { recursive: true });
  await writeFile(
    join(root, "pnpm-workspace.yaml"),
    "packages:\n  - apps/*\n  - packages/*\n",
  );
  await writeFile(
    join(root, "package.json"),
    JSON.stringify({ private: true, workspaces: ["apps/*", "packages/*"] }),
  );
  await writeFile(
    join(root, "apps/web/package.json"),
    JSON.stringify({
      name: "web",
      dependencies: { "@fixture/ui": "workspace:*", next: "15.0.0" },
    }),
  );
  await writeFile(
    join(root, "apps/web/app/page.tsx"),
    'import { Button } from "@fixture/ui";\nexport default function Page() { return <Button />; }\n',
  );
  await writeFile(
    join(root, "packages/ui/package.json"),
    JSON.stringify({ name: "@fixture/ui" }),
  );
  await writeFile(
    join(root, "packages/ui/src/button.tsx"),
    "export function Button() { return <button>Safe</button>; }\n",
  );
  await writeFile(
    join(root, "packages/private/package.json"),
    JSON.stringify({ name: "@fixture/private" }),
  );
  await writeFile(
    join(root, "packages/private/src/key.ts"),
    'export const key = "SECRET_MONOREPO_VALUE";\n',
  );
  const initialized = spawnSync("git", ["init", "--quiet"], {
    cwd: root,
    encoding: "utf8",
    shell: false,
  });
  expect(initialized.status, initialized.stderr).toBe(0);
});

afterAll(async () => rm(root, { recursive: true, force: true }));

describe("TypeScript monorepo and Next.js App Router", () => {
  it("selects the canonical workspace root without inventing nested repositories", () => {
    const output = JSON.parse(
      run(["--json", "scan", "--root", root, "--list-roots"]),
    ) as { selectedRoot: string; nestedRoots: string[] };
    expect(output).toEqual(
      expect.objectContaining({ selectedRoot: ".", nestedRoots: [] }),
    );
  });

  it("keeps task context budgeted and within the web/UI boundary", async () => {
    const output = join(root, "context.md");
    run([
      "context",
      "--root",
      root,
      "--task",
      "fix the App Router page button",
      "--profile",
      "bug-fix",
      "--budget-tokens",
      "800",
      "--format",
      "markdown",
      "--output",
      output,
    ]);
    const context = await readFile(output, "utf8");
    expect(context).toContain("page.tsx");
    expect(context).toContain("button.tsx");
    expect(context).not.toContain("SECRET_MONOREPO_VALUE");
    expect(context.length).toBeLessThan(12_000);
  }, 20_000);

  it("processes an incremental watcher pass", () => {
    run(["watch", "--root", root, "--once"]);
  });
});

import { describe, expect, it } from "vitest";

import { resolvePackRenderer } from "../../../apps/cli/src/commands/pack/register.js";
import { RendererRegistry, type Renderer } from "@fuzit/renderer-core";
import { jsonRenderer } from "@fuzit/renderer-json";
import { markdownRenderer } from "@fuzit/renderer-markdown";
import { textRenderer } from "@fuzit/renderer-text";
import { xmlRenderer } from "@fuzit/renderer-xml";

const registry = new RendererRegistry([
  jsonRenderer,
  markdownRenderer,
  textRenderer,
  xmlRenderer,
]);

describe("renderer compatibility", () => {
  it("rejects mismatched extensions", () => {
    expect(() => resolvePackRenderer(registry, "json", "bundle.md")).toThrow(
      "PACK.EXTENSION_MISMATCH",
    );
  });

  it("future-proofs stdout against binary renderers", () => {
    const binary: Renderer = {
      ...textRenderer,
      metadata: {
        ...textRenderer.metadata,
        format: "binary",
        extension: ".bin",
        capabilities: { ...textRenderer.metadata.capabilities, binary: true },
      },
    };
    expect(() =>
      resolvePackRenderer(new RendererRegistry([binary]), "binary", "-"),
    ).toThrow("PACK.BINARY_STDOUT_UNSUPPORTED");
  });

  it("resolves auto by extension and rejects unknown renderers", () => {
    expect(resolvePackRenderer(registry, "auto", "bundle.xml")).toBe(
      xmlRenderer,
    );
    expect(() =>
      resolvePackRenderer(registry, "unknown", "bundle.txt"),
    ).toThrow("Unknown renderer");
  });

  it("preserves the no-overwrite output policy and golden formats", () => {
    expect(registry.list().map(({ format }) => format)).toEqual([
      "json",
      "markdown",
      "text",
      "xml",
    ]);
  });
});

