import {
  lstat,
  mkdir,
  mkdtemp,
  readFile,
  rm,
  symlink,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, join, normalize } from "node:path";
import { describe, expect, it } from "vitest";
import { runDoctor } from "@fuzit/core";

describe("cross-platform contracts", () => {
  it("normalizes either path separator without changing the basename", () => {
    expect(basename(normalize(join("folder", "nested", "file.ts")))).toBe(
      "file.ts",
    );
    expect("folder\\nested/file.ts".replaceAll("\\", "/")).toBe(
      "folder/nested/file.ts",
    );
  });
  it("passes shell-significant task text as an argument value", () => {
    const task = `fix "quoted" value & preserve $HOME`;
    expect(JSON.parse(JSON.stringify([task]))).toEqual([task]);
  });
  it("detects symlink capability rather than assuming permissions", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-link-"));
    const target = join(root, "target.txt");
    await writeFile(target, "safe");
    try {
      const link = join(root, "link.txt");
      await symlink(target, link, "file");
      expect((await lstat(link)).isSymbolicLink()).toBe(true);
    } catch (error) {
      expect((error as NodeJS.ErrnoException).code).toMatch(/EPERM|EACCES/);
    }
  });
  it("uses LF repository fixtures", async () => {
    const content = await readFile(
      new URL("../../.nvmrc", import.meta.url),
      "utf8",
    );
    expect(content).not.toContain("\r\n");
  });
  it("audits the index package for native SQLite packaging", async () => {
    const manifest = JSON.parse(
      await readFile(
        new URL("../../packages/index/package.json", import.meta.url),
        "utf8",
      ),
    ) as { dependencies?: Record<string, string> };
    expect(
      Object.keys(manifest.dependencies ?? {}).filter((name) =>
        /sqlite/i.test(name),
      ),
    ).toEqual([]);
  });
  it("keeps runtime, package-manager, docs, and doctor metadata consistent", async () => {
    const manifest = JSON.parse(
      await readFile(new URL("../../package.json", import.meta.url), "utf8"),
    ) as {
      packageManager: string;
      engines: { node: string; pnpm: string };
    };
    const nvmrc = (
      await readFile(new URL("../../.nvmrc", import.meta.url), "utf8")
    ).trim();
    const matrix = await readFile(
      new URL("../../docs/reference/support-matrix.md", import.meta.url),
      "utf8",
    );
    expect(manifest).toMatchObject({
      packageManager: "pnpm@11.9.0",
      engines: { node: ">=24.0.0 <25.0.0", pnpm: "11.9.0" },
    });
    expect(nvmrc).toBe("24");
    expect(matrix).toContain(manifest.engines.node);
    expect(matrix).toContain(manifest.packageManager.replace("pnpm@", ""));
    for (const platform of ["win32", "linux", "darwin"] as const) {
      const report = await runDoctor(".", {
        nodeVersion: "24.0.0",
        pnpmUserAgent: "pnpm/11.9.0",
        platform,
        checkGit: () => "git version 2.40.0",
        checkAccess: async () => undefined,
      });
      expect(report.checks.find(({ id }) => id === "node")?.metadata).toEqual({
        version: "24.0.0",
      });
      expect(
        report.checks.find(({ id }) => id === "platform")?.metadata,
      ).toMatchObject({
        platform,
      });
    }
  });
  it("round-trips long Unicode paths and bounded cancellation", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-win-path-🚀-"));
    const nested = join(
      root,
      ...Array.from({ length: 12 }, (_, i) => `segment-${i}-資料`),
    );
    const controller = new AbortController();
    try {
      await mkdir(nested, { recursive: true });
      const file = join(nested, "context-✓.txt");
      await writeFile(file, "deterministic\n");
      expect(await readFile(file, "utf8")).toBe("deterministic\n");
      controller.abort(new Error("cancelled"));
      expect(controller.signal.aborted).toBe(true);
      expect(controller.signal.reason).toEqual(new Error("cancelled"));
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });
});

import { describe, expect, it } from "vitest";
import {
  normalizeRepositoryRelativePath,
  toRepositoryRelativePath,
} from "@fuzit/core";

describe("canonical path normalization fixtures", () => {
  it("canonicalizes separators and dot segments deterministically", () => {
    const fixtures = [
      "packages\\core/./src/../src/index.ts",
      "packages/core/src/index.ts",
      "./packages//core/src/index.ts",
    ];
    expect(fixtures.map(normalizeRepositoryRelativePath)).toEqual([
      "packages/core/src/index.ts",
      "packages/core/src/index.ts",
      "packages/core/src/index.ts",
    ]);
  });

  it("preserves case so collisions remain visible to policy", () => {
    const collision = ["src/Thing.ts", "src/thing.ts"].map(
      normalizeRepositoryRelativePath,
    );
    expect(collision).toEqual(["src/Thing.ts", "src/thing.ts"]);
    expect(new Set(collision).size).toBe(2);
  });

  it("normalizes both sides of a case-only rename without losing identity", () => {
    const rename = {
      from: normalizeRepositoryRelativePath("src\\Thing.ts"),
      to: normalizeRepositoryRelativePath("src/thing.ts"),
    };
    expect(rename).toEqual({ from: "src/Thing.ts", to: "src/thing.ts" });
  });

  it("rejects drive changes, absolute inputs, and repository escapes", () => {
    expect(() =>
      toRepositoryRelativePath("C:\\repo", "D:\\repo\\file.ts"),
    ).toThrowError(expect.objectContaining({ code: "PATH.ROOT_MISMATCH" }));
    expect(() =>
      normalizeRepositoryRelativePath("/rooted/file.ts"),
    ).toThrowError(expect.objectContaining({ code: "PATH.ABSOLUTE" }));
    expect(() =>
      normalizeRepositoryRelativePath("../../escape.ts"),
    ).toThrowError(expect.objectContaining({ code: "PATH.ESCAPE" }));
  });

  it("produces the same bundle-facing identity for host separator forms", () => {
    expect(normalizeRepositoryRelativePath("src\\nested\\file.ts")).toBe(
      normalizeRepositoryRelativePath("src/nested/file.ts"),
    );
  });
});

import { spawn } from "node:child_process";
import {
  access,
  chmod,
  mkdir,
  mkdtemp,
  readFile,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { IndexWriterLock } from "@fuzit/watcher";

const roots: string[] = [];

afterEach(async () => {
  await Promise.all(
    roots.splice(0).map((root) => rm(root, { recursive: true, force: true })),
  );
});

async function fixtureRoot(): Promise<string> {
  const root = await mkdtemp(join(tmpdir(), "fuzit-permissions-"));
  roots.push(root);
  return root;
}

describe("permission, lock, and cleanup fixtures", () => {
  it("rejects an active writer lock without replacing it", async () => {
    const root = await fixtureRoot();
    const child = spawn(
      process.execPath,
      ["-e", "setInterval(() => {}, 1000)"],
      {
        stdio: "ignore",
        windowsHide: true,
      },
    );
    try {
      expect(child.pid).toBeTypeOf("number");
      const metadata = {
        lockVersion: 1,
        pid: child.pid,
        createdAt: new Date().toISOString(),
        repositoryId: "repo-active",
        hostname: "fixture-host",
        sessionId: "fixture-session",
      };
      await writeFile(join(root, "writer.lock"), JSON.stringify(metadata));
      const lock = new IndexWriterLock({
        indexPath: root,
        repositoryId: "repo-active",
      });
      await expect(lock.acquire()).rejects.toThrow("Writer lock active");
      expect(
        JSON.parse(await readFile(join(root, "writer.lock"), "utf8")),
      ).toEqual(metadata);
    } finally {
      child.kill();
    }
  });

  it("replaces a stale lock and removes only its own lock on release", async () => {
    const parent = await fixtureRoot();
    const root = join(parent, "index");
    const sentinel = join(parent, "owner-sentinel.txt");
    await mkdir(root);
    await writeFile(sentinel, "keep");
    await writeFile(
      join(root, "writer.lock"),
      JSON.stringify({
        lockVersion: 1,
        pid: 2_147_483_647,
        createdAt: "2000-01-01T00:00:00.000Z",
        repositoryId: "repo-stale",
        hostname: "fixture-host",
        sessionId: "stale-session",
      }),
    );
    const lock = new IndexWriterLock({
      indexPath: root,
      repositoryId: "repo-stale",
      staleThresholdMs: 1,
    });
    await lock.acquire();
    expect(lock.metadata?.pid).toBe(process.pid);
    await lock.release();
    await expect(access(join(root, "writer.lock"))).rejects.toMatchObject({
      code: "ENOENT",
    });
    expect(await readFile(sentinel, "utf8")).toBe("keep");
  });

  it("maps read-only behavior according to host filesystem semantics", async () => {
    const root = await fixtureRoot();
    const file = join(root, "read-only.txt");
    await writeFile(file, "original");
    await chmod(file, 0o444);
    try {
      if (process.platform === "win32") {
        expect(await readFile(file, "utf8")).toBe("original");
      } else {
        await expect(writeFile(file, "changed")).rejects.toMatchObject({
          code: expect.stringMatching(/EACCES|EPERM|EROFS/u),
        });
      }
    } finally {
      await chmod(file, 0o666);
    }
  });
});

import { describe, expect, it } from "vitest";
import { runGit } from "@fuzit/git";
import { EXIT_CODES } from "@fuzit/schemas";
import { withTimeout } from "../../apps/mcp-server/src/tool-runner.js";
import { WatchRegistry } from "../../apps/vscode-extension/src/watch.js";

describe("cross-platform process cancellation", () => {
  it("cancels a spawned Git-owned process with common result semantics", async () => {
    const controller = new AbortController();
    const resultPromise = runGit(["-e", "setInterval(() => {}, 1000)"], {
      executable: process.execPath,
      signal: controller.signal,
      timeoutMs: 10_000,
    });
    controller.abort(new Error("cancelled by fixture"));
    await expect(resultPromise).resolves.toMatchObject({
      ok: false,
      cancelled: true,
      timedOut: false,
    });
  });

  it("propagates MCP cancellation and disposes its timeout listener", async () => {
    const controller = new AbortController();
    const operation = withTimeout(
      (signal) =>
        new Promise<never>((_, reject) => {
          signal.addEventListener("abort", () => reject(signal.reason), {
            once: true,
          });
        }),
      controller.signal,
      10_000,
    );
    controller.abort(new Error("client cancelled"));
    await expect(operation).rejects.toThrow("client cancelled");
  });

  it("cancels every extension-owned watcher and returns to idle", () => {
    const registry = new WatchRegistry();
    const first = registry.start("repository-a");
    const second = registry.start("repository-b");
    registry.stopAll();
    expect(first.signal.aborted).toBe(true);
    expect(second.signal.aborted).toBe(true);
    expect(registry.getState("repository-a")).toBe("idle");
    expect(registry.getState("repository-b")).toBe("idle");
  });

  it("preserves the shell-independent CLI cancellation exit contract", () => {
    expect(EXIT_CODES.cancelled).toBe(130);
  });
});

