import { describe, expect, it } from "vitest";

import { selectDeltaScope } from "../../../packages/core/src/index.js";

describe("delta bundle scope", () => {
  it("preserves deleted-file metadata", () => {
    expect(
      selectDeltaScope([], {
        complete: true,
        files: [{ path: "gone", previousPath: "gone", kind: "deleted" }],
      }).deleted,
    ).toEqual([{ path: "gone", previousPath: "gone" }]);
  });
  it("includes the target of a rename", () => {
    expect(
      selectDeltaScope([{ path: "new" }], {
        complete: true,
        files: [{ path: "new", previousPath: "old", kind: "renamed" }],
      }).included,
    ).toEqual([{ path: "new" }]);
  });
  it("selects nothing when there are no changes", () => {
    expect(
      selectDeltaScope([{ path: "same" }], {
        complete: true,
        files: [{ path: "same", previousPath: "same", kind: "unchanged" }],
      }).included,
    ).toEqual([]);
  });
  it("preserves partial baseline status", () => {
    expect(
      selectDeltaScope([], { complete: false, files: [] }).baselineComplete,
    ).toBe(false);
  });
  it("accounts for budget using only included content", () => {
    const result = selectDeltaScope(
      [
        { path: "changed", bytes: 10 },
        { path: "same", bytes: 20 },
      ],
      {
        complete: true,
        files: [
          { path: "changed", previousPath: "changed", kind: "modified" },
          { path: "same", previousPath: "same", kind: "unchanged" },
        ],
      },
    );
    expect(result.included.reduce((sum, item) => sum + item.bytes, 0)).toBe(10);
  });
});

import { describe, expect, it } from "vitest";

import { normalizeGitDiff, parseGitHistory, runGit } from "@fuzit/git";

describe("Git privacy and determinism golden gate", () => {
  it("sanitizes credentials and missing Git", async () => {
    const credential = "[REDACTED:url-credential]example.test/repo";
    const result = await runGit(
      ["-e", `process.stderr.write(${JSON.stringify(credential)})`],
      { executable: process.execPath },
    );
    expect(result.stderr).not.toContain("password");
    expect((await runGit([], { executable: "fuzit-missing-git" })).ok).toBe(
      false,
    );
  });

  it("bounds history and diff repeatably", () => {
    const record = `${"a".repeat(40)}\u001f\u001fAuthor\u001fa@example.test\u001f2026-01-01T00:00:00Z\u001fsubject\u001e`;
    expect(parseGitHistory(record)).toHaveLength(1);
    const first = normalizeGitDiff("x".repeat(1000), ["b", "a"], {
      maximumBytes: 32,
      maximumFiles: 1,
    });
    expect(first).toEqual(
      normalizeGitDiff("x".repeat(1000), ["b", "a"], {
        maximumBytes: 32,
        maximumFiles: 1,
      }),
    );
    expect(first.truncated).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import { normalizeRepositoryIntelligence } from "../../../packages/core/src/index.js";
const base = {
  languages: ["TypeScript"],
  packages: [],
  frameworks: [],
  tests: [],
  entryPoints: [],
  dependencies: [],
  conflicts: [],
  partial: false,
};
describe("intelligence bundle metadata", () => {
  it("supports no facts", () =>
    expect(
      normalizeRepositoryIntelligence({ ...base, languages: [] }),
    ).toMatchObject({ languages: [], partial: false }));
  it("marks partial adapters", () =>
    expect(
      normalizeRepositoryIntelligence({ ...base, partial: true }).partial,
    ).toBe(true));
  it("preserves conflicts", () =>
    expect(
      normalizeRepositoryIntelligence({ ...base, conflicts: ["a", "b"] })
        .conflicts,
    ).toEqual(["a", "b"]));
  it("is format-neutral structured metadata", () =>
    expect(
      JSON.parse(JSON.stringify(normalizeRepositoryIntelligence(base))),
    ).toEqual(base));
  it("keeps budget metadata separate", () =>
    expect(normalizeRepositoryIntelligence(base)).not.toHaveProperty("budget"));
  it("normalizes polyglot monorepo repository intelligence deterministically", () => {
    const polyglot = normalizeRepositoryIntelligence({
      languages: ["TypeScript", "Python", "Java", "Go"],
      packages: [
        "apps/web:package.json",
        "java:services/backend/pom.xml",
        "go:github.com/example/worker",
        "python:services/api/pyproject.toml",
      ],
      frameworks: ["next", "express", "fastapi", "spring-boot", "gin"],
