      dependencies: [
        "next",
        "express",
        "fastapi",
        "org.springframework.boot:spring-boot-starter-web",
        "github.com/gin-gonic/gin",
      ],
      conflicts: [
        "multiple confirmed server frameworks: express, next",
      ],
      partial: false,
