import { describe, expect, it } from "vitest";
import { buildFilePackageGraph } from "@fuzit/graph";
import type { NormalizedAnalysis } from "@fuzit/schemas";

const repositoryId = `sha256:${"a".repeat(64)}`;
const file = (path: string, index: number) => ({
  id: `analysis:file:${index.toString(16).padStart(64, "0")}`,
  repositoryId,
  kind: "file" as const,
  path,
  language: path.endsWith(".go") ? "go" : "typescript",
  contentHash: `sha256:${index.toString(16).padStart(64, "0")}`,
});
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: [file("apps/web/src/a.ts", 1), file("services/go/main.go", 2)],
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};

describe("file and package graph", () => {
  it("builds deterministic nested polyglot containment and dependencies", () => {
    const packages = [
      {
        name: "root",
        path: ".",
        manifestPath: "package.json",
        dependencies: ["web"],
      },
      {
        name: "web",
        path: "apps/web",
        manifestPath: "apps/web/package.json",
        dependencies: [],
      },
      {
        name: "go",
        path: "services/go",
        manifestPath: "services/go/go.mod",
        dependencies: [],
      },
    ];
    const first = buildFilePackageGraph({ analysis, revision: "r1", packages });
    expect(
      buildFilePackageGraph({
        analysis,
        revision: "r1",
        packages: [...packages].reverse(),
      }),
    ).toEqual(first);
    expect(
      first.nodes
        .filter((node) => node.kind === "file")
        .map((node) => node.parentId),
    ).not.toContain(first.nodes.find((node) => node.kind === "repository")?.id);
  });
  it("reports conflicting manifests and unresolved dependencies", () => {
    const graph = buildFilePackageGraph({
      analysis,
      revision: "r1",
      packages: [
        {
          name: "duplicate",
          path: "apps/a",
          manifestPath: "apps/a/package.json",
          dependencies: ["missing"],
        },
        {
          name: "duplicate",
          path: "apps/b",
          manifestPath: "apps/b/package.json",
          dependencies: [],
        },
      ],
    });
    expect(graph.completeness).toBe("partial");
    expect(graph.diagnostics).toEqual([
      "conflicting package manifest name: duplicate",
    ]);
    expect(graph.edges.some((edge) => edge.resolution === "unresolved")).toBe(
      true,
    );
  });
});

import { describe, expect, it } from "vitest";
import {
  buildFilePackageGraph,
  materializeImportDependencyEdges,
} from "@fuzit/graph";
import type { NormalizedAnalysis } from "@fuzit/schemas";

const repositoryId = `sha256:${"a".repeat(64)}`;
const id = (kind: string, value: string) =>
  `analysis:${kind}:${value.padStart(64, "0")}`;
const file = (path: string, value: string) => ({
  id: id("file", value),
  repositoryId,
  kind: "file" as const,
  path,
  language: "typescript",
  contentHash: `sha256:${value.padStart(64, "0")}`,
});
const provenance = {
  sourceFileId: id("file", "1"),
  sourceSymbolId: null,
  range: null,
  basis: "parsed" as const,
  parserIdentity: "typescript",
  analysisIdentity: "fixture",
  confidence: 1,
  resolution: "resolved" as const,
};

describe("import and dependency edges", () => {
  it("retains cycles, aliases, optional dependencies, and deleted targets", () => {
    const files = [file("a.ts", "1"), file("b.ts", "2")];
    const analysis: NormalizedAnalysis = {
      schemaVersion: 1,
      repositoryId,
      analysisIdentity: "fixture",
      files,
      modules: [],
      symbols: [],
      relationships: [
        {
          id: id("relation", "3"),
          repositoryId,
          kind: "import",
          sourceId: files[0]!.id,
          targetId: files[1]!.id,
          unresolvedTarget: null,
          provenance,
        },
        {
          id: id("relation", "4"),
          repositoryId,
          kind: "import",
          sourceId: files[1]!.id,
          targetId: files[0]!.id,
          unresolvedTarget: null,
          provenance: { ...provenance, sourceFileId: files[1]!.id },
        },
        {
          id: id("relation", "5"),
          repositoryId,
          kind: "import",
          sourceId: files[0]!.id,
          targetId: id("file", "9"),
          unresolvedTarget: "@alias/deleted",
          provenance: { ...provenance, resolution: "unresolved" },
        },
      ],
      completeness: "partial",
      diagnostics: [],
    };
    const base = buildFilePackageGraph({
      analysis,
      revision: "r1",
      packages: [
        {
          name: "a",
          path: ".",
          manifestPath: "package.json",
          dependencies: [{ name: "optional-missing", optional: true }],
        },
      ],
    });
    const graph = materializeImportDependencyEdges(base, analysis, {
      revision: "r1",
      collectorVersion: "1",
    });
    expect(graph.edges.filter((edge) => edge.kind === "imports")).toHaveLength(
      3,
    );
    expect(
      graph.edges.some((edge) => edge.unresolvedTarget === "@alias/deleted"),
    ).toBe(true);
    expect(
      graph.edges.some((edge) =>
        edge.evidence[0]?.reason.includes("optional manifest dependency"),
      ),
    ).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import {
  buildFilePackageGraph,
