        analysisIdentity: "fixture",
        confidence: 1,
        resolution: "resolved",
      },
    },
  ],
  completeness: "complete",
  diagnostics: [],
};

describe("domain graph relations", () => {
  it("adds justified relations without lookalike false positives", () => {
    const base = buildFilePackageGraph({
      analysis,
      revision: "r1",
      packages: [
        {
          name: "root",
          path: ".",
          manifestPath: "package.json",
          dependencies: [],
        },
      ],
    });
    const symbols = materializeSymbolNodes(base, analysis, {
      parserIdentity: "typescript",
      parserVersion: "1",
      revision: "r1",
    });
    const graph = materializeDomainRelations(symbols, analysis, {
      revision: "r1",
      collectorVersion: "1",
    });
    expect(graph.edges.filter((edge) => edge.kind === "tests")).toHaveLength(1);
    expect(
      graph.edges
        .filter((edge) =>
          ["tests", "configures", "references"].includes(edge.kind),
        )
        .some(
          (edge) =>
            edge.evidence[0]?.sourcePath === "src/controller-looking.ts",
        ),
    ).toBe(false);
  });
  it("keeps missing relation sources partial", () => {
    const empty = { ...analysis, symbols: [], relationships: [] };
    const base = buildFilePackageGraph({
      analysis: empty,
      revision: "r1",
      packages: [],
    });
    const result = materializeDomainRelations(
      base,
      {
        ...analysis,
        relationships: [
          {
            ...analysis.relationships[0]!,
            sourceId: `analysis:symbol:${hash(8)}`,
          },
        ],
      },
      { revision: "r1", collectorVersion: "1" },
    );
    expect(result.completeness).toBe("partial");
  });
});

import { describe, expect, it } from "vitest";
import { createGraphEdge, createGraphEdgeId } from "@fuzit/graph";

const repositoryId = `sha256:${"a".repeat(64)}`;
const sourceId = `graph:node:${"b".repeat(64)}`;
const targetId = `graph:node:${"c".repeat(64)}`;
const evidence = (basis: "direct" | "parsed" | "heuristic") => ({
  basis,
  collector: "fixture",
  collectorVersion: "1",
  sourcePath: "src/a.ts",
  reason: `${basis} fixture evidence`,
});
const resolved = (basis: "direct" | "parsed" | "heuristic") => ({
  repositoryId,
  kind: "imports" as const,
  sourceId,
  sourceKind: "file" as const,
  targetId,
  targetKind: "file" as const,
  unresolvedTarget: null,
  resolution: "resolved" as const,
  evidence: [evidence(basis)],
  revision: { validFrom: "r1", validThrough: null },
});

describe("graph edge contracts", () => {
  it.each(["direct", "parsed", "heuristic"] as const)(
    "retains %s evidence",
    (basis) => {
      expect(createGraphEdge(resolved(basis)).evidence[0]?.basis).toBe(basis);
    },
  );

  it("keeps unresolved and conflicting evidence explicit", () => {
    const unresolved = createGraphEdge({
      ...resolved("parsed"),
      targetId: null,
      targetKind: null,
      unresolvedTarget: "@missing/package",
      resolution: "unresolved",
    });
    const conflicting = createGraphEdge({
      ...resolved("direct"),
      kind: "depends-on",
      sourceKind: "package",
      targetKind: "package",
      resolution: "conflicting",
      evidence: [evidence("direct"), evidence("heuristic")],
    });
    expect(unresolved.unresolvedTarget).toBe("@missing/package");
    expect(conflicting.evidence).toHaveLength(2);
  });

  it("rejects invalid directions and keeps stable IDs", () => {
    expect(createGraphEdgeId(repositoryId, "imports", sourceId, targetId)).toBe(
      createGraphEdgeId(repositoryId, "imports", sourceId, targetId),
    );
    expect(() =>
      createGraphEdge({
        ...resolved("direct"),
        kind: "contains",
        sourceKind: "file",
        targetKind: "repository",
      }),
    ).toThrow(/Invalid contains edge direction/u);
  });
});

import { describe, expect, it } from "vitest";
import {
  buildFilePackageGraph,
  materializeLifecycleRelations,
} from "@fuzit/graph";
import type { NormalizedAnalysis } from "@fuzit/schemas";
const repositoryId = `sha256:${"a".repeat(64)}`;
const hash = (n: number) => n.toString(16).padStart(64, "0");
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: ["src/new.ts", "src/peer.ts"].map((path, i) => ({
    id: `analysis:file:${hash(i + 1)}`,
    repositoryId,
    kind: "file",
    path,
    language: "typescript",
    contentHash: `sha256:${hash(i + 3)}`,
  })),
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};
const base = buildFilePackageGraph({ analysis, revision: "r2", packages: [] });

describe("Git lifecycle graph relations", () => {
  it("retains rename, introduction, modification, and changed-with evidence", () => {
    const graph = materializeLifecycleRelations(base, {
      historyAvailable: true,
      shallow: false,
      changes: [
        {
          revision: "r2",
          path: "src/new.ts",
          previousPath: "src/old.ts",
          introduced: true,
          changedWith: ["src/peer.ts"],
        },
      ],
    });
    expect(
      graph.edges.filter((edge) =>
        ["modifies", "introduced-by", "changed-with"].includes(edge.kind),
