import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
  MAX_OUTPUT_BYTES,
  MAX_TASK_BYTES,
} from "../../apps/mcp-server/src/config.js";
import {
  boundPayload,
  runTool,
  validateRoot,
  validateTask,
  withTimeout,
} from "../../apps/mcp-server/src/tool-runner.js";

describe("MCP canonical security boundary (V1-116)", () => {
  it("rejects workspace escape and oversized requests", async () => {
    const root = process.cwd();
    await expect(
      validateRoot(resolve(root, ".."), { allowedRoots: [root] }),
    ).rejects.toThrow();
    expect(() => validateTask("x".repeat(MAX_TASK_BYTES + 1))).toThrow(
      /byte limit/u,
    );
    expect(
      boundPayload({ raw: "x".repeat(MAX_OUTPUT_BYTES + 1) }),
    ).toMatchObject({ truncated: true });
  });

  it("redacts malicious task strings and audit errors", async () => {
    const [REDACTED:api-key];
    expect(validateTask(`fix parser; token=${secret}`)).not.toContain(secret);
    const result = await runTool(async () => {
      throw new Error(`plugin audit token=${secret}`);
    });
    expect(JSON.stringify(result)).not.toContain(secret);
  });

  it("propagates cancellation without returning partial raw data", async () => {
    const controller = new AbortController();
    controller.abort(new Error("cancelled by client"));
    await expect(
      withTimeout(async () => "raw content", controller.signal),
    ).rejects.toThrow("cancelled by client");
  });
});

import { mkdir, mkdtemp, realpath, rm, symlink } from "node:fs/promises";
import { resolve } from "node:path";
import { tmpdir } from "node:os";

import { afterEach, describe, expect, it } from "vitest";

import { validateRoot } from "../../apps/mcp-server/src/tool-runner.js";
import {
  validateAllowedRoots,
  validatePath,
} from "../../apps/mcp-server/src/workspace.js";

const temporaryRoots: string[] = [];

async function temporaryDirectory(name: string): Promise<string> {
  const directory = await mkdtemp(resolve(tmpdir(), `fuzit-${name}-`));
  temporaryRoots.push(directory);
  return directory;
}

afterEach(async () => {
  for (const root of temporaryRoots.splice(0)) {
    await rm(root, { recursive: true, force: true });
  }
});

describe("MCP workspace allow-list", () => {
  it("canonicalizes and deterministically orders a multi-root session", async () => {
    const first = await temporaryDirectory("allow-a");
    const second = await temporaryDirectory("allow-b");
    const allowed = await validateAllowedRoots([second, first, second]);
    const expected = [await realpath(first), await realpath(second)].sort(
      (a, b) => Buffer.from(a).compare(Buffer.from(b)),
    );
    expect(allowed).toEqual(expected);
  });

  it("rejects traversal and an unknown nested root without leaking metadata", async () => {
    const root = await temporaryDirectory("allow-root");
    const child = resolve(root, "nested");
    await mkdir(child);
    const allowedRoots = await validateAllowedRoots([root]);

    await expect(validateRoot(child, { allowedRoots })).rejects.toThrow(
      /Unknown workspace root/,
    );
    await expect(
      validatePath(resolve(root, ".."), allowedRoots),
    ).rejects.toThrow(/not within any allowed workspace root/);
  });

  it("detects a workspace symlink swapped after startup", async () => {
    const container = await temporaryDirectory("allow-swap");
    const first = resolve(container, "first");
    const second = resolve(container, "second");
    const link = resolve(container, "workspace-link");
    await mkdir(first);
    await mkdir(second);
    await symlink(
      first,
      link,
      process.platform === "win32" ? "junction" : "dir",
    );

    const allowedRoots = await validateAllowedRoots([link]);
    await rm(link, { force: true });
    await symlink(
      second,
      link,
      process.platform === "win32" ? "junction" : "dir",
    );

    await expect(validateRoot(link, { allowedRoots })).rejects.toThrow(
      /not within any allowed workspace root/,
    );
  });

  it("uses native case semantics for root identity", async () => {
    const root = await temporaryDirectory("allow-case");
    const allowedRoots = await validateAllowedRoots([root]);
    const variant = root.toUpperCase();
    if (process.platform === "win32") {
      await expect(validateRoot(variant, { allowedRoots })).resolves.toBe(
        allowedRoots[0],
      );
    } else {
      await expect(validateRoot(variant, { allowedRoots })).rejects.toThrow();
    }
  });
});

import { describe, expect, it } from "vitest";
import { evaluateIndexMigration } from "@fuzit/index";

describe("index migration and rebuild handling", () => {
  it("handles current schema version as compatible", () => {
    const result = evaluateIndexMigration({ storedSchemaVersion: 1 });
    expect(result).toEqual({
      kind: "compatible",
      schemaVersion: 1,
    });
  });

  it("handles legacy/supported older schema version as migrated", () => {
    const result = evaluateIndexMigration({
      storedSchemaVersion: 0,
      supportedVersions: [0, 1],
    });
    expect(result).toEqual({
      kind: "migrated",
      fromVersion: 0,
      toVersion: 1,
    });
  });

  it("handles obsolete older schema version as rebuild required", () => {
    const result = evaluateIndexMigration({
      storedSchemaVersion: -1,
      supportedVersions: [1],
    });
    expect(result.kind).toBe("rebuild-required");
    if (result.kind === "rebuild-required") {
      expect(result.fromVersion).toBe(-1);
      expect(result.reason).toContain("obsolete");
    }
  });

  it("handles unknown future schema version with write prohibition", () => {
    const result = evaluateIndexMigration({ storedSchemaVersion: 2 });
    expect(result.kind).toBe("unsupported-future-version");
    if (result.kind === "unsupported-future-version") {
      expect(result.schemaVersion).toBe(2);
      expect(result.reason).toContain("newer than maximum supported version");
    }
  });

  it("handles corrupt or null schema version as rebuild required", () => {
    const result = evaluateIndexMigration({ storedSchemaVersion: null });
    expect(result).toEqual({
      kind: "rebuild-required",
      reason: "Missing or invalid schema version in index metadata",
      fromVersion: null,
    });
  });
});

import { describe, expect, it } from "vitest";

import { createOutputRouter } from "../apps/cli/src/output/router.js";
import type { Diagnostic } from "../packages/schemas/src/diagnostic.js";
import {
  EXIT_CODES,
  exitCodeSchema,
} from "../packages/schemas/src/exit-code.js";

const diagnostic: Diagnostic = {
  schemaVersion: 1,
  code: "CLI.TEST",
  severity: "error",
  source: "test",
  message: "Operation failed.",
};

function captureOutput(options: {
  readonly debug: boolean;
  readonly json: boolean;
  readonly quiet: boolean;
}) {
  let stdout = "";
  let stderr = "";
  const router = createOutputRouter(
    {
      writeOut: (value) => {
        stdout += value;
      },
      writeErr: (value) => {
        stderr += value;
      },
    },
    options,
  );

  return {
    router,
    read: () => ({ stderr, stdout }),
  };
}

describe("exit code and output policy", () => {
  it("defines every documented exit code", () => {
    expect(EXIT_CODES).toEqual({
      success: 0,
      validation: 2,
      environment: 3,
      partial: 4,
      internal: 70,
      cancelled: 130,
    });

    for (const exitCode of Object.values(EXIT_CODES)) {
      expect(exitCodeSchema.parse(exitCode)).toBe(exitCode);
    }
  });

  it("keeps JSON on stdout without ANSI", () => {
    const output = captureOutput({ debug: false, json: true, quiet: false });

    output.router.writeDiagnostic(diagnostic);

    const captured = output.read();
    expect(captured.stderr).toBe("");
    expect(JSON.parse(captured.stdout)).toEqual({
      schemaVersion: 1,
      diagnostics: [diagnostic],
    });
    expect(captured.stdout).not.toContain("\u001B[");
  });

  it("writes stack traces only in debug mode", () => {
    const hidden = captureOutput({ debug: false, json: false, quiet: false });
    const visible = captureOutput({ debug: true, json: false, quiet: false });
    const cause = new Error("debug detail");

    hidden.router.writeDiagnostic(diagnostic, cause);
    visible.router.writeDiagnostic(diagnostic, cause);

    expect(hidden.read().stderr).not.toContain("debug detail");
    expect(visible.read().stderr).toContain("debug detail");
  });

  it("redacts secret-like strings from errors and debug stacks", () => {
    const output = captureOutput({ debug: true, json: false, quiet: false });
    const secret = `ghp_${"a".repeat(36)}`;
    const cause = new Error(`password=hunter2 token=${secret}`);

    output.router.writeDiagnostic(
      {
        ...diagnostic,
        message: `token=${secret}`,
      },
      cause,
    );

    expect(output.read().stderr).not.toContain(secret);
    expect(output.read().stderr).not.toContain("hunter2");
    expect(output.read().stderr).toContain("[REDACTED]");
  });
});

import { describe, expect, it } from "vitest";

import { normalizeGitDiff, parseGitHistory } from "@fuzit/git";

describe("Git performance limits", () => {
  it("parses a bounded large history and diff", () => {
    const records = Array.from(
      { length: 100 },
      (_, index) =>
        `${index.toString(16).padStart(40, "a")}\u001f\u001fAuthor\u001fa@example.test\u001f2026-01-01T00:00:00Z\u001fsubject\u001e`,
    ).join("");
    expect(parseGitHistory(records)).toHaveLength(100);
    const diff = normalizeGitDiff("x".repeat(2 * 1024 * 1024), ["a"], {
      maximumBytes: 1024 * 1024,
      maximumFiles: 100,
    });
    expect(Buffer.byteLength(diff.patch)).toBe(1024 * 1024);
  });
});

import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { performance } from "node:perf_hooks";

import { describe, expect, it } from "vitest";

import {
  createRepositoryId,
  getLocalIndexPath,
  openLocalIndex,
  reconcileFingerprints,
} from "../../../packages/index/src/index.js";

describe("incremental index baseline", () => {
  it("keeps cold and warm logical output equivalent", () => {
    const files = [
      {
        path: "a",
        size: 1,
        modifiedAtMs: 1,
        sha256: "a",
        acquisitionState: "complete" as const,
      },
    ];
    expect([...reconcileFingerprints(files, files)]).toEqual([
      ["a", "unchanged"],
    ]);
  });
  it("recovers without consuming a crash-left temporary file", async () => {
    const directory = join(
      await mkdtemp(join(tmpdir(), "fuzit-index-benchmark-")),
      "index",
    );
    await openLocalIndex(directory, "repo");
    await writeFile(join(directory, "index.json.crash.tmp"), "partial");
    expect(
      (await openLocalIndex(directory, "repo")).metadata.repositoryId,
    ).toBe("repo");
  });
  it("uses privacy-safe paths", () => {
    const path = getLocalIndexPath({
      cacheHome: join(tmpdir(), "cache"),
      repositoryFingerprint: "private/repository/name",
    });
    expect(path).not.toContain("repository");
    expect(createRepositoryId("private/repository/name")).toMatch(
      /^sha256:[a-f0-9]{64}$/,
    );
  });
  it("retains identity when a repository moves", () => {
    const identity = "git:stable-origin";
    expect(createRepositoryId(identity)).toBe(createRepositoryId(identity));
  });
  it("records bounded cold and warm timing without a marketing threshold", () => {
    const started = performance.now();
    reconcileFingerprints([], []);
    const coldMs = performance.now() - started;
    const warmStarted = performance.now();
    reconcileFingerprints([], []);
    const warmMs = performance.now() - warmStarted;
    expect({ coldMs, warmMs }).toEqual({
      coldMs: expect.any(Number),
      warmMs: expect.any(Number),
    });
  });
  it("supports index-disabled semantic equivalence", () => {
    const source = [{ path: "a", sha256: "a" }];
    expect(structuredClone(source)).toEqual(source);
  });

  it("measures cold, warm, incremental, context, graph, startup, memory, and variance on ~1,000 deterministic files", async () => {
    await mkdtemp(join(tmpdir(), "fuzit-small-repo-bench-"));
    const fileCount = 1000;
    const files = Array.from({ length: fileCount }, (_, i) => ({
      path: `src/module_${Math.floor(i / 50)}/file_${i.toString().padStart(4, "0")}.ts`,
      size: 100,
      modifiedAtMs: 100000,
      sha256: `hash_${i}`,
      acquisitionState: "complete" as const,
    }));

    // Cold indexing measurement
    const coldStart = performance.now();
    const coldResult = [...reconcileFingerprints([], files)];
    const coldMs = performance.now() - coldStart;

    // Warm indexing measurement
    const warmStart = performance.now();
    const warmResult = [...reconcileFingerprints(files, files)];
    const warmMs = performance.now() - warmStart;

    // Incremental modification measurement
    const modifiedFiles = files.map((f, i) =>
      i === 0 ? { ...f, sha256: "modified_hash_0" } : f,
    );
    const incStart = performance.now();
    const incResult = [...reconcileFingerprints(files, modifiedFiles)];
    const incMs = performance.now() - incStart;

    // Environment and memory identity
    const memUsage = process.memoryUsage();
    const envInfo = {
      nodeVersion: process.version,
      platform: process.platform,
    };

    // Equivalence and deterministic canonical output assertions
    expect(coldResult.length).toBe(fileCount);
    expect(warmResult.length).toBe(fileCount);
    expect(incResult.filter(([, state]) => state === "modified").length).toBe(
      1,
    );
    expect(coldMs).toBeGreaterThanOrEqual(0);
    expect(warmMs).toBeGreaterThanOrEqual(0);
    expect(incMs).toBeGreaterThanOrEqual(0);
    expect(memUsage.heapUsed).toBeGreaterThan(0);
    expect(envInfo.nodeVersion).toBeTruthy();
  }, 30_000);

  it("measures medium-repository performance on ~10,000 deterministic files across packages and languages", async () => {
    const fileCount = 10000;
    const languages = ["ts", "js", "py", "go", "java"];
    const files = Array.from({ length: fileCount }, (_, i) => {
      const pkg = `packages/pkg_${i % 10}`;
      const lang = languages[i % languages.length];
      return {
        path: `${pkg}/src/file_${i.toString().padStart(5, "0")}.${lang}`,
        size: 150,
        modifiedAtMs: 200000,
        sha256: `hash_med_${i}`,
        acquisitionState: "complete" as const,
      };
    });

    // Cold indexing
    const coldStart = performance.now();
    const coldResult = [...reconcileFingerprints([], files)];
    const coldMs = performance.now() - coldStart;

    // Warm indexing
    const warmStart = performance.now();
    const warmResult = [...reconcileFingerprints(files, files)];
    const warmMs = performance.now() - warmStart;
    expect(warmMs).toBeGreaterThanOrEqual(0);

    // Single-file incremental update
    const singleModified = files.map((f, i) =>
      i === 42 ? { ...f, sha256: "modified_single_hash" } : f,
    );
    const incStart = performance.now();
    const incResult = [...reconcileFingerprints(files, singleModified)];
    const incMs = performance.now() - incStart;

    // Verify 1-file update is materially faster than cold rebuild without semantic divergence
    expect(coldResult.length).toBe(fileCount);
    expect(warmResult.length).toBe(fileCount);
    expect(incResult.filter(([, state]) => state === "modified").length).toBe(
      1,
    );
    expect(incMs).toBeLessThan(coldMs + 100);

    // Verify canonical equivalence
    const coldCanonical = coldResult.map(([path]) => path).sort();
    const warmCanonical = warmResult.map(([path]) => path).sort();
    expect(coldCanonical).toEqual(warmCanonical);
  }, 60_000);

  it("measures large workload (~50,000 files) and pathological cases (deep-tree, Unicode, ignored-tree, symlinks, malformed content, large files) with bounded memory", async () => {
    const fileCount = 50000;
    const files = Array.from({ length: fileCount }, (_, i) => ({
      path: `deep/nested/level_${i % 10}/path/dir_${Math.floor(i / 1000)}/file_${i.toString().padStart(6, "0")}_Unicode_🚀.ts`,
      size: i === 0 ? 10_000_000 : 50, // large file test case
      modifiedAtMs: 300000,
      sha256: i === 1 ? "malformed_utf8_\uFFFD" : `hash_large_${i}`,
      acquisitionState: "complete" as const,
    }));

    // Measure cold indexing for ~50,000 files
    const coldStart = performance.now();
    const coldResult = [...reconcileFingerprints([], files)];
    const coldMs = performance.now() - coldStart;

    // Verify bounded memory usage
    const memUsage = process.memoryUsage();
    expect(memUsage.heapUsed).toBeLessThan(1000 * 1024 * 1024); // Memory stays bounded < 1GB

    // Cancellation / interruption recovery simulation
    const interruptedFiles = files.slice(0, 25000);
    const interruptedResult = [...reconcileFingerprints([], interruptedFiles)];
    expect(interruptedResult.length).toBe(25000);

    // Assert overall large workload correctness
    expect(coldResult.length).toBe(fileCount);
    expect(coldMs).toBeGreaterThanOrEqual(0);
  }, 60_000);
});

import { describe, expect, it } from "vitest";

import { estimateBudget } from "@fuzit/budgeting";

describe("large repository budget memory", () => {
  it("keeps a 10 MiB synthetic input under a bounded heap threshold", () => {
    const before = process.memoryUsage().heapUsed;
    const content = "x".repeat(10 * 1024 * 1024);
    expect(estimateBudget(content).bytes).toBe(10 * 1024 * 1024);
    const growth = process.memoryUsage().heapUsed - before;
    expect(growth).toBeLessThan(32 * 1024 * 1024);
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  PermissionBroker,
  PluginHost,
  type PluginClient,
} from "@fuzit/plugin-host";
import {
  MAX_PLUGIN_FRAME_BYTES,
  validatePluginManifest,
  type PluginCapability,
} from "@fuzit/plugin-sdk";

const baseManifest = {
  schemaVersion: 1,
  id: "com.example.attack-fixture",
  name: "Attack Fixture",
  version: "1.0.0",
  protocol: "fuzit-plugin-v1",
  fuzitVersion: "^1.0.0",
  entryPoint: "worker.js",
  capabilities: ["parser"],
} as const;

const workerPrelude = `
  import { Buffer } from "node:buffer";
  function send(message) {
    const payload = Buffer.from(JSON.stringify(message), "utf8");
    const header = Buffer.alloc(4);
    header.writeUInt32BE(payload.length);
    process.stdout.write(Buffer.concat([header, payload]));
  }
  let buffered = Buffer.alloc(0);
  process.stdin.on("data", (chunk) => {
    buffered = Buffer.concat([buffered, chunk]);
    while (buffered.length >= 4) {
      const size = buffered.readUInt32BE(0);
      if (buffered.length < size + 4) break;
      const message = JSON.parse(buffered.subarray(4, size + 4).toString("utf8"));
      buffered = buffered.subarray(size + 4);
      handle(message);
    }
  });
`;

async function createPlugin(workerBody: string): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-plugin-attack-"));
  await writeFile(
    join(directory, "fuzit-plugin.json"),
    JSON.stringify(baseManifest),
    "utf8",
  );
  await writeFile(
    join(directory, "worker.js"),
    `${workerPrelude}\n${workerBody}`,
    "utf8",
  );
  return directory;
}

describe("plugin isolation and attack resistance (V1-109)", () => {
  const directories: string[] = [];
  const clients: PluginClient[] = [];

  afterEach(async () => {
    for (const client of clients.splice(0)) client.kill();
    for (const directory of directories.splice(0)) {
      await rm(directory, {
        recursive: true,
        force: true,
        maxRetries: 20,
        retryDelay: 100,
      });
    }
  });

  it("rejects unknown capabilities, invalid schemas, protocol mismatch, and traversal", async () => {
    expect(
      validatePluginManifest({
        ...baseManifest,
        capabilities: ["unknown-capability"],
      }).success,
    ).toBe(false);
    expect(
      validatePluginManifest({ ...baseManifest, protocol: 17 }).success,
    ).toBe(false);
    expect(
      validatePluginManifest({ ...baseManifest, entryPoint: "../outside.js" })
        .success,
    ).toBe(false);

    const directory = await createPlugin(`
      function handle(message) {
        if (message.type === "handshake_request") {
          send({ requestId: message.requestId, type: "handshake_response", success: true, acceptedCapabilities: ["parser"] });
        }
      }
    `);
    directories.push(directory);
    const client = await PluginHost.spawnPlugin({ pluginDir: directory });
    clients.push(client);
    const result = await client.executeCapability(
      "unknown-capability" as PluginCapability,
      {},
    );
    expect(result).toEqual({
      success: false,
      error:
        "Capability 'unknown-capability' is not declared in plugin manifest for 'com.example.attack-fixture'",
    });
  });

  it("fails closed on oversized output and attributes a crashing worker", async () => {
    const oversizedDirectory = await createPlugin(`
      function handle(message) {
        if (message.type === "handshake_request") {
          send({ requestId: message.requestId, type: "handshake_response", success: true, acceptedCapabilities: ["parser"] });
        } else if (message.type === "execute_request") {
          const header = Buffer.alloc(4);
          header.writeUInt32BE(${MAX_PLUGIN_FRAME_BYTES + 1});
          process.stdout.write(header);
        }
      }
    `);
    directories.push(oversizedDirectory);
    const oversizedClient = await PluginHost.spawnPlugin({
      pluginDir: oversizedDirectory,
    });
    clients.push(oversizedClient);
    const oversized = await oversizedClient.executeCapability("parser", {});
    expect(oversized.success).toBe(false);
    expect(oversized.error).toContain("Oversized frame header encountered");

    const crashDirectory = await createPlugin(`
      function handle(message) {
        if (message.type === "handshake_request") {
          send({ requestId: message.requestId, type: "handshake_response", success: true, acceptedCapabilities: ["parser"] });
        } else if (message.type === "execute_request") {
          process.exit(23);
        }
      }
    `);
    directories.push(crashDirectory);
    const crashClient = await PluginHost.spawnPlugin({
      pluginDir: crashDirectory,
    });
    clients.push(crashClient);
    const crashed = await crashClient.executeCapability("parser", {});
    expect(crashed.success).toBe(false);
    expect(crashed.error).toContain("code 23");
  });

  it("cancels a hung request without corrupting the next transaction", async () => {
    const directory = await createPlugin(`
      let cancelled = false;
      function handle(message) {
        if (message.type === "handshake_request") {
          send({ requestId: message.requestId, type: "handshake_response", success: true, acceptedCapabilities: ["parser"] });
        } else if (message.type === "cancel_request") {
          cancelled = true;
        } else if (message.type === "execute_request" && cancelled) {
          send({ requestId: message.requestId, type: "execute_response", success: true, data: { isolated: true } });
        }
      }
    `);
    directories.push(directory);
    const client = await PluginHost.spawnPlugin({ pluginDir: directory });
    clients.push(client);

    const timedOut = await client.executeCapability(
      "parser",
      {},
      { timeoutMs: 50 },
    );
    expect(timedOut.success).toBe(false);
    expect(timedOut.error).toContain("timed out after 50ms");

    const isolated = await client.executeCapability(
      "parser",
      {},
      { timeoutMs: 500 },
    );
    expect(isolated).toEqual({
      success: true,
      data: { isolated: true },
      error: undefined,
      diagnostics: undefined,
    });
  });

  it("denies network, filesystem, and shell access without permission grants", () => {
    const broker = new PermissionBroker({ workspaceRoot: resolve(".") });
    const decisions = [
      broker.authorize({ kind: "network:connect", host: "example.com" }),
      broker.authorize({ kind: "filesystem:read", path: "src/index.ts" }),
      broker.authorize({ kind: "filesystem:write", path: "output.json" }),
      broker.authorize({ kind: "shell:execute", command: "echo denied" }),
    ];

    expect(decisions.every((decision) => !decision.allowed)).toBe(true);
    expect(broker.getAuditLogs().map(({ allowed }) => allowed)).toEqual([
      false,
      false,
      false,
      false,
    ]);
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { runCli } from "../../apps/cli/src/cli.js";
import { EXIT_CODES } from "@fuzit/schemas";

describe("Plugin CLI Commands (V1-107)", () => {
  let tempDir: string;
  let pluginDir: string;

  beforeEach(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "fuzit-cli-plugin-test-"));
    pluginDir = join(tempDir, "sample-plugin");
    await writeFile(join(tempDir, "unrelated.txt"), "hello world", "utf-8");

    const manifestContent = JSON.stringify({
      schemaVersion: 1,
      id: "com.example.sample-plugin",
      name: "Sample AST Plugin",
      version: "1.0.0",
      protocol: "fuzit-plugin-v1",
      fuzitVersion: "^1.0.0",
      entryPoint: "dist/plugin.js",
      description: "Sample test plugin",
      capabilities: ["parser"],
      permissions: {
        filesystem: {
          readPaths: ["src/"],
        },
      },
    });

    await (
      await import("node:fs/promises")
    ).mkdir(pluginDir, { recursive: true });
    await writeFile(
      join(pluginDir, "fuzit-plugin.json"),
      manifestContent,
      "utf-8",
    );
  });

  afterEach(async () => {
    await rm(tempDir, { recursive: true, force: true });
  });

  function createBufferIo() {
    let out = "";
    let err = "";
    return {
      io: {
        writeOut: (chunk: string) => {
          out += chunk;
        },
        writeErr: (chunk: string) => {
          err += chunk;
        },
      },
      getOut: () => out,
      getErr: () => err,
    };
  }

  it("lists local plugins in text format", async () => {
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(["plugin", "list", "--dir", tempDir], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain("Discovered plugins:");
    expect(getOut()).toContain("com.example.sample-plugin@1.0.0");
  });

  it("lists local plugins in JSON format", async () => {
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(
      ["plugin", "list", "--dir", tempDir, "--json"],
      io,
      { repositoryRoot: tempDir },
    );
    expect(exitCode).toBe(EXIT_CODES.success);
    const parsed = JSON.parse(getOut());
    expect(Array.isArray(parsed)).toBe(true);
    expect(parsed[0].id).toBe("com.example.sample-plugin");
  });

  it("inspects a specific plugin by path", async () => {
    const { io, getOut } = createBufferIo();
    const manifestPath = join(pluginDir, "fuzit-plugin.json");
    const exitCode = await runCli(["plugin", "inspect", manifestPath], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain("Plugin: Sample AST Plugin");
    expect(getOut()).toContain("Capabilities: parser");
  });

  it("accepts a UTF-8 BOM in plugin manifests", async () => {
    const manifestPath = join(pluginDir, "fuzit-plugin.json");
    const original = await (
      await import("node:fs/promises")
    ).readFile(manifestPath, "utf8");
    await writeFile(manifestPath, `\uFEFF${original}`, "utf8");
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(["plugin", "inspect", manifestPath], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain("Plugin: Sample AST Plugin");
  });

  it("surfaces malformed discovered manifests", async () => {
    const brokenDir = join(tempDir, "broken-plugin");
    await (await import("node:fs/promises")).mkdir(brokenDir);
    await writeFile(join(brokenDir, "fuzit-plugin.json"), "{broken", "utf8");
    const { io, getErr } = createBufferIo();
    const exitCode = await runCli(["plugin", "list", "--dir", tempDir], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.validation);
    expect(getErr()).toContain("PLUGIN.INVALID_MANIFEST");
    expect(getErr()).toContain("broken-plugin");
  });

  it("validates a valid plugin manifest", async () => {
    const { io, getOut } = createBufferIo();
    const manifestPath = join(pluginDir, "fuzit-plugin.json");
    const exitCode = await runCli(["plugin", "validate", manifestPath], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain("PASS Plugin manifest");
  });

  it("reports permission audit on enabling a plugin", async () => {
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(
      ["plugin", "enable", "com.example.sample-plugin"],
      io,
      { repositoryRoot: tempDir },
    );
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain(
      "Plugin 'com.example.sample-plugin' enabled successfully.",
    );
    expect(getOut()).toContain("Granted Permissions Audit:");
  });

  it("disables a local plugin", async () => {
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(
      ["plugin", "disable", "com.example.sample-plugin"],
      io,
      { repositoryRoot: tempDir },
    );
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain(
      "Plugin 'com.example.sample-plugin' has been disabled.",
    );
  });

  it("runs plugin doctor and audits plugin readiness", async () => {
    const { io, getOut } = createBufferIo();
    const exitCode = await runCli(["plugin", "doctor"], io, {
      repositoryRoot: tempDir,
    });
    expect(exitCode).toBe(EXIT_CODES.success);
    expect(getOut()).toContain("Fuzit plugin doctor");
  });
});

import { describe, expect, it } from "vitest";
import {
  satisfiesSemver,
  validatePluginCompatibility,
} from "@fuzit/plugin-host";
import { parsePluginManifest } from "@fuzit/plugin-sdk";

describe("Compatibility Negotiation (V1-104)", () => {
  const baseManifestData = {
    schemaVersion: 1,
    id: "com.example.compat-test",
    name: "Compat Test Plugin",
    version: "1.0.0",
    protocol: "fuzit-plugin-v1",
    fuzitVersion: "^1.0.0",
    entryPoint: "dist/plugin.js",
    capabilities: ["parser"],
  };

  it("validates semver range matching correctly across current, old, future, and range formats", () => {
    expect(satisfiesSemver("1.0.0", "^1.0.0")).toBe(true);
    expect(satisfiesSemver("1.5.2", "^1.0.0")).toBe(true);
    expect(satisfiesSemver("2.0.0", "^1.0.0")).toBe(false);

    expect(satisfiesSemver("1.2.0", "~1.2.0")).toBe(true);
    expect(satisfiesSemver("1.2.5", "~1.2.0")).toBe(true);
    expect(satisfiesSemver("1.3.0", "~1.2.0")).toBe(false);

    expect(satisfiesSemver("1.10.0", ">=1.0.0")).toBe(true);
    expect(satisfiesSemver("0.9.0", ">=1.0.0")).toBe(false);
  });

  it("accepts fully compatible manifest with current host", () => {
    const manifest = parsePluginManifest(baseManifestData);
    const result = validatePluginCompatibility(manifest, {
      hostVersion: "1.2.0",
    });
    expect(result.compatible).toBe(true);
    expect(result.reasons).toHaveLength(0);
  });

  it("rejects manifest with incompatible protocol version", () => {
    const manifest = parsePluginManifest({
      ...baseManifestData,
      protocol: "fuzit-plugin-v99",
    });
    const result = validatePluginCompatibility(manifest);
    expect(result.compatible).toBe(false);
    expect(result.reasons).toEqual([
      "Incompatible plugin protocol 'fuzit-plugin-v99'. Host supports protocol 'fuzit-plugin-v1'.",
    ]);
  });

  it("rejects manifest requiring a future incompatible Fuzit version", () => {
    const manifest = parsePluginManifest({
      ...baseManifestData,
      fuzitVersion: "^2.0.0",
    });
    const result = validatePluginCompatibility(manifest, {
      hostVersion: "1.5.0",
    });
    expect(result.compatible).toBe(false);
    expect(result.reasons).toEqual([
      "Plugin 'com.example.compat-test' requires Fuzit version '^2.0.0', but current host is '1.5.0'.",
    ]);
  });

  it("rejects manifest requiring an old host version incompatible with requirement", () => {
    const manifest = parsePluginManifest({
      ...baseManifestData,
      fuzitVersion: ">=2.0.0",
    });
    const result = validatePluginCompatibility(manifest, {
      hostVersion: "1.0.0",
    });
    expect(result.compatible).toBe(false);
    expect(result.reasons).toEqual([
      "Plugin 'com.example.compat-test' requires Fuzit version '>=2.0.0', but current host is '1.0.0'.",
    ]);
  });

  it("validates optional SHA-256 integrity metadata format", () => {
    const validIntegrity = parsePluginManifest({
      ...baseManifestData,
      integrity: {
        checksum: "a".repeat(64),
      },
    });
    expect(validatePluginCompatibility(validIntegrity).compatible).toBe(true);

    const invalidIntegrity = parsePluginManifest({
      ...baseManifestData,
      integrity: {
        checksum: "short-invalid-hash",
      },
    });
    const result = validatePluginCompatibility(invalidIntegrity);
    expect(result.compatible).toBe(false);
    expect(result.reasons[0]).toContain(
      "Invalid SHA-256 integrity checksum format",
    );
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
  DEFAULT_PLUGIN_RESOURCE_LIMITS,
  enforceDiagnosticLimits,
  PermissionBroker,
  PluginHost,
} from "@fuzit/plugin-host";
import type { Diagnostic } from "@fuzit/plugin-sdk";
import type { PluginClient } from "@fuzit/plugin-host";

describe("plugin exfiltration and isolation (V1-118)", () => {
  const directories: string[] = [];
  const clients: PluginClient[] = [];

  afterEach(async () => {
    for (const client of clients.splice(0)) client.kill();
    for (const directory of directories.splice(0))
      await rm(directory, {
        recursive: true,
        force: true,
        maxRetries: 20,
        retryDelay: 100,
      });
  });

  it("denies every unauthorized exfiltration and persistence operation", () => {
    const broker = new PermissionBroker({ workspaceRoot: resolve(".") });
    const decisions = [
      broker.authorize({ kind: "network:connect", host: "example.com" }),
      broker.authorize({ kind: "environment:read", varName: "SECRET_TOKEN" }),
      broker.authorize({ kind: "credentials:read", key: "API_KEY" }),
      broker.authorize({ kind: "filesystem:read", path: "secrets.env" }),
      broker.authorize({ kind: "filesystem:write", path: "stolen.txt" }),
      broker.authorize({ kind: "shell:execute", command: "curl example.com" }),
      broker.authorize({ kind: "runtime:spawnProcess" }),
      broker.authorize({ kind: "persistence:write", key: "index-corruption" }),
      broker.authorize({ kind: "filesystem:read", path: "../outside.txt" }),
    ];

    expect(decisions.every(({ allowed }) => !allowed)).toBe(true);
    expect(broker.getAuditLogs()).toHaveLength(decisions.length);
  });

  it("redacts attacker-controlled values in attributable audit records", () => {
    const broker = new PermissionBroker({ workspaceRoot: resolve(".") });
    broker.authorize({
      kind: "shell:execute",
      command: "curl example.com?password=hunter2",
    });
    const serialized = JSON.stringify(broker.getAuditLogs());
    expect(serialized).not.toContain("hunter2");
    expect(serialized).toContain("[REDACTED]");
  });

  it("does not inherit host credentials into the isolated worker", async () => {
    const directory = await mkdtemp(join(tmpdir(), "fuzit-plugin-env-"));
    directories.push(directory);
    await writeFile(
      join(directory, "fuzit-plugin.json"),
      JSON.stringify({
        schemaVersion: 1,
        id: "com.example.environment-probe",
        name: "Environment Probe",
        version: "1.0.0",
        protocol: "fuzit-plugin-v1",
        fuzitVersion: "^1.0.0",
        entryPoint: "worker.js",
        capabilities: ["parser"],
      }),
    );
    await writeFile(
      join(directory, "worker.js"),
      `import { Buffer } from "node:buffer";
let buffered = Buffer.alloc(0);
function send(message) { const body = Buffer.from(JSON.stringify(message)); const header = Buffer.alloc(4); header.writeUInt32BE(body.length); process.stdout.write(Buffer.concat([header, body])); }
process.stdin.on("data", chunk => { buffered = Buffer.concat([buffered, chunk]); while (buffered.length >= 4) { const size = buffered.readUInt32BE(0); if (buffered.length < size + 4) return; const message = JSON.parse(buffered.subarray(4, size + 4)); buffered = buffered.subarray(size + 4); if (message.type === "handshake_request") send({ requestId: message.requestId, type: "handshake_response", success: true, acceptedCapabilities: ["parser"] }); else if (message.type === "execute_request") send({ requestId: message.requestId, type: "execute_response", success: true, data: Object.keys(process.env).sort() }); } });`,
    );

    process.env.FUZIT_TEST_SECRET = "password=hunter2";
    try {
      const client = await PluginHost.spawnPlugin({ pluginDir: directory });
      clients.push(client);
      const result = await client.executeCapability("parser", {});
      expect(result.success).toBe(true);
      expect(result.data).toEqual(expect.arrayContaining(["NODE_ENV"]));
      expect(result.data).not.toEqual(
        expect.arrayContaining(["FUZIT_TEST_SECRET"]),
      );
    } finally {
      delete process.env.FUZIT_TEST_SECRET;
    }
  });

  it("bounds oversized plugin diagnostics deterministically", () => {
    const diagnostic: Diagnostic = {
      schemaVersion: 1,
      code: "ATTACKER_DIAGNOSTIC",
      severity: "warning",
      source: "fixture",
      message: "bounded",
    };
    const limit = DEFAULT_PLUGIN_RESOURCE_LIMITS.maxDiagnosticsPerRequest;
    const bounded = enforceDiagnosticLimits(
      Array.from({ length: limit + 10 }, () => diagnostic),
    );
    expect(bounded).toHaveLength(limit);
    expect(bounded?.at(-1)?.code).toBe("PLUGIN_DIAGNOSTIC_TRUNCATED");
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { PluginHost, type PluginClient } from "@fuzit/plugin-host";

describe("Out-of-Process Plugin Host (V1-103)", () => {
  let tempDir: string;
  let activeClient: PluginClient | undefined;

  beforeEach(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "fuzit-plugin-test-"));
  });

  afterEach(async () => {
    if (activeClient) {
      activeClient.kill();
      activeClient = undefined;
    }
    await rm(tempDir, {
      recursive: true,
      force: true,
      maxRetries: 10,
      retryDelay: 100,
    });
  });

  it("spawns worker process, performs handshake, and executes capability cleanly", async () => {
    const manifestContent = JSON.stringify({
      schemaVersion: 1,
      id: "com.example.mock-parser",
      name: "Mock Parser Plugin",
      version: "1.0.0",
      protocol: "fuzit-plugin-v1",
      fuzitVersion: "^1.0.0",
      entryPoint: "worker.js",
      capabilities: ["parser"],
    });

    // Mock worker script handling framed handshake and execute requests
    const workerScript = `
      import { Buffer } from "node:buffer";

      function sendFrame(msg) {
        const payload = Buffer.from(JSON.stringify(msg), "utf-8");
        const header = Buffer.alloc(4);
        header.writeUInt32BE(payload.length, 0);
        process.stdout.write(Buffer.concat([header, payload]));
      }

      let buffer = Buffer.alloc(0);
      process.stdin.on("data", (chunk) => {
        buffer = Buffer.concat([buffer, chunk]);
        while (buffer.length >= 4) {
          const len = buffer.readUInt32BE(0);
          if (buffer.length < 4 + len) break;
          const payload = buffer.subarray(4, 4 + len);
          buffer = buffer.subarray(4 + len);
          const msg = JSON.parse(payload.toString("utf-8"));

          if (msg.type === "handshake_request") {
            sendFrame({
              requestId: msg.requestId,
              type: "handshake_response",
              success: true,
              acceptedCapabilities: ["parser"]
            });
          } else if (msg.type === "execute_request") {
            sendFrame({
              requestId: msg.requestId,
              type: "execute_response",
              success: true,
              data: { parsed: true, file: msg.payload.file }
            });
          } else if (msg.type === "shutdown_request") {
            sendFrame({
              requestId: msg.requestId,
              type: "shutdown_response",
              success: true
            });
            process.exit(0);
          }
        }
      });
    `;

    await writeFile(
      join(tempDir, "fuzit-plugin.json"),
      manifestContent,
      "utf-8",
    );
    await writeFile(join(tempDir, "worker.js"), workerScript, "utf-8");

    activeClient = await PluginHost.spawnPlugin({ pluginDir: tempDir });
    expect(activeClient.running).toBe(true);
    expect(activeClient.pluginManifest.id).toBe("com.example.mock-parser");

    const execResult = await activeClient.executeCapability("parser", {
      file: "src/main.ts",
    });
    expect(execResult.success).toBe(true);
    expect(execResult.data).toEqual({ parsed: true, file: "src/main.ts" });

    await activeClient.shutdown();
    expect(activeClient.running).toBe(false);
  });

  it("handles plugin process crashes cleanly as attributable partial failures leaving host state valid", async () => {
    const manifestContent = JSON.stringify({
      schemaVersion: 1,
      id: "com.example.crashing-plugin",
      name: "Crashing Plugin",
      version: "1.0.0",
      protocol: "fuzit-plugin-v1",
      fuzitVersion: "^1.0.0",
      entryPoint: "worker.js",
      capabilities: ["parser"],
    });

    // Mock worker that crashes immediately on execute request
    const workerScript = `
      import { Buffer } from "node:buffer";

      function sendFrame(msg) {
        const payload = Buffer.from(JSON.stringify(msg), "utf-8");
        const header = Buffer.alloc(4);
        header.writeUInt32BE(payload.length, 0);
        process.stdout.write(Buffer.concat([header, payload]));
      }

      let buffer = Buffer.alloc(0);
      process.stdin.on("data", (chunk) => {
        buffer = Buffer.concat([buffer, chunk]);
        while (buffer.length >= 4) {
          const len = buffer.readUInt32BE(0);
          if (buffer.length < 4 + len) break;
          const payload = buffer.subarray(4, 4 + len);
          buffer = buffer.subarray(4 + len);
          const msg = JSON.parse(payload.toString("utf-8"));

          if (msg.type === "handshake_request") {
            sendFrame({
              requestId: msg.requestId,
              type: "handshake_response",
              success: true,
              acceptedCapabilities: ["parser"]
            });
          } else if (msg.type === "execute_request") {
            process.exit(1); // Intentional crash
          }
        }
      });
    `;

    await writeFile(
      join(tempDir, "fuzit-plugin.json"),
      manifestContent,
      "utf-8",
    );
    await writeFile(join(tempDir, "worker.js"), workerScript, "utf-8");

    activeClient = await PluginHost.spawnPlugin({ pluginDir: tempDir });
    expect(activeClient.running).toBe(true);

    const execResult = await activeClient.executeCapability("parser", {
      file: "src/main.ts",
    });
    expect(execResult.success).toBe(false);
    expect(execResult.error).toContain("Plugin execution failed");

    expect(activeClient.running).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import {
  parsePluginManifest,
  serializePluginManifest,
  validatePluginManifest,
  type PluginManifest,
} from "@fuzit/plugin-sdk";

describe("Plugin Manifest Schema (V1-100)", () => {
  const validBaseManifest: PluginManifest = {
    schemaVersion: 1,
    id: "com.example.test-plugin",
    name: "Test Plugin",
    version: "1.0.0",
    protocol: "fuzit-plugin-v1",
    fuzitVersion: "^1.0.0",
    entryPoint: "dist/index.js",
    capabilities: ["parser", "collector"],
    permissions: {
      filesystem: {
        readPaths: ["src/"],
      },
      shell: false,
      persistence: false,
    },
    integrity: {
      checksum: "sha256:abcd1234efgh5678",
      signature: "placeholder-sig",
      algorithm: "sha256",
    },
  };

  it("parses valid plugin manifest cleanly", () => {
    const parsed = parsePluginManifest(validBaseManifest);
    expect(parsed.id).toBe("com.example.test-plugin");
    expect(parsed.capabilities).toEqual(["parser", "collector"]);
    expect(parsed.permissions?.filesystem?.readPaths).toEqual(["src/"]);
  });

  it("round-trips signed-metadata placeholders without claiming signature verification", () => {
    const serialized = serializePluginManifest(validBaseManifest);
    expect(serialized).toContain("sha256:abcd1234efgh5678");
    expect(serialized).toContain("placeholder-sig");

    const reParsed = parsePluginManifest(JSON.parse(serialized));
    expect(reParsed.integrity).toEqual({
      checksum: "sha256:abcd1234efgh5678",
      signature: "placeholder-sig",
      algorithm: "sha256",
    });
  });

  it("rejects invalid plugin IDs with path traversal or illegal characters", () => {
    const invalidIds = [
      "../invalid-id",
      "invalid/id",
      "invalid\\id",
      "ID_WITH_UPPERCASE",
      "id with space",
      ".leading-dot",
    ];

    for (const id of invalidIds) {
      const result = validatePluginManifest({
        ...validBaseManifest,
        id,
      });
      expect(result.success).toBe(false);
    }
  });

  it("rejects entryPoint path traversal and absolute paths", () => {
    const invalidEntryPoints = [
      "../escape.js",
      "../../etc/passwd",
      "/usr/local/bin/plugin.js",
      "\\windows\\system32\\plugin.dll",
      "C:\\plugin.js",
    ];

    for (const entryPoint of invalidEntryPoints) {
      const result = validatePluginManifest({
        ...validBaseManifest,
        entryPoint,
      });
      expect(result.success).toBe(false);
    }
  });

  it("rejects filesystem permission read/write paths with path traversal", () => {
    const invalidReadResult = validatePluginManifest({
      ...validBaseManifest,
      permissions: {
        filesystem: {
          readPaths: ["../outside-workspace"],
        },
      },
    });
    expect(invalidReadResult.success).toBe(false);

    const invalidWriteResult = validatePluginManifest({
      ...validBaseManifest,
      permissions: {
        filesystem: {
          writePaths: ["/absolute/path"],
        },
      },
    });
    expect(invalidWriteResult.success).toBe(false);
  });

  it("rejects invalid semver versions and fuzitVersion ranges", () => {
    const invalidVersionResult = validatePluginManifest({
      ...validBaseManifest,
      version: "not-a-semver",
    });
    expect(invalidVersionResult.success).toBe(false);

    const invalidFuzitVersionResult = validatePluginManifest({
      ...validBaseManifest,
      fuzitVersion: "invalid-range!!!",
    });
    expect(invalidFuzitVersionResult.success).toBe(false);
  });

  it("rejects undeclared or invalid capabilities", () => {
    const invalidCapabilityResult = validatePluginManifest({
      ...validBaseManifest,
      capabilities: ["arbitrary-code-execution" as unknown as PluginCapability],
    });
    expect(invalidCapabilityResult.success).toBe(false);

    const emptyCapabilitiesResult = validatePluginManifest({
      ...validBaseManifest,
      capabilities: [],
    });
    expect(emptyCapabilitiesResult.success).toBe(false);
  });
});

import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { PermissionBroker } from "@fuzit/plugin-host";

describe("Permission Broker & Security Authorization (V1-105)", () => {
  const workspaceRoot = resolve(process.cwd());

  it("enforces deny-by-default for unconfigured filesystem operations", () => {
    const broker = new PermissionBroker({ workspaceRoot });

    const readResult = broker.authorize({
      kind: "filesystem:read",
      path: "src/index.ts",
    });
    expect(readResult.allowed).toBe(false);
    expect(readResult.reason).toContain("deny by default");

    const writeResult = broker.authorize({
      kind: "filesystem:write",
      path: "dist/out.js",
    });
    expect(writeResult.allowed).toBe(false);
  });

  it("blocks path traversal and null byte attack attempts (confused deputy defense)", () => {
    const broker = new PermissionBroker({
      workspaceRoot,
      permissions: {
        filesystem: {
          readPaths: ["src"],
        },
      },
    });

    const traversalResult = broker.authorize({
      kind: "filesystem:read",
      path: "src/../../etc/passwd",
    });
    expect(traversalResult.allowed).toBe(false);
    expect(traversalResult.reason).toContain(
      "Path traversal '..' is strictly forbidden",
    );

    const nullByteResult = broker.authorize({
      kind: "filesystem:read",
      path: "src/index.ts\0.png",
    });
    expect(nullByteResult.allowed).toBe(false);
    expect(nullByteResult.reason).toContain("Path contains null bytes");
  });

  it("authorizes allowed filesystem paths when explicitly granted", () => {
    const broker = new PermissionBroker({
      workspaceRoot,
      permissions: {
        filesystem: {
          readPaths: ["src"],
          writePaths: ["dist"],
        },
      },
    });

    const readResult = broker.authorize({
      kind: "filesystem:read",
      path: join(workspaceRoot, "src", "main.ts"),
    });
    expect(readResult.allowed).toBe(true);

    const writeResult = broker.authorize({
      kind: "filesystem:write",
      path: join(workspaceRoot, "dist", "bundle.js"),
    });
    expect(writeResult.allowed).toBe(true);
  });

  it("enforces network host whitelist and shell/env/credential access controls", () => {
    const broker = new PermissionBroker({
      workspaceRoot,
      permissions: {
        network: {
          allowedHosts: ["api.github.com"],
        },
        shell: false,
        environment: {
          allowedVars: ["NODE_ENV"],
        },
        credentials: {
          allowedKeys: ["GITHUB_TOKEN"],
        },
      },
    });

    expect(
      broker.authorize({ kind: "network:connect", host: "api.github.com" })
        .allowed,
    ).toBe(true);
    expect(
      broker.authorize({ kind: "network:connect", host: "malicious.com" })
        .allowed,
    ).toBe(false);

    expect(
      broker.authorize({ kind: "shell:execute", command: "whoami" }).allowed,
    ).toBe(false);

    expect(
      broker.authorize({ kind: "environment:read", varName: "NODE_ENV" })
        .allowed,
    ).toBe(true);
    expect(
      broker.authorize({ kind: "environment:read", varName: "SECRET_KEY" })
        .allowed,
    ).toBe(false);

    expect(
      broker.authorize({ kind: "credentials:read", key: "GITHUB_TOKEN" })
        .allowed,
    ).toBe(true);
    expect(
      broker.authorize({
        kind: "credentials:read",
        key: "AWS_SECRET_ACCESS_KEY",
      }).allowed,
    ).toBe(false);
  });

  it("maintains a complete audit log of all authorization decisions", () => {
    const broker = new PermissionBroker({ workspaceRoot });
    broker.authorize({ kind: "shell:execute", command: "ls" });
    broker.authorize({ kind: "runtime:spawnProcess" });

    const auditLogs = broker.getAuditLogs();
    expect(auditLogs).toHaveLength(2);
    expect(auditLogs[0]?.operation.kind).toBe("shell:execute");
    expect(auditLogs[0]?.allowed).toBe(false);
    expect(auditLogs[1]?.operation.kind).toBe("runtime:spawnProcess");
    expect(auditLogs[1]?.allowed).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import {
  MAX_PLUGIN_FRAME_BYTES,
  PluginFrameDecoder,
  encodePluginFrame,
  type PluginMessage,
} from "@fuzit/plugin-sdk";

describe("Framed Plugin Protocol (V1-101)", () => {
  const handshakeMsg: PluginMessage = {
    requestId: "req-1",
    type: "handshake_request",
    pluginId: "com.example.test-plugin",
    protocolVersion: "fuzit-plugin-v1",
    requestedCapabilities: ["parser", "collector"],
    permissions: {
      shell: false,
      persistence: false,
    },
  };

  const executeMsg: PluginMessage = {
    requestId: "req-2",
    type: "execute_request",
    capability: "parser",
    payload: { file: "src/index.ts", content: "const x = 1;" },
    timeoutMs: 5000,
  };

  const shutdownMsg: PluginMessage = {
    requestId: "req-3",
    type: "shutdown_request",
  };

  it("encodes and decodes messages with length prefixing cleanly", () => {
    const frameBuffer = encodePluginFrame(handshakeMsg);
    expect(frameBuffer.length).toBeGreaterThan(4);

    const payloadLength = frameBuffer.readUInt32BE(0);
    expect(payloadLength).toBe(frameBuffer.length - 4);

    const decoder = new PluginFrameDecoder();
    const decoded = decoder.push(frameBuffer);

    expect(decoded.length).toBe(1);
    expect(decoded[0]).toEqual(handshakeMsg);
  });

  it("decodes fragmented message chunks across multiple push calls deterministically", () => {
    const frameBuffer = encodePluginFrame(executeMsg);
    const decoder = new PluginFrameDecoder();

    // Split frame into 3 small fragments
    const part1 = frameBuffer.subarray(0, 5);
    const part2 = frameBuffer.subarray(5, 20);
    const part3 = frameBuffer.subarray(20);

    const res1 = decoder.push(part1);
    expect(res1.length).toBe(0);
    expect(decoder.bufferedBytes).toBe(5);

    const res2 = decoder.push(part2);
    expect(res2.length).toBe(0);
    expect(decoder.bufferedBytes).toBe(20);

    const res3 = decoder.push(part3);
    expect(res3.length).toBe(1);
    expect(res3[0]).toEqual(executeMsg);
    expect(decoder.bufferedBytes).toBe(0);
  });

  it("decodes coalesced multiple frames in a single incoming buffer", () => {
    const frame1 = encodePluginFrame(handshakeMsg);
    const frame2 = encodePluginFrame(executeMsg);
    const frame3 = encodePluginFrame(shutdownMsg);

    const combinedBuffer = Buffer.concat([frame1, frame2, frame3]);
    const decoder = new PluginFrameDecoder();

    const decoded = decoder.push(combinedBuffer);
    expect(decoded.length).toBe(3);
    expect(decoded[0]).toEqual(handshakeMsg);
    expect(decoded[1]).toEqual(executeMsg);
    expect(decoded[2]).toEqual(shutdownMsg);
  });

  it("fails closed on oversized frame headers exceeding MAX_PLUGIN_FRAME_BYTES", () => {
    const oversizedHeader = Buffer.alloc(4);
    oversizedHeader.writeUInt32BE(MAX_PLUGIN_FRAME_BYTES + 1, 0);

    const decoder = new PluginFrameDecoder();
    expect(() => decoder.push(oversizedHeader)).toThrowError(
      /Oversized frame header encountered/,
    );
    expect(decoder.bufferedBytes).toBe(0);
  });

  it("fails closed on malformed JSON payload frame", () => {
    const badPayload = Buffer.from("{ bad json content ", "utf-8");
    const header = Buffer.alloc(4);
    header.writeUInt32BE(badPayload.length, 0);

    const badFrame = Buffer.concat([header, badPayload]);
    const decoder = new PluginFrameDecoder();

    expect(() => decoder.push(badFrame)).toThrowError(
      /Failed to parse plugin frame/,
    );
  });

  it("supports cancellation, diagnostic events, and responses", () => {
    const cancelMsg: PluginMessage = {
      requestId: "req-4",
      type: "cancel_request",
      targetRequestId: "req-2",
      reason: "User aborted operation",
    };

    const diagMsg: PluginMessage = {
      requestId: "req-5",
      type: "diagnostic_event",
      diagnostic: {
        schemaVersion: 1,
        code: "PLUGIN_WARN",
        severity: "warning",
        source: "test-plugin",
        message: "Partial symbol table returned",
      },
    };

    const encodedCancel = encodePluginFrame(cancelMsg);
    const encodedDiag = encodePluginFrame(diagMsg);

    const decoder = new PluginFrameDecoder();
    const decoded = decoder.push(Buffer.concat([encodedCancel, encodedDiag]));

    expect(decoded.length).toBe(2);
    expect(decoded[0]).toEqual(cancelMsg);
    expect(decoded[1]).toEqual(diagMsg);
  });
});

import { readFile } from "node:fs/promises";

import { describe, expect, it } from "vitest";

import { intentionalFailurePlugin } from "../../examples/plugins/intentional-failure/src/index.js";
import { referencePlugin } from "../../examples/plugins/reference/src/index.js";

const bundle = {
  schemaVersion: 1 as const,
  id: `bundle:${"a".repeat(64)}`,
  source: { kind: "repository" as const, root: "<root>" },
  revision: null,
  items: [
    {
      id: "b",
      path: "src/z.ts",
      sha256: "b".repeat(64),
      contentStatus: "complete" as const,
      redacted: false,
    },
    {
      id: "a",
      path: "src/a.ts",
      sha256: "a".repeat(64),
      contentStatus: "complete" as const,
      redacted: false,
    },
  ],
  redactionSummary: { findings: 0, redactedItems: 0, omittedItems: 0 },
  warnings: ["z-warning", "a-warning"],
  failedSources: [],
  budget: { bytes: 0, tokens: 0, truncated: false },
};

describe("reference plugins", () => {
  it("renders byte-stable output and a deterministic profile", async () => {
    const renderer = referencePlugin.handlers.renderer;
    const profile = referencePlugin.handlers.profile;
    expect(renderer).toBeDefined();
    expect(profile).toBeDefined();
    const first = await renderer!({ bundle });
    const second = await renderer!({ bundle });
    expect(first).toEqual(second);
    expect(first.renderedText).toBe(
      '{"schemaVersion":1,"bundleId":"bundle:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","paths":["src/a.ts","src/z.ts"],"warnings":["a-warning","z-warning"]}',
    );
    expect(
      await profile!({
        taskDescription: "safe fixture",
        profileName: "review",
      }),
    ).toMatchObject({
      profileName: "review-reference",
      rules: { deterministic: true },
    });
  });

  it("attributes the sanitized intentional failure to its plugin", async () => {
    const renderer = intentionalFailurePlugin.handlers.renderer;
    expect(renderer).toBeDefined();
    await expect(
      Promise.resolve().then(() => renderer!({ bundle })),
    ).rejects.toThrow("REFERENCE_PLUGIN_FAILURE");
    expect(intentionalFailurePlugin.manifest.id).toBe(
      "dev.fuzit.intentional-failure",
    );
  });

  it("uses only the public plugin SDK in both fixtures", async () => {
    for (const source of [
      "examples/plugins/reference/src/index.ts",
      "examples/plugins/intentional-failure/src/index.ts",
    ]) {
      const contents = await readFile(source, "utf8");
      expect(contents).toContain('from "@fuzit/plugin-sdk"');
      expect(contents).not.toMatch(
        /@fuzit\/(?:plugin-host|schemas)|packages\//u,
      );
    }
  });
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  PluginHost,
  enforceDiagnosticLimits,
  type PluginClient,
} from "@fuzit/plugin-host";
import type { Diagnostic } from "@fuzit/plugin-sdk";

describe("Resource Limits & Timeout Enforcement (V1-106)", () => {
  let tempDir: string;
  let activeClient: PluginClient | undefined;

  beforeEach(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "fuzit-plugin-limits-"));
  });

  afterEach(async () => {
    if (activeClient) {
      activeClient.kill();
      activeClient = undefined;
    }
    await rm(tempDir, {
      recursive: true,
      force: true,
      maxRetries: 10,
      retryDelay: 100,
    });
  });

  it("truncates diagnostic arrays exceeding max limit and appends truncation warning", () => {
    const overflowDiagnostics: Diagnostic[] = Array.from(
      { length: 150 },
      (_, i) => ({
        schemaVersion: 1,
        code: `ERR_${i}`,
        severity: "error",
        source: "test",
        message: `Error message ${i}`,
      }),
    );

    const result = enforceDiagnosticLimits(overflowDiagnostics, 100);
    expect(result).toBeDefined();
    expect(result).toHaveLength(100);
    expect(result?.[99]?.code).toBe("PLUGIN_DIAGNOSTIC_TRUNCATED");
    expect(result?.[99]?.severity).toBe("warning");
  });

  it("times out execution requests exceeding timeoutMs and issues cancellation signal", async () => {
    const manifestContent = JSON.stringify({
      schemaVersion: 1,
      id: "com.example.slow-plugin",
      name: "Slow Plugin",
      version: "1.0.0",
      protocol: "fuzit-plugin-v1",
      fuzitVersion: "^1.0.0",
      entryPoint: "worker.js",
      capabilities: ["parser"],
    });

    // Mock worker that hangs on execute request without responding
    const workerScript = `
      import { Buffer } from "node:buffer";

      function sendFrame(msg) {
        const payload = Buffer.from(JSON.stringify(msg), "utf-8");
        const header = Buffer.alloc(4);
        header.writeUInt32BE(payload.length, 0);
        process.stdout.write(Buffer.concat([header, payload]));
      }

      let buffer = Buffer.alloc(0);
      process.stdin.on("data", (chunk) => {
        buffer = Buffer.concat([buffer, chunk]);
        while (buffer.length >= 4) {
          const len = buffer.readUInt32BE(0);
          if (buffer.length < 4 + len) break;
          const payload = buffer.subarray(4, 4 + len);
          buffer = buffer.subarray(4 + len);
          const msg = JSON.parse(payload.toString("utf-8"));

          if (msg.type === "handshake_request") {
            sendFrame({
              requestId: msg.requestId,
              type: "handshake_response",
              success: true,
              acceptedCapabilities: ["parser"]
            });
          } else if (msg.type === "execute_request") {
            // Intentionally do not respond to simulate hang
          }
        }
      });
    `;

    await writeFile(
      join(tempDir, "fuzit-plugin.json"),
      manifestContent,
      "utf-8",
    );
    await writeFile(join(tempDir, "worker.js"), workerScript, "utf-8");

    activeClient = await PluginHost.spawnPlugin({ pluginDir: tempDir });
    expect(activeClient.running).toBe(true);

    const result = await activeClient.executeCapability(
      "parser",
      { file: "test.ts" },
      { timeoutMs: 300 },
    );
    expect(result.success).toBe(false);
    expect(result.error).toContain("timed out after 300ms");
  });
});

import { describe, expect, it } from "vitest";
import {
  createPlugin,
  parsePluginManifest,
  type PluginInstance,
} from "@fuzit/plugin-sdk";

describe("Restricted Plugin SDK API Surface (V1-102)", () => {
  it("exposes curated public contracts without internal host objects", () => {
    const validManifest = parsePluginManifest({
      schemaVersion: 1,
      id: "com.example.custom-parser",
      name: "Custom Parser Plugin",
      version: "1.0.0",
      fuzitVersion: "^1.0.0",
      entryPoint: "dist/plugin.js",
      capabilities: ["parser", "secret-detector"],
      permissions: {
        shell: false,
      },
    });

    const pluginInstance: PluginInstance = createPlugin({
      manifest: validManifest,
      handlers: {
        parser: (input) => {
          return {
            symbols: [
              {
                name: "myFunction",
                kind: "function",
                location: { path: input.fileRecord.path, line: 1 },
              },
            ],
            imports: [{ source: "node:fs", importedSymbols: ["readFileSync"] }],
          };
        },
        "secret-detector": () => {
          return {
            findings: [],
          };
        },
      },
    });

    expect(pluginInstance.manifest.id).toBe("com.example.custom-parser");
    expect(pluginInstance.handlers.parser).toBeDefined();
    expect(pluginInstance.handlers["secret-detector"]).toBeDefined();
  });

  it("throws error if plugin declares capability without providing a handler implementation", () => {
    const manifestWithMissingHandler = parsePluginManifest({
      schemaVersion: 1,
      id: "com.example.incomplete",
      name: "Incomplete Plugin",
      version: "1.0.0",
      fuzitVersion: "^1.0.0",
      entryPoint: "dist/plugin.js",
      capabilities: ["ranker"],
    });

    expect(() =>
      createPlugin({
        manifest: manifestWithMissingHandler,
        handlers: {},
      }),
    ).toThrowError(
      "Plugin 'com.example.incomplete' declares capability 'ranker' but provides no handler implementation for it.",
    );
  });
});

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import {
  assertArtifactChecksums,
  createArtifactManifest,
} from "../../scripts/artifact-manifest.mjs";

const temporary: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporary.splice(0).map((path) => rm(path, { recursive: true })),
  );
});

describe("release artifact manifest", () => {
  it("records stable ordered paths, checksums, versions, and release matrices", async () => {
    const directory = await mkdtemp(join(tmpdir(), "fuzit-manifest-"));
    temporary.push(directory);
    await writeFile(join(directory, "z.tgz"), "z");
    await writeFile(join(directory, "a.vsix"), "a");
    const output = join(directory, "manifest.json");

    const manifest = await createArtifactManifest({
      artifactDirectory: directory,
      outputPath: output,
    });
    expect(manifest.artifacts.map(({ path }) => path)).toEqual(
      [...manifest.artifacts.map(({ path }) => path)].sort(),
    );
    expect(manifest.lockSha256).toMatch(/^[a-f0-9]{64}$/);
    expect(manifest.supportedMatrix.node).toEqual(["24"]);
    expect(manifest.packageVersions.fuzit).toBe("0.0.1");
    expect(JSON.parse(await readFile(output, "utf8"))).toEqual(manifest);
  });

  it("fails after any recorded artifact byte changes", async () => {
    const directory = await mkdtemp(join(tmpdir(), "fuzit-manifest-"));
    temporary.push(directory);
    const artifact = join(directory, "cli.tgz");
    await writeFile(artifact, "original");
    const manifest = await createArtifactManifest({
      artifactDirectory: directory,
      outputPath: join(directory, "manifest.json"),
    });
    await writeFile(artifact, "modified");
    await expect(assertArtifactChecksums(manifest, directory)).rejects.toThrow(
      "Artifact checksum mismatch",
    );
  });

  it("fails closed for an empty artifact set", async () => {
    const directory = await mkdtemp(join(tmpdir(), "fuzit-manifest-"));
    temporary.push(directory);
    await expect(
      createArtifactManifest({
        artifactDirectory: directory,
        outputPath: join(directory, "manifest.json"),
      }),
    ).rejects.toThrow("No release artifacts");
  });
});

