import { spawnSync } from "node:child_process";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

const root = resolve(import.meta.dirname, "../..");
const candidates = [
  "apps/cli",
  "apps/mcp-server",
  "apps/vscode-extension",
  "packages/plugin-sdk",
] as const;

type PackEntry = { path: string };
type PackResult = { files: PackEntry[] };

function assertSafeListing(paths: string[]): void {
  const forbidden = [
    /(^|\/)\.fuzit-development(\/|$)/,
    /(^|\/)\.v1-development(\/|$)/,
    /(^|\/)\.cache(\/|$)/,
    /(^|\/)\.turbo(\/|$)/,
    /(^|\/)node_modules(\/|$)/,
    /(^|\/)implementation-plan(\/|$)/,
    /(^|\/)specs(\/|$)/,
    /(^|\/)src(\/|$)/,
    /(^|\/)test(s)?(\/|$)/,
    /\.map$/,
    /(^|\/)(\.env|credentials|secrets?)(\.|\/|$)/i,
    /^[A-Za-z]:[\\/]/,
    /^\//,
  ];
  for (const path of paths) {
    if (forbidden.some((pattern) => pattern.test(path))) {
      throw new Error(`forbidden package entry: ${path}`);
    }
  }
}

function dryRunListing(directory: string): string[] {
  const pnpmArguments = ["--dir", directory, "pack", "--dry-run", "--json"];
  const executable =
    process.platform === "win32" ? (process.env.ComSpec ?? "cmd.exe") : "pnpm";
  const arguments_ =
    process.platform === "win32"
      ? ["/d", "/s", "/c", "pnpm.cmd", ...pnpmArguments]
      : pnpmArguments;
  const result = spawnSync(executable, arguments_, {
    cwd: root,
    encoding: "utf8",
    shell: false,
  });
  if (result.status !== 0) {
    throw new Error(
      `pack listing failed for ${directory}: ${result.error?.message ?? result.stderr}`,
    );
  }
  const parsed = JSON.parse(result.stdout) as PackResult | PackResult[];
  const pack = Array.isArray(parsed) ? parsed[0] : parsed;
  return (pack?.files ?? []).map(({ path }) => path).sort();
}

describe("release package contents", () => {
  it("uses complete publishable metadata and strict allow-lists", async () => {
    for (const directory of candidates) {
      const manifest = JSON.parse(
        await readFile(resolve(root, directory, "package.json"), "utf8"),
      ) as Record<string, unknown>;
      expect(manifest.private).toBe(false);
      expect(manifest.license).toBe("MIT");
      expect(manifest.files).toEqual(
        expect.arrayContaining([expect.stringMatching(/^dist\/.*\.js$/)]),
      );
      expect(manifest.repository).toMatchObject({
        type: "git",
        directory,
      });
    }
  });

  it("produces deterministic safe dry-run listings", () => {
    for (const directory of candidates) {
      const first = dryRunListing(directory);
      const second = dryRunListing(directory);
      expect(second).toEqual(first);
      expect(first).toContain("package.json");
      assertSafeListing(first);
    }
  }, 30_000);

  it("fails closed on a private source or map entry", () => {
    expect(() =>
      assertSafeListing(["dist/index.js", "src/private.ts"]),
    ).toThrow("forbidden package entry: src/private.ts");
    expect(() => assertSafeListing(["dist/index.js.map"])).toThrow(
      "forbidden package entry: dist/index.js.map",
    );
  });
});

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

type Candidate = {
  name: string;
  path: string;
  distribution: "npm" | "vsix";
  bin: string[];
  exports: string[];
};

type Topology = {
  publicationAuthorized: boolean;
  npmNameApproval: string;
  publicCandidates: Candidate[];
  bundledInternalPackages: string[];
  privateDevelopmentPackages: string[];
};

const root = resolve(import.meta.dirname, "../..");

async function loadJson(path: string): Promise<Record<string, unknown>> {
  return JSON.parse(await readFile(resolve(root, path), "utf8")) as Record<
    string,
    unknown
  >;
}

function validateOrdering(values: string[], label: string): void {
  const sorted = [...values].sort((left, right) => left.localeCompare(right));
  if (JSON.stringify(values) !== JSON.stringify(sorted)) {
    throw new Error(`${label} must use deterministic lexical ordering`);
  }
}

async function validateCandidate(candidate: Candidate): Promise<void> {
  const manifest = await loadJson(`${candidate.path}/package.json`);
  if (manifest.name !== candidate.name) {
    throw new Error(`manifest name mismatch for ${candidate.path}`);
  }
  if (manifest.private !== false) {
    throw new Error(`${candidate.name} must be publishable after approval`);
  }
  const bins = Object.keys((manifest.bin ?? {}) as Record<string, unknown>);
  const exports = Object.keys(
    (manifest.exports ?? {}) as Record<string, unknown>,
  );
  if (JSON.stringify(bins) !== JSON.stringify(candidate.bin)) {
    throw new Error(`bin contract mismatch for ${candidate.name}`);
  }
  if (JSON.stringify(exports) !== JSON.stringify(candidate.exports)) {
    throw new Error(`export contract mismatch for ${candidate.name}`);
  }
}

describe("intended package topology", () => {
  it("matches the exact authorized release manifests", async () => {
    const topology = (await loadJson(
      "docs/release/package-topology.json",
    )) as unknown as Topology;

    expect(topology.publicationAuthorized).toBe(true);
    expect(topology.npmNameApproval).toBe("owner-controlled-and-approved");
    for (const candidate of topology.publicCandidates) {
      await validateCandidate(candidate);
    }
  });

  it("records every package exactly once in deterministic groups", async () => {
    const topology = (await loadJson(
      "docs/release/package-topology.json",
    )) as unknown as Topology;
    const names = [
      ...topology.publicCandidates.map(({ name }) => name),
      ...topology.bundledInternalPackages,
      ...topology.privateDevelopmentPackages,
    ];

    expect(new Set(names).size).toBe(28);
    expect(names).toHaveLength(28);
    validateOrdering(topology.bundledInternalPackages, "bundled packages");
    validateOrdering(topology.privateDevelopmentPackages, "private packages");
  });

  it("fails closed when a declared public contract differs from its manifest", async () => {
    const invalid: Candidate = {
      name: "@fuzit/cli",
      path: "apps/cli",
      distribution: "npm",
      bin: ["not-fuzit"],
      exports: ["."],
    };

    await expect(validateCandidate(invalid)).rejects.toThrow(
      "bin contract mismatch for @fuzit/cli",
    );
  });
});

import { describe, expect, it } from "vitest";

import { compareArtifactSets } from "../../scripts/verify-reproducibility.mjs";

const artifact = {
  path: "fuzit.tgz",
  bytes: 10,
  sha256: "a".repeat(64),
};

describe("release artifact reproducibility", () => {
  it("accepts byte-identical deterministically ordered artifact sets", () => {
    expect(compareArtifactSets([artifact], [{ ...artifact }])).toMatchObject({
      status: "reproducible",
      permittedDifferences: [],
      remoteCache: false,
      telemetry: false,
    });
  });

  it("rejects every unexplained byte difference", () => {
    expect(() =>
      compareArtifactSets(
        [artifact],
        [{ ...artifact, sha256: "b".repeat(64) }],
      ),
    ).toThrow("Unexplained artifact differences: fuzit.tgz");
  });

  it("documents volatile tar metadata only when canonical payloads match", () => {
    const report = compareArtifactSets(
      [{ ...artifact, canonicalSha256: "c".repeat(64) }],
      [
        {
          ...artifact,
          sha256: "b".repeat(64),
          canonicalSha256: "c".repeat(64),
        },
      ],
    );
    expect(report.permittedDifferences).toEqual([
      expect.objectContaining({ path: "fuzit.tgz" }),
    ]);
  });

  it("rejects missing artifacts", () => {
    expect(() => compareArtifactSets([artifact], [])).toThrow(
      "Unexplained artifact differences",
    );
  });
});

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import {
  assertDependencyLicenses,
  generateSbom,
} from "../../scripts/generate-sbom.mjs";

const temporary: string[] = [];
afterEach(async () => {
  await Promise.all(
    temporary.splice(0).map((path) => rm(path, { recursive: true })),
  );
});

async function fixture(dependencyLicense: string) {
  const directory = await mkdtemp(join(tmpdir(), "fuzit-sbom-"));
  temporary.push(directory);
  const dependency = join(directory, "node_modules", "dependency");
  await mkdir(dependency, { recursive: true });
  await writeFile(
    join(directory, "package.json"),
    JSON.stringify({
      name: "@fuzit/private-root",
      version: "1.0.0",
      license: "UNLICENSED",
      dependencies: { dependency: "1.0.0" },
    }),
  );
  await writeFile(
    join(dependency, "package.json"),
    JSON.stringify({
      name: "dependency",
      version: "1.0.0",
      license: dependencyLicense,
    }),
  );
  return join(directory, "package.json");
}

describe("software bill of materials", () => {
  it("records deterministic components, integrity, licenses, and relationships", async () => {
    const manifest = await fixture("MIT");
    const first = await generateSbom({ packageManifestPaths: [manifest] });
    const second = await generateSbom({ packageManifestPaths: [manifest] });
    expect(second).toEqual(first);
    expect(first.components).toHaveLength(2);
    expect(first.components[0]?.integrity).toMatch(/^sha256:[a-f0-9]{64}$/);
    expect(first.relationships).toHaveLength(1);
    expect(first.metadata.tool).toEqual({ name: "fuzit-sbom", version: "1" });
    expect(first.releaseEligible).toBe(false);
    expect(() => assertDependencyLicenses(first)).not.toThrow();
  });

  it("blocks unknown or disallowed dependency licenses", async () => {
    const manifest = await fixture("UNKNOWN");
    const sbom = await generateSbom({ packageManifestPaths: [manifest] });
    expect(() => assertDependencyLicenses(sbom)).toThrow(
      "blocked dependency licenses",
    );
  });
});

