import { describe, expect, it, vi } from "vitest";
import {
  ResourceLimitError,
  atomicWrite,
  enforceOutputLimit,
  mapConcurrent,
  operationSignal,
  withRollback,
} from "@fuzit/core";

describe("resource limits", () => {
  it("propagates Ctrl-C cancellation", () => {
    const input = new AbortController();
    const operation = operationSignal(input.signal, 10_000);
    input.abort();
    expect(operation.signal.aborted).toBe(true);
    operation.dispose();
  });
  it("applies a bounded timeout", async () => {
    vi.useFakeTimers();
    const operation = operationSignal(undefined, 5);
    await vi.advanceTimersByTimeAsync(5);
    expect(operation.signal.reason).toBeInstanceOf(ResourceLimitError);
    operation.dispose();
    vi.useRealTimers();
  });
  it("rejects output beyond the hard maximum", () => {
    expect(() => enforceOutputLimit("1234", 3)).toThrow("exceeds");
  });
  it("cleans temporary output after a simulated disk-full write", async () => {
    const unlink = vi.fn(async () => undefined);
    await expect(
      atomicWrite("out.txt", "data", 10, {
        mkdir: vi.fn(async () => undefined),
        writeFile: vi.fn(async () => {
          throw new Error("ENOSPC");
        }),
        rename: vi.fn(async () => undefined),
        unlink,
      }),
    ).rejects.toMatchObject({ code: "WRITE_FAILED" });
    expect(unlink).toHaveBeenCalledOnce();
  });
  it("rolls back an interrupted index transaction", async () => {
    const rollback = vi.fn(async () => undefined);
    await expect(
      withRollback(async () => {
        throw new Error("interrupted");
      }, rollback),
    ).rejects.toThrow("interrupted");
    expect(rollback).toHaveBeenCalledOnce();
  });
  it("caps concurrent file work", async () => {
    let active = 0;
    let maximum = 0;
    await mapConcurrent(
      [1, 2, 3, 4],
      2,
      async (value) => {
        active += 1;
        maximum = Math.max(maximum, active);
        await Promise.resolve();
        active -= 1;
        return value;
      },
      new AbortController().signal,
    );
    expect(maximum).toBeLessThanOrEqual(2);
  });
});

import { describe, expect, it } from "vitest";
import {
  normalizeIdentifierTokens,
  scoreExactIdentifiers,
} from "@fuzit/selection";

describe("exact identifier relevance", () => {
  it("normalizes case, Unicode, routes, schemas, packages, and aliases", () => {
    expect(normalizeIdentifierTokens("Cr\u00e9erHTTPClient")).toEqual([
      "cr\u00e9er",
      "httpclient",
    ]);
    const score = scoreExactIdentifiers("fix cr\u00e9er checkout", {
      symbols: ["Cr\u00e9er"],
      routes: ["/checkout/session"],
      schemas: ["CheckoutSession"],
      packages: ["@fuzit/payments"],
      aliases: ["checkout"],
    });
    expect(score.value).toBeCloseTo(2 / 3);
    expect(score.matchedTerms).toEqual(["cr\u00e9er", "checkout"]);
  });

  it("ranks exact anchors above incidental path text", () => {
    const exact = scoreExactIdentifiers("repair PaymentGateway", {
      symbols: ["PaymentGateway"],
    });
    const incidental = scoreExactIdentifiers("repair PaymentGateway", {
      paths: ["docs/payment-gateway-notes.md"],
    });
    expect(exact.value).toBeGreaterThan(incidental.value);
    expect(exact.basis).toContain("PaymentGateway");
  });

  it("does not promote common-name false positives", () => {
    expect(
      scoreExactIdentifiers("update main index file", {
        symbols: ["main", "index", "file"],
      }),
    ).toMatchObject({
      value: 0,
      matchedIdentifiers: [],
      matchedTerms: [],
    });
  });
});

import { describe, expect, it } from "vitest";
import { buildFilePackageGraph, createGraphEdge } from "@fuzit/graph";
import { scoreGraphDistance } from "@fuzit/selection";
import type { NormalizedAnalysis } from "@fuzit/schemas";

const repositoryId = `sha256:${"a".repeat(64)}`;
const hash = (value: number) => value.toString(16).padStart(64, "0");
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: ["a.ts", "b.ts", "c.ts"].map((path, index) => ({
    id: `analysis:file:${hash(index + 1)}`,
    repositoryId,
    kind: "file",
    path,
    language: "typescript",
    contentHash: `sha256:${hash(index + 10)}`,
  })),
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};
const base = buildFilePackageGraph({ analysis, revision: "r1", packages: [] });
const files = Object.fromEntries(
  base.nodes
    .filter((node) => node.kind === "file")
    .map((node) => [node.path!, node]),
);
const edge = (from: string, to: string, kind: "imports" | "depends-on") =>
  createGraphEdge({
    repositoryId,
    kind,
    sourceId: files[from]!.id,
    sourceKind: "file",
    targetId: files[to]!.id,
    targetKind: "file",
    unresolvedTarget: null,
    resolution: "resolved",
    evidence: [
      {
        basis: "parsed",
        collector: "fixture",
        collectorVersion: "1",
        sourcePath: from,
        reason: kind,
      },
    ],
    revision: { validFrom: "r1", validThrough: null },
  });

describe("graph-distance relevance", () => {
  it("chooses deterministic weighted shortest paths through cycles", () => {
    const graph = {
      ...base,
      edges: [
        ...base.edges,
        edge("a.ts", "b.ts", "imports"),
        edge("b.ts", "a.ts", "imports"),
        edge("a.ts", "c.ts", "depends-on"),
        edge("c.ts", "b.ts", "imports"),
      ],
    };
    const options = {
      requiredAnchorIds: [files["a.ts"]!.id],
      edgeWeights: { imports: 1, "depends-on": 0.5 },
      maxDepth: 3,
      maxNodes: 20,
      maxEdges: 50,
    };
    const first = scoreGraphDistance(graph, options);
    expect(scoreGraphDistance(graph, options)).toEqual(first);
    expect(
      first.find((score) => score.nodeId === files["b.ts"]!.id)?.graphPath,
    ).toEqual([files["a.ts"]!.id, files["b.ts"]!.id]);
  });
  it("records partial graph state and rejects unsafe bounds", () => {
    const graph = {
      ...base,
      completeness: "partial" as const,
      diagnostics: ["parser unavailable"],
    };
    expect(
      scoreGraphDistance(graph, {
        requiredAnchorIds: [base.nodes[0]!.id],
        edgeWeights: { contains: 1 },
        maxDepth: 1,
        maxNodes: 10,
        maxEdges: 10,
      })[0]?.basis,
    ).toContain("graph=partial");
    expect(() =>
      scoreGraphDistance(base, {
        requiredAnchorIds: [],
        edgeWeights: {},
        maxDepth: 11,
        maxNodes: 1,
        maxEdges: 1,
      }),
    ).toThrow(/depth/u);
  });
});

import { describe, expect, it } from "vitest";
import {
  compareHybridScores,
  createHybridScore,
  serializeHybridScore,
  type HybridFeatureVector,
} from "@fuzit/selection";

const featureVector = (path = "src/a.ts"): HybridFeatureVector => ({
  schemaVersion: 1,
  candidateId: `candidate:${path}`,
  path,
  requiredAnchor: true,
  features: { lexical: 0.5, exact: 1 },
});

describe("hybrid scoring contract", () => {
  it("serializes and ranks identical inputs deterministically", () => {
    const input = {
      featureVector: featureVector(),
      profileId: "bug-fix",
      profileVersion: 1,
      weights: { lexical: 3, exact: 4 },
      basis: { lexical: "normalized task tokens", exact: "exact identifier" },
    };
    const first = createHybridScore(input);
    expect(serializeHybridScore(createHybridScore(input))).toBe(
      serializeHybridScore(first),
    );
    expect(first.aggregateScore).toBe(5.5);
    expect(first.featureVector.requiredAnchor).toBe(true);
    expect(
      [
        createHybridScore({ ...input, featureVector: featureVector("b.ts") }),
        createHybridScore({ ...input, featureVector: featureVector("a.ts") }),
      ].sort(compareHybridScores)[0]?.featureVector.path,
    ).toBe("a.ts");
  });

  it.each([Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
    "rejects non-finite evidence %s",
    (value) => {
      expect(() =>
        createHybridScore({
          featureVector: {
            ...featureVector(),
            features: { lexical: value },
          },
          profileId: "bug-fix",
          profileVersion: 1,
          weights: { lexical: 1 },
          basis: { lexical: "tokens" },
        }),
      ).toThrow(/finite/u);
    },
  );

  it("rejects missing basis and unversioned evidence", () => {
    expect(() =>
      createHybridScore({
        featureVector: featureVector(),
        profileId: "bug-fix",
        profileVersion: 1,
        weights: {},
        basis: {},
      }),
    ).toThrow(/basis/u);
    expect(() =>
      createHybridScore({
        featureVector: { ...featureVector(), schemaVersion: 0 as 1 },
        profileId: "bug-fix",
        profileVersion: 1,
        weights: {},
        basis: {},
      }),
    ).toThrow(/version/u);
  });
});

import { describe, expect, it } from "vitest";
import { buildFilePackageGraph } from "@fuzit/graph";
import { scoreMetadataRelevance } from "@fuzit/selection";
import type { NormalizedAnalysis } from "@fuzit/schemas";
const repositoryId = `sha256:${"a".repeat(64)}`;
const hash = (n: number) => n.toString(16).padStart(64, "0");
const paths = [
  "apps/web/src/app.ts",
  "apps/web/package.json",
  "apps/web/tsconfig.json",
  "services/api/main.go",
  "services/api/go.mod",
  "services/other/go.mod",
];
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: paths.map((path, index) => ({
    id: `analysis:file:${hash(index + 1)}`,
    repositoryId,
    kind: "file",
    path,
    language: path.endsWith(".go") ? "go" : "typescript",
    contentHash: `sha256:${hash(index + 20)}`,
  })),
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};
const graph = buildFilePackageGraph({
  analysis,
  revision: "r1",
  packages: [
    {
      name: "web",
      path: "apps/web",
      manifestPath: "apps/web/package.json",
      dependencies: [],
    },
    {
      name: "api",
      path: "services/api",
      manifestPath: "services/api/go.mod",
      dependencies: [],
    },
    {
      name: "other",
      path: "services/other",
      manifestPath: "services/other/go.mod",
      dependencies: [],
    },
  ],
});
const node = (path: string) => graph.nodes.find((item) => item.path === path)!;

describe("manifest and configuration relevance", () => {
  it("selects nested package metadata in a polyglot monorepo", () => {
    const web = scoreMetadataRelevance(graph, [node("apps/web/src/app.ts").id]);
    expect(web.map((item) => item.nodeId)).toEqual(
      expect.arrayContaining([
        node("apps/web/package.json").id,
        node("apps/web/tsconfig.json").id,
      ]),
    );
    expect(
      web.some((item) => item.nodeId === node("services/api/go.mod").id),
    ).toBe(false);
    const api = scoreMetadataRelevance(graph, [
      node("services/api/main.go").id,
    ]);
    expect(api.map((item) => item.nodeId)).toContain(
      node("services/api/go.mod").id,
    );
    expect(api.map((item) => item.nodeId)).not.toContain(
      node("services/other/go.mod").id,
    );
  });
  it("bounds metadata expansion", () =>
    expect(() => scoreMetadataRelevance(graph, [], 201)).toThrow(/limit/u));
});

import { getProfile } from "@fuzit/profiles";
import { createHybridScore, type HybridFeatureVector } from "@fuzit/selection";
import { describe, expect, it } from "vitest";

const vector: HybridFeatureVector = {
  schemaVersion: 1,
  candidateId: "candidate:src/change.ts",
  path: "src/change.ts",
  requiredAnchor: false,
  features: { dependency: 0.8, doc: 0.8, exact: 0.5 },
};

const rank = (profileId: string) => {
  const profile = getProfile(profileId);
  return createHybridScore({
    featureVector: vector,
    profileId: profile.id,
    profileVersion: profile.version,
    weights: profile.weights,
    basis: {
      dependency: "resolved graph edge",
      doc: "documentation relation",
      exact: "exact identifier",
    },
  });
};

describe("profile-integrated hybrid ranking", () => {
  it("produces same-task differences for recorded profile weights", () => {
    const architecture = rank("architecture-review");
    const documentation = rank("documentation");
    expect(architecture.aggregateScore).not.toBe(documentation.aggregateScore);
    expect(
      architecture.components.find(
        ({ component }) => component === "dependency",
      )?.weight,
    ).toBe(4);
    expect(
      documentation.components.find(({ component }) => component === "doc")
        ?.weight,
    ).toBe(5);
  });
  it("is deterministic for the same task and profile", () => {
    expect(rank("bug-fix")).toEqual(rank("bug-fix"));
  });
  it("rejects an unknown profile before ranking", () => {
    expect(() => rank("unknown")).toThrow("Unknown profile: unknown");
  });
});

import { describe, expect, it } from "vitest";
import { buildFilePackageGraph, createGraphEdge } from "@fuzit/graph";
import { scoreRelatedTests } from "@fuzit/selection";
import type { NormalizedAnalysis } from "@fuzit/schemas";
const repositoryId = `sha256:${"a".repeat(64)}`;
const hash = (n: number) => n.toString(16).padStart(64, "0");
const paths = [
  "src/api.ts",
  "tests/api.test.ts",
  "integration/api.integration.ts",
  "e2e/api.e2e.ts",
  "src/contest.ts",
  "tests/unrelated.test.ts",
];
const analysis: NormalizedAnalysis = {
  schemaVersion: 1,
  repositoryId,
  analysisIdentity: "fixture",
  files: paths.map((path, index) => ({
    id: `analysis:file:${hash(index + 1)}`,
    repositoryId,
    kind: "file",
    path,
    language: "typescript",
    contentHash: `sha256:${hash(index + 20)}`,
  })),
  modules: [],
  symbols: [],
  relationships: [],
  completeness: "complete",
  diagnostics: [],
};
const base = buildFilePackageGraph({
  analysis,
  revision: "r1",
  packages: [
    { name: "root", path: ".", manifestPath: "package.json", dependencies: [] },
  ],
});
const node = (path: string) => base.nodes.find((item) => item.path === path)!;

describe("related-test relevance", () => {
  it("prioritizes explicit and parsed evidence with test distinctions", () => {
    const explicit = createGraphEdge({
      repositoryId,
      kind: "tests",
      sourceId: node("tests/api.test.ts").id,
      sourceKind: "test",
      targetId: node("src/api.ts").id,
      targetKind: "file",
      unresolvedTarget: null,
      resolution: "resolved",
      evidence: [
        {
          basis: "parsed",
          collector: "fixture",
          collectorVersion: "1",
          sourcePath: "tests/api.test.ts",
          reason: "explicit",
        },
      ],
      revision: { validFrom: "r1", validThrough: null },
    });
    const graph = {
      ...base,
      nodes: base.nodes.map((item) =>
        item.path === "tests/api.test.ts"
          ? { ...item, kind: "test" as const }
          : item,
      ),
      edges: [...base.edges, explicit],
    };
    const results = scoreRelatedTests(graph, [node("src/api.ts").id]);
    expect(results[0]).toMatchObject({ value: 1, testKind: "unit" });
    expect(results.some((item) => item.testKind === "integration")).toBe(true);
    expect(results.some((item) => item.testKind === "e2e")).toBe(true);
  });
  it("excludes false-positive and unrelated test filenames", () => {
    const results = scoreRelatedTests(base, [node("src/api.ts").id]);
    expect(
      results.some((item) => item.nodeId === node("src/contest.ts").id),
    ).toBe(false);
    expect(
      results.some(
        (item) =>
          item.nodeId === node("tests/unrelated.test.ts").id &&
          item.value >= 0.6,
      ),
    ).toBe(false);
  });
  it("bounds result expansion", () => {
    expect(() => scoreRelatedTests(base, [], 201)).toThrow(/limit/u);
  });
});

import { describe, expect, expectTypeOf, it } from "vitest";

import {
  assertSecurityFilteredItem,
  securityFilter,
  type SecurityFilteredItem,
} from "@fuzit/core";
import type { FileContextItem } from "@fuzit/schemas";

const digest = "a".repeat(64);

function item(content: string): FileContextItem {
  return {
    schemaVersion: 1,
    id: `file:${digest}`,
    kind: "file",
    path: "src/a.ts",
    content,
    contentStatus: "complete",
    provenance: { source: "scanner", confidenceBasis: "test" },
    lifecycle: "source",
    sensitivity: "unclassified",
    sha256: digest,
    transformations: [],
  };
}

describe("immutable security pipeline", () => {
  it("exposes a type-level renderer boundary", () => {
    type Renderer = (value: SecurityFilteredItem) => string;
    expectTypeOf<Renderer>().parameter(0).toMatchTypeOf<SecurityFilteredItem>();
    expectTypeOf<FileContextItem>().not.toMatchTypeOf<SecurityFilteredItem>();
  });

  it("asserts the boundary at runtime", () => {
    expect(() => assertSecurityFilteredItem(item("safe"))).toThrow(
      "must pass the security pipeline",
    );
  });

  it("never reads a path-blocked file", async () => {
    let reads = 0;
    const result = await securityFilter({
      path: ".env",
      readContent: async () => {
        reads += 1;
        return "never";
      },
      createItem: (content) => item(content),
    });
    expect(result.status).toBe("omitted");
    expect(reads).toBe(0);
  });

  it("safely omits content after detector failure", async () => {
    const result = await securityFilter({
      path: "src/a.ts",
      readContent: async () => "content",
      createItem: (content) => item(content),
      detect: () => {
        throw new Error("synthetic detector failure");
      },
    });
    expect(result).toMatchObject({
      status: "partial",
      reason: "detector-failed-content-omitted",
    });
  });

  it("returns a partial result after read failure", async () => {
    const result = await securityFilter({
      path: "src/a.ts",
      readContent: async () => {
        throw new Error("synthetic read failure");
      },
      createItem: (content) => item(content),
    });
    expect(result.status).toBe("partial");
  });
});

import { mkdtemp, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { normalizeRepositoryRelativePath } from "@fuzit/core";
import { loadEffectiveConfig } from "@fuzit/config";
import { runGit } from "@fuzit/git";
import { detectAndRedactCredentials } from "@fuzit/security";
import { readTextContent, resolveSymlinkSafely } from "@fuzit/scanner";

describe("malicious repository", () => {
  it("rejects path traversal", () =>
    expect(() => normalizeRepositoryRelativePath("../../outside")).toThrow());
  it("removes terminal escapes and line injection from Git output", async () => {
    const result = await runGit(
      ["-e", "process.stderr.write('\\u001b[31mEVIL\\nnext')"],
      { executable: process.execPath },
    );
    expect(result.stderr).not.toContain("\u001b");
    expect(result.stderr).not.toContain("\n");
  });
  it("redacts credential material", () => {
    const secret = ["SYNTHETIC", "TOKEN", "123456789012"].join("_");
    const result = detectAndRedactCredentials(`token=${secret}`, "fixture.txt");
    expect(result.findings.length).toBeGreaterThan(0);
    expect(result.content).not.toContain(secret);
  });
  it("does not follow a symlink escape", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-malicious-"));
    const outside = join(root, "..", `outside-${Date.now()}.txt`);
    await writeFile(outside, "outside");
    const link = join(root, "escape");
    try {
      await symlink(outside, link, "file");
      expect(
        await resolveSymlinkSafely(root, link, "escape" as never, {
          follow: true,
        }),
      ).toMatchObject({ followed: false, status: "outside-root" });
    } catch (error) {
      expect((error as NodeJS.ErrnoException).code).toMatch(/EPERM|EACCES/);
    }
  });
  it("bounds huge files and never extracts archive placeholders", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-huge-"));
    const path = join(root, "huge.txt");
    await writeFile(path, "x".repeat(10_000));
    expect(await readTextContent(path, { maximumBytes: 32 })).toMatchObject({
      bytesRead: 32,
      truncated: true,
    });
    const archive = await readTextContent(
      join(process.cwd(), "fixtures/malicious/archive.zip.placeholder"),
    );
    expect(archive.content).toContain("never be extracted");
  });
  it("rejects malformed configuration without leaking its value", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-config-abuse-"));
    const value = "private-malformed-value";
    await writeFile(
      join(root, "fuzit.config.json"),
      JSON.stringify({ maxFiles: value }),
    );
    let caught: unknown;
    try {
      await loadEffectiveConfig({ repositoryRoot: root });
    } catch (error) {
      caught = error;
    }
    expect(JSON.stringify(caught)).not.toContain(value);
  });
  it("treats deceptive names as inert text", async () => {
    expect(
      (
        await readTextContent(
          join(process.cwd(), "fixtures/malicious/deceptive-name.txt"),
        )
      ).status,
    ).toBe("complete");
  });
});

import dns from "node:dns";
import net from "node:net";

net.Socket.prototype.connect = function denied() {
  throw new Error("Unexpected network socket in network-denied child process");
};
dns.lookup = function deniedLookup() {
  throw new Error("Unexpected DNS attempt in network-denied child process");
};

import dns from "node:dns";
import net from "node:net";

export async function withNetworkDenied<T>(
  operation: () => Promise<T> | T,
): Promise<T> {
  const connect = net.Socket.prototype.connect;
  const lookup = dns.lookup;
  net.Socket.prototype.connect = function denied(): never {
    throw new Error("Unexpected network socket");
  } as typeof connect;
  dns.lookup = function deniedLookup(): never {
    throw new Error("Unexpected DNS attempt");
  } as typeof lookup;
  try {
    return await operation();
  } finally {
    net.Socket.prototype.connect = connect;
    dns.lookup = lookup;
  }
}

import dns from "node:dns";
import http from "node:http";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { runCli } from "../../../apps/cli/src/cli.js";
import { withNetworkDenied } from "./harness.js";

describe("deny-by-default network gate", () => {
  it("detects DNS attempts", async () => {
    await expect(
      withNetworkDenied(
        async () =>
          new Promise((resolve) =>
            dns.lookup("example.invalid", () => resolve(undefined)),
          ),
      ),
    ).rejects.toThrow("DNS");
  });
  it("detects HTTP/socket attempts", async () => {
    await expect(
      withNetworkDenied(
        async () =>
          new Promise((resolve) => {
            http.get("http://127.0.0.1/", resolve);
          }),
      ),
    ).rejects.toThrow("network socket");
  });
  it("runs context and JSON/debug/crash paths without network", async () => {
    const root = await mkdtemp(join(tmpdir(), "fuzit-network-"));
    await writeFile(join(root, "auth.ts"), "authentication\n");
    await withNetworkDenied(async () => {
      expect(
        await runCli(
          [
            "context",
            "--root",
            root,
            "--task",
            "authentication",
            "--profile",
            "bug-fix",
            "--budget-tokens",
            "100",
            "--format",
            "json",
            "--output",
            "-",
            "--no-index",
          ],
          { writeOut() {}, writeErr() {} },
          { repositoryRoot: root },
        ),
      ).toBe(0);
      for (const arguments_ of [
        ["--json", "profile", "list"],
        ["--debug", "unknown"],
      ] as const) {
        await runCli(
          arguments_,
          { writeOut() {}, writeErr() {} },
          { repositoryRoot: root },
        );
      }
    });
  });
});

import { spawnSync } from "node:child_process";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { runCli } from "../../../apps/cli/src/cli.js";
import { fuzitProfiles } from "../../../apps/mcp-server/src/tools/status.js";
import { renderPreview } from "../../../apps/vscode-extension/src/preview.js";
import { createTaskContext, runDoctor } from "@fuzit/core";
import { buildFilePackageGraph } from "@fuzit/graph";
import { PermissionBroker } from "@fuzit/plugin-host";
import { getProfile } from "@fuzit/profiles";
import type { NormalizedAnalysis } from "@fuzit/schemas";
import { withNetworkDenied } from "./harness.js";

describe("end-to-end zero-network proof (V1-119)", () => {
  let root: string;
  beforeAll(async () => {
    root = await mkdtemp(join(tmpdir(), "fuzit-zero-network-"));
    await writeFile(join(root, "index.ts"), "export const local = true;\n");
  });
  afterAll(async () => rm(root, { recursive: true, force: true }));

  it("observes CLI, daemon policy, MCP, extension, graph, context, and plugin boundaries", async () => {
    await withNetworkDenied(async () => {
      expect(
        await runCli(
          ["profile", "list"],
          { writeOut() {}, writeErr() {} },
          { repositoryRoot: root },
        ),
      ).toBe(0);

      const doctor = await runDoctor(root);
      expect(doctor.checks.find(({ id }) => id === "daemon")?.message).toBe(
        "No daemon is required for local CLI operation.",
      );
      expect(await fuzitProfiles({ allowedRoots: [root] })).toMatchObject({
        ok: true,
      });
      expect(renderPreview("local preview", { workspaceRoot: root })).toBe(
        "local preview",
      );

      const repositoryId = `sha256:${"a".repeat(64)}`;
      const analysis: NormalizedAnalysis = {
        schemaVersion: 1,
        repositoryId,
        analysisIdentity: "zero-network",
        files: [],
        modules: [],
        symbols: [],
        relationships: [],
        completeness: "complete",
        diagnostics: [],
      };
      expect(
        buildFilePackageGraph({ analysis, revision: "local", packages: [] })
          .nodes,
      ).toHaveLength(1);
      expect(
        createTaskContext({
          items: [],
          task: "local task",
          profile: getProfile("bug-fix"),
          budgetTokens: 100,
        }).selected,
      ).toEqual([]);
      expect(
        new PermissionBroker({ workspaceRoot: root }).authorize({
          kind: "network:connect",
          host: "example.com",
        }).allowed,
      ).toBe(false);
    });
  });

  it("runs the CLI packaging dry-run in a network-denied child process", async () => {
    const destination = await mkdtemp(join(tmpdir(), "fuzit-pack-network-"));
    try {
      const preload = pathToFileURL(
        resolve("tests/security/network/deny-network.mjs"),
      ).href;
      const result = spawnSync(
        process.execPath,
        [
          process.env.npm_execpath ?? "",
          "--dir",
          "apps/cli",
          "pack",
          "--pack-destination",
          destination,
        ],
        {
          cwd: resolve("."),
          encoding: "utf8",
          shell: false,
          env: {
            ...process.env,
            NODE_OPTIONS: `--import=${preload}`,
          },
        },
      );
      expect(result.status, result.stderr).toBe(0);
    } finally {
      await rm(destination, { recursive: true, force: true });
    }
  }, 30_000);
});

import { describe, it, expect } from "vitest";
