import { describe, it, expect } from "vitest";
import {
  assertTrusted,
  isTrustRefusal,
} from "../../apps/vscode-extension/src/trust.js";

const root = process.cwd();

describe("Workspace Trust Enforcement (V1-097)", () => {
  describe("assertTrusted", () => {
    it("allows trusted context with valid root", () => {
      const result = assertTrusted(
        { isTrusted: true, workspaceRoot: root },
        "scan",
      );
      expect(result.ok).toBe(true);
    });

    it("refuses untrusted context with actionable message", () => {
      const result = assertTrusted(
        { isTrusted: false, workspaceRoot: root },
        "scan repository",
      );
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.message).toContain("Workspace Trust is required");
        expect(result.message).toContain("scan repository");
        expect(result.message).toContain("Trust dialog");
      }
    });

    it("refuses when workspaceRoot is empty", () => {
      const result = assertTrusted(
        { isTrusted: true, workspaceRoot: "" },
        "watch",
      );
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.message).toContain("No workspace root");
      }
    });

    it("refuses when workspaceRoot is whitespace only", () => {
      const result = assertTrusted(
        { isTrusted: true, workspaceRoot: "   " },
        "watch",
      );
      expect(result.ok).toBe(false);
    });

    it("provides actionable label in refusal message", () => {
      const result = assertTrusted(
        { isTrusted: false, workspaceRoot: root },
        "run MCP server",
      );
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.message).toContain("run MCP server");
      }
    });
  });

  describe("isTrustRefusal", () => {
    it("returns true for a refusal result", () => {
      const result = assertTrusted(
        { isTrusted: false, workspaceRoot: root },
        "index workspace",
      );
      expect(isTrustRefusal(result)).toBe(true);
    });

    it("returns false for an allowed result", () => {
      const result = assertTrusted(
        { isTrusted: true, workspaceRoot: root },
        "index workspace",
      );
      expect(isTrustRefusal(result)).toBe(false);
    });
  });

  describe("trust transition scenarios (extension-host trust tests)", () => {
    it("allows a previously refused command once trust is granted", () => {
      const untrustedCtx = { isTrusted: false, workspaceRoot: root };
      const trustedCtx = { isTrusted: true, workspaceRoot: root };

      const before = assertTrusted(untrustedCtx, "run plugin");
      const after = assertTrusted(trustedCtx, "run plugin");

      expect(before.ok).toBe(false);
      expect(after.ok).toBe(true);
    });

    it("refuses every command on trust revocation", () => {
      const labels = ["scan", "watch", "index", "run plugin", "serve MCP"];
      for (const label of labels) {
        const result = assertTrusted(
          { isTrusted: false, workspaceRoot: root },
          label,
        );
        expect(result.ok).toBe(false);
        if (!result.ok) {
          expect(result.message.length).toBeGreaterThan(0);
        }
      }
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  WatchRegistry,
  startWatchCommand,
  stopWatchCommand,
} from "../../apps/vscode-extension/src/watch.js";

const root = process.cwd();

describe("Watch Controls (V1-095)", () => {
  describe("WatchRegistry", () => {
    it("starts idle state for unknown root", () => {
      const reg = new WatchRegistry();
      expect(reg.getState(root)).toBe("idle");
      expect(reg.isWatching(root)).toBe(false);
    });

    it("transitions to running state after start()", () => {
      const reg = new WatchRegistry();
      reg.start(root);
      expect(reg.isWatching(root)).toBe(true);
      expect(reg.getState(root)).toBe("running");
      reg.stop(root);
    });

    it("prevents duplicate watchers for same root", () => {
      const reg = new WatchRegistry();
      reg.start(root);
      expect(() => reg.start(root)).toThrow(/already running/);
      reg.stop(root);
    });

    it("transitions back to idle after stop()", () => {
      const reg = new WatchRegistry();
      reg.start(root);
      reg.stop(root);
      expect(reg.isWatching(root)).toBe(false);
      expect(reg.getState(root)).toBe("idle");
    });

    it("stopAll() cleans up all active watchers (deactivation cleanup)", () => {
      const reg = new WatchRegistry();
      const root2 = `${root}/a`;
      reg.start(root);
      reg.start(root2);
      expect(reg.isWatching(root)).toBe(true);
      expect(reg.isWatching(root2)).toBe(true);
      reg.stopAll();
      expect(reg.isWatching(root)).toBe(false);
      expect(reg.isWatching(root2)).toBe(false);
    });
  });

  describe("startWatchCommand", () => {
    it("rejects when workspace is untrusted", async () => {
      const reg = new WatchRegistry();
      const result = await startWatchCommand(reg, root, false);
      expect(result.ok).toBe(false);
      expect(result.message).toContain("Workspace Trust is required");
    });

    it("rejects when root is empty", async () => {
      const reg = new WatchRegistry();
      const result = await startWatchCommand(reg, "", true);
      expect(result.ok).toBe(false);
      expect(result.message).toContain("No workspace root selected");
    });

    it("succeeds for trusted workspace and valid root", async () => {
      const reg = new WatchRegistry();
      const result = await startWatchCommand(reg, root, true);
      expect(result.ok).toBe(true);
      expect(reg.isWatching(root)).toBe(true);
      reg.stop(root);
    });

    it("rejects starting a duplicate watcher", async () => {
      const reg = new WatchRegistry();
      await startWatchCommand(reg, root, true);
      const result = await startWatchCommand(reg, root, true);
      expect(result.ok).toBe(false);
      expect(result.message).toContain("already active");
      reg.stop(root);
    });
  });

  describe("stopWatchCommand", () => {
    it("returns error when no active watcher exists", () => {
      const reg = new WatchRegistry();
      const result = stopWatchCommand(reg, root);
      expect(result.ok).toBe(false);
      expect(result.message).toContain("No active watcher");
    });

    it("stops an active watcher cleanly", async () => {
      const reg = new WatchRegistry();
      await startWatchCommand(reg, root, true);
      const result = stopWatchCommand(reg, root);
      expect(result.ok).toBe(true);
      expect(reg.isWatching(root)).toBe(false);
    });
  });
});

import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { NativeFilesystemAdapter } from "@fuzit/watcher";
import type { WatcherEvent } from "@fuzit/schemas";

const REPO_ROOT = resolve("tests/watcher/tmp-repo");

describe("filesystem event adapter", () => {
  it("normalizes relative and absolute paths within root", async () => {
    const events: WatcherEvent[] = [];
    const adapter = new NativeFilesystemAdapter({
      repositoryRoot: REPO_ROOT,
      onEvent: (e) => events.push(e),
    });
    await adapter.start();

    const ev1 = adapter.emitSyntheticEvent("add", "src/a.ts");
    expect(ev1.path).toBe("src/a.ts");

    const absolutePath = join(REPO_ROOT, "src", "b.ts");
    const ev2 = adapter.emitSyntheticEvent("modify", absolutePath);
    expect(ev2.path).toBe("src/b.ts");

    expect(events.length).toBe(2);
    await adapter.stop();
  });

  it("rejects path escape outside repository root", async () => {
    const adapter = new NativeFilesystemAdapter({
      repositoryRoot: REPO_ROOT,
    });
    await adapter.start();

    expect(() => adapter.emitSyntheticEvent("modify", "../outside.ts")).toThrow(
      "path traversal",
    );
    const absoluteOutsidePath = resolve(REPO_ROOT, "..", "outside.ts");
    expect(() =>
      adapter.emitSyntheticEvent("modify", absoluteOutsidePath),
    ).toThrow("Path escape detected");
    await adapter.stop();
  });

  it("filters ignored paths", async () => {
    const adapter = new NativeFilesystemAdapter({
      repositoryRoot: REPO_ROOT,
      ignorePatterns: ["node_modules", ".git"],
    });
    await adapter.start();

    expect(() =>
      adapter.emitSyntheticEvent("modify", "node_modules/pkg/index.js"),
    ).toThrow("Ignored path change rejected");
    await adapter.stop();
  });
});

