import type { WatcherEvent } from "@fuzit/schemas";

const TEST_REPO = resolve("tests/watcher/tmp-verifier-repo");

describe("event filesystem verification", () => {
  it("verifies modify event on real existing file as upsert with valid contentHash", async () => {
    await rm(TEST_REPO, { recursive: true, force: true });
    await mkdir(join(TEST_REPO, "src"), { recursive: true });
    await writeFile(join(TEST_REPO, "src/hello.ts"), "console.log('hello');");

    const event: WatcherEvent = {
      contractVersion: 1,
      kind: "modify",
      path: "src/hello.ts",
      timestampMs: Date.now(),
    };

    const outcome = await verifyEventAgainstFilesystem(event, {
      repositoryRoot: TEST_REPO,
    });
    expect(outcome.action).toBe("upsert");
    if (outcome.action === "upsert") {
      expect(outcome.contentHash).toMatch(/^sha256:[a-f0-9]{64}$/);
      expect(outcome.sizeBytes).toBeGreaterThan(0);
    }
    await rm(TEST_REPO, { recursive: true, force: true });
  });

  it("treats modify event on deleted file as delete outcome", async () => {
    await rm(TEST_REPO, { recursive: true, force: true });
    await mkdir(TEST_REPO, { recursive: true });

    const event: WatcherEvent = {
      contractVersion: 1,
      kind: "modify",
      path: "src/deleted.ts",
      timestampMs: Date.now(),
    };

    const outcome = await verifyEventAgainstFilesystem(event, {
      repositoryRoot: TEST_REPO,
    });
    expect(outcome.action).toBe("delete");
    await rm(TEST_REPO, { recursive: true, force: true });
  });

  it("ignores event matching ignore pattern", async () => {
    const event: WatcherEvent = {
      contractVersion: 1,
      kind: "add",
      path: "node_modules/dep/index.js",
      timestampMs: Date.now(),
    };

    const outcome = await verifyEventAgainstFilesystem(event, {
      repositoryRoot: TEST_REPO,
      ignorePatterns: ["node_modules"],
    });
    expect(outcome.action).toBe("ignore");
  });
});

{
  "extends": "../../tsconfig.base.json",
  "files": ["./empty.ts"]
}

import { spawnSync } from "node:child_process";

const pnpmPath = process.env.npm_execpath;
if (!pnpmPath) throw new Error("pnpm must invoke local verification");

const suites = {
  checkpoint: [
    "build",
    "format:check",
    "lint",
    "typecheck",
    "test",
    "verify:goldens",
  ],
  phase: [
    "build",
    "format:check",
    "lint",
    "typecheck",
    "test",
    "verify:goldens",
    "test:incremental",
    "test:watcher",
    "test:analysis",
    "test:intelligence",
    "test:retrieval",
    "test:graph",
    "test:mcp",
    "test:security",
    "audit:secrets",
    "audit:privacy",
    "package:smoke",
  ],
  release: ["verify:phase", "acceptance:v1", "release:check"],
  all: ["verify:release", "benchmark:index", "benchmark:v1"],
};

const suite = process.argv[2];
if (!(suite in suites)) throw new Error(`unknown verification suite: ${suite}`);

for (const script of suites[suite]) {
  const result = spawnSync(process.execPath, [pnpmPath, "run", script], {
    stdio: "inherit",
  });
  if (result.status !== 0) process.exit(result.status ?? 1);
}

const diff = spawnSync("git", ["diff", "--check"], { stdio: "inherit" });
if (diff.status !== 0) process.exit(diff.status ?? 1);

import { spawnSync } from "node:child_process";

const packageTestDirectories = new Map([
  ["resource-limits", "tests/resource-limits"],
  ["@fuzit/benchmark", "packages/benchmark/test"],
  ["@fuzit/analysis", "packages/analysis/test"],
  ["@fuzit/selection", "packages/selection/test"],
  ["@fuzit/profiles", "packages/profiles/test"],
  ["@fuzit/git", "packages/git/test"],
  ["@fuzit/index", "packages/index/test"],
  ["@fuzit/budgeting", "packages/budgeting/test"],
  ["@fuzit/config", "packages/config/test"],
  ["@fuzit/core", "packages/core/test"],
  ["@fuzit/discovery", "packages/discovery/test"],
  ["@fuzit/schemas", "packages/schemas/test"],
  ["@fuzit/scanner", "packages/scanner/test"],
  ["@fuzit/renderer-markdown", "packages/renderers/markdown/test"],
  ["@fuzit/renderer-core", "packages/renderers/core/test"],
  ["@fuzit/renderer-json", "packages/renderers/json/test"],
  ["@fuzit/renderer-text", "packages/renderers/text/test"],
  ["@fuzit/renderer-xml", "packages/renderers/xml/test"],
  ["@fuzit/security", "packages/security/test"],
  ["@fuzit/snapshots", "packages/snapshots/test"],
]);

const filters = [];
const argumentsAfterSeparator = process.argv.slice(2);

for (let index = 0; index < argumentsAfterSeparator.length; index += 1) {
  const argument = argumentsAfterSeparator[index];

  if (argument !== "--filter") {
    throw new Error(`unsupported test argument: ${argument}`);
  }

  const packageName = argumentsAfterSeparator[index + 1];
  if (!packageName || !packageTestDirectories.has(packageName)) {
    throw new Error(`unsupported test filter: ${packageName ?? ""}`);
  }

  filters.push(packageTestDirectories.get(packageName));
  index += 1;
}

const pnpmPath = process.env.npm_execpath;
if (!pnpmPath) {
  throw new Error("pnpm must invoke the test wrapper");
}

const testPaths = [...new Set(filters)];
const result = spawnSync(
  process.execPath,
  [
    pnpmPath,
    "exec",
    "vitest",
    "run",
    "--config",
    "vitest.workspace.ts",
    ...testPaths,
  ],
  { stdio: "inherit" },
);

process.exit(result.status ?? 1);

import { spawnSync } from "node:child_process";

const pnpmPath = process.env.npm_execpath;

if (!pnpmPath) {
  throw new Error("pnpm must invoke the Turborepo wrapper");
}

const result = spawnSync(
  process.execPath,
  [pnpmPath, "exec", "turbo", ...process.argv.slice(2)],
  {
    env: {
      ...process.env,
      TURBO_TELEMETRY_DISABLED: "1",
    },
    stdio: "inherit",
  },
);

process.exit(result.status ?? 1);

import { describe, expect, it } from "vitest";

describe("quality tooling", () => {
  it("executes the baseline test workspace", () => {
    expect(true).toBe(true);
  });
});

